# Derive and audit doses in grams per day ----

# Build and audit arm-level absolute doses before fitting models. The primary
# families below distinguish total dietary protein from the dose prescribed as
# a supplement.
absolute_exposure_input_columns <- function() {
  c(
    "study_no",
    "arm_no",
    "intervention_i_e_protein_supplement_or_comparator_i_e_placebo_or_control",
    "absolute_protein_dose_g_day_note_if_placebo_condition_then_check_whether_it_includes_any_protein",
    "mean_body_mass_kg",
    "se_body_mass_kg",
    "sd_body_mass_kg",
    "sample_size_at_baseline",
    "baseline_dietary_protein_intake_g_day",
    "baseline_dietary_protein_intake_g_day_se",
    "baseline_dietary_protein_intake_g_day_sd",
    "baseline_dietary_protein_intake_g_kg_day",
    "baseline_dietary_protein_intake_g_kg_day_se",
    "baseline_dietary_protein_intake_g_kg_day_sd",
    "intervention_dietary_protein_intake_g_day",
    "intervention_dietary_protein_intake_g_day_se",
    "intervention_dietary_protein_intake_g_day_sd",
    "intervention_dietary_protein_intake_g_kg_day",
    "intervention_dietary_protein_intake_g_kg_day_se",
    "intervention_dietary_protein_intake_g_kg_day_sd"
  )
}

# Use a reported standard error when available. Otherwise recover it from the
# standard deviation and sample size where both are usable.
recover_arm_mean_se <- function(se, sd, n) {
  recovered <- dplyr::if_else(
    is.finite(sd) & sd > 0 & is.finite(n) & n > 0,
    sd / sqrt(n),
    NA_real_
  )
  dplyr::if_else(
    is.finite(se) & se > 0,
    as.numeric(se),
    recovered
  )
}

derive_product_se <- function(x, x_se, y, y_se) {
  dplyr::if_else(
    is.finite(x) & x > 0 & is.finite(x_se) & x_se > 0 &
      is.finite(y) & y > 0 & is.finite(y_se) & y_se > 0,
    sqrt((y * x_se)^2 + (x * y_se)^2),
    NA_real_
  )
}

# Return one row per study arm with reported and derived exposure values,
# uncertainty, and source labels for later eligibility and provenance checks.
make_update_2026_absolute_arm_exposures <- function(combined_workbook) {
  if (
    !is.list(combined_workbook) ||
      !"arm_characteristics" %in% names(combined_workbook)
  ) {
    stop("The combined workbook must contain arm characteristics.",
         call. = FALSE)
  }

  arms <- combined_workbook$arm_characteristics
  required <- absolute_exposure_input_columns()
  missing <- setdiff(required, names(arms))
  if (length(missing) > 0L) {
    stop(
      "Absolute-exposure inputs are missing columns: ",
      paste(missing, collapse = ", "), ".",
      call. = FALSE
    )
  }

  duplicate_keys <- arms |>
    dplyr::count(study_no, arm_no) |>
    dplyr::filter(n != 1L)
  if (nrow(duplicate_keys) > 0L) {
    stop("The combined workbook contains duplicate study-arm keys.",
         call. = FALSE)
  }

  dose_column <-
    "absolute_protein_dose_g_day_note_if_placebo_condition_then_check_whether_it_includes_any_protein"
  condition_column <-
    "intervention_i_e_protein_supplement_or_comparator_i_e_placebo_or_control"

  arms |>
    dplyr::select(dplyr::all_of(required)) |>
    dplyr::mutate(

      # Recover reported standard errors before propagating uncertainty in the
      # conversions from g/kg/day to g/day.
      exposure_condition = tolower(trimws(.data[[condition_column]])),
      body_mass_se = recover_arm_mean_se(
        se_body_mass_kg,
        sd_body_mass_kg,
        sample_size_at_baseline
      ),
      baseline_g_kg_day_se = recover_arm_mean_se(
        baseline_dietary_protein_intake_g_kg_day_se,
        baseline_dietary_protein_intake_g_kg_day_sd,
        sample_size_at_baseline
      ),
      intervention_g_kg_day_se = recover_arm_mean_se(
        intervention_dietary_protein_intake_g_kg_day_se,
        intervention_dietary_protein_intake_g_kg_day_sd,
        sample_size_at_baseline
      ),
      baseline_g_day_reported_se = recover_arm_mean_se(
        baseline_dietary_protein_intake_g_day_se,
        baseline_dietary_protein_intake_g_day_sd,
        sample_size_at_baseline
      ),
      total_g_day_reported_se = recover_arm_mean_se(
        intervention_dietary_protein_intake_g_day_se,
        intervention_dietary_protein_intake_g_day_sd,
        sample_size_at_baseline
      ),
      baseline_g_day_derived = dplyr::if_else(
        is.finite(baseline_dietary_protein_intake_g_kg_day) &
          baseline_dietary_protein_intake_g_kg_day > 0 &
          is.finite(mean_body_mass_kg) & mean_body_mass_kg > 0,
        baseline_dietary_protein_intake_g_kg_day * mean_body_mass_kg,
        NA_real_
      ),
      baseline_g_day_derived_se = derive_product_se(
        baseline_dietary_protein_intake_g_kg_day,
        baseline_g_kg_day_se,
        mean_body_mass_kg,
        body_mass_se
      ),
      total_g_day_derived = dplyr::if_else(
        is.finite(intervention_dietary_protein_intake_g_kg_day) &
          intervention_dietary_protein_intake_g_kg_day > 0 &
          is.finite(mean_body_mass_kg) & mean_body_mass_kg > 0,
        intervention_dietary_protein_intake_g_kg_day * mean_body_mass_kg,
        NA_real_
      ),
      total_g_day_derived_se = derive_product_se(
        intervention_dietary_protein_intake_g_kg_day,
        intervention_g_kg_day_se,
        mean_body_mass_kg,
        body_mass_se
      ),

      # Prefer directly reported absolute exposure. Record the source so
      # converted exposures can be distinguished in the audit.
      baseline_g_day = dplyr::case_when(
        is.finite(baseline_dietary_protein_intake_g_day) &
          baseline_dietary_protein_intake_g_day > 0 ~
          baseline_dietary_protein_intake_g_day,
        is.finite(baseline_g_day_derived) ~ baseline_g_day_derived,
        TRUE ~ NA_real_
      ),
      baseline_g_day_source = dplyr::case_when(
        is.finite(baseline_dietary_protein_intake_g_day) &
          baseline_dietary_protein_intake_g_day > 0 ~ "reported",
        is.finite(baseline_g_day_derived) ~ "derived_from_g_kg_and_body_mass",
        TRUE ~ "missing"
      ),
      baseline_g_day_se = dplyr::case_when(
        baseline_g_day_source == "reported" ~ baseline_g_day_reported_se,
        baseline_g_day_source == "derived_from_g_kg_and_body_mass" ~
          baseline_g_day_derived_se,
        TRUE ~ NA_real_
      ),
      baseline_g_day_se_source = dplyr::case_when(
        baseline_g_day_source == "reported" &
          is.finite(baseline_g_day_reported_se) ~
          "reported_or_sd_recovered",
        baseline_g_day_source == "derived_from_g_kg_and_body_mass" &
          is.finite(baseline_g_day_derived_se) ~
          "delta_method_g_kg_and_body_mass",
        baseline_g_day_source != "missing" ~ "unavailable",
        TRUE ~ "not_applicable"
      ),
      total_g_day = dplyr::case_when(
        is.finite(intervention_dietary_protein_intake_g_day) &
          intervention_dietary_protein_intake_g_day > 0 ~
          intervention_dietary_protein_intake_g_day,
        is.finite(total_g_day_derived) ~ total_g_day_derived,
        TRUE ~ NA_real_
      ),
      total_g_day_source = dplyr::case_when(
        is.finite(intervention_dietary_protein_intake_g_day) &
          intervention_dietary_protein_intake_g_day > 0 ~ "reported",
        is.finite(total_g_day_derived) ~
          "derived_from_g_kg_and_body_mass",
        TRUE ~ "missing"
      ),
      total_g_day_se = dplyr::case_when(
        total_g_day_source == "reported" ~ total_g_day_reported_se,
        total_g_day_source == "derived_from_g_kg_and_body_mass" ~
          total_g_day_derived_se,
        TRUE ~ NA_real_
      ),
      total_g_day_se_source = dplyr::case_when(
        total_g_day_source == "reported" &
          is.finite(total_g_day_reported_se) ~
          "reported_or_sd_recovered",
        total_g_day_source == "derived_from_g_kg_and_body_mass" &
          is.finite(total_g_day_derived_se) ~
          "delta_method_g_kg_and_body_mass",
        total_g_day_source != "missing" ~ "unavailable",
        TRUE ~ "not_applicable"
      ),
      supplement_g_day_reported = as.numeric(.data[[dose_column]]),
      supplement_g_day = dplyr::case_when(
        is.finite(supplement_g_day_reported) &
          supplement_g_day_reported >= 0 ~ supplement_g_day_reported,
        !is.finite(supplement_g_day_reported) &
          exposure_condition %in% c("control", "placebo") ~ 0,
        TRUE ~ NA_real_
      ),
      supplement_g_day_source = dplyr::case_when(
        is.finite(supplement_g_day_reported) &
          supplement_g_day_reported >= 0 &
          exposure_condition == "protein" ~ "reported_protein_arm",
        is.finite(supplement_g_day_reported) &
          supplement_g_day_reported >= 0 ~ "reported_comparator_product",
        !is.finite(supplement_g_day_reported) &
          exposure_condition %in% c("control", "placebo") ~
          "structural_zero_control_or_placebo",
        exposure_condition == "protein" ~ "missing_protein_arm",
        TRUE ~ "missing_unclassified_arm"
      ),
      assignment_total_g_day = dplyr::if_else(
        is.finite(baseline_g_day) & is.finite(supplement_g_day),
        baseline_g_day + supplement_g_day,
        NA_real_
      )
    ) |>
    dplyr::rename(arm_no_extracted = arm_no) |>
    dplyr::select(
      study_no,
      arm_no_extracted,
      exposure_condition,
      sample_size_at_baseline,
      mean_body_mass_kg,
      body_mass_se,
      baseline_dietary_protein_intake_g_kg_day,
      baseline_g_kg_day_se,
      baseline_dietary_protein_intake_g_day,
      baseline_g_day_reported_se,
      baseline_g_day_derived,
      baseline_g_day_derived_se,
      baseline_g_day,
      baseline_g_day_se,
      baseline_g_day_source,
      baseline_g_day_se_source,
      intervention_dietary_protein_intake_g_kg_day,
      intervention_g_kg_day_se,
      intervention_dietary_protein_intake_g_day,
      total_g_day_reported_se,
      total_g_day_derived,
      total_g_day_derived_se,
      total_g_day,
      total_g_day_se,
      total_g_day_source,
      total_g_day_se_source,
      supplement_g_day_reported,
      supplement_g_day,
      supplement_g_day_source,
      assignment_total_g_day
    )
}

make_absolute_exposure_model_registry <- function(primary_specifications) {
  registry <- primary_specifications |>
    purrr::map_dfr(
      ~ tibble::tibble(
        model_index = as.integer(.x$model_index),
        model_name = as.character(.x$model_name)
      )
    ) |>
    dplyr::distinct(model_index, model_name) |>
    dplyr::arrange(model_index)

  duplicate_names <- registry |>
    dplyr::count(model_index) |>
    dplyr::filter(n != 1L)
  if (
    nrow(registry) != 26L || nrow(duplicate_names) > 0L ||
      !identical(registry$model_index, seq_len(26L))
  ) {
    stop("The primary model registry does not contain 26 unique indices.",
         call. = FALSE)
  }

  omitted <- c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  registry |>
    dplyr::mutate(
      retained = !model_index %in% omitted,
      decision = dplyr::if_else(
        retained,
        "retain with exposure-specific scaling",
        "omit fixed 1.6 g/kg/day linear-spline form"
      )
    )
}

make_absolute_exposure_family_plan <- function() {
  families <- tibble::tribble(
    ~family, ~engine, ~total_applicable, ~supplement_applicable,
    "primary", "brms", TRUE, TRUE,
    "mundlak", "brms", TRUE, TRUE,
    "within", "brms", TRUE, TRUE,
    "achieved_common_sample", "brms", TRUE, FALSE,
    "assignment_derived", "brms", TRUE, FALSE,
    "eiv", "direct_stan", TRUE, FALSE,
    "rescor", "direct_stan", TRUE, TRUE,
    "strategy", "brms", TRUE, TRUE,
    "strategy_within", "brms", TRUE, TRUE
  )

  tidyr::expand_grid(
    exposure = c("total_g_day", "supplement_g_day"),
    family = families$family
  ) |>
    dplyr::left_join(families, by = "family") |>
    dplyr::mutate(
      applicable = dplyr::if_else(
        exposure == "total_g_day",
        total_applicable,
        supplement_applicable
      ),
      rationale = dplyr::case_when(
        applicable ~ "included",
        family == "achieved_common_sample" ~
          "no systematically measured achieved supplement dose",
        family == "assignment_derived" ~
          "prescribed supplement dose is already the assignment exposure",
        family == "eiv" ~
          "prescribed dose has no dietary measurement-error input",
        TRUE ~ "not applicable"
      ),
      retained_models_per_outcome = dplyr::if_else(applicable, 18L, 0L),
      outcomes = dplyr::if_else(applicable, 4L, 0L),
      planned_initial_fits = retained_models_per_outcome * outcomes
    ) |>
    dplyr::select(
      exposure,
      family,
      applicable,
      engine,
      rationale,
      retained_models_per_outcome,
      outcomes,
      planned_initial_fits
    )
}

summarise_absolute_exposure_coverage <- function(data) {
  exposure_rows <- dplyr::bind_rows(
    data |>
      dplyr::transmute(
        outcome,
        study_no,
        arm_no,
        exposure = "current_g_kg_day",
        eligible = base_eligible & is.finite(protein_intake_raw)
      ),
    data |>
      dplyr::transmute(
        outcome,
        study_no,
        arm_no,
        exposure = "total_g_day_reported_only",
        eligible = base_eligible &
          is.finite(intervention_dietary_protein_intake_g_day) &
          intervention_dietary_protein_intake_g_day > 0
      ),
    data |>
      dplyr::transmute(
        outcome,
        study_no,
        arm_no,
        exposure = "total_g_day_reported_or_derived",
        eligible = total_g_day_eligible
      ),
    data |>
      dplyr::transmute(
        outcome,
        study_no,
        arm_no,
        exposure = "total_g_day_eiv_input",
        eligible = total_g_day_eligible &
          is.finite(total_g_day_se) & total_g_day_se > 0
      ),
    data |>
      dplyr::transmute(
        outcome,
        study_no,
        arm_no,
        exposure = "assignment_total_g_day",
        eligible = base_eligible & is.finite(assignment_total_g_day)
      ),
    data |>
      dplyr::transmute(
        outcome,
        study_no,
        arm_no,
        exposure = "supplement_g_day_row_complete",
        eligible = supplement_g_day_row_complete
      ),
    data |>
      dplyr::transmute(
        outcome,
        study_no,
        arm_no,
        exposure = "supplement_g_day_positive_study",
        eligible = supplement_g_day_eligible
      )
  )

  exposure_rows |>
    dplyr::filter(eligible) |>
    dplyr::group_by(exposure, outcome) |>
    dplyr::summarise(
      contrasts = dplyr::n(),
      studies = dplyr::n_distinct(study_no),
      arms = dplyr::n_distinct(arm_no),
      .groups = "drop"
    ) |>
    dplyr::arrange(exposure, outcome)
}

make_update_2026_absolute_exposure_audit <- function(
    reviewed_data,
    combined_workbook,
    primary_specifications
) {
  required_reviewed <- c(
    "study_no", "arm_no_extracted", "arm_no", "outcome_group",
    "protein_intake_raw", "include_quantitative",
    "analysis_exclusion_count", "exclusion_missing_protein_intake"
  )
  missing <- setdiff(required_reviewed, names(reviewed_data))

  if (length(missing) > 0L) {
    stop(
      "Reviewed data are missing absolute-exposure audit columns: ",
      paste(missing, collapse = ", "), ".",
      call. = FALSE
    )
  }

  arms <- make_update_2026_absolute_arm_exposures(combined_workbook)
  registry <- make_absolute_exposure_model_registry(primary_specifications)
  family_plan <- make_absolute_exposure_family_plan()

  outcome_lookup <- tibble::enframe(
    update_2026_outcome_names(),
    name = "outcome",
    value = "outcome_group"
  )
  data <- reviewed_data |>
    dplyr::left_join(
      arms |> dplyr::mutate(exposure_arm_present = TRUE),
      by = c("study_no", "arm_no_extracted")
    ) |>
    dplyr::left_join(outcome_lookup, by = "outcome_group") |>
    dplyr::mutate(
      non_exposure_exclusion_count =
        analysis_exclusion_count -
        as.integer(exclusion_missing_protein_intake),
      base_eligible =
        non_exposure_exclusion_count == 0L & include_quantitative,
      total_g_day_eligible = base_eligible & is.finite(total_g_day),
      supplement_g_day_row_complete =
        base_eligible & is.finite(supplement_g_day)
    ) |>
    dplyr::group_by(outcome, study_no) |>
    dplyr::mutate(
      supplement_positive_protein_arm = any(
        supplement_g_day_row_complete &
          exposure_condition == "protein" & supplement_g_day > 0,
        na.rm = TRUE
      ),
      supplement_g_day_eligible =
        supplement_g_day_row_complete & supplement_positive_protein_arm
    ) |>
    dplyr::ungroup()

  agreement <- arms |>
    dplyr::filter(
      is.finite(intervention_dietary_protein_intake_g_day),
      intervention_dietary_protein_intake_g_day > 0,
      is.finite(total_g_day_derived),
      total_g_day_derived > 0
    ) |>
    dplyr::mutate(
      absolute_difference_g_day = abs(
        intervention_dietary_protein_intake_g_day - total_g_day_derived
      ),
      percentage_difference = 100 * absolute_difference_g_day /
        intervention_dietary_protein_intake_g_day
    )

  agreement_summary <- agreement |>
    dplyr::summarise(
      arms_with_both = dplyr::n(),
      median_absolute_difference_g_day =
        stats::median(absolute_difference_g_day),
      median_percentage_difference = stats::median(percentage_difference),
      p95_absolute_difference_g_day = stats::quantile(
        absolute_difference_g_day,
        probs = 0.95,
        names = FALSE,
        type = 7
      )
    )

  supplement_support <- data |>
    dplyr::filter(base_eligible) |>
    dplyr::group_by(outcome, study_no) |>
    dplyr::summarise(
      eligible_rows = dplyr::n(),
      row_complete_arms = dplyr::n_distinct(
        arm_no[is.finite(supplement_g_day)]
      ),
      positive_protein_arms = dplyr::n_distinct(
        arm_no[
          exposure_condition == "protein" &
            is.finite(supplement_g_day) & supplement_g_day > 0
        ]
      ),
      eligible_for_supplement_family = positive_protein_arms > 0L,
      .groups = "drop"
    )

  coverage <- summarise_absolute_exposure_coverage(data)
  provenance_summary <- dplyr::bind_rows(
    arms |>
      dplyr::count(source = total_g_day_source, name = "arms") |>
      dplyr::mutate(variable = "total_g_day"),
    arms |>
      dplyr::count(source = baseline_g_day_source, name = "arms") |>
      dplyr::mutate(variable = "baseline_g_day"),
    arms |>
      dplyr::count(source = supplement_g_day_source, name = "arms") |>
      dplyr::mutate(variable = "supplement_g_day"),
    arms |>
      dplyr::count(source = total_g_day_se_source, name = "arms") |>
      dplyr::mutate(variable = "total_g_day_uncertainty"),
    arms |>
      dplyr::count(source = baseline_g_day_se_source, name = "arms") |>
      dplyr::mutate(variable = "baseline_g_day_uncertainty")
  ) |>
    dplyr::select(variable, source, arms) |>
    dplyr::arrange(variable, source)

  support_by_outcome <- dplyr::bind_rows(
    data |>
      dplyr::filter(total_g_day_eligible) |>
      dplyr::transmute(
        outcome,
        study_no,
        arm_no,
        exposure = "total_g_day",
        value = total_g_day
      ),
    data |>
      dplyr::filter(supplement_g_day_eligible) |>
      dplyr::transmute(
        outcome,
        study_no,
        arm_no,
        exposure = "supplement_g_day",
        value = supplement_g_day
      )
  ) |>
    dplyr::group_by(exposure, outcome) |>
    dplyr::summarise(
      contrasts = dplyr::n(),
      studies = dplyr::n_distinct(study_no),
      arms = dplyr::n_distinct(arm_no),
      unique_values = dplyr::n_distinct(value),
      minimum = min(value),
      p05 = stats::quantile(value, 0.05, names = FALSE),
      median = stats::median(value),
      p95 = stats::quantile(value, 0.95, names = FALSE),
      maximum = max(value),
      .groups = "drop"
    )

  total_reference <- data |>
    dplyr::filter(
      total_g_day_eligible,
      exposure_condition %in% c("control", "placebo")
    ) |>
    dplyr::distinct(study_no, arm_no_extracted, total_g_day) |>
    dplyr::summarise(reference = stats::median(total_g_day)) |>
    dplyr::pull(reference)

  scaling_plan <- tibble::tibble(
    exposure = c("total_g_day", "supplement_g_day"),
    reference_g_day = c(total_reference, 0),
    internal_unit_g_day = c(50, 25),
    reference_basis = c(
      "median among eligible unique control/placebo arms",
      "zero prescribed supplement"
    ),
    include_standardised_body_mass_in_moderator_models = TRUE
  )

  family_totals <- family_plan |>
    dplyr::group_by(exposure) |>
    dplyr::summarise(
      applicable_families = sum(applicable),
      planned_initial_fits = sum(planned_initial_fits),
      .groups = "drop"
    )
  checks <- tibble::tibble(
    check = c(
      "all reviewed contrast rows match one source arm",
      "selected total-intake values are finite and positive",
      "reported and selected supplement doses are non-negative",
      "imputed zero supplement doses occur only in control/placebo arms",
      "missing protein-arm supplement doses remain missing",
      "reported nonzero comparator protein is retained",
      "the registry retains 18 and omits the eight fixed-knot models",
      "the total-intake programme contains nine 72-fit families",
      "the supplement programme contains six 72-fit families",
      "all four outcomes retain total-intake and supplement evidence",
      "both exposure scales have finite prespecified references and units"
    ),
    passed = c(
      all(data$exposure_arm_present %in% TRUE),
      all(
        !data$total_g_day_eligible |
          (is.finite(data$total_g_day) & data$total_g_day > 0)
      ),
      all(
        !is.finite(arms$supplement_g_day_reported) |
          arms$supplement_g_day_reported >= 0
      ) && all(
        !is.finite(data$supplement_g_day) | data$supplement_g_day >= 0
      ),
      all(
        arms$supplement_g_day_source !=
          "structural_zero_control_or_placebo" |
          arms$exposure_condition %in% c("control", "placebo")
      ),
      all(
        arms$supplement_g_day_source != "missing_protein_arm" |
          is.na(arms$supplement_g_day)
      ),
      all(
        arms$supplement_g_day_source != "reported_comparator_product" |
          (is.finite(arms$supplement_g_day) & arms$supplement_g_day > 0)
      ),
      sum(registry$retained) == 18L &&
        setequal(
          registry$model_index[!registry$retained],
          c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
        ),
      family_totals$applicable_families[
        family_totals$exposure == "total_g_day"
      ] == 9L && family_totals$planned_initial_fits[
        family_totals$exposure == "total_g_day"
      ] == 648L,
      family_totals$applicable_families[
        family_totals$exposure == "supplement_g_day"
      ] == 6L && family_totals$planned_initial_fits[
        family_totals$exposure == "supplement_g_day"
      ] == 432L,
      coverage |>
        dplyr::filter(
          exposure %in% c(
            "total_g_day_reported_or_derived",
            "supplement_g_day_positive_study"
          )
        ) |>
        dplyr::count(exposure) |>
        dplyr::pull(n) |>
        identical(c(4L, 4L)),
      nrow(scaling_plan) == 2L &&
        all(is.finite(scaling_plan$reference_g_day)) &&
        all(scaling_plan$internal_unit_g_day > 0) &&
        scaling_plan$reference_g_day[
          scaling_plan$exposure == "supplement_g_day"
        ] == 0
    )
  )

  if (any(!checks$passed)) {
    stop(
      "The shared absolute-exposure audit failed: ",
      paste(checks$check[!checks$passed], collapse = "; "),
      call. = FALSE
    )
  }

  list(
    checks = checks,
    arm_exposures = arms,
    outcome_coverage = coverage,
    exposure_provenance = provenance_summary,
    support_by_outcome = support_by_outcome,
    scaling_plan = scaling_plan,
    reported_derived_agreement = agreement_summary,
    supplement_study_outcome_support = supplement_support,
    model_registry = registry,
    family_plan = family_plan,
    family_totals = family_totals,
    total_data_by_outcome = purrr::imap(
      update_2026_outcome_names(),
      function(outcome_group_value, outcome_name) {
        output <- data |>
          dplyr::filter(
            outcome == outcome_name,
            total_g_day_eligible
          )
        if (identical(outcome_name, "function")) {
          output <- apply_function_direction(output)
        }
        add_primary_display_fields(output)
      }
    ),
    supplement_data_by_outcome = purrr::imap(
      update_2026_outcome_names(),
      function(outcome_group_value, outcome_name) {
        output <- data |>
          dplyr::filter(
            outcome == outcome_name,
            supplement_g_day_eligible
          )
        if (identical(outcome_name, "function")) {
          output <- apply_function_direction(output)
        }
        add_primary_display_fields(output)
      }
    ),
    ready_for_review = TRUE,
    next_step = paste(
      "Review and confirm the shared exposure, coverage, model-registry,",
      "and family-plan files before the total-g/day primary family is built."
    )
  )
}

write_update_2026_absolute_exposure_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "audit"
    )
) {
  if (!isTRUE(audit$ready_for_review) || any(!audit$checks$passed)) {
    stop("The shared absolute-exposure audit is not ready to write.",
         call. = FALSE)
  }
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    checks = file.path(output_dir, "checks.csv"),
    arms = file.path(output_dir, "arm_exposures.csv"),
    coverage = file.path(output_dir, "outcome_coverage.csv"),
    agreement = file.path(output_dir, "reported_derived_agreement.csv"),
    provenance = file.path(output_dir, "exposure_provenance.csv"),
    support = file.path(output_dir, "support_by_outcome.csv"),
    scaling = file.path(output_dir, "scaling_plan.csv"),
    supplement_support = file.path(
      output_dir,
      "supplement_study_outcome_support.csv"
    ),
    model_registry = file.path(output_dir, "model_registry.csv"),
    family_plan = file.path(output_dir, "family_plan.csv"),
    family_totals = file.path(output_dir, "family_totals.csv")
  )

  readr::write_csv(audit$checks, paths[["checks"]], na = "")
  readr::write_csv(audit$arm_exposures, paths[["arms"]], na = "")
  readr::write_csv(audit$outcome_coverage, paths[["coverage"]], na = "")
  readr::write_csv(
    audit$reported_derived_agreement,
    paths[["agreement"]],
    na = ""
  )
  readr::write_csv(
    audit$exposure_provenance,
    paths[["provenance"]],
    na = ""
  )
  readr::write_csv(audit$support_by_outcome, paths[["support"]], na = "")
  readr::write_csv(audit$scaling_plan, paths[["scaling"]], na = "")
  readr::write_csv(
    audit$supplement_study_outcome_support,
    paths[["supplement_support"]],
    na = ""
  )
  readr::write_csv(audit$model_registry, paths[["model_registry"]], na = "")
  readr::write_csv(audit$family_plan, paths[["family_plan"]], na = "")
  readr::write_csv(audit$family_totals, paths[["family_totals"]], na = "")
  unname(paths)
}

# Primary models on total dietary intake ----

# Use the audited total-intake reference and unit to prepare outcomes on a
# common internal scale. Candidate comparisons later align the fits on the
# same complete observations.
make_update_2026_total_primary_data_by_outcome <- function(audit) {
  if (
    !isTRUE(audit$ready_for_review) ||
      any(!audit$checks$passed) ||
      !"total_g_day" %in% audit$scaling_plan$exposure
  ) {
    stop("The absolute-exposure audit is not ready for modelling.",
         call. = FALSE)
  }

  scaling <- audit$scaling_plan |>
    dplyr::filter(exposure == "total_g_day")
  if (
    nrow(scaling) != 1L ||
      !is.finite(scaling$reference_g_day) ||
      !is.finite(scaling$internal_unit_g_day) ||
      scaling$internal_unit_g_day <= 0
  ) {
    stop("The total-intake scale is invalid.", call. = FALSE)
  }

  purrr::map(
    audit$total_data_by_outcome,
    function(data) {
      if (!"mean_body_mass_kg" %in% names(data)) {
        body_mass_columns <- c(
          "mean_body_mass_kg.y",
          "mean_body_mass_kg.x"
        )
        if (!all(body_mass_columns %in% names(data))) {
          stop("The total-intake data do not contain body mass.",
               call. = FALSE)
        }
        both_reported <- is.finite(data$mean_body_mass_kg.y) &
          is.finite(data$mean_body_mass_kg.x)
        if (
          any(
            both_reported &
              abs(
                data$mean_body_mass_kg.y - data$mean_body_mass_kg.x
              ) > 1e-8
          )
        ) {
          stop("Joined body-mass values disagree.", call. = FALSE)
        }
        data <- data |>
          dplyr::mutate(
            mean_body_mass_kg = dplyr::coalesce(
              mean_body_mass_kg.y,
              mean_body_mass_kg.x
            )
          )
      }
      data |>
        dplyr::mutate(
          protein_intake_g_kg_day = protein_intake_raw,
          protein_intake_raw = total_g_day,
          protein_intake =
            (total_g_day - scaling$reference_g_day[[1L]]) /
              scaling$internal_unit_g_day[[1L]],
          absolute_exposure_reference_g_day =
            scaling$reference_g_day[[1L]],
          absolute_exposure_unit_g_day =
            scaling$internal_unit_g_day[[1L]]
        ) |>
        droplevels()
    }
  )
}

add_absolute_primary_body_mass <- function(data) {
  data <- data |>
    dplyr::filter(is.finite(mean_body_mass_kg)) |>
    droplevels()
  if (!nrow(data)) {
    stop("No finite body-mass observations remain.", call. = FALSE)
  }

  body_mass_centre <- mean(data$mean_body_mass_kg)
  body_mass_scale <- stats::sd(data$mean_body_mass_kg)
  if (
    !is.finite(body_mass_centre) ||
      !is.finite(body_mass_scale) ||
      body_mass_scale <= 0
  ) {
    stop("Body mass cannot be standardised for this outcome.",
         call. = FALSE)
  }

  data |>
    dplyr::mutate(
      body_mass_outcome_z =
        (mean_body_mass_kg - body_mass_centre) / body_mass_scale
    ) |>
    structure(
      body_mass_centre = body_mass_centre,
      body_mass_scale = body_mass_scale
    )
}

add_absolute_primary_body_mass_prior <- function(priors) {
  c(
    priors,
    brms::set_prior(
      "student_t(3, 0, 0.5)",
      class = "b",
      coef = "body_mass_outcome_z"
    )
  )
}

make_update_2026_total_primary_specifications <- function(
    primary_specifications,
    model_registry
) {
  retained <- model_registry |>
    dplyr::filter(retained) |>
    dplyr::pull(model_index)

  if (
    length(retained) != 18L ||
      !setequal(
        setdiff(seq_len(26L), retained),
        c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
      )
  ) {
    stop("The absolute-exposure model registry is invalid.",
         call. = FALSE)
  }

  specifications <- dplyr::bind_rows(primary_specifications) |>
    dplyr::filter(model_index %in% retained) |>
    dplyr::mutate(
      family = "total_primary",
      exposure = "total_g_day",
      formula = stringr::str_replace_all(
        formula,
        "\\bprotein_intake_05\\b",
        "protein_intake"
      ),
      formula = stringr::str_replace(
        formula,
        stringr::fixed("splines::ns(protein_intake, df = 3)"),
        "s(protein_intake, bs='tp', k=4)"
      ),
      includes_moderators = stringr::str_detect(model_name, "moderators"),
      standardised_moderators = includes_moderators,
      half_unit_protein = FALSE,
      natural_spline = FALSE,
      targeted_smooth_prior = stringr::str_detect(
        formula,
        "s\\(\\s*protein_intake\\s*,"
      ),
      smooth_prior_scale = dplyr::if_else(
        targeted_smooth_prior,
        0.5,
        NA_real_
      ),
      adapt_delta = dplyr::if_else(
        targeted_smooth_prior,
        pmax(as.numeric(adapt_delta), 0.999),
        as.numeric(adapt_delta)
      ),
      max_treedepth = dplyr::if_else(
        targeted_smooth_prior,
        pmax(as.integer(max_treedepth), 15L),
        as.integer(max_treedepth)
      ),
      sampling_schedule = dplyr::case_when(
        targeted_smooth_prior ~ "accepted_smooth_controls",
        dplyr::coalesce(second_remedy, FALSE) ~
          "accepted_second_remedy_controls",
        dplyr::coalesce(requires_refit, FALSE) ~
          "accepted_first_remedy_controls",
        TRUE ~ "base_controls"
      ),
      requires_refit = FALSE,
      second_remedy = FALSE,
      third_remedy = FALSE,
      formula = purrr::map2_chr(
        formula,
        includes_moderators,
        function(value, moderators) {
          if (!moderators) return(value)
          value <- replace_primary_standardised_moderators(value)
          updated <- stringr::str_replace(
            value,
            "\\(1\\s*\\|\\s*arm_no\\)",
            "body_mass_outcome_z + (1 | arm_no)"
          )
          if (identical(updated, value)) {
            stop("Could not add body mass to a moderator model.",
                 call. = FALSE)
          }
          updated
        }
      ),
      model_name = paste0(model_name, " [total g/day]"),
      chains = 4L,
      parallel_chains = 4L,
      iter_warmup = 2000L,
      iter_sampling = 6000L
    )

  outcome_counts <- specifications |>
    dplyr::count(outcome) |>
    tibble::deframe()
  if (
    nrow(specifications) != 72L ||
      !identical(
        outcome_counts[c(
          "whole_body", "hypertrophy", "strength", "function"
        )],
        c(
          whole_body = 18L,
          hypertrophy = 18L,
          strength = 18L,
          `function` = 18L
        )
      ) ||
      any(specifications$model_index %in%
            c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)) ||
      sum(specifications$includes_moderators) != 36L ||
      sum(specifications$targeted_smooth_prior) != 32L ||
      any(
        specifications$targeted_smooth_prior &
          (
            specifications$adapt_delta < 0.999 |
              specifications$max_treedepth < 15L
          )
      ) ||
      any(
        specifications$includes_moderators &
          !stringr::str_detect(
            specifications$formula,
            "\\bbody_mass_outcome_z\\b"
          )
      )
  ) {
    stop("The total-intake primary registry failed validation.",
         call. = FALSE)
  }

  output <- purrr::pmap(specifications, list)
  names(output) <- paste0(
    specifications$outcome,
    "_model_",
    stringr::str_pad(specifications$model_index, 2L, pad = "0")
  )
  output
}

prepare_update_2026_total_primary_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome
) {
  data <- data_by_outcome[[specification$outcome]]
  priors <- priors_by_outcome[[specification$outcome]]

  if (is.null(data) || !nrow(data) || is.null(priors)) {
    stop("Total-intake primary data or priors are missing.",
         call. = FALSE)
  }
  priors <- normalize_primary_brms_priors(priors)
  if (isTRUE(specification$regularised_variance_priors)) {
    priors <- add_regularised_variance_priors(priors)
  }

  if (isTRUE(specification$includes_moderators)) {
    data <- add_absolute_primary_body_mass(data)
    data <- add_primary_standardised_moderators(data)
    priors <- add_primary_standardised_moderator_priors(priors)
    priors <- add_absolute_primary_body_mass_prior(priors)
  }

  if (isTRUE(specification$targeted_smooth_prior)) {
    priors <- add_primary_targeted_smooth_prior(
      priors,
      scale = specification$smooth_prior_scale
    )
  }

  list(
    family = "total_primary",
    formula = specification$formula,
    priors = priors,
    data = data,
    specification = specification
  )
}

validate_update_2026_total_primary_inputs <- function(
    specifications,
    data_by_outcome,
    priors_by_outcome,
    audit
) {
  if (!isTRUE(audit$ready_for_review) || any(!audit$checks$passed)) {
    stop("The absolute-exposure audit has not passed.", call. = FALSE)
  }

  checks <- purrr::map_dfr(
    specifications,
    function(specification) {
      input <- prepare_update_2026_total_primary_input(
        specification,
        data_by_outcome,
        priors_by_outcome
      )
      brms::make_standata(
        formula = stats::as.formula(input$formula),
        data = input$data,
        prior = input$priors
      )
      tibble::tibble(
        family = input$family,
        outcome = specification$outcome,
        model_index = as.integer(specification$model_index),
        model_name = specification$model_name,
        includes_moderators = specification$includes_moderators,
        targeted_smooth_prior = specification$targeted_smooth_prior,
        sampling_schedule = specification$sampling_schedule,
        contrasts = nrow(input$data),
        studies = dplyr::n_distinct(input$data$study_no),
        arms = dplyr::n_distinct(input$data$arm_no),
        exposure_minimum_g_day = min(input$data$protein_intake_raw),
        exposure_maximum_g_day = max(input$data$protein_intake_raw),
        reference_g_day =
          unique(input$data$absolute_exposure_reference_g_day),
        internal_unit_g_day =
          unique(input$data$absolute_exposure_unit_g_day),
        adapt_delta = specification$adapt_delta,
        max_treedepth = as.integer(specification$max_treedepth),
        iter_warmup = specification$iter_warmup,
        iter_sampling = specification$iter_sampling,
        chains = specification$chains,
        parallel_chains = specification$parallel_chains,
        valid = TRUE
      )
    }
  )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  if (
    nrow(checks) != 72L ||
      anyDuplicated(keys) ||
      !all(checks$valid) ||
      any(checks$contrasts <= 0L) ||
      any(checks$studies < 2L) ||
      any(checks$exposure_minimum_g_day <= 0) ||
      any(checks$exposure_maximum_g_day <=
            checks$exposure_minimum_g_day) ||
      any(checks$reference_g_day !=
            audit$scaling_plan$reference_g_day[
              audit$scaling_plan$exposure == "total_g_day"
            ]) ||
      any(checks$internal_unit_g_day != 50)
  ) {
    stop("The total-intake primary input preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_primary_input_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure",
      "total_g_day", "primary", "input_preflight.csv"
    )
) {
  if (nrow(checks) != 72L || !all(checks$valid)) {
    stop("Cannot write an invalid total-intake primary preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

fit_update_2026_total_primary_candidate_to_file <- function(
    input,
    enabled,
    seed_offset = 46888L,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "total_g_day", "primary", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      "Total-intake primary fitting is disabled. Set ",
      "PROTEIN_UPDATE_2026_TOTAL_PRIMARY=fit to enable it.",
      call. = FALSE
    )
  }

  specification <- input$specification
  seed <- as.integer(seed_offset) +
    100L * match(
      specification$outcome,
      c("whole_body", "hypertrophy", "strength", "function")
    ) +
    as.integer(specification$model_index)
  model <- brms::brm(
    formula = stats::as.formula(input$formula),
    data = input$data,
    prior = input$priors,
    chains = specification$chains,
    cores = specification$parallel_chains,
    seed = seed,
    warmup = specification$iter_warmup,
    iter = specification$iter_warmup + specification$iter_sampling,
    control = list(
      adapt_delta = specification$adapt_delta,
      max_treedepth = specification$max_treedepth
    ),
    save_pars = brms::save_pars(all = TRUE)
  )

  candidate <- list(
    outcome = specification$outcome,
    model_index = as.integer(specification$model_index),
    model_name = specification$model_name,
    specification = specification,
    model = model
  )
  output_dir <- file.path(output_root, specification$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d.qs", as.integer(specification$model_index))
  )
  temporary_file <- paste0(output_file, ".tmp-", Sys.getpid())
  qs::qsave(candidate, temporary_file, preset = "high")

  if (file.exists(output_file)) file.remove(output_file)
  if (!file.rename(temporary_file, output_file)) {
    stop("Could not finalise the total-intake primary fit file.",
         call. = FALSE)
  }
  if (!file.exists(output_file) || file.info(output_file)$size <= 0) {
    stop("The total-intake primary fit file is invalid.",
         call. = FALSE)
  }

  output_file
}

make_update_2026_total_primary_fit_manifest <- function(
    fit_paths,
    specifications
) {
  paths <- unname(unlist(fit_paths, use.names = FALSE))
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::select(outcome, model_index, model_name)
  path_table <- tibble::tibble(
    outcome = basename(dirname(paths)),
    model_index = as.integer(stringr::str_match(
      basename(paths),
      "model_([0-9]+)\\.qs$"
    )[, 2]),
    fit_path = paths
  )

  manifest <- specification_table |>
    dplyr::left_join(path_table, by = c("outcome", "model_index")) |>
    dplyr::mutate(
      stage = "initial",
      bytes = file.info(fit_path)$size,
      sha256 = purrr::map_chr(
        fit_path,
        ~ digest::digest(
          file = .x,
          algo = "sha256",
          serialize = FALSE
        )
      )
    ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  if (
    length(paths) != 72L ||
      nrow(manifest) != 72L ||
      anyDuplicated(paste(manifest$outcome, manifest$model_index)) ||
      anyNA(manifest$fit_path) ||
      !all(file.exists(manifest$fit_path)) ||
      any(manifest$bytes <= 0) ||
      any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The total-intake primary fit manifest is incomplete.",
         call. = FALSE)
  }

  manifest
}

write_update_2026_total_primary_fit_manifest <- function(
    manifest,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure",
      "total_g_day", "primary", "fit_manifest.csv"
    )
) {
  if (
    nrow(manifest) != 72L ||
      !all(file.exists(manifest$fit_path)) ||
      any(manifest$bytes <= 0) ||
      any(nchar(manifest$sha256) != 64L)
  ) {
    stop("Cannot write an invalid total-intake fit manifest.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(manifest, output_file, na = "")
  output_file
}

compile_update_2026_total_primary_diagnostic_audit <- function(
    diagnostics,
    family = "total_primary"
) {
  if (length(family) != 1L || is.na(family) || !nzchar(family)) {
    stop("The diagnostic-audit family must be a nonempty scalar.",
         call. = FALSE)
  }

  summary <- dplyr::bind_rows(purrr::map(diagnostics, "summary")) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    ) |>
    dplyr::mutate(
      ppc_warning = primary_ppc_warning(dplyr::pick(dplyr::everything())),
      status = dplyr::case_when(
        !diagnostic_pass ~ "REQUIRES REMEDIATION",
        ppc_warning ~ "PASS WITH PPC WARNING",
        TRUE ~ "PASS"
      )
    )

  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  index_check <- summary |>
    dplyr::group_by(outcome) |>
    dplyr::summarise(
      models = dplyr::n(),
      indices_valid = setequal(model_index, retained),
      .groups = "drop"
    )

  if (
    length(diagnostics) != 72L ||
      nrow(summary) != 72L ||
      anyDuplicated(paste(summary$outcome, summary$model_index)) ||
      nrow(index_check) != 4L ||
      any(index_check$models != 18L) ||
      !all(index_check$indices_valid)
  ) {
    stop("The total-intake primary diagnostics are incomplete.",
         call. = FALSE)
  }

  parameter_failures <- purrr::map_dfr(
    diagnostics,
    function(result) {
      result$parameter_failures |>
        dplyr::mutate(
          outcome = result$summary$outcome[[1L]],
          model_index = result$summary$model_index[[1L]],
          .before = 1L
        )
    }
  )

  outcome_summary <- summary |>
    dplyr::group_by(outcome) |>
    dplyr::summarise(
      models = dplyr::n(),
      models_passing_sampling = sum(diagnostic_pass),
      models_requiring_remediation = sum(!diagnostic_pass),
      models_with_ppc_warning = sum(ppc_warning),
      minimum_coverage = min(predictive_90_interval_coverage),
      maximum_coverage = max(predictive_90_interval_coverage),
      .groups = "drop"
    )

  list(
    family = family,
    models = nrow(summary),
    models_passing_sampling = sum(summary$diagnostic_pass),
    models_requiring_remediation = sum(!summary$diagnostic_pass),
    all_sampling_diagnostics_pass = all(summary$diagnostic_pass),
    diagnostic_summary = summary,
    parameter_failures = parameter_failures,
    outcome_summary = outcome_summary
  )
}

write_update_2026_total_primary_diagnostic_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure",
      "total_g_day", "primary", "diagnostics"
    )
) {
  if (
    audit$models != 72L ||
      nrow(audit$diagnostic_summary) != 72L ||
      nrow(audit$outcome_summary) != 4L
  ) {
    stop("Cannot write an incomplete total-intake diagnostic audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    parameter_failures = file.path(output_dir, "parameter_failures.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv")
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$parameter_failures,
    paths[["parameter_failures"]],
    na = ""
  )
  readr::write_csv(
    audit$outcome_summary,
    paths[["outcome_summary"]],
    na = ""
  )
  unname(paths)
}

make_update_2026_total_primary_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass)

  if (
    nrow(failed) != 1L ||
      failed$outcome[[1L]] != "hypertrophy" ||
      failed$model_index[[1L]] != 20L ||
      failed$divergent_transitions[[1L]] != 1L ||
      failed$maximum_treedepth_transitions[[1L]] != 0L ||
      !isTRUE(failed$convergence_pass[[1L]])
  ) {
    stop("The total-intake primary remedy no longer matches its audit.",
         call. = FALSE)
  }

  selected <- purrr::keep(
    specifications,
    ~ identical(.x$outcome, "hypertrophy") &&
      identical(as.integer(.x$model_index), 20L)
  )
  if (length(selected) != 1L) {
    stop("Could not uniquely select total-intake hypertrophy model 20.",
         call. = FALSE)
  }

  remedy <- selected[[1L]]
  remedy$adapt_delta <- 0.9995
  remedy$remedy <- "adapt_delta_0.9995_after_one_divergence"
  remedy$archive_stage <- "remedy_1"
  remedy$remedy_reason <- paste(
    "One divergent transition with no tree-depth, E-BFMI, R-hat, ESS,",
    "or MCSE failure."
  )
  list(hypertrophy_model_20 = remedy)
}

validate_update_2026_total_primary_remedy_inputs <- function(
    inputs,
    initial_fit_paths
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(
    inputs,
    function(input) {
      specification <- input$specification
      expected_path <- paths[
        basename(dirname(paths)) == specification$outcome &
          basename(paths) == sprintf(
            "model_%02d.qs",
            as.integer(specification$model_index)
          )
      ]
      brms::make_standata(
        formula = stats::as.formula(input$formula),
        data = input$data,
        prior = input$priors
      )
      tibble::tibble(
        outcome = specification$outcome,
        model_index = as.integer(specification$model_index),
        model_name = specification$model_name,
        remedy = specification$remedy,
        adapt_delta = specification$adapt_delta,
        max_treedepth = as.integer(specification$max_treedepth),
        iter_warmup = specification$iter_warmup,
        iter_sampling = specification$iter_sampling,
        chains = specification$chains,
        parallel_chains = specification$parallel_chains,
        initial_fit_exists =
          length(expected_path) == 1L && file.exists(expected_path),
        valid = TRUE
      )
    }
  )

  if (
    nrow(checks) != 1L ||
      checks$outcome[[1L]] != "hypertrophy" ||
      checks$model_index[[1L]] != 20L ||
      checks$adapt_delta[[1L]] != 0.9995 ||
      checks$max_treedepth[[1L]] < 15L ||
      !checks$initial_fit_exists[[1L]] ||
      !checks$valid[[1L]]
  ) {
    stop("The total-intake primary remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_primary_remedy_preflight <- function(
