validate_update_2026_total_primary_loo_inputs <- function(
    accepted_fit_manifest,
    final_diagnostic_audit,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  stage_counts <- table(accepted_fit_manifest$stage)
  outcome_counts <- table(accepted_fit_manifest$outcome)
  checks <- tibble::tribble(
    ~check, ~passed,
    "all 72 final sampling diagnostics pass",
    isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass),
    "accepted registry contains 18 models per outcome",
    length(outcome_counts) == 4L && all(outcome_counts == 18L),
    "accepted registry contains 71 initial and 1 remedy fit",
    identical(unname(stage_counts["initial"]), 71L) &&
      identical(unname(stage_counts["remedy_1"]), 1L),
    "all accepted fit files exist and are nonempty",
    all(file.exists(accepted_fit_manifest$fit_path)) &&
      all(file.info(accepted_fit_manifest$fit_path)$size > 0),
    "all accepted fit hashes are present",
    all(nchar(accepted_fit_manifest$sha256) == 64L)
  )

  ready <-
    nrow(accepted_fit_manifest) == 72L &&
    !anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) &&
    all(checks$passed) &&
    is.numeric(k_threshold) && length(k_threshold) == 1L &&
    !is.na(k_threshold) && k_threshold == 0.7 &&
    is.numeric(cores_per_branch) && length(cores_per_branch) == 1L &&
    !is.na(cores_per_branch) && cores_per_branch == 1L

  if (!ready) {
    stop("The total-intake primary LOO preflight is incomplete.",
         call. = FALSE)
  }
  list(
    family = "total_primary",
    models = 72L,
    k_threshold = k_threshold,
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    ready = TRUE
  )
}

