    directory,
    sprintf("model_%02d_integrated_loo.qs", as.integer(model_index))
  )
}

compute_update_2026_total_primary_integrated_loo_to_file <- function(
    record,
    enabled,
    cores = 1L,
    k_threshold = 0.7
) {
  retained_indices <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (!isTRUE(enabled)) {
    stop(
      "Total-intake primary LOO is disabled. Set ",
      "PROTEIN_UPDATE_2026_TOTAL_PRIMARY_LOO=run to enable it.",
      call. = FALSE
    )
  }

  if (
    !file.exists(record$fit_path) ||
      !record$model_index %in% retained_indices ||
      !record$outcome %in% c(
        "whole_body", "hypertrophy", "strength", "function"
      )
  ) {
    stop("A total-intake primary LOO record is invalid.", call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  if (
    !identical(candidate$outcome, record$outcome) ||
      as.integer(candidate$model_index) != record$model_index
  ) {
    stop("A total-intake fit does not match its LOO record.",
         call. = FALSE)
  }

  initial <- compute_primary_candidate_psis_loo(
    fitted_candidate = candidate,
    cores = cores,
    save_psis = FALSE
  )
  integrated <- compute_primary_candidate_integrated_psis_loo(
    fitted_candidate = candidate,
    initial_loo_result = initial,
    k_threshold = k_threshold,
    cores = cores
  )
  integrated$fit_path <- normalizePath(
    record$fit_path, winslash = "/", mustWork = TRUE
  )
  integrated$fit_stage <- record$fit_stage

  output_file <- update_2026_total_primary_loo_file_path(
    record$outcome,
    record$model_index
  )
  temporary_file <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary_file, force = TRUE), add = TRUE)
  qs::qsave(integrated, temporary_file, preset = "high")

  if (!file.copy(temporary_file, output_file, overwrite = TRUE)) {
    stop("Could not finalise a total-intake primary LOO reduction.",
         call. = FALSE)
  }
  unlink(temporary_file, force = TRUE)
  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

audit_update_2026_total_primary_integrated_loo_files <- function(
    paths,
    k_threshold = 0.7
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  if (
    length(paths) != 72L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The total-intake primary integrated-LOO files are incomplete.",
         call. = FALSE)
  }

  results <- purrr::map(paths, qs::qread)
  retained_indices <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  valid <- purrr::map_lgl(results, function(result) {
    inherits(result$loo, "loo") &&
      identical(result$remedy, "integrated_observation_level_psis") &&
      result$outcome %in% c(
        "whole_body", "hypertrophy", "strength", "function"
      ) &&
      result$model_index %in% retained_indices &&
      nrow(result$observation_manifest) == nrow(result$loo$pointwise)
  })

  keys <- purrr::map_chr(
    results,
    ~ paste(.x$outcome, .x$model_index, sep = "|")
  )
  expected_keys <- as.vector(outer(
    c("whole_body", "hypertrophy", "strength", "function"),
    retained_indices,
    function(outcome, model_index) paste(outcome, model_index, sep = "|")
  ))

  if (!all(valid) || anyDuplicated(keys) || !setequal(keys, expected_keys)) {
    stop("The total-intake primary integrated-LOO set is invalid.",
         call. = FALSE)
  }

  method_comparison <- purrr::map_dfr(results, "comparison")
  observation_diagnostics <- purrr::map_dfr(
    results,
    "observation_diagnostics"
  )
  observation_set_audit <- purrr::map_dfr(
    results,
    function(result) {
      manifest <- result$observation_manifest |>
        dplyr::mutate(
          dplyr::across(where(is.factor), as.character),
          study_no = as.character(study_no)
        )
      tibble::tibble(
        outcome = result$outcome,
        model_index = as.integer(result$model_index),
        observations = nrow(manifest),
        observation_set_sha256 = digest::digest(
          manifest,
          algo = "sha256"
        )
      )
    }
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  model_summary <- method_comparison |>
    dplyr::filter(method == "integrated_observation_level_psis") |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  high_k_cases <- observation_diagnostics |>
    dplyr::filter(integrated_pareto_k > k_threshold) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )

  outcome_summary <- model_summary |>
    dplyr::group_by(outcome) |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_high_k = sum(n_pareto_k_gt_threshold > 0L),
      high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_pareto_k = max(maximum_pareto_k),
      compute_hours = sum(compute_seconds) / 3600,
      .groups = "drop"
    ) |>
    dplyr::left_join(
      observation_set_audit |>
        dplyr::group_by(outcome) |>
        dplyr::summarise(
          observation_counts = paste(
            sort(unique(observations)),
            collapse = ","
          ),
          observation_sets_aligned =
            dplyr::n_distinct(observation_set_sha256) == 1L,
          .groups = "drop"
        ),
      by = "outcome"
    ) |>
    dplyr::mutate(
      stacking_ready =
        high_k_cases == 0L & observation_sets_aligned
    )

  reduction_manifest <- purrr::map2_dfr(
    paths,
    results,
    function(path, result) {
      tibble::tibble(
        outcome = result$outcome,
        model_index = as.integer(result$model_index),
        model_name = result$model_name,
        fit_stage = result$fit_stage,
        fit_path = result$fit_path,
        integrated_loo_path = normalizePath(
          path, winslash = "/", mustWork = TRUE
        ),
        bytes = file.info(path)$size,
        sha256 = digest::digest(
          file = path,
          algo = "sha256",
          serialize = FALSE
        )
      )
    }
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  if (
    nrow(model_summary) != 72L ||
      nrow(outcome_summary) != 4L ||
      nrow(method_comparison) != 144L ||
      nrow(observation_set_audit) != 72L ||
      nrow(reduction_manifest) != 72L
  ) {
    stop("The total-intake primary integrated-LOO audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_primary",
    reduction_manifest = reduction_manifest,
    model_summary = model_summary,
    outcome_summary = outcome_summary,
    method_comparison = method_comparison,
    observation_diagnostics = observation_diagnostics,
    observation_set_audit = observation_set_audit,
    high_k_cases = high_k_cases,
    exact_refits_required = nrow(high_k_cases),
    stacking_ready =
      nrow(high_k_cases) == 0L &&
      all(outcome_summary$observation_sets_aligned),
    k_threshold = k_threshold
  )
}

write_update_2026_total_primary_integrated_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "primary", "loo_psis"
    )
) {
  if (
    nrow(audit$model_summary) != 72L ||
      nrow(audit$outcome_summary) != 4L ||
      nrow(audit$reduction_manifest) != 72L
  ) {
    stop("Cannot write an incomplete total-intake LOO audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    reduction_manifest = file.path(output_dir, "reduction_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    method_comparison = file.path(output_dir, "method_comparison.csv"),
    observation_diagnostics = file.path(
      output_dir, "observation_diagnostics.csv.gz"
    ),
    observation_set_audit = file.path(
      output_dir, "observation_set_audit.csv"
    ),
    high_k_cases = file.path(output_dir, "high_k_cases.csv")
  )

  readr::write_csv(audit$reduction_manifest, paths[["reduction_manifest"]])
  readr::write_csv(audit$model_summary, paths[["model_summary"]])
  readr::write_csv(audit$outcome_summary, paths[["outcome_summary"]])
  readr::write_csv(audit$method_comparison, paths[["method_comparison"]])
  readr::write_csv(
    audit$observation_diagnostics,
    paths[["observation_diagnostics"]]
  )
  readr::write_csv(
    audit$observation_set_audit,
    paths[["observation_set_audit"]]
  )
  readr::write_csv(audit$high_k_cases, paths[["high_k_cases"]])
  unname(paths)
}

# Refit candidates as needed on the body-mass-complete sample so the total-
# intake models with and without body mass as a moderator can be compared on
# the same observations.
make_update_2026_total_primary_common_sample_specifications <- function(
    specifications,
    integrated_loo_audit
) {
  alignment <- integrated_loo_audit$outcome_summary |>
    dplyr::select(outcome, observation_sets_aligned)

  if (
    nrow(alignment) != 4L ||
      alignment$observation_sets_aligned[
        alignment$outcome == "hypertrophy"
      ] ||
      !all(alignment$observation_sets_aligned[
        alignment$outcome != "hypertrophy"
      ]) ||
      integrated_loo_audit$exact_refits_required != 0L
  ) {
    stop(
      "The total-intake common-sample refit no longer matches the LOO audit.",
      call. = FALSE
    )
  }

  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  selected <- purrr::keep(
    specifications,
    function(specification) {
      identical(specification$outcome, "hypertrophy") &&
        !isTRUE(specification$includes_moderators) &&
        as.integer(specification$model_index) %in% expected_indices
    }
  )

  observed_indices <- sort(unname(
    purrr::map_int(selected, "model_index")
  ))
  if (
    length(selected) != 9L ||
      !identical(observed_indices, expected_indices)
  ) {
    stop("The total-intake common-sample model set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::map(
    selected,
    function(specification) {
      specification$archive_stage <- "common_sample_1"
      specification$common_sample_reason <- paste(
        "Restrict non-moderator hypertrophy candidates to the 421-row",
        "body-mass-complete sample used by moderator candidates so that",
        "pointwise predictive densities are comparable for stacking."
      )
      specification
    }
  )

  names(selected) <- paste0(
    "hypertrophy_model_",
    stringr::str_pad(
      purrr::map_int(selected, "model_index"),
      2L,
      pad = "0"
    )
  )

  selected
}

prepare_update_2026_total_primary_common_sample_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome
) {
  if (
    !identical(specification$outcome, "hypertrophy") ||
      isTRUE(specification$includes_moderators)
  ) {
    stop("Only non-moderator hypertrophy models require common-sample refits.",
         call. = FALSE)
  }

  common_data <- data_by_outcome
  common_data[["hypertrophy"]] <- common_data[["hypertrophy"]] |>
    dplyr::filter(is.finite(mean_body_mass_kg)) |>
    droplevels()
  input <- prepare_update_2026_total_primary_input(
    specification = specification,
    data_by_outcome = common_data,
    priors_by_outcome = priors_by_outcome
  )
  input$family <- "total_primary_common_sample"
  input
}

validate_update_2026_total_primary_common_sample_inputs <- function(
    inputs,
    accepted_fit_manifest,
    integrated_loo_audit
) {
  reference <- integrated_loo_audit$observation_diagnostics |>
    dplyr::filter(
      outcome == "hypertrophy",
      model_index == 5L
    ) |>
    dplyr::arrange(observation) |>
    dplyr::transmute(
      study_no = as.character(study_no),
      arm_no = as.integer(arm_no),
      outcome_no = as.integer(outcome_no),
      yi = as.numeric(yi),
      vi = as.numeric(vi)
    )

  if (nrow(reference) != 421L) {
    stop("The hypertrophy common-sample reference is invalid.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(
    inputs,
    function(input) {
      specification <- input$specification
      brms::make_standata(
        formula = stats::as.formula(input$formula),
        data = input$data,
        prior = input$priors
      )
      observed <- input$data |>
        dplyr::transmute(
          study_no = as.character(study_no),
          arm_no = as.integer(arm_no),
          outcome_no = as.integer(outcome_no),
          yi = as.numeric(yi),
          vi = as.numeric(vi)
        )
      initial_path <- accepted_fit_manifest |>
        dplyr::filter(
          outcome == specification$outcome,
          model_index == specification$model_index
        ) |>
        dplyr::pull(fit_path)
      tibble::tibble(
        outcome = specification$outcome,
        model_index = as.integer(specification$model_index),
        model_name = specification$model_name,
        contrasts = nrow(input$data),
        studies = dplyr::n_distinct(input$data$study_no),
        common_observation_set = isTRUE(all.equal(
          observed,
          reference,
          tolerance = 0,
          check.attributes = FALSE
        )),
        adapt_delta = specification$adapt_delta,
        max_treedepth = as.integer(specification$max_treedepth),
        iter_warmup = as.integer(specification$iter_warmup),
        iter_sampling = as.integer(specification$iter_sampling),
        chains = as.integer(specification$chains),
        parallel_chains = as.integer(specification$parallel_chains),
        superseded_fit_exists =
          length(initial_path) == 1L && file.exists(initial_path),
        valid = TRUE
      )
    }
  ) |>
    dplyr::arrange(model_index)

  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  if (
    nrow(checks) != 9L ||
      !identical(checks$model_index, expected_indices) ||
      any(checks$contrasts != 421L) ||
      any(checks$studies != 53L) ||
      !all(checks$common_observation_set) ||
      !all(checks$superseded_fit_exists) ||
      !all(checks$valid) ||
      any(checks$chains != 4L) ||
      any(checks$parallel_chains != 4L)
  ) {
    stop("The total-intake common-sample preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

