compile_update_2026_total_primary_common_sample_diagnostic_audit <- function(
    diagnostics
) {
  summary <- dplyr::bind_rows(purrr::map(diagnostics, "summary")) |>
    dplyr::arrange(model_index) |>
    dplyr::mutate(
      ppc_warning = primary_ppc_warning(dplyr::pick(dplyr::everything())),
      status = dplyr::case_when(
        !diagnostic_pass ~ "REQUIRES REMEDIATION",
        ppc_warning ~ "PASS WITH PPC WARNING",
        TRUE ~ "PASS"
      )
    )

  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  if (
    length(diagnostics) != 9L ||
      nrow(summary) != 9L ||
      any(summary$outcome != "hypertrophy") ||
      !identical(summary$model_index, expected_indices)
  ) {
    stop("The total-intake common-sample diagnostics are incomplete.",
         call. = FALSE)
  }

  parameter_failures <- purrr::map_dfr(
    diagnostics,
    function(result) {
      result$parameter_failures |>
        dplyr::mutate(
          outcome = result$summary$outcome[[1L]],
          model_index = result$summary$model_index[[1L]],
          .before = 1L
        )
    }
  )

  list(
    family = "total_primary_common_sample",
    models = 9L,
    models_passing_sampling = sum(summary$diagnostic_pass),
    models_requiring_remediation = sum(!summary$diagnostic_pass),
    all_sampling_diagnostics_pass = all(summary$diagnostic_pass),
    diagnostic_summary = summary,
    parameter_failures = parameter_failures
  )
}

write_update_2026_total_primary_common_sample_diagnostic_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "primary", "common_sample_1", "diagnostics"
    )
) {
  if (
    audit$models != 9L ||
      nrow(audit$diagnostic_summary) != 9L
  ) {
    stop("Cannot write an incomplete common-sample diagnostic audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    parameter_failures = file.path(output_dir, "parameter_failures.csv")
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$parameter_failures,
    paths[["parameter_failures"]],
    na = ""
  )
  unname(paths)
}

make_update_2026_total_primary_common_sample_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass)

  if (
    nrow(failed) != 1L ||
      failed$outcome[[1L]] != "hypertrophy" ||
      failed$model_index[[1L]] != 11L ||
      failed$divergent_transitions[[1L]] != 0L ||
      failed$maximum_treedepth_transitions[[1L]] != 0L ||
      !isTRUE(failed$geometry_pass[[1L]]) ||
      isTRUE(failed$convergence_pass[[1L]]) ||
      failed$minimum_tail_ess[[1L]] >= 400
  ) {
    stop("The common-sample remedy no longer matches its diagnostic audit.",
         call. = FALSE)
  }

  selected <- purrr::keep(
    specifications,
    ~ identical(.x$outcome, "hypertrophy") &&
      identical(as.integer(.x$model_index), 11L)
  )
  if (length(selected) != 1L) {
    stop("Could not uniquely select common-sample hypertrophy model 11.",
         call. = FALSE)
  }

  remedy <- selected[[1L]]
  remedy$iter_sampling <- 12000L
  remedy$remedy <- "double_sampling_after_low_tail_ess"
  remedy$archive_stage <- "common_sample_remedy_1"
  remedy$remedy_reason <- paste(
    "Clean geometry with two random-smooth parameters below the tail-ESS",
    "threshold; retain priors and geometry controls and double sampling."
  )
  list(hypertrophy_model_11 = remedy)
}

validate_update_2026_total_primary_common_sample_remedy_inputs <- function(
    inputs,
    common_sample_fit_paths
) {
  paths <- unname(unlist(common_sample_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(
    inputs,
    function(input) {
      specification <- input$specification
      expected_path <- paths[
        basename(dirname(paths)) == specification$outcome &
          basename(paths) == sprintf(
            "model_%02d.qs",
            as.integer(specification$model_index)
          )
      ]
      brms::make_standata(
        formula = stats::as.formula(input$formula),
        data = input$data,
        prior = input$priors
      )
      tibble::tibble(
        outcome = specification$outcome,
        model_index = as.integer(specification$model_index),
        model_name = specification$model_name,
        remedy = specification$remedy,
        contrasts = nrow(input$data),
        studies = dplyr::n_distinct(input$data$study_no),
        adapt_delta = specification$adapt_delta,
        max_treedepth = as.integer(specification$max_treedepth),
        iter_warmup = as.integer(specification$iter_warmup),
        iter_sampling = as.integer(specification$iter_sampling),
        chains = as.integer(specification$chains),
        parallel_chains = as.integer(specification$parallel_chains),
        common_sample_fit_exists =
          length(expected_path) == 1L && file.exists(expected_path),
        valid = TRUE
      )
    }
  )

  if (
    nrow(checks) != 1L ||
      checks$outcome[[1L]] != "hypertrophy" ||
      checks$model_index[[1L]] != 11L ||
      checks$contrasts[[1L]] != 421L ||
      checks$studies[[1L]] != 53L ||
      checks$adapt_delta[[1L]] != 0.999 ||
      checks$max_treedepth[[1L]] != 15L ||
      checks$iter_warmup[[1L]] != 2000L ||
      checks$iter_sampling[[1L]] != 12000L ||
      checks$chains[[1L]] != 4L ||
      checks$parallel_chains[[1L]] != 4L ||
      !checks$common_sample_fit_exists[[1L]] ||
      !checks$valid[[1L]]
  ) {
    stop("The common-sample remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

