combine_update_2026_total_primary_common_sample_remedy_diagnostics <- function(
    initial_audit,
    remedy_diagnostics
) {
  if (length(remedy_diagnostics) != 1L) {
    stop("Expected one common-sample remedy diagnostic.", call. = FALSE)
  }

  remedy <- remedy_diagnostics[[1L]]
  remedy_summary <- remedy$summary
  if (
    nrow(remedy_summary) != 1L ||
      remedy_summary$outcome[[1L]] != "hypertrophy" ||
      remedy_summary$model_index[[1L]] != 11L
  ) {
    stop("The common-sample remedy diagnostic is invalid.",
         call. = FALSE)
  }

  summary <- initial_audit$diagnostic_summary |>
    dplyr::filter(model_index != 11L) |>
    dplyr::bind_rows(remedy_summary) |>
    dplyr::arrange(model_index) |>
    dplyr::mutate(
      ppc_warning = primary_ppc_warning(dplyr::pick(dplyr::everything())),
      status = dplyr::case_when(
        !diagnostic_pass ~ "REQUIRES REMEDIATION",
        ppc_warning ~ "PASS WITH PPC WARNING",
        TRUE ~ "PASS"
      )
    )

  parameter_failures <- initial_audit$parameter_failures |>
    dplyr::filter(model_index != 11L) |>
    dplyr::bind_rows(
      remedy$parameter_failures |>
        dplyr::mutate(
          outcome = "hypertrophy",
          model_index = 11L,
          .before = 1L
        )
    )

  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  if (
    nrow(summary) != 9L ||
      !identical(summary$model_index, expected_indices)
  ) {
    stop("The final common-sample diagnostic audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_primary_common_sample",
    models = 9L,
    models_passing_sampling = sum(summary$diagnostic_pass),
    models_requiring_remediation = sum(!summary$diagnostic_pass),
    all_sampling_diagnostics_pass = all(summary$diagnostic_pass),
    diagnostic_summary = summary,
    parameter_failures = parameter_failures
  )
}

make_update_2026_total_primary_common_sample_accepted_fit_manifest <- function(
    common_sample_fit_paths,
    remedy_fit_paths,
    specifications,
    final_diagnostic_audit
) {
  path_manifest <- function(paths, stage) {
    paths <- unname(unlist(paths, use.names = FALSE))
    tibble::tibble(
      outcome = basename(dirname(paths)),
      model_index = as.integer(stringr::str_match(
        basename(paths), "model_([0-9]+)\\.qs$"
      )[, 2]),
      fit_path = paths,
      stage = stage
    )
  }

  initial <- path_manifest(
    common_sample_fit_paths,
    "common_sample_1"
  )
  remedy <- path_manifest(
    remedy_fit_paths,
    "common_sample_remedy_1"
  )
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::select(outcome, model_index, model_name)

  if (
    nrow(initial) != 9L ||
      nrow(remedy) != 1L ||
      remedy$outcome[[1L]] != "hypertrophy" ||
      remedy$model_index[[1L]] != 11L ||
      !isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass) ||
      final_diagnostic_audit$models_passing_sampling != 9L
  ) {
    stop("Accepted common-sample fits cannot yet be assembled.",
         call. = FALSE)
  }

  accepted <- initial |>
    dplyr::anti_join(
      remedy |> dplyr::select(outcome, model_index),
      by = c("outcome", "model_index")
    ) |>
    dplyr::bind_rows(remedy) |>
    dplyr::left_join(
      specification_table,
      by = c("outcome", "model_index")
    ) |>
    dplyr::mutate(
      bytes = file.info(fit_path)$size,
      sha256 = purrr::map_chr(
        fit_path,
        ~ digest::digest(
          file = .x,
          algo = "sha256",
          serialize = FALSE
        )
      )
    ) |>
    dplyr::select(
      outcome, model_index, model_name, fit_path, stage, bytes, sha256
    ) |>
    dplyr::arrange(model_index)

  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  if (
    nrow(accepted) != 9L ||
      !identical(accepted$model_index, expected_indices) ||
      sum(accepted$stage == "common_sample_1") != 8L ||
      sum(accepted$stage == "common_sample_remedy_1") != 1L ||
      anyDuplicated(accepted[c("outcome", "model_index")]) ||
      !all(file.exists(accepted$fit_path)) ||
      any(accepted$bytes <= 0) ||
      any(nchar(accepted$sha256) != 64L)
  ) {
    stop("The accepted common-sample fit manifest is invalid.",
         call. = FALSE)
  }

  accepted
}

