validate_update_2026_total_primary_common_sample_loo_inputs <- function(
    accepted_fit_manifest,
    final_diagnostic_audit,
    common_sample_preflight,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  stage_counts <- table(accepted_fit_manifest$stage)
  checks <- tibble::tribble(
    ~check, ~passed,
    "all nine common-sample diagnostics pass",
    isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass),
    "accepted registry contains eight initial and one remedy fit",
    identical(unname(stage_counts["common_sample_1"]), 8L) &&
      identical(
        unname(stage_counts["common_sample_remedy_1"]),
        1L
      ),
    "all nine fits use the 421-row common observation set",
    nrow(common_sample_preflight) == 9L &&
      all(common_sample_preflight$contrasts == 421L) &&
      all(common_sample_preflight$common_observation_set),
    "all accepted fit files exist and are nonempty",
    all(file.exists(accepted_fit_manifest$fit_path)) &&
      all(file.info(accepted_fit_manifest$fit_path)$size > 0),
    "all accepted fit hashes are present",
    all(nchar(accepted_fit_manifest$sha256) == 64L)
  )

  ready <-
    nrow(accepted_fit_manifest) == 9L &&
    !anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) &&
    all(checks$passed) &&
    identical(k_threshold, 0.7) &&
    identical(as.integer(cores_per_branch), 1L)

  if (!ready) {
    stop("The common-sample replacement LOO preflight is incomplete.",
         call. = FALSE)
  }
  list(
    family = "total_primary_common_sample",
    models = 9L,
    k_threshold = k_threshold,
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    ready = TRUE
  )
}

write_update_2026_total_primary_common_sample_loo_preflight <- function(
    preflight,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "primary", "common_sample_loo_preflight"
    )
) {
  if (
    !isTRUE(preflight$ready) ||
      preflight$models != 9L ||
      !all(preflight$checks$passed)
  ) {
    stop("Cannot write an invalid common-sample LOO preflight.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    checks = file.path(output_dir, "checks.csv"),
    accepted_fit_manifest = file.path(
      output_dir, "accepted_fit_manifest.csv"
    )
  )
  readr::write_csv(preflight$checks, paths[["checks"]], na = "")
  readr::write_csv(
    preflight$accepted_fit_manifest,
    paths[["accepted_fit_manifest"]],
    na = ""
  )
  unname(paths)
}

make_update_2026_total_primary_common_sample_loo_records <- function(
    accepted_fit_manifest
) {
  required <- c("outcome", "model_index", "fit_path", "stage")
  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  if (
    !all(required %in% names(accepted_fit_manifest)) ||
      nrow(accepted_fit_manifest) != 9L ||
      !identical(accepted_fit_manifest$model_index, expected_indices) ||
      anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) ||
      !all(file.exists(accepted_fit_manifest$fit_path))
  ) {
    stop("The common-sample LOO fit manifest is invalid.", call. = FALSE)
  }

  records <- purrr::pmap(
    accepted_fit_manifest[required],
    function(outcome, model_index, fit_path, stage) {
      list(
        outcome = as.character(outcome),
        model_index = as.integer(model_index),
        fit_path = as.character(fit_path),
        fit_stage = as.character(stage)
      )
    }
  )

  names(records) <- paste0(
    "hypertrophy_model_",
    stringr::str_pad(
      accepted_fit_manifest$model_index,
      2L,
      pad = "0"
    )
  )

  records
}

update_2026_total_primary_common_sample_loo_file_path <- function(model_index) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure", "total_g_day",
    "primary", "loo", "common_sample_final", "hypertrophy"
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf("model_%02d_integrated_loo.qs", as.integer(model_index))
  )
}

compute_update_2026_total_primary_common_sample_loo_to_file <- function(
    record,
    enabled,
    cores = 1L,
    k_threshold = 0.7
) {
  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)

  if (!isTRUE(enabled)) {
    stop(
      "Common-sample LOO is disabled. Set ",
      "PROTEIN_UPDATE_2026_TOTAL_PRIMARY_COMMON_SAMPLE_LOO=run.",
      call. = FALSE
    )
  }

  if (
    !file.exists(record$fit_path) ||
      record$outcome != "hypertrophy" ||
      !record$model_index %in% expected_indices
  ) {
    stop("A common-sample LOO record is invalid.", call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  if (
    !identical(candidate$outcome, record$outcome) ||
      as.integer(candidate$model_index) != record$model_index
  ) {
    stop("A common-sample fit does not match its LOO record.",
         call. = FALSE)
  }

  initial <- compute_primary_candidate_psis_loo(
    fitted_candidate = candidate,
    cores = cores,
    save_psis = FALSE
  )
  integrated <- compute_primary_candidate_integrated_psis_loo(
    fitted_candidate = candidate,
    initial_loo_result = initial,
    k_threshold = k_threshold,
    cores = cores
  )
  integrated$fit_path <- normalizePath(
    record$fit_path, winslash = "/", mustWork = TRUE
  )
  integrated$fit_stage <- record$fit_stage
  output_file <- update_2026_total_primary_common_sample_loo_file_path(
    record$model_index
  )
  temporary_file <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary_file, force = TRUE), add = TRUE)
  qs::qsave(integrated, temporary_file, preset = "high")

  if (!file.copy(temporary_file, output_file, overwrite = TRUE)) {
    stop("Could not finalise a common-sample LOO reduction.",
         call. = FALSE)
  }
  unlink(temporary_file, force = TRUE)
  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

audit_update_2026_total_primary_common_sample_loo_files <- function(
    paths,
    k_threshold = 0.7,
    observations_per_model = 421L,
    family = "total_primary_common_sample"
) {
  paths <- unname(unlist(paths, use.names = FALSE))

  if (
    length(paths) != 9L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The common-sample LOO files are incomplete.", call. = FALSE)
  }

  results <- purrr::map(paths, qs::qread)
  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  observed_indices <- sort(unname(purrr::map_int(results, "model_index")))
  observation_hashes <- purrr::map_chr(
    results,
    function(result) {
      manifest <- result$observation_manifest |>
        dplyr::mutate(
          dplyr::across(where(is.factor), as.character),
          study_no = as.character(study_no)
        )
      digest::digest(manifest, algo = "sha256")
    }
  )

  valid <- purrr::map_lgl(results, function(result) {
    inherits(result$loo, "loo") &&
      identical(result$outcome, "hypertrophy") &&
      result$model_index %in% expected_indices &&
      nrow(result$observation_manifest) == observations_per_model &&
      nrow(result$loo$pointwise) == observations_per_model
  })

  if (
    !all(valid) ||
      !identical(observed_indices, expected_indices) ||
      dplyr::n_distinct(observation_hashes) != 1L
  ) {
    stop("The common-sample LOO set is invalid.", call. = FALSE)
  }

  method_comparison <- purrr::map_dfr(results, "comparison")
  observation_diagnostics <- purrr::map_dfr(
    results,
    "observation_diagnostics"
  )
  model_summary <- method_comparison |>
    dplyr::filter(method == "integrated_observation_level_psis") |>
    dplyr::arrange(model_index)
  high_k_cases <- observation_diagnostics |>
    dplyr::filter(integrated_pareto_k > k_threshold) |>
    dplyr::arrange(model_index, observation)
  reduction_manifest <- purrr::map2_dfr(
    paths,
    results,
    function(path, result) {
      tibble::tibble(
        outcome = result$outcome,
        model_index = as.integer(result$model_index),
        model_name = result$model_name,
        fit_stage = result$fit_stage,
        fit_path = result$fit_path,
        integrated_loo_path = normalizePath(
          path, winslash = "/", mustWork = TRUE
        ),
        bytes = file.info(path)$size,
        sha256 = digest::digest(
          file = path,
          algo = "sha256",
          serialize = FALSE
        )
      )
    }
  ) |>
    dplyr::arrange(model_index)

  if (
    nrow(model_summary) != 9L ||
      nrow(method_comparison) != 18L ||
      nrow(reduction_manifest) != 9L
  ) {
    stop("The common-sample LOO audit is incomplete.", call. = FALSE)
  }

  list(
    family = family,
    reduction_manifest = reduction_manifest,
    model_summary = model_summary,
    method_comparison = method_comparison,
    observation_diagnostics = observation_diagnostics,
    high_k_cases = high_k_cases,
    models = 9L,
    observations_per_model = as.integer(observations_per_model),
    observation_sets_aligned = TRUE,
    maximum_pareto_k = max(model_summary$maximum_pareto_k),
    exact_refits_required = nrow(high_k_cases),
    stacking_ready = nrow(high_k_cases) == 0L,
    k_threshold = k_threshold
  )
}

write_update_2026_total_primary_common_sample_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
