make_update_2026_total_primary_final_loo_manifest <- function(
    integrated_loo_audit,
    common_sample_loo_audit,
    final_fit_manifest
) {
  replacement <- common_sample_loo_audit$reduction_manifest
  replacement_keys <- replacement |>
    dplyr::select(outcome, model_index)

  if (
    nrow(integrated_loo_audit$reduction_manifest) != 72L ||
      integrated_loo_audit$exact_refits_required != 0L ||
      nrow(replacement) != 9L ||
      common_sample_loo_audit$exact_refits_required != 0L ||
      !isTRUE(common_sample_loo_audit$stacking_ready) ||
      !isTRUE(common_sample_loo_audit$observation_sets_aligned) ||
      nrow(final_fit_manifest) != 72L
  ) {
    stop("The final total-intake LOO inputs are incomplete.", call. = FALSE)
  }

  manifest <- integrated_loo_audit$reduction_manifest |>
    dplyr::anti_join(
      replacement_keys,
      by = c("outcome", "model_index")
    ) |>
    dplyr::bind_rows(replacement) |>
    dplyr::mutate(
      loo_source = dplyr::if_else(
        fit_stage %in% c(
          "common_sample_1", "common_sample_remedy_1"
        ),
        "common_sample_integrated_psis",
        "original_integrated_psis"
      ),
      final_loo_path = integrated_loo_path,
      final_bytes = bytes,
      final_sha256 = sha256
    ) |>
    dplyr::select(
      outcome, model_index, model_name, fit_stage, fit_path, loo_source,
      final_loo_path, final_bytes, final_sha256
    ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  fit_comparison <- manifest |>
    dplyr::select(
      outcome, model_index,
      loo_model_name = model_name,
      loo_fit_stage = fit_stage,
      loo_fit_path = fit_path
    ) |>
    dplyr::inner_join(
      final_fit_manifest |>
        dplyr::select(
          outcome, model_index,
          fit_model_name = model_name,
          fit_stage = stage,
          fit_path
        ),
      by = c("outcome", "model_index")
    )

  outcome_counts <- table(manifest$outcome)
  if (
    nrow(manifest) != 72L ||
      anyDuplicated(manifest[c("outcome", "model_index")]) ||
      length(outcome_counts) != 4L ||
      any(outcome_counts != 18L) ||
      sum(manifest$loo_source == "common_sample_integrated_psis") != 9L ||
      nrow(fit_comparison) != 72L ||
      any(fit_comparison$loo_model_name != fit_comparison$fit_model_name) ||
      any(fit_comparison$loo_fit_stage != fit_comparison$fit_stage) ||
      any(fit_comparison$loo_fit_path != fit_comparison$fit_path) ||
      any(!file.exists(manifest$final_loo_path)) ||
      any(file.info(manifest$final_loo_path)$size <= 0) ||
      any(nchar(manifest$final_sha256) != 64L)
  ) {
    stop("The final total-intake LOO manifest is invalid.", call. = FALSE)
  }

  manifest
}

audit_update_2026_total_primary_final_loo <- function(
    final_loo_manifest,
    k_threshold = 0.7
) {
  results <- purrr::map(final_loo_manifest$final_loo_path, qs::qread)
  manifest_keys <- paste(
    final_loo_manifest$outcome,
    final_loo_manifest$model_index,
    sep = "|"
  )
  result_keys <- purrr::map_chr(
    results,
    ~ paste(.x$outcome, .x$model_index, sep = "|")
  )
  retained_indices <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  valid <- purrr::map_lgl(results, function(result) {
    inherits(result$loo, "loo") &&
      identical(result$remedy, "integrated_observation_level_psis") &&
      result$outcome %in% c(
        "whole_body", "hypertrophy", "strength", "function"
      ) &&
      result$model_index %in% retained_indices &&
      nrow(result$observation_manifest) == nrow(result$loo$pointwise)
  })

  if (!all(valid) || !identical(result_keys, manifest_keys)) {
    stop("The final total-intake LOO objects are invalid.", call. = FALSE)
  }
  method_comparison <- purrr::map_dfr(results, "comparison")
  model_summary <- method_comparison |>
    dplyr::filter(method == "integrated_observation_level_psis") |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  observation_diagnostics <- purrr::map_dfr(
    results,
    "observation_diagnostics"
  )
  observation_set_audit <- purrr::map_dfr(
    results,
    function(result) {
      observation_manifest <- result$observation_manifest |>
        dplyr::mutate(
          dplyr::across(where(is.factor), as.character),
          study_no = as.character(study_no)
        )
      tibble::tibble(
        outcome = result$outcome,
        model_index = as.integer(result$model_index),
        observations = nrow(observation_manifest),
        observation_set_sha256 = digest::digest(
          observation_manifest,
          algo = "sha256"
        )
      )
    }
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  high_k_cases <- observation_diagnostics |>
    dplyr::filter(integrated_pareto_k > k_threshold) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )

  outcome_summary <- model_summary |>
    dplyr::group_by(outcome) |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_high_k = sum(n_pareto_k_gt_threshold > 0L),
      high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_pareto_k = max(maximum_pareto_k),
      compute_hours = sum(compute_seconds) / 3600,
      .groups = "drop"
    ) |>
    dplyr::left_join(
      observation_set_audit |>
        dplyr::group_by(outcome) |>
        dplyr::summarise(
          observations = dplyr::first(observations),
          observation_sets_aligned =
            dplyr::n_distinct(observations) == 1L &&
            dplyr::n_distinct(observation_set_sha256) == 1L,
          .groups = "drop"
        ),
      by = "outcome"
    ) |>
    dplyr::mutate(
      stacking_ready = high_k_cases == 0L & observation_sets_aligned
    )

  stacking_ready <-
    nrow(high_k_cases) == 0L &&
    nrow(outcome_summary) == 4L &&
    all(outcome_summary$models == 18L) &&
    all(outcome_summary$observation_sets_aligned) &&
    all(outcome_summary$stacking_ready)

  if (
    nrow(final_loo_manifest) != 72L ||
      nrow(model_summary) != 72L ||
      nrow(method_comparison) != 144L ||
      nrow(observation_set_audit) != 72L ||
      !stacking_ready
  ) {
    stop("The final total-intake LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  list(
    family = "total_primary",
    final_loo_manifest = final_loo_manifest,
    model_summary = model_summary,
    outcome_summary = outcome_summary,
    method_comparison = method_comparison,
    observation_diagnostics = observation_diagnostics,
    observation_set_audit = observation_set_audit,
    high_k_cases = high_k_cases,
    exact_refits = 0L,
    stacking_ready = TRUE,
    k_threshold = k_threshold
  )
}

