compute_update_2026_total_primary_stacking_weights <- function(
    final_loo_audit
) {
  if (!isTRUE(final_loo_audit$stacking_ready)) {
    stop("The final total-intake LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  weights <- purrr::map_dfr(outcomes, function(current_outcome) {
    records <- final_loo_audit$final_loo_manifest |>
      dplyr::filter(outcome == current_outcome) |>
      dplyr::arrange(model_index)
    if (nrow(records) != 18L) {
      stop("A total-intake stacking outcome is incomplete.", call. = FALSE)
    }
    results <- purrr::map(records$final_loo_path, qs::qread)
    loo_objects <- purrr::map(results, "loo")
    pointwise_rows <- purrr::map_int(
      loo_objects,
      ~ nrow(.x$pointwise)
    )
    if (dplyr::n_distinct(pointwise_rows) != 1L) {
      stop(
        "Total-intake stacking requires identical observation counts.",
        call. = FALSE
      )
    }
    # loo_model_weights() checks both the posterior-draw and observation
    # dimensions, although stacking itself consumes only pointwise ELPD.
    # Model 11 deliberately has twice as many retained draws after its
    # convergence remedy. Standardise draw-count metadata only on these
    # temporary copies; the audited LOO objects remain unchanged.
    stacking_dimensions <- c(1L, pointwise_rows[[1L]])
    loo_objects <- purrr::map(
      loo_objects,
      function(loo_object) {
        attr(loo_object, "dims") <- stacking_dimensions
        loo_object
      }
    )
    names(loo_objects) <- records$model_name
    values <- as.numeric(loo::loo_model_weights(
      loo_objects,
      method = "stacking"
    ))
    if (
      length(values) != 18L || any(!is.finite(values)) ||
        any(values < -sqrt(.Machine$double.eps)) ||
        !isTRUE(all.equal(sum(values), 1, tolerance = 1e-8))
    ) {
      stop("Total-intake stacking returned invalid weights.",
           call. = FALSE)
    }
    values <- pmax(values, 0)
    values <- values / sum(values)
    tibble::tibble(
      outcome = current_outcome,
      model_index = records$model_index,
      model_name = records$model_name,
      weight = values
    )
  })

  outcome_sums <- tapply(weights$weight, weights$outcome, sum)
  if (
    nrow(weights) != 72L ||
      anyDuplicated(weights[c("outcome", "model_index")]) ||
      length(outcome_sums) != 4L ||
      any(abs(outcome_sums - 1) > 1e-8)
  ) {
    stop("The total-intake stacking weights are invalid.", call. = FALSE)
  }

  weights
}

write_update_2026_total_primary_stacking_weights <- function(
    weights,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "primary", "stacking_weights.csv"
    )
) {
  outcome_sums <- tapply(weights$weight, weights$outcome, sum)
  if (
    nrow(weights) != 72L || length(outcome_sums) != 4L ||
      any(abs(outcome_sums - 1) > 1e-8)
  ) {
    stop("Cannot write invalid total-intake stacking weights.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(weights, output_file)
  output_file
}

make_update_2026_total_primary_prediction_records <- function(
    accepted_fit_manifest,
    stacking_weights,
    n_draws = 4000L,
    exposure_minimum_g_day = 50,
    grid_step_g_day = 1,
    seed = 105988L
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  required_fit <- c(
    "outcome", "model_index", "model_name", "fit_path", "sha256"
  )
  required_weight <- c("outcome", "model_index", "model_name", "weight")
  n_draws <- as.integer(n_draws)

  if (
    !all(required_fit %in% names(accepted_fit_manifest)) ||
      !all(required_weight %in% names(stacking_weights)) ||
      nrow(accepted_fit_manifest) != 72L ||
      nrow(stacking_weights) != 72L ||
      n_draws < 1L ||
      !is.finite(exposure_minimum_g_day) ||
      !is.finite(grid_step_g_day) || grid_step_g_day <= 0
  ) {
    stop("The total-intake reporting inputs are invalid.", call. = FALSE)
  }

  joined <- stacking_weights |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(dplyr::all_of(required_fit)) |>
        dplyr::rename(fit_sha256 = sha256),
      by = c("outcome", "model_index", "model_name"),
      relationship = "one-to-one"
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)

  if (
    anyNA(joined$fit_path) || any(!file.exists(joined$fit_path)) ||
      anyDuplicated(joined[c("outcome", "model_index")]) ||
      !setequal(unique(joined$outcome), outcomes) ||
      any(!is.finite(joined$weight)) || any(joined$weight < 0)
  ) {
    stop("The total-intake fit and weight registries do not match.",
         call. = FALSE)
  }

  outcome_seed <- stats::setNames(
    seed + seq_along(outcomes) * 10000L,
    outcomes
  )
  allocated <- joined |>
    dplyr::group_by(outcome) |>
    dplyr::group_modify(function(table, key) {
      if (nrow(table) != 18L || abs(sum(table$weight) - 1) > 1e-8) {
        stop("A total-intake prediction ensemble is invalid.",
             call. = FALSE)
      }
      table$draw_count <- allocate_primary_mixture_models(
        table$weight / sum(table$weight),
        n_draws
      )
      table
    }) |>
    dplyr::ungroup() |>
    dplyr::mutate(
      family = "total_primary",
      prediction_type = "total_g_day",
      prediction_seed = as.integer(
        outcome_seed[outcome] + as.integer(model_index)
      ),
      n_draws = n_draws,
      exposure_minimum_g_day = exposure_minimum_g_day,
      grid_step_g_day = grid_step_g_day
    )

  allocation_audit <- allocated |>
    dplyr::summarise(
      allocated_draws = sum(draw_count),
      selected_models = sum(draw_count > 0L),
      .by = outcome
    )

  if (
    nrow(allocation_audit) != 4L ||
      any(allocation_audit$allocated_draws != n_draws) ||
      any(allocation_audit$selected_models < 1L)
  ) {
    stop("The total-intake prediction allocation is incomplete.",
         call. = FALSE)
  }

  allocated <- dplyr::filter(allocated, draw_count > 0L)
  purrr::map(seq_len(nrow(allocated)), function(row) {
    purrr::map(as.list(allocated[row, , drop = FALSE]), unname)
  })
}

make_update_2026_total_primary_prediction_grid <- function(
    data,
    fitted_candidate = NULL,
    exposure_minimum_g_day = 50,
    grid_step_g_day = 1
) {
  required <- c(
    "protein_intake_raw", "resistance_exercise_code",
    "absolute_exposure_reference_g_day", "absolute_exposure_unit_g_day"
  )

  if (!all(required %in% names(data)) || !nrow(data)) {
    stop("The total-intake prediction data are invalid.", call. = FALSE)
  }
  reference <- unique(data$absolute_exposure_reference_g_day)
  unit <- unique(data$absolute_exposure_unit_g_day)
  exposure_maximum_g_day <- max(data$protein_intake_raw, na.rm = TRUE)

  if (
    length(reference) != 1L || !is.finite(reference) ||
      length(unit) != 1L || !is.finite(unit) || unit <= 0 ||
      !is.finite(exposure_minimum_g_day) ||
      exposure_minimum_g_day >= exposure_maximum_g_day ||
      !is.finite(grid_step_g_day) || grid_step_g_day <= 0
  ) {
    stop("The total-intake prediction-grid limits are invalid.",
         call. = FALSE)
  }

  exposure_values <- sort(unique(c(
    round(seq(
      exposure_minimum_g_day,
      exposure_maximum_g_day,
      by = grid_step_g_day
    ), 10),
    reference
  )))

  keys <- tidyr::crossing(
    resistance_exercise_code = c(0, 1),
    protein_intake = exposure_values
  )
  template_data <- if (
    is.list(fitted_candidate) &&
      inherits(fitted_candidate$model, "brmsfit") &&
      is.data.frame(fitted_candidate$model$data)
  ) {
    fitted_candidate$model$data
  } else {
    data
  }

  grouping_variables <- intersect(
    c("study_no", "arm_no", "outcome_no", "study_factor"),
    names(template_data)
  )
  complete <- stats::complete.cases(
    template_data[, grouping_variables, drop = FALSE]
  )

  if (!any(complete)) {
    stop("No complete row is available for the prediction grid.",
         call. = FALSE)
  }
  newdata <- template_data[
    rep(which(complete)[[1L]], nrow(keys)),
    ,
    drop = FALSE
  ]
  newdata$resistance_exercise_code <- keys$resistance_exercise_code
  newdata$protein_intake_raw <- keys$protein_intake
  newdata$total_g_day <- keys$protein_intake
  newdata$protein_intake <- (keys$protein_intake - reference) / unit
  exercise_label <- ifelse(keys$resistance_exercise_code == 0, "yes", "no")

  if ("resistance_exercise_yes_no" %in% names(newdata)) {
    newdata$resistance_exercise_yes_no <- exercise_label
  }
  if ("resistance_exercise_factor" %in% names(newdata)) {
    newdata$resistance_exercise_factor <- factor(
      exercise_label,
      levels = levels(data$resistance_exercise_factor)
    )
  }

  if ("age_centre" %in% names(newdata)) newdata$age_centre <- 0
  if ("duration_centre" %in% names(newdata)) newdata$duration_centre <- 0
  if ("vi" %in% names(newdata)) newdata$vi <- 0
  moderator_data <- add_primary_standardised_moderators(data)
  moderator_centres <- attr(moderator_data, "moderator_centres")
  moderator_scales <- attr(moderator_data, "moderator_scales")
  newdata$age_outcome_z <-
    (0 - moderator_centres[["age_centre"]]) /
      moderator_scales[["age_centre"]]
  newdata$duration_outcome_z <-
    (0 - moderator_centres[["duration_centre"]]) /
      moderator_scales[["duration_centre"]]
  newdata$body_mass_outcome_z <- 0
  list(
    newdata = newdata,
    keys = tibble::tibble(
      resistance_exercise_code = keys$resistance_exercise_code,
      resistance_exercise_label = "Resistance Exercise?",
      resistance_exercise = ifelse(
        keys$resistance_exercise_code == 0,
        "YES",
        "NO"
      ),
      protein_intake = keys$protein_intake,
      protein_intake_g_day = keys$protein_intake
    ),
    reference_g_day = reference,
    unit_g_day = unit,
    protein_min = exposure_minimum_g_day,
    protein_max = max(exposure_values),
    grid_step = grid_step_g_day
  )
}

make_update_2026_total_primary_reporting_preflight <- function(
    records,
    data_by_outcome
) {
  checks <- purrr::map_dfr(records, function(record) {
    data <- data_by_outcome[[record$outcome]]
    maximum <- if (is.data.frame(data)) {
      max(data$protein_intake_raw, na.rm = TRUE)
    } else {
      NA_real_
    }
    reference <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_reference_g_day)
    } else {
      NA_real_
    }
    tibble::tibble(
      outcome = as.character(record$outcome),
      model_index = as.integer(record$model_index),
      model_name = as.character(record$model_name),
      weight = as.numeric(record$weight),
      allocated_draws = as.integer(record$draw_count),
      exposure_minimum_g_day = as.numeric(record$exposure_minimum_g_day),
      exposure_maximum_g_day = maximum,
      reference_g_day = reference,
      grid_step_g_day = as.numeric(record$grid_step_g_day),
      fit_path = as.character(record$fit_path),
      fit_exists = file.exists(record$fit_path),
      valid = record$draw_count > 0L && file.exists(record$fit_path) &&
        nchar(record$fit_sha256) == 64L &&
        is.finite(maximum) && maximum > record$exposure_minimum_g_day &&
        length(reference) == 1L && is.finite(reference)
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  audit <- checks |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      allocated_draws = sum(allocated_draws),
      retained_weight = sum(weight),
      .by = outcome
    )

  if (
    nrow(audit) != 4L || any(audit$selected_models < 1L) ||
      any(audit$allocated_draws != 4000L) ||
      any(audit$retained_weight <= 0) ||
      any(audit$retained_weight > 1 + 1e-8) ||
      anyDuplicated(checks[c("outcome", "model_index")]) ||
      !all(checks$valid)
  ) {
    stop("The total-intake reporting preflight failed.", call. = FALSE)
  }

  checks
}

write_update_2026_total_primary_reporting_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "primary", "reporting", "input_preflight.csv"
    )
) {
  if (!all(checks$valid) || any(tapply(
    checks$allocated_draws,
    checks$outcome,
    sum
  ) != 4000L)) {
    stop("Cannot write an invalid total-intake reporting preflight.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file)
  output_file
}

update_2026_total_primary_reporting_path <- function(
    outcome,
    stage,
    model_index = NULL
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure", "total_g_day",
    "primary", "reporting", stage, outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  filename <- if (is.null(model_index)) {
    paste0(stage, ".qs")
  } else {
    sprintf("model_%02d_%s.qs", as.integer(model_index), stage)
  }
  file.path(directory, filename)
}

write_update_2026_total_primary_prediction_draw_file <- function(
    record,
    data_by_outcome,
    result_path
) {
  if (
    !file.exists(record$fit_path) || record$draw_count < 1L ||
      !identical(as.character(record$family), "total_primary")
  ) {
    stop("A total-intake prediction record is invalid.", call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  if (
    !identical(candidate$outcome, as.character(record$outcome)) ||
      as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(candidate$model_name, as.character(record$model_name))
  ) {
    stop("A total-intake fit does not match its prediction record.",
         call. = FALSE)
  }

  grid <- make_update_2026_total_primary_prediction_grid(
    data = data_by_outcome[[record$outcome]],
    fitted_candidate = candidate,
    exposure_minimum_g_day = record$exposure_minimum_g_day,
    grid_step_g_day = record$grid_step_g_day
  )
  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  set.seed(as.integer(record$prediction_seed))
  draws <- as.matrix(brms::posterior_epred(
    candidate$model,
    newdata = grid$newdata,
    re_formula = NA,
    ndraws = as.integer(record$draw_count)
  ))

  if (ncol(draws) != nrow(grid$keys) && nrow(draws) == nrow(grid$keys)) {
    draws <- t(draws)
  }
  if (
    nrow(draws) != as.integer(record$draw_count) ||
      ncol(draws) != nrow(grid$keys) || anyNA(draws)
  ) {
    stop("Total-intake predictions do not match their allocation.",
         call. = FALSE)
  }

  reduction <- list(
    family = "total_primary",
    outcome = as.character(record$outcome),
    model_index = as.integer(record$model_index),
    model_name = as.character(record$model_name),
    weight = as.numeric(record$weight),
    draw_count = as.integer(record$draw_count),
    prediction_seed = as.integer(record$prediction_seed),
    fit_sha256 = as.character(record$fit_sha256),
    grid = grid$keys,
    draws = draws,
    settings = list(
      protein_min = grid$protein_min,
      protein_max = grid$protein_max,
      grid_step = grid$grid_step,
      reference_intake = grid$reference_g_day,
      internal_unit_g_day = grid$unit_g_day,
      prediction_type = "total_primary"
    )
  )

  write_atomic_qs(reduction, result_path)
}

make_update_2026_total_primary_model_average_records <- function(
    prediction_manifest,
    stacking_weights,
    n_draws = 4000L,
    seed = 106988L
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  purrr::map(seq_along(outcomes), function(index) {
    current_outcome <- outcomes[[index]]
    files <- dplyr::filter(
      prediction_manifest,
      outcome == current_outcome
    )
    weights <- stacking_weights |>
      dplyr::filter(outcome == current_outcome) |>
      dplyr::arrange(model_index)
    if (
      nrow(files) < 1L || sum(files$draw_count) != n_draws ||
        nrow(weights) != 18L || abs(sum(weights$weight) - 1) > 1e-8 ||
        any(!file.exists(files$prediction_path))
    ) {
      stop("A total-intake model-average record is invalid.",
           call. = FALSE)
    }
    list(
      family = "total_primary",
      outcome = current_outcome,
      prediction_manifest = files,
      stacking_weights = weights,
      n_draws = as.integer(n_draws),
      averaging_seed = as.integer(seed + index)
    )
  })
}

write_update_2026_total_primary_reporting_file <- function(
    model_average_path,
    data_by_outcome,
    reference_intake = 78.785,
    sesoi = 0.10,
    result_path
) {
  model_average <- read_sensitivity_full_model_average_file(
    model_average_path,
    family = "total_primary"
  )
  outcome <- model_average$outcome
  data <- data_by_outcome[[outcome]]
  absolute <- summarise_primary_dose_response(model_average)
  supported <- build_sensitivity_mundlak_reporting_pilot(
    absolute,
    model_average,
    data,
    reference_intake
  )
  heatmap <- compute_primary_heatmap_contrasts(
    model_average = model_average,
    data = data,
    protein_min = 50,
    sesoi = sesoi
  )
  report <- list(
    family = "total_primary",
    outcome = outcome,
    dose_response = supported$absolute_full_grid,
    dose_response_increments = supported$increments_full_grid,
    exposure_support_by_group = supported$support_by_group,
    common_exposure_support = supported$common_support,
    pairwise_contrasts = heatmap$contrasts,
    pairwise_support = heatmap$support,
    local_equivalence = summarise_primary_local_equivalence(
      heatmap$contrasts,
      outcome = outcome
    ),
    model_weights = tibble::tibble(
      model_name = names(model_average$model_weights),
      weight = as.numeric(model_average$model_weights)
    ),
    settings = utils::modifyList(
      model_average$settings,
      list(
        reference_intake = reference_intake,
        sesoi = sesoi,
        exposure = "total_g_day",
        exposure_unit = "g/day"
      )
    )
  )

  write_atomic_qs(report, result_path)
}

write_update_2026_total_primary_reporting_audit <- function(
    audit,
    prediction_manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "primary", "reporting"
    )
) {
  if (
    !identical(audit$family, "total_primary") ||
      !isTRUE(audit$all_reporting_checks_pass) ||
      nrow(audit$summary) != 4L ||
      sum(prediction_manifest$draw_count) != 16000L
  ) {
    stop("The total-intake reporting audit is incomplete.", call. = FALSE)
  }

  reports <- purrr::map(
    audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "total_primary"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(
      report$model_weights,
      outcome = report$outcome,
      .before = 1L
    )
  })
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    prediction_manifest = file.path(output_dir, "prediction_manifest.csv"),
    dose_response = file.path(output_dir, "dose_response.csv"),
    dose_response_increments = file.path(
      output_dir, "dose_response_increments.csv"
    ),
    exposure_support_by_group = file.path(
      output_dir, "exposure_support_by_group.csv"
    ),
    common_exposure_support = file.path(
      output_dir, "common_exposure_support.csv"
    ),
    pairwise_contrasts = file.path(output_dir, "pairwise_contrasts.csv.gz"),
    pairwise_support = file.path(output_dir, "pairwise_support.csv"),
    local_equivalence = file.path(output_dir, "local_equivalence.csv"),
    model_weights = file.path(output_dir, "model_weights.csv")
  )

  readr::write_csv(audit$summary, paths[["summary"]])
  readr::write_csv(prediction_manifest, paths[["prediction_manifest"]])
  readr::write_csv(bind_report("dose_response"), paths[["dose_response"]])
  readr::write_csv(
    bind_report("dose_response_increments"),
    paths[["dose_response_increments"]]
  )
  readr::write_csv(
    bind_report("exposure_support_by_group"),
    paths[["exposure_support_by_group"]]
  )
  readr::write_csv(
    bind_report("common_exposure_support"),
    paths[["common_exposure_support"]]
  )
  readr::write_csv(
    bind_report("pairwise_contrasts"),
    paths[["pairwise_contrasts"]]
  )
  readr::write_csv(
    bind_report("pairwise_support"),
    paths[["pairwise_support"]]
  )
  readr::write_csv(
    bind_report("local_equivalence"),
    paths[["local_equivalence"]]
  )
  readr::write_csv(model_weights, paths[["model_weights"]])
  unname(paths)
}

make_update_2026_total_primary_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    data_by_outcome,
    specifications,
    initial_accepted_fit_manifest,
    initial_diagnostic_audit,
    initial_loo_audit,
    common_accepted_fit_manifest,
    common_diagnostic_audit,
    common_loo_audit,
    final_fit_manifest,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  common_keys <- paste(
    common_accepted_fit_manifest$outcome,
    common_accepted_fit_manifest$model_index,
    sep = "::"
  )
  initial_diagnostics <- initial_diagnostic_audit$diagnostic_summary |>
    dplyr::filter(
      !paste(outcome, model_index, sep = "::") %in% common_keys
    )
  final_diagnostics <- dplyr::bind_rows(
    initial_diagnostics,
    common_diagnostic_audit$diagnostic_summary
  ) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  final_parameter_failures <- dplyr::bind_rows(
    initial_diagnostic_audit$parameter_failures |>
      dplyr::filter(
        !paste(outcome, model_index, sep = "::") %in% common_keys
      ),
    common_diagnostic_audit$parameter_failures
  )
  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  specification_keys <- registry_keys(specification_table)
  diagnostic_keys <- registry_keys(final_diagnostics)
  fit_keys <- registry_keys(final_fit_manifest)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, fit_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- specification_table |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      final_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_diagnostics |>
        dplyr::select(outcome, model_index, diagnostic_name = model),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  weight_sums <- stacking_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    )
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )
  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "total_primary"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }

  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      "all four total-intake datasets are valid",
      "all five final registries contain the same 72 model keys",
      "model names agree across specifications fits diagnostics LOO and weights",
      "all 72 final fit files exist and have checksums",
      "all final accepted-fit sampling diagnostics pass",
      "initial LOO contains 72 reductions and no high-k cases",
      "nine common-sample replacements pass diagnostics and LOO",
      "final LOO contains 72 aligned models and no unresolved high-k cases",
      "four stacking vectors contain 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      "all four total-intake reporting audits pass"
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      identical(names(data_by_outcome), outcomes) &&
        all(vapply(data_by_outcome, nrow, integer(1L)) > 0L) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0),
      common_registry && length(specification_keys) == 72L,
      nrow(name_alignment) == 72L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(
          name_alignment$diagnostic_name ==
            name_alignment$specification_name
        ) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(final_fit_manifest) == 72L &&
        all(file.exists(final_fit_manifest$fit_path)) &&
        all(final_fit_manifest$bytes > 0) &&
        all(nchar(final_fit_manifest$sha256) == 64L),
      nrow(final_diagnostics) == 72L &&
        all(final_diagnostics$diagnostic_pass),
      nrow(initial_loo_audit$reduction_manifest) == 72L &&
        nrow(initial_loo_audit$model_summary) == 72L &&
        initial_loo_audit$exact_refits_required == 0L &&
        nrow(initial_loo_audit$high_k_cases) == 0L,
      nrow(common_accepted_fit_manifest) == 9L &&
        common_diagnostic_audit$models == 9L &&
        isTRUE(common_diagnostic_audit$all_sampling_diagnostics_pass) &&
        common_loo_audit$models == 9L &&
        isTRUE(common_loo_audit$observation_sets_aligned) &&
        common_loo_audit$exact_refits_required == 0L,
      nrow(final_loo_audit$model_summary) == 72L &&
        final_loo_audit$exact_refits == 0L &&
        isTRUE(final_loo_audit$stacking_ready) &&
        all(final_loo_audit$outcome_summary$observation_sets_aligned) &&
        all(final_loo_audit$outcome_summary$high_k_cases == 0L),
      nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        all(prediction_sums$selected_models == 6L) &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Updated total-intake primary verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    absolute_exposure_provenance = absolute_audit$exposure_provenance,
    absolute_support_by_outcome = absolute_audit$support_by_outcome,
    absolute_scaling_plan = absolute_audit$scaling_plan,
    reported_derived_agreement = absolute_audit$reported_derived_agreement,
    absolute_model_registry = absolute_audit$model_registry,
    absolute_family_plan = absolute_audit$family_plan,
    analysis_data = analysis_data,
    model_specifications = specification_table,
    model_name_alignment = name_alignment,
    initial_accepted_fit_manifest = initial_accepted_fit_manifest,
    common_sample_accepted_fit_manifest = common_accepted_fit_manifest,
    final_fit_manifest = final_fit_manifest,
    final_sampling_diagnostic_summary = final_diagnostics,
    final_sampling_parameter_failures = final_parameter_failures,
    initial_loo_manifest = initial_loo_audit$reduction_manifest,
    initial_loo_model_summary = initial_loo_audit$model_summary,
    initial_loo_outcome_summary = initial_loo_audit$outcome_summary,
    common_sample_loo_manifest = common_loo_audit$reduction_manifest,
    common_sample_loo_model_summary = common_loo_audit$model_summary,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    c(
      "Final total-intake primary checkpoint checks.",
      "Paths, sizes, and SHA-256 hashes for source data.",
      "Combined-data preparation invariants.",
      "Shared absolute-exposure construction invariants.",
      "Eligible contrast counts for both absolute exposure scales.",
      "Provenance of selected reported or derived exposures.",
      "Observed absolute-exposure support by outcome.",
      "Frozen references, units, and grid rules.",
      "Agreement between reported and derived total intake.",
      "Retained 18-model absolute-exposure registry.",
      "Planned primary and sensitivity absolute-exposure families.",
      "Outcome analysis rows used by total-intake candidates.",
      "Final 72-model total-intake specification registry.",
      "Cross-stage model-name identity audit.",
      "Initial accepted-fit lineage before common-sample alignment.",
      "Accepted nine-fit common-sample replacement lineage.",
      "Final accepted 72-fit lineage used for reporting.",
      "Sampling diagnostics for the final accepted fits.",
      "Parameter-level failures after final fit selection.",
      "Initial 72 integrated PSIS-LOO file manifest.",
      "Initial integrated PSIS-LOO summaries by model.",
      "Initial integrated PSIS-LOO summaries by outcome.",
      "Nine common-sample replacement LOO files.",
      "Common-sample replacement LOO summaries.",
      "Final aligned 72-model LOO lineage.",
      "Final aligned LOO summaries by model.",
      "Final aligned LOO summaries by outcome.",
      "Final total-intake stacking weights.",
      "Allocation of 4,000 prediction draws per outcome.",
      "Reporting file dimensions and checksums.",
      "Model-averaged total-intake dose-response curves.",
      "Changes from the 78.785 g/day reference.",
      "Observed exposure support by resistance-training group.",
      "Exposure support common to resistance-training groups.",
      "Pairwise total-intake contrasts and probabilities.",
      "Observed support for pairwise contrasts.",
      "Practical-equivalence summaries in grams per day."
    ),
    names(artifacts)
  )

  list(
    checks = checks,
    artifacts = artifacts,
    descriptions = descriptions,
    next_family = paste(
      "The total-intake primary family is frozen after this verification",
      "checkpoint; its lean-pruning plan can now be audited."
    )
  )
}

make_update_2026_total_primary_pruning_plan <- function(
    final_fit_manifest,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "primary"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "total_primary_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (any(!file.exists(verification_files))) {
    stop("The total-intake verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  verification_index <- readr::read_csv(
    verification_manifest,
    show_col_types = FALSE
  )

  if (length(verification_files) != nrow(verification_index) + 2L) {
    stop("The total-intake verification-file count is invalid.",
         call. = FALSE)
  }

  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "primary"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the total-intake archive.",
         call. = FALSE)
  }

  fit_roots <- file.path(
    archive_root,
    c("initial", "remedy_1", "common_sample_1", "common_sample_remedy_1")
  )
  if (any(!dir.exists(fit_roots))) {
    stop("An expected total-intake fit directory is missing.", call. = FALSE)
  }

  fit_paths <- unlist(
    purrr::map(
      fit_roots,
      ~ list.files(
        .x,
        pattern = "\\.qs$",
        recursive = TRUE,
        full.names = TRUE
      )
    ),
    use.names = FALSE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)

  accepted_paths <- normalizePath(
    final_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  if (
    length(fit_paths) != 83L || length(accepted_paths) != 72L ||
      anyDuplicated(fit_paths) || anyDuplicated(accepted_paths) ||
      !all(accepted_paths %in% fit_paths) ||
      sum(!fit_paths %in% accepted_paths) != 11L
  ) {
    stop("Total-intake fit retention does not match its final lineage.",
         call. = FALSE)
  }

  fit_manifest <- tibble::tibble(
    path = fit_paths,
    relative_path = substring(fit_paths, nchar(resolved_root) + 2L),
    archive_stage = dplyr::case_when(
      grepl("/initial/", fit_paths, fixed = TRUE) ~ "initial",
      grepl("/remedy_1/", fit_paths, fixed = TRUE) ~ "remedy_1",
      grepl("/common_sample_1/", fit_paths, fixed = TRUE) ~
        "common_sample_1",
      grepl("/common_sample_remedy_1/", fit_paths, fixed = TRUE) ~
        "common_sample_remedy_1",
      TRUE ~ "unknown"
    ),
    outcome = basename(dirname(fit_paths)),
    model_index = as.integer(sub(
      "^model_([0-9]+)\\.qs$", "\\1", basename(fit_paths)
    )),
    accepted_fit = fit_paths %in% accepted_paths,
    bytes = as.numeric(file.info(fit_paths)$size),
    lean_action = "delete frozen total-intake fit archive"
  ) |>
    dplyr::arrange(archive_stage, outcome, model_index)

  expected_stage_counts <- c(
    initial = 72L,
    remedy_1 = 1L,
    common_sample_1 = 9L,
    common_sample_remedy_1 = 1L
  )
  observed_stage_counts <- table(factor(
    fit_manifest$archive_stage,
    levels = names(expected_stage_counts)
  ))

  if (
    any(fit_manifest$archive_stage == "unknown") ||
      anyNA(fit_manifest$model_index) ||
      !identical(
        as.integer(observed_stage_counts),
        unname(expected_stage_counts)
      ) ||
      sum(fit_manifest$accepted_fit) != 72L ||
      sum(!fit_manifest$accepted_fit) != 11L ||
      any(fit_manifest$bytes <= 0)
  ) {
    stop("The total-intake fit stages are not as expected.", call. = FALSE)
  }

  deletion_manifest <- fit_manifest |>
    dplyr::mutate(
      artifact_role = dplyr::if_else(
        accepted_fit,
        "accepted_model_fit",
        "superseded_model_fit"
      ),
      .after = archive_stage
    )

  compact_roots <- c(
    loo = file.path(archive_root, "loo"),
    reporting = file.path(archive_root, "reporting")
  )
  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact total-intake directory is missing.",
         call. = FALSE)
  }

  compact_paths <- unlist(
    purrr::map(
      compact_roots,
      ~ list.files(
        .x,
        recursive = TRUE,
        full.names = TRUE,
        all.files = TRUE
      )
    ),
    use.names = FALSE
  )

  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = dplyr::case_when(
      grepl("/loo/", compact_paths, fixed = TRUE) ~ "loo",
      grepl("/reporting/", compact_paths, fixed = TRUE) ~ "reporting",
      TRUE ~ "unknown"
    ),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact total-intake LOO and reporting archive"
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo", "reporting")
  ))
  if (
    nrow(compact_manifest) != 113L ||
      !identical(as.integer(compact_counts), c(81L, 32L)) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact total-intake archive inventory is incomplete.",
         call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    full_fit_archives_deleted = nrow(deletion_manifest),
    accepted_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "accepted_model_fit"
    ),
    superseded_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "superseded_model_fit"
    ),
    full_fit_archives_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained =
      sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, aligned LOO, and all 72 weights remain frozen;",
      "restoring accepted or superseded total-intake fits requires refitting",
      "the primary total-intake family."
    )
  )

  list(
    summary = summary,
    fit_file_manifest = fit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_total_primary_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "primary", "pruning"
    )
) {
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    fit_file_manifest = file.path(output_dir, "fit_file_manifest.csv"),
    deletion_file_manifest = file.path(
      output_dir, "deletion_file_manifest.csv"
    ),
    compact_archive_manifest = file.path(
      output_dir, "compact_archive_manifest.csv"
    )
  )

  readr::write_csv(plan$summary, paths[["summary"]])
  readr::write_csv(plan$fit_file_manifest, paths[["fit_file_manifest"]])
  readr::write_csv(
    plan$deletion_file_manifest,
    paths[["deletion_file_manifest"]]
  )
  readr::write_csv(
    plan$compact_archive_manifest,
    paths[["compact_archive_manifest"]]
  )
  unname(paths)
}

execute_update_2026_total_primary_pruning <- function(
    plan,
    confirmation,
    receipt_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "primary", "pruning"
    )
) {
  required_confirmation <- "DELETE ALL TOTAL-PRIMARY FIT ARCHIVES"
  if (!identical(confirmation, required_confirmation)) {
    stop(
      "Pruning confirmation must be exactly: ",
      required_confirmation,
      call. = FALSE
    )
  }

  verify_update_2026_manifest_files(plan$verification_manifest)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "primary"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(plan$archive_root), tolower(expected_root))) {
    stop("The pruning plan does not target the total-intake archive.",
         call. = FALSE)
  }
  verify_compact_archive <- function() {
    compact <- plan$compact_archive_manifest
    if (
      nrow(compact) != 113L || any(!file.exists(compact$path)) ||
        any(nchar(compact$sha256) != 64L)
    ) {
      stop("The retained total-intake compact archive is incomplete.",
           call. = FALSE)
    }
    observed <- purrr::map_chr(
      compact$path,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    )
    if (any(observed != compact$sha256)) {
      stop("A retained total-intake compact-file checksum does not match.",
           call. = FALSE)
    }
    invisible(TRUE)
  }

  verify_compact_archive()
  selected <- plan$deletion_file_manifest
  if (
    nrow(selected) != 83L ||
      sum(selected$artifact_role == "accepted_model_fit") != 72L ||
      sum(selected$artifact_role == "superseded_model_fit") != 11L
  ) {
    stop("The total-intake pruning set is inconsistent with its audit.",
         call. = FALSE)
  }

  receipt_path <- file.path(receipt_dir, "executed_lean.csv")
  pending_path <- file.path(receipt_dir, "executed_lean.pending.csv")
  if (file.exists(receipt_path) || file.exists(pending_path)) {
    stop("A total-intake lean-pruning receipt already exists.",
         call. = FALSE)
  }

  selected_paths <- normalizePath(
    selected$path,
    winslash = "/",
    mustWork = TRUE
  )
  permitted_roots <- normalizePath(
    file.path(
      plan$archive_root,
      c("initial", "remedy_1", "common_sample_1", "common_sample_remedy_1")
    ),
    winslash = "/",
    mustWork = TRUE
  )

  permitted_prefixes <- paste0(tolower(permitted_roots), "/")
  path_allowed <- vapply(
    tolower(selected_paths),
    function(path) any(startsWith(path, permitted_prefixes)),
    logical(1L)
  )

  if (any(!path_allowed) || anyDuplicated(selected_paths)) {
    stop("A selected fit falls outside the permitted archive subtrees.",
         call. = FALSE)
  }
  current_paths <- unlist(
    purrr::map(
      permitted_roots,
      ~ list.files(
        .x,
        pattern = "\\.qs$",
        recursive = TRUE,
        full.names = TRUE
      )
    ),
    use.names = FALSE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)

  if (!setequal(current_paths, selected_paths)) {
    stop("The current fit inventory differs from the audited pruning plan.",
         call. = FALSE)
  }
  receipt <- selected |>
    dplyr::mutate(
      sha256_before_deletion = purrr::map_chr(
        selected_paths,
        ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
      ),
      deleted_utc = format(
        Sys.time(),
        tz = "UTC",
        format = "%Y-%m-%dT%H:%M:%SZ"
      )
    )

  dir.create(receipt_dir, recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(receipt, pending_path)
  failures <- selected_paths[!vapply(
    selected_paths,
    function(path) isTRUE(unlink(path) == 0L),
    logical(1L)
  )]
  remaining <- selected_paths[file.exists(selected_paths)]

  if (length(failures) > 0L || length(remaining) > 0L) {
    stop(
      "Total-intake pruning was incomplete; retain the pending receipt.",
      call. = FALSE
    )
  }

  verify_update_2026_manifest_files(plan$verification_manifest)
  verify_compact_archive()
  if (file.rename(pending_path, receipt_path)) {
    return(normalizePath(receipt_path, winslash = "/", mustWork = TRUE))
  }
  stop("Fit deletion completed but the pruning receipt could not be finalised.",
       call. = FALSE)
}

# Total intake with within- and between-study terms ----

# Prepare the body-mass-complete total-intake sample used to separate study
# means from variation in dose within studies.
make_update_2026_total_mundlak_data_by_outcome <- function(
    total_primary_data_by_outcome
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  if (!identical(names(total_primary_data_by_outcome), outcomes)) {
    stop("The total-intake Mundlak outcome registry is invalid.",
         call. = FALSE)
  }

  data <- purrr::map(total_primary_data_by_outcome, function(outcome_data) {
    required <- c(
      "study_no", "arm_no", "outcome_no", "yi", "vi",
      "protein_intake", "protein_intake_raw", "mean_body_mass_kg",
      "absolute_exposure_reference_g_day",
      "absolute_exposure_unit_g_day"
    )
    if (!all(required %in% names(outcome_data))) {
      stop("A total-intake Mundlak dataset is missing required columns.",
           call. = FALSE)
    }
    outcome_data |>
      dplyr::filter(is.finite(mean_body_mass_kg)) |>
      droplevels()
  })

  if (
    any(vapply(data, nrow, integer(1L)) < 1L) ||
      any(vapply(data, function(x) any(!is.finite(x$yi)), logical(1L))) ||
      any(vapply(
        data,
        function(x) any(!is.finite(x$vi) | x$vi <= 0),
        logical(1L)
      ))
  ) {
    stop("The total-intake Mundlak common samples are invalid.",
         call. = FALSE)
  }

  data
}

make_update_2026_total_mundlak_specifications <- function(
    total_primary_specifications
) {
  specifications <- dplyr::bind_rows(total_primary_specifications)
  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  historical_longer_keys <- c(
    "whole_body::4", "whole_body::6", "strength::5", "strength::6",
    "function::5"
  )
  specifications <- specifications |>
    dplyr::mutate(
      key = paste(outcome, model_index, sep = "::"),
      family = "total_mundlak",
      exposure = "total_g_day",
      regularised_variance_priors =
        regularised_variance_priors | model_index == 4L,
      historical_schedule = dplyr::if_else(
        key %in% historical_longer_keys,
        "longer_sampling",
        "base"
      ),
      adapt_delta = as.numeric(adapt_delta),
      max_treedepth = dplyr::if_else(
        key == "strength::6",
        pmax(as.integer(max_treedepth), 15L),
        as.integer(max_treedepth)
      ),
      iter_warmup = dplyr::if_else(
        historical_schedule == "longer_sampling",
        2000L,
        1500L
      ),
      iter_sampling = dplyr::if_else(
        historical_schedule == "longer_sampling",
        4000L,
        2000L
      ),
      chains = 4L,
      parallel_chains = 4L,
      common_sample = TRUE,
      sensitivity_mundlak_expansion = TRUE
    ) |>
    dplyr::select(-key)

  counts <- table(factor(specifications$outcome, levels = c(
    "whole_body", "hypertrophy", "strength", "function"
  )))
  keys <- paste(specifications$outcome, specifications$model_index, sep = "::")
  if (
    nrow(specifications) != 72L || anyDuplicated(keys) ||
      !identical(as.integer(counts), rep(18L, 4L)) ||
      !all(specifications$model_index %in% retained) ||
      sum(specifications$historical_schedule == "longer_sampling") != 5L ||
      sum(specifications$regularised_variance_priors &
            specifications$model_index == 4L) != 4L ||
      any(specifications$chains != 4L) ||
      any(specifications$parallel_chains != 4L)
  ) {
    stop("The total-intake Mundlak specification registry is invalid.",
         call. = FALSE)
  }

  output <- purrr::pmap(specifications, list)
  names(output) <- paste0(
    specifications$outcome,
    "_model_",
    stringr::str_pad(specifications$model_index, 2L, pad = "0")
  )
  output
}

prepare_update_2026_total_mundlak_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome,
    config
) {
  data <- data_by_outcome[[specification$outcome]]
  priors <- priors_by_outcome[[specification$outcome]]

  if (
    is.null(data) || !nrow(data) || is.null(priors) ||
      !specification$outcome %in% config$outcomes
  ) {
    stop("A total-intake Mundlak outcome input is unavailable.",
         call. = FALSE)
  }

  specification$sensitivity_mundlak_sampling <- paste0(
    specification$iter_warmup,
    "_warmup_",
    specification$iter_sampling,
    "_sampling"
  )
  priors <- normalize_primary_brms_priors(priors)

  if (isTRUE(specification$includes_moderators)) {
    data <- add_absolute_primary_body_mass(data)
    priors <- add_absolute_primary_body_mass_prior(priors)
  }
  input <- prepare_mundlak_pilot_input(data, specification, priors)
  input$family <- "total_mundlak"
  input$specification$family <- "total_mundlak"

  if (
    isTRUE(specification$includes_moderators) &&
      sensitivity_model_features(specification$model_index)$includes_protein
  ) {
    updated_formula <- stringr::str_replace(
      input$formula,
      stringr::fixed(" + (1 | arm_no)"),
      " + body_mass_outcome_z + (1 | arm_no)"
    )
    if (identical(updated_formula, input$formula)) {
      stop("Could not add body mass to a total-intake Mundlak formula.",
           call. = FALSE)
    }
    input$formula <- updated_formula
  }

  input
}

validate_update_2026_total_mundlak_inputs <- function(
    specifications,
    data_by_outcome,
    priors_by_outcome,
    config
) {
  checks <- purrr::map_dfr(specifications, function(specification) {
    input <- prepare_update_2026_total_mundlak_input(
      specification,
      data_by_outcome,
      priors_by_outcome,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      family = input$family,
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      historical_schedule = specification$historical_schedule,
      common_sample = isTRUE(specification$common_sample),
      includes_moderators = isTRUE(specification$includes_moderators),
      body_mass_in_formula =
        stringr::str_detect(input$formula, "\\bbody_mass_outcome_z\\b"),
      regularised_variance_priors =
        isTRUE(specification$regularised_variance_priors),
      basis_dimension = if (is.null(input$basis_spec)) {
        0L
      } else {
        as.integer(input$basis_spec$basis_dimension)
      },
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      arms = dplyr::n_distinct(input$data$arm_no),
      exposure_minimum_g_day = min(input$data$protein_intake_raw),
      exposure_maximum_g_day = max(input$data$protein_intake_raw),
      reference_g_day = unique(
        input$data$absolute_exposure_reference_g_day
      ),
      internal_unit_g_day = unique(
        input$data$absolute_exposure_unit_g_day
      ),
      adapt_delta = max(
        specification$adapt_delta,
        config$adapt_delta_floor
      ),
      max_treedepth = max(
        specification$max_treedepth,
        config$max_treedepth_floor
      ),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    )

  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  outcome_counts <- table(factor(checks$outcome, levels = c(
    "whole_body", "hypertrophy", "strength", "function"
  )))
  schedule_counts <- table(factor(
    checks$historical_schedule,
    levels = c("base", "longer_sampling")
  ))
  row_counts <- checks |>
    dplyr::summarise(
      samples = dplyr::n_distinct(contrasts),
      contrasts = dplyr::first(contrasts),
      .by = outcome
    )
  expected_rows <- tibble::tibble(
    outcome = names(data_by_outcome),
    expected = vapply(data_by_outcome, nrow, integer(1L))
  )
  row_counts <- dplyr::left_join(row_counts, expected_rows, by = "outcome")
  keys <- paste(checks$outcome, checks$model_index, sep = "::")

  if (
    nrow(checks) != 72L || anyDuplicated(keys) || !all(checks$valid) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !all(checks$model_index %in% retained) ||
      !identical(as.integer(schedule_counts), c(67L, 5L)) ||
      any(!checks$common_sample) ||
      nrow(row_counts) != 4L || any(row_counts$samples != 1L) ||
      any(row_counts$contrasts != row_counts$expected) ||
      any(checks$includes_moderators & !checks$body_mass_in_formula) ||
      any(!checks$includes_moderators & checks$body_mass_in_formula) ||
      sum(checks$model_index == 4L &
            checks$regularised_variance_priors) != 4L ||
      any(checks$reference_g_day != 78.785) ||
      any(checks$internal_unit_g_day != 50) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The total-intake Mundlak input preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_mundlak_input_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak", "input_preflight.csv"
    )
) {
  if (nrow(checks) != 72L || !all(checks$valid)) {
    stop("Cannot write an invalid total-intake Mundlak preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

fit_update_2026_total_mundlak_candidate_to_file <- function(
    input,
    config,
    enabled,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop("Total-intake Mundlak fitting is disabled.", call. = FALSE)
  }
  outcome_offset <- match(input$specification$outcome, config$outcomes)
  if (is.na(outcome_offset)) {
    stop("Unknown outcome in a total-intake Mundlak fit.", call. = FALSE)
  }

  local_config <- config
  local_config$iter_warmup <- as.integer(input$specification$iter_warmup)
  local_config$iter_sampling <- as.integer(input$specification$iter_sampling)
  local_config$seed <- as.integer(
    config$seed + 100L * (outcome_offset - 1L) +
      input$specification$model_index
  )
  candidate <- fit_sensitivity_brms_pilot(
    input = input,
    enabled = TRUE,
    config = local_config,
    family = "total_mundlak"
  )
  output_dir <- file.path(output_root, candidate$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d.qs", as.integer(candidate$model_index))
  )
  temporary <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary, force = TRUE), add = TRUE)
  qs::qsave(candidate, temporary, preset = "high")

  if (!file.copy(temporary, output_file, overwrite = TRUE)) {
    stop("Could not finalise a total-intake Mundlak fit file.",
         call. = FALSE)
  }
  unlink(temporary, force = TRUE)
  if (!file.exists(output_file) || file.info(output_file)$size <= 0) {
    stop("The total-intake Mundlak fit file is invalid.", call. = FALSE)
  }

  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

make_update_2026_total_mundlak_fit_manifest <- function(
    fit_paths,
    specifications
) {
  manifest <- make_update_2026_total_primary_fit_manifest(
    fit_paths = fit_paths,
    specifications = specifications
  ) |>
    dplyr::mutate(
      model_name = dplyr::if_else(
        stringr::str_ends(model_name, stringr::fixed(" [total_mundlak]")),
        model_name,
        paste0(model_name, " [total_mundlak]")
      )
    )

  if (
    nrow(manifest) != 72L ||
      anyDuplicated(paste(manifest$outcome, manifest$model_index)) ||
      !all(stringr::str_ends(
        manifest$model_name,
        stringr::fixed(" [total_mundlak]")
      ))
  ) {
    stop("The total-intake Mundlak fit manifest is invalid.",
         call. = FALSE)
  }

  manifest
}

make_update_2026_total_mundlak_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  expected_keys <- c(
    "whole_body::2", "strength::2", "strength::17", "function::6"
  )
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))

  if (
    !identical(diagnostic_audit$family, "total_mundlak") ||
      nrow(failed) != 4L || anyDuplicated(failed$key) ||
      !setequal(failed$key, expected_keys) ||
      any(!failed$geometry_pass) || any(failed$convergence_pass) ||
      any(failed$divergent_transitions != 0L) ||
      any(failed$maximum_treedepth_transitions != 0L)
  ) {
    stop("The total-intake Mundlak remedy set no longer matches its audit.",
         call. = FALSE)
  }

  selected <- purrr::keep(specifications, function(specification) {
    paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    ) %in% expected_keys
  })
  selected <- purrr::map(selected, function(specification) {
    specification$iter_warmup <- 2000L
    specification$iter_sampling <- 4000L
    specification$remedy <- "double_sampling_after_convergence_failure"
    specification$archive_stage <- "remedy_1"
    specification$remedy_reason <- paste(
      "Sampling geometry passed, but the arm-level standard-deviation",
      "parameter did not meet the convergence thresholds."
    )
    specification
  })

  keys <- purrr::map_chr(
    selected,
    ~ paste(.x$outcome, .x$model_index, sep = "::")
  )
  if (
    length(selected) != 4L || anyDuplicated(keys) ||
      !setequal(keys, expected_keys)
  ) {
    stop("The total-intake Mundlak remedy specifications are incomplete.",
         call. = FALSE)
  }

  names(selected) <- paste0(
    purrr::map_chr(selected, "outcome"),
    "_model_",
    stringr::str_pad(purrr::map_int(selected, "model_index"), 2L, pad = "0")
  )
  selected
}

validate_update_2026_total_mundlak_remedy_inputs <- function(
    inputs,
    initial_fit_paths,
    config
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    expected_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      adapt_delta = max(
        as.numeric(specification$adapt_delta),
        config$adapt_delta_floor
      ),
      max_treedepth = max(
        as.integer(specification$max_treedepth),
        config$max_treedepth_floor
      ),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      initial_fit_exists =
        length(expected_path) == 1L && file.exists(expected_path),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  expected_keys <- c(
    "whole_body::2", "strength::2", "strength::17", "function::6"
  )
  if (
    nrow(checks) != 4L || anyDuplicated(keys) ||
      !setequal(keys, expected_keys) || !all(checks$valid) ||
      any(checks$remedy != "double_sampling_after_convergence_failure") ||
      any(checks$iter_warmup != 2000L) ||
      any(checks$iter_sampling != 4000L) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$initial_fit_exists)
  ) {
    stop("The total-intake Mundlak remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

