combine_update_2026_total_mundlak_remedy_diagnostics <- function(
    initial_diagnostics,
    remedy_diagnostics
) {
  diagnostic_key <- function(x) {
    paste(x$summary$outcome[[1L]], x$summary$model_index[[1L]], sep = "::")
  }

  if (length(initial_diagnostics) != 72L || length(remedy_diagnostics) != 4L) {
    stop("The total-intake Mundlak remedy diagnostics are incomplete.",
         call. = FALSE)
  }
  initial_keys <- purrr::map_chr(initial_diagnostics, diagnostic_key)
  remedy_keys <- purrr::map_chr(remedy_diagnostics, diagnostic_key)
  failed_keys <- initial_diagnostics |>
    purrr::keep(~ !.x$summary$diagnostic_pass[[1L]]) |>
    purrr::map_chr(diagnostic_key)

  if (
    anyDuplicated(initial_keys) || anyDuplicated(remedy_keys) ||
      !setequal(remedy_keys, failed_keys) ||
      !all(remedy_keys %in% initial_keys)
  ) {
    stop("The total-intake Mundlak diagnostic replacement is invalid.",
         call. = FALSE)
  }

  final_diagnostics <- initial_diagnostics
  final_diagnostics[match(remedy_keys, initial_keys)] <- remedy_diagnostics
  compile_update_2026_total_primary_diagnostic_audit(
    final_diagnostics,
    family = "total_mundlak"
  )
}

make_update_2026_total_mundlak_accepted_fit_manifest <- function(
    initial_manifest,
    remedy_fit_paths,
    final_diagnostic_audit
) {
  remedy_paths <- unname(unlist(remedy_fit_paths, use.names = FALSE))
  expected_keys <- c(
    "whole_body::2", "strength::2", "strength::17", "function::6"
  )

  if (
    nrow(initial_manifest) != 72L || length(remedy_paths) != 4L ||
      any(!file.exists(remedy_paths)) ||
      any(file.info(remedy_paths)$size <= 0) ||
      !identical(final_diagnostic_audit$family, "total_mundlak") ||
      !isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass) ||
      final_diagnostic_audit$models_passing_sampling != 72L
  ) {
    stop(
      "Accepted total-intake Mundlak fits require 72 passing diagnostics.",
      call. = FALSE
    )
  }

  remedy <- tibble::tibble(
    outcome = basename(dirname(remedy_paths)),
    model_index = as.integer(stringr::str_match(
      basename(remedy_paths), "model_([0-9]+)\\.qs$"
    )[, 2]),
    fit_path = normalizePath(
      remedy_paths,
      winslash = "/",
      mustWork = TRUE
    ),
    stage = "remedy_1",
    bytes = file.info(remedy_paths)$size,
    sha256 = purrr::map_chr(
      remedy_paths,
      ~ digest::digest(
        file = .x,
        algo = "sha256",
        serialize = FALSE
      )
    )
  ) |>
    dplyr::left_join(
      initial_manifest |>
        dplyr::select(outcome, model_index, model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::select(
      outcome, model_index, model_name, fit_path, stage, bytes, sha256
    )

  remedy_keys <- paste(remedy$outcome, remedy$model_index, sep = "::")
  accepted <- initial_manifest |>
    dplyr::anti_join(
      remedy |> dplyr::select(outcome, model_index),
      by = c("outcome", "model_index")
    ) |>
    dplyr::bind_rows(remedy) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  index_check <- accepted |>
    dplyr::summarise(
      models = dplyr::n(),
      indices_valid = setequal(model_index, retained),
      .by = outcome
    )

  if (
    nrow(remedy) != 4L || anyDuplicated(remedy_keys) ||
      !setequal(remedy_keys, expected_keys) ||
      nrow(accepted) != 72L ||
      anyDuplicated(accepted[c("outcome", "model_index")]) ||
      nrow(index_check) != 4L || any(index_check$models != 18L) ||
      !all(index_check$indices_valid) ||
      sum(accepted$stage == "initial") != 68L ||
      sum(accepted$stage == "remedy_1") != 4L ||
      !all(stringr::str_ends(
        accepted$model_name,
        stringr::fixed(" [total_mundlak]")
      )) ||
      !all(file.exists(accepted$fit_path)) ||
      any(accepted$bytes <= 0) || any(nchar(accepted$sha256) != 64L)
  ) {
    stop("The accepted total-intake Mundlak manifest is invalid.",
         call. = FALSE)
  }

  accepted
}

validate_update_2026_total_mundlak_loo_inputs <- function(
    accepted_fit_manifest,
    final_diagnostic_audit,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  stage_counts <- table(accepted_fit_manifest$stage)
  outcome_counts <- table(accepted_fit_manifest$outcome)
  checks <- tibble::tribble(
    ~check, ~passed,
    "all 72 final Mundlak sampling diagnostics pass",
    identical(final_diagnostic_audit$family, "total_mundlak") &&
      isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass),
    "accepted registry contains 18 models per outcome",
    length(outcome_counts) == 4L && all(outcome_counts == 18L),
    "accepted registry contains 68 initial and 4 remedy fits",
    identical(unname(stage_counts["initial"]), 68L) &&
      identical(unname(stage_counts["remedy_1"]), 4L),
    "all accepted fit files exist and are nonempty",
    all(file.exists(accepted_fit_manifest$fit_path)) &&
      all(file.info(accepted_fit_manifest$fit_path)$size > 0),
    "all accepted fit hashes and Mundlak model names are present",
    all(nchar(accepted_fit_manifest$sha256) == 64L) &&
      all(stringr::str_ends(
        accepted_fit_manifest$model_name,
        stringr::fixed(" [total_mundlak]")
      ))
  )

  ready <-
    nrow(accepted_fit_manifest) == 72L &&
    !anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) &&
    all(checks$passed) &&
    is.numeric(k_threshold) && length(k_threshold) == 1L &&
    !is.na(k_threshold) && k_threshold == 0.7 &&
    is.numeric(cores_per_branch) && length(cores_per_branch) == 1L &&
    !is.na(cores_per_branch) && cores_per_branch == 1L

  if (!ready) {
    stop("The total-intake Mundlak LOO preflight is incomplete.",
         call. = FALSE)
  }
  list(
    family = "total_mundlak",
    models = 72L,
    k_threshold = k_threshold,
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    ready = TRUE
  )
}

# Pair accepted fit artifacts with their outcome and model indices so
# integrated scores and exact corrections can be joined.
make_update_2026_total_mundlak_loo_records <- function(
    accepted_fit_manifest
) {
  required <- c(
    "outcome", "model_index", "model_name", "fit_path", "stage"
  )

  if (
    !all(required %in% names(accepted_fit_manifest)) ||
      nrow(accepted_fit_manifest) != 72L ||
      anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) ||
      !all(file.exists(accepted_fit_manifest$fit_path))
  ) {
    stop("The total-intake Mundlak LOO fit manifest is invalid.",
         call. = FALSE)
  }

  records <- purrr::map(
    seq_len(nrow(accepted_fit_manifest)),
    ~ as.list(accepted_fit_manifest[.x, required, drop = FALSE])
  )
  names(records) <- paste0(
    accepted_fit_manifest$outcome,
    "_model_",
    stringr::str_pad(accepted_fit_manifest$model_index, 2L, pad = "0")
  )
  records
}

compute_update_2026_total_mundlak_integrated_loo_to_file <- function(
    fit_record,
    enabled,
    loo_draws = 4000L,
    k_threshold = 0.7,
    cores = 1L,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak", "loo", "integrated"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      "Total-intake Mundlak LOO is disabled. Set ",
      "PROTEIN_UPDATE_2026_TOTAL_MUNDLAK_LOO=run to enable it.",
      call. = FALSE
    )
  }

  result <- compute_mundlak_full_file_integrated_loo(
    fit_record = fit_record,
    loo_draws = loo_draws,
    k_threshold = k_threshold,
    cores = cores,
    family = "total_mundlak",
    slope_description = "total_intake_mundlak_within_basis_slopes"
  )

  if (
    !inherits(result$loo, "loo") ||
      !inherits(result$conditional_loo, "loo") ||
      !identical(unname(as.character(result$family)), "total_mundlak") ||
      !identical(result$remedy, "integrated_observation_level_psis")
  ) {
    stop("Cannot archive an invalid total-intake Mundlak LOO result.",
         call. = FALSE)
  }

  output_dir <- file.path(output_root, result$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf(
      "model_%02d_integrated_loo.qs",
      as.integer(result$model_index)
    )
  )
  write_atomic_qs(result, output_file)
}

audit_update_2026_total_mundlak_integrated_loo_files <- function(
    manifest,
    k_threshold = 0.7
) {
  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (
    !is.data.frame(manifest) || nrow(manifest) != 72L ||
      any(manifest$family != "total_mundlak") ||
      any(!file.exists(manifest$integrated_loo_path))
  ) {
    stop("The total-intake Mundlak LOO manifest cannot be audited.",
         call. = FALSE)
  }

  results <- purrr::map(manifest$integrated_loo_path, qs::qread)
  audit <- audit_mundlak_full_integrated_loo(
    results,
    k_threshold = k_threshold,
    expected_indices = retained
  )
  observation_set_audit <- purrr::map_dfr(results, function(result) {
    observation_manifest <- result$observation_manifest |>
      dplyr::mutate(
        dplyr::across(where(is.factor), as.character),
        study_no = as.character(study_no)
      )
    tibble::tibble(
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      observations = nrow(observation_manifest),
      observation_set_sha256 = digest::digest(
        observation_manifest,
        algo = "sha256"
      )
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  alignment <- observation_set_audit |>
    dplyr::summarise(
      observation_counts = paste(sort(unique(observations)), collapse = ","),
      observation_sets_aligned =
        dplyr::n_distinct(observation_set_sha256) == 1L,
      .by = outcome
    )
  audit$outcome_summary <- audit$outcome_summary |>
    dplyr::left_join(alignment, by = "outcome") |>
    dplyr::mutate(
      stacking_ready =
        exact_refits_required == 0L & observation_sets_aligned
    )
  audit$family <- "total_mundlak"
  audit$observation_set_audit <- observation_set_audit
  audit$stacking_ready <-
    audit$exact_refits_required == 0L &&
    all(audit$outcome_summary$observation_sets_aligned)

  if (
    audit$models != 72L || nrow(audit$outcome_summary) != 4L ||
      nrow(audit$observation_set_audit) != 72L ||
      any(!audit$outcome_summary$observation_sets_aligned)
  ) {
    stop("The total-intake Mundlak integrated-LOO audit is incomplete.",
         call. = FALSE)
  }

  audit
}

write_update_2026_total_mundlak_integrated_loo_audit <- function(
    audit,
    manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak", "loo_psis"
    )
) {
  if (
    !isTRUE(audit$integrated_psis_complete) || audit$models != 72L ||
      nrow(manifest) != 72L ||
      any(!file.exists(manifest$integrated_loo_path)) ||
      nrow(audit$observation_set_audit) != 72L
  ) {
    stop("The total-intake Mundlak integrated-LOO audit is incomplete.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    reduction_manifest = file.path(output_dir, "reduction_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    high_k_cases = file.path(output_dir, "high_k_cases.csv"),
    observation_set_audit = file.path(
      output_dir,
      "observation_set_audit.csv"
    )
  )

  readr::write_csv(manifest, paths[["reduction_manifest"]], na = "")
  readr::write_csv(audit$model_summary, paths[["model_summary"]], na = "")
  readr::write_csv(
    audit$outcome_summary,
    paths[["outcome_summary"]],
    na = ""
  )
  readr::write_csv(audit$high_k_cases, paths[["high_k_cases"]], na = "")
  readr::write_csv(
    audit$observation_set_audit,
    paths[["observation_set_audit"]],
    na = ""
  )
  unname(paths)
}

validate_update_2026_total_mundlak_exact_inputs <- function(
    records,
    config
) {
  if (!is.list(records) || length(records) != 2L) {
    stop("Expected two total-intake Mundlak exact-LOO records.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    integrated <- qs::qread(record$integrated_loo_path)
    observation <- as.integer(record$observation)
    observed_k <- as.numeric(
      loo::pareto_k_values(integrated$loo)[[observation]]
    )
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = observation,
      study_no = as.character(
        integrated$observation_manifest$study_no[[observation]]
      ),
      arm_no = as.integer(
        integrated$observation_manifest$arm_no[[observation]]
      ),
      outcome_no = as.integer(
        integrated$observation_manifest$outcome_no[[observation]]
      ),
      pareto_k = observed_k,
      adapt_delta = 0.999,
      max_treedepth = 15L,
      iter_warmup = as.integer(config$iter_warmup),
      iter_sampling = as.integer(config$iter_sampling),
      chains = as.integer(config$chains),
      parallel_chains = as.integer(config$parallel_chains),
      original_fit_exists = file.exists(record$original_fit_path),
      integrated_loo_exists = file.exists(record$integrated_loo_path),
      valid =
        identical(unname(as.character(integrated$family)),
                  "total_mundlak") &&
        identical(integrated$outcome, record$outcome) &&
        as.integer(integrated$model_index) == record$model_index &&
        is.finite(observed_k) && observed_k > 0.7
    )
  }) |>
    dplyr::arrange(case_id)

  keys <- paste(
    checks$outcome,
    checks$model_index,
    checks$observation,
    sep = "::"
  )

  if (
    nrow(checks) != 2L || anyDuplicated(keys) ||
      !setequal(keys, c("hypertrophy::20::248", "hypertrophy::20::249")) ||
      !identical(checks$case_id, 1:2) ||
      any(checks$study_no != "124") || any(checks$arm_no != 189L) ||
      any(checks$outcome_no != 1023L) ||
      !all(checks$original_fit_exists) ||
      !all(checks$integrated_loo_exists) || !all(checks$valid) ||
      config$chains != 4L || config$parallel_chains != 4L ||
      config$iter_warmup != 2000L || config$iter_sampling != 6000L
  ) {
    stop("The total-intake Mundlak exact-LOO preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_mundlak_exact_preflight <- function(
