read_update_2026_total_mundlak_exact_corrections <- function(manifest) {
  if (
    !is.data.frame(manifest) || nrow(manifest) != 2L ||
      any(!file.exists(manifest$correction_path))
  ) {
    stop("The total-intake Mundlak correction manifest is invalid.",
         call. = FALSE)
  }

  corrections <- purrr::map(manifest$correction_path, qs::qread)
  corrections <- corrections[order(purrr::map_int(corrections, "case_id"))]
  if (
    !identical(unname(purrr::map_int(corrections, "case_id")), 1:2) ||
      any(!purrr::map_lgl(corrections, ~ inherits(.x$loo, "loo")))
  ) {
    stop("The total-intake Mundlak exact corrections are invalid.",
         call. = FALSE)
  }

  corrections
}

make_update_2026_total_mundlak_final_loo_audit <- function(
    integrated_manifest,
    exact_corrections,
    exact_audit
) {
  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (!isTRUE(exact_audit$all_exact_refit_diagnostics_pass)) {
    stop("Final total-intake Mundlak LOO requires passing exact refits.",
         call. = FALSE)
  }
  final <- apply_sensitivity_full_exact_loo_corrections_from_files(
    integrated_manifest = integrated_manifest,
    exact_results = exact_corrections,
    family = "total_mundlak",
    expected_models = 72L,
    expected_indices = retained
  )
  outcome_summary <- final$model_summary |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_unresolved_high_k =
        sum(n_pareto_k_gt_threshold > 0L),
      unresolved_high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_remaining_pareto_k = max(maximum_pareto_k, na.rm = TRUE),
      .by = outcome
    )

  correction_counts <- exact_audit$diagnostic_summary |>
    dplyr::count(outcome, model_index, name = "exact_corrections")
  final_manifest <- integrated_manifest |>
    dplyr::left_join(
      correction_counts,
      by = c("outcome", "model_index")
    ) |>
    dplyr::mutate(
      exact_corrections = tidyr::replace_na(exact_corrections, 0L),
      final_method = dplyr::if_else(
        exact_corrections > 0L,
        "integrated_observation_level_psis_plus_exact",
        "integrated_observation_level_psis"
      )
    )

  if (
    !isTRUE(final$stacking_ready) || nrow(final$model_summary) != 72L ||
      nrow(outcome_summary) != 4L || any(outcome_summary$models != 18L) ||
      any(outcome_summary$unresolved_high_k_cases != 0L) ||
      nrow(final_manifest) != 72L ||
      sum(final_manifest$exact_corrections) != 2L
  ) {
    stop("The final total-intake Mundlak LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  final$family <- "total_mundlak"
  final$outcome_summary <- outcome_summary
  final$final_loo_manifest <- final_manifest
  final$exact_refits <- 2L
  final$all_exact_refit_diagnostics_pass <- TRUE
  final
}

write_update_2026_total_mundlak_final_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak", "loo_final"
    )
) {
  if (
    !isTRUE(audit$stacking_ready) ||
      nrow(audit$model_summary) != 72L ||
      nrow(audit$outcome_summary) != 4L ||
      nrow(audit$exact_refit_summary) != 2L ||
      nrow(audit$final_loo_manifest) != 72L
  ) {
    stop("Cannot write an incomplete final total-intake Mundlak LOO audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    final_loo_manifest = file.path(output_dir, "final_loo_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    exact_refit_summary = file.path(output_dir, "exact_refit_summary.csv")
  )
  readr::write_csv(audit$final_loo_manifest, paths[["final_loo_manifest"]])
  readr::write_csv(audit$model_summary, paths[["model_summary"]])
  readr::write_csv(audit$outcome_summary, paths[["outcome_summary"]])
  readr::write_csv(
    audit$exact_refit_summary,
    paths[["exact_refit_summary"]]
  )
  unname(paths)
}

write_update_2026_total_mundlak_stacking_weights <- function(
    weights,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak", "stacking_weights.csv"
    )
) {
  outcome_sums <- tapply(weights$weight, weights$outcome, sum)
  if (
    nrow(weights) != 72L ||
      anyDuplicated(paste(weights$outcome, weights$model_index)) ||
      length(outcome_sums) != 4L ||
      any(abs(outcome_sums - 1) > 1e-8)
  ) {
    stop("The total-intake Mundlak stacking weights are invalid.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(weights, output_file, na = "")
  output_file
}

make_update_2026_total_mundlak_prediction_records <- function(
    accepted_fit_manifest,
    stacking_weights,
    n_draws = 4000L,
    exposure_minimum_g_day = 50,
    grid_step_g_day = 1,
    seed = 107988L
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  required_fit <- c(
    "outcome", "model_index", "model_name", "fit_path", "sha256"
  )
  required_weight <- c("outcome", "model_index", "model_name", "weight")
  n_draws <- as.integer(n_draws)

  if (
    !all(required_fit %in% names(accepted_fit_manifest)) ||
      !all(required_weight %in% names(stacking_weights)) ||
      nrow(accepted_fit_manifest) != 72L ||
      nrow(stacking_weights) != 72L || n_draws < 1L ||
      !is.finite(exposure_minimum_g_day) ||
      !is.finite(grid_step_g_day) || grid_step_g_day <= 0
  ) {
    stop("The total-intake Mundlak reporting inputs are invalid.",
         call. = FALSE)
  }

  joined <- stacking_weights |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(dplyr::all_of(required_fit)) |>
        dplyr::rename(fit_sha256 = sha256),
      by = c("outcome", "model_index", "model_name"),
      relationship = "one-to-one"
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)

  if (
    anyNA(joined$fit_path) || any(!file.exists(joined$fit_path)) ||
      anyDuplicated(joined[c("outcome", "model_index")]) ||
      !setequal(unique(joined$outcome), outcomes) ||
      any(!is.finite(joined$weight)) || any(joined$weight < 0)
  ) {
    stop("The total-intake Mundlak fit and weight registries do not match.",
         call. = FALSE)
  }

  outcome_seed <- stats::setNames(
    seed + seq_along(outcomes) * 10000L,
    outcomes
  )
  allocated <- joined |>
    dplyr::group_by(outcome) |>
    dplyr::group_modify(function(table, key) {
      if (nrow(table) != 18L || abs(sum(table$weight) - 1) > 1e-8) {
        stop("A total-intake Mundlak prediction ensemble is invalid.",
             call. = FALSE)
      }
      table$draw_count <- allocate_primary_mixture_models(
        table$weight / sum(table$weight),
        n_draws
      )
      table
    }) |>
    dplyr::ungroup() |>
    dplyr::mutate(
      family = "total_mundlak",
      prediction_type = "total_mundlak",
      prediction_seed = as.integer(
        outcome_seed[outcome] + as.integer(model_index)
      ),
      n_draws = n_draws,
      exposure_minimum_g_day = exposure_minimum_g_day,
      grid_step_g_day = grid_step_g_day
    )

  allocation_audit <- allocated |>
    dplyr::summarise(
      allocated_draws = sum(draw_count),
      selected_models = sum(draw_count > 0L),
      .by = outcome
    )

  if (
    nrow(allocation_audit) != 4L ||
      any(allocation_audit$allocated_draws != n_draws) ||
      any(allocation_audit$selected_models < 1L)
  ) {
    stop("The total-intake Mundlak prediction allocation is incomplete.",
         call. = FALSE)
  }

  allocated <- dplyr::filter(allocated, draw_count > 0L)
  purrr::map(seq_len(nrow(allocated)), function(row) {
    purrr::map(as.list(allocated[row, , drop = FALSE]), unname)
  })
}

make_update_2026_total_mundlak_prediction_grid <- function(
    fitted_candidate,
    data,
    exposure_minimum_g_day = 50,
    grid_step_g_day = 1,
    study_mean_g_day = NULL
) {
  required <- c(
    "protein_intake_raw", "resistance_exercise_code",
    "absolute_exposure_reference_g_day", "absolute_exposure_unit_g_day"
  )

  if (
    !is.list(fitted_candidate) ||
      !inherits(fitted_candidate$model, "brmsfit") ||
      !all(required %in% names(data)) || !nrow(data)
  ) {
    stop("The total-intake Mundlak prediction data are invalid.",
         call. = FALSE)
  }

  reference <- unique(data$absolute_exposure_reference_g_day)
  unit <- unique(data$absolute_exposure_unit_g_day)
  exposure_maximum_g_day <- max(data$protein_intake_raw, na.rm = TRUE)
  if (is.null(study_mean_g_day)) study_mean_g_day <- reference
  if (
    length(reference) != 1L || !is.finite(reference) ||
      length(unit) != 1L || !is.finite(unit) || unit <= 0 ||
      length(study_mean_g_day) != 1L || !is.finite(study_mean_g_day) ||
      !is.finite(exposure_minimum_g_day) ||
      exposure_minimum_g_day >= exposure_maximum_g_day ||
      !is.finite(grid_step_g_day) || grid_step_g_day <= 0
  ) {
    stop("The total-intake Mundlak prediction-grid limits are invalid.",
         call. = FALSE)
  }

  exposure_values <- sort(unique(c(
    round(seq(
      exposure_minimum_g_day,
      exposure_maximum_g_day,
      by = grid_step_g_day
    ), 10),
    reference
  )))

  keys <- tidyr::crossing(
    resistance_exercise_code = c(0, 1),
    protein_intake = exposure_values
  )
  template_data <- fitted_candidate$model$data
  grouping_variables <- intersect(
    c("study_no", "arm_no", "outcome_no", "study_factor"),
    names(template_data)
  )
  complete <- stats::complete.cases(
    template_data[, grouping_variables, drop = FALSE]
  )

  if (!any(complete)) {
    stop("No complete fitted row is available for the prediction grid.",
         call. = FALSE)
  }
  newdata <- template_data[
    rep(which(complete)[[1L]], nrow(keys)),
    ,
    drop = FALSE
  ]
  newdata$resistance_exercise_code <- keys$resistance_exercise_code
  newdata$protein_intake_raw <- keys$protein_intake
  newdata$total_g_day <- keys$protein_intake
  internal_exposure <- (keys$protein_intake - reference) / unit
  newdata$protein_intake <- internal_exposure
  exercise_label <- ifelse(keys$resistance_exercise_code == 0, "yes", "no")

  if ("resistance_exercise_yes_no" %in% names(newdata)) {
    newdata$resistance_exercise_yes_no <- exercise_label
  }
  if ("resistance_exercise_factor" %in% names(newdata)) {
    newdata$resistance_exercise_factor <- factor(
      exercise_label,
      levels = levels(template_data$resistance_exercise_factor)
    )
  }

  if ("age_centre" %in% names(newdata)) newdata$age_centre <- 0
  if ("duration_centre" %in% names(newdata)) newdata$duration_centre <- 0
  if ("vi" %in% names(newdata)) newdata$vi <- 0
  moderator_data <- add_primary_standardised_moderators(data)
  moderator_centres <- attr(moderator_data, "moderator_centres")
  moderator_scales <- attr(moderator_data, "moderator_scales")
  newdata$age_outcome_z <-
    (0 - moderator_centres[["age_centre"]]) /
      moderator_scales[["age_centre"]]
  newdata$duration_outcome_z <-
    (0 - moderator_centres[["duration_centre"]]) /
      moderator_scales[["duration_centre"]]
  newdata$body_mass_outcome_z <- 0

  if (!is.null(fitted_candidate$basis_spec)) {
    within_names <- fitted_candidate$within_names
    between_names <- fitted_candidate$between_names
    if (
      length(within_names) != fitted_candidate$basis_spec$basis_dimension ||
        length(between_names) != fitted_candidate$basis_spec$basis_dimension
    ) {
      stop("The fitted total-intake Mundlak basis registry is invalid.",
           call. = FALSE)
    }
    varied <- predict_sensitivity_basis(
      fitted_candidate$basis_spec,
      internal_exposure
    )
    held <- predict_sensitivity_basis(
      fitted_candidate$basis_spec,
      (study_mean_g_day - reference) / unit
    )
    held <- matrix(
      held,
      nrow = nrow(varied),
      ncol = ncol(varied),
      byrow = TRUE
    )
    for (index in seq_len(ncol(varied))) {
      newdata[[within_names[[index]]]] <- varied[, index] - held[, index]
      newdata[[between_names[[index]]]] <- held[, index]
    }
  }

  list(
    newdata = newdata,
    keys = tibble::tibble(
      resistance_exercise_code = keys$resistance_exercise_code,
      resistance_exercise_label = "Resistance Exercise?",
      resistance_exercise = ifelse(
        keys$resistance_exercise_code == 0,
        "YES",
        "NO"
      ),
      protein_intake = keys$protein_intake,
      protein_intake_g_day = keys$protein_intake
    ),
    reference_g_day = reference,
    study_mean_g_day = study_mean_g_day,
    unit_g_day = unit,
    protein_min = exposure_minimum_g_day,
    protein_max = max(exposure_values),
    grid_step = grid_step_g_day
  )
}

make_update_2026_total_mundlak_reporting_preflight <- function(
    records,
    data_by_outcome
) {
  checks <- purrr::map_dfr(records, function(record) {
    data <- data_by_outcome[[record$outcome]]
    maximum <- if (is.data.frame(data)) {
      max(data$protein_intake_raw, na.rm = TRUE)
    } else {
      NA_real_
    }
    reference <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_reference_g_day)
    } else {
      NA_real_
    }
    unit <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_unit_g_day)
    } else {
      NA_real_
    }
    tibble::tibble(
      outcome = as.character(record$outcome),
      model_index = as.integer(record$model_index),
      model_name = as.character(record$model_name),
      weight = as.numeric(record$weight),
      allocated_draws = as.integer(record$draw_count),
      exposure_minimum_g_day = as.numeric(record$exposure_minimum_g_day),
      exposure_maximum_g_day = maximum,
      reference_g_day = reference,
      study_mean_g_day = reference,
      internal_unit_g_day = unit,
      grid_step_g_day = as.numeric(record$grid_step_g_day),
      fit_path = as.character(record$fit_path),
      fit_exists = file.exists(record$fit_path),
      valid = record$draw_count > 0L && file.exists(record$fit_path) &&
        nchar(record$fit_sha256) == 64L &&
        is.finite(maximum) && maximum > record$exposure_minimum_g_day &&
        length(reference) == 1L && is.finite(reference) &&
        length(unit) == 1L && is.finite(unit) && unit > 0
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  audit <- checks |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      allocated_draws = sum(allocated_draws),
      retained_weight = sum(weight),
      .by = outcome
    )

  if (
    nrow(audit) != 4L || any(audit$selected_models < 1L) ||
      any(audit$allocated_draws != 4000L) ||
      any(audit$retained_weight <= 0) ||
      any(audit$retained_weight > 1 + 1e-8) ||
      anyDuplicated(checks[c("outcome", "model_index")]) ||
      !all(checks$valid)
  ) {
    stop("The total-intake Mundlak reporting preflight failed.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_mundlak_reporting_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak", "reporting", "input_preflight.csv"
    )
) {
  if (
    !all(checks$valid) ||
      any(tapply(checks$allocated_draws, checks$outcome, sum) != 4000L)
  ) {
    stop("Cannot write an invalid total-intake Mundlak reporting preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

update_2026_total_mundlak_reporting_path <- function(
    outcome,
    stage,
    model_index = NULL
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure", "total_g_day",
    "mundlak", "reporting", stage, outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  filename <- if (is.null(model_index)) {
    paste0(stage, ".qs")
  } else {
    sprintf("model_%02d_%s.qs", as.integer(model_index), stage)
  }
  file.path(directory, filename)
}

write_update_2026_total_mundlak_prediction_draw_file <- function(
    record,
    data_by_outcome,
    result_path
) {
  if (
    !file.exists(record$fit_path) || record$draw_count < 1L ||
      !identical(as.character(record$family), "total_mundlak")
  ) {
    stop("A total-intake Mundlak prediction record is invalid.",
         call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  candidate_model_name <- if (stringr::str_ends(
    candidate$model_name,
    stringr::fixed(" [total_mundlak]")
  )) {
    candidate$model_name
  } else {
    paste0(candidate$model_name, " [total_mundlak]")
  }

  if (
    !identical(unname(as.character(candidate$family)), "total_mundlak") ||
      !identical(
        unname(as.character(candidate$outcome)),
        as.character(record$outcome)
      ) ||
      as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(candidate_model_name, as.character(record$model_name))
  ) {
    stop("A total-intake Mundlak fit does not match its prediction record.",
         call. = FALSE)
  }

  grid <- make_update_2026_total_mundlak_prediction_grid(
    fitted_candidate = candidate,
    data = data_by_outcome[[record$outcome]],
    exposure_minimum_g_day = record$exposure_minimum_g_day,
    grid_step_g_day = record$grid_step_g_day
  )
  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  set.seed(as.integer(record$prediction_seed))
  draws <- as.matrix(brms::posterior_epred(
    candidate$model,
    newdata = grid$newdata,
    re_formula = NA,
    ndraws = as.integer(record$draw_count)
  ))

  if (ncol(draws) != nrow(grid$keys) && nrow(draws) == nrow(grid$keys)) {
    draws <- t(draws)
  }
  if (
    nrow(draws) != as.integer(record$draw_count) ||
      ncol(draws) != nrow(grid$keys) || anyNA(draws)
  ) {
    stop("Total-intake Mundlak predictions do not match their allocation.",
         call. = FALSE)
  }

  reduction <- list(
    family = "total_mundlak",
    outcome = as.character(record$outcome),
    model_index = as.integer(record$model_index),
    model_name = as.character(record$model_name),
    weight = as.numeric(record$weight),
    draw_count = as.integer(record$draw_count),
    prediction_seed = as.integer(record$prediction_seed),
    fit_sha256 = as.character(record$fit_sha256),
    grid = grid$keys,
    draws = draws,
    settings = list(
      protein_min = grid$protein_min,
      protein_max = grid$protein_max,
      grid_step = grid$grid_step,
      reference_intake = grid$reference_g_day,
      study_mean_g_day = grid$study_mean_g_day,
      internal_unit_g_day = grid$unit_g_day,
      prediction_type = "total_mundlak"
    )
  )

  write_atomic_qs(reduction, result_path)
}

make_update_2026_total_mundlak_model_average_records <- function(
    prediction_manifest,
    stacking_weights,
    n_draws = 4000L,
    seed = 108988L
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  purrr::map(seq_along(outcomes), function(index) {
    current_outcome <- outcomes[[index]]
    files <- dplyr::filter(
      prediction_manifest,
      outcome == current_outcome
    )
    weights <- stacking_weights |>
      dplyr::filter(outcome == current_outcome) |>
      dplyr::arrange(model_index)
    if (
      nrow(files) < 1L || sum(files$draw_count) != n_draws ||
        nrow(weights) != 18L || abs(sum(weights$weight) - 1) > 1e-8 ||
        any(!file.exists(files$prediction_path))
    ) {
      stop("A total-intake Mundlak model-average record is invalid.",
           call. = FALSE)
    }
    list(
      family = "total_mundlak",
      outcome = current_outcome,
      prediction_manifest = files,
      stacking_weights = weights,
      n_draws = as.integer(n_draws),
      averaging_seed = as.integer(seed + index)
    )
  })
}

write_update_2026_total_mundlak_reporting_file <- function(
    model_average_path,
    data_by_outcome,
    reference_intake = 78.785,
    sesoi = 0.10,
    result_path
) {
  model_average <- read_sensitivity_full_model_average_file(
    model_average_path,
    family = "total_mundlak"
  )
  outcome <- model_average$outcome
  data <- data_by_outcome[[outcome]]
  absolute <- summarise_primary_dose_response(model_average)
  supported <- build_sensitivity_mundlak_reporting_pilot(
    absolute,
    model_average,
    data,
    reference_intake
  )
  heatmap <- compute_primary_heatmap_contrasts(
    model_average = model_average,
    data = data,
    protein_min = 50,
    sesoi = sesoi
  )
  report <- list(
    family = "total_mundlak",
    outcome = outcome,
    dose_response = supported$absolute_full_grid,
    dose_response_increments = supported$increments_full_grid,
    exposure_support_by_group = supported$support_by_group,
    common_exposure_support = supported$common_support,
    pairwise_contrasts = heatmap$contrasts,
    pairwise_support = heatmap$support,
    local_equivalence = summarise_primary_local_equivalence(
      heatmap$contrasts,
      outcome = outcome
    ),
    model_weights = tibble::tibble(
      model_name = names(model_average$model_weights),
      weight = as.numeric(model_average$model_weights)
    ),
    settings = utils::modifyList(
      model_average$settings,
      list(
        reference_intake = reference_intake,
        sesoi = sesoi,
        exposure = "total_g_day",
        exposure_unit = "g/day",
        mundlak_between_profile = "study mean held at reference intake"
      )
    )
  )

  write_atomic_qs(report, result_path)
}

write_update_2026_total_mundlak_reporting_audit <- function(
    audit,
    prediction_manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak", "reporting"
    )
) {
  if (
    !identical(audit$family, "total_mundlak") ||
      !isTRUE(audit$all_reporting_checks_pass) ||
      nrow(audit$summary) != 4L ||
      sum(prediction_manifest$draw_count) != 16000L
  ) {
    stop("The total-intake Mundlak reporting audit is incomplete.",
         call. = FALSE)
  }

  reports <- purrr::map(
    audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "total_mundlak"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(
      report$model_weights,
      outcome = report$outcome,
      .before = 1L
    )
  })
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    prediction_manifest = file.path(output_dir, "prediction_manifest.csv"),
    dose_response = file.path(output_dir, "dose_response.csv"),
    dose_response_increments = file.path(
      output_dir, "dose_response_increments.csv"
    ),
    exposure_support_by_group = file.path(
      output_dir, "exposure_support_by_group.csv"
    ),
    common_exposure_support = file.path(
      output_dir, "common_exposure_support.csv"
    ),
    pairwise_contrasts = file.path(output_dir, "pairwise_contrasts.csv.gz"),
    pairwise_support = file.path(output_dir, "pairwise_support.csv"),
    local_equivalence = file.path(output_dir, "local_equivalence.csv"),
    model_weights = file.path(output_dir, "model_weights.csv")
  )

  readr::write_csv(audit$summary, paths[["summary"]])
  readr::write_csv(prediction_manifest, paths[["prediction_manifest"]])
  readr::write_csv(bind_report("dose_response"), paths[["dose_response"]])
  readr::write_csv(
    bind_report("dose_response_increments"),
    paths[["dose_response_increments"]]
  )
  readr::write_csv(
    bind_report("exposure_support_by_group"),
    paths[["exposure_support_by_group"]]
  )
  readr::write_csv(
    bind_report("common_exposure_support"),
    paths[["common_exposure_support"]]
  )
  readr::write_csv(
    bind_report("pairwise_contrasts"),
    paths[["pairwise_contrasts"]]
  )
  readr::write_csv(
    bind_report("pairwise_support"),
    paths[["pairwise_support"]]
  )
  readr::write_csv(
    bind_report("local_equivalence"),
    paths[["local_equivalence"]]
  )
  readr::write_csv(model_weights, paths[["model_weights"]])
  unname(paths)
}

make_update_2026_total_mundlak_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    data_by_outcome,
    specifications,
    accepted_fit_manifest,
    diagnostic_audit,
    integrated_loo_audit,
    exact_diagnostic_audit,
    exact_correction_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::mutate(
      model_name = dplyr::if_else(
        stringr::str_ends(
          model_name,
          stringr::fixed(" [total_mundlak]")
        ),
        model_name,
        paste0(model_name, " [total_mundlak]")
      )
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)

  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  specification_keys <- registry_keys(specification_table)
  diagnostic_keys <- registry_keys(diagnostic_audit$diagnostic_summary)
  fit_keys <- registry_keys(accepted_fit_manifest)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, fit_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- specification_table |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      diagnostic_audit$diagnostic_summary |>
        dplyr::select(outcome, model_index, diagnostic_name = model),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  weight_sums <- stacking_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    )
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )
  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "total_mundlak"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  correction_manifest <- exact_correction_audit$correction_manifest
  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      "all four common-sample total-intake datasets are valid",
      "all five final registries contain the same 72 model keys",
      "model names agree across specifications fits diagnostics LOO and weights",
      "all 72 accepted fit files exist and have checksums",
      "all accepted-fit sampling diagnostics pass",
      "initial LOO contains 72 aligned models and two high-k cases",
      "both exact-refit sampling diagnostics pass",
      "both compact exact corrections exist and have checksums",
      "final LOO contains 72 models and no unresolved high-k cases",
      "four stacking vectors contain 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      "all four total-intake Mundlak reporting audits pass"
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      identical(names(data_by_outcome), outcomes) &&
        all(vapply(data_by_outcome, nrow, integer(1L)) > 0L) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0) &&
        all(is.finite(analysis_data$mean_body_mass_kg)) &&
        all(analysis_data$absolute_exposure_reference_g_day == 78.785) &&
        all(analysis_data$absolute_exposure_unit_g_day == 50),
      common_registry && length(specification_keys) == 72L,
      nrow(name_alignment) == 72L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(
          name_alignment$diagnostic_name ==
            name_alignment$specification_name
        ) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(accepted_fit_manifest) == 72L &&
        all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(accepted_fit_manifest$bytes > 0) &&
        all(nchar(accepted_fit_manifest$sha256) == 64L),
      identical(diagnostic_audit$family, "total_mundlak") &&
        diagnostic_audit$models == 72L &&
        isTRUE(diagnostic_audit$all_sampling_diagnostics_pass) &&
        all(diagnostic_audit$diagnostic_summary$diagnostic_pass),
      identical(integrated_loo_audit$family, "total_mundlak") &&
        integrated_loo_audit$models == 72L &&
        sum(
          stringr::str_starts(
            integrated_loo_audit$model_summary$method,
            "integrated_"
          )
        ) == 72L &&
        integrated_loo_audit$exact_refits_required == 2L &&
        nrow(integrated_loo_audit$high_k_cases) == 2L &&
        all(
          integrated_loo_audit$outcome_summary$observation_sets_aligned
        ),
      exact_diagnostic_audit$exact_refits == 2L &&
        exact_diagnostic_audit$exact_refits_passing == 2L &&
        isTRUE(
          exact_diagnostic_audit$all_exact_refit_diagnostics_pass
        ),
      nrow(correction_manifest) == 2L &&
        all(file.exists(correction_manifest$correction_path)) &&
        all(correction_manifest$bytes > 0) &&
        all(nchar(correction_manifest$sha256) == 64L),
      identical(final_loo_audit$family, "total_mundlak") &&
        nrow(final_loo_audit$model_summary) == 72L &&
        final_loo_audit$exact_refits == 2L &&
        isTRUE(final_loo_audit$stacking_ready) &&
        all(
          final_loo_audit$outcome_summary$unresolved_high_k_cases == 0L
        ),
      nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        sum(prediction_sums$selected_models) == 23L &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      identical(reporting_audit$family, "total_mundlak") &&
        isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Updated total-intake Mundlak verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    preparation_outcome_counts = preparation_audit$outcome_counts,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    absolute_exposure_provenance = absolute_audit$exposure_provenance,
    absolute_support_by_outcome = absolute_audit$support_by_outcome,
    absolute_scaling_plan = absolute_audit$scaling_plan,
    absolute_model_registry = absolute_audit$model_registry,
    absolute_family_plan = absolute_audit$family_plan,
    analysis_data = analysis_data,
    model_specifications = specification_table,
    model_name_alignment = name_alignment,
    accepted_fit_manifest = accepted_fit_manifest,
    sampling_diagnostic_summary = diagnostic_audit$diagnostic_summary,
    sampling_parameter_failures = diagnostic_audit$parameter_failures,
    initial_integrated_loo_model_summary =
      integrated_loo_audit$model_summary,
    initial_integrated_loo_outcome_summary =
      integrated_loo_audit$outcome_summary,
    initial_high_pareto_k_cases = integrated_loo_audit$high_k_cases,
    observation_set_audit = integrated_loo_audit$observation_set_audit,
    exact_refit_diagnostic_summary =
      exact_diagnostic_audit$diagnostic_summary,
    exact_correction_manifest = correction_manifest,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    exact_refit_summary = final_loo_audit$exact_refit_summary,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    c(
      "Final total-intake Mundlak checkpoint checks.",
      "Paths, sizes, and SHA-256 hashes for source data.",
      "Combined-data preparation invariants.",
      "Analysis counts by primary outcome.",
      "Shared absolute-exposure construction invariants.",
      "Eligible contrast counts for absolute exposure scales.",
      "Provenance of selected reported or derived exposures.",
      "Observed absolute-exposure support by outcome.",
      "Frozen references, units, and grid rules.",
      "Retained 18-model absolute-exposure registry.",
      "Planned primary and sensitivity absolute-exposure families.",
      "Common-sample rows used by total-intake Mundlak models.",
      "Final 72-model total-intake Mundlak specification registry.",
      "Cross-stage model-name identity audit.",
      "Accepted fit lineage with file checksums.",
      "Final model-level sampling diagnostics.",
      "Parameter-level diagnostic failures.",
      "Initial integrated PSIS-LOO summaries by model.",
      "Initial integrated PSIS-LOO summaries by outcome.",
      "The two observations selected for exact refitting.",
      "Observation-set alignment across each outcome.",
      "Diagnostics for both exact-deletion refits.",
      "Compact exact-correction paths and checksums.",
      "Final exact-corrected LOO lineage.",
      "Final LOO summary for all 72 models.",
      "Final high-k resolution by outcome.",
      "Exact-refit correction summary.",
      "Final exact-corrected stacking weights.",
      "Allocation of 4,000 prediction draws per outcome.",
      "Reporting file dimensions and checksums.",
      "Model-averaged total-intake Mundlak dose-response curves.",
      "Changes from the 78.785 g/day reference.",
      "Observed exposure support by resistance-training group.",
      "Exposure support common to resistance-training groups.",
      "Pairwise total-intake contrasts and probabilities.",
      "Observed support for pairwise contrasts.",
      "Practical-equivalence summaries in grams per day."
    ),
    names(artifacts)
  )

  list(
    checks = checks,
    artifacts = artifacts,
    descriptions = descriptions,
    next_family = paste(
      "The total-intake Mundlak family is frozen after this verification",
      "checkpoint; its lean-pruning plan can then be audited."
    )
  )
}

make_update_2026_total_mundlak_pruning_plan <- function(
    accepted_fit_manifest,
    exact_diagnostic_audit,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "total_mundlak_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (any(!file.exists(verification_files))) {
    stop("The total-intake Mundlak verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  verification_index <- readr::read_csv(
    verification_manifest,
    show_col_types = FALSE
  )

  if (length(verification_files) != nrow(verification_index) + 2L) {
    stop("The total-intake Mundlak verification-file count is invalid.",
         call. = FALSE)
  }

  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the total-intake Mundlak archive.",
         call. = FALSE)
  }

  fit_roots <- file.path(archive_root, c("initial", "remedy_1"))
  exact_fit_root <- file.path(archive_root, "loo", "exact_fit")
  if (any(!dir.exists(c(fit_roots, exact_fit_root)))) {
    stop("An expected total-intake Mundlak fit directory is missing.",
         call. = FALSE)
  }

  fit_paths <- unlist(
    purrr::map(
      fit_roots,
      ~ list.files(
        .x,
        pattern = "\\.qs$",
        recursive = TRUE,
        full.names = TRUE
      )
    ),
    use.names = FALSE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)

  accepted_paths <- normalizePath(
    accepted_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  if (
    length(fit_paths) != 76L || length(accepted_paths) != 72L ||
      anyDuplicated(fit_paths) || anyDuplicated(accepted_paths) ||
      !all(accepted_paths %in% fit_paths) ||
      sum(!fit_paths %in% accepted_paths) != 4L
  ) {
    stop("Total-intake Mundlak fit retention does not match its lineage.",
         call. = FALSE)
  }

  model_fit_manifest <- tibble::tibble(
    path = fit_paths,
    relative_path = substring(fit_paths, nchar(resolved_root) + 2L),
    archive_stage = dplyr::case_when(
      grepl("/initial/", fit_paths, fixed = TRUE) ~ "initial",
      grepl("/remedy_1/", fit_paths, fixed = TRUE) ~ "remedy_1",
      TRUE ~ "unknown"
    ),
    outcome = basename(dirname(fit_paths)),
    model_index = as.integer(sub(
      "^model_([0-9]+)\\.qs$", "\\1", basename(fit_paths)
    )),
    accepted_fit = fit_paths %in% accepted_paths,
    bytes = as.numeric(file.info(fit_paths)$size),
    lean_action = "delete frozen total-intake Mundlak model fit"
  ) |>
    dplyr::arrange(archive_stage, outcome, model_index)

  stage_counts <- table(factor(
    model_fit_manifest$archive_stage,
    levels = c("initial", "remedy_1")
  ))
  if (
    any(model_fit_manifest$archive_stage == "unknown") ||
      anyNA(model_fit_manifest$model_index) ||
      !identical(as.integer(stage_counts), c(72L, 4L)) ||
      sum(model_fit_manifest$accepted_fit) != 72L ||
      sum(!model_fit_manifest$accepted_fit) != 4L ||
      any(model_fit_manifest$bytes <= 0)
  ) {
    stop("The total-intake Mundlak model-fit stages are not as expected.",
         call. = FALSE)
  }

  exact_fit_paths <- list.files(
    exact_fit_root,
    pattern = "\\.qs$",
    recursive = TRUE,
    full.names = TRUE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)
  exact_match <- stringr::str_match(
    basename(exact_fit_paths),
    "^model_([0-9]+)_case_([0-9]+)_observation_([0-9]+)\\.qs$"
  )
  exact_refit_manifest <- tibble::tibble(
    path = exact_fit_paths,
    relative_path = substring(
      exact_fit_paths,
      nchar(resolved_root) + 2L
    ),
    archive_stage = "exact_refit",
    outcome = basename(dirname(exact_fit_paths)),
    model_index = as.integer(exact_match[, 2L]),
    case_id = as.integer(exact_match[, 3L]),
    observation = as.integer(exact_match[, 4L]),
    bytes = as.numeric(file.info(exact_fit_paths)$size),
    lean_action = "delete frozen exact-deletion refit"
  ) |>
    dplyr::arrange(case_id)

  exact_keys <- paste(
    exact_refit_manifest$outcome,
    exact_refit_manifest$model_index,
    exact_refit_manifest$observation,
    sep = "::"
  )
  diagnostic_keys <- paste(
    exact_diagnostic_audit$diagnostic_summary$outcome,
    exact_diagnostic_audit$diagnostic_summary$model_index,
    exact_diagnostic_audit$diagnostic_summary$observation,
    sep = "::"
  )

  if (
    nrow(exact_refit_manifest) != 2L ||
      anyNA(exact_refit_manifest[c("model_index", "case_id", "observation")]) ||
      !identical(exact_refit_manifest$case_id, 1:2) ||
      any(exact_refit_manifest$bytes <= 0) ||
      !setequal(exact_keys, diagnostic_keys) ||
      !isTRUE(exact_diagnostic_audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("The total-intake Mundlak exact-refit inventory is invalid.",
         call. = FALSE)
  }

  deletion_manifest <- dplyr::bind_rows(
    model_fit_manifest |>
      dplyr::mutate(
        artifact_role = dplyr::if_else(
          accepted_fit,
          "accepted_model_fit",
          "superseded_model_fit"
        ),
        case_id = NA_integer_,
        observation = NA_integer_
      ),
    exact_refit_manifest |>
      dplyr::mutate(
        accepted_fit = FALSE,
        artifact_role = "exact_refit"
      )
  ) |>
    dplyr::select(
      path, relative_path, archive_stage, artifact_role, outcome,
      model_index, case_id, observation, accepted_fit, bytes, lean_action
    )

  compact_roots <- c(
    loo_psis = file.path(archive_root, "loo", "integrated"),
    exact_corrections = file.path(archive_root, "loo", "exact_correction"),
    reporting = file.path(archive_root, "reporting")
  )
  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact total-intake Mundlak directory is missing.",
         call. = FALSE)
  }

  compact_paths <- unlist(
    purrr::map(
      compact_roots,
      ~ list.files(
        .x,
        recursive = TRUE,
        full.names = TRUE,
        all.files = TRUE
      )
    ),
    use.names = FALSE
  )

  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  component <- vapply(compact_paths, function(path) {
    matches <- names(compact_roots)[vapply(
      normalizePath(compact_roots, winslash = "/", mustWork = TRUE),
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact total-intake Mundlak result"
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo_psis", "exact_corrections", "reporting")
  ))
  if (
    nrow(compact_manifest) != 105L ||
      !identical(as.integer(compact_counts), c(72L, 2L, 31L)) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact total-intake Mundlak archive is incomplete.",
         call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    full_fit_archives_deleted = nrow(deletion_manifest),
    accepted_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "accepted_model_fit"
    ),
    superseded_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "superseded_model_fit"
    ),
    exact_refit_archives_deleted = sum(
      deletion_manifest$artifact_role == "exact_refit"
    ),
    full_fit_archives_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained =
      sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, corrected LOO, and all 72 weights remain frozen;",
      "restoring model or exact-refit objects requires refitting the",
      "total-intake Mundlak family."
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_fit_manifest,
    exact_refit_manifest = exact_refit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_total_mundlak_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "mundlak", "pruning"
    )
) {
  if (
    nrow(plan$model_fit_manifest) != 76L ||
      nrow(plan$exact_refit_manifest) != 2L ||
      nrow(plan$deletion_file_manifest) != 78L ||
      nrow(plan$compact_archive_manifest) != 105L
  ) {
    stop("Cannot write an invalid total-intake Mundlak pruning plan.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    exact_refit_manifest = file.path(output_dir, "exact_refit_manifest.csv"),
    deletion_file_manifest = file.path(
      output_dir, "deletion_file_manifest.csv"
    ),
    compact_archive_manifest = file.path(
      output_dir, "compact_archive_manifest.csv"
    )
  )

  readr::write_csv(plan$summary, paths[["summary"]])
  readr::write_csv(plan$model_fit_manifest, paths[["model_fit_manifest"]])
  readr::write_csv(plan$exact_refit_manifest, paths[["exact_refit_manifest"]])
  readr::write_csv(
    plan$deletion_file_manifest,
    paths[["deletion_file_manifest"]]
  )
  readr::write_csv(
    plan$compact_archive_manifest,
    paths[["compact_archive_manifest"]]
  )
  unname(paths)
}

# Strict within-study comparisons for total intake ----

# Construct the same-study arm contrasts using the total-intake model sample
# and carry its dose scale forward for reporting.
make_update_2026_total_within_contrast_data_by_outcome <- function(
    total_mundlak_data_by_outcome
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  if (!identical(names(total_mundlak_data_by_outcome), outcomes)) {
    stop("The total-intake within-study source registry is invalid.",
         call. = FALSE)
  }

  contrasts <- purrr::map(
    total_mundlak_data_by_outcome,
    function(data) {
      required <- c(
        "study_no", "arm_no_extracted", "mean_body_mass_kg",
        "absolute_exposure_reference_g_day", "absolute_exposure_unit_g_day"
      )
      if (!all(required %in% names(data))) {
        stop("A total-intake within-study source is incomplete.",
             call. = FALSE)
      }
      arm_mass <- data |>
        dplyr::distinct(
          study_no,
          arm_no_extracted,
          mean_body_mass_kg
        )
      if (
        anyDuplicated(arm_mass[c("study_no", "arm_no_extracted")]) ||
          any(!is.finite(arm_mass$mean_body_mass_kg))
      ) {
        stop("Total-intake within-study arm body mass is ambiguous.",
             call. = FALSE)
      }
      reference <- unique(data$absolute_exposure_reference_g_day)
      unit <- unique(data$absolute_exposure_unit_g_day)
      output <- make_strict_within_study_contrasts(data) |>
        dplyr::left_join(
          arm_mass |>
            dplyr::rename(
              protein_arm_no_extracted = arm_no_extracted,
              protein_arm_body_mass_kg = mean_body_mass_kg
            ),
          by = c("study_no", "protein_arm_no_extracted"),
          relationship = "many-to-one"
        ) |>
        dplyr::left_join(
          arm_mass |>
            dplyr::rename(
              comparator_arm_no_extracted = arm_no_extracted,
              comparator_arm_body_mass_kg = mean_body_mass_kg
            ),
          by = c("study_no", "comparator_arm_no_extracted"),
          relationship = "many-to-one"
        ) |>
        dplyr::mutate(
          mean_body_mass_kg =
            (protein_arm_body_mass_kg + comparator_arm_body_mass_kg) / 2,
          absolute_exposure_reference_g_day = reference,
          absolute_exposure_unit_g_day = unit
        ) |>
        dplyr::select(
          -protein_arm_body_mass_kg,
          -comparator_arm_body_mass_kg
        )
      if (
        length(reference) != 1L || reference != 78.785 ||
          length(unit) != 1L || unit != 50 ||
          any(!is.finite(output$mean_body_mass_kg))
      ) {
        stop("A total-intake within-study contrast scale is invalid.",
             call. = FALSE)
      }
      output
    }
  )

  if (
    !identical(vapply(contrasts, nrow, integer(1L)), c(
      whole_body = 145L,
      hypertrophy = 250L,
      strength = 379L,
      `function` = 133L
    ))
  ) {
    stop("The total-intake within-study contrast counts have changed.",
         call. = FALSE)
  }

  contrasts
}

make_update_2026_total_within_specifications <- function(
    total_primary_specifications
) {
  specifications <- dplyr::bind_rows(total_primary_specifications)
  historical_longer_keys <- c(
    "hypertrophy::9", "strength::9", "strength::12", "strength::23"
  )
  specifications <- specifications |>
    dplyr::mutate(
      key = paste(outcome, model_index, sep = "::"),
      family = "total_within",
      exposure = "total_g_day",
      historical_schedule = dplyr::if_else(
        key %in% historical_longer_keys,
        "longer_sampling",
        "base"
      ),
      historical_relative_within_remedy = key %in%
        c("strength::12", "strength::23"),
      adapt_delta = dplyr::if_else(
        key %in% c("hypertrophy::9", "strength::9"),
        pmax(as.numeric(adapt_delta), 0.999),
        as.numeric(adapt_delta)
      ),
      max_treedepth = dplyr::if_else(
        key %in% c("hypertrophy::9", "strength::9"),
        pmax(as.integer(max_treedepth), 15L),
        as.integer(max_treedepth)
      ),
      iter_warmup = dplyr::if_else(
        historical_schedule == "longer_sampling",
        2000L,
        1500L
      ),
      iter_sampling = dplyr::if_else(
        historical_schedule == "longer_sampling",
        4000L,
        2000L
      ),
      chains = 4L,
      parallel_chains = 4L,
      strict_within_study = TRUE,
      model_name = paste0(model_name, " [total_within]")
    ) |>
    dplyr::select(-key)

  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  counts <- table(factor(
    specifications$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  schedule_counts <- table(factor(
    specifications$historical_schedule,
    levels = c("base", "longer_sampling")
  ))
  keys <- paste(specifications$outcome, specifications$model_index, sep = "::")

  if (
    nrow(specifications) != 72L || anyDuplicated(keys) ||
      !identical(as.integer(counts), rep(18L, 4L)) ||
      !all(specifications$model_index %in% retained) ||
      !identical(as.integer(schedule_counts), c(68L, 4L)) ||
      any(specifications$chains != 4L) ||
      any(specifications$parallel_chains != 4L) ||
      !all(stringr::str_ends(
        specifications$model_name,
        stringr::fixed(" [total_within]")
      ))
  ) {
    stop("The total-intake within-study specification registry is invalid.",
         call. = FALSE)
  }

  output <- purrr::pmap(specifications, list)
  names(output) <- paste0(
    specifications$outcome,
    "_model_",
    stringr::str_pad(specifications$model_index, 2L, pad = "0")
  )
  output
}

update_2026_total_within_local_config <- function(specification, config) {
  local_config <- config
  local_config$iter_warmup <- as.integer(specification$iter_warmup)
  local_config$iter_sampling <- as.integer(specification$iter_sampling)
  local_config$adapt_delta_floor <- max(
    as.numeric(config$adapt_delta_floor),
    as.numeric(specification$adapt_delta)
  )
  local_config$max_treedepth_floor <- max(
    as.integer(config$max_treedepth_floor),
    as.integer(specification$max_treedepth)
  )
  outcome_offset <- match(specification$outcome, config$outcomes)

  if (is.na(outcome_offset)) {
    stop("Unknown outcome in the total-intake within-study configuration.",
         call. = FALSE)
  }
  local_config$seed <- as.integer(
    config$seed + 100L * (outcome_offset - 1L) +
      as.integer(specification$model_index)
  )
  local_config
}

prepare_update_2026_total_within_input <- function(
    specification,
    contrast_data_by_outcome,
    priors_by_outcome,
    config
) {
  data <- contrast_data_by_outcome[[specification$outcome]]
  priors <- priors_by_outcome[[specification$outcome]]

  if (is.null(data) || !nrow(data) || is.null(priors)) {
    stop("Total-intake within-study data or priors are unavailable.",
         call. = FALSE)
  }
  local_config <- update_2026_total_within_local_config(
    specification,
    config
  )
  specification$sensitivity_within_expansion <- TRUE
  specification$sensitivity_within_sampling <- paste0(
    local_config$iter_warmup,
    "_warmup_",
    local_config$iter_sampling,
    "_sampling"
  )

  if (isTRUE(specification$includes_moderators)) {
    data <- add_absolute_primary_body_mass(data)
  }
  input <- prepare_within_contrast_pilot_input(
    data,
    specification,
    priors
  )
  input$family <- "total_within"
  input$specification$family <- "total_within"

  if (isTRUE(specification$includes_moderators)) {
    input$priors <- add_absolute_primary_body_mass_prior(input$priors)
    if (!stringr::str_detect(input$formula, "\\bbody_mass_outcome_z\\b")) {
      updated_formula <- stringr::str_replace(
        input$formula,
        stringr::fixed(" + (1 | arm_no)"),
        " + body_mass_outcome_z + (1 | arm_no)"
      )
      if (identical(updated_formula, input$formula)) {
        stop("Could not add body mass to a total-intake within formula.",
             call. = FALSE)
      }
      input$formula <- updated_formula
    }
  }

  input
}

validate_update_2026_total_within_inputs <- function(
    specifications,
    contrast_data_by_outcome,
    priors_by_outcome,
    config
) {
  checks <- purrr::map_dfr(specifications, function(specification) {
    input <- prepare_update_2026_total_within_input(
      specification,
      contrast_data_by_outcome,
      priors_by_outcome,
      config
    )
    local_config <- update_2026_total_within_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      family = input$family,
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      historical_schedule = specification$historical_schedule,
      includes_moderators = isTRUE(specification$includes_moderators),
      body_mass_in_formula =
        stringr::str_detect(input$formula, "\\bbody_mass_outcome_z\\b"),
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      matched_arm_pairs = dplyr::n_distinct(input$data$arm_no),
      exposure_minimum_g_day = min(c(
        input$data$protein_intake_raw_treatment,
        input$data$protein_intake_raw_comparator
      )),
      exposure_maximum_g_day = max(c(
        input$data$protein_intake_raw_treatment,
        input$data$protein_intake_raw_comparator
      )),
      reference_g_day = unique(
        input$data$absolute_exposure_reference_g_day
      ),
      internal_unit_g_day = unique(
        input$data$absolute_exposure_unit_g_day
      ),
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  schedule_counts <- table(factor(
    checks$historical_schedule,
    levels = c("base", "longer_sampling")
  ))
  outcome_counts <- table(factor(
    checks$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  contrast_counts <- checks |>
    dplyr::summarise(
      distinct_counts = dplyr::n_distinct(contrasts),
      contrasts = dplyr::first(contrasts),
      .by = outcome
    )
  expected_contrasts <- c(
    whole_body = 145L,
    hypertrophy = 250L,
    strength = 379L,
    `function` = 133L
  )

  if (
    nrow(checks) != 72L || anyDuplicated(keys) || !all(checks$valid) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !identical(as.integer(schedule_counts), c(68L, 4L)) ||
      any(contrast_counts$distinct_counts != 1L) ||
      !identical(
        stats::setNames(contrast_counts$contrasts, contrast_counts$outcome)[
          names(expected_contrasts)
        ],
        expected_contrasts
      ) ||
      any(checks$includes_moderators & !checks$body_mass_in_formula) ||
      any(!checks$includes_moderators & checks$body_mass_in_formula) ||
      any(checks$reference_g_day != 78.785) ||
      any(checks$internal_unit_g_day != 50) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The total-intake within-study input preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_within_input_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "within", "input_preflight.csv"
    )
) {
  if (nrow(checks) != 72L || !all(checks$valid)) {
    stop("Cannot write an invalid total-intake within-study preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

fit_update_2026_total_within_candidate_to_file <- function(
    input,
    config,
    enabled,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "within", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop("Total-intake within-study fitting is disabled.", call. = FALSE)
  }
  local_config <- update_2026_total_within_local_config(
    input$specification,
    config
  )
  candidate <- fit_sensitivity_brms_pilot(
    input = input,
    enabled = TRUE,
    config = local_config,
    family = "total_within"
  )
  output_dir <- file.path(output_root, candidate$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d.qs", as.integer(candidate$model_index))
  )
  temporary <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary, force = TRUE), add = TRUE)
  qs::qsave(candidate, temporary, preset = "high")

  if (!file.copy(temporary, output_file, overwrite = TRUE)) {
    stop("Could not finalise a total-intake within-study fit.",
         call. = FALSE)
  }
  unlink(temporary, force = TRUE)
  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

make_update_2026_total_within_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  expected_keys <- c("function::9", "function::21")
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))

  if (
    !identical(diagnostic_audit$family, "total_within") ||
      nrow(failed) != 2L || anyDuplicated(failed$key) ||
      !setequal(failed$key, expected_keys) ||
      any(!failed$geometry_pass) || any(failed$convergence_pass) ||
      any(failed$divergent_transitions != 0L) ||
      any(failed$maximum_treedepth_transitions != 0L)
  ) {
    stop("The total-intake within-study remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(specifications, function(specification) {
    paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    ) %in% expected_keys
  })
  selected <- purrr::map(selected, function(specification) {
    specification$iter_warmup <- 2000L
    specification$iter_sampling <- 4000L
    specification$remedy <- "double_sampling_after_low_ess"
    specification$archive_stage <- "remedy_1"
    specification$remedy_reason <- paste(
      "Sampling geometry passed, but convergence and effective sample-size",
      "thresholds were not met."
    )
    specification
  })

  keys <- purrr::map_chr(
    selected,
    ~ paste(.x$outcome, .x$model_index, sep = "::")
  )
  if (
    length(selected) != 2L || anyDuplicated(keys) ||
      !setequal(keys, expected_keys)
  ) {
    stop("The total-intake within-study remedy specifications are incomplete.",
         call. = FALSE)
  }

  names(selected) <- paste0(
    purrr::map_chr(selected, "outcome"),
    "_model_",
    stringr::str_pad(purrr::map_int(selected, "model_index"), 2L, pad = "0")
  )
  selected
}

validate_update_2026_total_within_remedy_inputs <- function(
    inputs,
    initial_fit_paths,
    config
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    expected_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    local_config <- update_2026_total_within_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      matched_arm_pairs = dplyr::n_distinct(input$data$arm_no),
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      initial_fit_exists =
        length(expected_path) == 1L && file.exists(expected_path),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(model_index)

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  if (
    nrow(checks) != 2L || anyDuplicated(keys) ||
      !setequal(keys, c("function::9", "function::21")) ||
      any(checks$remedy != "double_sampling_after_low_ess") ||
      any(checks$iter_warmup != 2000L) ||
      any(checks$iter_sampling != 4000L) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$initial_fit_exists) || !all(checks$valid)
  ) {
    stop("The total-intake within-study remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_within_remedy_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "within", "remedy_1", "input_preflight.csv"
    )
