make_update_2026_total_within_prediction_grid <- function(
    fitted_candidate,
    data,
    exposure_minimum_g_day = 50,
    grid_step_g_day = 1,
    reference_g_day = NULL
) {
  required <- c(
    "protein_intake_raw_treatment", "protein_intake_raw_comparator",
    "resistance_exercise_code", "absolute_exposure_reference_g_day",
    "absolute_exposure_unit_g_day"
  )

  if (
    !is.list(fitted_candidate) ||
      !inherits(fitted_candidate$model, "brmsfit") ||
      !all(required %in% names(data)) || !nrow(data)
  ) {
    stop("The total-intake within-study prediction data are invalid.",
         call. = FALSE)
  }

  observed_reference <- unique(data$absolute_exposure_reference_g_day)
  unit <- unique(data$absolute_exposure_unit_g_day)
  exposure_maximum <- max(c(
    data$protein_intake_raw_treatment,
    data$protein_intake_raw_comparator
  ), na.rm = TRUE)

  if (is.null(reference_g_day)) reference_g_day <- observed_reference
  if (
    length(observed_reference) != 1L || !is.finite(observed_reference) ||
      length(reference_g_day) != 1L || !is.finite(reference_g_day) ||
      length(unit) != 1L || !is.finite(unit) || unit <= 0 ||
      !is.finite(exposure_minimum_g_day) ||
      exposure_minimum_g_day >= exposure_maximum ||
      !is.finite(grid_step_g_day) || grid_step_g_day <= 0
  ) {
    stop("The total-intake within-study prediction limits are invalid.",
         call. = FALSE)
  }

  exposure_values <- sort(unique(c(
    round(seq(
      exposure_minimum_g_day,
      exposure_maximum,
      by = grid_step_g_day
    ), 10),
    reference_g_day
  )))

  keys <- tidyr::crossing(
    resistance_exercise_code = c(0, 1),
    protein_intake = exposure_values
  )
  template <- fitted_candidate$model$data
  grouping_variables <- intersect(
    c("study_no", "arm_no", "outcome_no", "study_factor"),
    names(template)
  )
  complete <- stats::complete.cases(
    template[, grouping_variables, drop = FALSE]
  )

  if (!any(complete)) {
    stop("No complete fitted row is available for the prediction grid.",
         call. = FALSE)
  }
  newdata <- template[
    rep(which(complete)[[1L]], nrow(keys)),
    ,
    drop = FALSE
  ]
  newdata$resistance_exercise_code <- keys$resistance_exercise_code
  exercise_label <- ifelse(keys$resistance_exercise_code == 0, "yes", "no")

  if ("resistance_exercise_factor" %in% names(newdata)) {
    newdata$resistance_exercise_factor <- factor(
      exercise_label,
      levels = levels(template$resistance_exercise_factor)
    )
  }

  if ("age_centre" %in% names(newdata)) newdata$age_centre <- 0
  if ("duration_centre" %in% names(newdata)) newdata$duration_centre <- 0
  if ("vi" %in% names(newdata)) newdata$vi <- 0
  if ("age_outcome_z" %in% names(newdata)) {
    moderator_data <- add_primary_standardised_moderators(data)
    centres <- attr(moderator_data, "moderator_centres")
    scales <- attr(moderator_data, "moderator_scales")
    newdata$age_outcome_z <-
      (0 - centres[["age_centre"]]) / scales[["age_centre"]]
    newdata$duration_outcome_z <-
      (0 - centres[["duration_centre"]]) /
        scales[["duration_centre"]]
  }

  if ("body_mass_outcome_z" %in% names(newdata)) {
    newdata$body_mass_outcome_z <- 0
  }
  if (!is.null(fitted_candidate$basis_spec)) {
    contrast_names <- fitted_candidate$contrast_names
    if (
      length(contrast_names) !=
        fitted_candidate$basis_spec$basis_dimension
    ) {
      stop("The fitted total-intake within-study basis registry is invalid.",
           call. = FALSE)
    }
    treatment_internal <-
      (keys$protein_intake - observed_reference) / unit
    comparator_internal <-
      (reference_g_day - observed_reference) / unit
    varied <- predict_sensitivity_basis(
      fitted_candidate$basis_spec,
      treatment_internal
    )
    held <- predict_sensitivity_basis(
      fitted_candidate$basis_spec,
      comparator_internal
    )
    held <- matrix(
      held,
      nrow = nrow(varied),
      ncol = ncol(varied),
      byrow = TRUE
    )
    for (index in seq_len(ncol(varied))) {
      newdata[[contrast_names[[index]]]] <-
        varied[, index] - held[, index]
    }
  }

  list(
    newdata = newdata,
    keys = tibble::tibble(
      resistance_exercise_code = keys$resistance_exercise_code,
      resistance_exercise_label = "Resistance Exercise?",
      resistance_exercise = ifelse(
        keys$resistance_exercise_code == 0,
        "YES",
        "NO"
      ),
      protein_intake = keys$protein_intake,
      protein_intake_g_day = keys$protein_intake,
      reference_protein_intake_g_day = reference_g_day
    ),
    reference_g_day = reference_g_day,
    unit_g_day = unit,
    protein_min = exposure_minimum_g_day,
    protein_max = max(exposure_values),
    grid_step = grid_step_g_day
  )
}

make_update_2026_total_within_reporting_preflight <- function(
    records,
    data_by_outcome
) {
  checks <- purrr::map_dfr(records, function(record) {
    data <- data_by_outcome[[record$outcome]]
    maximum <- if (is.data.frame(data)) {
      max(c(
        data$protein_intake_raw_treatment,
        data$protein_intake_raw_comparator
      ), na.rm = TRUE)
    } else {
      NA_real_
    }
    reference <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_reference_g_day)
    } else {
      NA_real_
    }
    unit <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_unit_g_day)
    } else {
      NA_real_
    }
    tibble::tibble(
      outcome = as.character(record$outcome),
      model_index = as.integer(record$model_index),
      model_name = as.character(record$model_name),
      weight = as.numeric(record$weight),
      allocated_draws = as.integer(record$draw_count),
      exposure_minimum_g_day = as.numeric(record$exposure_minimum_g_day),
      exposure_maximum_g_day = maximum,
      reference_g_day = reference,
      internal_unit_g_day = unit,
      grid_step_g_day = as.numeric(record$grid_step_g_day),
      fit_path = as.character(record$fit_path),
      fit_exists = file.exists(record$fit_path),
      valid = record$draw_count > 0L && file.exists(record$fit_path) &&
        nchar(record$fit_sha256) == 64L &&
        is.finite(maximum) && maximum > record$exposure_minimum_g_day &&
        length(reference) == 1L && is.finite(reference) &&
        length(unit) == 1L && is.finite(unit) && unit > 0
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  audit <- checks |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      allocated_draws = sum(allocated_draws),
      retained_weight = sum(weight),
      .by = outcome
    )

  if (
    nrow(audit) != 4L || any(audit$selected_models < 1L) ||
      any(audit$allocated_draws != 4000L) ||
      any(audit$retained_weight <= 0) ||
      any(audit$retained_weight > 1 + 1e-8) ||
      anyDuplicated(checks[c("outcome", "model_index")]) ||
      !all(checks$valid)
  ) {
    stop("The total-intake within-study reporting preflight failed.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_within_reporting_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "within", "reporting", "input_preflight.csv"
    )
) {
  if (
    !all(checks$valid) ||
      any(tapply(checks$allocated_draws, checks$outcome, sum) != 4000L)
  ) {
    stop("Cannot write an invalid total-intake within-study reporting preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

update_2026_total_within_reporting_path <- function(
    outcome,
    stage,
    model_index = NULL
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure", "total_g_day",
    "within", "reporting", stage, outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  filename <- if (is.null(model_index)) {
    paste0(stage, ".qs")
  } else {
    sprintf("model_%02d_%s.qs", as.integer(model_index), stage)
  }
  file.path(directory, filename)
}

write_update_2026_total_within_prediction_draw_file <- function(
    record,
    data_by_outcome,
    result_path
) {
  if (
    length(record$fit_path) != 1L || is.na(record$fit_path) ||
      !file.exists(record$fit_path) || record$draw_count < 1L ||
      !identical(as.character(record$family), "total_within") ||
      !identical(as.character(record$prediction_type), "total_within")
  ) {
    stop("A total-intake within-study prediction record is invalid.",
         call. = FALSE)
  }

  candidate <- read_sensitivity_fit_file(record$fit_path)
  if (
    !identical(unname(as.character(candidate$family)), "total_within") ||
      !identical(
        unname(as.character(candidate$outcome)),
        as.character(record$outcome)
      ) ||
      as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(candidate$model_name, as.character(record$model_name))
  ) {
    stop("A total-intake within-study fit does not match its prediction record.",
         call. = FALSE)
  }

  prediction_data <- data_by_outcome[[record$outcome]]
  if (is.null(prediction_data) || !is.data.frame(prediction_data)) {
    stop("The total-intake within-study prediction data are unavailable.",
         call. = FALSE)
  }
  grid <- make_update_2026_total_within_prediction_grid(
    fitted_candidate = candidate,
    data = prediction_data,
    exposure_minimum_g_day = record$exposure_minimum_g_day,
    grid_step_g_day = record$grid_step_g_day
  )
  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  set.seed(as.integer(record$prediction_seed))
  draws <- as.matrix(brms::posterior_epred(
    candidate$model,
    newdata = grid$newdata,
    re_formula = NA,
    ndraws = as.integer(record$draw_count)
  ))

  if (ncol(draws) != nrow(grid$keys) && nrow(draws) == nrow(grid$keys)) {
    draws <- t(draws)
  }
  if (
    nrow(draws) != as.integer(record$draw_count) ||
      ncol(draws) != nrow(grid$keys) || anyNA(draws)
  ) {
    stop("Total-intake within-study predictions do not match their allocation.",
         call. = FALSE)
  }

  reduction <- list(
    family = "total_within",
    outcome = as.character(record$outcome),
    model_index = as.integer(record$model_index),
    model_name = as.character(record$model_name),
    weight = as.numeric(record$weight),
    draw_count = as.integer(record$draw_count),
    prediction_seed = as.integer(record$prediction_seed),
    fit_sha256 = as.character(record$fit_sha256),
    grid = grid$keys,
    draws = draws,
    settings = list(
      protein_min = grid$protein_min,
      protein_max = grid$protein_max,
      grid_step = grid$grid_step,
      reference_intake = grid$reference_g_day,
      internal_unit_g_day = grid$unit_g_day,
      prediction_type = "total_within"
    )
  )

  write_atomic_qs(reduction, result_path)
}

make_update_2026_total_within_model_average_records <- function(
    prediction_manifest,
    stacking_weights,
    n_draws = 4000L,
    seed = 110988L
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  purrr::map(seq_along(outcomes), function(index) {
    current_outcome <- outcomes[[index]]
    files <- dplyr::filter(
      prediction_manifest,
      outcome == current_outcome
    )
    weights <- stacking_weights |>
      dplyr::filter(outcome == current_outcome) |>
      dplyr::arrange(model_index)
    if (
      nrow(files) < 1L || sum(files$draw_count) != n_draws ||
        nrow(weights) != 18L || abs(sum(weights$weight) - 1) > 1e-8 ||
        any(!file.exists(files$prediction_path))
    ) {
      stop("A total-intake within-study model-average record is invalid.",
           call. = FALSE)
    }
    list(
      family = "total_within",
      outcome = current_outcome,
      prediction_manifest = files,
      stacking_weights = weights,
      n_draws = as.integer(n_draws),
      averaging_seed = as.integer(seed + index)
    )
  })
}

write_update_2026_total_within_reporting_file <- function(
    model_average_path,
    data_by_outcome,
    reference_intake = 78.785,
    sesoi = 0.10,
    result_path
) {
  model_average <- read_sensitivity_full_model_average_file(
    model_average_path,
    family = "total_within"
  )
  outcome <- model_average$outcome
  data <- data_by_outcome[[outcome]]

  if (is.null(data) || !is.data.frame(data)) {
    stop("The total-intake within-study reporting data are unavailable.",
         call. = FALSE)
  }
  absolute <- summarise_primary_dose_response(model_average)
  supported <- build_sensitivity_within_reporting_pilot(
    absolute_summary = absolute,
    model_average = model_average,
    data = data,
    reference_intake = reference_intake
  )
  heatmap <- compute_primary_heatmap_contrasts(
    model_average = model_average,
    data = dplyr::mutate(
      data,
      protein_intake_raw = protein_intake_raw_treatment
    ),
    protein_min = 50,
    sesoi = sesoi
  )

  report <- list(
    family = "total_within",
    outcome = outcome,
    dose_response = supported$absolute_full_grid,
    dose_response_increments = supported$increments_full_grid,
    exposure_support_by_group = supported$support_by_group,
    common_exposure_support = supported$common_support,
    pairwise_contrasts = heatmap$contrasts,
    pairwise_support = heatmap$support,
    local_equivalence = summarise_primary_local_equivalence(
      heatmap$contrasts,
      outcome = outcome
    ),
    model_weights = tibble::tibble(
      model_name = names(model_average$model_weights),
      weight = as.numeric(model_average$model_weights)
    ),
    settings = utils::modifyList(
      model_average$settings,
      list(
        reference_intake = reference_intake,
        sesoi = sesoi,
        exposure = "total_g_day",
        exposure_unit = "g/day",
        within_comparator = "fixed at the 78.785 g/day reference"
      )
    )
  )

  write_atomic_qs(report, result_path)
}

write_update_2026_total_within_reporting_audit <- function(
    audit,
    prediction_manifest,
    family = "total_within",
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "within", "reporting"
    )
) {
  if (
    !identical(audit$family, family) ||
      !isTRUE(audit$all_reporting_checks_pass) ||
      nrow(audit$summary) != 4L ||
      sum(prediction_manifest$draw_count) != 16000L
  ) {
    stop("The total-intake within-study reporting audit is incomplete.",
         call. = FALSE)
  }

  reports <- purrr::map(
    audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = family
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(
      report$model_weights,
      outcome = report$outcome,
      .before = 1L
    )
  })
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    prediction_manifest = file.path(output_dir, "prediction_manifest.csv"),
    dose_response = file.path(output_dir, "dose_response.csv"),
    dose_response_increments = file.path(
      output_dir, "dose_response_increments.csv"
    ),
    exposure_support_by_group = file.path(
      output_dir, "exposure_support_by_group.csv"
    ),
    common_exposure_support = file.path(
      output_dir, "common_exposure_support.csv"
    ),
    pairwise_contrasts = file.path(output_dir, "pairwise_contrasts.csv.gz"),
    pairwise_support = file.path(output_dir, "pairwise_support.csv"),
    local_equivalence = file.path(output_dir, "local_equivalence.csv"),
    model_weights = file.path(output_dir, "model_weights.csv")
  )

  readr::write_csv(audit$summary, paths[["summary"]])
  readr::write_csv(prediction_manifest, paths[["prediction_manifest"]])
  readr::write_csv(bind_report("dose_response"), paths[["dose_response"]])
  readr::write_csv(
    bind_report("dose_response_increments"),
    paths[["dose_response_increments"]]
  )
  readr::write_csv(
    bind_report("exposure_support_by_group"),
    paths[["exposure_support_by_group"]]
  )
  readr::write_csv(
    bind_report("common_exposure_support"),
    paths[["common_exposure_support"]]
  )
  readr::write_csv(
    bind_report("pairwise_contrasts"),
    paths[["pairwise_contrasts"]]
  )
  readr::write_csv(
    bind_report("pairwise_support"),
    paths[["pairwise_support"]]
  )
  readr::write_csv(
    bind_report("local_equivalence"),
    paths[["local_equivalence"]]
  )
  readr::write_csv(model_weights, paths[["model_weights"]])
  unname(paths)
}

make_update_2026_total_within_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    data_by_outcome,
    specifications,
    accepted_fit_manifest,
    diagnostic_audit,
    integrated_loo_audit,
    exact_diagnostic_audit,
    exact_correction_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  analysis_sample_summary <- analysis_data |>
    dplyr::summarise(
      contrasts = dplyr::n(),
      studies = dplyr::n_distinct(study_no),
      matched_arm_pairs = dplyr::n_distinct(interaction(
        study_no, protein_arm_no, comparator_arm_no, drop = TRUE
      )),
      exposure_minimum_g_day = min(c(
        protein_intake_raw_treatment,
        protein_intake_raw_comparator
      )),
      exposure_maximum_g_day = max(c(
        protein_intake_raw_treatment,
        protein_intake_raw_comparator
      )),
      .by = analysis_outcome
    ) |>
    dplyr::arrange(factor(analysis_outcome, levels = outcomes))

  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  specification_keys <- registry_keys(specification_table)
  diagnostic_keys <- registry_keys(diagnostic_audit$diagnostic_summary)
  fit_keys <- registry_keys(accepted_fit_manifest)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, fit_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- specification_table |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      diagnostic_audit$diagnostic_summary |>
        dplyr::select(outcome, model_index, diagnostic_name = model),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  weight_sums <- stacking_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    )
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )
  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "total_within"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  correction_manifest <- exact_correction_audit$correction_manifest
  initial_integrated_model_summary <- integrated_loo_audit$model_summary |>
    dplyr::filter(method == "integrated_observation_level_psis")
  initial_conditional_model_summary <- integrated_loo_audit$model_summary |>
    dplyr::filter(method == "conditional_observation_level_psis")

  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      "all four strict within-study total-intake datasets are valid",
      "all five final registries contain the same 72 model keys",
      "model names agree across specifications fits diagnostics LOO and weights",
      "all 72 accepted fit files exist and have checksums",
      "all accepted-fit sampling diagnostics pass",
      "initial LOO contains 72 aligned models and 45 high-k cases",
      "all 45 exact-refit sampling diagnostics pass",
      "all 45 compact exact corrections exist and have checksums",
      "final LOO contains 72 models and no unresolved high-k cases",
      "four stacking vectors contain 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      "all four total-intake within-study reporting audits pass"
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      identical(names(data_by_outcome), outcomes) &&
        identical(analysis_sample_summary$contrasts, c(145L, 250L, 379L, 133L)) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0) &&
        all(is.finite(analysis_data$mean_body_mass_kg)) &&
        all(analysis_data$absolute_exposure_reference_g_day == 78.785) &&
        all(analysis_data$absolute_exposure_unit_g_day == 50),
      common_registry && length(specification_keys) == 72L,
      nrow(name_alignment) == 72L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(
          name_alignment$diagnostic_name ==
            name_alignment$specification_name
        ) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(accepted_fit_manifest) == 72L &&
        sum(accepted_fit_manifest$stage == "initial") == 70L &&
        sum(accepted_fit_manifest$stage == "remedy_1") == 2L &&
        all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(accepted_fit_manifest$bytes > 0) &&
        all(nchar(accepted_fit_manifest$sha256) == 64L),
      identical(diagnostic_audit$family, "total_within") &&
        diagnostic_audit$models == 72L &&
        isTRUE(diagnostic_audit$all_sampling_diagnostics_pass) &&
        all(diagnostic_audit$diagnostic_summary$diagnostic_pass),
      identical(integrated_loo_audit$family, "total_within") &&
        integrated_loo_audit$models == 72L &&
        nrow(initial_integrated_model_summary) == 72L &&
        nrow(initial_conditional_model_summary) == 72L &&
        integrated_loo_audit$exact_refits_required == 45L &&
        nrow(integrated_loo_audit$high_k_cases) == 45L,
      exact_diagnostic_audit$exact_refits == 45L &&
        exact_diagnostic_audit$exact_refits_passing == 45L &&
        isTRUE(
          exact_diagnostic_audit$all_exact_refit_diagnostics_pass
        ),
      nrow(correction_manifest) == 45L &&
        all(file.exists(correction_manifest$correction_path)) &&
        all(correction_manifest$bytes > 0) &&
        all(nchar(correction_manifest$sha256) == 64L),
      identical(final_loo_audit$family, "total_within") &&
        nrow(final_loo_audit$model_summary) == 72L &&
        final_loo_audit$exact_refits == 45L &&
        isTRUE(final_loo_audit$stacking_ready) &&
        all(
          final_loo_audit$outcome_summary$unresolved_high_k_cases == 0L
        ),
      nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        sum(prediction_sums$selected_models) == 22L &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      identical(reporting_audit$family, "total_within") &&
        isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Updated total-intake within-study verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    preparation_outcome_counts = preparation_audit$outcome_counts,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    absolute_exposure_provenance = absolute_audit$exposure_provenance,
    absolute_support_by_outcome = absolute_audit$support_by_outcome,
    absolute_scaling_plan = absolute_audit$scaling_plan,
    absolute_model_registry = absolute_audit$model_registry,
    absolute_family_plan = absolute_audit$family_plan,
    analysis_data = analysis_data,
    analysis_sample_summary = analysis_sample_summary,
    model_specifications = specification_table,
    model_name_alignment = name_alignment,
    accepted_fit_manifest = accepted_fit_manifest,
    sampling_diagnostic_summary = diagnostic_audit$diagnostic_summary,
    sampling_parameter_failures = diagnostic_audit$parameter_failures,
    initial_integrated_loo_model_summary =
      initial_integrated_model_summary,
    initial_integrated_loo_outcome_summary =
      integrated_loo_audit$outcome_summary,
    initial_high_pareto_k_cases = integrated_loo_audit$high_k_cases,
    exact_refit_diagnostic_summary =
      exact_diagnostic_audit$diagnostic_summary,
    exact_correction_manifest = correction_manifest,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    exact_refit_summary = final_loo_audit$exact_refit_summary,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    c(
      "Final total-intake within-study checkpoint checks.",
      "Paths, sizes, and SHA-256 hashes for source data.",
      "Combined-data preparation invariants.",
      "Analysis counts by primary outcome.",
      "Shared absolute-exposure construction invariants.",
      "Eligible contrast counts for absolute exposure scales.",
      "Provenance of selected reported or derived exposures.",
      "Observed absolute-exposure support by outcome.",
      "Frozen references, units, and grid rules.",
      "Retained 18-model absolute-exposure registry.",
      "Planned primary and sensitivity absolute-exposure families.",
      "Strict matched-arm contrasts used by total-intake within-study models.",
      "Outcome-level strict within-study sample and exposure summary.",
      "Final 72-model total-intake within-study specification registry.",
      "Cross-stage model-name identity audit.",
      "Accepted fit lineage with file checksums.",
      "Final model-level sampling diagnostics.",
      "Parameter-level diagnostic failures.",
      "Initial integrated PSIS-LOO summaries by model.",
      "Initial integrated PSIS-LOO summaries by outcome.",
      "The 45 model-observation cases selected for exact refitting.",
      "Diagnostics for all 45 exact-deletion refits.",
      "Compact exact-correction paths and checksums.",
      "Final exact-corrected LOO lineage.",
      "Final LOO summary for all 72 models.",
      "Final high-k resolution by outcome.",
      "Exact-refit correction summary.",
      "Final exact-corrected stacking weights.",
      "Allocation of 4,000 prediction draws per outcome.",
      "Reporting file dimensions and checksums.",
      "Model-averaged total-intake within-study dose-response contrasts.",
      "Changes from the 78.785 g/day fixed comparator.",
      "Observed treatment and comparator support by training group.",
      "Treatment support common to resistance-training groups.",
      "Pairwise total-intake contrasts and probabilities.",
      "Observed support for pairwise contrasts.",
      "Practical-equivalence summaries in grams per day."
    ),
    names(artifacts)
  )

  list(
    checks = checks,
    artifacts = artifacts,
    descriptions = descriptions,
    next_family = paste(
      "The total-intake within-study family is frozen after this",
      "verification checkpoint; its lean-pruning plan can then be audited."
    )
  )
}

make_update_2026_total_within_pruning_plan <- function(
    accepted_fit_manifest,
    exact_diagnostic_audit,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "within"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "total_within_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (any(!file.exists(verification_files))) {
    stop("The total-intake within-study verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  verification_index <- readr::read_csv(
    verification_manifest,
    show_col_types = FALSE
  )

  if (length(verification_files) != nrow(verification_index) + 2L) {
    stop("The total-intake within-study verification-file count is invalid.",
         call. = FALSE)
  }

  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "within"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the total-intake within-study archive.",
         call. = FALSE)
  }

  fit_roots <- file.path(archive_root, c("initial", "remedy_1"))
  exact_fit_root <- file.path(archive_root, "loo", "exact_fit")
  if (any(!dir.exists(c(fit_roots, exact_fit_root)))) {
    stop("An expected total-intake within-study fit directory is missing.",
         call. = FALSE)
  }

  fit_paths <- unlist(
    purrr::map(
      fit_roots,
      ~ list.files(
        .x,
        pattern = "\\.qs$",
        recursive = TRUE,
        full.names = TRUE
      )
    ),
    use.names = FALSE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)

  accepted_paths <- normalizePath(
    accepted_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  if (
    length(fit_paths) != 74L || length(accepted_paths) != 72L ||
      anyDuplicated(fit_paths) || anyDuplicated(accepted_paths) ||
      !all(accepted_paths %in% fit_paths) ||
      sum(!fit_paths %in% accepted_paths) != 2L
  ) {
    stop("Total-intake within-study fit retention does not match its lineage.",
         call. = FALSE)
  }

  model_fit_manifest <- tibble::tibble(
    path = fit_paths,
    relative_path = substring(fit_paths, nchar(resolved_root) + 2L),
    archive_stage = dplyr::case_when(
      grepl("/initial/", fit_paths, fixed = TRUE) ~ "initial",
      grepl("/remedy_1/", fit_paths, fixed = TRUE) ~ "remedy_1",
      TRUE ~ "unknown"
    ),
    outcome = basename(dirname(fit_paths)),
    model_index = as.integer(sub(
      "^model_([0-9]+)\\.qs$", "\\1", basename(fit_paths)
    )),
    accepted_fit = fit_paths %in% accepted_paths,
    bytes = as.numeric(file.info(fit_paths)$size),
    lean_action = "delete frozen total-intake within-study model fit"
  ) |>
    dplyr::arrange(archive_stage, outcome, model_index)

  stage_counts <- table(factor(
    model_fit_manifest$archive_stage,
    levels = c("initial", "remedy_1")
  ))
  if (
    any(model_fit_manifest$archive_stage == "unknown") ||
      anyNA(model_fit_manifest$model_index) ||
      !identical(as.integer(stage_counts), c(72L, 2L)) ||
      sum(model_fit_manifest$accepted_fit) != 72L ||
      sum(!model_fit_manifest$accepted_fit) != 2L ||
      any(model_fit_manifest$bytes <= 0)
  ) {
    stop("The total-intake within-study model-fit stages are not as expected.",
         call. = FALSE)
  }

  exact_fit_paths <- list.files(
    exact_fit_root,
    pattern = "\\.qs$",
    recursive = TRUE,
    full.names = TRUE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)
  exact_match <- stringr::str_match(
    basename(exact_fit_paths),
    "^model_([0-9]+)_case_([0-9]+)_observation_([0-9]+)\\.qs$"
  )
  exact_refit_manifest <- tibble::tibble(
    path = exact_fit_paths,
    relative_path = substring(
      exact_fit_paths,
      nchar(resolved_root) + 2L
    ),
    archive_stage = "exact_refit",
    outcome = basename(dirname(exact_fit_paths)),
    model_index = as.integer(exact_match[, 2L]),
    case_id = as.integer(exact_match[, 3L]),
    observation = as.integer(exact_match[, 4L]),
    bytes = as.numeric(file.info(exact_fit_paths)$size),
    lean_action = "delete frozen exact-deletion refit"
  ) |>
    dplyr::arrange(case_id)

  exact_keys <- paste(
    exact_refit_manifest$outcome,
    exact_refit_manifest$model_index,
    exact_refit_manifest$observation,
    sep = "::"
  )
  diagnostic_keys <- paste(
    exact_diagnostic_audit$diagnostic_summary$outcome,
    exact_diagnostic_audit$diagnostic_summary$model_index,
    exact_diagnostic_audit$diagnostic_summary$observation,
    sep = "::"
  )

  if (
    nrow(exact_refit_manifest) != 45L ||
      anyNA(exact_refit_manifest[c("model_index", "case_id", "observation")]) ||
      !identical(exact_refit_manifest$case_id, seq_len(45L)) ||
      any(exact_refit_manifest$bytes <= 0) ||
      !setequal(exact_keys, diagnostic_keys) ||
      !isTRUE(exact_diagnostic_audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("The total-intake within-study exact-refit inventory is invalid.",
         call. = FALSE)
  }

  deletion_manifest <- dplyr::bind_rows(
    model_fit_manifest |>
      dplyr::mutate(
        artifact_role = dplyr::if_else(
          accepted_fit,
          "accepted_model_fit",
          "superseded_model_fit"
        ),
        case_id = NA_integer_,
        observation = NA_integer_
      ),
    exact_refit_manifest |>
      dplyr::mutate(
        accepted_fit = FALSE,
        artifact_role = "exact_refit"
      )
  ) |>
    dplyr::select(
      path, relative_path, archive_stage, artifact_role, outcome,
      model_index, case_id, observation, accepted_fit, bytes, lean_action
    )

  compact_roots <- c(
    loo_psis = file.path(archive_root, "loo", "integrated"),
    exact_corrections = file.path(archive_root, "loo", "exact_correction"),
    reporting = file.path(archive_root, "reporting")
  )
  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact total-intake within-study directory is missing.",
         call. = FALSE)
  }

  compact_paths <- unlist(
    purrr::map(
      compact_roots,
      ~ list.files(
        .x,
        recursive = TRUE,
        full.names = TRUE,
        all.files = TRUE
      )
    ),
    use.names = FALSE
  )

  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  component <- vapply(compact_paths, function(path) {
    matches <- names(compact_roots)[vapply(
      normalizePath(compact_roots, winslash = "/", mustWork = TRUE),
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact total-intake within-study result"
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo_psis", "exact_corrections", "reporting")
  ))
  if (
    nrow(compact_manifest) != 147L ||
      !identical(as.integer(compact_counts), c(72L, 45L, 30L)) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact total-intake within-study archive is incomplete.",
         call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    full_fit_archives_deleted = nrow(deletion_manifest),
    accepted_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "accepted_model_fit"
    ),
    superseded_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "superseded_model_fit"
    ),
    exact_refit_archives_deleted = sum(
      deletion_manifest$artifact_role == "exact_refit"
    ),
    full_fit_archives_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained =
      sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, corrected LOO, and all 72 weights remain frozen;",
      "restoring model or exact-refit objects requires refitting the",
      "total-intake within-study family."
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_fit_manifest,
    exact_refit_manifest = exact_refit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_total_within_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "within", "pruning"
    )
) {
  if (
    nrow(plan$model_fit_manifest) != 74L ||
      nrow(plan$exact_refit_manifest) != 45L ||
      nrow(plan$deletion_file_manifest) != 119L ||
      nrow(plan$compact_archive_manifest) != 147L
  ) {
    stop("Cannot write an invalid total-intake within-study pruning plan.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    exact_refit_manifest = file.path(output_dir, "exact_refit_manifest.csv"),
    deletion_file_manifest = file.path(
      output_dir, "deletion_file_manifest.csv"
    ),
    compact_archive_manifest = file.path(
      output_dir, "compact_archive_manifest.csv"
    )
  )

  readr::write_csv(plan$summary, paths[["summary"]])
  readr::write_csv(plan$model_fit_manifest, paths[["model_fit_manifest"]])
  readr::write_csv(plan$exact_refit_manifest, paths[["exact_refit_manifest"]])
  readr::write_csv(
    plan$deletion_file_manifest,
    paths[["deletion_file_manifest"]]
  )
  readr::write_csv(
    plan$compact_archive_manifest,
    paths[["compact_archive_manifest"]]
  )
  unname(paths)
}

# Primary models on prescribed supplement dose ----

# Use the audited supplement exposure with zero as the reference and a 25
# g/day internal unit.
make_update_2026_supplement_primary_data_by_outcome <- function(audit) {
  if (
    !isTRUE(audit$ready_for_review) || any(!audit$checks$passed) ||
      !"supplement_g_day" %in% audit$scaling_plan$exposure
  ) {
    stop("The absolute-exposure audit is not ready for supplement modelling.",
         call. = FALSE)
  }

  scaling <- audit$scaling_plan |>
    dplyr::filter(exposure == "supplement_g_day")
  if (
    nrow(scaling) != 1L || scaling$reference_g_day != 0 ||
      scaling$internal_unit_g_day != 25
  ) {
    stop("The prescribed supplement-dose scale is invalid.", call. = FALSE)
  }

  output <- purrr::map(
    audit$supplement_data_by_outcome,
    function(data) {
      if (!"mean_body_mass_kg" %in% names(data)) {
        body_mass_columns <- c("mean_body_mass_kg.y", "mean_body_mass_kg.x")
        if (!all(body_mass_columns %in% names(data))) {
          stop("The supplement-dose data do not contain body mass.",
               call. = FALSE)
        }
        both_reported <- is.finite(data$mean_body_mass_kg.y) &
          is.finite(data$mean_body_mass_kg.x)
        if (any(
          both_reported &
            abs(data$mean_body_mass_kg.y - data$mean_body_mass_kg.x) > 1e-8
        )) {
          stop("Joined body-mass values disagree.", call. = FALSE)
        }
        data <- data |>
          dplyr::mutate(
            mean_body_mass_kg = dplyr::coalesce(
              mean_body_mass_kg.y,
              mean_body_mass_kg.x
            )
          )
      }
      data |>
        dplyr::mutate(
          protein_intake_g_kg_day = protein_intake_raw,
          protein_intake_raw = supplement_g_day,
          protein_intake =
            (supplement_g_day - scaling$reference_g_day[[1L]]) /
              scaling$internal_unit_g_day[[1L]],
          absolute_exposure_reference_g_day =
            scaling$reference_g_day[[1L]],
          absolute_exposure_unit_g_day =
            scaling$internal_unit_g_day[[1L]]
        ) |>
        droplevels()
    }
  )

  expected_rows <- c(
    whole_body = 240L,
    hypertrophy = 394L,
    strength = 661L,
    `function` = 233L
  )

  if (
    !identical(names(output), names(expected_rows)) ||
      !identical(vapply(output, nrow, integer(1L)), expected_rows) ||
      any(vapply(output, function(data) {
        any(!is.finite(data$protein_intake_raw)) ||
          min(data$protein_intake_raw) != 0 ||
          max(data$protein_intake_raw) <= 0
      }, logical(1L)))
  ) {
    stop("The prescribed supplement-dose datasets are invalid.",
         call. = FALSE)
  }

  output
}

make_update_2026_supplement_primary_specifications <- function(
    primary_specifications,
    model_registry
) {
  specifications <- make_update_2026_total_primary_specifications(
    primary_specifications = primary_specifications,
    model_registry = model_registry
  )
  specifications <- purrr::map(specifications, function(specification) {
    specification$family <- "supplement_primary"
    specification$exposure <- "supplement_g_day"
    specification$model_name <- stringr::str_replace(
      specification$model_name,
      stringr::fixed(" [total g/day]"),
      " [supplement g/day]"
    )
    specification
  })

  table <- dplyr::bind_rows(specifications)
  if (
    length(specifications) != 72L || nrow(table) != 72L ||
      any(table$family != "supplement_primary") ||
      any(table$exposure != "supplement_g_day") ||
      anyDuplicated(table[c("outcome", "model_index")]) ||
      !all(stringr::str_ends(
        table$model_name,
        stringr::fixed(" [supplement g/day]")
      ))
  ) {
    stop("The supplement-dose primary registry failed validation.",
         call. = FALSE)
  }

  specifications
}

prepare_update_2026_supplement_primary_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome
) {
  input <- prepare_update_2026_total_primary_input(
    specification = specification,
    data_by_outcome = data_by_outcome,
    priors_by_outcome = priors_by_outcome
  )
  input$family <- "supplement_primary"
  input
}

validate_update_2026_supplement_primary_inputs <- function(
    specifications,
    data_by_outcome,
    priors_by_outcome,
    audit
) {
  if (!isTRUE(audit$ready_for_review) || any(!audit$checks$passed)) {
    stop("The absolute-exposure audit has not passed.", call. = FALSE)
  }

  checks <- purrr::map_dfr(
    specifications,
    function(specification) {
      input <- prepare_update_2026_supplement_primary_input(
        specification,
        data_by_outcome,
        priors_by_outcome
      )
      brms::make_standata(
        formula = stats::as.formula(input$formula),
        data = input$data,
        prior = input$priors
      )
      tibble::tibble(
        family = input$family,
        outcome = specification$outcome,
        model_index = as.integer(specification$model_index),
        model_name = specification$model_name,
        includes_moderators = specification$includes_moderators,
        targeted_smooth_prior = specification$targeted_smooth_prior,
        sampling_schedule = specification$sampling_schedule,
        contrasts = nrow(input$data),
        studies = dplyr::n_distinct(input$data$study_no),
        arms = dplyr::n_distinct(input$data$arm_no),
        exposure_minimum_g_day = min(input$data$protein_intake_raw),
        exposure_maximum_g_day = max(input$data$protein_intake_raw),
        reference_g_day =
          unique(input$data$absolute_exposure_reference_g_day),
        internal_unit_g_day =
          unique(input$data$absolute_exposure_unit_g_day),
        adapt_delta = specification$adapt_delta,
        max_treedepth = as.integer(specification$max_treedepth),
        iter_warmup = specification$iter_warmup,
        iter_sampling = specification$iter_sampling,
        chains = specification$chains,
        parallel_chains = specification$parallel_chains,
        valid = TRUE
      )
    }
  )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  expected_reference <- audit$scaling_plan$reference_g_day[
    audit$scaling_plan$exposure == "supplement_g_day"
  ]
  if (
    nrow(checks) != 72L || anyDuplicated(keys) || !all(checks$valid) ||
      any(checks$family != "supplement_primary") ||
      any(checks$contrasts <= 0L) || any(checks$studies < 2L) ||
      any(checks$exposure_minimum_g_day != 0) ||
      any(checks$exposure_maximum_g_day <= 0) ||
      any(checks$reference_g_day != expected_reference) ||
      any(checks$internal_unit_g_day != 25) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The supplement-dose primary input preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

