make_update_2026_supplement_primary_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass)

  if (
    !identical(diagnostic_audit$family, "supplement_primary") ||
      nrow(failed) != 1L || failed$outcome[[1L]] != "strength" ||
      failed$model_index[[1L]] != 6L ||
      failed$divergent_transitions[[1L]] != 0L ||
      failed$maximum_treedepth_transitions[[1L]] != 2L ||
      !isTRUE(failed$convergence_pass[[1L]])
  ) {
    stop("The supplement-dose primary remedy no longer matches its audit.",
         call. = FALSE)
  }

  selected <- purrr::keep(
    specifications,
    ~ identical(.x$outcome, "strength") &&
      identical(as.integer(.x$model_index), 6L)
  )
  if (length(selected) != 1L) {
    stop("Could not uniquely select supplement-dose strength model 6.",
         call. = FALSE)
  }

  remedy <- selected[[1L]]
  remedy$max_treedepth <- 15L
  remedy$remedy <- "max_treedepth_15_after_two_transitions"
  remedy$archive_stage <- "remedy_1"
  remedy$remedy_reason <- paste(
    "Two maximum-tree-depth transitions with no divergence, E-BFMI,",
    "R-hat, ESS, or MCSE failure."
  )
  list(strength_model_06 = remedy)
}

validate_update_2026_supplement_primary_remedy_inputs <- function(
    inputs,
    initial_fit_paths
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    expected_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      adapt_delta = specification$adapt_delta,
      max_treedepth = as.integer(specification$max_treedepth),
      iter_warmup = specification$iter_warmup,
      iter_sampling = specification$iter_sampling,
      chains = specification$chains,
      parallel_chains = specification$parallel_chains,
      initial_fit_exists =
        length(expected_path) == 1L && file.exists(expected_path),
      valid = TRUE
    )
  })

  if (
    nrow(checks) != 1L || checks$outcome[[1L]] != "strength" ||
      checks$model_index[[1L]] != 6L ||
      checks$remedy[[1L]] !=
        "max_treedepth_15_after_two_transitions" ||
      checks$contrasts[[1L]] != 636L || checks$studies[[1L]] != 71L ||
      checks$adapt_delta[[1L]] != 0.995 ||
      checks$max_treedepth[[1L]] != 15L ||
      checks$iter_warmup[[1L]] != 2000L ||
      checks$iter_sampling[[1L]] != 6000L ||
      checks$chains[[1L]] != 4L ||
      checks$parallel_chains[[1L]] != 4L ||
      !checks$initial_fit_exists[[1L]] || !checks$valid[[1L]]
  ) {
    stop("The supplement-dose primary remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

