combine_update_2026_supplement_primary_remedy_diagnostics <- function(
    initial_audit,
    remedy_diagnostics
) {
  if (length(remedy_diagnostics) != 1L) {
    stop("Expected one supplement-dose primary remedy diagnostic.",
         call. = FALSE)
  }

  remedy <- remedy_diagnostics[[1L]]
  remedy_summary <- remedy$summary
  if (
    nrow(remedy_summary) != 1L ||
      remedy_summary$outcome[[1L]] != "strength" ||
      remedy_summary$model_index[[1L]] != 6L
  ) {
    stop("The supplement-dose primary remedy diagnostic is invalid.",
         call. = FALSE)
  }

  summary <- initial_audit$diagnostic_summary |>
    dplyr::filter(!(outcome == "strength" & model_index == 6L)) |>
    dplyr::bind_rows(remedy_summary) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    ) |>
    dplyr::mutate(
      ppc_warning = primary_ppc_warning(dplyr::pick(dplyr::everything())),
      status = dplyr::case_when(
        !diagnostic_pass ~ "REQUIRES REMEDIATION",
        ppc_warning ~ "PASS WITH PPC WARNING",
        TRUE ~ "PASS"
      )
    )

  parameter_failures <- initial_audit$parameter_failures |>
    dplyr::filter(!(outcome == "strength" & model_index == 6L)) |>
    dplyr::bind_rows(
      remedy$parameter_failures |>
        dplyr::mutate(
          outcome = "strength",
          model_index = 6L,
          .before = 1L
        )
    )

  outcome_summary <- summary |>
    dplyr::summarise(
      models = dplyr::n(),
      models_passing_sampling = sum(diagnostic_pass),
      models_requiring_remediation = sum(!diagnostic_pass),
      models_with_ppc_warning = sum(ppc_warning),
      minimum_coverage = min(predictive_90_interval_coverage),
      maximum_coverage = max(predictive_90_interval_coverage),
      .by = outcome
    )

  if (
    nrow(summary) != 72L ||
      anyDuplicated(summary[c("outcome", "model_index")]) ||
      nrow(outcome_summary) != 4L
  ) {
    stop("The final supplement-dose primary diagnostic audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = "supplement_primary",
    models = 72L,
    models_passing_sampling = sum(summary$diagnostic_pass),
    models_requiring_remediation = sum(!summary$diagnostic_pass),
    all_sampling_diagnostics_pass = all(summary$diagnostic_pass),
    diagnostic_summary = summary,
    parameter_failures = parameter_failures,
    outcome_summary = outcome_summary
  )
}

make_update_2026_supplement_primary_accepted_fit_manifest <- function(
    initial_manifest,
    remedy_fit_paths,
    final_diagnostic_audit
) {
  remedy_paths <- unname(unlist(remedy_fit_paths, use.names = FALSE))

  if (
    nrow(initial_manifest) != 72L || length(remedy_paths) != 1L ||
      !isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass) ||
      final_diagnostic_audit$models_passing_sampling != 72L ||
      any(!file.exists(remedy_paths)) ||
      any(file.info(remedy_paths)$size <= 0)
  ) {
    stop(
      "Accepted supplement-dose fits require all sampling diagnostics to pass.",
      call. = FALSE
    )
  }

  remedy <- tibble::tibble(
    outcome = basename(dirname(remedy_paths)),
    model_index = as.integer(stringr::str_match(
      basename(remedy_paths), "model_([0-9]+)\\.qs$"
    )[, 2]),
    fit_path = remedy_paths,
    stage = "remedy_1",
    bytes = file.info(remedy_paths)$size,
    sha256 = purrr::map_chr(
      remedy_paths,
      ~ digest::digest(
        file = .x,
        algo = "sha256",
        serialize = FALSE
      )
    )
  ) |>
    dplyr::left_join(
      initial_manifest |>
        dplyr::select(outcome, model_index, model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::select(
      outcome, model_index, model_name, fit_path, stage, bytes, sha256
    )

  accepted <- initial_manifest |>
    dplyr::anti_join(
      remedy |> dplyr::select(outcome, model_index),
      by = c("outcome", "model_index")
    ) |>
    dplyr::bind_rows(remedy) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  if (
    nrow(remedy) != 1L || remedy$outcome[[1L]] != "strength" ||
      remedy$model_index[[1L]] != 6L || nrow(accepted) != 72L ||
      anyDuplicated(accepted[c("outcome", "model_index")]) ||
      any(table(accepted$outcome) != 18L) ||
      sum(accepted$stage == "initial") != 71L ||
      sum(accepted$stage == "remedy_1") != 1L ||
      !all(file.exists(accepted$fit_path)) ||
      any(accepted$bytes <= 0) || any(nchar(accepted$sha256) != 64L)
  ) {
    stop("The accepted supplement-dose fit manifest is invalid.",
         call. = FALSE)
  }

  accepted
}

validate_update_2026_supplement_primary_loo_inputs <- function(
    accepted_fit_manifest,
    final_diagnostic_audit,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  stage_counts <- table(accepted_fit_manifest$stage)
  outcome_counts <- table(accepted_fit_manifest$outcome)
  checks <- tibble::tribble(
    ~check, ~passed,
    "all 72 final supplement-dose sampling diagnostics pass",
    identical(final_diagnostic_audit$family, "supplement_primary") &&
      isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass),
    "accepted registry contains 18 models per outcome",
    length(outcome_counts) == 4L && all(outcome_counts == 18L),
    "accepted registry contains 71 initial and 1 remedy fit",
    identical(unname(stage_counts["initial"]), 71L) &&
      identical(unname(stage_counts["remedy_1"]), 1L),
    "all accepted fit files exist and are nonempty",
    all(file.exists(accepted_fit_manifest$fit_path)) &&
      all(file.info(accepted_fit_manifest$fit_path)$size > 0),
    "all accepted fit hashes are present",
    all(nchar(accepted_fit_manifest$sha256) == 64L)
  )

  ready <-
    nrow(accepted_fit_manifest) == 72L &&
    !anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) &&
    all(checks$passed) && identical(k_threshold, 0.7) &&
    identical(as.integer(cores_per_branch), 1L)
  if (!ready) {
    stop("The supplement-dose primary LOO preflight is incomplete.",
         call. = FALSE)
  }

  list(
    family = "supplement_primary",
    models = 72L,
    k_threshold = k_threshold,
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    ready = TRUE
  )
}

write_update_2026_supplement_primary_loo_preflight <- function(
    preflight,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "primary", "loo_preflight"
    )
) {
  if (
    !isTRUE(preflight$ready) || preflight$models != 72L ||
      !all(preflight$checks$passed)
  ) {
    stop("Cannot write an invalid supplement-dose primary LOO preflight.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    checks = file.path(output_dir, "checks.csv"),
