update_2026_supplement_primary_loo_file_path <- function(
    outcome,
    model_index
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "primary", "loo", "integrated", outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf("model_%02d_integrated_loo.qs", as.integer(model_index))
  )
}

compute_update_2026_supplement_primary_integrated_loo_to_file <- function(
    record,
    enabled,
    cores = 1L,
    k_threshold = 0.7
) {
  retained_indices <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (!isTRUE(enabled)) {
    stop(
      "Supplement-dose primary LOO is disabled. Set ",
      "PROTEIN_UPDATE_2026_SUPPLEMENT_PRIMARY_LOO=run to enable it.",
      call. = FALSE
    )
  }

  if (
    !file.exists(record$fit_path) ||
      !record$model_index %in% retained_indices ||
      !record$outcome %in% c(
        "whole_body", "hypertrophy", "strength", "function"
      )
  ) {
    stop("A supplement-dose primary LOO record is invalid.", call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  if (
    !identical(candidate$outcome, record$outcome) ||
      as.integer(candidate$model_index) != record$model_index
  ) {
    stop("A supplement-dose fit does not match its LOO record.",
         call. = FALSE)
  }

  initial <- compute_primary_candidate_psis_loo(
    fitted_candidate = candidate,
    cores = cores,
    save_psis = FALSE
  )
  integrated <- compute_primary_candidate_integrated_psis_loo(
    fitted_candidate = candidate,
    initial_loo_result = initial,
    k_threshold = k_threshold,
    cores = cores
  )
  integrated$fit_path <- normalizePath(
    record$fit_path, winslash = "/", mustWork = TRUE
  )
  integrated$fit_stage <- record$fit_stage

  output_file <- update_2026_supplement_primary_loo_file_path(
    record$outcome,
    record$model_index
  )
  temporary_file <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary_file, force = TRUE), add = TRUE)
  qs::qsave(integrated, temporary_file, preset = "high")

  if (!file.copy(temporary_file, output_file, overwrite = TRUE)) {
    stop("Could not finalise a supplement-dose primary LOO reduction.",
         call. = FALSE)
  }
  unlink(temporary_file, force = TRUE)
  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

audit_update_2026_supplement_primary_integrated_loo_files <- function(
    paths,
    k_threshold = 0.7
) {
  audit <- audit_update_2026_total_primary_integrated_loo_files(
    paths = paths,
    k_threshold = k_threshold
  )
  audit$family <- "supplement_primary"
  audit
}

# Align the supplement-dose candidates on the body-mass-complete observations
# before comparing their predictive performance.
make_update_2026_supplement_primary_common_sample_specifications <- function(
    specifications,
    integrated_loo_audit
) {
  outcome_summary <- integrated_loo_audit$outcome_summary |>
    dplyr::arrange(outcome)
  expected_counts <- c(
    `function` = "219,233",
    hypertrophy = "391,394",
    strength = "636,661",
    whole_body = "236,240"
  )
  observed_counts <- stats::setNames(
    outcome_summary$observation_counts,
    outcome_summary$outcome
  )
  high_k <- integrated_loo_audit$high_k_cases

  if (
    !identical(integrated_loo_audit$family, "supplement_primary") ||
      nrow(outcome_summary) != 4L ||
      any(outcome_summary$observation_sets_aligned) ||
      !identical(observed_counts[names(expected_counts)], expected_counts) ||
      integrated_loo_audit$exact_refits_required != 4L ||
      nrow(high_k) != 4L || any(high_k$outcome != "whole_body") ||
      any(high_k$observation != 125L)
  ) {
    stop(
      "The supplement common-sample refit no longer matches its LOO audit.",
      call. = FALSE
    )
  }

  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  selected <- purrr::keep(
    specifications,
    function(specification) {
      !isTRUE(specification$includes_moderators) &&
        as.integer(specification$model_index) %in% expected_indices
    }
  )
  selected_table <- dplyr::bind_rows(selected) |>
    dplyr::count(outcome, model_index)

  if (
    length(selected) != 36L || nrow(selected_table) != 36L ||
      any(table(selected_table$outcome) != 9L) ||
      any(selected_table$n != 1L) ||
      !all(purrr::map_lgl(
        split(selected_table$model_index, selected_table$outcome),
        ~ identical(sort(.x), expected_indices)
      ))
  ) {
    stop("The supplement common-sample model set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::map(
    selected,
    function(specification) {
      specification$archive_stage <- "common_sample_1"
      specification$common_sample_reason <- paste(
        "Restrict non-moderator candidates to the body-mass-complete sample",
        "used by moderator candidates so pointwise predictive densities",
        "are comparable for stacking."
      )
      specification
    }
  )

  names(selected) <- purrr::map_chr(
    selected,
    ~ paste0(
      .x$outcome,
      "_model_",
      stringr::str_pad(.x$model_index, 2L, pad = "0")
    )
  )

  selected
}

prepare_update_2026_supplement_primary_common_sample_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome
) {
  if (isTRUE(specification$includes_moderators)) {
    stop("Only non-moderator supplement models require replacement.",
         call. = FALSE)
  }

  outcome <- specification$outcome
  common_data <- data_by_outcome
  common_data[[outcome]] <- common_data[[outcome]] |>
    dplyr::filter(is.finite(mean_body_mass_kg)) |>
    droplevels()
  input <- prepare_update_2026_supplement_primary_input(
    specification = specification,
    data_by_outcome = common_data,
    priors_by_outcome = priors_by_outcome
  )
  input$family <- "supplement_primary_common_sample"
  input
}

validate_update_2026_supplement_primary_common_sample_inputs <- function(
    inputs,
    accepted_fit_manifest,
    integrated_loo_audit
) {
  expected_rows <- c(
    whole_body = 236L,
    hypertrophy = 391L,
    strength = 636L,
    `function` = 219L
  )
  expected_studies <- c(
    whole_body = 68L,
    hypertrophy = 43L,
    strength = 71L,
    `function` = 28L
  )
  references <- purrr::map(
    names(expected_rows),
    function(outcome) {
      integrated_loo_audit$observation_diagnostics |>
        dplyr::filter(outcome == .env$outcome, model_index == 5L) |>
        dplyr::arrange(observation) |>
        dplyr::transmute(
          study_no = as.character(study_no),
          arm_no = as.integer(arm_no),
          outcome_no = as.integer(outcome_no),
          yi = as.numeric(yi),
          vi = as.numeric(vi)
        )
    }
  ) |>
    stats::setNames(names(expected_rows))

  if (!all(purrr::map_int(references, nrow) == expected_rows)) {
    stop("A supplement common-sample reference is invalid.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(
    inputs,
    function(input) {
      specification <- input$specification
      outcome <- specification$outcome
      brms::make_standata(
        formula = stats::as.formula(input$formula),
        data = input$data,
        prior = input$priors
      )
      observed <- input$data |>
        dplyr::transmute(
          study_no = as.character(study_no),
          arm_no = as.integer(arm_no),
          outcome_no = as.integer(outcome_no),
          yi = as.numeric(yi),
          vi = as.numeric(vi)
        )
      superseded_path <- accepted_fit_manifest |>
        dplyr::filter(
          outcome == specification$outcome,
          model_index == specification$model_index
        ) |>
        dplyr::pull(fit_path)
      tibble::tibble(
        outcome = outcome,
        model_index = as.integer(specification$model_index),
        model_name = specification$model_name,
        contrasts = nrow(input$data),
        studies = dplyr::n_distinct(input$data$study_no),
        common_observation_set = isTRUE(all.equal(
          observed,
          references[[outcome]],
          tolerance = 0,
          check.attributes = FALSE
        )),
        adapt_delta = specification$adapt_delta,
        max_treedepth = as.integer(specification$max_treedepth),
        iter_warmup = as.integer(specification$iter_warmup),
        iter_sampling = as.integer(specification$iter_sampling),
        chains = as.integer(specification$chains),
        parallel_chains = as.integer(specification$parallel_chains),
        superseded_fit_exists =
          length(superseded_path) == 1L && file.exists(superseded_path),
        valid = TRUE
      )
    }
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  observed_indices <- split(checks$model_index, checks$outcome)
  if (
    nrow(checks) != 36L ||
      anyDuplicated(checks[c("outcome", "model_index")]) ||
      any(table(checks$outcome) != 9L) ||
      !all(purrr::map_lgl(
        observed_indices,
        ~ identical(sort(.x), expected_indices)
      )) ||
      any(checks$contrasts != expected_rows[checks$outcome]) ||
      any(checks$studies != expected_studies[checks$outcome]) ||
      !all(checks$common_observation_set) ||
      !all(checks$superseded_fit_exists) || !all(checks$valid) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The supplement common-sample preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

