compile_update_2026_supplement_primary_common_sample_diagnostic_audit <-
  function(diagnostics) {
    summary <- dplyr::bind_rows(purrr::map(diagnostics, "summary")) |>
      dplyr::arrange(
        factor(
          outcome,
          levels = c("whole_body", "hypertrophy", "strength", "function")
        ),
        model_index
      ) |>
      dplyr::mutate(
        ppc_warning = primary_ppc_warning(dplyr::pick(dplyr::everything())),
        status = dplyr::case_when(
          !diagnostic_pass ~ "REQUIRES REMEDIATION",
          ppc_warning ~ "PASS WITH PPC WARNING",
          TRUE ~ "PASS"
        )
      )
    expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
    observed_indices <- split(summary$model_index, summary$outcome)
    if (
      length(diagnostics) != 36L || nrow(summary) != 36L ||
        anyDuplicated(summary[c("outcome", "model_index")]) ||
        any(table(summary$outcome) != 9L) ||
        !all(purrr::map_lgl(
          observed_indices,
          ~ identical(sort(.x), expected_indices)
        ))
    ) {
      stop("The supplement common-sample diagnostics are incomplete.",
           call. = FALSE)
    }
    parameter_failures <- purrr::map_dfr(
      diagnostics,
      function(result) {
        result$parameter_failures |>
          dplyr::mutate(
            outcome = result$summary$outcome[[1L]],
            model_index = result$summary$model_index[[1L]],
            .before = 1L
          )
      }
    )
    list(
      family = "supplement_primary_common_sample",
      models = 36L,
      models_passing_sampling = sum(summary$diagnostic_pass),
      models_requiring_remediation = sum(!summary$diagnostic_pass),
      all_sampling_diagnostics_pass = all(summary$diagnostic_pass),
      diagnostic_summary = summary,
      parameter_failures = parameter_failures
    )
  }

write_update_2026_supplement_primary_common_sample_diagnostic_audit <-
  function(
      audit,
      output_dir = here::here(
        "results", "update_2026", "absolute_exposure", "supplement_g_day",
        "primary", "common_sample_1", "diagnostics"
      )
  ) {
    if (audit$models != 36L || nrow(audit$diagnostic_summary) != 36L) {
      stop("Cannot write an incomplete supplement common-sample audit.",
           call. = FALSE)
    }
    dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
    paths <- c(
      diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
      parameter_failures = file.path(output_dir, "parameter_failures.csv")
    )
    readr::write_csv(
      audit$diagnostic_summary,
      paths[["diagnostic_summary"]],
      na = ""
    )
    readr::write_csv(
      audit$parameter_failures,
      paths[["parameter_failures"]],
      na = ""
    )
    unname(paths)
  }

make_update_2026_supplement_primary_common_sample_accepted_fit_manifest <-
  function(
      common_sample_fit_paths,
      specifications,
      diagnostic_audit
  ) {
    paths <- unname(unlist(common_sample_fit_paths, use.names = FALSE))
    specification_table <- dplyr::bind_rows(specifications) |>
      dplyr::select(outcome, model_index, model_name)
    if (
      length(paths) != 36L || any(!file.exists(paths)) ||
        any(file.info(paths)$size <= 0) ||
        !identical(
          diagnostic_audit$family,
          "supplement_primary_common_sample"
        ) ||
        !isTRUE(diagnostic_audit$all_sampling_diagnostics_pass) ||
        diagnostic_audit$models_passing_sampling != 36L
    ) {
      stop("Accepted supplement common-sample fits are incomplete.",
           call. = FALSE)
    }
    manifest <- tibble::tibble(
      outcome = basename(dirname(paths)),
      model_index = as.integer(stringr::str_match(
        basename(paths), "model_([0-9]+)\\.qs$"
      )[, 2]),
      fit_path = normalizePath(paths, winslash = "/", mustWork = TRUE),
      stage = "common_sample_1",
      bytes = file.info(paths)$size,
      sha256 = purrr::map_chr(
        paths,
        ~ digest::digest(
          file = .x,
          algo = "sha256",
          serialize = FALSE
        )
      )
    ) |>
      dplyr::left_join(
        specification_table,
        by = c("outcome", "model_index")
      ) |>
      dplyr::select(
        outcome, model_index, model_name, fit_path, stage, bytes, sha256
      ) |>
      dplyr::arrange(
        factor(
          outcome,
          levels = c("whole_body", "hypertrophy", "strength", "function")
        ),
        model_index
      )
    expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
    observed_indices <- split(manifest$model_index, manifest$outcome)
    if (
      nrow(manifest) != 36L ||
        anyDuplicated(manifest[c("outcome", "model_index")]) ||
        any(table(manifest$outcome) != 9L) ||
        !all(purrr::map_lgl(
          observed_indices,
          ~ identical(sort(.x), expected_indices)
        )) ||
        anyNA(manifest$model_name) ||
        any(manifest$stage != "common_sample_1") ||
        any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
    ) {
      stop("The accepted supplement common-sample manifest is invalid.",
           call. = FALSE)
    }
    manifest
  }

