validate_update_2026_supplement_primary_common_sample_loo_inputs <-
  function(
      accepted_fit_manifest,
      diagnostic_audit,
      common_sample_preflight,
      k_threshold = 0.7,
      cores_per_branch = 1L
  ) {
    outcome_counts <- table(accepted_fit_manifest$outcome)
    expected_rows <- c(
      whole_body = 236L,
      hypertrophy = 391L,
      strength = 636L,
      `function` = 219L
    )
    checks <- tibble::tribble(
      ~check, ~passed,
      "all 36 supplement common-sample diagnostics pass",
      identical(
        diagnostic_audit$family,
        "supplement_primary_common_sample"
      ) && isTRUE(diagnostic_audit$all_sampling_diagnostics_pass),
      "accepted registry contains nine replacements per outcome",
      length(outcome_counts) == 4L && all(outcome_counts == 9L),
      "all 36 replacements use their outcome common observation set",
      nrow(common_sample_preflight) == 36L &&
        all(common_sample_preflight$common_observation_set) &&
        all(
          common_sample_preflight$contrasts ==
            expected_rows[common_sample_preflight$outcome]
        ),
      "all accepted replacement files exist and are nonempty",
      all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(file.info(accepted_fit_manifest$fit_path)$size > 0),
      "all accepted replacement hashes are present",
      all(nchar(accepted_fit_manifest$sha256) == 64L)
    )
    ready <-
      nrow(accepted_fit_manifest) == 36L &&
      !anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) &&
      all(accepted_fit_manifest$stage == "common_sample_1") &&
      all(checks$passed) && identical(k_threshold, 0.7) &&
      identical(as.integer(cores_per_branch), 1L)
    if (!ready) {
      stop("The supplement common-sample LOO preflight is incomplete.",
           call. = FALSE)
    }
    list(
      family = "supplement_primary_common_sample",
      models = 36L,
      k_threshold = k_threshold,
      cores_per_branch = as.integer(cores_per_branch),
      checks = checks,
      accepted_fit_manifest = accepted_fit_manifest,
      ready = TRUE
    )
  }

write_update_2026_supplement_primary_common_sample_loo_preflight <-
  function(
      preflight,
      output_dir = here::here(
        "results", "update_2026", "absolute_exposure", "supplement_g_day",
        "primary", "common_sample_loo_preflight"
      )
  ) {
    if (
      !isTRUE(preflight$ready) || preflight$models != 36L ||
        !all(preflight$checks$passed)
    ) {
      stop("Cannot write an invalid supplement common-sample LOO preflight.",
           call. = FALSE)
    }
    dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
    paths <- c(
      checks = file.path(output_dir, "checks.csv"),
      accepted_fit_manifest = file.path(
        output_dir,
        "accepted_fit_manifest.csv"
      )
    )
    readr::write_csv(preflight$checks, paths[["checks"]], na = "")
    readr::write_csv(
      preflight$accepted_fit_manifest,
      paths[["accepted_fit_manifest"]],
      na = ""
    )
    unname(paths)
  }

make_update_2026_supplement_primary_common_sample_loo_records <- function(
    accepted_fit_manifest
) {
  required <- c("outcome", "model_index", "fit_path", "stage")
  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  if (
    !all(required %in% names(accepted_fit_manifest)) ||
      nrow(accepted_fit_manifest) != 36L ||
      anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) ||
      any(table(accepted_fit_manifest$outcome) != 9L) ||
      !all(purrr::map_lgl(
        split(
          accepted_fit_manifest$model_index,
          accepted_fit_manifest$outcome
        ),
        ~ identical(sort(.x), expected_indices)
      )) ||
      !all(file.exists(accepted_fit_manifest$fit_path))
  ) {
    stop("The supplement common-sample LOO manifest is invalid.",
         call. = FALSE)
  }

  records <- purrr::pmap(
    accepted_fit_manifest[required],
    function(outcome, model_index, fit_path, stage) {
      list(
        outcome = as.character(outcome),
        model_index = as.integer(model_index),
        fit_path = as.character(fit_path),
        fit_stage = as.character(stage)
      )
    }
  )

  names(records) <- paste0(
    accepted_fit_manifest$outcome,
    "_model_",
    stringr::str_pad(accepted_fit_manifest$model_index, 2L, pad = "0")
  )
  records
}

update_2026_supplement_primary_common_sample_loo_file_path <- function(
    outcome,
    model_index
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "primary", "loo", "common_sample_final", outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf("model_%02d_integrated_loo.qs", as.integer(model_index))
  )
}

compute_update_2026_supplement_primary_common_sample_loo_to_file <-
  function(
      record,
      enabled,
      cores = 1L,
      k_threshold = 0.7
  ) {
    expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
    if (!isTRUE(enabled)) {
      stop(
        "Supplement common-sample LOO is disabled. Set ",
        "PROTEIN_UPDATE_2026_SUPPLEMENT_PRIMARY_COMMON_SAMPLE_LOO=run.",
        call. = FALSE
      )
    }
    if (
      !file.exists(record$fit_path) ||
        !record$outcome %in% c(
          "whole_body", "hypertrophy", "strength", "function"
        ) ||
        !record$model_index %in% expected_indices
    ) {
      stop("A supplement common-sample LOO record is invalid.",
           call. = FALSE)
    }
    candidate <- qs::qread(record$fit_path)
    if (
      !identical(candidate$outcome, record$outcome) ||
        as.integer(candidate$model_index) != record$model_index
    ) {
      stop("A supplement common-sample fit does not match its LOO record.",
           call. = FALSE)
    }
    initial <- compute_primary_candidate_psis_loo(
      fitted_candidate = candidate,
      cores = cores,
      save_psis = FALSE
    )
    integrated <- compute_primary_candidate_integrated_psis_loo(
      fitted_candidate = candidate,
      initial_loo_result = initial,
      k_threshold = k_threshold,
      cores = cores
    )
    integrated$fit_path <- normalizePath(
      record$fit_path,
      winslash = "/",
      mustWork = TRUE
    )
    integrated$fit_stage <- record$fit_stage
    output_file <-
      update_2026_supplement_primary_common_sample_loo_file_path(
        record$outcome,
        record$model_index
      )
    temporary_file <- paste0(output_file, ".tmp-", Sys.getpid())
    on.exit(unlink(temporary_file, force = TRUE), add = TRUE)
    qs::qsave(integrated, temporary_file, preset = "high")
    if (!file.copy(temporary_file, output_file, overwrite = TRUE)) {
      stop("Could not finalise a supplement common-sample LOO reduction.",
           call. = FALSE)
    }
    unlink(temporary_file, force = TRUE)
    normalizePath(output_file, winslash = "/", mustWork = TRUE)
  }

audit_update_2026_supplement_primary_common_sample_loo_files <- function(
    paths,
    k_threshold = 0.7
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  if (
    length(paths) != 36L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The supplement common-sample LOO files are incomplete.",
         call. = FALSE)
  }

  results <- purrr::map(paths, qs::qread)
  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  expected_rows <- c(
    whole_body = 236L,
    hypertrophy = 391L,
    strength = 636L,
    `function` = 219L
  )
  keys <- purrr::map_chr(
    results,
    ~ paste(.x$outcome, .x$model_index, sep = "|")
  )
  expected_keys <- as.vector(outer(
    names(expected_rows),
    expected_indices,
    function(outcome, model_index) paste(outcome, model_index, sep = "|")
  ))
  valid <- purrr::map_lgl(results, function(result) {
    inherits(result$loo, "loo") &&
      identical(result$remedy, "integrated_observation_level_psis") &&
      result$outcome %in% names(expected_rows) &&
      result$model_index %in% expected_indices &&
      nrow(result$observation_manifest) == expected_rows[[result$outcome]] &&
      nrow(result$loo$pointwise) == expected_rows[[result$outcome]]
  })

  observation_set_audit <- purrr::map_dfr(results, function(result) {
    manifest <- result$observation_manifest |>
      dplyr::mutate(
        dplyr::across(where(is.factor), as.character),
        study_no = as.character(study_no)
      )
    tibble::tibble(
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      observations = nrow(manifest),
      observation_set_sha256 = digest::digest(manifest, algo = "sha256")
    )
  })

  alignment <- observation_set_audit |>
    dplyr::summarise(
      models = dplyr::n(),
      observations = dplyr::first(observations),
      observation_sets_aligned =
        dplyr::n_distinct(observation_set_sha256) == 1L,
      .by = outcome
    )

  if (
    !all(valid) || anyDuplicated(keys) || !setequal(keys, expected_keys) ||
      nrow(alignment) != 4L || any(alignment$models != 9L) ||
      !all(alignment$observation_sets_aligned)
  ) {
    stop("The supplement common-sample LOO set is invalid.",
         call. = FALSE)
  }

  method_comparison <- purrr::map_dfr(results, "comparison")
  observation_diagnostics <- purrr::map_dfr(
    results,
    "observation_diagnostics"
  )
  model_summary <- method_comparison |>
    dplyr::filter(method == "integrated_observation_level_psis") |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  high_k_cases <- observation_diagnostics |>
    dplyr::filter(integrated_pareto_k > k_threshold) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )

  outcome_summary <- model_summary |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_high_k = sum(n_pareto_k_gt_threshold > 0L),
      high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_pareto_k = max(maximum_pareto_k),
      compute_hours = sum(compute_seconds) / 3600,
      .by = outcome
    ) |>
    dplyr::left_join(alignment, by = c("outcome", "models")) |>
    dplyr::mutate(
      stacking_ready = high_k_cases == 0L & observation_sets_aligned
    )

  reduction_manifest <- purrr::map2_dfr(
    paths,
    results,
    function(path, result) {
      tibble::tibble(
        outcome = result$outcome,
        model_index = as.integer(result$model_index),
        model_name = result$model_name,
        fit_stage = result$fit_stage,
        fit_path = result$fit_path,
        integrated_loo_path = normalizePath(
          path,
          winslash = "/",
          mustWork = TRUE
        ),
        bytes = file.info(path)$size,
        sha256 = digest::digest(
          file = path,
          algo = "sha256",
          serialize = FALSE
        )
      )
    }
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  if (
    nrow(model_summary) != 36L || nrow(method_comparison) != 72L ||
      nrow(observation_set_audit) != 36L ||
      nrow(reduction_manifest) != 36L
  ) {
    stop("The supplement common-sample LOO audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = "supplement_primary_common_sample",
    reduction_manifest = reduction_manifest,
    model_summary = model_summary,
    outcome_summary = outcome_summary,
    method_comparison = method_comparison,
    observation_diagnostics = observation_diagnostics,
    observation_set_audit = observation_set_audit,
    high_k_cases = high_k_cases,
    models = 36L,
    observation_sets_aligned = TRUE,
    exact_refits_required = nrow(high_k_cases),
    stacking_ready = nrow(high_k_cases) == 0L,
    k_threshold = k_threshold
  )
}

