    )
) {
  if (
    nrow(manifest) != 72L || !all(file.exists(manifest$fit_path)) ||
      any(file.info(manifest$fit_path)$size <= 0) ||
      any(nchar(manifest$sha256) != 64L)
  ) {
    stop("Cannot write an invalid final supplement fit manifest.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(manifest, output_file, na = "")
  output_file
}

make_update_2026_supplement_primary_aligned_loo_manifest <- function(
    integrated_loo_audit,
    common_sample_loo_audit,
    final_fit_manifest
) {
  replacement <- common_sample_loo_audit$reduction_manifest
  replacement_keys <- replacement |>
    dplyr::select(outcome, model_index)

  if (
    nrow(integrated_loo_audit$reduction_manifest) != 72L ||
      nrow(replacement) != 36L ||
      !isTRUE(common_sample_loo_audit$observation_sets_aligned) ||
      nrow(final_fit_manifest) != 72L
  ) {
    stop("The aligned supplement LOO inputs are incomplete.",
         call. = FALSE)
  }

  manifest <- integrated_loo_audit$reduction_manifest |>
    dplyr::anti_join(replacement_keys, by = c("outcome", "model_index")) |>
    dplyr::bind_rows(replacement) |>
    dplyr::mutate(
      loo_source = dplyr::if_else(
        fit_stage == "common_sample_1",
        "common_sample_integrated_psis",
        "original_integrated_psis"
      ),
      final_loo_path = integrated_loo_path,
      final_bytes = bytes,
      final_sha256 = sha256
    ) |>
    dplyr::select(
      outcome, model_index, model_name, fit_stage, fit_path, loo_source,
      final_loo_path, final_bytes, final_sha256
    ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  comparison <- manifest |>
    dplyr::select(
      outcome,
      model_index,
      loo_model_name = model_name,
      loo_fit_stage = fit_stage,
      loo_fit_path = fit_path
    ) |>
    dplyr::inner_join(
      final_fit_manifest |>
        dplyr::select(
          outcome,
          model_index,
          fit_model_name = model_name,
          fit_stage = stage,
          fit_path
        ),
      by = c("outcome", "model_index")
    )

  if (
    nrow(manifest) != 72L ||
      anyDuplicated(manifest[c("outcome", "model_index")]) ||
      any(table(manifest$outcome) != 18L) ||
      sum(manifest$loo_source == "common_sample_integrated_psis") != 36L ||
      nrow(comparison) != 72L ||
      any(comparison$loo_model_name != comparison$fit_model_name) ||
      any(comparison$loo_fit_stage != comparison$fit_stage) ||
      any(comparison$loo_fit_path != comparison$fit_path) ||
      any(!file.exists(manifest$final_loo_path)) ||
      any(manifest$final_bytes <= 0) ||
      any(nchar(manifest$final_sha256) != 64L)
  ) {
    stop("The aligned supplement LOO manifest is invalid.", call. = FALSE)
  }

  manifest
}

audit_update_2026_supplement_primary_aligned_loo <- function(
    aligned_loo_manifest,
    k_threshold = 0.7
) {
  audit <- audit_update_2026_supplement_primary_integrated_loo_files(
    paths = aligned_loo_manifest$final_loo_path,
    k_threshold = k_threshold
  )
  key <- c("outcome", "model_index")
  source_check <- audit$reduction_manifest |>
    dplyr::select(dplyr::all_of(key), integrated_loo_path) |>
    dplyr::inner_join(
      aligned_loo_manifest |>
        dplyr::select(
          dplyr::all_of(key),
          final_loo_path,
          loo_source
        ),
      by = key
    )

  if (
    nrow(source_check) != 72L ||
      any(source_check$integrated_loo_path != source_check$final_loo_path) ||
      !all(audit$outcome_summary$observation_sets_aligned)
  ) {
    stop("The aligned supplement LOO audit is invalid.", call. = FALSE)
  }

  audit$family <- "supplement_primary_aligned"
  audit$aligned_loo_manifest <- aligned_loo_manifest
  audit$exact_refits_required <- nrow(audit$high_k_cases)
  audit$stacking_ready <-
    audit$exact_refits_required == 0L &&
    all(audit$outcome_summary$observation_sets_aligned)
  audit
}

