make_update_2026_supplement_primary_final_loo_manifest <- function(
    aligned_loo_audit,
    exact_loo_audit
) {
  if (
    !isTRUE(exact_loo_audit$all_exact_refit_diagnostics_pass) ||
      exact_loo_audit$exact_refits != 2L ||
      nrow(aligned_loo_audit$aligned_loo_manifest) != 72L
  ) {
    stop("Final supplement LOO assembly requires two passing exact refits.",
         call. = FALSE)
  }

  exact <- exact_loo_audit$correction_manifest |>
    dplyr::select(
      outcome,
      model_index,
      observation,
      correction_path,
      correction_bytes = bytes,
      correction_sha256 = sha256
    )

  manifest <- aligned_loo_audit$aligned_loo_manifest |>
    dplyr::rename(
      base_loo_source = loo_source,
      integrated_loo_path = final_loo_path,
      integrated_bytes = final_bytes,
      integrated_sha256 = final_sha256
    ) |>
    dplyr::left_join(exact, by = c("outcome", "model_index")) |>
    dplyr::mutate(
      loo_source = dplyr::if_else(
        is.na(correction_path),
        base_loo_source,
        "integrated_psis_plus_exact"
      ),
      final_loo_path = dplyr::coalesce(
        correction_path,
        integrated_loo_path
      ),
      final_bytes = dplyr::coalesce(
        correction_bytes,
        integrated_bytes
      ),
      final_sha256 = dplyr::coalesce(
        correction_sha256,
        integrated_sha256
      )
    ) |>
    dplyr::select(
      outcome, model_index, model_name, fit_stage, fit_path,
      base_loo_source, loo_source, observation,
      integrated_loo_path, correction_path, final_loo_path,
      final_bytes, final_sha256
    ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  if (
    nrow(manifest) != 72L ||
      sum(manifest$loo_source == "integrated_psis_plus_exact") != 2L ||
      anyDuplicated(manifest[c("outcome", "model_index")]) ||
      any(!file.exists(manifest$final_loo_path)) ||
      any(file.info(manifest$final_loo_path)$size <= 0) ||
      any(nchar(manifest$final_sha256) != 64L)
  ) {
    stop("The final supplement LOO manifest is invalid.", call. = FALSE)
  }

  manifest
}

audit_update_2026_supplement_primary_final_loo <- function(
    final_loo_manifest,
    exact_loo_audit,
    k_threshold = 0.7
) {
  audit <- audit_update_2026_supplement_primary_integrated_loo_files(
    paths = final_loo_manifest$final_loo_path,
    k_threshold = k_threshold
  )

  if (
    nrow(final_loo_manifest) != 72L ||
      !isTRUE(exact_loo_audit$all_exact_refit_diagnostics_pass) ||
      exact_loo_audit$exact_refits != 2L ||
      nrow(audit$high_k_cases) != 0L ||
      audit$exact_refits_required != 0L ||
      !isTRUE(audit$stacking_ready) ||
      !all(audit$outcome_summary$observation_sets_aligned)
  ) {
    stop("The final supplement LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  audit$family <- "supplement_primary"
  audit$final_loo_manifest <- final_loo_manifest
  audit$exact_refit_summary <- exact_loo_audit$diagnostic_summary
  audit$exact_refits <- 2L
  audit$all_exact_refit_diagnostics_pass <- TRUE
  audit
}

write_update_2026_supplement_primary_final_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "primary", "loo_final"
    )
) {
  if (
    !isTRUE(audit$stacking_ready) ||
      nrow(audit$final_loo_manifest) != 72L ||
      nrow(audit$model_summary) != 72L ||
      nrow(audit$outcome_summary) != 4L ||
      nrow(audit$observation_set_audit) != 72L ||
      nrow(audit$exact_refit_summary) != 2L
  ) {
    stop("Cannot write an incomplete final supplement LOO audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    final_loo_manifest = file.path(output_dir, "final_loo_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    method_comparison = file.path(output_dir, "method_comparison.csv"),
    observation_diagnostics = file.path(
      output_dir,
      "observation_diagnostics.csv.gz"
    ),
    observation_set_audit = file.path(
      output_dir,
      "observation_set_audit.csv"
    ),
    exact_refit_summary = file.path(output_dir, "exact_refit_summary.csv"),
    high_k_cases = file.path(output_dir, "high_k_cases.csv")
  )

  readr::write_csv(audit$final_loo_manifest, paths[["final_loo_manifest"]])
  readr::write_csv(audit$model_summary, paths[["model_summary"]])
  readr::write_csv(audit$outcome_summary, paths[["outcome_summary"]])
  readr::write_csv(audit$method_comparison, paths[["method_comparison"]])
  readr::write_csv(
    audit$observation_diagnostics,
    paths[["observation_diagnostics"]]
  )
  readr::write_csv(
    audit$observation_set_audit,
    paths[["observation_set_audit"]]
  )
  readr::write_csv(
    audit$exact_refit_summary,
    paths[["exact_refit_summary"]]
  )
  readr::write_csv(audit$high_k_cases, paths[["high_k_cases"]])
  unname(paths)
}

compute_update_2026_supplement_primary_stacking_weights <- function(
    final_loo_audit
) {
  weights <- compute_update_2026_total_primary_stacking_weights(
    final_loo_audit
  )
  if (
    nrow(weights) != 72L ||
      any(abs(tapply(weights$weight, weights$outcome, sum) - 1) > 1e-8)
  ) {
    stop("The supplement primary stacking weights are invalid.",
         call. = FALSE)
  }
  weights
}

write_update_2026_supplement_primary_stacking_weights <- function(
    weights,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "primary", "stacking_weights.csv"
    )
) {
  outcome_sums <- tapply(weights$weight, weights$outcome, sum)
  if (
    nrow(weights) != 72L || length(outcome_sums) != 4L ||
      any(abs(outcome_sums - 1) > 1e-8)
  ) {
    stop("Cannot write invalid supplement primary stacking weights.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(weights, output_file)
  output_file
}

make_update_2026_supplement_primary_reporting_data_by_outcome <- function(
    data_by_outcome
) {
  expected_rows <- c(
    whole_body = 236L,
    hypertrophy = 391L,
    strength = 636L,
    `function` = 219L
  )
  expected_studies <- c(
    whole_body = 68L,
    hypertrophy = 43L,
    strength = 71L,
    `function` = 28L
  )
  expected_maximum <- c(
    whole_body = 106,
    hypertrophy = 78.4,
    strength = 106,
    `function` = 320 / 7
  )
  reporting <- purrr::imap(data_by_outcome, function(data, outcome) {
    filtered <- data |>
      dplyr::filter(is.finite(mean_body_mass_kg)) |>
      droplevels()
    reference <- unique(filtered$absolute_exposure_reference_g_day)
    unit <- unique(filtered$absolute_exposure_unit_g_day)
    if (
      nrow(filtered) != expected_rows[[outcome]] ||
        dplyr::n_distinct(filtered$study_no) != expected_studies[[outcome]] ||
        length(reference) != 1L || reference != 0 ||
        length(unit) != 1L || unit != 25 ||
        abs(max(filtered$protein_intake_raw) - expected_maximum[[outcome]]) >
          1e-8
    ) {
      stop("A supplement reporting dataset is invalid.", call. = FALSE)
    }
    filtered
  })

  if (!identical(sort(names(reporting)), sort(names(expected_rows)))) {
    stop("The supplement reporting datasets are incomplete.",
         call. = FALSE)
  }
  reporting
}

make_update_2026_supplement_primary_prediction_records <- function(
    accepted_fit_manifest,
    stacking_weights,
    n_draws = 4000L,
    exposure_minimum_g_day = 0,
    grid_step_g_day = 1,
    seed = 115988L
) {
  records <- make_update_2026_total_primary_prediction_records(
    accepted_fit_manifest = accepted_fit_manifest,
    stacking_weights = stacking_weights,
    n_draws = n_draws,
    exposure_minimum_g_day = exposure_minimum_g_day,
    grid_step_g_day = grid_step_g_day,
    seed = seed
  )

  records <- purrr::map(records, function(record) {
    record$family <- "supplement_primary"
    record$prediction_type <- "supplement_g_day"
    record
  })
  allocated <- purrr::map_dfr(records, function(record) {
    tibble::tibble(
      outcome = as.character(record$outcome),
      draw_count = as.integer(record$draw_count)
    )
  }) |>
    dplyr::summarise(draws = sum(draw_count), .by = outcome)

  if (
    length(records) < 4L || nrow(allocated) != 4L ||
      any(allocated$draws != n_draws) ||
      any(!purrr::map_lgl(
        records,
        ~ identical(.x$family, "supplement_primary") &&
          identical(.x$prediction_type, "supplement_g_day")
      ))
  ) {
    stop("The supplement prediction allocation is incomplete.",
         call. = FALSE)
  }

  records
}

make_update_2026_supplement_primary_reporting_preflight <- function(
    records,
    data_by_outcome
) {
  checks <- make_update_2026_total_primary_reporting_preflight(
    records = records,
    data_by_outcome = data_by_outcome
  )
  units <- purrr::map_dbl(
    checks$outcome,
    ~ unique(
      data_by_outcome[[.x]]$absolute_exposure_unit_g_day
    )
  )
  checks <- dplyr::mutate(
    checks,
    internal_unit_g_day = units,
    .after = reference_g_day
  )
  expected_maximum <- c(
    whole_body = 106,
    hypertrophy = 78.4,
    strength = 106,
    `function` = 320 / 7
  )

  if (
    any(checks$exposure_minimum_g_day != 0) ||
      any(abs(
        checks$exposure_maximum_g_day - expected_maximum[checks$outcome]
      ) > 1e-8) ||
      any(checks$reference_g_day != 0) ||
      any(checks$internal_unit_g_day != 25) ||
      any(checks$grid_step_g_day != 1) || !all(checks$valid)
  ) {
    stop("The supplement reporting preflight failed.", call. = FALSE)
  }

  checks
}

write_update_2026_supplement_primary_reporting_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "primary", "reporting", "input_preflight.csv"
    )
) {
  if (
    !all(checks$valid) ||
      any(tapply(checks$allocated_draws, checks$outcome, sum) != 4000L) ||
      any(checks$reference_g_day != 0) ||
      any(checks$internal_unit_g_day != 25)
  ) {
    stop("Cannot write an invalid supplement reporting preflight.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file)
  output_file
}

update_2026_supplement_primary_reporting_path <- function(
    outcome,
    stage,
    model_index = NULL
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "primary", "reporting", stage, outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  filename <- if (is.null(model_index)) {
    paste0(stage, ".qs")
  } else {
    sprintf("model_%02d_%s.qs", as.integer(model_index), stage)
  }
  file.path(directory, filename)
}

write_update_2026_supplement_primary_prediction_draw_file <- function(
    record,
    data_by_outcome,
    result_path
) {
  if (
    !file.exists(record$fit_path) || record$draw_count < 1L ||
      !identical(as.character(record$family), "supplement_primary")
  ) {
    stop("A supplement prediction record is invalid.", call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  if (
    !identical(candidate$outcome, as.character(record$outcome)) ||
      as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(candidate$model_name, as.character(record$model_name))
  ) {
    stop("A supplement fit does not match its prediction record.",
         call. = FALSE)
  }

  grid <- make_update_2026_total_primary_prediction_grid(
    data = data_by_outcome[[record$outcome]],
    fitted_candidate = candidate,
    exposure_minimum_g_day = record$exposure_minimum_g_day,
    grid_step_g_day = record$grid_step_g_day
  )
  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  set.seed(as.integer(record$prediction_seed))
  draws <- as.matrix(brms::posterior_epred(
    candidate$model,
    newdata = grid$newdata,
    re_formula = NA,
    ndraws = as.integer(record$draw_count)
  ))

  if (ncol(draws) != nrow(grid$keys) && nrow(draws) == nrow(grid$keys)) {
    draws <- t(draws)
  }
  if (
    nrow(draws) != as.integer(record$draw_count) ||
      ncol(draws) != nrow(grid$keys) || anyNA(draws)
  ) {
    stop("Supplement predictions do not match their allocation.",
         call. = FALSE)
  }

  reduction <- list(
    family = "supplement_primary",
    outcome = as.character(record$outcome),
    model_index = as.integer(record$model_index),
    model_name = as.character(record$model_name),
    weight = as.numeric(record$weight),
    draw_count = as.integer(record$draw_count),
    prediction_seed = as.integer(record$prediction_seed),
    fit_sha256 = as.character(record$fit_sha256),
    grid = grid$keys,
    draws = draws,
    settings = list(
      protein_min = grid$protein_min,
      protein_max = grid$protein_max,
      grid_step = grid$grid_step,
      reference_intake = grid$reference_g_day,
      internal_unit_g_day = grid$unit_g_day,
      prediction_type = "supplement_primary"
    )
  )

  write_atomic_qs(reduction, result_path)
}

