write_update_2026_supplement_primary_reporting_file <- function(
    model_average_path,
    data_by_outcome,
    reference_intake = 0,
    sesoi = 0.10,
    result_path
) {
  model_average <- read_sensitivity_full_model_average_file(
    model_average_path,
    family = "supplement_primary"
  )
  outcome <- model_average$outcome
  data <- data_by_outcome[[outcome]]

  if (is.null(data) || !is.data.frame(data)) {
    stop("The supplement reporting data are unavailable.", call. = FALSE)
  }
  absolute <- summarise_primary_dose_response(model_average)
  supported <- build_sensitivity_mundlak_reporting_pilot(
    absolute,
    model_average,
    data,
    reference_intake
  )
  heatmap <- compute_primary_heatmap_contrasts(
    model_average = model_average,
    data = data,
    protein_min = 0,
    sesoi = sesoi
  )
  report <- list(
    family = "supplement_primary",
    outcome = outcome,
    dose_response = supported$absolute_full_grid,
    dose_response_increments = supported$increments_full_grid,
    exposure_support_by_group = supported$support_by_group,
    common_exposure_support = supported$common_support,
    pairwise_contrasts = heatmap$contrasts,
    pairwise_support = heatmap$support,
    local_equivalence = summarise_primary_local_equivalence(
      heatmap$contrasts,
      outcome = outcome
    ),
    model_weights = tibble::tibble(
      model_name = names(model_average$model_weights),
      weight = as.numeric(model_average$model_weights)
    ),
    settings = utils::modifyList(
      model_average$settings,
      list(
        reference_intake = reference_intake,
        sesoi = sesoi,
        exposure = "supplement_g_day",
        exposure_unit = "g/day"
      )
    )
  )

  write_atomic_qs(report, result_path)
}

write_update_2026_supplement_primary_reporting_audit <- function(
    audit,
    prediction_manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "primary", "reporting"
    )
) {
  if (
    !identical(audit$family, "supplement_primary") ||
      !isTRUE(audit$all_reporting_checks_pass) ||
      nrow(audit$summary) != 4L ||
      sum(prediction_manifest$draw_count) != 16000L
  ) {
    stop("The supplement reporting audit is incomplete.", call. = FALSE)
  }

  reports <- purrr::map(
    audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "supplement_primary"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(
      report$model_weights,
      outcome = report$outcome,
      .before = 1L
    )
  })
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    prediction_manifest = file.path(output_dir, "prediction_manifest.csv"),
    dose_response = file.path(output_dir, "dose_response.csv"),
    dose_response_increments = file.path(
      output_dir, "dose_response_increments.csv"
    ),
    exposure_support_by_group = file.path(
      output_dir, "exposure_support_by_group.csv"
    ),
    common_exposure_support = file.path(
      output_dir, "common_exposure_support.csv"
    ),
    pairwise_contrasts = file.path(output_dir, "pairwise_contrasts.csv.gz"),
    pairwise_support = file.path(output_dir, "pairwise_support.csv"),
    local_equivalence = file.path(output_dir, "local_equivalence.csv"),
    model_weights = file.path(output_dir, "model_weights.csv")
  )

  readr::write_csv(audit$summary, paths[["summary"]])
  readr::write_csv(prediction_manifest, paths[["prediction_manifest"]])
  readr::write_csv(bind_report("dose_response"), paths[["dose_response"]])
  readr::write_csv(
    bind_report("dose_response_increments"),
    paths[["dose_response_increments"]]
  )
  readr::write_csv(
    bind_report("exposure_support_by_group"),
    paths[["exposure_support_by_group"]]
  )
  readr::write_csv(
    bind_report("common_exposure_support"),
    paths[["common_exposure_support"]]
  )
  readr::write_csv(
    bind_report("pairwise_contrasts"),
    paths[["pairwise_contrasts"]]
  )
  readr::write_csv(
    bind_report("pairwise_support"),
    paths[["pairwise_support"]]
  )
  readr::write_csv(
    bind_report("local_equivalence"),
    paths[["local_equivalence"]]
  )
  readr::write_csv(model_weights, paths[["model_weights"]])
  unname(paths)
}

make_update_2026_supplement_primary_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    data_by_outcome,
    specifications,
    initial_accepted_fit_manifest,
    initial_diagnostic_audit,
    initial_loo_audit,
    common_accepted_fit_manifest,
    common_diagnostic_audit,
    common_loo_audit,
    final_fit_manifest,
    aligned_loo_audit,
    exact_loo_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  common_keys <- paste(
    common_accepted_fit_manifest$outcome,
    common_accepted_fit_manifest$model_index,
    sep = "::"
  )
  initial_diagnostics <- initial_diagnostic_audit$diagnostic_summary |>
    dplyr::filter(
      !paste(outcome, model_index, sep = "::") %in% common_keys
    )
  final_diagnostics <- dplyr::bind_rows(
    initial_diagnostics,
    common_diagnostic_audit$diagnostic_summary
  ) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  final_parameter_failures <- dplyr::bind_rows(
    initial_diagnostic_audit$parameter_failures |>
      dplyr::filter(
        !paste(outcome, model_index, sep = "::") %in% common_keys
      ),
    common_diagnostic_audit$parameter_failures
  )
  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  specification_keys <- registry_keys(specification_table)
  diagnostic_keys <- registry_keys(final_diagnostics)
  fit_keys <- registry_keys(final_fit_manifest)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, fit_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- specification_table |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      final_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_diagnostics |>
        dplyr::select(outcome, model_index, diagnostic_name = model),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  weight_sums <- stacking_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    )
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )
  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "supplement_primary"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  correction_manifest <- exact_loo_audit$correction_manifest

  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      "all four supplement-dose datasets are valid",
      "all five final registries contain the same 72 model keys",
      "model names agree across specifications fits diagnostics LOO and weights",
      "all 72 final fit files exist and have checksums",
      "all final accepted-fit sampling diagnostics pass",
      "initial LOO contains 72 reductions and four high-k cases",
      "36 common-sample replacements pass diagnostics with no high-k cases",
      "aligned LOO contains 72 models and two high-k cases",
      "both exact-refit sampling diagnostics pass",
      "both compact exact corrections exist and have checksums",
      "final LOO contains 72 models and no unresolved high-k cases",
      "four stacking vectors contain 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      "all four supplement-dose reporting audits pass"
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      identical(names(data_by_outcome), outcomes) &&
        all(vapply(data_by_outcome, nrow, integer(1L)) > 0L) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0) &&
        all(is.finite(analysis_data$protein_intake_raw)) &&
        all(analysis_data$absolute_exposure_reference_g_day == 0) &&
        all(analysis_data$absolute_exposure_unit_g_day == 25),
      common_registry && length(specification_keys) == 72L,
      nrow(name_alignment) == 72L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(
          name_alignment$diagnostic_name ==
            name_alignment$specification_name
        ) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(final_fit_manifest) == 72L &&
        all(file.exists(final_fit_manifest$fit_path)) &&
        all(final_fit_manifest$bytes > 0) &&
        all(nchar(final_fit_manifest$sha256) == 64L),
      nrow(final_diagnostics) == 72L &&
        all(final_diagnostics$diagnostic_pass),
      identical(initial_loo_audit$family, "supplement_primary") &&
        nrow(initial_loo_audit$reduction_manifest) == 72L &&
        nrow(initial_loo_audit$model_summary) == 72L &&
        initial_loo_audit$exact_refits_required == 4L &&
        nrow(initial_loo_audit$high_k_cases) == 4L &&
        !any(initial_loo_audit$outcome_summary$observation_sets_aligned),
      nrow(common_accepted_fit_manifest) == 36L &&
        common_diagnostic_audit$models == 36L &&
        isTRUE(common_diagnostic_audit$all_sampling_diagnostics_pass) &&
        common_loo_audit$models == 36L &&
        isTRUE(common_loo_audit$observation_sets_aligned) &&
        common_loo_audit$exact_refits_required == 0L &&
        nrow(common_loo_audit$high_k_cases) == 0L,
      identical(aligned_loo_audit$family, "supplement_primary_aligned") &&
        nrow(aligned_loo_audit$model_summary) == 72L &&
        aligned_loo_audit$exact_refits_required == 2L &&
        nrow(aligned_loo_audit$high_k_cases) == 2L &&
        all(aligned_loo_audit$outcome_summary$observation_sets_aligned),
      exact_loo_audit$exact_refits == 2L &&
        exact_loo_audit$exact_refits_passing == 2L &&
        isTRUE(exact_loo_audit$all_exact_refit_diagnostics_pass),
      nrow(correction_manifest) == 2L &&
        all(file.exists(correction_manifest$correction_path)) &&
        all(correction_manifest$bytes > 0) &&
        all(nchar(correction_manifest$sha256) == 64L),
      identical(final_loo_audit$family, "supplement_primary") &&
        nrow(final_loo_audit$model_summary) == 72L &&
        final_loo_audit$exact_refits == 2L &&
        isTRUE(final_loo_audit$stacking_ready) &&
        nrow(final_loo_audit$high_k_cases) == 0L &&
        all(final_loo_audit$outcome_summary$high_k_cases == 0L),
      nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        sum(prediction_sums$selected_models) == 29L &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      identical(reporting_audit$family, "supplement_primary") &&
        isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Updated supplement-dose primary verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    absolute_exposure_provenance = absolute_audit$exposure_provenance,
    absolute_support_by_outcome = absolute_audit$support_by_outcome,
    absolute_scaling_plan = absolute_audit$scaling_plan,
    absolute_model_registry = absolute_audit$model_registry,
    absolute_family_plan = absolute_audit$family_plan,
    analysis_data = analysis_data,
    model_specifications = specification_table,
    model_name_alignment = name_alignment,
    initial_accepted_fit_manifest = initial_accepted_fit_manifest,
    common_sample_accepted_fit_manifest = common_accepted_fit_manifest,
    final_fit_manifest = final_fit_manifest,
    final_sampling_diagnostic_summary = final_diagnostics,
    final_sampling_parameter_failures = final_parameter_failures,
    initial_loo_manifest = initial_loo_audit$reduction_manifest,
    initial_loo_model_summary = initial_loo_audit$model_summary,
    initial_loo_outcome_summary = initial_loo_audit$outcome_summary,
    initial_high_pareto_k_cases = initial_loo_audit$high_k_cases,
    initial_observation_set_audit = initial_loo_audit$observation_set_audit,
    common_sample_loo_manifest = common_loo_audit$reduction_manifest,
    common_sample_loo_model_summary = common_loo_audit$model_summary,
    common_sample_loo_outcome_summary = common_loo_audit$outcome_summary,
    aligned_loo_manifest = aligned_loo_audit$aligned_loo_manifest,
    aligned_loo_model_summary = aligned_loo_audit$model_summary,
    aligned_loo_outcome_summary = aligned_loo_audit$outcome_summary,
    aligned_high_pareto_k_cases = aligned_loo_audit$high_k_cases,
    exact_refit_diagnostic_summary = exact_loo_audit$diagnostic_summary,
    exact_correction_manifest = correction_manifest,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    c(
      "Final supplement-dose primary checkpoint checks.",
      "Paths, sizes, and SHA-256 hashes for source data.",
      "Combined-data preparation invariants.",
      "Shared absolute-exposure construction invariants.",
      "Eligible contrast counts for both absolute exposure scales.",
      "Provenance of selected reported or derived exposures.",
      "Observed absolute-exposure support by outcome.",
      "Frozen references, units, and grid rules.",
      "Retained 18-model absolute-exposure registry.",
      "Planned primary and sensitivity absolute-exposure families.",
      "Outcome rows used by supplement-dose candidates.",
      "Final 72-model supplement-dose specification registry.",
      "Cross-stage model-name identity audit.",
      "Accepted fit lineage before common-sample alignment.",
      "Accepted 36-fit common-sample replacement lineage.",
      "Final accepted 72-fit lineage used for reporting.",
      "Sampling diagnostics for the final accepted fits.",
      "Parameter-level failures after final fit selection.",
      "Initial 72 integrated PSIS-LOO file manifest.",
      "Initial integrated PSIS-LOO summaries by model.",
      "Initial integrated PSIS-LOO summaries by outcome.",
      "Four initial high Pareto-k cases.",
      "Initial observation-set alignment audit.",
      "Thirty-six common-sample replacement LOO files.",
      "Common-sample replacement LOO summaries by model.",
      "Common-sample replacement LOO summaries by outcome.",
      "Aligned 72-model LOO lineage before exact correction.",
      "Aligned PSIS-LOO summaries by model.",
      "Aligned PSIS-LOO summaries by outcome.",
      "Two aligned high Pareto-k cases selected for exact correction.",
      "Diagnostics for both exact-deletion refits.",
      "Compact exact-correction paths and checksums.",
      "Final exact-corrected 72-model LOO lineage.",
      "Final LOO summary for all 72 models.",
      "Final high-k resolution by outcome.",
      "Final supplement-dose stacking weights.",
      "Allocation of 4,000 prediction draws per outcome.",
      "Reporting file dimensions and checksums.",
      "Model-averaged supplement-dose response curves.",
      "Changes from the zero-supplement reference.",
      "Observed supplement-dose support by resistance-training group.",
      "Supplement-dose support common to resistance-training groups.",
      "Pairwise supplement-dose contrasts and probabilities.",
      "Observed support for pairwise contrasts.",
      "Practical-equivalence summaries in grams per day."
    ),
    names(artifacts)
  )

  list(
    checks = checks,
    artifacts = artifacts,
    descriptions = descriptions,
    next_family = paste(
      "The supplement-dose primary family is frozen after this",
      "verification checkpoint; its lean-pruning plan can be audited."
    )
  )
}

make_update_2026_supplement_primary_pruning_plan <- function(
    final_fit_manifest,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "primary"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "supplement_primary_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (any(!file.exists(verification_files))) {
    stop("The supplement verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  verification_index <- readr::read_csv(
    verification_manifest,
    show_col_types = FALSE
  )

  if (length(verification_files) != nrow(verification_index) + 2L) {
    stop("The supplement verification-file count is invalid.",
         call. = FALSE)
  }

  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "primary"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the supplement archive.",
         call. = FALSE)
  }

  fit_roots <- file.path(
    archive_root,
    c("initial", "remedy_1", "common_sample_1")
  )
  if (any(!dir.exists(fit_roots))) {
    stop("An expected supplement fit directory is missing.",
         call. = FALSE)
  }

  fit_paths <- unlist(
    purrr::map(
      fit_roots,
      ~ list.files(
        .x,
        pattern = "\\.qs$",
        recursive = TRUE,
        full.names = TRUE
      )
    ),
    use.names = FALSE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)

  accepted_paths <- normalizePath(
    final_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  if (
    length(fit_paths) != 109L || length(accepted_paths) != 72L ||
      anyDuplicated(fit_paths) || anyDuplicated(accepted_paths) ||
      !all(accepted_paths %in% fit_paths) ||
      sum(!fit_paths %in% accepted_paths) != 37L
  ) {
    stop("Supplement fit retention does not match its final lineage.",
         call. = FALSE)
  }

  model_fit_manifest <- tibble::tibble(
    path = fit_paths,
    relative_path = substring(fit_paths, nchar(resolved_root) + 2L),
    archive_stage = dplyr::case_when(
      grepl("/initial/", fit_paths, fixed = TRUE) ~ "initial",
      grepl("/remedy_1/", fit_paths, fixed = TRUE) ~ "remedy_1",
      grepl("/common_sample_1/", fit_paths, fixed = TRUE) ~
        "common_sample_1",
      TRUE ~ "unknown"
    ),
    outcome = basename(dirname(fit_paths)),
    model_index = as.integer(sub(
      "^model_([0-9]+)\\.qs$", "\\1", basename(fit_paths)
    )),
    accepted_fit = fit_paths %in% accepted_paths,
    bytes = as.numeric(file.info(fit_paths)$size),
    lean_action = "delete frozen supplement-dose model fit"
  ) |>
    dplyr::arrange(archive_stage, outcome, model_index)

  stage_counts <- table(factor(
    model_fit_manifest$archive_stage,
    levels = c("initial", "remedy_1", "common_sample_1")
  ))
  if (
    any(model_fit_manifest$archive_stage == "unknown") ||
      anyNA(model_fit_manifest$model_index) ||
      !identical(as.integer(stage_counts), c(72L, 1L, 36L)) ||
      sum(model_fit_manifest$accepted_fit) != 72L ||
      sum(!model_fit_manifest$accepted_fit) != 37L ||
      any(model_fit_manifest$bytes <= 0)
  ) {
    stop("The supplement model-fit stages are not as expected.",
         call. = FALSE)
  }

  deletion_manifest <- model_fit_manifest |>
    dplyr::mutate(
      artifact_role = dplyr::if_else(
        accepted_fit,
        "accepted_model_fit",
        "superseded_model_fit"
      ),
      .after = archive_stage
    )

  compact_roots <- c(
    loo_psis_initial = file.path(archive_root, "loo", "integrated"),
    loo_psis_common = file.path(
      archive_root, "loo", "common_sample_final"
    ),
    exact_corrections = file.path(
      archive_root, "loo", "exact_correction"
    ),
    reporting = file.path(archive_root, "reporting")
  )

  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact supplement directory is missing.",
         call. = FALSE)
  }
  compact_paths <- unlist(
    purrr::map(
      compact_roots,
      ~ list.files(
        .x,
        recursive = TRUE,
        full.names = TRUE,
        all.files = TRUE
      )
    ),
    use.names = FALSE
  )

  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  resolved_compact_roots <- normalizePath(
    compact_roots,
    winslash = "/",
    mustWork = TRUE
  )
  component <- vapply(compact_paths, function(path) {
    matches <- names(compact_roots)[vapply(
      resolved_compact_roots,
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact supplement-dose LOO and reporting result"
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c(
      "loo_psis_initial", "loo_psis_common", "exact_corrections",
      "reporting"
    )
  ))

  if (
    nrow(compact_manifest) != 147L ||
      !identical(as.integer(compact_counts), c(72L, 36L, 2L, 37L)) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact supplement archive is incomplete.", call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    full_fit_archives_deleted = nrow(deletion_manifest),
    accepted_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "accepted_model_fit"
    ),
    superseded_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "superseded_model_fit"
    ),
    exact_refit_archives_deleted = 0L,
    full_fit_archives_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained =
      sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, corrected LOO, and all 72 weights remain frozen;",
      "restoring accepted or superseded supplement-dose fits requires",
      "refitting the supplement primary family. Exact refits were already",
      "reduced directly to compact corrections."
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_fit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_supplement_primary_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "primary", "pruning"
    )
) {
  if (
    nrow(plan$model_fit_manifest) != 109L ||
      nrow(plan$deletion_file_manifest) != 109L ||
      nrow(plan$compact_archive_manifest) != 147L
  ) {
    stop("Cannot write an invalid supplement pruning plan.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    deletion_file_manifest = file.path(
      output_dir, "deletion_file_manifest.csv"
    ),
    compact_archive_manifest = file.path(
      output_dir, "compact_archive_manifest.csv"
    )
  )

  readr::write_csv(plan$summary, paths[["summary"]])
  readr::write_csv(plan$model_fit_manifest, paths[["model_fit_manifest"]])
  readr::write_csv(
    plan$deletion_file_manifest,
    paths[["deletion_file_manifest"]]
  )
  readr::write_csv(
    plan$compact_archive_manifest,
    paths[["compact_archive_manifest"]]
  )
  unname(paths)
}

# Prescribed supplement dose with within- and between-study terms ----

# Reuse the absolute-scale sample preparation and verify the expected outcome
# and study counts for the supplement family.
make_update_2026_supplement_mundlak_data_by_outcome <- function(
    supplement_primary_data_by_outcome
) {
  data <- make_update_2026_total_mundlak_data_by_outcome(
    supplement_primary_data_by_outcome
  )
  expected_rows <- c(
    whole_body = 236L,
    hypertrophy = 391L,
    strength = 636L,
    `function` = 219L
  )
  expected_studies <- c(
    whole_body = 68L,
    hypertrophy = 43L,
    strength = 71L,
    `function` = 28L
  )

  if (
    !identical(names(data), names(expected_rows)) ||
      !identical(vapply(data, nrow, integer(1L)), expected_rows) ||
      !identical(
        vapply(
          data,
          function(x) dplyr::n_distinct(x$study_no),
          integer(1L)
        ),
        expected_studies
      ) ||
      any(vapply(data, function(x) {
        any(x$absolute_exposure_reference_g_day != 0) ||
          any(x$absolute_exposure_unit_g_day != 25) ||
          min(x$protein_intake_raw) != 0
      }, logical(1L)))
  ) {
    stop("The supplement Mundlak common samples are invalid.",
         call. = FALSE)
  }

  data
}

make_update_2026_supplement_mundlak_specifications <- function(
    supplement_primary_specifications
) {
  specifications <- make_update_2026_total_mundlak_specifications(
    supplement_primary_specifications
  )
  specifications <- purrr::map(specifications, function(specification) {
    specification$family <- "supplement_mundlak"
    specification$exposure <- "supplement_g_day"
    specification
  })
  table <- dplyr::bind_rows(specifications)
  schedule_counts <- table(factor(
    table$historical_schedule,
    levels = c("base", "longer_sampling")
  ))

  if (
    length(specifications) != 72L || nrow(table) != 72L ||
      any(table$family != "supplement_mundlak") ||
      any(table$exposure != "supplement_g_day") ||
      anyDuplicated(table[c("outcome", "model_index")]) ||
      !identical(as.integer(schedule_counts), c(67L, 5L)) ||
      !all(stringr::str_ends(
        table$model_name,
        stringr::fixed(" [supplement g/day]")
      ))
  ) {
    stop("The supplement Mundlak specification registry is invalid.",
         call. = FALSE)
  }

  specifications
}

prepare_update_2026_supplement_mundlak_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome,
    config
) {
  input <- prepare_update_2026_total_mundlak_input(
    specification = specification,
    data_by_outcome = data_by_outcome,
    priors_by_outcome = priors_by_outcome,
    config = config
  )
  input$family <- "supplement_mundlak"
  input$specification$family <- "supplement_mundlak"
  input
}

validate_update_2026_supplement_mundlak_inputs <- function(
    specifications,
    data_by_outcome,
    priors_by_outcome,
    config
) {
  checks <- purrr::map_dfr(specifications, function(specification) {
    input <- prepare_update_2026_supplement_mundlak_input(
      specification,
      data_by_outcome,
      priors_by_outcome,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      family = input$family,
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      historical_schedule = specification$historical_schedule,
      common_sample = isTRUE(specification$common_sample),
      includes_moderators = isTRUE(specification$includes_moderators),
      body_mass_in_formula =
        stringr::str_detect(input$formula, "\\bbody_mass_outcome_z\\b"),
      regularised_variance_priors =
        isTRUE(specification$regularised_variance_priors),
      basis_dimension = if (is.null(input$basis_spec)) {
        0L
      } else {
        as.integer(input$basis_spec$basis_dimension)
      },
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      arms = dplyr::n_distinct(input$data$arm_no),
      exposure_minimum_g_day = min(input$data$protein_intake_raw),
      exposure_maximum_g_day = max(input$data$protein_intake_raw),
      reference_g_day = unique(
        input$data$absolute_exposure_reference_g_day
      ),
      internal_unit_g_day = unique(
        input$data$absolute_exposure_unit_g_day
      ),
      adapt_delta = max(
        specification$adapt_delta,
        config$adapt_delta_floor
      ),
      max_treedepth = max(
        specification$max_treedepth,
        config$max_treedepth_floor
      ),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    )

  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  outcome_counts <- table(factor(checks$outcome, levels = c(
    "whole_body", "hypertrophy", "strength", "function"
  )))
  schedule_counts <- table(factor(
    checks$historical_schedule,
    levels = c("base", "longer_sampling")
  ))
  expected_rows <- c(
    whole_body = 236L,
    hypertrophy = 391L,
    strength = 636L,
    `function` = 219L
  )
  expected_studies <- c(
    whole_body = 68L,
    hypertrophy = 43L,
    strength = 71L,
    `function` = 28L
  )
  row_audit <- checks |>
    dplyr::summarise(
      row_values = dplyr::n_distinct(contrasts),
      contrasts = dplyr::first(contrasts),
      study_values = dplyr::n_distinct(studies),
      studies = dplyr::first(studies),
      .by = outcome
    )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  if (
    nrow(checks) != 72L || anyDuplicated(keys) || !all(checks$valid) ||
      any(checks$family != "supplement_mundlak") ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !all(checks$model_index %in% retained) ||
      !identical(as.integer(schedule_counts), c(67L, 5L)) ||
      any(!checks$common_sample) ||
      nrow(row_audit) != 4L ||
      any(row_audit$row_values != 1L) ||
      any(row_audit$study_values != 1L) ||
      any(row_audit$contrasts != expected_rows[row_audit$outcome]) ||
      any(row_audit$studies != expected_studies[row_audit$outcome]) ||
      any(checks$includes_moderators & !checks$body_mass_in_formula) ||
      any(!checks$includes_moderators & checks$body_mass_in_formula) ||
      sum(checks$model_index == 4L &
            checks$regularised_variance_priors) != 4L ||
      any(checks$exposure_minimum_g_day != 0) ||
      any(checks$reference_g_day != 0) ||
      any(checks$internal_unit_g_day != 25) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The supplement Mundlak input preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

