fit_update_2026_supplement_mundlak_candidate_to_file <- function(
    input,
    config,
    enabled,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "mundlak", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      paste0(
        "Supplement-dose Mundlak fitting is disabled. Set ",
        "PROTEIN_UPDATE_2026_SUPPLEMENT_MUNDLAK=fit to enable it."
      ),
      call. = FALSE
    )
  }

  if (!identical(input$family, "supplement_mundlak")) {
    stop("The supplement-dose Mundlak fit input is invalid.",
         call. = FALSE)
  }
  outcome_offset <- match(input$specification$outcome, config$outcomes)
  if (is.na(outcome_offset)) {
    stop("Unknown outcome in a supplement-dose Mundlak fit.",
         call. = FALSE)
  }

  local_config <- config
  local_config$iter_warmup <- as.integer(input$specification$iter_warmup)
  local_config$iter_sampling <- as.integer(input$specification$iter_sampling)
  local_config$seed <- as.integer(
    config$seed + 100L * (outcome_offset - 1L) +
      input$specification$model_index
  )
  candidate <- fit_sensitivity_brms_pilot(
    input = input,
    enabled = TRUE,
    config = local_config,
    family = "supplement_mundlak"
  )
  output_dir <- file.path(output_root, candidate$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d.qs", as.integer(candidate$model_index))
  )
  temporary <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary, force = TRUE), add = TRUE)
  qs::qsave(candidate, temporary, preset = "high")

  if (!file.copy(temporary, output_file, overwrite = TRUE)) {
    stop("Could not finalise a supplement-dose Mundlak fit file.",
         call. = FALSE)
  }
  unlink(temporary, force = TRUE)
  if (!file.exists(output_file) || file.info(output_file)$size <= 0) {
    stop("The supplement-dose Mundlak fit file is invalid.",
         call. = FALSE)
  }

  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

make_update_2026_supplement_mundlak_fit_manifest <- function(
    fit_paths,
    specifications
) {
  paths <- unname(unlist(fit_paths, use.names = FALSE))
  manifest <- make_sensitivity_fit_file_manifest(
    paths = paths,
    stage = "initial"
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  expected <- dplyr::bind_rows(specifications) |>
    dplyr::transmute(
      outcome,
      model_index = as.integer(model_index),
      expected_model_name = paste0(model_name, " [supplement_mundlak]")
    )
  alignment <- manifest |>
    dplyr::left_join(
      expected,
      by = c("outcome", "model_index"),
      relationship = "one-to-one"
    )

  if (
    length(paths) != 72L || nrow(manifest) != 72L ||
      any(manifest$family != "supplement_mundlak") ||
      anyDuplicated(paste(manifest$outcome, manifest$model_index)) ||
      anyNA(alignment$expected_model_name) ||
      any(alignment$model_name != alignment$expected_model_name) ||
      any(!file.exists(manifest$fit_path)) ||
      any(manifest$bytes <= 0) ||
      any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The supplement-dose Mundlak fit manifest is invalid.",
         call. = FALSE)
  }

  manifest
}

make_update_2026_supplement_mundlak_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass)

  if (
    !identical(diagnostic_audit$family, "supplement_mundlak") ||
      nrow(failed) != 1L || failed$outcome[[1L]] != "hypertrophy" ||
      failed$model_index[[1L]] != 24L ||
      !isTRUE(failed$geometry_pass[[1L]]) ||
      isTRUE(failed$convergence_pass[[1L]]) ||
      failed$divergent_transitions[[1L]] != 0L ||
      failed$maximum_treedepth_transitions[[1L]] != 0L ||
      failed$maximum_rhat[[1L]] <= 1.01
  ) {
    stop(
      "The supplement Mundlak remedy no longer matches its audit.",
      call. = FALSE
    )
  }

  selected <- purrr::keep(
    specifications,
    ~ identical(.x$outcome, "hypertrophy") &&
      identical(as.integer(.x$model_index), 24L)
  )
  if (length(selected) != 1L) {
    stop("Could not uniquely select supplement Mundlak model 24.",
         call. = FALSE)
  }

  remedy <- selected[[1L]]
  remedy$iter_warmup <- 2000L
  remedy$iter_sampling <- 6000L
  remedy$remedy <- "extended_sampling_after_rhat_failure"
  remedy$archive_stage <- "remedy_1"
  remedy$remedy_reason <- paste(
    "Sampling geometry passed, but maximum R-hat remained just above",
    "the 1.01 convergence threshold."
  )
  list(hypertrophy_model_24 = remedy)
}

validate_update_2026_supplement_mundlak_remedy_inputs <- function(
    inputs,
    initial_fit_paths,
    config
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    expected_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      arms = dplyr::n_distinct(input$data$arm_no),
      adapt_delta = max(
        as.numeric(specification$adapt_delta),
        config$adapt_delta_floor
      ),
      max_treedepth = max(
        as.integer(specification$max_treedepth),
        config$max_treedepth_floor
      ),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      initial_fit_exists =
        length(expected_path) == 1L && file.exists(expected_path),
      valid = TRUE
    )
  })

  if (
    nrow(checks) != 1L || checks$outcome[[1L]] != "hypertrophy" ||
      checks$model_index[[1L]] != 24L ||
      checks$remedy[[1L]] != "extended_sampling_after_rhat_failure" ||
      checks$contrasts[[1L]] != 391L || checks$studies[[1L]] != 43L ||
      checks$arms[[1L]] != 123L ||
      checks$iter_warmup[[1L]] != 2000L ||
      checks$iter_sampling[[1L]] != 6000L ||
      checks$chains[[1L]] != 4L ||
      checks$parallel_chains[[1L]] != 4L ||
      !checks$initial_fit_exists[[1L]] || !checks$valid[[1L]]
  ) {
    stop("The supplement Mundlak remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

