  readr::write_csv(audit$model_summary, paths[["model_summary"]])
  readr::write_csv(audit$outcome_summary, paths[["outcome_summary"]])
  readr::write_csv(
    audit$exact_refit_summary,
    paths[["exact_refit_summary"]]
  )
  unname(paths)
}

make_update_2026_supplement_mundlak_prediction_records <- function(
    accepted_fit_manifest,
    stacking_weights,
    n_draws = 4000L,
    exposure_minimum_g_day = 0,
    grid_step_g_day = 1,
    seed = 177988L
) {
  records <- make_update_2026_total_mundlak_prediction_records(
    accepted_fit_manifest = accepted_fit_manifest,
    stacking_weights = stacking_weights,
    n_draws = n_draws,
    exposure_minimum_g_day = exposure_minimum_g_day,
    grid_step_g_day = grid_step_g_day,
    seed = seed
  )

  records <- purrr::map(records, function(record) {
    record$family <- "supplement_mundlak"
    record$prediction_type <- "supplement_mundlak"
    record
  })
  table <- dplyr::bind_rows(records)
  audit <- table |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      allocated_draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )

  if (
    nrow(audit) != 4L || any(audit$selected_models < 1L) ||
      any(audit$allocated_draws != 4000L) ||
      any(audit$retained_weight <= 0) ||
      any(audit$retained_weight > 1 + 1e-8) ||
      any(table$family != "supplement_mundlak") ||
      any(table$prediction_type != "supplement_mundlak") ||
      any(table$exposure_minimum_g_day != 0) ||
      any(table$grid_step_g_day != 1)
  ) {
    stop("The supplement Mundlak prediction allocation is incomplete.",
         call. = FALSE)
  }

  records
}

make_update_2026_supplement_mundlak_reporting_preflight <- function(
    records,
    data_by_outcome
) {
  checks <- make_update_2026_total_mundlak_reporting_preflight(
    records = records,
    data_by_outcome = data_by_outcome
  )
  record_table <- dplyr::bind_rows(records)

  if (
    any(record_table$family != "supplement_mundlak") ||
      any(record_table$prediction_type != "supplement_mundlak") ||
      any(checks$exposure_minimum_g_day != 0) ||
      any(checks$reference_g_day != 0) ||
      any(checks$study_mean_g_day != 0) ||
      any(checks$internal_unit_g_day != 25) ||
      any(checks$grid_step_g_day != 1) ||
      !all(checks$valid)
  ) {
    stop("The supplement Mundlak reporting preflight failed.",
         call. = FALSE)
  }

  checks
}

write_update_2026_supplement_mundlak_reporting_preflight <- function(
    checks,
