write_update_2026_supplement_mundlak_prediction_draw_file <- function(
    record,
    data_by_outcome,
    result_path
) {
  if (
    !file.exists(record$fit_path) || record$draw_count < 1L ||
      !identical(as.character(record$family), "supplement_mundlak")
  ) {
    stop("A supplement Mundlak prediction record is invalid.",
         call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  candidate_model_name <- if (stringr::str_ends(
    candidate$model_name,
    stringr::fixed(" [supplement_mundlak]")
  )) {
    candidate$model_name
  } else {
    paste0(candidate$model_name, " [supplement_mundlak]")
  }

  if (
    !identical(unname(as.character(candidate$family)),
               "supplement_mundlak") ||
      !identical(
        unname(as.character(candidate$outcome)),
        as.character(record$outcome)
      ) ||
      as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(candidate_model_name, as.character(record$model_name))
  ) {
    stop("A supplement Mundlak fit does not match its prediction record.",
         call. = FALSE)
  }

  grid <- make_update_2026_supplement_mundlak_prediction_grid(
    fitted_candidate = candidate,
    data = data_by_outcome[[record$outcome]],
    exposure_minimum_g_day = record$exposure_minimum_g_day,
    grid_step_g_day = record$grid_step_g_day
  )
  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  set.seed(as.integer(record$prediction_seed))
  draws <- as.matrix(brms::posterior_epred(
    candidate$model,
    newdata = grid$newdata,
    re_formula = NA,
    ndraws = as.integer(record$draw_count)
  ))

  if (ncol(draws) != nrow(grid$keys) && nrow(draws) == nrow(grid$keys)) {
    draws <- t(draws)
  }
  if (
    nrow(draws) != as.integer(record$draw_count) ||
      ncol(draws) != nrow(grid$keys) || anyNA(draws)
  ) {
    stop("Supplement Mundlak predictions do not match their allocation.",
         call. = FALSE)
  }

  reduction <- list(
    family = "supplement_mundlak",
    outcome = as.character(record$outcome),
    model_index = as.integer(record$model_index),
    model_name = as.character(record$model_name),
    weight = as.numeric(record$weight),
    draw_count = as.integer(record$draw_count),
    prediction_seed = as.integer(record$prediction_seed),
    fit_sha256 = as.character(record$fit_sha256),
    grid = grid$keys,
    draws = draws,
    settings = list(
      protein_min = grid$protein_min,
      protein_max = grid$protein_max,
      grid_step = grid$grid_step,
      reference_intake = grid$reference_g_day,
      study_mean_g_day = grid$study_mean_g_day,
      internal_unit_g_day = grid$unit_g_day,
      prediction_type = "supplement_mundlak"
    )
  )

  write_atomic_qs(reduction, result_path)
}

make_update_2026_supplement_mundlak_model_average_records <- function(
    prediction_manifest,
    stacking_weights,
    n_draws = 4000L,
    seed = 178988L
) {
  records <- make_update_2026_total_mundlak_model_average_records(
    prediction_manifest = prediction_manifest,
    stacking_weights = stacking_weights,
    n_draws = n_draws,
    seed = seed
  )
  records <- purrr::map(records, function(record) {
    record$family <- "supplement_mundlak"
    record
  })

  if (any(!purrr::map_lgl(
    records,
    ~ identical(.x$family, "supplement_mundlak")
  ))) {
    stop("The supplement Mundlak model-average records are invalid.",
         call. = FALSE)
  }

  records
}

write_update_2026_supplement_mundlak_reporting_file <- function(
    model_average_path,
    data_by_outcome,
    reference_intake = 0,
    sesoi = 0.10,
    result_path
) {
  model_average <- read_sensitivity_full_model_average_file(
    model_average_path,
    family = "supplement_mundlak"
  )
  outcome <- model_average$outcome
  data <- data_by_outcome[[outcome]]

  if (is.null(data) || !is.data.frame(data)) {
    stop("The supplement Mundlak reporting data are unavailable.",
         call. = FALSE)
  }
  absolute <- summarise_primary_dose_response(model_average)
  supported <- build_sensitivity_mundlak_reporting_pilot(
    absolute,
    model_average,
    data,
    reference_intake
  )
  heatmap <- compute_primary_heatmap_contrasts(
    model_average = model_average,
    data = data,
    protein_min = 0,
    sesoi = sesoi
  )
  report <- list(
    family = "supplement_mundlak",
    outcome = outcome,
    dose_response = supported$absolute_full_grid,
    dose_response_increments = supported$increments_full_grid,
    exposure_support_by_group = supported$support_by_group,
    common_exposure_support = supported$common_support,
    pairwise_contrasts = heatmap$contrasts,
    pairwise_support = heatmap$support,
    local_equivalence = summarise_primary_local_equivalence(
      heatmap$contrasts,
      outcome = outcome
    ),
    model_weights = tibble::tibble(
      model_name = names(model_average$model_weights),
      weight = as.numeric(model_average$model_weights)
    ),
    settings = utils::modifyList(
      model_average$settings,
      list(
        reference_intake = reference_intake,
        sesoi = sesoi,
        exposure = "supplement_g_day",
        exposure_unit = "g/day",
        mundlak_between_profile = "study mean held at zero supplement"
      )
    )
  )

  write_atomic_qs(report, result_path)
}

write_update_2026_supplement_mundlak_reporting_audit <- function(
    audit,
    prediction_manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "mundlak", "reporting"
    )
) {
  if (
    !identical(audit$family, "supplement_mundlak") ||
      !isTRUE(audit$all_reporting_checks_pass) ||
      nrow(audit$summary) != 4L ||
      sum(prediction_manifest$draw_count) != 16000L
  ) {
    stop("The supplement Mundlak reporting audit is incomplete.",
         call. = FALSE)
  }

  reports <- purrr::map(
    audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "supplement_mundlak"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(
      report$model_weights,
      outcome = report$outcome,
      .before = 1L
    )
  })
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    prediction_manifest = file.path(output_dir, "prediction_manifest.csv"),
    dose_response = file.path(output_dir, "dose_response.csv"),
    dose_response_increments = file.path(
      output_dir, "dose_response_increments.csv"
    ),
    exposure_support_by_group = file.path(
      output_dir, "exposure_support_by_group.csv"
    ),
    common_exposure_support = file.path(
      output_dir, "common_exposure_support.csv"
    ),
    pairwise_contrasts = file.path(output_dir, "pairwise_contrasts.csv.gz"),
    pairwise_support = file.path(output_dir, "pairwise_support.csv"),
    local_equivalence = file.path(output_dir, "local_equivalence.csv"),
    model_weights = file.path(output_dir, "model_weights.csv")
  )

  readr::write_csv(audit$summary, paths[["summary"]])
  readr::write_csv(prediction_manifest, paths[["prediction_manifest"]])
  readr::write_csv(bind_report("dose_response"), paths[["dose_response"]])
  readr::write_csv(
    bind_report("dose_response_increments"),
    paths[["dose_response_increments"]]
  )
  readr::write_csv(
    bind_report("exposure_support_by_group"),
    paths[["exposure_support_by_group"]]
  )
  readr::write_csv(
    bind_report("common_exposure_support"),
    paths[["common_exposure_support"]]
  )
  readr::write_csv(
    bind_report("pairwise_contrasts"),
    paths[["pairwise_contrasts"]]
  )
  readr::write_csv(
    bind_report("pairwise_support"),
    paths[["pairwise_support"]]
  )
  readr::write_csv(
    bind_report("local_equivalence"),
    paths[["local_equivalence"]]
  )
  readr::write_csv(model_weights, paths[["model_weights"]])
  unname(paths)
}

make_update_2026_supplement_mundlak_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    data_by_outcome,
    specifications,
    accepted_fit_manifest,
    diagnostic_audit,
    integrated_loo_audit,
    exact_diagnostic_audit,
    exact_correction_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  expected_rows <- c(
    whole_body = 236L,
    hypertrophy = 391L,
    strength = 636L,
    `function` = 219L
  )
  expected_studies <- c(
    whole_body = 68L,
    hypertrophy = 43L,
    strength = 71L,
    `function` = 28L
  )
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::mutate(
      model_name = dplyr::if_else(
        stringr::str_ends(
          model_name,
          stringr::fixed(" [supplement_mundlak]")
        ),
        model_name,
        paste0(model_name, " [supplement_mundlak]")
      )
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)

  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  specification_keys <- registry_keys(specification_table)
  diagnostic_keys <- registry_keys(diagnostic_audit$diagnostic_summary)
  fit_keys <- registry_keys(accepted_fit_manifest)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, fit_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- specification_table |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      diagnostic_audit$diagnostic_summary |>
        dplyr::select(outcome, model_index, diagnostic_name = model),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  weight_sums <- stacking_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    )
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )
  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "supplement_mundlak"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  correction_manifest <- exact_correction_audit$correction_manifest
  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      "all four supplement Mundlak datasets are valid",
      "all five final registries contain the same 72 model keys",
      "model names agree across specifications fits diagnostics LOO and weights",
      "all 72 accepted fit files exist and have checksums",
      "all accepted-fit sampling diagnostics pass",
      "initial LOO contains 72 aligned models and eight high-k cases",
      "all eight exact-refit sampling diagnostics pass",
      "all eight compact exact corrections exist and have checksums",
      "final LOO contains 72 models and no unresolved high-k cases",
      "four stacking vectors contain 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      "all four supplement Mundlak reporting audits pass"
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      identical(names(data_by_outcome), outcomes) &&
        identical(vapply(data_by_outcome, nrow, integer(1L)), expected_rows) &&
        identical(
          vapply(
            data_by_outcome,
            function(data) dplyr::n_distinct(data$study_no),
            integer(1L)
          ),
          expected_studies
        ) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0) &&
        all(is.finite(analysis_data$mean_body_mass_kg)) &&
        all(analysis_data$absolute_exposure_reference_g_day == 0) &&
        all(analysis_data$absolute_exposure_unit_g_day == 25),
      common_registry && length(specification_keys) == 72L,
      nrow(name_alignment) == 72L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(
          name_alignment$diagnostic_name ==
            name_alignment$specification_name
        ) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(accepted_fit_manifest) == 72L &&
        all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(accepted_fit_manifest$bytes > 0) &&
        all(nchar(accepted_fit_manifest$sha256) == 64L),
      identical(diagnostic_audit$family, "supplement_mundlak") &&
        diagnostic_audit$models == 72L &&
        isTRUE(diagnostic_audit$all_sampling_diagnostics_pass) &&
        all(diagnostic_audit$diagnostic_summary$diagnostic_pass),
      identical(integrated_loo_audit$family, "supplement_mundlak") &&
        integrated_loo_audit$models == 72L &&
        sum(stringr::str_starts(
          integrated_loo_audit$model_summary$method,
          "integrated_"
        )) == 72L &&
        integrated_loo_audit$exact_refits_required == 8L &&
        nrow(integrated_loo_audit$high_k_cases) == 8L &&
        all(integrated_loo_audit$outcome_summary$observation_sets_aligned),
      exact_diagnostic_audit$exact_refits == 8L &&
        exact_diagnostic_audit$exact_refits_passing == 8L &&
        isTRUE(exact_diagnostic_audit$all_exact_refit_diagnostics_pass),
      nrow(correction_manifest) == 8L &&
        all(file.exists(correction_manifest$correction_path)) &&
        all(correction_manifest$bytes > 0) &&
        all(nchar(correction_manifest$sha256) == 64L),
      identical(final_loo_audit$family, "supplement_mundlak") &&
        nrow(final_loo_audit$model_summary) == 72L &&
        final_loo_audit$exact_refits == 8L &&
        isTRUE(final_loo_audit$stacking_ready) &&
        all(final_loo_audit$outcome_summary$unresolved_high_k_cases == 0L),
      nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        sum(prediction_sums$selected_models) == 28L &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      identical(reporting_audit$family, "supplement_mundlak") &&
        isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Updated supplement Mundlak verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    preparation_outcome_counts = preparation_audit$outcome_counts,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    absolute_exposure_provenance = absolute_audit$exposure_provenance,
    absolute_support_by_outcome = absolute_audit$support_by_outcome,
    absolute_scaling_plan = absolute_audit$scaling_plan,
    absolute_model_registry = absolute_audit$model_registry,
    absolute_family_plan = absolute_audit$family_plan,
    analysis_data = analysis_data,
    model_specifications = specification_table,
    model_name_alignment = name_alignment,
    accepted_fit_manifest = accepted_fit_manifest,
    sampling_diagnostic_summary = diagnostic_audit$diagnostic_summary,
    sampling_parameter_failures = diagnostic_audit$parameter_failures,
    initial_integrated_loo_model_summary = integrated_loo_audit$model_summary,
    initial_integrated_loo_outcome_summary =
      integrated_loo_audit$outcome_summary,
    initial_high_pareto_k_cases = integrated_loo_audit$high_k_cases,
    observation_set_audit = integrated_loo_audit$observation_set_audit,
    exact_refit_diagnostic_summary = exact_diagnostic_audit$diagnostic_summary,
    exact_correction_manifest = correction_manifest,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    exact_refit_summary = final_loo_audit$exact_refit_summary,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    paste("Frozen supplement Mundlak verification artifact:", names(artifacts)),
    names(artifacts)
  )
  list(
    checks = checks,
    artifacts = artifacts,
    descriptions = descriptions,
    next_family = paste(
      "The supplement Mundlak family is frozen after this verification",
      "checkpoint; its lean-pruning plan can then be audited."
    )
  )
}

make_update_2026_supplement_mundlak_pruning_plan <- function(
    accepted_fit_manifest,
    exact_diagnostic_audit,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "mundlak"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "supplement_mundlak_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (any(!file.exists(verification_files))) {
    stop("The supplement Mundlak verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  verification_index <- readr::read_csv(
    verification_manifest,
    show_col_types = FALSE
  )

  if (length(verification_files) != nrow(verification_index) + 2L) {
    stop("The supplement Mundlak verification-file count is invalid.",
         call. = FALSE)
  }
  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "mundlak"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the supplement Mundlak archive.",
         call. = FALSE)
  }
  fit_roots <- file.path(archive_root, c("initial", "remedy_1"))
  exact_fit_root <- file.path(archive_root, "loo", "exact_fit")

  if (any(!dir.exists(c(fit_roots, exact_fit_root)))) {
    stop("An expected supplement Mundlak fit directory is missing.",
         call. = FALSE)
  }
  fit_paths <- unlist(
    purrr::map(
      fit_roots,
      ~ list.files(
        .x,
        pattern = "\\.qs$",
        recursive = TRUE,
        full.names = TRUE
      )
    ),
    use.names = FALSE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)

  accepted_paths <- normalizePath(
    accepted_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  if (
    length(fit_paths) != 73L || length(accepted_paths) != 72L ||
      anyDuplicated(fit_paths) || anyDuplicated(accepted_paths) ||
      !all(accepted_paths %in% fit_paths) ||
      sum(!fit_paths %in% accepted_paths) != 1L
  ) {
    stop("Supplement Mundlak fit retention does not match its lineage.",
         call. = FALSE)
  }

  model_fit_manifest <- tibble::tibble(
    path = fit_paths,
    relative_path = substring(fit_paths, nchar(resolved_root) + 2L),
    archive_stage = dplyr::case_when(
      grepl("/initial/", fit_paths, fixed = TRUE) ~ "initial",
      grepl("/remedy_1/", fit_paths, fixed = TRUE) ~ "remedy_1",
      TRUE ~ "unknown"
    ),
    outcome = basename(dirname(fit_paths)),
    model_index = as.integer(sub(
      "^model_([0-9]+)\\.qs$", "\\1", basename(fit_paths)
    )),
    accepted_fit = fit_paths %in% accepted_paths,
    bytes = as.numeric(file.info(fit_paths)$size),
    lean_action = "delete frozen supplement Mundlak model fit"
  ) |>
    dplyr::arrange(archive_stage, outcome, model_index)

  stage_counts <- table(factor(
    model_fit_manifest$archive_stage,
    levels = c("initial", "remedy_1")
  ))
  if (
    any(model_fit_manifest$archive_stage == "unknown") ||
      anyNA(model_fit_manifest$model_index) ||
      !identical(as.integer(stage_counts), c(72L, 1L)) ||
      sum(model_fit_manifest$accepted_fit) != 72L ||
      sum(!model_fit_manifest$accepted_fit) != 1L ||
      any(model_fit_manifest$bytes <= 0)
  ) {
    stop("The supplement Mundlak model-fit stages are not as expected.",
         call. = FALSE)
  }

  exact_fit_paths <- list.files(
    exact_fit_root,
    pattern = "\\.qs$",
    recursive = TRUE,
    full.names = TRUE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)
  exact_match <- stringr::str_match(
    basename(exact_fit_paths),
    "^model_([0-9]+)_case_([0-9]+)_observation_([0-9]+)\\.qs$"
  )
  exact_refit_manifest <- tibble::tibble(
    path = exact_fit_paths,
    relative_path = substring(exact_fit_paths, nchar(resolved_root) + 2L),
    archive_stage = "exact_refit",
    outcome = basename(dirname(exact_fit_paths)),
    model_index = as.integer(exact_match[, 2L]),
    case_id = as.integer(exact_match[, 3L]),
    observation = as.integer(exact_match[, 4L]),
    bytes = as.numeric(file.info(exact_fit_paths)$size),
    lean_action = "delete frozen supplement Mundlak exact-deletion refit"
  ) |>
    dplyr::arrange(case_id)

  exact_keys <- paste(
    exact_refit_manifest$outcome,
    exact_refit_manifest$model_index,
    exact_refit_manifest$observation,
    sep = "::"
  )
  diagnostic_keys <- paste(
    exact_diagnostic_audit$diagnostic_summary$outcome,
    exact_diagnostic_audit$diagnostic_summary$model_index,
    exact_diagnostic_audit$diagnostic_summary$observation,
    sep = "::"
  )

  if (
    nrow(exact_refit_manifest) != 8L ||
      anyNA(exact_refit_manifest[c("model_index", "case_id", "observation")]) ||
      !identical(exact_refit_manifest$case_id, seq_len(8L)) ||
      any(exact_refit_manifest$bytes <= 0) ||
      !setequal(exact_keys, diagnostic_keys) ||
      !isTRUE(exact_diagnostic_audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("The supplement Mundlak exact-refit inventory is invalid.",
         call. = FALSE)
  }

  deletion_manifest <- dplyr::bind_rows(
    model_fit_manifest |>
      dplyr::mutate(
        artifact_role = dplyr::if_else(
          accepted_fit,
          "accepted_model_fit",
          "superseded_model_fit"
        ),
        case_id = NA_integer_,
        observation = NA_integer_
      ),
    exact_refit_manifest |>
      dplyr::mutate(
        accepted_fit = FALSE,
        artifact_role = "exact_refit"
      )
  ) |>
    dplyr::select(
      path, relative_path, archive_stage, artifact_role, outcome,
      model_index, case_id, observation, accepted_fit, bytes, lean_action
    )

  compact_roots <- c(
    loo_psis = file.path(archive_root, "loo", "integrated"),
    exact_corrections = file.path(archive_root, "loo", "exact_correction"),
    reporting = file.path(archive_root, "reporting")
  )
  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact supplement Mundlak directory is missing.",
         call. = FALSE)
  }

  compact_paths <- unlist(
    purrr::map(
      compact_roots,
      ~ list.files(
        .x,
        recursive = TRUE,
        full.names = TRUE,
        all.files = TRUE
      )
    ),
    use.names = FALSE
  )

  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  normalized_compact_roots <- normalizePath(
    compact_roots,
    winslash = "/",
    mustWork = TRUE
  )
  component <- vapply(compact_paths, function(path) {
    matches <- names(compact_roots)[vapply(
      normalized_compact_roots,
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact supplement Mundlak result"
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo_psis", "exact_corrections", "reporting")
  ))
  if (
    nrow(compact_manifest) != 116L ||
      !identical(as.integer(compact_counts), c(72L, 8L, 36L)) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact supplement Mundlak archive is incomplete.",
         call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    full_fit_archives_deleted = nrow(deletion_manifest),
    accepted_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "accepted_model_fit"
    ),
    superseded_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "superseded_model_fit"
    ),
    exact_refit_archives_deleted = sum(
      deletion_manifest$artifact_role == "exact_refit"
    ),
    full_fit_archives_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained = sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, corrected LOO, and all 72 weights remain frozen;",
      "restoring model or exact-refit objects requires refitting the",
      "supplement Mundlak family."
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_fit_manifest,
    exact_refit_manifest = exact_refit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_supplement_mundlak_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "mundlak", "pruning"
    )
) {
  if (
    nrow(plan$model_fit_manifest) != 73L ||
      nrow(plan$exact_refit_manifest) != 8L ||
      nrow(plan$deletion_file_manifest) != 81L ||
      nrow(plan$compact_archive_manifest) != 116L
  ) {
    stop("Cannot write an invalid supplement Mundlak pruning plan.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    exact_refit_manifest = file.path(output_dir, "exact_refit_manifest.csv"),
    deletion_file_manifest = file.path(
      output_dir, "deletion_file_manifest.csv"
    ),
    compact_archive_manifest = file.path(
      output_dir, "compact_archive_manifest.csv"
    )
  )

  readr::write_csv(plan$summary, paths[["summary"]])
  readr::write_csv(plan$model_fit_manifest, paths[["model_fit_manifest"]])
  readr::write_csv(plan$exact_refit_manifest, paths[["exact_refit_manifest"]])
  readr::write_csv(
    plan$deletion_file_manifest,
    paths[["deletion_file_manifest"]]
  )
  readr::write_csv(
    plan$compact_archive_manifest,
    paths[["compact_archive_manifest"]]
  )
  unname(paths)
}

# Absolute prescribed-supplement strict within-study sensitivity ----

# Construct within-study comparisons using the prescribed supplement exposure
# and its corresponding outcome sample.
make_update_2026_supplement_within_contrast_data_by_outcome <- function(
    supplement_mundlak_data_by_outcome
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  if (!identical(names(supplement_mundlak_data_by_outcome), outcomes)) {
    stop("The supplement within-study source registry is invalid.",
         call. = FALSE)
  }

  contrasts <- purrr::map(
    supplement_mundlak_data_by_outcome,
    function(data) {
      required <- c(
        "study_no", "arm_no_extracted", "mean_body_mass_kg",
        "absolute_exposure_reference_g_day", "absolute_exposure_unit_g_day"
      )
      if (!all(required %in% names(data))) {
        stop("A supplement within-study source is incomplete.",
             call. = FALSE)
      }
      arm_mass <- data |>
        dplyr::distinct(study_no, arm_no_extracted, mean_body_mass_kg)
      if (
        anyDuplicated(arm_mass[c("study_no", "arm_no_extracted")]) ||
          any(!is.finite(arm_mass$mean_body_mass_kg))
      ) {
        stop("Supplement within-study arm body mass is ambiguous.",
             call. = FALSE)
      }
      reference <- unique(data$absolute_exposure_reference_g_day)
      unit <- unique(data$absolute_exposure_unit_g_day)
      output <- make_strict_within_study_contrasts(data) |>
        dplyr::left_join(
          arm_mass |>
            dplyr::rename(
              protein_arm_no_extracted = arm_no_extracted,
              protein_arm_body_mass_kg = mean_body_mass_kg
            ),
          by = c("study_no", "protein_arm_no_extracted"),
          relationship = "many-to-one"
        ) |>
        dplyr::left_join(
          arm_mass |>
            dplyr::rename(
              comparator_arm_no_extracted = arm_no_extracted,
              comparator_arm_body_mass_kg = mean_body_mass_kg
            ),
          by = c("study_no", "comparator_arm_no_extracted"),
          relationship = "many-to-one"
        ) |>
        dplyr::mutate(
          mean_body_mass_kg =
            (protein_arm_body_mass_kg + comparator_arm_body_mass_kg) / 2,
          absolute_exposure_reference_g_day = reference,
          absolute_exposure_unit_g_day = unit
        ) |>
        dplyr::select(
          -protein_arm_body_mass_kg,
          -comparator_arm_body_mass_kg
        )
      if (
        length(reference) != 1L || reference != 0 ||
          length(unit) != 1L || unit != 25 ||
          any(!is.finite(output$mean_body_mass_kg))
      ) {
        stop("A supplement within-study contrast scale is invalid.",
             call. = FALSE)
      }
      output
    }
  )

  expected_contrasts <- c(
    whole_body = 134L,
    hypertrophy = 229L,
    strength = 330L,
    `function` = 122L
  )

  if (!identical(vapply(contrasts, nrow, integer(1L)), expected_contrasts)) {
    stop("The supplement within-study contrast counts have changed.",
         call. = FALSE)
  }
  contrasts
}

make_update_2026_supplement_within_specifications <- function(
    supplement_primary_specifications
) {
  specifications <- make_update_2026_total_within_specifications(
    supplement_primary_specifications
  )
  specifications <- purrr::map(specifications, function(specification) {
    specification$family <- "supplement_within"
    specification$exposure <- "supplement_g_day"
    specification$model_name <- stringr::str_replace(
      specification$model_name,
      stringr::fixed(" [total_within]"),
      " [supplement_within]"
    )
    specification
  })

  table <- dplyr::bind_rows(specifications)
  schedule_counts <- table(factor(
    table$historical_schedule,
    levels = c("base", "longer_sampling")
  ))
  if (
    length(specifications) != 72L || nrow(table) != 72L ||
      any(table$family != "supplement_within") ||
      any(table$exposure != "supplement_g_day") ||
      anyDuplicated(table[c("outcome", "model_index")]) ||
      !identical(as.integer(schedule_counts), c(68L, 4L)) ||
      !all(stringr::str_ends(
        table$model_name,
        stringr::fixed(" [supplement_within]")
      ))
  ) {
    stop("The supplement within-study specification registry is invalid.",
         call. = FALSE)
  }

  specifications
}

prepare_update_2026_supplement_within_input <- function(
    specification,
    contrast_data_by_outcome,
    priors_by_outcome,
    config
) {
  input <- prepare_update_2026_total_within_input(
    specification = specification,
    contrast_data_by_outcome = contrast_data_by_outcome,
    priors_by_outcome = priors_by_outcome,
    config = config
  )
  input$family <- "supplement_within"
  input$specification$family <- "supplement_within"
  input
}

validate_update_2026_supplement_within_inputs <- function(
    specifications,
    contrast_data_by_outcome,
    priors_by_outcome,
    config
) {
  checks <- purrr::map_dfr(specifications, function(specification) {
    input <- prepare_update_2026_supplement_within_input(
      specification,
      contrast_data_by_outcome,
      priors_by_outcome,
      config
    )
    local_config <- update_2026_total_within_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      family = input$family,
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      historical_schedule = specification$historical_schedule,
      includes_moderators = isTRUE(specification$includes_moderators),
      body_mass_in_formula =
        stringr::str_detect(input$formula, "\\bbody_mass_outcome_z\\b"),
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      matched_arm_pairs = dplyr::n_distinct(input$data$arm_no),
      exposure_minimum_g_day = min(c(
        input$data$protein_intake_raw_treatment,
        input$data$protein_intake_raw_comparator
      )),
      exposure_maximum_g_day = max(c(
        input$data$protein_intake_raw_treatment,
        input$data$protein_intake_raw_comparator
      )),
      reference_g_day = unique(
        input$data$absolute_exposure_reference_g_day
      ),
      internal_unit_g_day = unique(
        input$data$absolute_exposure_unit_g_day
      ),
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  expected <- tibble::tribble(
    ~outcome, ~contrasts, ~studies, ~matched_arm_pairs,
    "whole_body", 134L, 63L, 106L,
    "hypertrophy", 229L, 40L, 72L,
    "strength", 330L, 65L, 104L,
    "function", 122L, 26L, 40L
  )
  outcome_audit <- checks |>
    dplyr::summarise(
      contrast_values = dplyr::n_distinct(contrasts),
      contrasts = dplyr::first(contrasts),
      study_values = dplyr::n_distinct(studies),
      studies = dplyr::first(studies),
      pair_values = dplyr::n_distinct(matched_arm_pairs),
      matched_arm_pairs = dplyr::first(matched_arm_pairs),
      .by = outcome
    ) |>
    dplyr::left_join(expected, by = "outcome", suffix = c("", "_expected"))

  outcome_counts <- table(factor(
    checks$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  schedule_counts <- table(factor(
    checks$historical_schedule,
    levels = c("base", "longer_sampling")
  ))
  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (
    nrow(checks) != 72L || anyDuplicated(keys) || !all(checks$valid) ||
      any(checks$family != "supplement_within") ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !all(checks$model_index %in% retained) ||
      !identical(as.integer(schedule_counts), c(68L, 4L)) ||
      nrow(outcome_audit) != 4L ||
      any(outcome_audit$contrast_values != 1L) ||
      any(outcome_audit$study_values != 1L) ||
      any(outcome_audit$pair_values != 1L) ||
      any(outcome_audit$contrasts != outcome_audit$contrasts_expected) ||
      any(outcome_audit$studies != outcome_audit$studies_expected) ||
      any(
        outcome_audit$matched_arm_pairs !=
          outcome_audit$matched_arm_pairs_expected
      ) ||
      any(checks$includes_moderators & !checks$body_mass_in_formula) ||
      any(!checks$includes_moderators & checks$body_mass_in_formula) ||
      any(checks$exposure_minimum_g_day != 0) ||
      any(checks$reference_g_day != 0) ||
      any(checks$internal_unit_g_day != 25) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The supplement within-study input preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_supplement_within_input_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "within", "input_preflight.csv"
    )
) {
  if (nrow(checks) != 72L || !all(checks$valid)) {
    stop("Cannot write an invalid supplement within-study preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

fit_update_2026_supplement_within_candidate_to_file <- function(
    input,
    config,
    enabled,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "within", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      paste0(
        "Supplement within-study fitting is disabled. Set ",
        "PROTEIN_UPDATE_2026_SUPPLEMENT_WITHIN=fit to enable it."
      ),
      call. = FALSE
    )
  }

  if (!identical(input$family, "supplement_within")) {
    stop("The supplement within-study fit input is invalid.",
         call. = FALSE)
  }
  local_config <- update_2026_total_within_local_config(
    input$specification,
    config
  )
  candidate <- fit_sensitivity_brms_pilot(
    input = input,
    enabled = TRUE,
    config = local_config,
    family = "supplement_within"
  )
  output_dir <- file.path(output_root, candidate$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d.qs", as.integer(candidate$model_index))
  )
  temporary <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary, force = TRUE), add = TRUE)
  qs::qsave(candidate, temporary, preset = "high")

  if (!file.copy(temporary, output_file, overwrite = TRUE)) {
    stop("Could not finalise a supplement within-study fit.",
         call. = FALSE)
  }
  unlink(temporary, force = TRUE)
  if (!file.exists(output_file) || file.info(output_file)$size <= 0) {
    stop("The supplement within-study fit file is invalid.",
         call. = FALSE)
  }

  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

make_update_2026_supplement_within_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  expected_keys <- c(
    "hypertrophy::9", "hypertrophy::18", "hypertrophy::24",
    "strength::11"
  )
  expected_geometry_keys <- c("hypertrophy::9", "hypertrophy::24")
  expected_convergence_keys <- c("hypertrophy::18", "strength::11")
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  geometry_keys <- failed$key[!failed$geometry_pass]
  convergence_keys <- failed$key[
    failed$geometry_pass & !failed$convergence_pass
  ]

  if (
    !identical(diagnostic_audit$family, "supplement_within") ||
      nrow(failed) != 4L || anyDuplicated(failed$key) ||
      !setequal(failed$key, expected_keys) ||
      !setequal(geometry_keys, expected_geometry_keys) ||
      !setequal(convergence_keys, expected_convergence_keys)
  ) {
    stop("The supplement within-study remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(specifications, function(specification) {
    paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    ) %in% expected_keys
  })
  selected <- purrr::map(selected, function(specification) {
    key <- paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    )
    if (key %in% expected_geometry_keys) {
      specification$adapt_delta <- max(
        as.numeric(specification$adapt_delta),
        0.999
      )
      specification$max_treedepth <- max(
        as.integer(specification$max_treedepth),
        15L
      )
      specification$iter_warmup <- 3000L
      specification$iter_sampling <- 6000L
      specification$remedy <- "stabilized_sampling_after_geometry_failure"
      specification$remedy_reason <- paste(
        "At least one divergent transition remained in the initial fit;",
        "adaptation, tree depth, warmup, and sampling are increased."
      )
    } else {
      specification$adapt_delta <- max(
        as.numeric(specification$adapt_delta),
        0.995
      )
      specification$max_treedepth <- max(
        as.integer(specification$max_treedepth),
        12L
      )
      specification$iter_warmup <- 2000L
      specification$iter_sampling <- 6000L
      specification$remedy <- "extended_sampling_after_convergence_failure"
      specification$remedy_reason <- paste(
        "Sampling geometry passed, but R-hat or effective sample-size",
        "thresholds were not met."
      )
    }
    specification$archive_stage <- "remedy_1"
    specification
  })

  keys <- purrr::map_chr(
    selected,
    ~ paste(.x$outcome, .x$model_index, sep = "::")
  )
  if (
    length(selected) != 4L || anyDuplicated(keys) ||
      !setequal(keys, expected_keys)
  ) {
    stop("The supplement within-study remedy specifications are incomplete.",
         call. = FALSE)
  }

  names(selected) <- paste0(
    purrr::map_chr(selected, "outcome"),
    "_model_",
    stringr::str_pad(purrr::map_int(selected, "model_index"), 2L, pad = "0")
  )
  selected
}

validate_update_2026_supplement_within_remedy_inputs <- function(
    inputs,
    initial_fit_paths,
    config
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    expected_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    local_config <- update_2026_total_within_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      matched_arm_pairs = dplyr::n_distinct(input$data$arm_no),
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      initial_fit_exists =
        length(expected_path) == 1L && file.exists(expected_path),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    )

  expected <- tibble::tribble(
    ~outcome, ~model_index, ~remedy, ~adapt_delta, ~max_treedepth,
    ~iter_warmup, ~iter_sampling,
    "hypertrophy", 9L, "stabilized_sampling_after_geometry_failure",
    0.999, 15L, 3000L, 6000L,
    "hypertrophy", 18L, "extended_sampling_after_convergence_failure",
    0.995, 12L, 2000L, 6000L,
    "hypertrophy", 24L, "stabilized_sampling_after_geometry_failure",
    0.999, 15L, 3000L, 6000L,
    "strength", 11L, "extended_sampling_after_convergence_failure",
    0.999, 15L, 2000L, 6000L
  )

  comparison <- checks |>
    dplyr::left_join(
      expected,
      by = c("outcome", "model_index"),
      suffix = c("", "_expected")
    )

  if (
    nrow(checks) != 4L ||
      anyNA(comparison$remedy_expected) ||
      any(comparison$remedy != comparison$remedy_expected) ||
      any(comparison$adapt_delta != comparison$adapt_delta_expected) ||
      any(comparison$max_treedepth != comparison$max_treedepth_expected) ||
      any(comparison$iter_warmup != comparison$iter_warmup_expected) ||
      any(comparison$iter_sampling != comparison$iter_sampling_expected) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$initial_fit_exists) || !all(checks$valid)
  ) {
    stop("The supplement within-study remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

