  make_update_2026_total_within_loo_records(accepted_fit_manifest)
}

compute_update_2026_supplement_within_integrated_loo_to_file <- function(
    fit_record,
    enabled,
    loo_draws = 4000L,
    k_threshold = 0.7,
    cores = 1L,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "within", "loo", "integrated"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      "Supplement within-study LOO is disabled. Set ",
      "PROTEIN_UPDATE_2026_SUPPLEMENT_WITHIN_LOO=run to enable it.",
      call. = FALSE
    )
  }

  result <- compute_mundlak_full_file_integrated_loo(
    fit_record = fit_record,
    loo_draws = loo_draws,
    k_threshold = k_threshold,
    cores = cores,
    family = "supplement_within",
    slope_description = "within_contrast_basis_slopes"
  )

  if (
    !inherits(result$loo, "loo") ||
      !inherits(result$conditional_loo, "loo") ||
      !identical(unname(as.character(result$family)),
                 "supplement_within") ||
      !identical(result$remedy, "integrated_observation_level_psis")
  ) {
    stop("Cannot archive an invalid supplement within-study LOO result.",
         call. = FALSE)
  }

  output_dir <- file.path(output_root, result$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf(
      "model_%02d_integrated_loo.qs",
      as.integer(result$model_index)
    )
  )
  write_atomic_qs(result, output_file)
}

