update_2026_supplement_within_exact_fit_file_path <- function(record) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "within", "loo", "exact_fit", record$outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf(
      "model_%02d_case_%03d_observation_%04d.qs",
