make_update_2026_supplement_within_exact_remedy_config <- function(
    exact_config,
    adapt_delta = 0.9995,
    seed_offset = 1000L
) {
  config <- exact_config
  config$adapt_delta_floor <- max(
    as.numeric(exact_config$adapt_delta_floor),
    as.numeric(adapt_delta)
  )
  config$seed <- as.integer(exact_config$seed + seed_offset)

  if (
    config$chains != 4L || config$parallel_chains != 4L ||
      config$iter_warmup != 2000L || config$iter_sampling != 6000L ||
      config$adapt_delta_floor != 0.9995 ||
      config$max_treedepth_floor != 15L
  ) {
    stop(
      "The supplement within-study exact-remedy configuration is invalid.",
      call. = FALSE
    )
  }

  config
}

select_update_2026_supplement_within_exact_remedy_records <- function(
    records,
    exact_audit
) {
  failed <- exact_audit$diagnostic_summary |>
    dplyr::filter(!.data$diagnostic_pass) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )

  failed_keys <- paste(
    failed$outcome,
    failed$model_index,
    failed$observation,
    sep = "::"
  )
  expected_keys <- c(
    "hypertrophy::12::153",
    "hypertrophy::14::153",
    "hypertrophy::24::153",
    "function::14::115"
  )

  if (
    exact_audit$exact_refits != 31L ||
      exact_audit$exact_refits_requiring_remediation != 4L ||
      nrow(failed) != 4L ||
      !identical(failed_keys, expected_keys) ||
      !identical(
        as.integer(failed$divergent_transitions),
        c(1L, 1L, 2L, 1L)
      ) ||
      any(failed$maximum_treedepth_transitions != 0L) ||
      !all(failed$convergence_pass)
  ) {
    stop(
      "The supplement within-study exact remedies no longer match the audit.",
      call. = FALSE
    )
  }

  selected <- purrr::keep(records, function(record) {
    paste(
      record$outcome,
      as.integer(record$model_index),
      as.integer(record$observation),
      sep = "::"
    ) %in% expected_keys
  })

  selected_keys <- purrr::map_chr(selected, function(record) {
    paste(
      record$outcome,
      as.integer(record$model_index),
      as.integer(record$observation),
      sep = "::"
    )
  })

  selected_case_ids <- purrr::map_int(
    selected,
    ~ as.integer(.x$case_id)
  )
  if (
    length(selected) != 4L ||
      !identical(selected_keys, expected_keys) ||
      !identical(selected_case_ids, c(8L, 10L, 16L, 26L))
  ) {
    stop(
      "Could not uniquely select the four supplement exact-remedy records.",
      call. = FALSE
    )
  }

  names(selected) <- sprintf(
    "case_%03d_%s_model_%02d_observation_%04d",
    selected_case_ids,
    purrr::map_chr(selected, ~ .x$outcome),
    purrr::map_int(selected, ~ as.integer(.x$model_index)),
    purrr::map_int(selected, ~ as.integer(.x$observation))
  )
  selected
}

validate_update_2026_supplement_within_exact_remedy_inputs <- function(
    records,
    config
) {
  if (!is.list(records) || length(records) != 4L) {
    stop("Expected four supplement within-study exact-remedy records.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    candidate <- read_sensitivity_fit_file(record$original_fit_path)
    integrated <- qs::qread(record$integrated_loo_path)
    observation <- as.integer(record$observation)
    observed_k <- as.numeric(
      loo::pareto_k_values(integrated$loo)[[observation]]
    )
    effective_adapt_delta <- max(
      as.numeric(candidate$specification$adapt_delta),
      as.numeric(config$adapt_delta_floor)
    )
    effective_max_treedepth <- max(
      as.integer(candidate$specification$max_treedepth),
      as.integer(config$max_treedepth_floor)
    )
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = observation,
      remedy = "adapt_delta_0.9995_after_exact_refit",
      adapt_delta = effective_adapt_delta,
      max_treedepth = effective_max_treedepth,
      iter_warmup = as.integer(config$iter_warmup),
      iter_sampling = as.integer(config$iter_sampling),
      chains = as.integer(config$chains),
      parallel_chains = as.integer(config$parallel_chains),
      pareto_k = observed_k,
      original_fit_exists = file.exists(record$original_fit_path),
      integrated_loo_exists = file.exists(record$integrated_loo_path),
      valid =
        identical(unname(as.character(candidate$family)),
                  "supplement_within") &&
        identical(unname(as.character(integrated$family)),
                  "supplement_within") &&
        is.finite(observed_k) && observed_k > 0.7
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    checks$case_id,
    checks$outcome,
    checks$model_index,
    checks$observation,
    sep = "::"
  )
  expected_keys <- c(
    "8::hypertrophy::12::153",
    "10::hypertrophy::14::153",
    "16::hypertrophy::24::153",
    "26::function::14::115"
  )

  if (
    nrow(checks) != 4L ||
      !identical(observed_keys, expected_keys) ||
      any(checks$adapt_delta != 0.9995) ||
      any(checks$max_treedepth != 15L) ||
      any(checks$iter_warmup != 2000L) ||
      any(checks$iter_sampling != 6000L) ||
      any(checks$chains != 4L) ||
      any(checks$parallel_chains != 4L) ||
      !all(checks$original_fit_exists) ||
      !all(checks$integrated_loo_exists) ||
      !all(checks$valid)
  ) {
    stop(
      "The supplement within-study exact-remedy preflight is invalid.",
      call. = FALSE
    )
  }

  checks
}

