make_update_2026_supplement_within_exact_second_remedy_config <- function(
    remedy_config,
    iter_warmup = 3000L,
    iter_sampling = 8000L,
    adapt_delta = 0.9999,
    max_treedepth = 16L,
    seed_offset = 1000L
) {
  config <- remedy_config
  config$iter_warmup <- as.integer(iter_warmup)
  config$iter_sampling <- as.integer(iter_sampling)
  config$adapt_delta_floor <- as.numeric(adapt_delta)
  config$max_treedepth_floor <- as.integer(max_treedepth)
  config$seed <- as.integer(remedy_config$seed + seed_offset)

  if (
    config$chains != 4L || config$parallel_chains != 4L ||
      config$iter_warmup != 3000L || config$iter_sampling != 8000L ||
      config$adapt_delta_floor != 0.9999 ||
      config$max_treedepth_floor != 16L ||
      config$iter_warmup <= remedy_config$iter_warmup ||
      config$iter_sampling <= remedy_config$iter_sampling ||
      config$adapt_delta_floor <= remedy_config$adapt_delta_floor
  ) {
    stop(
      paste0(
        "The supplement within-study exact second-remedy configuration ",
        "is invalid."
      ),
      call. = FALSE
    )
  }

  config
}

select_update_2026_supplement_within_exact_second_remedy_records <- function(
    records,
    remedy_audit
) {
  failed <- remedy_audit$diagnostic_summary |>
    dplyr::filter(!.data$diagnostic_pass) |>
    dplyr::arrange(case_id)
  failed_keys <- paste(
    failed$case_id,
    failed$outcome,
    failed$model_index,
    failed$observation,
    sep = "::"
  )
  expected_keys <- c(
    "10::hypertrophy::14::153",
    "16::hypertrophy::24::153"
  )

  if (
    remedy_audit$exact_refits != 4L ||
      remedy_audit$exact_refits_requiring_remediation != 2L ||
      nrow(failed) != 2L ||
      !identical(failed_keys, expected_keys) ||
      !identical(
        as.integer(failed$divergent_transitions),
        c(2L, 1L)
      ) ||
      any(failed$maximum_treedepth_transitions != 0L) ||
      !all(failed$convergence_pass)
  ) {
    stop(
      paste0(
        "The supplement within-study exact second remedies no longer ",
        "match the first-remedy audit."
      ),
      call. = FALSE
    )
  }

  selected <- purrr::keep(records, function(record) {
    paste(
      as.integer(record$case_id),
      record$outcome,
      as.integer(record$model_index),
      as.integer(record$observation),
      sep = "::"
    ) %in% expected_keys
  })

  selected_keys <- purrr::map_chr(selected, function(record) {
    paste(
      as.integer(record$case_id),
      record$outcome,
      as.integer(record$model_index),
      as.integer(record$observation),
      sep = "::"
    )
  })

  if (length(selected) != 2L || !identical(selected_keys, expected_keys)) {
    stop(
      "Could not uniquely select the two supplement second-remedy records.",
      call. = FALSE
    )
  }

  names(selected) <- c(
    "case_010_hypertrophy_model_14_observation_0153",
    "case_016_hypertrophy_model_24_observation_0153"
  )
  selected
}

validate_update_2026_supplement_within_exact_second_remedy_inputs <-
    function(records, config) {
  if (!is.list(records) || length(records) != 2L) {
    stop("Expected two supplement exact second-remedy records.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    candidate <- read_sensitivity_fit_file(record$original_fit_path)
    integrated <- qs::qread(record$integrated_loo_path)
    observation <- as.integer(record$observation)
    observed_k <- as.numeric(
      loo::pareto_k_values(integrated$loo)[[observation]]
    )
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = observation,
      remedy = "extended_adaptation_after_exact_remedy_1",
      adapt_delta = max(
        as.numeric(candidate$specification$adapt_delta),
        as.numeric(config$adapt_delta_floor)
      ),
      max_treedepth = max(
        as.integer(candidate$specification$max_treedepth),
        as.integer(config$max_treedepth_floor)
      ),
      iter_warmup = as.integer(config$iter_warmup),
      iter_sampling = as.integer(config$iter_sampling),
      chains = as.integer(config$chains),
      parallel_chains = as.integer(config$parallel_chains),
      pareto_k = observed_k,
      original_fit_exists = file.exists(record$original_fit_path),
      integrated_loo_exists = file.exists(record$integrated_loo_path),
      valid =
        identical(unname(as.character(candidate$family)),
                  "supplement_within") &&
        identical(unname(as.character(integrated$family)),
                  "supplement_within") &&
        is.finite(observed_k) && observed_k > 0.7
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    checks$case_id,
    checks$outcome,
    checks$model_index,
    checks$observation,
    sep = "::"
  )
  expected_keys <- c(
    "10::hypertrophy::14::153",
    "16::hypertrophy::24::153"
  )

  if (
    nrow(checks) != 2L || !identical(observed_keys, expected_keys) ||
      any(checks$adapt_delta != 0.9999) ||
      any(checks$max_treedepth != 16L) ||
      any(checks$iter_warmup != 3000L) ||
      any(checks$iter_sampling != 8000L) ||
      any(checks$chains != 4L) ||
      any(checks$parallel_chains != 4L) ||
      !all(checks$original_fit_exists) ||
      !all(checks$integrated_loo_exists) ||
      !all(checks$valid)
  ) {
    stop(
      "The supplement exact second-remedy preflight is invalid.",
      call. = FALSE
    )
  }

  checks
}

