make_update_2026_supplement_within_final_exact_audit <- function(
    records,
    initial_fit_paths,
    remedy_fit_paths,
    second_remedy_fit_paths,
    initial_audit,
    remedy_audit,
    second_remedy_audit
) {
  if (!is.list(records) || length(records) != 31L) {
    stop("The supplement final exact registry requires 31 records.",
         call. = FALSE)
  }

  record_manifest <- purrr::map_dfr(records, function(record) {
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = as.integer(record$observation)
    )
  }) |>
    dplyr::arrange(case_id)

  path_manifest <- function(paths, stage, expected) {
    paths <- unname(unlist(paths, use.names = FALSE))
    case_id <- as.integer(stringr::str_match(
      basename(paths),
      "case_([0-9]+)_observation_[0-9]+\\.qs$"
    )[, 2])
    output <- tibble::tibble(
      case_id = case_id,
      exact_fit_path = normalizePath(
        paths,
        winslash = "/",
        mustWork = TRUE
      ),
      stage = stage
    ) |>
      dplyr::arrange(case_id)
    if (
      nrow(output) != expected || anyNA(output$case_id) ||
        anyDuplicated(output$case_id) ||
        any(file.info(output$exact_fit_path)$size <= 0)
    ) {
      stop("A supplement exact-fit path registry is invalid.",
           call. = FALSE)
    }
    output
  }

  initial_paths <- path_manifest(initial_fit_paths, "initial", 31L)
  remedy_paths <- path_manifest(remedy_fit_paths, "remedy_1", 4L)
  second_paths <- path_manifest(
    second_remedy_fit_paths,
    "remedy_2",
    2L
  )
  accepted_paths <- initial_paths |>
    dplyr::filter(!case_id %in% remedy_paths$case_id) |>
    dplyr::bind_rows(remedy_paths) |>
    dplyr::filter(!case_id %in% second_paths$case_id) |>
    dplyr::bind_rows(second_paths) |>
    dplyr::arrange(case_id)
  accepted_manifest <- record_manifest |>
    dplyr::left_join(
      accepted_paths,
      by = "case_id",
      relationship = "one-to-one"
    ) |>
    dplyr::mutate(
      bytes = file.info(exact_fit_path)$size,
      sha256 = purrr::map_chr(
        exact_fit_path,
        ~ digest::digest(
          file = .x,
          algo = "sha256",
          serialize = FALSE
        )
      )
    )

  case_lookup <- record_manifest |>
    dplyr::select(case_id, outcome, model_index, observation)
  initial_summary <- initial_audit$diagnostic_summary |>
    dplyr::left_join(
      case_lookup,
      by = c("outcome", "model_index", "observation"),
      relationship = "one-to-one"
    ) |>
    dplyr::relocate(case_id)
  remedy_summary <- remedy_audit$diagnostic_summary
  second_summary <- second_remedy_audit$diagnostic_summary
  diagnostic_summary <- initial_summary |>
    dplyr::filter(!case_id %in% remedy_summary$case_id) |>
    dplyr::bind_rows(remedy_summary) |>
    dplyr::filter(!case_id %in% second_summary$case_id) |>
    dplyr::bind_rows(second_summary) |>
    dplyr::left_join(
      accepted_manifest |>
        dplyr::select(case_id, stage),
      by = "case_id",
      relationship = "one-to-one"
    ) |>
    dplyr::arrange(case_id)

  stage_counts <- table(accepted_manifest$stage)
  if (
    initial_audit$exact_refits != 31L ||
      initial_audit$exact_refits_requiring_remediation != 4L ||
      remedy_audit$exact_refits != 4L ||
      remedy_audit$exact_refits_requiring_remediation != 2L ||
      second_remedy_audit$exact_refits != 2L ||
      !isTRUE(second_remedy_audit$all_exact_refit_diagnostics_pass) ||
      nrow(accepted_manifest) != 31L ||
      !identical(accepted_manifest$case_id, seq_len(31L)) ||
      !identical(unname(stage_counts["initial"]), 27L) ||
      !identical(unname(stage_counts["remedy_1"]), 2L) ||
      !identical(unname(stage_counts["remedy_2"]), 2L) ||
      anyNA(accepted_manifest$exact_fit_path) ||
      any(accepted_manifest$bytes <= 0) ||
      any(nchar(accepted_manifest$sha256) != 64L) ||
      nrow(diagnostic_summary) != 31L ||
      !identical(diagnostic_summary$case_id, seq_len(31L)) ||
      anyDuplicated(diagnostic_summary$case_id) ||
      !all(diagnostic_summary$diagnostic_pass)
  ) {
    stop("The supplement within-study final exact audit is invalid.",
         call. = FALSE)
  }

  list(
    family = "supplement_within",
    diagnostic_summary = diagnostic_summary,
    accepted_exact_fit_manifest = accepted_manifest,
    exact_refits = 31L,
    exact_refits_passing = 31L,
    exact_refits_requiring_remediation = 0L,
    all_exact_refit_diagnostics_pass = TRUE
  )
}

write_update_2026_supplement_within_final_exact_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "within", "loo_exact", "final"
    )
) {
  if (
    !identical(audit$family, "supplement_within") ||
      audit$exact_refits != 31L ||
      nrow(audit$diagnostic_summary) != 31L ||
      nrow(audit$accepted_exact_fit_manifest) != 31L ||
      !isTRUE(audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("Cannot write an incomplete supplement final exact audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    accepted_exact_fit_manifest = file.path(
      output_dir,
      "accepted_exact_fit_manifest.csv"
    )
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$accepted_exact_fit_manifest,
    paths[["accepted_exact_fit_manifest"]],
    na = ""
  )
  unname(paths)
}

