compute_update_2026_supplement_within_exact_correction_to_file <- function(
    record,
    diagnostic_audit,
    enabled
) {
  if (!isTRUE(enabled)) {
    stop("Supplement within-study exact correction is disabled.",
         call. = FALSE)
  }

  exact_fit_path <- unname(as.character(record$exact_fit_path))
  refit <- read_sensitivity_full_exact_loo_file(
    exact_fit_path,
    "supplement_within"
  )
  output_file <-
    update_2026_supplement_within_exact_correction_file_path(refit)

  if (file.exists(output_file) && file.info(output_file)$size > 0) {
    archived <- tryCatch(qs::qread(output_file), error = function(error) NULL)
    if (
      !is.null(archived) && inherits(archived$loo, "loo") &&
        as.integer(archived$case_id) == as.integer(refit$case_id) &&
        identical(archived$outcome, refit$outcome) &&
        as.integer(archived$model_index) == as.integer(refit$model_index) &&
        as.integer(archived$exact_refit_summary$observation[[1L]]) ==
          as.integer(refit$observation)
    ) {
      return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
    }
    stop("An existing supplement-within exact correction is invalid.",
         call. = FALSE)
  }

  correction <- compute_sensitivity_full_exact_loo_file(
    path = exact_fit_path,
    diagnostic_audit = diagnostic_audit,
    family = "supplement_within"
  )
  if (
    !inherits(correction$loo, "loo") ||
      as.integer(correction$case_id) != as.integer(refit$case_id) ||
      nrow(correction$exact_refit_summary) != 1L ||
      !isTRUE(correction$exact_refit_summary$diagnostic_pass[[1L]])
  ) {
    stop("The supplement within-study exact correction is invalid.",
         call. = FALSE)
  }

  write_atomic_qs(correction, output_file)
}

audit_update_2026_supplement_within_exact_correction_files <- function(
    paths,
    integrated_audit
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  expected <- as.integer(integrated_audit$exact_refits_required)

  if (
    length(paths) != expected || expected != 31L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The supplement within-study exact corrections are incomplete.",
         call. = FALSE)
  }

  corrections <- purrr::map(paths, qs::qread)
  diagnostic_summary <- purrr::map_dfr(
    corrections,
    "exact_refit_summary"
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )

  manifest <- purrr::map2_dfr(paths, corrections, function(path, result) {
    tibble::tibble(
      case_id = as.integer(result$case_id),
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      model_name = result$model_name,
      observation =
        as.integer(result$exact_refit_summary$observation[[1L]]),
      correction_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      bytes = file.info(path)$size,
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    manifest$outcome,
    manifest$model_index,
    manifest$observation,
    sep = "::"
  )
  expected_keys <- paste(
    integrated_audit$high_k_cases$outcome,
    integrated_audit$high_k_cases$model_index,
    integrated_audit$high_k_cases$observation,
    sep = "::"
  )

  if (
    nrow(diagnostic_summary) != 31L || nrow(manifest) != 31L ||
      anyDuplicated(observed_keys) || !setequal(observed_keys, expected_keys) ||
      !identical(manifest$case_id, seq_len(31L)) ||
      !all(diagnostic_summary$diagnostic_pass)
  ) {
    stop("The supplement-within exact-correction audit is invalid.",
         call. = FALSE)
  }

  list(
    diagnostic_summary = diagnostic_summary,
    correction_manifest = manifest,
    exact_refits = 31L,
    exact_refits_passing = sum(diagnostic_summary$diagnostic_pass),
    exact_refits_requiring_remediation =
      sum(!diagnostic_summary$diagnostic_pass),
    all_exact_refit_diagnostics_pass =
      all(diagnostic_summary$diagnostic_pass)
  )
}

write_update_2026_supplement_within_exact_correction_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "within", "loo_exact", "corrections"
    )
) {
  if (
    audit$exact_refits != 31L ||
      nrow(audit$diagnostic_summary) != 31L ||
      nrow(audit$correction_manifest) != 31L
  ) {
    stop("Cannot write an incomplete supplement-within correction audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    correction_manifest = file.path(output_dir, "correction_manifest.csv")
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$correction_manifest,
    paths[["correction_manifest"]],
    na = ""
  )
  unname(paths)
}

read_update_2026_supplement_within_exact_corrections <- function(manifest) {
  if (
    !is.data.frame(manifest) || nrow(manifest) != 31L ||
      any(!file.exists(manifest$correction_path))
  ) {
    stop("The supplement-within correction manifest is invalid.",
         call. = FALSE)
  }

  corrections <- purrr::map(manifest$correction_path, qs::qread)
  corrections <- corrections[order(purrr::map_int(corrections, "case_id"))]
  if (
    !identical(
      unname(purrr::map_int(corrections, "case_id")),
      seq_len(31L)
    ) ||
      any(!purrr::map_lgl(corrections, ~ inherits(.x$loo, "loo")))
  ) {
    stop("The supplement-within exact corrections are invalid.",
         call. = FALSE)
  }

  corrections
}

make_update_2026_supplement_within_final_loo_audit <- function(
    integrated_manifest,
    exact_corrections,
    exact_audit
) {
  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (!isTRUE(exact_audit$all_exact_refit_diagnostics_pass)) {
    stop("Final supplement-within LOO requires passing exact refits.",
         call. = FALSE)
  }
  final <- apply_sensitivity_full_exact_loo_corrections_from_files(
    integrated_manifest = integrated_manifest,
    exact_results = exact_corrections,
    family = "supplement_within",
    expected_models = 72L,
    expected_indices = retained
  )
  outcome_summary <- final$model_summary |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_unresolved_high_k =
        sum(n_pareto_k_gt_threshold > 0L),
      unresolved_high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_remaining_pareto_k = max(maximum_pareto_k, na.rm = TRUE),
      .by = outcome
    )

  correction_counts <- exact_audit$diagnostic_summary |>
    dplyr::count(outcome, model_index, name = "exact_corrections")
  final_manifest <- integrated_manifest |>
    dplyr::left_join(
      correction_counts,
      by = c("outcome", "model_index")
    ) |>
    dplyr::mutate(
      exact_corrections = tidyr::replace_na(exact_corrections, 0L),
      final_method = dplyr::if_else(
        exact_corrections > 0L,
        "integrated_observation_level_psis_plus_exact",
        "integrated_observation_level_psis"
      )
    )

  if (
    !isTRUE(final$stacking_ready) || nrow(final$model_summary) != 72L ||
      nrow(outcome_summary) != 4L || any(outcome_summary$models != 18L) ||
      any(outcome_summary$unresolved_high_k_cases != 0L) ||
      nrow(final_manifest) != 72L ||
      sum(final_manifest$exact_corrections) != 31L
  ) {
    stop("The final supplement-within LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  final$family <- "supplement_within"
  final$outcome_summary <- outcome_summary
  final$final_loo_manifest <- final_manifest
  final$exact_refits <- 31L
  final$all_exact_refit_diagnostics_pass <- TRUE
  final
}

write_update_2026_supplement_within_final_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "within", "loo_final"
    )
) {
  if (
    !isTRUE(audit$stacking_ready) ||
      nrow(audit$model_summary) != 72L ||
      nrow(audit$outcome_summary) != 4L ||
      nrow(audit$exact_refit_summary) != 31L ||
      nrow(audit$final_loo_manifest) != 72L
  ) {
    stop("Cannot write an incomplete final supplement-within LOO audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    final_loo_manifest = file.path(output_dir, "final_loo_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    exact_refit_summary = file.path(output_dir, "exact_refit_summary.csv")
  )
  readr::write_csv(audit$final_loo_manifest, paths[["final_loo_manifest"]])
  readr::write_csv(audit$model_summary, paths[["model_summary"]])
  readr::write_csv(audit$outcome_summary, paths[["outcome_summary"]])
  readr::write_csv(
    audit$exact_refit_summary,
    paths[["exact_refit_summary"]]
  )
  unname(paths)
}

make_update_2026_supplement_within_prediction_records <- function(
    accepted_fit_manifest,
    stacking_weights,
    n_draws = 4000L,
    exposure_minimum_g_day = 0,
    grid_step_g_day = 1,
    seed = 188988L
) {
  records <- make_update_2026_total_within_prediction_records(
    accepted_fit_manifest = accepted_fit_manifest,
    stacking_weights = stacking_weights,
    n_draws = n_draws,
    exposure_minimum_g_day = exposure_minimum_g_day,
    grid_step_g_day = grid_step_g_day,
    seed = seed
  )

  records <- purrr::map(records, function(record) {
    record$family <- "supplement_within"
    record$prediction_type <- "supplement_within"
    record
  })
  table <- dplyr::bind_rows(records)
  audit <- table |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      allocated_draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )

  if (
    nrow(audit) != 4L || any(audit$selected_models < 1L) ||
      any(audit$allocated_draws != 4000L) ||
      any(audit$retained_weight <= 0) ||
      any(audit$retained_weight > 1 + 1e-8) ||
      any(table$family != "supplement_within") ||
      any(table$prediction_type != "supplement_within") ||
      any(table$exposure_minimum_g_day != 0) ||
      any(table$grid_step_g_day != 1)
  ) {
    stop("The supplement within-study prediction allocation is incomplete.",
         call. = FALSE)
  }

  records
}

make_update_2026_supplement_within_reporting_preflight <- function(
    records,
    data_by_outcome
) {
  checks <- make_update_2026_total_within_reporting_preflight(
    records = records,
    data_by_outcome = data_by_outcome
  )
  record_table <- dplyr::bind_rows(records)

  if (
    any(record_table$family != "supplement_within") ||
      any(record_table$prediction_type != "supplement_within") ||
      any(checks$exposure_minimum_g_day != 0) ||
      any(checks$reference_g_day != 0) ||
      any(checks$internal_unit_g_day != 25) ||
      any(checks$grid_step_g_day != 1) ||
      !all(checks$valid)
  ) {
    stop("The supplement within-study reporting preflight failed.",
         call. = FALSE)
  }

  checks
}

write_update_2026_supplement_within_reporting_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "within", "reporting", "input_preflight.csv"
    )
) {
  if (
    !all(checks$valid) ||
      any(tapply(checks$allocated_draws, checks$outcome, sum) != 4000L)
  ) {
    stop("Cannot write an invalid supplement-within reporting preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

make_update_2026_supplement_within_prediction_grid <- function(
    fitted_candidate,
    data,
    exposure_minimum_g_day = 0,
    grid_step_g_day = 1,
    reference_g_day = 0
) {
  grid <- make_update_2026_total_within_prediction_grid(
    fitted_candidate = fitted_candidate,
    data = data,
    exposure_minimum_g_day = exposure_minimum_g_day,
    grid_step_g_day = grid_step_g_day,
    reference_g_day = reference_g_day
  )
  grid$newdata$supplement_g_day <- grid$keys$protein_intake_g_day

  if (
    grid$reference_g_day != 0 || grid$unit_g_day != 25 ||
      grid$protein_min != 0
  ) {
    stop("The supplement within-study prediction grid is invalid.",
         call. = FALSE)
  }

  grid
}

update_2026_supplement_within_reporting_path <- function(
    outcome,
    stage,
    model_index = NULL
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "within", "reporting", stage, outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  filename <- if (is.null(model_index)) {
    paste0(stage, ".qs")
  } else {
    sprintf("model_%02d_%s.qs", as.integer(model_index), stage)
  }
  file.path(directory, filename)
}

write_update_2026_supplement_within_prediction_draw_file <- function(
    record,
    data_by_outcome,
    result_path
) {
  if (
    length(record$fit_path) != 1L || is.na(record$fit_path) ||
      !file.exists(record$fit_path) || record$draw_count < 1L ||
      !identical(as.character(record$family), "supplement_within") ||
      !identical(as.character(record$prediction_type),
                 "supplement_within")
  ) {
    stop("A supplement within-study prediction record is invalid.",
         call. = FALSE)
  }

  candidate <- read_sensitivity_fit_file(record$fit_path)
  if (
    !identical(unname(as.character(candidate$family)),
               "supplement_within") ||
      !identical(
        unname(as.character(candidate$outcome)),
        as.character(record$outcome)
      ) ||
      as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(candidate$model_name, as.character(record$model_name))
  ) {
    stop("A supplement-within fit does not match its prediction record.",
         call. = FALSE)
  }

  prediction_data <- data_by_outcome[[record$outcome]]
  if (is.null(prediction_data) || !is.data.frame(prediction_data)) {
    stop("The supplement within-study prediction data are unavailable.",
         call. = FALSE)
  }
  grid <- make_update_2026_supplement_within_prediction_grid(
    fitted_candidate = candidate,
    data = prediction_data,
    exposure_minimum_g_day = record$exposure_minimum_g_day,
    grid_step_g_day = record$grid_step_g_day,
    reference_g_day = 0
  )
  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  set.seed(as.integer(record$prediction_seed))
  draws <- as.matrix(brms::posterior_epred(
    candidate$model,
    newdata = grid$newdata,
    re_formula = NA,
    ndraws = as.integer(record$draw_count)
  ))

  if (ncol(draws) != nrow(grid$keys) && nrow(draws) == nrow(grid$keys)) {
    draws <- t(draws)
  }
  if (
    nrow(draws) != as.integer(record$draw_count) ||
      ncol(draws) != nrow(grid$keys) || anyNA(draws)
  ) {
    stop("Supplement-within predictions do not match their allocation.",
         call. = FALSE)
  }

  reduction <- list(
    family = "supplement_within",
    outcome = as.character(record$outcome),
    model_index = as.integer(record$model_index),
    model_name = as.character(record$model_name),
    weight = as.numeric(record$weight),
    draw_count = as.integer(record$draw_count),
    prediction_seed = as.integer(record$prediction_seed),
    fit_sha256 = as.character(record$fit_sha256),
    grid = grid$keys,
    draws = draws,
    settings = list(
      protein_min = grid$protein_min,
      protein_max = grid$protein_max,
      grid_step = grid$grid_step,
      reference_intake = grid$reference_g_day,
      internal_unit_g_day = grid$unit_g_day,
      prediction_type = "supplement_within"
    )
  )

  write_atomic_qs(reduction, result_path)
}

make_update_2026_supplement_within_model_average_records <- function(
    prediction_manifest,
