) {
  write_update_2026_total_within_reporting_audit(
    audit = audit,
    prediction_manifest = prediction_manifest,
    family = "supplement_within",
    output_dir = output_dir
  )
}

make_update_2026_supplement_within_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    data_by_outcome,
    specifications,
    accepted_fit_manifest,
    diagnostic_audit,
    integrated_loo_audit,
    final_exact_audit,
    exact_correction_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  expected_rows <- c(
    whole_body = 134L,
    hypertrophy = 229L,
    strength = 330L,
    `function` = 122L
  )
  expected_studies <- c(
    whole_body = 63L,
    hypertrophy = 40L,
    strength = 65L,
    `function` = 26L
  )
  expected_pairs <- c(
    whole_body = 106L,
    hypertrophy = 72L,
    strength = 104L,
    `function` = 40L
  )
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  matched_pairs <- vapply(data_by_outcome, function(data) {
    dplyr::n_distinct(interaction(
      data$study_no,
      data$protein_arm_no,
      data$comparator_arm_no,
      drop = TRUE
    ))
  }, integer(1L))

  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  specification_keys <- registry_keys(specification_table)
  diagnostic_keys <- registry_keys(diagnostic_audit$diagnostic_summary)
  fit_keys <- registry_keys(accepted_fit_manifest)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, fit_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- specification_table |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      diagnostic_audit$diagnostic_summary |>
        dplyr::select(outcome, model_index, diagnostic_name = model),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  weight_sums <- stacking_weights |>
    dplyr::summarise(models = dplyr::n(), weight_sum = sum(weight), .by = outcome)
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )
  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "supplement_within"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  correction_manifest <- exact_correction_audit$correction_manifest
  accepted_exact_manifest <- final_exact_audit$accepted_exact_fit_manifest
  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      "all four supplement within-study datasets are valid",
      "all five final registries contain the same 72 model keys",
      "model names agree across specifications fits diagnostics LOO and weights",
      "all 72 accepted fit files exist and have checksums",
      "all accepted-fit sampling diagnostics pass",
      "initial LOO contains 72 aligned models and 31 high-k cases",
      "all 31 accepted exact-refit sampling diagnostics pass",
      "all 31 compact exact corrections exist and have checksums",
      "final LOO contains 72 models and no unresolved high-k cases",
      "four stacking vectors contain 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      "all four supplement within-study reporting audits pass"
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      identical(names(data_by_outcome), outcomes) &&
        identical(vapply(data_by_outcome, nrow, integer(1L)), expected_rows) &&
        identical(
          vapply(
            data_by_outcome,
            function(data) dplyr::n_distinct(data$study_no),
            integer(1L)
          ),
          expected_studies
        ) &&
        identical(matched_pairs, expected_pairs) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0) &&
        all(is.finite(analysis_data$mean_body_mass_kg)) &&
        all(analysis_data$absolute_exposure_reference_g_day == 0) &&
        all(analysis_data$absolute_exposure_unit_g_day == 25),
      common_registry && length(specification_keys) == 72L,
      nrow(name_alignment) == 72L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(name_alignment$diagnostic_name == name_alignment$specification_name) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(accepted_fit_manifest) == 72L &&
        sum(accepted_fit_manifest$stage == "initial") == 68L &&
        sum(accepted_fit_manifest$stage == "remedy_1") == 4L &&
        all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(accepted_fit_manifest$bytes > 0) &&
        all(nchar(accepted_fit_manifest$sha256) == 64L),
      identical(diagnostic_audit$family, "supplement_within") &&
        diagnostic_audit$models == 72L &&
        isTRUE(diagnostic_audit$all_sampling_diagnostics_pass) &&
        all(diagnostic_audit$diagnostic_summary$diagnostic_pass),
      identical(integrated_loo_audit$family, "supplement_within") &&
        integrated_loo_audit$models == 72L &&
        sum(integrated_loo_audit$model_summary$method ==
              "integrated_observation_level_psis") == 72L &&
        sum(integrated_loo_audit$model_summary$method ==
              "conditional_observation_level_psis") == 72L &&
        integrated_loo_audit$exact_refits_required == 31L &&
        nrow(integrated_loo_audit$high_k_cases) == 31L,
      identical(final_exact_audit$family, "supplement_within") &&
        final_exact_audit$exact_refits == 31L &&
        final_exact_audit$exact_refits_passing == 31L &&
        isTRUE(final_exact_audit$all_exact_refit_diagnostics_pass) &&
        nrow(accepted_exact_manifest) == 31L &&
        sum(accepted_exact_manifest$stage == "initial") == 27L &&
        sum(accepted_exact_manifest$stage == "remedy_1") == 2L &&
        sum(accepted_exact_manifest$stage == "remedy_2") == 2L &&
        all(file.exists(accepted_exact_manifest$exact_fit_path)) &&
        all(nchar(accepted_exact_manifest$sha256) == 64L),
      nrow(correction_manifest) == 31L &&
        all(file.exists(correction_manifest$correction_path)) &&
        all(correction_manifest$bytes > 0) &&
        all(nchar(correction_manifest$sha256) == 64L),
      identical(final_loo_audit$family, "supplement_within") &&
        nrow(final_loo_audit$model_summary) == 72L &&
        final_loo_audit$exact_refits == 31L &&
        isTRUE(final_loo_audit$stacking_ready) &&
        all(final_loo_audit$outcome_summary$unresolved_high_k_cases == 0L),
      nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        sum(prediction_sums$selected_models) == 21L &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      identical(reporting_audit$family, "supplement_within") &&
        isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Updated supplement within-study verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    preparation_outcome_counts = preparation_audit$outcome_counts,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    absolute_exposure_provenance = absolute_audit$exposure_provenance,
    absolute_support_by_outcome = absolute_audit$support_by_outcome,
    absolute_scaling_plan = absolute_audit$scaling_plan,
    absolute_model_registry = absolute_audit$model_registry,
    absolute_family_plan = absolute_audit$family_plan,
    analysis_data = analysis_data,
    model_specifications = specification_table,
    model_name_alignment = name_alignment,
    accepted_fit_manifest = accepted_fit_manifest,
    sampling_diagnostic_summary = diagnostic_audit$diagnostic_summary,
    sampling_parameter_failures = diagnostic_audit$parameter_failures,
    initial_integrated_loo_model_summary = integrated_loo_audit$model_summary,
    initial_integrated_loo_outcome_summary = integrated_loo_audit$outcome_summary,
    initial_high_pareto_k_cases = integrated_loo_audit$high_k_cases,
    accepted_exact_fit_manifest = accepted_exact_manifest,
    exact_refit_diagnostic_summary = final_exact_audit$diagnostic_summary,
    exact_correction_manifest = correction_manifest,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    exact_refit_summary = final_loo_audit$exact_refit_summary,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    paste(
      "Frozen supplement within-study verification artifact:",
      names(artifacts)
    ),
    names(artifacts)
  )
  list(
    checks = checks,
    artifacts = artifacts,
    descriptions = descriptions,
    next_family = paste(
      "The supplement within-study family is frozen after this verification",
      "checkpoint; its lean-pruning plan can then be audited."
    )
  )
}

make_update_2026_supplement_within_pruning_plan <- function(
    accepted_fit_manifest,
    final_exact_audit,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "within"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "supplement_within_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (any(!file.exists(verification_files))) {
    stop("The supplement within-study verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  verification_index <- readr::read_csv(
    verification_manifest,
    show_col_types = FALSE
  )

  if (length(verification_files) != nrow(verification_index) + 2L) {
    stop("The supplement within-study verification-file count is invalid.",
         call. = FALSE)
  }
  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "within"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the supplement within-study archive.",
         call. = FALSE)
  }
  fit_roots <- file.path(archive_root, c("initial", "remedy_1"))
  exact_roots <- file.path(
    archive_root,
    "loo",
    c("exact_fit", "exact_remedy", "exact_remedy_2")
  )

  if (any(!dir.exists(c(fit_roots, exact_roots)))) {
    stop("An expected supplement within-study fit directory is missing.",
         call. = FALSE)
  }
  fit_paths <- unlist(purrr::map(fit_roots, ~ list.files(
    .x, pattern = "\\.qs$", recursive = TRUE, full.names = TRUE
  )), use.names = FALSE) |>
    normalizePath(winslash = "/", mustWork = TRUE)
  accepted_paths <- normalizePath(
    accepted_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )

  if (
    length(fit_paths) != 76L || length(accepted_paths) != 72L ||
      anyDuplicated(fit_paths) || anyDuplicated(accepted_paths) ||
      !all(accepted_paths %in% fit_paths) ||
      sum(!fit_paths %in% accepted_paths) != 4L
  ) {
    stop("Supplement within-study fit retention does not match its lineage.",
         call. = FALSE)
  }

  model_fit_manifest <- tibble::tibble(
    path = fit_paths,
    relative_path = substring(fit_paths, nchar(resolved_root) + 2L),
    archive_stage = dplyr::case_when(
      grepl("/initial/", fit_paths, fixed = TRUE) ~ "initial",
      grepl("/remedy_1/", fit_paths, fixed = TRUE) ~ "remedy_1",
      TRUE ~ "unknown"
    ),
    outcome = basename(dirname(fit_paths)),
    model_index = as.integer(sub(
      "^model_([0-9]+)\\.qs$", "\\1", basename(fit_paths)
    )),
    accepted_fit = fit_paths %in% accepted_paths,
    bytes = as.numeric(file.info(fit_paths)$size),
    lean_action = "delete frozen supplement within-study model fit"
  ) |>
    dplyr::arrange(archive_stage, outcome, model_index)

  fit_stage_counts <- table(factor(
    model_fit_manifest$archive_stage,
    levels = c("initial", "remedy_1")
  ))
  if (
    any(model_fit_manifest$archive_stage == "unknown") ||
      anyNA(model_fit_manifest$model_index) ||
      !identical(as.integer(fit_stage_counts), c(72L, 4L)) ||
      sum(model_fit_manifest$accepted_fit) != 72L ||
      sum(!model_fit_manifest$accepted_fit) != 4L ||
      any(model_fit_manifest$bytes <= 0)
  ) {
    stop("The supplement within-study model-fit stages are not as expected.",
         call. = FALSE)
  }

  exact_paths <- unlist(purrr::map(exact_roots, ~ list.files(
    .x, pattern = "\\.qs$", recursive = TRUE, full.names = TRUE
  )), use.names = FALSE) |>
    normalizePath(winslash = "/", mustWork = TRUE)
  exact_match <- stringr::str_match(
    basename(exact_paths),
    "^model_([0-9]+)_case_([0-9]+)_observation_([0-9]+)\\.qs$"
  )
  accepted_exact_paths <- normalizePath(
    final_exact_audit$accepted_exact_fit_manifest$exact_fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  exact_refit_manifest <- tibble::tibble(
    path = exact_paths,
    relative_path = substring(exact_paths, nchar(resolved_root) + 2L),
    archive_stage = dplyr::case_when(
      grepl("/exact_fit/", exact_paths, fixed = TRUE) ~ "initial",
      grepl("/exact_remedy/", exact_paths, fixed = TRUE) ~ "remedy_1",
      grepl("/exact_remedy_2/", exact_paths, fixed = TRUE) ~ "remedy_2",
      TRUE ~ "unknown"
    ),
    outcome = basename(dirname(exact_paths)),
    model_index = as.integer(exact_match[, 2L]),
    case_id = as.integer(exact_match[, 3L]),
    observation = as.integer(exact_match[, 4L]),
    accepted_fit = exact_paths %in% accepted_exact_paths,
    bytes = as.numeric(file.info(exact_paths)$size),
    lean_action = "delete frozen supplement within-study exact-deletion refit"
  ) |>
    dplyr::arrange(archive_stage, case_id)

  exact_stage_counts <- table(factor(
    exact_refit_manifest$archive_stage,
    levels = c("initial", "remedy_1", "remedy_2")
  ))
  if (
    nrow(exact_refit_manifest) != 37L ||
      any(exact_refit_manifest$archive_stage == "unknown") ||
      anyNA(exact_refit_manifest[c("model_index", "case_id", "observation")]) ||
      !identical(as.integer(exact_stage_counts), c(31L, 4L, 2L)) ||
      length(accepted_exact_paths) != 31L ||
      !all(accepted_exact_paths %in% exact_paths) ||
      sum(exact_refit_manifest$accepted_fit) != 31L ||
      any(exact_refit_manifest$bytes <= 0) ||
      !isTRUE(final_exact_audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("The supplement within-study exact-refit inventory is invalid.",
         call. = FALSE)
  }

  deletion_manifest <- dplyr::bind_rows(
    model_fit_manifest |>
      dplyr::mutate(
        artifact_role = dplyr::if_else(
          accepted_fit, "accepted_model_fit", "superseded_model_fit"
        ),
        case_id = NA_integer_,
        observation = NA_integer_
      ),
    exact_refit_manifest |>
      dplyr::mutate(
        artifact_role = dplyr::if_else(
          accepted_fit, "accepted_exact_refit", "superseded_exact_refit"
        )
      )
  ) |>
    dplyr::select(
      path, relative_path, archive_stage, artifact_role, outcome,
      model_index, case_id, observation, accepted_fit, bytes, lean_action
    )

  compact_roots <- c(
    loo_psis = file.path(archive_root, "loo", "integrated"),
    exact_corrections = file.path(archive_root, "loo", "exact_correction"),
    reporting = file.path(archive_root, "reporting")
  )
  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact supplement within-study directory is missing.",
         call. = FALSE)
  }

  compact_paths <- unlist(purrr::map(compact_roots, ~ list.files(
    .x, recursive = TRUE, full.names = TRUE, all.files = TRUE
  )), use.names = FALSE)
  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  normalized_compact_roots <- normalizePath(
    compact_roots,
    winslash = "/",
    mustWork = TRUE
  )
  component <- vapply(compact_paths, function(path) {
    matches <- names(compact_roots)[vapply(
      normalized_compact_roots,
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact supplement within-study result"
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo_psis", "exact_corrections", "reporting")
  ))
  if (
    nrow(compact_manifest) != 132L ||
      !identical(as.integer(compact_counts), c(72L, 31L, 29L)) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact supplement within-study archive is incomplete.",
         call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    full_fit_archives_deleted = nrow(deletion_manifest),
    accepted_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "accepted_model_fit"
    ),
    superseded_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "superseded_model_fit"
    ),
    accepted_exact_refit_archives_deleted = sum(
      deletion_manifest$artifact_role == "accepted_exact_refit"
    ),
    superseded_exact_refit_archives_deleted = sum(
      deletion_manifest$artifact_role == "superseded_exact_refit"
    ),
    full_fit_archives_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained = sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, corrected LOO, and all 72 weights remain frozen;",
      "restoring model or exact-refit objects requires refitting the",
      "supplement within-study family."
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_fit_manifest,
    exact_refit_manifest = exact_refit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_supplement_within_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "within", "pruning"
    )
) {
  if (
    nrow(plan$model_fit_manifest) != 76L ||
      nrow(plan$exact_refit_manifest) != 37L ||
      nrow(plan$deletion_file_manifest) != 113L ||
      nrow(plan$compact_archive_manifest) != 132L
  ) {
    stop("Cannot write an invalid supplement within-study pruning plan.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    exact_refit_manifest = file.path(output_dir, "exact_refit_manifest.csv"),
    deletion_file_manifest = file.path(
      output_dir, "deletion_file_manifest.csv"
    ),
    compact_archive_manifest = file.path(
      output_dir, "compact_archive_manifest.csv"
    )
  )

  readr::write_csv(plan$summary, paths[["summary"]])
  readr::write_csv(plan$model_fit_manifest, paths[["model_fit_manifest"]])
  readr::write_csv(plan$exact_refit_manifest, paths[["exact_refit_manifest"]])
  readr::write_csv(
    plan$deletion_file_manifest,
    paths[["deletion_file_manifest"]]
  )
  readr::write_csv(
    plan$compact_archive_manifest,
    paths[["compact_archive_manifest"]]
  )
  unname(paths)
}

# Absolute total-intake achieved common-sample sensitivity ----

# Prepare the achieved total-intake rows for comparisons that also require an
# assignment-derived dose.
make_update_2026_total_achieved_data_by_outcome <- function(
    total_primary_data_by_outcome
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  if (!identical(names(total_primary_data_by_outcome), outcomes)) {
    stop("The total achieved-intake source registry is invalid.",
         call. = FALSE)
  }

  data <- purrr::map(total_primary_data_by_outcome, function(outcome_data) {
    required <- c(
      "study_no", "arm_no", "mean_body_mass_kg", "total_g_day",
      "assignment_total_g_day",
      "protein_intake_raw", "protein_intake",
      "absolute_exposure_reference_g_day",
      "absolute_exposure_unit_g_day"
    )
    if (!all(required %in% names(outcome_data))) {
      stop("A total achieved-intake source is incomplete.", call. = FALSE)
    }
    output <- outcome_data |>
      dplyr::filter(
        is.finite(total_g_day),
        total_g_day > 0,
        is.finite(mean_body_mass_kg),
        mean_body_mass_kg > 0,
        is.finite(assignment_total_g_day),
        assignment_total_g_day > 0
      ) |>
      dplyr::mutate(
        total_achieved_common_sample = TRUE,
        assignment_exposure_g_day = assignment_total_g_day
      ) |>
      droplevels()
    if (
      !nrow(output) ||
        any(abs(output$protein_intake_raw - output$total_g_day) > 1e-8) ||
        any(output$absolute_exposure_reference_g_day != 78.785) ||
        any(output$absolute_exposure_unit_g_day != 50)
    ) {
      stop("A total achieved-intake common sample is invalid.",
           call. = FALSE)
    }
    output
  })

  expected_rows <- c(
    whole_body = 182L,
    hypertrophy = 328L,
    strength = 546L,
    `function` = 200L
  )
  expected_studies <- c(
    whole_body = 60L,
    hypertrophy = 43L,
    strength = 63L,
    `function` = 26L
  )

  if (
    !identical(vapply(data, nrow, integer(1L)), expected_rows) ||
      !identical(
        vapply(
          data,
          function(x) dplyr::n_distinct(x$study_no),
          integer(1L)
        ),
        expected_studies
      ) ||
      any(vapply(data, function(x) {
        any(!x$total_achieved_common_sample) ||
          any(!is.finite(x$assignment_exposure_g_day))
      }, logical(1L)))
  ) {
    stop("The total achieved-intake common samples are incomplete.",
         call. = FALSE)
  }

  data
}

make_update_2026_total_achieved_specifications <- function(
    total_primary_specifications
) {
  specifications <- dplyr::bind_rows(total_primary_specifications)
  historical_longer_keys <- c(
    "hypertrophy::11", "hypertrophy::14", "hypertrophy::18",
    "hypertrophy::23", "strength::6", "function::14"
  )
  specifications <- specifications |>
    dplyr::mutate(
      key = paste(outcome, model_index, sep = "::"),
      family = "total_achieved",
      exposure = "total_g_day",
      common_sample = TRUE,
      historical_schedule = dplyr::if_else(
        key %in% historical_longer_keys,
        "longer_sampling",
        "base"
      ),
      historical_relative_achieved_remedy =
        key %in% historical_longer_keys,
      adapt_delta = dplyr::if_else(
        historical_relative_achieved_remedy,
        pmax(as.numeric(adapt_delta), 0.999),
        as.numeric(adapt_delta)
      ),
      max_treedepth = dplyr::if_else(
        historical_relative_achieved_remedy,
        pmax(as.integer(max_treedepth), 15L),
        as.integer(max_treedepth)
      ),
      iter_warmup = dplyr::if_else(
        historical_schedule == "longer_sampling",
        2000L,
        1500L
      ),
      iter_sampling = dplyr::if_else(
        historical_schedule == "longer_sampling",
        4000L,
        2000L
      ),
      chains = 4L,
      parallel_chains = 4L,
      model_name = paste0(model_name, " [total_achieved]")
    ) |>
    dplyr::select(-key)

  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  counts <- table(factor(specifications$outcome, levels = c(
    "whole_body", "hypertrophy", "strength", "function"
  )))
  schedule_counts <- table(factor(
    specifications$historical_schedule,
    levels = c("base", "longer_sampling")
  ))
  keys <- paste(specifications$outcome, specifications$model_index, sep = "::")

  if (
    nrow(specifications) != 72L || anyDuplicated(keys) ||
      !identical(as.integer(counts), rep(18L, 4L)) ||
      !all(specifications$model_index %in% retained) ||
      !identical(as.integer(schedule_counts), c(66L, 6L)) ||
      !setequal(
        keys[specifications$historical_relative_achieved_remedy],
        historical_longer_keys
      ) ||
      any(specifications$chains != 4L) ||
      any(specifications$parallel_chains != 4L)
  ) {
    stop("The total achieved-intake specification registry is invalid.",
         call. = FALSE)
  }

  output <- purrr::pmap(specifications, list)
  names(output) <- paste0(
    specifications$outcome,
    "_model_",
    stringr::str_pad(specifications$model_index, 2L, pad = "0")
  )
  output
}

update_2026_total_achieved_local_config <- function(specification, config) {
  local_config <- config
  local_config$iter_warmup <- as.integer(specification$iter_warmup)
  local_config$iter_sampling <- as.integer(specification$iter_sampling)
  local_config$adapt_delta_floor <- max(
    as.numeric(config$adapt_delta_floor),
    as.numeric(specification$adapt_delta)
  )
  local_config$max_treedepth_floor <- max(
    as.integer(config$max_treedepth_floor),
    as.integer(specification$max_treedepth)
  )
  outcome_offset <- match(specification$outcome, config$outcomes)

  if (is.na(outcome_offset)) {
    stop("Unknown outcome in the total achieved-intake configuration.",
         call. = FALSE)
  }
  local_config$seed <- as.integer(
    config$seed + 100L * (outcome_offset - 1L) +
      as.integer(specification$model_index)
  )
  local_config
}

prepare_update_2026_total_achieved_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome,
    config
) {
  local_config <- update_2026_total_achieved_local_config(
    specification,
    config
  )
  input <- prepare_update_2026_total_primary_input(
    specification = specification,
    data_by_outcome = data_by_outcome,
    priors_by_outcome = priors_by_outcome
  )
  input$family <- "total_achieved"
  input$specification$family <- "total_achieved"
  input$specification$sensitivity_exposure_definition <-
    "achieved_common_sample"
  input$specification$sensitivity_exposure_sampling <- paste0(
    local_config$iter_warmup,
    "_warmup_",
    local_config$iter_sampling,
    "_sampling"
  )
  input
}

validate_update_2026_total_achieved_inputs <- function(
    specifications,
    data_by_outcome,
    priors_by_outcome,
    config
) {
  checks <- purrr::map_dfr(specifications, function(specification) {
    input <- prepare_update_2026_total_achieved_input(
      specification,
      data_by_outcome,
      priors_by_outcome,
      config
    )
    local_config <- update_2026_total_achieved_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      family = input$family,
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      historical_schedule = specification$historical_schedule,
      common_sample = isTRUE(specification$common_sample),
      includes_moderators = isTRUE(specification$includes_moderators),
      body_mass_in_formula =
        stringr::str_detect(input$formula, "\\bbody_mass_outcome_z\\b"),
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      arms = dplyr::n_distinct(input$data$arm_no),
      exposure_minimum_g_day = min(input$data$protein_intake_raw),
      exposure_maximum_g_day = max(input$data$protein_intake_raw),
      assignment_minimum_g_day = min(input$data$assignment_exposure_g_day),
      assignment_maximum_g_day = max(input$data$assignment_exposure_g_day),
      reference_g_day = unique(
        input$data$absolute_exposure_reference_g_day
      ),
      internal_unit_g_day = unique(
        input$data$absolute_exposure_unit_g_day
      ),
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  outcome_counts <- table(factor(checks$outcome, levels = c(
    "whole_body", "hypertrophy", "strength", "function"
  )))
  schedule_counts <- table(factor(
    checks$historical_schedule,
    levels = c("base", "longer_sampling")
  ))
  sample_audit <- checks |>
    dplyr::summarise(
      contrast_values = dplyr::n_distinct(contrasts),
      contrasts = dplyr::first(contrasts),
      study_values = dplyr::n_distinct(studies),
      studies = dplyr::first(studies),
      .by = outcome
    )

  expected_rows <- c(
    whole_body = 182L,
    hypertrophy = 328L,
    strength = 546L,
    `function` = 200L
  )
  expected_studies <- c(
    whole_body = 60L,
    hypertrophy = 43L,
    strength = 63L,
    `function` = 26L
  )

  if (
    nrow(checks) != 72L || anyDuplicated(keys) || !all(checks$valid) ||
      any(checks$family != "total_achieved") ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !identical(as.integer(schedule_counts), c(66L, 6L)) ||
      any(!checks$common_sample) || nrow(sample_audit) != 4L ||
      any(sample_audit$contrast_values != 1L) ||
      any(sample_audit$study_values != 1L) ||
      any(sample_audit$contrasts != expected_rows[sample_audit$outcome]) ||
      any(sample_audit$studies != expected_studies[sample_audit$outcome]) ||
      any(checks$includes_moderators & !checks$body_mass_in_formula) ||
      any(!checks$includes_moderators & checks$body_mass_in_formula) ||
      any(checks$exposure_minimum_g_day <= 0) ||
      any(checks$exposure_maximum_g_day <=
            checks$exposure_minimum_g_day) ||
      any(checks$assignment_minimum_g_day <= 0) ||
      any(checks$assignment_maximum_g_day <=
            checks$assignment_minimum_g_day) ||
      any(checks$reference_g_day != 78.785) ||
      any(checks$internal_unit_g_day != 50) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The total achieved-intake input preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_achieved_input_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "achieved_common_sample", "input_preflight.csv"
    )
) {
  if (nrow(checks) != 72L || !all(checks$valid)) {
    stop("Cannot write an invalid total achieved-intake preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

fit_update_2026_total_achieved_candidate_to_file <- function(
    input,
    config,
    enabled,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "achieved_common_sample", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop("Total achieved-intake fitting is disabled.", call. = FALSE)
  }
  if (
    !identical(input$family, "total_achieved") ||
      !identical(input$specification$family, "total_achieved") ||
      !isTRUE(input$specification$common_sample)
  ) {
    stop("The total achieved-intake fit input is invalid.", call. = FALSE)
  }

  local_config <- update_2026_total_achieved_local_config(
    input$specification,
    config
  )
  candidate <- fit_sensitivity_brms_pilot(
    input = input,
    enabled = TRUE,
    config = local_config,
    family = "total_achieved"
  )
  output_dir <- file.path(output_root, candidate$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d.qs", as.integer(candidate$model_index))
  )
  temporary <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary, force = TRUE), add = TRUE)
  qs::qsave(candidate, temporary, preset = "high")

  if (!file.copy(temporary, output_file, overwrite = TRUE)) {
    stop("Could not finalise a total achieved-intake fit.",
         call. = FALSE)
  }
  unlink(temporary, force = TRUE)
  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

make_update_2026_total_achieved_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  expected_key <- "whole_body::15"
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  parameter_failures <- diagnostic_audit$parameter_failures |>
    dplyr::filter(
      outcome == "whole_body",
      model_index == 15L
    )

  if (
    !identical(diagnostic_audit$family, "total_achieved") ||
      nrow(failed) != 1L || failed$key[[1L]] != expected_key ||
      !isTRUE(failed$geometry_pass[[1L]]) ||
      isTRUE(failed$convergence_pass[[1L]]) ||
      failed$divergent_transitions[[1L]] != 0L ||
      failed$maximum_treedepth_transitions[[1L]] != 0L ||
      nrow(parameter_failures) != 1L ||
      parameter_failures$variable[[1L]] != "sd_outcome_no__Intercept" ||
      parameter_failures$rhat[[1L]] <= 1.01
  ) {
    stop("The total achieved-intake remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(specifications, function(specification) {
    paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    ) == expected_key
  })

  if (length(selected) != 1L) {
    stop("Could not uniquely select total achieved-intake model 15.",
         call. = FALSE)
  }
  remedy <- selected[[1L]]
  remedy$iter_warmup <- 2000L
  remedy$iter_sampling <- 4000L
  remedy$remedy <- "double_sampling_after_convergence_failure"
  remedy$archive_stage <- "remedy_1"
  remedy$remedy_reason <- paste(
    "Sampling geometry, ESS, and MCSE passed, but R-hat exceeded 1.01",
    "for sd_outcome_no__Intercept."
  )
  list(whole_body_model_15 = remedy)
}

validate_update_2026_total_achieved_remedy_inputs <- function(
    inputs,
    initial_fit_paths,
    config
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    expected_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    local_config <- update_2026_total_achieved_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      arms = dplyr::n_distinct(input$data$arm_no),
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      initial_fit_exists =
        length(expected_path) == 1L && file.exists(expected_path),
      valid = TRUE
    )
  })

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  if (
    nrow(checks) != 1L || !identical(keys, "whole_body::15") ||
      checks$remedy[[1L]] !=
        "double_sampling_after_convergence_failure" ||
      checks$contrasts[[1L]] != 182L || checks$studies[[1L]] != 60L ||
      checks$iter_warmup[[1L]] != 2000L ||
      checks$iter_sampling[[1L]] != 4000L ||
      checks$chains[[1L]] != 4L || checks$parallel_chains[[1L]] != 4L ||
      !checks$initial_fit_exists[[1L]] || !checks$valid[[1L]]
  ) {
    stop("The total achieved-intake remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

