combine_update_2026_total_achieved_remedy_diagnostics <- function(
    initial_diagnostics,
    remedy_diagnostics
) {
  diagnostic_key <- function(x) {
    paste(x$summary$outcome[[1L]], x$summary$model_index[[1L]], sep = "::")
  }

  if (length(initial_diagnostics) != 72L || length(remedy_diagnostics) != 1L) {
    stop("The total achieved-intake remedy diagnostics are incomplete.",
         call. = FALSE)
  }
  initial_keys <- purrr::map_chr(initial_diagnostics, diagnostic_key)
  remedy_keys <- purrr::map_chr(remedy_diagnostics, diagnostic_key)
  failed_keys <- initial_diagnostics |>
    purrr::keep(~ !.x$summary$diagnostic_pass[[1L]]) |>
    purrr::map_chr(diagnostic_key)

  if (
    anyDuplicated(initial_keys) || anyDuplicated(remedy_keys) ||
      !setequal(remedy_keys, "whole_body::15") ||
      !setequal(remedy_keys, failed_keys) ||
      !all(remedy_keys %in% initial_keys)
  ) {
    stop("The total achieved-intake diagnostic replacement is invalid.",
         call. = FALSE)
  }

  final_diagnostics <- initial_diagnostics
  final_diagnostics[match(remedy_keys, initial_keys)] <- remedy_diagnostics
  compile_update_2026_total_primary_diagnostic_audit(
    final_diagnostics,
    family = "total_achieved"
  )
}

make_update_2026_total_achieved_accepted_fit_manifest <- function(
    initial_manifest,
    remedy_fit_paths,
    final_diagnostic_audit
) {
  remedy_paths <- unname(unlist(remedy_fit_paths, use.names = FALSE))

  if (
    nrow(initial_manifest) != 72L || length(remedy_paths) != 1L ||
      any(!file.exists(remedy_paths)) ||
      any(file.info(remedy_paths)$size <= 0) ||
      !identical(final_diagnostic_audit$family, "total_achieved") ||
      !isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass)
  ) {
    stop("Accepted total achieved-intake fits require 72 passing diagnostics.",
         call. = FALSE)
  }

  remedy <- tibble::tibble(
    outcome = basename(dirname(remedy_paths)),
    model_index = as.integer(stringr::str_match(
      basename(remedy_paths), "model_([0-9]+)\\.qs$"
    )[, 2]),
    fit_path = normalizePath(remedy_paths, winslash = "/", mustWork = TRUE),
    stage = "remedy_1",
    bytes = file.info(remedy_paths)$size,
    sha256 = purrr::map_chr(
      remedy_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    )
  ) |>
    dplyr::left_join(
      initial_manifest |>
        dplyr::select(outcome, model_index, model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::select(
      outcome, model_index, model_name, fit_path, stage, bytes, sha256
    )

  remedy_key <- paste(remedy$outcome, remedy$model_index, sep = "::")
  accepted <- initial_manifest |>
    dplyr::anti_join(
      remedy |> dplyr::select(outcome, model_index),
      by = c("outcome", "model_index")
    ) |>
    dplyr::bind_rows(remedy) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  if (
    nrow(remedy) != 1L || !identical(remedy_key, "whole_body::15") ||
      nrow(accepted) != 72L ||
      anyDuplicated(accepted[c("outcome", "model_index")]) ||
      any(table(accepted$outcome) != 18L) ||
      sum(accepted$stage == "initial") != 71L ||
      sum(accepted$stage == "remedy_1") != 1L ||
      !all(stringr::str_ends(
        accepted$model_name,
        stringr::fixed(" [total_achieved]")
      )) ||
      !all(file.exists(accepted$fit_path)) ||
      any(accepted$bytes <= 0) || any(nchar(accepted$sha256) != 64L)
  ) {
    stop("The accepted total achieved-intake manifest is invalid.",
         call. = FALSE)
  }

  accepted
}

validate_update_2026_total_achieved_loo_inputs <- function(
    accepted_fit_manifest,
    final_diagnostic_audit,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  stage_counts <- table(accepted_fit_manifest$stage)
  outcome_counts <- table(accepted_fit_manifest$outcome)
  checks <- tibble::tribble(
    ~check, ~passed,
    "all 72 final achieved-intake sampling diagnostics pass",
    identical(final_diagnostic_audit$family, "total_achieved") &&
      isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass),
    "accepted registry contains 18 models per outcome",
    length(outcome_counts) == 4L && all(outcome_counts == 18L),
    "accepted registry contains 71 initial and 1 remedy fit",
    identical(unname(stage_counts["initial"]), 71L) &&
      identical(unname(stage_counts["remedy_1"]), 1L),
    "all accepted fit files exist and are nonempty",
    all(file.exists(accepted_fit_manifest$fit_path)) &&
      all(file.info(accepted_fit_manifest$fit_path)$size > 0),
    "all accepted fit hashes and achieved-intake model names are present",
    all(nchar(accepted_fit_manifest$sha256) == 64L) &&
      all(stringr::str_ends(
        accepted_fit_manifest$model_name,
        stringr::fixed(" [total_achieved]")
      ))
  )

  ready <-
    nrow(accepted_fit_manifest) == 72L &&
    !anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) &&
    all(checks$passed) && identical(k_threshold, 0.7) &&
    identical(as.integer(cores_per_branch), 1L)
  if (!ready) {
    stop("The total achieved-intake LOO preflight is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_achieved",
    models = 72L,
    k_threshold = k_threshold,
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    ready = TRUE
  )
}

make_update_2026_total_achieved_loo_records <- function(
    accepted_fit_manifest
) {
  required <- c(
    "outcome", "model_index", "model_name", "fit_path", "stage"
  )

  if (
    !all(required %in% names(accepted_fit_manifest)) ||
      nrow(accepted_fit_manifest) != 72L ||
      anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) ||
      !all(file.exists(accepted_fit_manifest$fit_path))
  ) {
    stop("The total achieved-intake LOO fit manifest is invalid.",
         call. = FALSE)
  }

  records <- purrr::map(
    seq_len(nrow(accepted_fit_manifest)),
    ~ purrr::map(
      as.list(accepted_fit_manifest[.x, required, drop = FALSE]),
      unname
    )
  )
  names(records) <- paste0(
    accepted_fit_manifest$outcome,
    "_model_",
    stringr::str_pad(accepted_fit_manifest$model_index, 2L, pad = "0")
  )
  records
}

compute_update_2026_total_achieved_integrated_loo_to_file <- function(
    fit_record,
    enabled,
    loo_draws = 4000L,
    k_threshold = 0.7,
    cores = 1L,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "achieved_common_sample", "loo", "integrated"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      "Total achieved-intake LOO is disabled. Set ",
      "PROTEIN_UPDATE_2026_TOTAL_ACHIEVED_LOO=run to enable it.",
      call. = FALSE
    )
  }

  fit_path <- fit_record$fit_path
  if (
    length(fit_path) != 1L || is.na(fit_path) || !file.exists(fit_path)
  ) {
    stop("The total achieved-intake LOO fit is unavailable.",
         call. = FALSE)
  }

  candidate <- read_sensitivity_fit_file(fit_path)
  if (
    !identical(unname(as.character(candidate$family)), "total_achieved") ||
      !identical(candidate$outcome, fit_record$outcome) ||
      !identical(
        as.integer(candidate$model_index),
        as.integer(fit_record$model_index)
      ) ||
      !identical(candidate$model_name, fit_record$model_name) ||
      !inherits(candidate$model, "brmsfit")
  ) {
    stop("The total achieved-intake fit does not match its LOO record.",
         call. = FALSE)
  }

  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  draw_ids <- make_sensitivity_loo_draw_ids(
    brms::ndraws(candidate$model),
    min(as.integer(loo_draws), as.integer(brms::ndraws(candidate$model)))
  )
  conditional_loo <- brms::loo(
    candidate$model,
    draw_ids = draw_ids,
    pointwise = FALSE,
    moment_match = FALSE,
    reloo = FALSE,
    cores = as.integer(cores)
  )

  result <- compute_sensitivity_exposure_integrated_psis_loo(
    job = list(
      fitted_candidate = candidate,
      conditional_loo = conditional_loo,
      loo_draws = length(draw_ids)
    ),
    family = "total_achieved",
    k_threshold = k_threshold,
    cores = cores
  )

  result$family <- "total_achieved"
  result$fit_record <- fit_record
  result$loo_draws <- length(draw_ids)
  if (
    !inherits(result$loo, "loo") ||
      !inherits(result$conditional_loo, "loo") ||
      !identical(unname(as.character(result$family)), "total_achieved") ||
      !identical(result$remedy, "integrated_observation_level_psis")
  ) {
    stop("Cannot archive an invalid total achieved-intake LOO result.",
         call. = FALSE)
  }

  output_dir <- file.path(output_root, result$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf(
      "model_%02d_integrated_loo.qs",
      as.integer(result$model_index)
    )
  )
  write_atomic_qs(result, output_file)
}

