    stop("Cannot write an invalid total assignment-derived preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

fit_update_2026_total_assignment_candidate_to_file <- function(
    input,
    config,
    enabled,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop("Total assignment-derived fitting is disabled.", call. = FALSE)
  }
  if (
    !identical(input$family, "total_assignment") ||
      !identical(input$specification$family, "total_assignment") ||
      !isTRUE(input$specification$common_sample)
  ) {
    stop("The total assignment-derived fit input is invalid.",
         call. = FALSE)
  }

  local_config <- update_2026_total_assignment_local_config(
    input$specification,
    config
  )
  candidate <- fit_sensitivity_brms_pilot(
    input = input,
    enabled = TRUE,
    config = local_config,
    family = "total_assignment"
  )
  output_dir <- file.path(output_root, candidate$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d.qs", as.integer(candidate$model_index))
  )
  temporary <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary, force = TRUE), add = TRUE)
  qs::qsave(candidate, temporary, preset = "high")

  if (!file.copy(temporary, output_file, overwrite = TRUE)) {
    stop("Could not finalise a total assignment-derived fit.",
         call. = FALSE)
  }
  unlink(temporary, force = TRUE)
  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

make_update_2026_total_assignment_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  expected_keys <- c(
    "whole_body::4",
    "hypertrophy::11",
    "strength::1", "strength::11", "strength::14", "strength::21",
    "strength::23", "strength::26",
    "function::4", "function::23"
  )
  expected_extended_keys <- c(
    "strength::11", "strength::14", "strength::23"
  )
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(
      key = paste(outcome, model_index, sep = "::"),
      extended_sampling =
        maximum_rhat >= 1.04 |
          minimum_bulk_ess < 200 |
          minimum_tail_ess < 200 |
          maximum_mcse_sd_ratio > 0.10
    )

  extended_keys <- failed$key[failed$extended_sampling]
  parameter_counts <- diagnostic_audit$parameter_failures |>
    dplyr::count(outcome, model_index, name = "parameter_failures") |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  if (
    !identical(diagnostic_audit$family, "total_assignment") ||
      nrow(failed) != 10L || anyDuplicated(failed$key) ||
      !setequal(failed$key, expected_keys) ||
      !setequal(extended_keys, expected_extended_keys) ||
      !all(failed$geometry_pass) || any(failed$convergence_pass) ||
      any(failed$divergent_transitions != 0L) ||
      any(failed$maximum_treedepth_transitions != 0L) ||
      nrow(parameter_counts) != 10L ||
      !setequal(parameter_counts$key, expected_keys) ||
      any(
        parameter_counts$parameter_failures[
          parameter_counts$key %in% expected_extended_keys
        ] < 100L
      )
  ) {
    stop("The total assignment-derived remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(specifications, function(specification) {
    paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    ) %in% expected_keys
  })
  selected <- purrr::map(selected, function(specification) {
    key <- paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    )
    specification$iter_warmup <- if (
      key %in% expected_extended_keys
    ) 3000L else 2000L
    specification$iter_sampling <- if (
      key %in% expected_extended_keys
    ) 8000L else 4000L
    specification$remedy <- if (
      key %in% expected_extended_keys
    ) {
      "extended_sampling_after_severe_convergence_failure"
    } else {
      "double_sampling_after_convergence_failure"
    }
    specification$archive_stage <- "remedy_1"
    specification$remedy_reason <- if (
      key %in% expected_extended_keys
    ) {
      paste(
        "Sampling geometry passed, but widespread R-hat, ESS, and MCSE",
        "failures require an extended convergence schedule."
      )
    } else {
      paste(
        "Sampling geometry passed, but one or more parameters did not",
        "meet the convergence thresholds."
      )
    }
    specification
  })

  selected_keys <- purrr::map_chr(selected, function(specification) {
    paste(specification$outcome, specification$model_index, sep = "::")
  })
  if (
    length(selected) != 10L || anyDuplicated(selected_keys) ||
      !setequal(selected_keys, expected_keys)
  ) {
    stop("Could not select the total assignment-derived remedies.",
         call. = FALSE)
  }

  selected
}

validate_update_2026_total_assignment_remedy_inputs <- function(
    inputs,
    initial_fit_paths,
    config
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    local_config <- update_2026_total_assignment_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    expected_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      arms = dplyr::n_distinct(input$data$arm_no),
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      initial_fit_exists =
        length(expected_path) == 1L && file.exists(expected_path),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  expected_keys <- c(
    "whole_body::4",
    "hypertrophy::11",
    "strength::1", "strength::11", "strength::14", "strength::21",
    "strength::23", "strength::26",
    "function::4", "function::23"
  )
  expected_extended_keys <- c(
    "strength::11", "strength::14", "strength::23"
  )
  extended <- keys %in% expected_extended_keys

  if (
    nrow(checks) != 10L || anyDuplicated(keys) ||
      !setequal(keys, expected_keys) || !all(checks$valid) ||
      !all(checks$initial_fit_exists) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      any(checks$iter_warmup[!extended] != 2000L) ||
      any(checks$iter_sampling[!extended] != 4000L) ||
      any(checks$iter_warmup[extended] != 3000L) ||
      any(checks$iter_sampling[extended] != 8000L) ||
      any(
        checks$remedy[!extended] !=
          "double_sampling_after_convergence_failure"
      ) ||
      any(
        checks$remedy[extended] !=
          "extended_sampling_after_severe_convergence_failure"
      )
  ) {
    stop("The total assignment-derived remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

