compile_update_2026_total_assignment_final_diagnostic_audit <- function(
    initial_diagnostics,
    remedy_diagnostics
) {
  diagnostic_key <- function(result) {
    paste(
      result$summary$outcome[[1L]],
      result$summary$model_index[[1L]],
      sep = "::"
    )
  }
  expected_remedy_keys <- c(
    "whole_body::4",
    "hypertrophy::11",
    "strength::1", "strength::11", "strength::14", "strength::21",
    "strength::23", "strength::26",
    "function::4", "function::23"
  )
  initial_keys <- purrr::map_chr(initial_diagnostics, diagnostic_key)
  remedy_keys <- purrr::map_chr(remedy_diagnostics, diagnostic_key)
  initial_failed <- purrr::map_lgl(
    initial_diagnostics,
    ~ !isTRUE(.x$summary$diagnostic_pass[[1L]])
  )
  initial_failed_keys <- initial_keys[initial_failed]

  if (
    length(initial_diagnostics) != 72L ||
      length(remedy_diagnostics) != 10L ||
      anyDuplicated(initial_keys) || anyDuplicated(remedy_keys) ||
      !setequal(remedy_keys, expected_remedy_keys) ||
      !setequal(initial_failed_keys, expected_remedy_keys) ||
      any(!remedy_keys %in% initial_keys)
  ) {
    stop("The total assignment-derived diagnostic replacement is invalid.",
         call. = FALSE)
  }

  final_diagnostics <- initial_diagnostics
  final_diagnostics[match(remedy_keys, initial_keys)] <- remedy_diagnostics
  compile_update_2026_total_primary_diagnostic_audit(
    diagnostics = final_diagnostics,
    family = "total_assignment"
  )
}

