compile_update_2026_total_assignment_second_final_diagnostic_audit <-
    function(
      initial_diagnostics,
      first_remedy_diagnostics,
      second_remedy_diagnostics,
      first_final_audit
    ) {
  diagnostic_key <- function(result) {
    paste(
      result$summary$outcome[[1L]],
      result$summary$model_index[[1L]],
      sep = "::"
    )
  }
  expected_first_keys <- c(
    "whole_body::4",
    "hypertrophy::11",
    "strength::1", "strength::11", "strength::14", "strength::21",
    "strength::23", "strength::26",
    "function::4", "function::23"
  )
  expected_second_keys <- c(
    "strength::11", "strength::23", "strength::26"
  )
  initial_keys <- purrr::map_chr(initial_diagnostics, diagnostic_key)
  first_keys <- purrr::map_chr(first_remedy_diagnostics, diagnostic_key)
  second_keys <- purrr::map_chr(second_remedy_diagnostics, diagnostic_key)
  first_final_failed <- first_final_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
    dplyr::pull(key)

  if (
    !identical(first_final_audit$family, "total_assignment") ||
      length(initial_diagnostics) != 72L ||
      length(first_remedy_diagnostics) != 10L ||
      length(second_remedy_diagnostics) != 3L ||
      anyDuplicated(initial_keys) || anyDuplicated(first_keys) ||
      anyDuplicated(second_keys) ||
      !setequal(first_keys, expected_first_keys) ||
      !setequal(second_keys, expected_second_keys) ||
      !setequal(first_final_failed, expected_second_keys) ||
      any(!first_keys %in% initial_keys) ||
      any(!second_keys %in% initial_keys)
  ) {
    stop(
      "The total assignment-derived second diagnostic replacement is invalid.",
      call. = FALSE
    )
  }

  final_diagnostics <- initial_diagnostics
  final_diagnostics[match(first_keys, initial_keys)] <-
    first_remedy_diagnostics
  final_diagnostics[match(second_keys, initial_keys)] <-
    second_remedy_diagnostics
  compile_update_2026_total_primary_diagnostic_audit(
    diagnostics = final_diagnostics,
    family = "total_assignment"
  )
}

make_update_2026_total_assignment_third_remedy_specifications <- function(
    second_remedy_specifications,
    diagnostic_audit
) {
  expected_keys <- c("strength::11", "strength::23", "strength::26")
  stabilization_keys <- c("strength::11", "strength::26")
  precision_key <- "strength::23"
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  parameter_counts <- diagnostic_audit$parameter_failures |>
    dplyr::count(outcome, model_index, name = "parameter_failures") |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))

  if (
    !identical(diagnostic_audit$family, "total_assignment") ||
      nrow(failed) != 3L || anyDuplicated(failed$key) ||
      !setequal(failed$key, expected_keys) ||
      sum(failed$divergent_transitions) != 1L ||
      failed$divergent_transitions[failed$key == "strength::11"] != 1L ||
      any(failed$maximum_treedepth_transitions != 0L) ||
      any(failed$convergence_pass) ||
      failed$geometry_pass[failed$key == "strength::11"] ||
      !all(failed$geometry_pass[failed$key != "strength::11"]) ||
      nrow(parameter_counts) != 3L ||
      !setequal(parameter_counts$key, expected_keys) ||
      any(
        parameter_counts$parameter_failures[
          parameter_counts$key %in% stabilization_keys
        ] < 100L
      ) ||
      parameter_counts$parameter_failures[
        parameter_counts$key == precision_key
      ] != 6L
  ) {
    stop("The total assignment-derived third-remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(
    second_remedy_specifications,
    function(specification) {
      paste(
        specification$outcome,
        specification$model_index,
        sep = "::"
      ) %in% expected_keys
    }
  )

  selected <- purrr::map(selected, function(specification) {
    key <- paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    )
    if (key %in% stabilization_keys) {
      specification$iter_warmup <- 6000L
      specification$iter_sampling <- 20000L
      specification$adapt_delta <- max(
        as.numeric(specification$adapt_delta),
        0.9999
      )
      specification$max_treedepth <- max(
        as.integer(specification$max_treedepth),
        16L
      )
      specification$remedy <-
        "stabilized_extended_sampling_after_persistent_failure"
      specification$remedy_reason <- paste(
        "Broad convergence failures persisted after two remedies; model 11",
        "also produced a divergent transition."
      )
    } else {
      specification$iter_warmup <- 4000L
      specification$iter_sampling <- 16000L
      specification$remedy <-
        "additional_sampling_after_precision_failure"
      specification$remedy_reason <- paste(
        "Only six tail-ESS and MCSE precision failures remained with clean",
        "geometry and R-hat."
      )
    }
    specification$archive_stage <- "remedy_3"
    specification
  })

  selected_keys <- purrr::map_chr(selected, function(specification) {
    paste(specification$outcome, specification$model_index, sep = "::")
  })
  if (
    length(selected) != 3L || anyDuplicated(selected_keys) ||
      !setequal(selected_keys, expected_keys)
  ) {
    stop("Could not select the total assignment-derived third remedies.",
         call. = FALSE)
  }

  selected
}

