compile_update_2026_total_assignment_third_final_diagnostic_audit <-
    function(
      initial_diagnostics,
      first_remedy_diagnostics,
      second_remedy_diagnostics,
      third_remedy_diagnostics,
      second_final_audit
    ) {
  diagnostic_key <- function(result) {
    paste(
      result$summary$outcome[[1L]],
      result$summary$model_index[[1L]],
      sep = "::"
    )
  }
  expected_first_keys <- c(
    "whole_body::4",
    "hypertrophy::11",
    "strength::1", "strength::11", "strength::14", "strength::21",
    "strength::23", "strength::26",
    "function::4", "function::23"
  )
  expected_later_keys <- c(
    "strength::11", "strength::23", "strength::26"
  )
  initial_keys <- purrr::map_chr(initial_diagnostics, diagnostic_key)
  first_keys <- purrr::map_chr(first_remedy_diagnostics, diagnostic_key)
  second_keys <- purrr::map_chr(second_remedy_diagnostics, diagnostic_key)
  third_keys <- purrr::map_chr(third_remedy_diagnostics, diagnostic_key)
  second_final_failed <- second_final_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
    dplyr::pull(key)

  if (
    !identical(second_final_audit$family, "total_assignment") ||
      length(initial_diagnostics) != 72L ||
      length(first_remedy_diagnostics) != 10L ||
      length(second_remedy_diagnostics) != 3L ||
      length(third_remedy_diagnostics) != 3L ||
      anyDuplicated(initial_keys) || anyDuplicated(first_keys) ||
      anyDuplicated(second_keys) || anyDuplicated(third_keys) ||
      !setequal(first_keys, expected_first_keys) ||
      !setequal(second_keys, expected_later_keys) ||
      !setequal(third_keys, expected_later_keys) ||
      !setequal(second_final_failed, expected_later_keys) ||
      any(!first_keys %in% initial_keys) ||
      any(!second_keys %in% initial_keys) ||
      any(!third_keys %in% initial_keys)
  ) {
    stop(
      "The total assignment-derived third diagnostic replacement is invalid.",
      call. = FALSE
    )
  }

  final_diagnostics <- initial_diagnostics
  final_diagnostics[match(first_keys, initial_keys)] <-
    first_remedy_diagnostics
  final_diagnostics[match(second_keys, initial_keys)] <-
    second_remedy_diagnostics
  final_diagnostics[match(third_keys, initial_keys)] <-
    third_remedy_diagnostics
  compile_update_2026_total_primary_diagnostic_audit(
    diagnostics = final_diagnostics,
    family = "total_assignment"
  )
}

make_update_2026_total_assignment_structural_exclusion_audit <- function(
    first_final_audit,
    second_final_audit,
    third_final_audit
) {
  audits <- list(
    remedy_1 = first_final_audit,
    remedy_2 = second_final_audit,
    remedy_3 = third_final_audit
  )
  expected_keys <- c("strength::11", "strength::23", "strength::26")

  if (any(!purrr::map_lgl(
    audits,
    ~ identical(.x$family, "total_assignment") &&
      nrow(.x$diagnostic_summary) == 72L
  ))) {
    stop("An assignment-derived exclusion diagnostic audit is invalid.",
         call. = FALSE)
  }

  parameter_counts <- purrr::imap_dfr(audits, function(audit, stage) {
    audit$parameter_failures |>
      dplyr::count(outcome, model_index, name = "parameter_failures") |>
      dplyr::mutate(stage = stage, .before = 1L)
  })
  history <- purrr::imap_dfr(audits, function(audit, stage) {
    audit$diagnostic_summary |>
      dplyr::filter(
        paste(outcome, model_index, sep = "::") %in% expected_keys
      ) |>
      dplyr::mutate(stage = stage, .before = 1L)
  }) |>
    dplyr::left_join(
      parameter_counts,
      by = c("stage", "outcome", "model_index")
    ) |>
    dplyr::mutate(
      stage = factor(
        stage,
        levels = c("remedy_1", "remedy_2", "remedy_3")
      )
    ) |>
    dplyr::arrange(model_index, stage) |>
    dplyr::mutate(stage = as.character(stage))

  history_keys <- paste(history$outcome, history$model_index, sep = "::")
  stage_counts <- table(factor(
    history$stage,
    levels = c("remedy_1", "remedy_2", "remedy_3")
  ))
  if (
    nrow(history) != 9L || anyNA(history$parameter_failures) ||
      !setequal(unique(history_keys), expected_keys) ||
      !identical(as.integer(stage_counts), rep(3L, 3L)) ||
      any(history$diagnostic_pass) ||
      any(history$parameter_failures <= 0L)
  ) {
    stop("The assignment-derived exclusion history is incomplete.",
         call. = FALSE)
  }

  summary <- history |>
    dplyr::filter(stage == "remedy_3") |>
    dplyr::transmute(
      outcome,
      model_index,
      model_name = model,
      exclusion = "structurally_non_estimable",
      shared_unstable_component =
        "study-specific factor-smooth exposure term",
      remedies_failed = 3L,
      persistent_parameter_failures = parameter_failures,
      final_divergent_transitions = divergent_transitions,
      final_maximum_rhat = maximum_rhat,
      final_minimum_bulk_ess = minimum_bulk_ess,
      final_minimum_tail_ess = minimum_tail_ess,
      final_maximum_mcse_sd_ratio = maximum_mcse_sd_ratio,
      preregistered_analysis_affected = FALSE,
      analysis_scope =
        "additional absolute assignment-derived sensitivity analysis",
      decision = paste(
        "Exclude from stacking after three diagnostic remedies failed;",
        "retain all fit archives and diagnostic history."
      )
    ) |>
    dplyr::arrange(model_index)

  summary_keys <- paste(summary$outcome, summary$model_index, sep = "::")
  if (
    nrow(summary) != 3L || !setequal(summary_keys, expected_keys) ||
      any(summary$preregistered_analysis_affected)
  ) {
    stop("The assignment-derived exclusion summary is invalid.",
         call. = FALSE)
  }

  list(
    family = "total_assignment",
    excluded_models = 3L,
    retained_models = 69L,
    excluded_keys = expected_keys,
    preregistered_analysis_affected = FALSE,
    exclusion_summary = summary,
    diagnostic_history = history,
    approved = TRUE
  )
}

write_update_2026_total_assignment_structural_exclusion_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "structural_exclusions"
    )
) {
  if (
    !isTRUE(audit$approved) || audit$excluded_models != 3L ||
      audit$retained_models != 69L ||
      nrow(audit$exclusion_summary) != 3L ||
      nrow(audit$diagnostic_history) != 9L ||
      isTRUE(audit$preregistered_analysis_affected)
  ) {
    stop("Cannot write an invalid assignment-derived exclusion audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    exclusion_summary = file.path(output_dir, "exclusion_summary.csv"),
    diagnostic_history = file.path(output_dir, "diagnostic_history.csv"),
    metadata = file.path(output_dir, "metadata.csv")
  )
  readr::write_csv(
    audit$exclusion_summary,
    paths[["exclusion_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$diagnostic_history,
    paths[["diagnostic_history"]],
    na = ""
  )
  readr::write_csv(
    tibble::tibble(
      family = audit$family,
      excluded_models = audit$excluded_models,
      retained_models = audit$retained_models,
      preregistered_analysis_affected =
        audit$preregistered_analysis_affected,
      approved = audit$approved
    ),
    paths[["metadata"]],
    na = ""
  )

  unname(paths)
}

make_update_2026_total_assignment_accepted_fit_manifest <- function(
    initial_manifest,
    first_remedy_fit_paths,
    first_remedy_diagnostics,
    final_diagnostic_audit,
    exclusion_audit
) {
  remedy_paths <- unname(unlist(first_remedy_fit_paths, use.names = FALSE))
  remedy_summary <- dplyr::bind_rows(
    purrr::map(first_remedy_diagnostics, "summary")
  ) |>
    dplyr::select(outcome, model_index, diagnostic_pass)
  remedy <- tibble::tibble(
    outcome = basename(dirname(remedy_paths)),
    model_index = as.integer(stringr::str_match(
      basename(remedy_paths), "model_([0-9]+)\\.qs$"
    )[, 2]),
    fit_path = normalizePath(remedy_paths, winslash = "/", mustWork = TRUE),
    stage = "remedy_1",
    bytes = file.info(remedy_paths)$size,
    sha256 = purrr::map_chr(
      remedy_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    )
  ) |>
    dplyr::left_join(
      initial_manifest |>
        dplyr::select(outcome, model_index, model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      remedy_summary,
      by = c("outcome", "model_index")
    )

  all_remedy_keys <- paste(remedy$outcome, remedy$model_index, sep = "::")
  accepted_remedy <- remedy |>
    dplyr::filter(diagnostic_pass) |>
    dplyr::select(
      outcome, model_index, model_name, fit_path, stage, bytes, sha256
    )
  accepted <- initial_manifest |>
    dplyr::filter(
      !paste(outcome, model_index, sep = "::") %in% all_remedy_keys
    ) |>
    dplyr::bind_rows(accepted_remedy) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  accepted_keys <- paste(accepted$outcome, accepted$model_index, sep = "::")
  final_summary <- final_diagnostic_audit$diagnostic_summary |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  passing_keys <- final_summary$key[final_summary$diagnostic_pass]
  excluded_keys <- final_summary$key[!final_summary$diagnostic_pass]
  stage_counts <- table(accepted$stage)
  outcome_counts <- table(factor(
    accepted$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))

  if (
    nrow(initial_manifest) != 72L || length(remedy_paths) != 10L ||
      any(!file.exists(remedy_paths)) || nrow(remedy_summary) != 10L ||
      !identical(final_diagnostic_audit$family, "total_assignment") ||
      !identical(exclusion_audit$family, "total_assignment") ||
      !isTRUE(exclusion_audit$approved) ||
      !setequal(excluded_keys, exclusion_audit$excluded_keys) ||
      nrow(accepted) != 69L || anyDuplicated(accepted_keys) ||
      !setequal(accepted_keys, passing_keys) ||
      !identical(as.integer(outcome_counts), c(18L, 18L, 15L, 18L)) ||
      !identical(unname(stage_counts["initial"]), 62L) ||
      !identical(unname(stage_counts["remedy_1"]), 7L) ||
      !all(file.exists(accepted$fit_path)) || any(accepted$bytes <= 0) ||
      any(nchar(accepted$sha256) != 64L)
  ) {
    stop("The accepted total assignment-derived manifest is invalid.",
         call. = FALSE)
  }

  accepted
}

write_update_2026_total_assignment_accepted_fit_manifest <- function(
    manifest,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "accepted_fit_manifest.csv"
    )
) {
  if (
    nrow(manifest) != 69L ||
      !identical(
        as.integer(table(factor(
          manifest$outcome,
          levels = c("whole_body", "hypertrophy", "strength", "function")
        ))),
        c(18L, 18L, 15L, 18L)
      ) ||
      !all(file.exists(manifest$fit_path)) || any(manifest$bytes <= 0) ||
      any(nchar(manifest$sha256) != 64L)
  ) {
    stop("Cannot write an invalid assignment-derived accepted manifest.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(manifest, output_file, na = "")
  output_file
}

validate_update_2026_total_assignment_loo_inputs <- function(
    accepted_fit_manifest,
    final_diagnostic_audit,
    exclusion_audit,
    specifications,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  accepted_keys <- paste(
    accepted_fit_manifest$outcome,
    accepted_fit_manifest$model_index,
    sep = "::"
  )
  diagnostic_table <- final_diagnostic_audit$diagnostic_summary |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  accepted_diagnostics <- diagnostic_table |>
    dplyr::filter(key %in% accepted_keys)
  excluded_diagnostics <- diagnostic_table |>
    dplyr::filter(key %in% exclusion_audit$excluded_keys)
  stage_counts <- table(accepted_fit_manifest$stage)
  outcome_counts <- table(factor(
    accepted_fit_manifest$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  checks <- tibble::tribble(
    ~check, ~passed,
    "all 69 accepted assignment-derived sampling diagnostics pass",
    nrow(accepted_diagnostics) == 69L &&
      all(accepted_diagnostics$diagnostic_pass),
    "accepted registry contains 18 18 15 and 18 outcome models",
    identical(as.integer(outcome_counts), c(18L, 18L, 15L, 18L)),
    "accepted registry contains 62 initial and 7 remedy fits",
    identical(unname(stage_counts["initial"]), 62L) &&
      identical(unname(stage_counts["remedy_1"]), 7L),
    "three strength random-smooth candidates are structurally excluded",
    nrow(excluded_diagnostics) == 3L &&
      all(!excluded_diagnostics$diagnostic_pass) &&
      setequal(
        excluded_diagnostics$key,
        c("strength::11", "strength::23", "strength::26")
      ) &&
      isTRUE(exclusion_audit$approved) &&
      !isTRUE(exclusion_audit$preregistered_analysis_affected),
    "all accepted candidates retain their common observation sets",
    nrow(specification_table) == 72L &&
      all(specification_table$common_sample) &&
      all(accepted_keys %in% specification_table$key),
    "all accepted fit files exist are nonempty and have hashes",
    all(file.exists(accepted_fit_manifest$fit_path)) &&
      all(file.info(accepted_fit_manifest$fit_path)$size > 0) &&
      all(nchar(accepted_fit_manifest$sha256) == 64L)
  )

  ready <-
    nrow(accepted_fit_manifest) == 69L &&
    !anyDuplicated(accepted_keys) && all(checks$passed) &&
    identical(k_threshold, 0.7) &&
    identical(as.integer(cores_per_branch), 1L)
  if (!ready) {
    stop("The total assignment-derived LOO preflight is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_assignment",
    models = 69L,
    excluded_models = 3L,
    k_threshold = k_threshold,
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    exclusion_summary = exclusion_audit$exclusion_summary,
    ready = TRUE
  )
}

write_update_2026_total_assignment_loo_preflight <- function(
    preflight,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "loo_preflight"
    )
) {
  if (
    !isTRUE(preflight$ready) || preflight$models != 69L ||
      preflight$excluded_models != 3L || !all(preflight$checks$passed)
  ) {
    stop("Cannot write an invalid assignment-derived LOO preflight.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    checks = file.path(output_dir, "checks.csv"),
    accepted_fit_manifest = file.path(
      output_dir,
      "accepted_fit_manifest.csv"
    ),
    exclusion_summary = file.path(output_dir, "exclusion_summary.csv")
  )

  readr::write_csv(preflight$checks, paths[["checks"]], na = "")
  readr::write_csv(
    preflight$accepted_fit_manifest,
    paths[["accepted_fit_manifest"]],
    na = ""
  )
  readr::write_csv(
    preflight$exclusion_summary,
    paths[["exclusion_summary"]],
    na = ""
  )
  unname(paths)
}

make_update_2026_total_assignment_loo_records <- function(
    accepted_fit_manifest
) {
  required <- c(
    "outcome", "model_index", "model_name", "fit_path", "stage"
  )
  outcome_counts <- table(factor(
    accepted_fit_manifest$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))

  if (
    !all(required %in% names(accepted_fit_manifest)) ||
      nrow(accepted_fit_manifest) != 69L ||
      anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) ||
      !identical(as.integer(outcome_counts), c(18L, 18L, 15L, 18L)) ||
      !all(file.exists(accepted_fit_manifest$fit_path))
  ) {
    stop("The total assignment-derived LOO fit manifest is invalid.",
         call. = FALSE)
  }

  records <- purrr::map(
    seq_len(nrow(accepted_fit_manifest)),
    ~ purrr::map(
      as.list(accepted_fit_manifest[.x, required, drop = FALSE]),
      unname
    )
  )
  names(records) <- paste0(
    accepted_fit_manifest$outcome,
    "_model_",
    stringr::str_pad(accepted_fit_manifest$model_index, 2L, pad = "0")
  )
  records
}

compute_update_2026_total_assignment_integrated_loo_to_file <- function(
    fit_record,
    enabled,
    loo_draws = 4000L,
    k_threshold = 0.7,
    cores = 1L,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "loo", "integrated"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      "Total assignment-derived LOO is disabled. Set ",
      "PROTEIN_UPDATE_2026_TOTAL_ASSIGNMENT_LOO=run to enable it.",
      call. = FALSE
    )
  }

  fit_path <- fit_record$fit_path
  if (
    length(fit_path) != 1L || is.na(fit_path) || !file.exists(fit_path)
  ) {
    stop("The total assignment-derived LOO fit is unavailable.",
         call. = FALSE)
  }

  candidate <- read_sensitivity_fit_file(fit_path)
  if (
    !identical(unname(as.character(candidate$family)),
               "total_assignment") ||
      !identical(candidate$outcome, fit_record$outcome) ||
      !identical(
        as.integer(candidate$model_index),
        as.integer(fit_record$model_index)
      ) ||
      !identical(candidate$model_name, fit_record$model_name) ||
      !inherits(candidate$model, "brmsfit")
  ) {
    stop("The total assignment-derived fit does not match its LOO record.",
         call. = FALSE)
  }

  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  draw_ids <- make_sensitivity_loo_draw_ids(
    brms::ndraws(candidate$model),
    min(as.integer(loo_draws), as.integer(brms::ndraws(candidate$model)))
  )
  conditional_loo <- brms::loo(
    candidate$model,
    draw_ids = draw_ids,
    pointwise = FALSE,
    moment_match = FALSE,
    reloo = FALSE,
    cores = as.integer(cores)
  )

  result <- compute_sensitivity_exposure_integrated_psis_loo(
    job = list(
      fitted_candidate = candidate,
      conditional_loo = conditional_loo,
      loo_draws = length(draw_ids)
    ),
    family = "total_assignment",
    k_threshold = k_threshold,
    cores = cores
  )

  result$family <- "total_assignment"
  result$fit_record <- fit_record
  result$loo_draws <- length(draw_ids)
  if (
    !inherits(result$loo, "loo") ||
      !inherits(result$conditional_loo, "loo") ||
      !identical(unname(as.character(result$family)),
                 "total_assignment") ||
      !identical(result$remedy, "integrated_observation_level_psis")
  ) {
    stop("Cannot archive an invalid total assignment-derived LOO result.",
         call. = FALSE)
  }

  output_dir <- file.path(output_root, result$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf(
      "model_%02d_integrated_loo.qs",
      as.integer(result$model_index)
    )
  )
  write_atomic_qs(result, output_file)
}

make_update_2026_total_assignment_integrated_loo_manifest <- function(
    paths,
    accepted_fit_manifest
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  expected_keys <- paste(
    accepted_fit_manifest$outcome,
    accepted_fit_manifest$model_index,
    sep = "::"
  )

  if (
    length(paths) != 69L || anyNA(paths) || any(!file.exists(paths)) ||
      nrow(accepted_fit_manifest) != 69L || anyDuplicated(expected_keys)
  ) {
    stop("The assignment-derived integrated LOO file set is incomplete.",
         call. = FALSE)
  }

  manifest <- purrr::map_dfr(paths, function(path) {
    result <- qs::qread(path)
    if (
      !inherits(result$loo, "loo") ||
        !inherits(result$conditional_loo, "loo") ||
        !identical(unname(as.character(result$family)),
                   "total_assignment")
    ) {
      stop("An assignment-derived integrated LOO file is invalid.",
           call. = FALSE)
    }
    tibble::tibble(
      family = "total_assignment",
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      model_name = result$model_name,
      integrated_loo_path = normalizePath(
        path, winslash = "/", mustWork = TRUE
      ),
      bytes = file.info(path)$size,
      sha256 = digest::digest(
        file = path, algo = "sha256", serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  manifest_keys <- paste(manifest$outcome, manifest$model_index, sep = "::")
  expected_names <- stats::setNames(
    accepted_fit_manifest$model_name,
    expected_keys
  )
  if (
    nrow(manifest) != 69L || anyDuplicated(manifest_keys) ||
      !setequal(manifest_keys, expected_keys) ||
      !identical(
        unname(manifest$model_name),
        unname(expected_names[manifest_keys])
      ) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The assignment-derived integrated LOO manifest is invalid.",
         call. = FALSE)
  }

  manifest
}

audit_update_2026_total_assignment_integrated_loo_files <- function(
    manifest,
    accepted_fit_manifest,
    k_threshold = 0.7
) {
  manifest_keys <- paste(manifest$outcome, manifest$model_index, sep = "::")
  accepted_keys <- paste(
    accepted_fit_manifest$outcome,
    accepted_fit_manifest$model_index,
    sep = "::"
  )

  if (
    nrow(manifest) != 69L || nrow(accepted_fit_manifest) != 69L ||
      anyDuplicated(manifest_keys) || anyDuplicated(accepted_keys) ||
      !setequal(manifest_keys, accepted_keys) ||
      any(manifest$family != "total_assignment") ||
      any(!file.exists(manifest$integrated_loo_path))
  ) {
    stop("The assignment-derived integrated LOO manifest cannot be audited.",
         call. = FALSE)
  }

  results <- purrr::map(manifest$integrated_loo_path, qs::qread)
  accepted_paths <- stats::setNames(
    normalizePath(
      accepted_fit_manifest$fit_path,
      winslash = "/",
      mustWork = TRUE
    ),
    accepted_keys
  )

  valid <- purrr::map2_lgl(results, seq_along(results), function(result, i) {
    result_key <- paste(result$outcome, result$model_index, sep = "::")
    inherits(result$loo, "loo") &&
      inherits(result$conditional_loo, "loo") &&
      identical(unname(as.character(result$family)), "total_assignment") &&
      identical(result_key, manifest_keys[[i]]) &&
      identical(result$model_name, manifest$model_name[[i]]) &&
      is.list(result$fit_record) &&
      file.exists(result$fit_record$fit_path) &&
      identical(
        normalizePath(
          result$fit_record$fit_path,
          winslash = "/",
          mustWork = TRUE
        ),
        unname(accepted_paths[[result_key]])
      )
  })

  if (!all(valid)) {
    stop("The assignment-derived integrated LOO files failed validation.",
         call. = FALSE)
  }
  conditional_method <- "conditional_observation_level_psis"
  integrated_method <- "integrated_observation_level_psis"
  model_summary <- purrr::map_dfr(results, function(result) {
    dplyr::bind_rows(
      summarise_primary_loo_method(
        result$conditional_loo,
        conditional_method,
        k_threshold
      ),
      summarise_primary_loo_method(
        result$loo,
        integrated_method,
        k_threshold
      )
    ) |>
      dplyr::mutate(
        outcome = result$outcome,
        model_index = result$model_index,
        model_name = result$model_name,
        loo_draws = result$loo_draws,
        .before = 1L
      )
  })

  high_k_cases <- purrr::map_dfr(results, function(result) {
    pareto_k <- as.numeric(loo::pareto_k_values(result$loo))
    observations <- which(pareto_k > k_threshold)
    if (length(observations) < 1L) return(tibble::tibble())
    result$observation_manifest[observations, , drop = FALSE] |>
      dplyr::mutate(
        outcome = result$outcome,
        model_index = result$model_index,
        model_name = result$model_name,
        observation = observations,
        pareto_k = pareto_k[observations],
        fit_path = result$fit_record$fit_path,
        .before = 1L
      )
  })

  if (nrow(high_k_cases) > 0L) {
    high_k_cases <- high_k_cases |>
      dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )
  } else {
    high_k_cases <- tibble::tibble(
      outcome = character(),
      model_index = integer(),
      model_name = character(),
      observation = integer(),
      pareto_k = double(),
      fit_path = character()
    )
  }

  outcome_summary <- model_summary |>
    dplyr::filter(method == integrated_method) |>
    dplyr::group_by(outcome) |>
    dplyr::summarise(
      models = dplyr::n(),
      models_without_high_k = sum(n_pareto_k_gt_threshold == 0L),
      models_requiring_exact_refits = sum(n_pareto_k_gt_threshold > 0L),
      exact_refits_required = sum(n_pareto_k_gt_threshold),
      maximum_pareto_k = max(maximum_pareto_k),
      .groups = "drop"
    )

  outcome_counts <- outcome_summary |>
    dplyr::arrange(factor(
      outcome,
      levels = c("whole_body", "hypertrophy", "strength", "function")
    )) |>
    dplyr::pull(models)

  if (
    nrow(model_summary) != 138L ||
      !identical(as.integer(outcome_counts), c(18L, 18L, 15L, 18L))
  ) {
    stop("The assignment-derived integrated LOO audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_assignment",
    model_summary = model_summary,
    outcome_summary = outcome_summary,
    high_k_cases = high_k_cases,
    models = length(results),
    excluded_models = 3L,
    exact_refits_required = nrow(high_k_cases),
    integrated_psis_complete = TRUE,
    stacking_ready = nrow(high_k_cases) == 0L,
    loo_unit = "observation",
    k_threshold = k_threshold
  )
}

write_update_2026_total_assignment_integrated_loo_audit <- function(
    audit,
    manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "loo_psis"
    )
) {
  if (
    !isTRUE(audit$integrated_psis_complete) || audit$models != 69L ||
      audit$excluded_models != 3L || nrow(manifest) != 69L ||
      any(!file.exists(manifest$integrated_loo_path))
  ) {
    stop("The assignment-derived integrated LOO audit is incomplete.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    reduction_manifest = file.path(output_dir, "reduction_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    high_k_cases = file.path(output_dir, "high_k_cases.csv")
  )
  readr::write_csv(manifest, paths[["reduction_manifest"]], na = "")
  readr::write_csv(audit$model_summary, paths[["model_summary"]], na = "")
  readr::write_csv(audit$outcome_summary, paths[["outcome_summary"]], na = "")
  readr::write_csv(audit$high_k_cases, paths[["high_k_cases"]], na = "")
  unname(paths)
}

validate_update_2026_total_assignment_exact_inputs <- function(
    records,
    config
) {
  if (!is.list(records) || length(records) != 8L) {
    stop("Expected eight total assignment-derived exact-LOO records.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    integrated <- qs::qread(record$integrated_loo_path)
    observation <- as.integer(record$observation)
    if (
      !identical(unname(as.character(integrated$family)),
                 "total_assignment") ||
        !identical(integrated$outcome, record$outcome) ||
        as.integer(integrated$model_index) !=
          as.integer(record$model_index) ||
        observation < 1L ||
        observation > nrow(integrated$observation_manifest)
    ) {
      stop("A total assignment-derived exact record is invalid.",
           call. = FALSE)
    }
    held_out <- integrated$observation_manifest[
      observation,
      ,
      drop = FALSE
    ]
    observed_k <- as.numeric(
      loo::pareto_k_values(integrated$loo)[[observation]]
    )
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = observation,
      study_no = as.character(held_out$study_no[[1L]]),
      arm_no = as.integer(held_out$arm_no[[1L]]),
      outcome_no = as.integer(held_out$outcome_no[[1L]]),
      pareto_k = observed_k,
      adapt_delta = as.numeric(config$adapt_delta_floor),
      max_treedepth = as.integer(config$max_treedepth_floor),
      iter_warmup = as.integer(config$iter_warmup),
      iter_sampling = as.integer(config$iter_sampling),
      chains = as.integer(config$chains),
      parallel_chains = as.integer(config$parallel_chains),
      original_fit_exists = file.exists(record$original_fit_path),
      integrated_loo_exists = file.exists(record$integrated_loo_path),
      valid = is.finite(observed_k) && observed_k > 0.7
    )
  }) |>
    dplyr::arrange(case_id)

  observed_cases <- paste(
    checks$outcome,
    checks$model_index,
    checks$observation,
    sep = "::"
  )
  expected_cases <- c(
    "whole_body::14::40",
    "whole_body::17::130",
    "whole_body::17::131",
    "whole_body::20::131",
    "hypertrophy::12::193",
    "hypertrophy::12::194",
    "hypertrophy::12::204",
    "hypertrophy::24::193"
  )

  if (
    nrow(checks) != 8L ||
      !identical(checks$case_id, seq_len(8L)) ||
      !identical(observed_cases, expected_cases) ||
      anyDuplicated(observed_cases) ||
      !all(stringr::str_ends(
        checks$model_name,
        stringr::fixed(" [total_assignment]")
      )) ||
      any(checks$pareto_k <= 0.7) ||
      any(checks$adapt_delta != 0.999) ||
      any(checks$max_treedepth != 15L) ||
      any(checks$iter_warmup != 2000L) ||
      any(checks$iter_sampling != 6000L) ||
      any(checks$chains != 4L) ||
      any(checks$parallel_chains != 1L) ||
      !all(checks$original_fit_exists) ||
      !all(checks$integrated_loo_exists) ||
      !all(checks$valid)
  ) {
    stop("The total assignment-derived exact-LOO preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

