compute_update_2026_total_assignment_exact_correction_to_file <- function(
    exact_fit_path,
    diagnostic_audit,
    enabled
) {
  if (!isTRUE(enabled)) {
    stop("Total assignment-derived exact correction is disabled.",
         call. = FALSE)
  }

  refit <- read_sensitivity_full_exact_loo_file(
    exact_fit_path,
    "total_assignment"
  )
  output_file <-
    update_2026_total_assignment_exact_correction_file_path(refit)

  if (file.exists(output_file) && file.info(output_file)$size > 0) {
    archived <- tryCatch(qs::qread(output_file), error = function(error) NULL)
    if (
      !is.null(archived) && inherits(archived$loo, "loo") &&
        as.integer(archived$case_id) == as.integer(refit$case_id) &&
        identical(archived$outcome, refit$outcome) &&
        as.integer(archived$model_index) == as.integer(refit$model_index) &&
        as.integer(archived$exact_refit_summary$observation[[1L]]) ==
          as.integer(refit$observation)
    ) {
      return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
    }
    stop(
      paste0(
        "An existing total assignment-derived exact-correction archive ",
        "is invalid; it was not overwritten."
      ),
      call. = FALSE
    )
  }

  correction <- compute_sensitivity_full_exact_loo_file(
    path = exact_fit_path,
    diagnostic_audit = diagnostic_audit,
    family = "total_assignment"
  )
  if (
    !inherits(correction$loo, "loo") ||
      as.integer(correction$case_id) != as.integer(refit$case_id) ||
      nrow(correction$exact_refit_summary) != 1L ||
      !isTRUE(correction$exact_refit_summary$diagnostic_pass[[1L]])
  ) {
    stop("The total assignment-derived exact correction is invalid.",
         call. = FALSE)
  }

  write_atomic_qs(correction, output_file)
}

audit_update_2026_total_assignment_exact_correction_files <- function(
    paths,
    integrated_audit
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  expected <- as.integer(integrated_audit$exact_refits_required)

  if (
    length(paths) != expected || expected != 8L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The assignment-derived exact corrections are incomplete.",
         call. = FALSE)
  }

  corrections <- purrr::map(paths, qs::qread)
  diagnostic_summary <- purrr::map_dfr(
    corrections,
    "exact_refit_summary"
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )

  manifest <- purrr::map2_dfr(paths, corrections, function(path, result) {
    tibble::tibble(
      case_id = as.integer(result$case_id),
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      model_name = result$model_name,
      observation =
        as.integer(result$exact_refit_summary$observation[[1L]]),
      correction_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      bytes = file.info(path)$size,
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    manifest$outcome,
    manifest$model_index,
    manifest$observation,
    sep = "::"
  )
  expected_keys <- paste(
    integrated_audit$high_k_cases$outcome,
    integrated_audit$high_k_cases$model_index,
    integrated_audit$high_k_cases$observation,
    sep = "::"
  )

  if (
    nrow(diagnostic_summary) != 8L || nrow(manifest) != 8L ||
      anyDuplicated(observed_keys) || !setequal(observed_keys, expected_keys) ||
      !identical(manifest$case_id, seq_len(8L)) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L) ||
      !all(diagnostic_summary$diagnostic_pass)
  ) {
    stop("The assignment-derived exact-correction audit is invalid.",
         call. = FALSE)
  }

  list(
    diagnostic_summary = diagnostic_summary,
    correction_manifest = manifest,
    exact_refits = 8L,
    exact_refits_passing = sum(diagnostic_summary$diagnostic_pass),
    exact_refits_requiring_remediation =
      sum(!diagnostic_summary$diagnostic_pass),
    all_exact_refit_diagnostics_pass =
      all(diagnostic_summary$diagnostic_pass)
  )
}

write_update_2026_total_assignment_exact_correction_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "loo_exact", "corrections"
    )
) {
  if (
    audit$exact_refits != 8L ||
      nrow(audit$diagnostic_summary) != 8L ||
      nrow(audit$correction_manifest) != 8L
  ) {
    stop("Cannot write an incomplete assignment-derived correction audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    correction_manifest = file.path(output_dir, "correction_manifest.csv")
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$correction_manifest,
    paths[["correction_manifest"]],
    na = ""
  )
  unname(paths)
}

read_update_2026_total_assignment_exact_corrections <- function(manifest) {
  if (
    !is.data.frame(manifest) || nrow(manifest) != 8L ||
      any(!file.exists(manifest$correction_path)) ||
      !identical(manifest$case_id, seq_len(8L))
  ) {
    stop("The assignment-derived correction manifest is invalid.",
         call. = FALSE)
  }

  corrections <- purrr::map(manifest$correction_path, qs::qread)
  if (
    !identical(
      unname(purrr::map_int(corrections, "case_id")),
      seq_len(8L)
    ) ||
      any(!purrr::map_lgl(corrections, ~ inherits(.x$loo, "loo")))
  ) {
    stop("The assignment-derived exact corrections are invalid.",
         call. = FALSE)
  }

  corrections
}

make_update_2026_total_assignment_final_loo_audit <- function(
    integrated_manifest,
    exact_corrections,
    exact_audit
) {
  if (
    nrow(integrated_manifest) != 69L ||
      any(integrated_manifest$family != "total_assignment") ||
      any(!file.exists(integrated_manifest$integrated_loo_path)) ||
      length(exact_corrections) != 8L ||
      !isTRUE(exact_audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("Final assignment-derived LOO inputs are incomplete.",
         call. = FALSE)
  }

  final_results <- purrr::map(
    integrated_manifest$integrated_loo_path,
    qs::qread
  )
  result_keys <- paste(
    purrr::map_chr(final_results, "outcome"),
    purrr::map_int(final_results, "model_index"),
    sep = "::"
  )
  manifest_keys <- paste(
    integrated_manifest$outcome,
    integrated_manifest$model_index,
    sep = "::"
  )
  warning_cases <- purrr::map_dfr(final_results, function(result) {
    pareto_k <- loo::pareto_k_values(result$loo)
    tibble::tibble(
      outcome = result$outcome,
      model_index = result$model_index,
      observation = which(pareto_k > 0.7)
    )
  }) |>
    dplyr::arrange(outcome, model_index, observation)

  exact_cases <- purrr::map_dfr(exact_corrections, function(result) {
    tibble::tibble(
      outcome = result$outcome,
      model_index = result$model_index,
      observation = result$exact_refit_summary$observation[[1L]]
    )
  }) |>
    dplyr::arrange(outcome, model_index, observation)

  if (
    anyDuplicated(result_keys) || !identical(result_keys, manifest_keys) ||
      !identical(warning_cases, exact_cases)
  ) {
    stop("Exact corrections do not match assignment-derived high-k cases.",
         call. = FALSE)
  }

  corrected_keys <- unique(paste(
    exact_cases$outcome,
    exact_cases$model_index,
    sep = "::"
  ))
  for (key in corrected_keys) {
    position <- match(key, result_keys)
    patched <- final_results[[position]]
    corrections <- purrr::keep(
      exact_corrections,
      ~ identical(paste(.x$outcome, .x$model_index, sep = "::"), key)
    )
    for (correction in corrections) {
      observation <- correction$exact_refit_summary$observation[[1L]]
      patched$loo$pointwise[observation, ] <-
        correction$loo$pointwise[observation, ]
      patched$loo$diagnostics$pareto_k[[observation]] <- NA_real_
      if (!is.null(patched$loo$diagnostics$n_eff)) {
        patched$loo$diagnostics$n_eff[[observation]] <- NA_real_
      }
    }
    patched$loo <- update_primary_exact_loo_estimates(patched$loo)
    patched$remedy <- "integrated_observation_level_psis_plus_exact"
    final_results[[position]] <- patched
  }

  exact_summary <- purrr::map_dfr(
    exact_corrections,
    "exact_refit_summary"
  )
  model_summary <- purrr::map_dfr(final_results, function(result) {
    summarise_primary_loo_method(
      result$loo,
      "integrated_observation_level_psis_plus_exact"
    ) |>
      dplyr::mutate(
        outcome = result$outcome,
        model_index = result$model_index,
        model_name = result$model_name,
        .before = 1L
      )
  })

  outcome_summary <- model_summary |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_unresolved_high_k =
        sum(n_pareto_k_gt_threshold > 0L),
      unresolved_high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_remaining_pareto_k = max(maximum_pareto_k, na.rm = TRUE),
      .by = outcome
    )

  correction_counts <- exact_summary |>
    dplyr::count(outcome, model_index, name = "exact_corrections")
  final_manifest <- integrated_manifest |>
    dplyr::left_join(
      correction_counts,
      by = c("outcome", "model_index")
    ) |>
    dplyr::mutate(
      exact_corrections = tidyr::replace_na(exact_corrections, 0L),
      final_method = dplyr::if_else(
        exact_corrections > 0L,
        "integrated_observation_level_psis_plus_exact",
        "integrated_observation_level_psis"
      )
    )

  outcome_counts <- outcome_summary |>
    dplyr::arrange(factor(
      outcome,
      levels = c("whole_body", "hypertrophy", "strength", "function")
    )) |>
    dplyr::pull(models)
  stacking_ready <-
    all(model_summary$n_pareto_k_gt_threshold == 0L) &&
    all(exact_summary$diagnostic_pass)

  if (
    !stacking_ready || nrow(model_summary) != 69L ||
      !identical(as.integer(outcome_counts), c(18L, 18L, 15L, 18L)) ||
      any(outcome_summary$unresolved_high_k_cases != 0L) ||
      nrow(final_manifest) != 69L ||
      sum(final_manifest$exact_corrections) != 8L ||
      nrow(exact_summary) != 8L
  ) {
    stop("The final assignment-derived LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  list(
    family = "total_assignment",
    results = final_results,
    model_summary = model_summary,
    outcome_summary = outcome_summary,
    exact_refit_summary = exact_summary,
    final_loo_manifest = final_manifest,
    exact_refits = 8L,
    all_exact_refit_diagnostics_pass = TRUE,
    stacking_ready = TRUE
  )
}

write_update_2026_total_assignment_final_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "loo_final"
    )
) {
  if (
    !isTRUE(audit$stacking_ready) ||
      nrow(audit$model_summary) != 69L ||
      nrow(audit$outcome_summary) != 4L ||
      nrow(audit$exact_refit_summary) != 8L ||
      nrow(audit$final_loo_manifest) != 69L
  ) {
    stop("Cannot write an incomplete final assignment-derived LOO audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    final_loo_manifest = file.path(output_dir, "final_loo_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    exact_refit_summary = file.path(output_dir, "exact_refit_summary.csv")
  )
