  readr::write_csv(audit$model_summary, paths[["model_summary"]])
  readr::write_csv(audit$outcome_summary, paths[["outcome_summary"]])
  readr::write_csv(
    audit$exact_refit_summary,
    paths[["exact_refit_summary"]]
  )
  unname(paths)
}

compute_update_2026_total_assignment_stacking_weights <- function(
    final_loo_audit
) {
  if (!isTRUE(final_loo_audit$stacking_ready)) {
    stop("The assignment-derived LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  expected_counts <- c(
    whole_body = 18L,
    hypertrophy = 18L,
    strength = 15L,
    "function" = 18L
  )
  weights <- purrr::map_dfr(names(expected_counts), function(outcome) {
    results <- purrr::keep(
      final_loo_audit$results,
      ~ identical(.x$outcome, outcome)
    )
    if (length(results) != expected_counts[[outcome]]) {
      stop("An assignment-derived outcome ensemble is incomplete.",
           call. = FALSE)
    }
    loo_objects <- purrr::map(results, "loo")
    names(loo_objects) <- purrr::map_chr(results, "model_name")
    values <- loo::loo_model_weights(loo_objects, method = "stacking")
    tibble::tibble(
      family = "total_assignment",
      outcome = outcome,
      model_index = purrr::map_int(results, "model_index"),
      model_name = purrr::map_chr(results, "model_name"),
      weight = as.numeric(values) / sum(as.numeric(values)),
      method = "stacking_exact_corrected_integrated_loo"
    )
  })

  observed_counts <- table(factor(
    weights$outcome,
    levels = names(expected_counts)
  ))
  if (
    nrow(weights) != 69L ||
      !identical(as.integer(observed_counts), unname(expected_counts)) ||
      anyDuplicated(weights[c("outcome", "model_index")]) ||
      any(abs(tapply(weights$weight, weights$outcome, sum) - 1) > 1e-8)
  ) {
    stop("The assignment-derived stacking weights are invalid.",
         call. = FALSE)
  }

  weights
}

write_update_2026_total_assignment_stacking_weights <- function(
    weights,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "stacking_weights.csv"
    )
) {
  outcome_sums <- tapply(weights$weight, weights$outcome, sum)
  outcome_counts <- table(factor(
    weights$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  if (
    nrow(weights) != 69L ||
      !identical(as.integer(outcome_counts), c(18L, 18L, 15L, 18L)) ||
      anyDuplicated(weights[c("outcome", "model_index")]) ||
      length(outcome_sums) != 4L ||
      any(abs(outcome_sums - 1) > 1e-8)
  ) {
    stop("The assignment-derived stacking weights are invalid.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(weights, output_file, na = "")
  output_file
}

make_update_2026_total_assignment_prediction_records <- function(
    accepted_fit_manifest,
    stacking_weights,
    n_draws = 4000L,
    exposure_minimum_g_day = 50,
    grid_step_g_day = 1,
    seed = 113988L
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  expected_counts <- c(
    whole_body = 18L,
    hypertrophy = 18L,
    strength = 15L,
    "function" = 18L
  )
  required_fit <- c(
    "outcome", "model_index", "model_name", "fit_path", "sha256"
  )
  required_weight <- c("outcome", "model_index", "model_name", "weight")
  n_draws <- as.integer(n_draws)

  if (
    !all(required_fit %in% names(accepted_fit_manifest)) ||
      !all(required_weight %in% names(stacking_weights)) ||
      nrow(accepted_fit_manifest) != 69L ||
      nrow(stacking_weights) != 69L ||
      n_draws < 1L ||
      !is.finite(exposure_minimum_g_day) ||
      !is.finite(grid_step_g_day) || grid_step_g_day <= 0
  ) {
    stop("The assignment-derived reporting inputs are invalid.",
         call. = FALSE)
  }

  joined <- stacking_weights |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(dplyr::all_of(required_fit)) |>
        dplyr::rename(fit_sha256 = sha256),
      by = c("outcome", "model_index", "model_name"),
      relationship = "one-to-one"
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)

  observed_counts <- table(factor(joined$outcome, levels = outcomes))
  if (
    anyNA(joined$fit_path) || any(!file.exists(joined$fit_path)) ||
      anyDuplicated(joined[c("outcome", "model_index")]) ||
      !identical(as.integer(observed_counts), unname(expected_counts)) ||
      any(!is.finite(joined$weight)) || any(joined$weight < 0) ||
      any(abs(tapply(joined$weight, joined$outcome, sum) - 1) > 1e-8)
  ) {
    stop("The assignment-derived fit and weight registries do not match.",
         call. = FALSE)
  }

  outcome_seed <- stats::setNames(
    seed + seq_along(outcomes) * 10000L,
    outcomes
  )
  allocated <- joined |>
    dplyr::group_by(outcome) |>
    dplyr::group_modify(function(table, key) {
      expected <- expected_counts[[as.character(key$outcome[[1L]])]]
      if (nrow(table) != expected || abs(sum(table$weight) - 1) > 1e-8) {
        stop("An assignment-derived prediction ensemble is invalid.",
             call. = FALSE)
      }
      table$draw_count <- allocate_primary_mixture_models(
        table$weight / sum(table$weight),
        n_draws
      )
      table
    }) |>
    dplyr::ungroup() |>
    dplyr::mutate(
      family = "total_assignment",
      prediction_type = "total_assignment",
      prediction_seed = as.integer(
        outcome_seed[outcome] + as.integer(model_index)
      ),
      n_draws = n_draws,
      exposure_minimum_g_day = exposure_minimum_g_day,
      grid_step_g_day = grid_step_g_day
    )

  allocation_audit <- allocated |>
    dplyr::summarise(
      allocated_draws = sum(draw_count),
      selected_models = sum(draw_count > 0L),
      .by = outcome
    )

  if (
    nrow(allocation_audit) != 4L ||
      any(allocation_audit$allocated_draws != n_draws) ||
      any(allocation_audit$selected_models < 1L)
  ) {
    stop("The assignment-derived prediction allocation is incomplete.",
         call. = FALSE)
  }

  allocated <- dplyr::filter(allocated, draw_count > 0L)
  purrr::map(seq_len(nrow(allocated)), function(row) {
    purrr::map(as.list(allocated[row, , drop = FALSE]), unname)
  })
}

make_update_2026_total_assignment_reporting_preflight <- function(
    records,
    data_by_outcome
) {
  checks <- purrr::map_dfr(records, function(record) {
    data <- data_by_outcome[[record$outcome]]
    maximum <- if (is.data.frame(data)) {
      max(data$protein_intake_raw, na.rm = TRUE)
    } else {
      NA_real_
    }
    reference <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_reference_g_day)
    } else {
      NA_real_
    }
    unit <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_unit_g_day)
    } else {
      NA_real_
    }
    tibble::tibble(
      outcome = as.character(record$outcome),
      model_index = as.integer(record$model_index),
      model_name = as.character(record$model_name),
      weight = as.numeric(record$weight),
      allocated_draws = as.integer(record$draw_count),
      exposure_minimum_g_day = as.numeric(record$exposure_minimum_g_day),
      exposure_maximum_g_day = maximum,
      reference_g_day = reference,
      internal_unit_g_day = unit,
      grid_step_g_day = as.numeric(record$grid_step_g_day),
      fit_path = as.character(record$fit_path),
      fit_exists = file.exists(record$fit_path),
      valid = record$draw_count > 0L && file.exists(record$fit_path) &&
        nchar(record$fit_sha256) == 64L &&
        identical(as.character(record$family), "total_assignment") &&
        identical(
          as.character(record$prediction_type),
          "total_assignment"
        ) &&
        is.finite(maximum) && maximum > record$exposure_minimum_g_day &&
        length(reference) == 1L && is.finite(reference) &&
        length(unit) == 1L && is.finite(unit) && unit > 0
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  audit <- checks |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      allocated_draws = sum(allocated_draws),
      retained_weight = sum(weight),
      .by = outcome
    )

  if (
    nrow(audit) != 4L || any(audit$selected_models < 1L) ||
      any(audit$allocated_draws != 4000L) ||
      any(audit$retained_weight <= 0) ||
      any(audit$retained_weight > 1 + 1e-8) ||
      anyDuplicated(checks[c("outcome", "model_index")]) ||
      !all(checks$valid) ||
      any(checks$reference_g_day != 78.785) ||
      any(checks$internal_unit_g_day != 50) ||
      any(checks$exposure_minimum_g_day != 50) ||
      any(checks$grid_step_g_day != 1)
  ) {
    stop("The assignment-derived reporting preflight failed.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_assignment_reporting_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "reporting", "input_preflight.csv"
    )
) {
  if (
    !all(checks$valid) ||
      any(tapply(checks$allocated_draws, checks$outcome, sum) != 4000L)
  ) {
    stop("Cannot write an invalid assignment-derived reporting preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

update_2026_total_assignment_reporting_path <- function(
    outcome,
    stage,
    model_index = NULL
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure", "total_g_day",
    "assignment_common_sample", "reporting", stage, outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
