write_update_2026_total_assignment_prediction_draw_file <- function(
    record,
    data_by_outcome,
    result_path
) {
  if (
    length(record$fit_path) != 1L || is.na(record$fit_path) ||
      !file.exists(record$fit_path) || record$draw_count < 1L ||
      !identical(as.character(record$family), "total_assignment") ||
      !identical(as.character(record$prediction_type), "total_assignment")
  ) {
    stop("An assignment-derived prediction record is invalid.",
         call. = FALSE)
  }

  candidate <- read_sensitivity_fit_file(record$fit_path)
  if (
    !identical(unname(as.character(candidate$family)),
               "total_assignment") ||
      !identical(
        unname(as.character(candidate$outcome)),
        as.character(record$outcome)
      ) ||
      as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(candidate$model_name, as.character(record$model_name))
  ) {
    stop("An assignment-derived fit does not match its prediction record.",
         call. = FALSE)
  }

  prediction_data <- data_by_outcome[[record$outcome]]
  if (is.null(prediction_data) || !is.data.frame(prediction_data)) {
    stop("The assignment-derived prediction data are unavailable.",
         call. = FALSE)
  }
  grid <- make_update_2026_total_primary_prediction_grid(
    data = prediction_data,
    fitted_candidate = candidate,
    exposure_minimum_g_day = record$exposure_minimum_g_day,
    grid_step_g_day = record$grid_step_g_day
  )
  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  set.seed(as.integer(record$prediction_seed))
  draws <- as.matrix(brms::posterior_epred(
    candidate$model,
    newdata = grid$newdata,
    re_formula = NA,
    ndraws = as.integer(record$draw_count)
  ))

  if (ncol(draws) != nrow(grid$keys) && nrow(draws) == nrow(grid$keys)) {
    draws <- t(draws)
  }
  if (
    nrow(draws) != as.integer(record$draw_count) ||
      ncol(draws) != nrow(grid$keys) || anyNA(draws)
  ) {
    stop("Assignment-derived predictions do not match their allocation.",
         call. = FALSE)
  }

  reduction <- list(
    family = "total_assignment",
    outcome = as.character(record$outcome),
    model_index = as.integer(record$model_index),
    model_name = as.character(record$model_name),
    weight = as.numeric(record$weight),
    draw_count = as.integer(record$draw_count),
    prediction_seed = as.integer(record$prediction_seed),
    fit_sha256 = as.character(record$fit_sha256),
    grid = grid$keys,
    draws = draws,
    settings = list(
      protein_min = grid$protein_min,
      protein_max = grid$protein_max,
      grid_step = grid$grid_step,
      reference_intake = grid$reference_g_day,
      internal_unit_g_day = grid$unit_g_day,
      prediction_type = "total_assignment"
    )
  )

  write_atomic_qs(reduction, result_path)
}

make_update_2026_total_assignment_model_average_records <- function(
    prediction_manifest,
    stacking_weights,
    n_draws = 4000L,
    seed = 114988L
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  expected_counts <- c(
    whole_body = 18L,
    hypertrophy = 18L,
    strength = 15L,
    "function" = 18L
  )

  if (
    !is.data.frame(prediction_manifest) ||
      !is.data.frame(stacking_weights) ||
      nrow(stacking_weights) != 69L ||
      any(prediction_manifest$family != "total_assignment")
  ) {
    stop("The assignment-derived averaging inputs are invalid.",
         call. = FALSE)
  }

  purrr::map(seq_along(outcomes), function(index) {
    outcome <- outcomes[[index]]
    files <- dplyr::filter(
      prediction_manifest,
      .data$outcome == .env$outcome
    )
    weights <- dplyr::filter(
      stacking_weights,
      .data$outcome == .env$outcome
    ) |>
      dplyr::arrange(model_index)
    if (
      nrow(files) < 1L || sum(files$draw_count) != n_draws ||
        nrow(weights) != expected_counts[[outcome]] ||
        abs(sum(weights$weight) - 1) > 1e-8 ||
        any(!file.exists(files$prediction_path))
    ) {
      stop("An assignment-derived model-average record is invalid.",
           call. = FALSE)
    }
    list(
      family = "total_assignment",
      outcome = outcome,
      prediction_manifest = files,
      stacking_weights = weights,
      n_draws = as.integer(n_draws),
      averaging_seed = as.integer(seed + index)
    )
  })
}

write_update_2026_total_assignment_reporting_file <- function(
    model_average_path,
    data_by_outcome,
    reference_intake = 78.785,
    sesoi = 0.10,
    result_path
) {
  model_average <- read_sensitivity_full_model_average_file(
    model_average_path,
    family = "total_assignment"
  )
  outcome <- model_average$outcome
  data <- data_by_outcome[[outcome]]

  if (is.null(data) || !is.data.frame(data)) {
    stop("The assignment-derived reporting data are unavailable.",
         call. = FALSE)
  }
  absolute <- summarise_primary_dose_response(model_average)
  supported <- build_sensitivity_mundlak_reporting_pilot(
    absolute,
    model_average,
    data,
    reference_intake
  )
  heatmap <- compute_primary_heatmap_contrasts(
    model_average = model_average,
    data = data,
    protein_min = 50,
    sesoi = sesoi
  )
  report <- list(
    family = "total_assignment",
    outcome = outcome,
    dose_response = supported$absolute_full_grid,
    dose_response_increments = supported$increments_full_grid,
    exposure_support_by_group = supported$support_by_group,
    common_exposure_support = supported$common_support,
    pairwise_contrasts = heatmap$contrasts,
    pairwise_support = heatmap$support,
    local_equivalence = summarise_primary_local_equivalence(
      heatmap$contrasts,
      outcome = outcome
    ),
    model_weights = tibble::tibble(
      model_name = names(model_average$model_weights),
      weight = as.numeric(model_average$model_weights)
    ),
    settings = utils::modifyList(
      model_average$settings,
      list(
        reference_intake = reference_intake,
        sesoi = sesoi,
        exposure = "total_g_day",
        exposure_definition = "assignment_common_sample",
        exposure_unit = "g/day"
      )
    )
  )

  write_atomic_qs(report, result_path)
}

write_update_2026_total_assignment_reporting_audit <- function(
    audit,
    prediction_manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "reporting"
    )
) {
  if (
    !identical(audit$family, "total_assignment") ||
      !isTRUE(audit$all_reporting_checks_pass) ||
      nrow(audit$summary) != 4L ||
      sum(prediction_manifest$draw_count) != 16000L
  ) {
    stop("The assignment-derived reporting audit is incomplete.",
         call. = FALSE)
  }

  reports <- purrr::map(
    audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "total_assignment"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(
      report$model_weights,
      outcome = report$outcome,
      .before = 1L
    )
  })
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    prediction_manifest = file.path(output_dir, "prediction_manifest.csv"),
    dose_response = file.path(output_dir, "dose_response.csv"),
    dose_response_increments = file.path(
      output_dir, "dose_response_increments.csv"
    ),
    exposure_support_by_group = file.path(
      output_dir, "exposure_support_by_group.csv"
    ),
    common_exposure_support = file.path(
      output_dir, "common_exposure_support.csv"
    ),
    pairwise_contrasts = file.path(output_dir, "pairwise_contrasts.csv.gz"),
    pairwise_support = file.path(output_dir, "pairwise_support.csv"),
    local_equivalence = file.path(output_dir, "local_equivalence.csv"),
    model_weights = file.path(output_dir, "model_weights.csv")
  )

  readr::write_csv(audit$summary, paths[["summary"]])
  readr::write_csv(prediction_manifest, paths[["prediction_manifest"]])
  readr::write_csv(bind_report("dose_response"), paths[["dose_response"]])
  readr::write_csv(
    bind_report("dose_response_increments"),
    paths[["dose_response_increments"]]
  )
  readr::write_csv(
    bind_report("exposure_support_by_group"),
    paths[["exposure_support_by_group"]]
  )
  readr::write_csv(
    bind_report("common_exposure_support"),
    paths[["common_exposure_support"]]
  )
  readr::write_csv(
    bind_report("pairwise_contrasts"),
    paths[["pairwise_contrasts"]]
  )
  readr::write_csv(
    bind_report("pairwise_support"),
    paths[["pairwise_support"]]
  )
  readr::write_csv(
    bind_report("local_equivalence"),
    paths[["local_equivalence"]]
  )
  readr::write_csv(model_weights, paths[["model_weights"]])
  unname(paths)
}

make_update_2026_total_assignment_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    data_by_outcome,
    specifications,
    accepted_fit_manifest,
    diagnostic_audit,
    exclusion_audit,
    integrated_loo_audit,
    exact_diagnostic_audit,
    exact_correction_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  expected_model_counts <- c(18L, 18L, 15L, 18L)
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  analysis_sample_summary <- analysis_data |>
    dplyr::summarise(
      contrasts = dplyr::n(),
      studies = dplyr::n_distinct(study_no),
      arms = dplyr::n_distinct(arm_no),
      exposure_minimum_g_day = min(protein_intake_raw),
      exposure_maximum_g_day = max(protein_intake_raw),
      achieved_minimum_g_day = min(achieved_exposure_g_day),
      achieved_maximum_g_day = max(achieved_exposure_g_day),
      .by = analysis_outcome
    ) |>
    dplyr::arrange(factor(analysis_outcome, levels = outcomes))

  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  accepted_keys <- registry_keys(accepted_fit_manifest)
  retained_specifications <- specification_table |>
    dplyr::filter(
      paste(outcome, model_index, sep = "::") %in% accepted_keys
    )
  retained_diagnostics <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(
      paste(outcome, model_index, sep = "::") %in% accepted_keys
    )
  excluded_diagnostics <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(
      paste(outcome, model_index, sep = "::") %in%
        exclusion_audit$excluded_keys
    )
  specification_keys <- registry_keys(retained_specifications)
  diagnostic_keys <- registry_keys(retained_diagnostics)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, accepted_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- retained_specifications |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      retained_diagnostics |>
        dplyr::select(outcome, model_index, diagnostic_name = model),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  weight_sums <- stacking_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes))
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )
  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "total_assignment"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  correction_manifest <- exact_correction_audit$correction_manifest
  initial_integrated_model_summary <- integrated_loo_audit$model_summary |>
    dplyr::filter(method == "integrated_observation_level_psis")
  initial_conditional_model_summary <- integrated_loo_audit$model_summary |>
    dplyr::filter(method == "conditional_observation_level_psis")
  expected_contrasts <- c(
    whole_body = 182L,
    hypertrophy = 328L,
    strength = 546L,
    `function` = 200L
  )
  accepted_outcome_counts <- table(factor(
    accepted_fit_manifest$outcome,
    levels = outcomes
  ))
  accepted_stage_counts <- table(accepted_fit_manifest$stage)
  excluded_keys <- paste(
    excluded_diagnostics$outcome,
    excluded_diagnostics$model_index,
    sep = "::"
  )

  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      "all four assignment-derived common-sample datasets are valid",
      "three non-estimable sensitivity models remain explicitly excluded",
      "all five retained registries contain the same 69 model keys",
      "retained model names agree across specifications fits diagnostics LOO and weights",
      "all 69 accepted fit files exist and have checksums",
      "accepted diagnostics pass and excluded diagnostics remain identified",
      "initial LOO contains 69 aligned models and eight high-k cases",
      "all eight exact-refit sampling diagnostics pass",
      "all eight compact exact corrections exist and have checksums",
      "final LOO contains 69 models and no unresolved high-k cases",
      "four stacking vectors contain 18 18 15 and 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      "all four assignment-derived reporting audits pass"
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      identical(names(data_by_outcome), outcomes) &&
        identical(
          analysis_sample_summary$contrasts,
          unname(expected_contrasts[analysis_sample_summary$analysis_outcome])
        ) &&
        all(analysis_data$total_achieved_common_sample) &&
        all(analysis_data$total_assignment_common_sample) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0) &&
        all(is.finite(analysis_data$mean_body_mass_kg)) &&
        all(is.finite(analysis_data$achieved_exposure_g_day)) &&
        all(is.finite(analysis_data$assignment_exposure_g_day)) &&
        all(abs(
          analysis_data$protein_intake_raw -
            analysis_data$assignment_exposure_g_day
        ) < 1e-8) &&
        all(analysis_data$absolute_exposure_reference_g_day == 78.785) &&
        all(analysis_data$absolute_exposure_unit_g_day == 50),
      identical(exclusion_audit$family, "total_assignment") &&
        isTRUE(exclusion_audit$approved) &&
        exclusion_audit$excluded_models == 3L &&
        exclusion_audit$retained_models == 69L &&
        !isTRUE(exclusion_audit$preregistered_analysis_affected) &&
        nrow(exclusion_audit$exclusion_summary) == 3L &&
        nrow(exclusion_audit$diagnostic_history) == 9L &&
        setequal(
          exclusion_audit$excluded_keys,
          c("strength::11", "strength::23", "strength::26")
        ),
      common_registry && length(specification_keys) == 69L &&
        identical(as.integer(accepted_outcome_counts), expected_model_counts),
      nrow(name_alignment) == 69L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(
          name_alignment$diagnostic_name ==
            name_alignment$specification_name
        ) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(accepted_fit_manifest) == 69L &&
        identical(unname(accepted_stage_counts["initial"]), 62L) &&
        identical(unname(accepted_stage_counts["remedy_1"]), 7L) &&
        all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(accepted_fit_manifest$bytes > 0) &&
        all(nchar(accepted_fit_manifest$sha256) == 64L),
      identical(diagnostic_audit$family, "total_assignment") &&
        diagnostic_audit$models == 72L &&
        nrow(retained_diagnostics) == 69L &&
        all(retained_diagnostics$diagnostic_pass) &&
        nrow(excluded_diagnostics) == 3L &&
        all(!excluded_diagnostics$diagnostic_pass) &&
        setequal(excluded_keys, exclusion_audit$excluded_keys),
      identical(integrated_loo_audit$family, "total_assignment") &&
        integrated_loo_audit$models == 69L &&
        integrated_loo_audit$excluded_models == 3L &&
        nrow(initial_integrated_model_summary) == 69L &&
        nrow(initial_conditional_model_summary) == 69L &&
        integrated_loo_audit$exact_refits_required == 8L &&
        nrow(integrated_loo_audit$high_k_cases) == 8L,
      exact_diagnostic_audit$exact_refits == 8L &&
        exact_diagnostic_audit$exact_refits_passing == 8L &&
        isTRUE(exact_diagnostic_audit$all_exact_refit_diagnostics_pass),
      nrow(correction_manifest) == 8L &&
        all(file.exists(correction_manifest$correction_path)) &&
        all(correction_manifest$bytes > 0) &&
        all(nchar(correction_manifest$sha256) == 64L),
      identical(final_loo_audit$family, "total_assignment") &&
        nrow(final_loo_audit$model_summary) == 69L &&
        final_loo_audit$exact_refits == 8L &&
        isTRUE(final_loo_audit$stacking_ready) &&
        all(final_loo_audit$outcome_summary$unresolved_high_k_cases == 0L),
      nrow(weight_sums) == 4L &&
        identical(as.integer(weight_sums$models), expected_model_counts) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        sum(prediction_sums$selected_models) == 23L &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      identical(reporting_audit$family, "total_assignment") &&
        isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Updated total assignment-derived verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    preparation_outcome_counts = preparation_audit$outcome_counts,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    absolute_exposure_provenance = absolute_audit$exposure_provenance,
    absolute_support_by_outcome = absolute_audit$support_by_outcome,
    absolute_scaling_plan = absolute_audit$scaling_plan,
    absolute_model_registry = absolute_audit$model_registry,
    absolute_family_plan = absolute_audit$family_plan,
    analysis_data = analysis_data,
    analysis_sample_summary = analysis_sample_summary,
    model_specifications = specification_table,
    structural_exclusion_summary = exclusion_audit$exclusion_summary,
    structural_exclusion_history = exclusion_audit$diagnostic_history,
    model_name_alignment = name_alignment,
    accepted_fit_manifest = accepted_fit_manifest,
    sampling_diagnostic_summary = diagnostic_audit$diagnostic_summary,
    sampling_parameter_failures = diagnostic_audit$parameter_failures,
    initial_integrated_loo_model_summary =
      initial_integrated_model_summary,
    initial_integrated_loo_outcome_summary =
      integrated_loo_audit$outcome_summary,
    initial_high_pareto_k_cases = integrated_loo_audit$high_k_cases,
    exact_refit_diagnostic_summary =
      exact_diagnostic_audit$diagnostic_summary,
    exact_correction_manifest = correction_manifest,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    exact_refit_summary = final_loo_audit$exact_refit_summary,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    c(
      "Final assignment-derived total-intake checkpoint checks.",
      "Paths, sizes, and SHA-256 hashes for source data.",
      "Combined-data preparation invariants.",
      "Analysis counts by primary outcome.",
      "Shared absolute-exposure construction invariants.",
      "Eligible contrast counts for absolute exposure scales.",
      "Provenance of selected reported or derived exposures.",
      "Observed absolute-exposure support by outcome.",
      "Frozen references, units, and grid rules.",
      "Retained 18-model absolute-exposure registry.",
      "Planned primary and sensitivity absolute-exposure families.",
      "Common-sample arm-level data used by assignment-derived models.",
      "Outcome-level assignment and achieved exposure summary.",
      "Complete 72-model assignment-derived specification registry.",
      "Approved structural exclusions from the additional sensitivity.",
      "Three-stage diagnostic history for structural exclusions.",
      "Cross-stage retained-model name identity audit.",
      "Accepted 69-fit lineage with file checksums.",
      "Final model-level sampling diagnostics, including exclusions.",
      "Parameter-level diagnostic failures.",
      "Initial integrated PSIS-LOO summaries by retained model.",
      "Initial integrated PSIS-LOO summaries by outcome.",
      "The eight model-observation cases selected for exact refitting.",
      "Diagnostics for the eight exact-deletion refits.",
      "Compact exact-correction paths and checksums.",
      "Final exact-corrected LOO lineage.",
      "Final LOO summary for all 69 retained models.",
      "Final high-k resolution by outcome.",
      "Exact-refit correction summary.",
      "Final exact-corrected assignment-derived stacking weights.",
      "Allocation of 4,000 prediction draws per outcome.",
      "Reporting file dimensions and checksums.",
      "Model-averaged assignment-derived dose-response curves.",
      "Changes from the 78.785 g/day reference.",
      "Observed assignment-derived intake support by training group.",
      "Assignment-derived intake support common to training groups.",
      "Pairwise assignment-derived intake contrasts and probabilities.",
      "Observed support for pairwise contrasts.",
      "Practical-equivalence summaries in grams per day."
    ),
    names(artifacts)
  )

  list(
    checks = checks,
    artifacts = artifacts,
    descriptions = descriptions,
    next_family = paste(
      "The assignment-derived total-intake common-sample family is frozen",
      "after this verification checkpoint; its lean-pruning plan can be",
      "audited without changing the preregistered analyses."
    )
  )
}

make_update_2026_total_assignment_pruning_plan <- function(
    accepted_fit_manifest,
    exact_diagnostic_audit,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "total_assignment_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (any(!file.exists(verification_files))) {
    stop("The assignment-derived verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  verification_index <- readr::read_csv(
    verification_manifest,
    show_col_types = FALSE
  )

  if (length(verification_files) != nrow(verification_index) + 2L) {
    stop("The assignment-derived verification-file count is invalid.",
         call. = FALSE)
  }

  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the assignment-derived archive.",
         call. = FALSE)
  }

  fit_roots <- file.path(
    archive_root,
    c("initial", "remedy_1", "remedy_2", "remedy_3")
  )
  exact_fit_root <- file.path(archive_root, "loo", "exact_fit")
  if (any(!dir.exists(c(fit_roots, exact_fit_root)))) {
    stop("An expected assignment-derived fit directory is missing.",
         call. = FALSE)
  }

  fit_paths <- unlist(
    purrr::map(
      fit_roots,
      ~ list.files(
        .x,
        pattern = "\\.qs$",
        recursive = TRUE,
        full.names = TRUE
      )
    ),
    use.names = FALSE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)

  accepted_paths <- normalizePath(
    accepted_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  if (
    length(fit_paths) != 88L || length(accepted_paths) != 69L ||
      anyDuplicated(fit_paths) || anyDuplicated(accepted_paths) ||
      !all(accepted_paths %in% fit_paths) ||
      sum(!fit_paths %in% accepted_paths) != 19L
  ) {
    stop("Assignment-derived fit retention does not match its lineage.",
         call. = FALSE)
  }

  model_fit_manifest <- tibble::tibble(
    path = fit_paths,
    relative_path = substring(fit_paths, nchar(resolved_root) + 2L),
    archive_stage = dplyr::case_when(
      grepl("/initial/", fit_paths, fixed = TRUE) ~ "initial",
      grepl("/remedy_1/", fit_paths, fixed = TRUE) ~ "remedy_1",
      grepl("/remedy_2/", fit_paths, fixed = TRUE) ~ "remedy_2",
      grepl("/remedy_3/", fit_paths, fixed = TRUE) ~ "remedy_3",
      TRUE ~ "unknown"
    ),
    outcome = basename(dirname(fit_paths)),
    model_index = as.integer(sub(
      "^model_([0-9]+)\\.qs$", "\\1", basename(fit_paths)
    )),
    accepted_fit = fit_paths %in% accepted_paths,
    bytes = as.numeric(file.info(fit_paths)$size),
    lean_action = "delete frozen assignment-derived model fit"
  ) |>
    dplyr::arrange(archive_stage, outcome, model_index)

  stage_counts <- table(factor(
    model_fit_manifest$archive_stage,
    levels = c("initial", "remedy_1", "remedy_2", "remedy_3")
  ))
  if (
    any(model_fit_manifest$archive_stage == "unknown") ||
      anyNA(model_fit_manifest$model_index) ||
      !identical(as.integer(stage_counts), c(72L, 10L, 3L, 3L)) ||
      sum(model_fit_manifest$accepted_fit) != 69L ||
      sum(!model_fit_manifest$accepted_fit) != 19L ||
      any(model_fit_manifest$bytes <= 0)
  ) {
    stop("The assignment-derived model-fit stages are not as expected.",
         call. = FALSE)
  }

  exact_fit_paths <- list.files(
    exact_fit_root,
    pattern = "\\.qs$",
    recursive = TRUE,
    full.names = TRUE
  ) |>
    normalizePath(winslash = "/", mustWork = TRUE)
  exact_match <- stringr::str_match(
    basename(exact_fit_paths),
    "^model_([0-9]+)_case_([0-9]+)_observation_([0-9]+)\\.qs$"
  )
  exact_refit_manifest <- tibble::tibble(
    path = exact_fit_paths,
    relative_path = substring(exact_fit_paths, nchar(resolved_root) + 2L),
    archive_stage = "exact_refit",
    outcome = basename(dirname(exact_fit_paths)),
    model_index = as.integer(exact_match[, 2L]),
    case_id = as.integer(exact_match[, 3L]),
    observation = as.integer(exact_match[, 4L]),
    bytes = as.numeric(file.info(exact_fit_paths)$size),
    lean_action = "delete frozen assignment-derived exact-deletion refit"
  ) |>
    dplyr::arrange(case_id)

  exact_keys <- paste(
    exact_refit_manifest$outcome,
    exact_refit_manifest$model_index,
    exact_refit_manifest$observation,
    sep = "::"
  )
  diagnostic_keys <- paste(
    exact_diagnostic_audit$diagnostic_summary$outcome,
    exact_diagnostic_audit$diagnostic_summary$model_index,
    exact_diagnostic_audit$diagnostic_summary$observation,
    sep = "::"
  )

  if (
    nrow(exact_refit_manifest) != 8L ||
      anyNA(exact_refit_manifest[c("model_index", "case_id", "observation")]) ||
      !identical(exact_refit_manifest$case_id, seq_len(8L)) ||
      any(exact_refit_manifest$bytes <= 0) ||
      !setequal(exact_keys, diagnostic_keys) ||
      !isTRUE(exact_diagnostic_audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("The assignment-derived exact-refit inventory is invalid.",
         call. = FALSE)
  }

  deletion_manifest <- dplyr::bind_rows(
    model_fit_manifest |>
      dplyr::mutate(
        artifact_role = dplyr::if_else(
          accepted_fit,
          "accepted_model_fit",
          "superseded_or_excluded_model_fit"
        ),
        case_id = NA_integer_,
        observation = NA_integer_
      ),
    exact_refit_manifest |>
      dplyr::mutate(
        accepted_fit = FALSE,
        artifact_role = "exact_refit"
      )
  ) |>
    dplyr::select(
      path, relative_path, archive_stage, artifact_role, outcome,
      model_index, case_id, observation, accepted_fit, bytes, lean_action
    )

  compact_roots <- c(
    loo_psis = file.path(archive_root, "loo", "integrated"),
    exact_corrections = file.path(archive_root, "loo", "exact_correction"),
    reporting = file.path(archive_root, "reporting")
  )
  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact assignment-derived directory is missing.",
         call. = FALSE)
  }

  compact_paths <- unlist(
    purrr::map(
      compact_roots,
      ~ list.files(
        .x,
        recursive = TRUE,
        full.names = TRUE,
        all.files = TRUE
      )
    ),
    use.names = FALSE
  )

  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  normalized_compact_roots <- normalizePath(
    compact_roots,
    winslash = "/",
    mustWork = TRUE
  )
  component <- vapply(compact_paths, function(path) {
    matches <- names(compact_roots)[vapply(
      normalized_compact_roots,
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact assignment-derived result"
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo_psis", "exact_corrections", "reporting")
  ))
  if (
    nrow(compact_manifest) != 108L ||
      !identical(as.integer(compact_counts), c(69L, 8L, 31L)) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact assignment-derived archive is incomplete.",
         call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    full_fit_archives_deleted = nrow(deletion_manifest),
    accepted_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role == "accepted_model_fit"
    ),
    superseded_or_excluded_model_fit_archives_deleted = sum(
      deletion_manifest$artifact_role ==
        "superseded_or_excluded_model_fit"
    ),
    exact_refit_archives_deleted = sum(
      deletion_manifest$artifact_role == "exact_refit"
    ),
    full_fit_archives_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained = sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, exclusions, corrected LOO, and all 69 retained",
      "weights remain frozen; restoring model or exact-refit objects",
      "requires refitting the assignment-derived common-sample family."
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_fit_manifest,
    exact_refit_manifest = exact_refit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_total_assignment_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "assignment_common_sample", "pruning"
    )
) {
  if (
    nrow(plan$model_fit_manifest) != 88L ||
      nrow(plan$exact_refit_manifest) != 8L ||
      nrow(plan$deletion_file_manifest) != 96L ||
      nrow(plan$compact_archive_manifest) != 108L
  ) {
    stop("Cannot write an invalid assignment-derived pruning plan.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    exact_refit_manifest = file.path(output_dir, "exact_refit_manifest.csv"),
    deletion_file_manifest = file.path(
      output_dir, "deletion_file_manifest.csv"
    ),
    compact_archive_manifest = file.path(
      output_dir, "compact_archive_manifest.csv"
    )
  )

  readr::write_csv(plan$summary, paths[["summary"]])
  readr::write_csv(plan$model_fit_manifest, paths[["model_fit_manifest"]])
  readr::write_csv(plan$exact_refit_manifest, paths[["exact_refit_manifest"]])
  readr::write_csv(
    plan$deletion_file_manifest,
    paths[["deletion_file_manifest"]]
  )
  readr::write_csv(
    plan$compact_archive_manifest,
    paths[["compact_archive_manifest"]]
  )
  unname(paths)
}

# Absolute total-intake errors-in-variables sensitivity ----

# Prepare the absolute total-intake values and their uncertainty for the
# measurement-error model.
make_update_2026_total_eiv_data_by_outcome <- function(
    total_primary_data_by_outcome,
    absolute_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  if (
    !identical(names(total_primary_data_by_outcome), outcomes) ||
      !isTRUE(absolute_audit$ready_for_review) ||
      any(!absolute_audit$checks$passed)
  ) {
    stop("The absolute total-intake EIV source registry is invalid.",
         call. = FALSE)
  }

  output <- purrr::map(total_primary_data_by_outcome, function(data) {
    required <- c(
      "study_no", "arm_no", "outcome_no", "yi", "vi",
      "total_g_day", "total_g_day_se", "mean_body_mass_kg",
      "resistance_exercise_code", "age_centre", "duration_centre",
      "absolute_exposure_reference_g_day",
      "absolute_exposure_unit_g_day"
    )
    if (!all(required %in% names(data))) {
      stop("An absolute total-intake EIV source is incomplete.",
           call. = FALSE)
    }
    data |>
      dplyr::filter(
        is.finite(total_g_day),
        is.finite(total_g_day_se),
        total_g_day_se > 0,
        is.finite(mean_body_mass_kg),
        mean_body_mass_kg > 0
      ) |>
      dplyr::mutate(
        protein_intake_raw = total_g_day,
        protein_intake =
          (total_g_day - absolute_exposure_reference_g_day) /
            absolute_exposure_unit_g_day,
        protein_intake_se =
          total_g_day_se / absolute_exposure_unit_g_day,
        protein_median = absolute_exposure_reference_g_day,
        total_eiv_sample = TRUE
      ) |>
      droplevels()
  })

  expected_rows <- c(
    whole_body = 247L,
    hypertrophy = 373L,
    strength = 721L,
    `function` = 323L
  )
  expected_studies <- c(
    whole_body = 72L,
    hypertrophy = 48L,
    strength = 76L,
    `function` = 31L
  )
  expected_arms <- c(
    whole_body = 193L,
    hypertrophy = 131L,
    strength = 202L,
    `function` = 87L
  )
  audit_rows <- c(
    whole_body = 247L,
    hypertrophy = 381L,
    strength = 721L,
    `function` = 323L
  )
  audit_studies <- c(
    whole_body = 72L,
    hypertrophy = 49L,
    strength = 76L,
    `function` = 31L
  )
  audit_arms <- c(
    whole_body = 193L,
    hypertrophy = 133L,
    strength = 202L,
    `function` = 87L
  )
  coverage <- absolute_audit$outcome_coverage |>
    dplyr::filter(exposure == "total_g_day_eiv_input") |>
    dplyr::arrange(factor(outcome, levels = outcomes))

  if (
    !identical(vapply(output, nrow, integer(1L)), expected_rows) ||
      !identical(
        vapply(
          output,
          function(x) dplyr::n_distinct(x$study_no),
          integer(1L)
        ),
        expected_studies
      ) ||
      !identical(
        vapply(
          output,
          function(x) dplyr::n_distinct(x$arm_no),
          integer(1L)
        ),
        expected_arms
      ) ||
      nrow(coverage) != 4L ||
      !identical(coverage$contrasts, unname(audit_rows[coverage$outcome])) ||
      !identical(coverage$studies, unname(audit_studies[coverage$outcome])) ||
      !identical(coverage$arms, unname(audit_arms[coverage$outcome])) ||
      any(vapply(output, function(x) {
        any(!x$total_eiv_sample) ||
          any(!is.finite(x$protein_intake)) ||
          any(!is.finite(x$protein_intake_se)) ||
          any(x$protein_intake_se <= 0) ||
          any(!is.finite(x$mean_body_mass_kg)) ||
          any(x$mean_body_mass_kg <= 0) ||
          any(x$absolute_exposure_reference_g_day != 78.785) ||
          any(x$absolute_exposure_unit_g_day != 50)
      }, logical(1L)))
  ) {
    stop("The absolute total-intake EIV samples are incomplete.",
         call. = FALSE)
  }

  output
}

make_update_2026_total_eiv_specifications <- function(
    total_primary_specifications
) {
  longer_sampling <- c(
    "whole_body::2", "whole_body::5", "whole_body::26"
  )
  first_escalation <- c(
    "whole_body::23", "hypertrophy::23", "strength::15"
  )
  second_escalation <- "whole_body::14"
  specifications <- dplyr::bind_rows(total_primary_specifications) |>
    dplyr::mutate(
      key = paste(outcome, model_index, sep = "::"),
      family = "total_eiv",
      exposure = "total_g_day",
      exposure_error = "total_g_day_se",
      eiv = TRUE,
      historical_schedule = dplyr::case_when(
        key %in% longer_sampling ~ "longer_sampling",
        key %in% first_escalation ~ "remedy_1",
        key %in% second_escalation ~ "remedy_2",
        TRUE ~ "base"
      ),
      adapt_delta = dplyr::if_else(
        historical_schedule %in% c("remedy_1", "remedy_2"),
        pmax(as.numeric(adapt_delta), 0.999),
        as.numeric(adapt_delta)
      ),
      max_treedepth = dplyr::if_else(
        historical_schedule %in% c("remedy_1", "remedy_2"),
        pmax(as.integer(max_treedepth), 15L),
        as.integer(max_treedepth)
      ),
      iter_warmup = dplyr::case_when(
        historical_schedule == "remedy_2" ~ 3000L,
        historical_schedule %in% c("longer_sampling", "remedy_1") ~
          2000L,
        TRUE ~ 1500L
      ),
      iter_sampling = dplyr::case_when(
        historical_schedule == "remedy_2" ~ 8000L,
        historical_schedule %in% c("longer_sampling", "remedy_1") ~
          4000L,
        TRUE ~ 2000L
      ),
      chains = 4L,
      parallel_chains = 4L,
      model_name = paste0(model_name, " [total_eiv]")
    ) |>
    dplyr::select(-key)

  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  keys <- paste(specifications$outcome, specifications$model_index,
                sep = "::")
  outcome_counts <- table(factor(
    specifications$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  schedule_counts <- table(factor(
    specifications$historical_schedule,
    levels = c("base", "longer_sampling", "remedy_1", "remedy_2")
  ))

  if (
    nrow(specifications) != 72L || anyDuplicated(keys) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !all(specifications$model_index %in% retained) ||
      !identical(as.integer(schedule_counts), c(65L, 3L, 3L, 1L)) ||
      !setequal(
        keys[specifications$historical_schedule != "base"],
        c(longer_sampling, first_escalation, second_escalation)
      ) ||
      any(specifications$chains != 4L) ||
      any(specifications$parallel_chains != 4L)
  ) {
    stop("The absolute total-intake EIV registry failed validation.",
         call. = FALSE)
  }

  output <- purrr::pmap(specifications, list)
  names(output) <- paste0(
    specifications$outcome,
    "_model_",
    stringr::str_pad(specifications$model_index, 2L, pad = "0")
  )
  output
}

make_update_2026_total_eiv_config <- function(
    base_config,
    seed_offset = 383000L
) {
  config <- make_eiv_full_expansion_config(
    base_config = base_config,
    iter_warmup = 1500L,
    iter_sampling = 2000L,
    seed_offset = seed_offset
  )
  config$family <- "total_eiv"
  config$reference_g_day <- 78.785
  config$internal_unit_g_day <- 50
  config$grid_minimum_g_day <- 50
  config$grid_step_g_day <- 1
  config
}

update_2026_total_eiv_local_config <- function(specification, config) {
  local_config <- config
  local_config$iter_warmup <- as.integer(specification$iter_warmup)
  local_config$iter_sampling <- as.integer(specification$iter_sampling)
  local_config$adapt_delta_floor <- max(
    as.numeric(config$adapt_delta_floor),
    as.numeric(specification$adapt_delta)
  )
  local_config$max_treedepth_floor <- max(
    as.integer(config$max_treedepth_floor),
    as.integer(specification$max_treedepth)
  )
  outcome_offset <- match(specification$outcome, config$outcomes)

  if (is.na(outcome_offset)) {
    stop("Unknown outcome in the absolute total-intake EIV configuration.",
         call. = FALSE)
  }
  local_config$seed <- as.integer(
    config$seed + 100L * (outcome_offset - 1L) +
      as.integer(specification$model_index)
  )
  local_config
}

prepare_update_2026_total_eiv_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome,
    config
) {
  data <- data_by_outcome[[specification$outcome]]
  priors <- priors_by_outcome[[specification$outcome]]

  if (is.null(data) || !nrow(data) || is.null(priors)) {
    stop("Absolute total-intake EIV data or priors are missing.",
         call. = FALSE)
  }
  data <- add_absolute_primary_body_mass(data)
  input <- make_eiv_candidate_data(data, specification, priors)
  ordered_data <- data |>
    dplyr::filter(
      is.finite(yi), is.finite(vi), vi > 0,
      is.finite(protein_intake), is.finite(protein_intake_se),
      protein_intake_se > 0
    ) |>
    dplyr::arrange(study_no, arm_no, outcome_no)
  exposure_maximum <- max(data$protein_intake_raw, na.rm = TRUE)
  exposure_values <- sort(unique(c(
    round(seq(
      config$grid_minimum_g_day,
      exposure_maximum,
      by = config$grid_step_g_day
    ), 10),
    config$reference_g_day
  )))

  grid <- tidyr::crossing(
    resistance_exercise_code = c(0, 1),
    protein_intake_raw = exposure_values
  ) |>
    dplyr::mutate(
      protein_intake =
        (protein_intake_raw - config$reference_g_day) /
          config$internal_unit_g_day
    )

  age_grid_z <- input$stan_data$age_grid_z[[1L]]
  duration_grid_z <- input$stan_data$duration_grid_z[[1L]]
  input$family <- "total_eiv"
  input$specification$family <- "total_eiv"
  input$grid <- grid
  input$stan_data$body_mass_z <- ordered_data$body_mass_outcome_z
  input$stan_data$N_grid <- nrow(grid)
  input$stan_data$x_grid <- grid$protein_intake
  input$stan_data$rt_grid <- grid$resistance_exercise_code
  input$stan_data$age_grid_z <- rep(age_grid_z, nrow(grid))
  input$stan_data$duration_grid_z <- rep(duration_grid_z, nrow(grid))
  input$stan_data$body_mass_grid_z <- rep(0, nrow(grid))
  input$reference_g_day <- config$reference_g_day
  input$internal_unit_g_day <- config$internal_unit_g_day
  input$grid_minimum_g_day <- config$grid_minimum_g_day
  input$grid_step_g_day <- config$grid_step_g_day
  input
}

validate_update_2026_total_eiv_inputs <- function(inputs, config) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    local_config <- update_2026_total_eiv_local_config(
      specification,
      config
    )
    stan_data <- input$stan_data
    effective_adapt_delta <- max(
      as.numeric(specification$adapt_delta),
      as.numeric(local_config$adapt_delta_floor)
    )
    effective_max_treedepth <- max(
      as.integer(specification$max_treedepth),
      as.integer(local_config$max_treedepth_floor)
    )
    valid <-
      identical(input$family, "total_eiv") &&
      is.list(stan_data) && stan_data$N > 0L && stan_data$N_arm > 0L &&
      stan_data$N_study > 0L && stan_data$N_outcome > 0L &&
      length(stan_data$y) == stan_data$N &&
      length(stan_data$arm) == stan_data$N &&
      length(stan_data$body_mass_z) == stan_data$N &&
      length(stan_data$x_obs) == stan_data$N_arm &&
      length(stan_data$x_se) == stan_data$N_arm &&
      all(is.finite(stan_data$x_obs)) &&
      all(is.finite(stan_data$x_se)) && all(stan_data$x_se > 0) &&
      all(is.finite(stan_data$body_mass_z)) &&
      stan_data$N_grid == nrow(input$grid) &&
      length(stan_data$body_mass_grid_z) == stan_data$N_grid &&
      all(stan_data$body_mass_grid_z == 0) &&
      all(is.finite(input$grid$protein_intake)) &&
      min(input$grid$protein_intake_raw) == config$grid_minimum_g_day &&
      config$reference_g_day %in% input$grid$protein_intake_raw &&
      is.finite(effective_adapt_delta) && effective_adapt_delta > 0 &&
      effective_adapt_delta < 1 && effective_max_treedepth >= 1L
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      contrasts = as.integer(stan_data$N),
      studies = as.integer(stan_data$N_study),
      arms = as.integer(stan_data$N_arm),
      outcome_rows = as.integer(stan_data$N_outcome),
      exposure_minimum_g_day =
        min(stan_data$x_obs) * config$internal_unit_g_day +
          config$reference_g_day,
      exposure_maximum_g_day =
        max(stan_data$x_obs) * config$internal_unit_g_day +
          config$reference_g_day,
      minimum_exposure_se_g_day =
        min(stan_data$x_se) * config$internal_unit_g_day,
      maximum_exposure_se_g_day =
        max(stan_data$x_se) * config$internal_unit_g_day,
      reference_g_day = config$reference_g_day,
      internal_unit_g_day = config$internal_unit_g_day,
      grid_minimum_g_day = config$grid_minimum_g_day,
      grid_step_g_day = config$grid_step_g_day,
      historical_schedule = specification$historical_schedule,
      adapt_delta = effective_adapt_delta,
      max_treedepth = effective_max_treedepth,
      iter_warmup = as.integer(local_config$iter_warmup),
      iter_sampling = as.integer(local_config$iter_sampling),
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      valid = valid
    )
  }) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  outcome_counts <- table(factor(checks$outcome, levels = outcomes))
  schedule_counts <- table(factor(
    checks$historical_schedule,
    levels = c("base", "longer_sampling", "remedy_1", "remedy_2")
  ))
  sample_counts <- checks |>
    dplyr::distinct(
      outcome, contrasts, studies, arms, outcome_rows,
      exposure_minimum_g_day, exposure_maximum_g_day,
      minimum_exposure_se_g_day, maximum_exposure_se_g_day,
      reference_g_day, internal_unit_g_day,
      grid_minimum_g_day, grid_step_g_day
    )

  expected_rows <- c(247L, 373L, 721L, 323L)
  expected_studies <- c(72L, 48L, 76L, 31L)
  expected_arms <- c(193L, 131L, 202L, 87L)
  if (
    nrow(checks) != 72L || anyDuplicated(keys) || !all(checks$valid) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !identical(as.integer(schedule_counts), c(65L, 3L, 3L, 1L)) ||
      nrow(sample_counts) != 4L ||
      !identical(sample_counts$contrasts, expected_rows) ||
      !identical(sample_counts$studies, expected_studies) ||
      !identical(sample_counts$arms, expected_arms) ||
      any(sample_counts$minimum_exposure_se_g_day <= 0) ||
      any(!is.finite(sample_counts$maximum_exposure_se_g_day)) ||
      any(checks$reference_g_day != 78.785) ||
      any(checks$internal_unit_g_day != 50) ||
      any(checks$grid_minimum_g_day != 50) ||
      any(checks$grid_step_g_day != 1) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The absolute total-intake EIV input preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_eiv_input_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "input_preflight.csv"
    )
) {
  if (nrow(checks) != 72L || !all(checks$valid)) {
    stop("Cannot write an incomplete absolute total-intake EIV preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file)
  output_file
}

read_update_2026_total_eiv_fit_file <- function(path) {
  if (length(path) != 1L || is.na(path) || !file.exists(path)) {
    stop("The absolute total-intake EIV fit file is unavailable.",
         call. = FALSE)
  }
  candidate <- qs::qread(path)
  output_files <- tryCatch(
    candidate$fit$output_files(),
    error = function(error) character()
  )

  if (
    !is.list(candidate) || !identical(candidate$family, "total_eiv") ||
      !inherits(candidate$fit, "CmdStanMCMC") ||
      is.null(candidate$outcome) || is.null(candidate$model_index) ||
      length(output_files) != 4L || any(!file.exists(output_files))
  ) {
    stop(
      paste0(
        "The absolute total-intake EIV fit is invalid or its CmdStan ",
        "CSV files are missing."
      ),
      call. = FALSE
    )
  }

  candidate
}

fit_update_2026_total_eiv_candidate_to_file <- function(
    input,
    model,
    config,
    enabled,
    stage = "initial",
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      paste0(
        "Absolute total-intake EIV fitting is disabled. Set ",
        "PROTEIN_UPDATE_2026_TOTAL_EIV=fit to enable it."
      ),
      call. = FALSE
    )
  }

  if (is_sensitivity_pilot_skip(model)) {
    stop("The absolute total-intake EIV Stan model was not compiled.",
         call. = FALSE)
  }
  if (!identical(input$family, "total_eiv")) {
    stop("The absolute total-intake EIV fit input is invalid.",
         call. = FALSE)
  }

  specification <- input$specification
  local_config <- update_2026_total_eiv_local_config(
    specification,
    config
  )
  effective_adapt_delta <- max(
    as.numeric(specification$adapt_delta),
    as.numeric(local_config$adapt_delta_floor)
  )
  effective_max_treedepth <- max(
    as.integer(specification$max_treedepth),
    as.integer(local_config$max_treedepth_floor)
  )
  specification$adapt_delta <- effective_adapt_delta
  specification$max_treedepth <- effective_max_treedepth
  specification$update_2026_iter_warmup <-
    as.integer(local_config$iter_warmup)
  specification$update_2026_iter_sampling <-
    as.integer(local_config$iter_sampling)
  input_sha256 <- digest::digest(
    list(
      specification = specification,
      stan_data = input$stan_data,
      grid = input$grid
    ),
    algo = "sha256"
  )

  stan_file <- model$stan_file()
  if (length(stan_file) != 1L || is.na(stan_file) || !file.exists(stan_file)) {
    stop("The absolute total-intake EIV Stan source is unavailable.",
         call. = FALSE)
  }
  stan_sha256 <- digest::digest(
    file = stan_file,
    algo = "sha256",
    serialize = FALSE
  )
  candidate_dir <- file.path(
    output_root,
    specification$outcome,
    sprintf("model_%02d", as.integer(specification$model_index))
  )
  output_file <- file.path(candidate_dir, "fit.qs")
  cmdstan_dir <- file.path(candidate_dir, "cmdstan")
  dir.create(cmdstan_dir, recursive = TRUE, showWarnings = FALSE)

  if (file.exists(output_file)) {
    existing <- tryCatch(
      read_update_2026_total_eiv_fit_file(output_file),
      error = function(error) NULL
    )
    if (
      !is.null(existing) &&
        identical(existing$outcome, specification$outcome) &&
        identical(
          as.integer(existing$model_index),
          as.integer(specification$model_index)
        ) &&
        identical(existing$archive_stage, stage) &&
        identical(
          existing$specification$historical_schedule,
          specification$historical_schedule
        ) &&
        identical(
          as.integer(existing$specification$update_2026_iter_warmup),
          as.integer(local_config$iter_warmup)
        ) &&
        identical(
          as.integer(existing$specification$update_2026_iter_sampling),
          as.integer(local_config$iter_sampling)
        ) &&
        identical(existing$input_sha256, input_sha256) &&
        identical(existing$stan_sha256, stan_sha256)
    ) {
      return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
    }
    stop(
      paste0(
        "An existing absolute total-intake EIV fit archive does not match ",
        "the current input; it was not overwritten."
      ),
      call. = FALSE
    )
  }

  fit <- model$sample(
    data = input$stan_data,
    chains = local_config$chains,
    parallel_chains = local_config$parallel_chains,
    iter_warmup = local_config$iter_warmup,
    iter_sampling = local_config$iter_sampling,
    adapt_delta = effective_adapt_delta,
    max_treedepth = effective_max_treedepth,
    seed = local_config$seed,
    refresh = 100,
    output_dir = cmdstan_dir
  )

  candidate <- list(
    family = "total_eiv",
    archive_stage = stage,
    outcome = specification$outcome,
    model_index = as.integer(specification$model_index),
    model_name = specification$model_name,
    specification = specification,
    grid = input$grid,
    output_dir = normalizePath(
      cmdstan_dir,
      winslash = "/",
      mustWork = TRUE
    ),
    input_sha256 = input_sha256,
    stan_sha256 = stan_sha256,
    fit = fit
  )

  write_atomic_qs(candidate, output_file)
}

make_update_2026_total_eiv_fit_manifest <- function(
    paths,
    stage = "initial"
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  if (
    length(paths) != 72L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The absolute total-intake EIV fit-file set is incomplete.",
         call. = FALSE)
  }

  manifest <- purrr::map_dfr(paths, function(path) {
    candidate <- read_update_2026_total_eiv_fit_file(path)
    tibble::tibble(
      family = candidate$family,
      outcome = candidate$outcome,
      model_index = as.integer(candidate$model_index),
      model_name = candidate$model_name,
      fit_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      stage = stage,
      historical_schedule =
        candidate$specification$historical_schedule,
      iter_warmup =
        as.integer(candidate$specification$update_2026_iter_warmup),
      iter_sampling =
        as.integer(candidate$specification$update_2026_iter_sampling),
      bytes = as.numeric(file.info(path)$size),
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  keys <- paste(manifest$outcome, manifest$model_index, sep = "::")
  outcome_counts <- table(factor(
    manifest$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  schedule_counts <- table(factor(
    manifest$historical_schedule,
    levels = c("base", "longer_sampling", "remedy_1", "remedy_2")
  ))

  if (
    nrow(manifest) != 72L || any(manifest$family != "total_eiv") ||
      anyDuplicated(keys) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !identical(as.integer(schedule_counts), c(65L, 3L, 3L, 1L)) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The absolute total-intake EIV fit manifest is invalid.",
         call. = FALSE)
  }

  manifest
}

write_update_2026_total_eiv_fit_manifest <- function(
    manifest,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
