diagnose_update_2026_total_eiv_fit_file <- function(path) {
  candidate <- read_update_2026_total_eiv_fit_file(path)
  generic_candidate <- candidate
  generic_candidate$family <- "eiv"
  diagnostic <- diagnose_cmdstan_pilot_fit(generic_candidate)
  diagnostic$family <- "total_eiv"
  diagnostic$model_name <- candidate$model_name
