}

compile_update_2026_total_eiv_diagnostic_audit <- function(
    diagnostics,
    fit_manifest
) {
  summary <- dplyr::bind_rows(diagnostics) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    ) |>
    dplyr::mutate(
      status = dplyr::if_else(
        diagnostic_pass,
        "PASS",
        "REQUIRES REMEDIATION"
      )
    )

  diagnostic_keys <- paste(summary$outcome, summary$model_index, sep = "::")
  manifest_keys <- paste(
    fit_manifest$outcome,
    fit_manifest$model_index,
    sep = "::"
  )

  if (
    nrow(summary) != 72L || nrow(fit_manifest) != 72L ||
      any(summary$family != "total_eiv") ||
      anyDuplicated(diagnostic_keys) ||
      !identical(diagnostic_keys, manifest_keys) ||
      !identical(summary$model_name, fit_manifest$model_name)
  ) {
    stop("The absolute total-intake EIV diagnostic audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_eiv",
    diagnostic_summary = summary,
    parameter_failures = tibble::tibble(),
    models = nrow(summary),
    models_passing_sampling = sum(summary$diagnostic_pass),
    models_requiring_remediation = sum(!summary$diagnostic_pass),
    all_sampling_diagnostics_pass = all(summary$diagnostic_pass)
  )
}

