}

make_update_2026_total_eiv_remedy_inputs <- function(
    inputs,
    diagnostic_audit
) {
  expected_keys <- c("whole_body::6", "strength::9")
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  whole_body_failure <- failed |>
    dplyr::filter(key == "whole_body::6")
  strength_failure <- failed |>
    dplyr::filter(key == "strength::9")

  if (
    !identical(diagnostic_audit$family, "total_eiv") ||
      diagnostic_audit$models != 72L || nrow(failed) != 2L ||
      anyDuplicated(failed$key) || !setequal(failed$key, expected_keys) ||
      nrow(whole_body_failure) != 1L ||
      !isTRUE(whole_body_failure$geometry_pass[[1L]]) ||
      isTRUE(whole_body_failure$convergence_pass[[1L]]) ||
      whole_body_failure$divergent_transitions[[1L]] != 0L ||
      whole_body_failure$maximum_treedepth_transitions[[1L]] != 0L ||
      whole_body_failure$minimum_bulk_ess[[1L]] < 400 ||
      whole_body_failure$minimum_tail_ess[[1L]] >= 400 ||
      whole_body_failure$maximum_mcse_sd_ratio[[1L]] > 0.10 ||
      nrow(strength_failure) != 1L ||
      isTRUE(strength_failure$geometry_pass[[1L]]) ||
      !isTRUE(strength_failure$convergence_pass[[1L]]) ||
      strength_failure$divergent_transitions[[1L]] != 1L ||
      strength_failure$maximum_treedepth_transitions[[1L]] != 0L ||
      strength_failure$minimum_ebfmi[[1L]] < 0.2
  ) {
    stop("The absolute total-intake EIV remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    ) %in% expected_keys
  })
  selected <- purrr::map(selected, function(input) {
    specification <- input$specification
    key <- paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    )
    if (key == "whole_body::6") {
      specification$iter_warmup <- 2000L
      specification$iter_sampling <- 6000L
      specification$remedy <-
        "extended_sampling_after_precision_failure"
      specification$remedy_reason <- paste(
        "Sampling geometry, R-hat, bulk ESS, and MCSE passed, but the",
        "minimum tail ESS was below 400."
      )
    } else if (key == "strength::9") {
      specification$adapt_delta <- max(
        as.numeric(specification$adapt_delta),
        0.999
      )
      specification$max_treedepth <- max(
        as.integer(specification$max_treedepth),
        15L
      )
      specification$iter_warmup <- 3000L
      specification$iter_sampling <- 6000L
      specification$remedy <-
        "stabilized_sampling_after_geometry_failure"
      specification$remedy_reason <- paste(
        "Convergence and precision thresholds passed, but the initial fit",
        "contained one divergent transition."
      )
    } else {
      stop("Unexpected absolute total-intake EIV remedy key.",
           call. = FALSE)
    }
    specification$archive_stage <- "remedy_1"
    input$specification <- specification
    input
  })

  selected_keys <- purrr::map_chr(selected, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })

  if (
    length(selected) != 2L || anyDuplicated(selected_keys) ||
      !setequal(selected_keys, expected_keys)
  ) {
    stop("Could not uniquely select the absolute total-intake EIV remedies.",
         call. = FALSE)
  }

  selected <- selected[match(expected_keys, selected_keys)]
  names(selected) <- c("whole_body_model_06", "strength_model_09")
  selected
}

validate_update_2026_total_eiv_remedy_inputs <- function(
    inputs,
    initial_fit_manifest,
    config
) {
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    local_config <- update_2026_total_eiv_local_config(
      specification,
      config
    )
    initial_fit <- initial_fit_manifest |>
      dplyr::filter(
        outcome == specification$outcome,
        model_index == specification$model_index
      )
    stan_data <- input$stan_data
    effective_adapt_delta <- max(
      as.numeric(specification$adapt_delta),
      as.numeric(local_config$adapt_delta_floor)
    )
    effective_max_treedepth <- max(
      as.integer(specification$max_treedepth),
      as.integer(local_config$max_treedepth_floor)
    )
    valid <-
      identical(input$family, "total_eiv") &&
      identical(specification$archive_stage, "remedy_1") &&
      is.list(stan_data) && stan_data$N > 0L &&
      length(stan_data$x_obs) == stan_data$N_arm &&
      length(stan_data$x_se) == stan_data$N_arm &&
      all(is.finite(stan_data$x_se)) && all(stan_data$x_se > 0) &&
      nrow(initial_fit) == 1L && file.exists(initial_fit$fit_path[[1L]])
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      contrasts = as.integer(stan_data$N),
      studies = as.integer(stan_data$N_study),
      arms = as.integer(stan_data$N_arm),
      adapt_delta = effective_adapt_delta,
      max_treedepth = effective_max_treedepth,
      iter_warmup = as.integer(local_config$iter_warmup),
      iter_sampling = as.integer(local_config$iter_sampling),
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      initial_fit_exists =
        nrow(initial_fit) == 1L && file.exists(initial_fit$fit_path[[1L]]),
      valid = valid
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  whole_body <- checks$outcome == "whole_body" & checks$model_index == 6L
  strength <- checks$outcome == "strength" & checks$model_index == 9L
  if (
    nrow(checks) != 2L || anyDuplicated(keys) ||
      !setequal(keys, c("whole_body::6", "strength::9")) ||
      sum(whole_body) != 1L || sum(strength) != 1L ||
      checks$remedy[whole_body] !=
        "extended_sampling_after_precision_failure" ||
      checks$iter_warmup[whole_body] != 2000L ||
      checks$iter_sampling[whole_body] != 6000L ||
      checks$remedy[strength] !=
        "stabilized_sampling_after_geometry_failure" ||
      checks$adapt_delta[strength] != 0.999 ||
      checks$max_treedepth[strength] != 15L ||
      checks$iter_warmup[strength] != 3000L ||
      checks$iter_sampling[strength] != 6000L ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$initial_fit_exists) || !all(checks$valid)
  ) {
    stop("The absolute total-intake EIV remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

