compile_update_2026_total_eiv_final_diagnostic_audit <- function(
    initial_audit,
    remedy_diagnostics
) {
  expected_keys <- c("whole_body::6", "strength::9")
  initial <- initial_audit$diagnostic_summary
  remedy <- dplyr::bind_rows(remedy_diagnostics)
  initial_keys <- paste(initial$outcome, initial$model_index, sep = "::")
  remedy_keys <- paste(remedy$outcome, remedy$model_index, sep = "::")
  initial_failed_keys <- initial_keys[!initial$diagnostic_pass]
  original_remedy_rows <- initial[match(remedy_keys, initial_keys), , drop = FALSE]

  if (
    !identical(initial_audit$family, "total_eiv") ||
      nrow(initial) != 72L || nrow(remedy) != 2L ||
      anyDuplicated(initial_keys) || anyDuplicated(remedy_keys) ||
      !setequal(initial_failed_keys, expected_keys) ||
      !setequal(remedy_keys, expected_keys) ||
      any(!remedy_keys %in% initial_keys) ||
      any(remedy$family != "total_eiv") ||
      !identical(remedy$model_name, original_remedy_rows$model_name)
  ) {
    stop("The absolute total-intake EIV diagnostic replacement is invalid.",
         call. = FALSE)
  }

  final <- initial |>
    dplyr::filter(!paste(outcome, model_index, sep = "::") %in% remedy_keys) |>
    dplyr::select(-status) |>
    dplyr::bind_rows(remedy) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    ) |>
    dplyr::mutate(
      status = dplyr::if_else(
        diagnostic_pass,
        "PASS",
        "REQUIRES REMEDIATION"
      )
    )

  final_keys <- paste(final$outcome, final$model_index, sep = "::")
  if (
    nrow(final) != 72L || anyDuplicated(final_keys) ||
      !setequal(final_keys, initial_keys)
  ) {
    stop("The final absolute total-intake EIV audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_eiv",
    diagnostic_summary = final,
    parameter_failures = tibble::tibble(),
    models = nrow(final),
    models_passing_sampling = sum(final$diagnostic_pass),
    models_requiring_remediation = sum(!final$diagnostic_pass),
    all_sampling_diagnostics_pass = all(final$diagnostic_pass)
  )
}

make_update_2026_total_eiv_accepted_fit_manifest <- function(
    initial_manifest,
    remedy_manifest,
    final_diagnostic_audit
) {
  expected_remedy_keys <- c("whole_body::6", "strength::9")
  remedy_keys <- paste(
    remedy_manifest$outcome,
    remedy_manifest$model_index,
    sep = "::"
  )
  final_summary <- final_diagnostic_audit$diagnostic_summary
  final_keys <- paste(
    final_summary$outcome,
    final_summary$model_index,
    sep = "::"
  )
  accepted <- initial_manifest |>
    dplyr::anti_join(
      remedy_manifest |> dplyr::select(outcome, model_index),
      by = c("outcome", "model_index")
    ) |>
    dplyr::bind_rows(remedy_manifest) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  accepted_keys <- paste(
    accepted$outcome,
    accepted$model_index,
    sep = "::"
  )
  outcome_counts <- table(factor(
    accepted$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  stage_counts <- table(factor(
    accepted$stage,
    levels = c("initial", "remedy_1")
  ))

  if (
    nrow(initial_manifest) != 72L || nrow(remedy_manifest) != 2L ||
      anyDuplicated(remedy_keys) ||
      !setequal(remedy_keys, expected_remedy_keys) ||
      !identical(final_diagnostic_audit$family, "total_eiv") ||
      !isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass) ||
      nrow(final_summary) != 72L || !all(final_summary$diagnostic_pass) ||
      nrow(accepted) != 72L || anyDuplicated(accepted_keys) ||
      !setequal(accepted_keys, final_keys) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !identical(as.integer(stage_counts), c(70L, 2L)) ||
      any(accepted$family != "total_eiv") ||
      !all(stringr::str_ends(
        accepted$model_name,
        stringr::fixed(" [total_eiv]")
      )) ||
      any(!file.exists(accepted$fit_path)) ||
      any(accepted$bytes <= 0) || any(nchar(accepted$sha256) != 64L)
  ) {
    stop("The accepted absolute total-intake EIV manifest is invalid.",
         call. = FALSE)
  }

  accepted
}

