validate_update_2026_total_eiv_loo_inputs <- function(
    accepted_fit_manifest,
    final_diagnostic_audit,
    inputs,
    loo_draws = 4000L,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  accepted_keys <- paste(
    accepted_fit_manifest$outcome,
    accepted_fit_manifest$model_index,
    sep = "::"
  )
  input_keys <- purrr::map_chr(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })
  input_families <- purrr::map_chr(inputs, "family")
  stage_counts <- table(factor(
    accepted_fit_manifest$stage,
    levels = c("initial", "remedy_1")
  ))
  outcome_counts <- table(factor(
    accepted_fit_manifest$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  checks <- tibble::tribble(
    ~check, ~passed,
    "all 72 final absolute total-intake EIV diagnostics pass",
    identical(final_diagnostic_audit$family, "total_eiv") &&
      final_diagnostic_audit$models == 72L &&
      isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass),
    "accepted registry contains 18 models per outcome",
    identical(as.integer(outcome_counts), rep(18L, 4L)),
    "accepted registry contains 70 initial and 2 remedy fits",
    identical(as.integer(stage_counts), c(70L, 2L)),
    "all 72 accepted fits align one-to-one with their EIV inputs",
    length(inputs) == 72L && !anyDuplicated(input_keys) &&
      setequal(accepted_keys, input_keys) &&
      all(input_families == "total_eiv"),
    "all accepted fit files exist are nonempty and have hashes",
    all(file.exists(accepted_fit_manifest$fit_path)) &&
      all(file.info(accepted_fit_manifest$fit_path)$size > 0) &&
      all(nchar(accepted_fit_manifest$sha256) == 64L),
    "integrated LOO uses 4000 draws a 0.7 threshold and one core per branch",
    identical(as.integer(loo_draws), 4000L) &&
      identical(k_threshold, 0.7) &&
      identical(as.integer(cores_per_branch), 1L)
  )

  ready <-
    nrow(accepted_fit_manifest) == 72L &&
    !anyDuplicated(accepted_keys) && all(checks$passed)
  if (!ready) {
    stop("The absolute total-intake EIV LOO preflight is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_eiv",
    models = 72L,
    loo_draws = as.integer(loo_draws),
    k_threshold = k_threshold,
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    ready = TRUE
  )
}

write_update_2026_total_eiv_loo_preflight <- function(
    preflight,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "loo_preflight"
    )
) {
  if (
    !identical(preflight$family, "total_eiv") ||
      !isTRUE(preflight$ready) || preflight$models != 72L ||
      !all(preflight$checks$passed)
  ) {
    stop("Cannot write an invalid absolute total-intake EIV LOO preflight.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    checks = file.path(output_dir, "checks.csv"),
    accepted_fit_manifest = file.path(
      output_dir,
      "accepted_fit_manifest.csv"
    )
  )
  readr::write_csv(preflight$checks, paths[["checks"]], na = "")
  readr::write_csv(
    preflight$accepted_fit_manifest,
    paths[["accepted_fit_manifest"]],
    na = ""
  )
  unname(paths)
}

make_update_2026_total_eiv_loo_records <- function(
    accepted_fit_manifest,
    inputs
) {
  accepted_keys <- paste(
    accepted_fit_manifest$outcome,
    accepted_fit_manifest$model_index,
    sep = "::"
  )
  input_keys <- purrr::map_chr(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })

  if (
    nrow(accepted_fit_manifest) != 72L || length(inputs) != 72L ||
      anyDuplicated(accepted_keys) || anyDuplicated(input_keys) ||
      !setequal(accepted_keys, input_keys) ||
      any(!file.exists(accepted_fit_manifest$fit_path))
  ) {
    stop("The absolute total-intake EIV fit/input registry is misaligned.",
         call. = FALSE)
  }

  records <- purrr::map(seq_len(nrow(accepted_fit_manifest)), function(row) {
    record <- purrr::map(
      as.list(accepted_fit_manifest[row, , drop = FALSE]),
      unname
    )
    record$input <- inputs[[match(accepted_keys[[row]], input_keys)]]
    record
  })

  names(records) <- paste0(
    accepted_fit_manifest$outcome,
    "_model_",
    stringr::str_pad(accepted_fit_manifest$model_index, 2L, pad = "0")
  )
  records
}

compute_update_2026_total_eiv_integrated_loo_to_file <- function(
    fit_record,
    enabled,
    loo_draws = 4000L,
    k_threshold = 0.7,
    cores = 1L,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "loo", "integrated"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      paste0(
        "Absolute total-intake EIV LOO is disabled. Set ",
        "PROTEIN_UPDATE_2026_TOTAL_EIV_LOO=run to enable it."
      ),
      call. = FALSE
    )
  }

  candidate <- read_update_2026_total_eiv_fit_file(fit_record$fit_path)
  input <- fit_record$input
  if (
    !identical(candidate$family, "total_eiv") ||
      !identical(input$family, "total_eiv") ||
      candidate$model_index != input$specification$model_index ||
      candidate$model_index != fit_record$model_index ||
      !identical(candidate$outcome, input$specification$outcome) ||
      !identical(candidate$outcome, fit_record$outcome)
  ) {
    stop("The absolute total-intake EIV LOO record is misaligned.",
         call. = FALSE)
  }

  available_draws <- posterior::ndraws(
    candidate$fit$draws("b_intercept")
  )
  if (
    length(available_draws) != 1L || is.na(available_draws) ||
      available_draws < 1L
  ) {
    stop("The absolute total-intake EIV fit has no posterior draws.",
         call. = FALSE)
  }

  job <- list(
    fitted_candidate = candidate,
    input = input,
    loo_draws = min(as.integer(loo_draws), available_draws),
    fit_draws = available_draws
  )
  result <- compute_eiv_integrated_psis_loo(
    job,
    k_threshold = k_threshold,
    cores = cores
  )
  result$fit_record <- fit_record[c(
    "family", "outcome", "model_index", "model_name", "fit_path",
    "stage", "bytes", "sha256"
  )]
  result$input <- input

  if (
    !inherits(result$loo, "loo") ||
      !inherits(result$conditional_loo, "loo") ||
      !identical(result$family, "total_eiv") ||
      !identical(
        result$remedy,
        "outcome_effects_integrated_latent_exposure_psis"
      ) ||
      result$model_index != fit_record$model_index ||
      !identical(result$outcome, fit_record$outcome)
  ) {
    stop("Cannot archive an invalid absolute total-intake EIV LOO result.",
         call. = FALSE)
  }

  output_dir <- file.path(output_root, result$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf(
      "model_%02d_integrated_loo.qs",
      as.integer(result$model_index)
    )
  )
  write_atomic_qs(result, output_file)
}

