read_update_2026_total_eiv_exact_fit_file <- function(path) {
  if (length(path) != 1L || is.na(path) || !file.exists(path)) {
    stop("An absolute total-intake EIV exact-refit file is unavailable.",
         call. = FALSE)
  }
  refit <- qs::qread(path)
  output_files <- tryCatch(
    refit$fitted_candidate$fit$output_files(),
    error = function(error) character()
  )

  if (
    !is.list(refit) || !identical(refit$family, "total_eiv") ||
      !identical(refit$fitted_candidate$family, "total_eiv") ||
      !inherits(refit$fitted_candidate$fit, "CmdStanMCMC") ||
      length(output_files) != 4L || any(!file.exists(output_files)) ||
      is.null(refit$case_id) || is.null(refit$observation)
  ) {
    stop("The absolute total-intake EIV exact refit is invalid.",
         call. = FALSE)
  }

  refit
}

fit_update_2026_total_eiv_exact_to_file <- function(
    record,
    model,
    enabled,
    config
) {
  if (!isTRUE(enabled)) {
    stop(
      paste0(
        "Absolute total-intake EIV exact refitting is disabled. Set ",
        "PROTEIN_UPDATE_2026_TOTAL_EIV_EXACT=fit to enable it."
      ),
      call. = FALSE
    )
  }

  if (is_sensitivity_pilot_skip(model)) {
    stop("The absolute total-intake EIV Stan model was not compiled.",
         call. = FALSE)
  }
  output_file <- update_2026_total_eiv_exact_fit_file_path(record)
  existing <- if (file.exists(output_file)) {
    tryCatch(
      read_update_2026_total_eiv_exact_fit_file(output_file),
      error = function(error) NULL
    )
  } else {
    NULL
  }

  if (
    !is.null(existing) &&
      identical(as.integer(existing$case_id), as.integer(record$case_id)) &&
      identical(existing$outcome, record$outcome) &&
      identical(
        as.integer(existing$model_index),
        as.integer(record$model_index)
      ) &&
      identical(
        as.integer(existing$observation),
        as.integer(record$observation)
      ) &&
      identical(existing$source_fit_sha256, record$original_fit_sha256) &&
      identical(
        existing$source_integrated_loo_sha256,
        record$integrated_loo_sha256
      )
  ) {
    return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
  }

  if (file.exists(output_file)) {
    stop(
      paste0(
        "An existing absolute total-intake EIV exact refit does not match ",
        "the current case; it was not overwritten."
      ),
      call. = FALSE
    )
  }

  candidate <- read_update_2026_total_eiv_fit_file(
    record$original_fit_path
  )
  integrated <- qs::qread(record$integrated_loo_path)
  input <- integrated$input
  observation <- as.integer(record$observation)
  pareto_values <- if (inherits(integrated$loo, "loo")) {
    loo::pareto_k_values(integrated$loo)
  } else {
    numeric()
  }

  if (
    !identical(integrated$family, "total_eiv") ||
      !identical(candidate$family, "total_eiv") ||
      candidate$model_index != record$model_index ||
      input$specification$model_index != record$model_index ||
      observation < 1L || observation > input$stan_data$N ||
      length(pareto_values) < observation ||
      !is.finite(pareto_values[[observation]]) ||
      pareto_values[[observation]] <= 0.7
  ) {
    stop("An absolute total-intake EIV exact-refit record is invalid.",
         call. = FALSE)
  }

  training_data <- make_eiv_leave_one_out_stan_data(
    input$stan_data,
    observation
  )
  specification <- candidate$specification
  specification$adapt_delta <- max(
    as.numeric(specification$adapt_delta),
    as.numeric(config$adapt_delta_floor)
  )
  specification$max_treedepth <- max(
    as.integer(specification$max_treedepth),
    as.integer(config$max_treedepth_floor)
  )
  specification$update_2026_iter_warmup <-
    as.integer(config$iter_warmup)
  specification$update_2026_iter_sampling <-
    as.integer(config$iter_sampling)
  stan_file <- model$stan_file()
  stan_sha256 <- digest::digest(
    file = stan_file,
    algo = "sha256",
    serialize = FALSE
  )
  cmdstan_dir <- file.path(dirname(output_file), "cmdstan")
  dir.create(cmdstan_dir, recursive = TRUE, showWarnings = FALSE)
  start_time <- proc.time()[["elapsed"]]
  fit <- model$sample(
    data = training_data,
    chains = config$chains,
    parallel_chains = config$parallel_chains,
    iter_warmup = config$iter_warmup,
    iter_sampling = config$iter_sampling,
    adapt_delta = specification$adapt_delta,
    max_treedepth = specification$max_treedepth,
    seed = as.integer(config$seed + record$case_id),
    refresh = 100,
    output_dir = cmdstan_dir
  )

  fitted_candidate <- list(
    family = "total_eiv",
    outcome = record$outcome,
    model_index = as.integer(record$model_index),
    model_name = record$model_name,
    specification = specification,
    grid = input$grid,
    output_dir = normalizePath(
      cmdstan_dir,
      winslash = "/",
      mustWork = TRUE
    ),
    fit = fit
  )

  refit <- list(
    case_id = as.integer(record$case_id),
    family = "total_eiv",
    outcome = record$outcome,
    model_index = as.integer(record$model_index),
    model_name = record$model_name,
    observation = observation,
    pareto_k = as.numeric(record$pareto_k),
    fitted_candidate = fitted_candidate,
    input = input,
    integrated_result = integrated,
    source_fit_sha256 = record$original_fit_sha256,
    source_integrated_loo_sha256 = record$integrated_loo_sha256,
    stan_sha256 = stan_sha256,
    refit_seconds = as.numeric(proc.time()[["elapsed"]] - start_time)
  )

  write_atomic_qs(refit, output_file)
}

diagnose_update_2026_total_eiv_exact_fit_file <- function(path) {
  refit <- read_update_2026_total_eiv_exact_fit_file(path)
  generic_refit <- refit
  generic_refit$fitted_candidate$family <- "eiv"
  diagnostic <- summarise_eiv_exact_loo_refit(generic_refit)
  diagnostic$family <- "total_eiv"
  diagnostic$model_name <- refit$model_name
  diagnostic
}

audit_update_2026_total_eiv_exact_diagnostics <- function(
    diagnostics,
    integrated_audit
) {
  audit <- audit_mundlak_full_exact_loo_diagnostics(
    diagnostics = diagnostics,
    integrated_audit = integrated_audit
  )
  expected_keys <- paste(
    integrated_audit$high_k_cases$outcome,
    integrated_audit$high_k_cases$model_index,
    integrated_audit$high_k_cases$observation,
    sep = "::"
  )
  observed_keys <- paste(
    audit$diagnostic_summary$outcome,
    audit$diagnostic_summary$model_index,
    audit$diagnostic_summary$observation,
    sep = "::"
  )

  if (
    audit$exact_refits != 4L ||
      nrow(audit$diagnostic_summary) != 4L ||
      any(audit$diagnostic_summary$family != "total_eiv") ||
      anyDuplicated(observed_keys) || !setequal(observed_keys, expected_keys)
  ) {
    stop("The absolute total-intake EIV exact diagnostics are incomplete.",
         call. = FALSE)
  }

  audit$family <- "total_eiv"
  audit
}

write_update_2026_total_eiv_exact_diagnostic_audit <- function(
    audit,
