update_2026_total_eiv_exact_correction_file_path <- function(
    refit,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "loo", "exact_corrections"
    )
) {
  directory <- file.path(output_root, refit$outcome)
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf(
      "model_%02d_case_%03d_observation_%04d.qs",
      as.integer(refit$model_index),
      as.integer(refit$case_id),
      as.integer(refit$observation)
    )
  )
}

compute_update_2026_total_eiv_exact_correction_to_file <- function(
    exact_fit_path,
    diagnostic_audit,
    loo_draws = 4000L
) {
  if (!isTRUE(diagnostic_audit$all_exact_refit_diagnostics_pass)) {
    stop("Total-intake EIV exact corrections require passing diagnostics.",
         call. = FALSE)
  }

  refit <- read_update_2026_total_eiv_exact_fit_file(exact_fit_path)
  output_file <- update_2026_total_eiv_exact_correction_file_path(refit)
  existing <- if (file.exists(output_file)) {
    tryCatch(qs::qread(output_file), error = function(error) NULL)
  } else {
    NULL
  }

  if (
    is.list(existing) && identical(existing$family, "total_eiv") &&
      as.integer(existing$case_id) == refit$case_id &&
      identical(existing$outcome, refit$outcome) &&
      as.integer(existing$model_index) == refit$model_index &&
      is.data.frame(existing$exact_refit_summary) &&
      nrow(existing$exact_refit_summary) == 1L &&
      existing$exact_refit_summary$observation[[1L]] ==
        refit$observation &&
      identical(existing$source_fit_sha256, refit$source_fit_sha256) &&
      identical(
        existing$source_integrated_loo_sha256,
        refit$source_integrated_loo_sha256
      ) &&
      identical(as.integer(existing$loo_draws), as.integer(loo_draws))
  ) {
    return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
  }

  if (file.exists(output_file)) {
    stop(
      paste0(
        "An existing total-intake EIV exact correction does not match ",
        "the passing refit; it was not overwritten."
      ),
      call. = FALSE
    )
  }

  correction <- compute_eiv_exact_loo_case(
    refit,
    loo_draws = loo_draws
  )
  correction$family <- "total_eiv"
  correction$source_fit_sha256 <- refit$source_fit_sha256
  correction$source_integrated_loo_sha256 <-
    refit$source_integrated_loo_sha256
  correction$stan_sha256 <- refit$stan_sha256
  correction$loo_draws <- as.integer(loo_draws)

  if (
    as.integer(correction$case_id) != refit$case_id ||
      !inherits(correction$loo, "loo") ||
      nrow(correction$exact_refit_summary) != 1L ||
      correction$exact_refit_summary$observation[[1L]] !=
        refit$observation ||
      !isTRUE(correction$exact_refit_summary$diagnostic_pass[[1L]])
  ) {
    stop("The total-intake EIV exact correction is invalid.",
         call. = FALSE)
  }

  write_atomic_qs(correction, output_file)
}

audit_update_2026_total_eiv_exact_corrections <- function(
    paths,
    integrated_audit
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  expected <- as.integer(integrated_audit$exact_refits_required)

  if (
    length(paths) != expected || expected != 4L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The total-intake EIV exact corrections are incomplete.",
         call. = FALSE)
  }

  corrections <- purrr::map(paths, qs::qread)
  diagnostic_summary <- purrr::map_dfr(
    corrections,
    "exact_refit_summary"
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )

  manifest <- purrr::map2_dfr(paths, corrections, function(path, result) {
    tibble::tibble(
      case_id = as.integer(result$case_id),
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      model_name = result$model_name,
      observation =
        as.integer(result$exact_refit_summary$observation[[1L]]),
      correction_path = normalizePath(
        path,
        winslash = "/",
        mustWork = TRUE
      ),
      bytes = as.numeric(file.info(path)$size),
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    manifest$outcome,
    manifest$model_index,
    manifest$observation,
    sep = "::"
  )
  expected_keys <- paste(
    integrated_audit$high_k_cases$outcome,
    integrated_audit$high_k_cases$model_index,
    integrated_audit$high_k_cases$observation,
    sep = "::"
  )

  if (
    nrow(diagnostic_summary) != expected || nrow(manifest) != expected ||
      anyDuplicated(observed_keys) || !setequal(observed_keys, expected_keys) ||
      any(!purrr::map_lgl(
        corrections,
        ~ identical(.x$family, "total_eiv") && inherits(.x$loo, "loo")
      )) ||
      any(!diagnostic_summary$diagnostic_pass)
  ) {
    stop("The total-intake EIV exact-correction audit is invalid.",
         call. = FALSE)
  }

  list(
    family = "total_eiv",
    diagnostic_summary = diagnostic_summary,
    correction_manifest = manifest,
    exact_refits = expected,
    exact_refits_passing = sum(diagnostic_summary$diagnostic_pass),
    exact_refits_requiring_remediation =
      sum(!diagnostic_summary$diagnostic_pass),
    all_exact_refit_diagnostics_pass =
      all(diagnostic_summary$diagnostic_pass)
  )
}

write_update_2026_total_eiv_exact_correction_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "loo_exact"
    )
) {
  if (
    !identical(audit$family, "total_eiv") ||
      audit$exact_refits != 4L ||
      nrow(audit$diagnostic_summary) != 4L ||
      nrow(audit$correction_manifest) != 4L
  ) {
    stop("Cannot write an incomplete total-intake EIV correction audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    correction_manifest = file.path(output_dir, "correction_manifest.csv")
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$correction_manifest,
    paths[["correction_manifest"]],
    na = ""
  )
  unname(paths)
}

read_update_2026_total_eiv_exact_corrections <- function(manifest) {
  if (
    !is.data.frame(manifest) || nrow(manifest) != 4L ||
      any(!file.exists(manifest$correction_path)) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The total-intake EIV exact-correction manifest is invalid.",
         call. = FALSE)
  }

  corrections <- purrr::map(manifest$correction_path, qs::qread)
  corrections <- corrections[order(purrr::map_int(corrections, "case_id"))]
  if (
    !identical(unname(purrr::map_int(corrections, "case_id")), seq_len(4L)) ||
      any(!purrr::map_lgl(corrections, ~ inherits(.x$loo, "loo"))) ||
      any(!purrr::map_lgl(
        corrections,
        ~ identical(.x$family, "total_eiv")
      ))
  ) {
    stop("The total-intake EIV exact corrections are incomplete.",
         call. = FALSE)
  }

  corrections
}

make_update_2026_total_eiv_final_loo_audit <- function(
    integrated_manifest,
    exact_corrections,
    exact_audit,
    accepted_fit_manifest
) {
  expected_indices <- sort(unique(accepted_fit_manifest$model_index))

  if (
    !isTRUE(exact_audit$all_exact_refit_diagnostics_pass) ||
      exact_audit$exact_refits != 4L ||
      nrow(accepted_fit_manifest) != 72L ||
      length(expected_indices) != 18L
  ) {
    stop("Final total-intake EIV LOO requires four passing exact refits.",
         call. = FALSE)
  }

  final <- apply_sensitivity_full_exact_loo_corrections_from_files(
    integrated_manifest = integrated_manifest,
    exact_results = exact_corrections,
    family = "total_eiv",
    expected_models = 72L,
    expected_indices = expected_indices
  )
  outcome_summary <- final$model_summary |>
    dplyr::group_by(outcome) |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_unresolved_high_k =
        sum(n_pareto_k_gt_threshold > 0L),
      unresolved_high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_remaining_pareto_k = max(maximum_pareto_k, na.rm = TRUE),
      .groups = "drop"
    )

  correction_counts <- exact_audit$diagnostic_summary |>
    dplyr::count(outcome, model_index, name = "exact_corrections")
  final_manifest <- integrated_manifest |>
    dplyr::left_join(
      correction_counts,
      by = c("outcome", "model_index")
    ) |>
    dplyr::mutate(
      exact_corrections = tidyr::replace_na(exact_corrections, 0L),
      final_method = dplyr::if_else(
        exact_corrections > 0L,
        "outcome_effects_integrated_latent_exposure_psis_plus_exact",
        "outcome_effects_integrated_latent_exposure_psis"
      )
    )

  if (
    !isTRUE(final$stacking_ready) || nrow(final$model_summary) != 72L ||
      nrow(outcome_summary) != 4L ||
      any(outcome_summary$models != 18L) ||
      any(outcome_summary$unresolved_high_k_cases != 0L) ||
      nrow(final_manifest) != 72L ||
      sum(final_manifest$exact_corrections) != 4L
  ) {
    stop("The final total-intake EIV LOO is not stacking-ready.",
         call. = FALSE)
  }

  final$family <- "total_eiv"
  final$outcome_summary <- outcome_summary
  final$final_loo_manifest <- final_manifest
  final$exact_refits <- 4L
  final$all_exact_refit_diagnostics_pass <- TRUE
  final
}

write_update_2026_total_eiv_final_loo_audit <- function(
    audit,
    output_dir = here::here(
