}

write_update_2026_total_eiv_stacking_weights <- function(
    weights,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "stacking_weights.csv"
    )
) {
  outcome_sums <- tapply(weights$weight, weights$outcome, sum)
  if (
    nrow(weights) != 72L || any(weights$family != "total_eiv") ||
      anyDuplicated(paste(weights$outcome, weights$model_index)) ||
      length(outcome_sums) != 4L ||
      any(abs(outcome_sums - 1) > 1e-8)
  ) {
    stop("The total-intake EIV stacking weights are invalid.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(weights, output_file, na = "")
  output_file
}

make_update_2026_total_eiv_prediction_records <- function(
    accepted_fit_manifest,
    stacking_weights,
    inputs,
    n_draws = 4000L,
    seed = 41388L
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  input_keys <- purrr::map_chr(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })
  fit_manifest <- accepted_fit_manifest |>
    dplyr::select(
      outcome, model_index, model_name, fit_path,
      fit_sha256 = sha256
    )
  joined <- stacking_weights |>
    dplyr::left_join(
      fit_manifest,
      by = c("outcome", "model_index", "model_name"),
      relationship = "one-to-one"
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)

  if (
    nrow(accepted_fit_manifest) != 72L ||
      nrow(stacking_weights) != 72L || length(inputs) != 72L ||
      anyDuplicated(input_keys) || anyNA(joined$fit_path) ||
      any(!file.exists(joined$fit_path)) ||
      anyDuplicated(paste(joined$outcome, joined$model_index)) ||
      any(joined$family != "total_eiv") ||
      any(!is.finite(joined$weight)) || any(joined$weight < 0)
  ) {
    stop("The total-intake EIV prediction registries do not align.",
         call. = FALSE)
  }

  outcome_seed <- stats::setNames(
    as.integer(seed) + seq_along(outcomes) * 10000L,
    outcomes
  )
  allocated <- joined |>
    dplyr::group_by(outcome) |>
    dplyr::group_modify(function(table, key) {
      if (nrow(table) != 18L || abs(sum(table$weight) - 1) > 1e-8) {
        stop("An outcome-specific total-intake EIV ensemble is invalid.",
             call. = FALSE)
      }
      table$draw_count <- allocate_primary_mixture_models(
        table$weight / sum(table$weight),
        as.integer(n_draws)
      )
      table
    }) |>
    dplyr::ungroup() |>
    dplyr::mutate(
      prediction_seed = as.integer(
        outcome_seed[outcome] + as.integer(model_index)
      ),
      n_draws = as.integer(n_draws),
      reference_g_day = 78.785,
      internal_unit_g_day = 50,
      exposure_minimum_g_day = 50,
      grid_step_g_day = 1,
      body_mass_reference_z = 0,
      prediction_type = "total_eiv"
    )

  allocated <- allocated |>
    dplyr::rowwise() |>
    dplyr::mutate(
      exposure_maximum_g_day = {
        key <- paste(outcome, model_index, sep = "::")
        position <- match(key, input_keys)
        if (is.na(position)) {
          stop("A total-intake EIV prediction input is unavailable.",
               call. = FALSE)
        }
        input <- inputs[[position]]
        if (
          any(input$stan_data$body_mass_grid_z != 0) ||
            min(input$grid$protein_intake_raw) != 50
        ) {
          stop("A total-intake EIV prediction grid is invalid.",
               call. = FALSE)
        }
        max(input$grid$protein_intake_raw)
      }
    ) |>
    dplyr::ungroup()

  allocation_audit <- allocated |>
    dplyr::summarise(
      allocated_draws = sum(draw_count),
      .by = outcome
    )
  if (
    nrow(allocation_audit) != 4L ||
      any(allocation_audit$allocated_draws != 4000L)
  ) {
    stop("The total-intake EIV draw allocation is incomplete.",
         call. = FALSE)
  }

  allocated <- dplyr::filter(allocated, draw_count > 0L)
  purrr::map(seq_len(nrow(allocated)), function(row) {
    purrr::map(as.list(allocated[row, , drop = FALSE]), unname)
  })
}

make_update_2026_total_eiv_reporting_preflight <- function(records) {
  if (!is.list(records) || length(records) < 4L) {
    stop("The total-intake EIV reporting allocation is incomplete.",
         call. = FALSE)
  }
  checks <- purrr::map_dfr(records, function(record) {
    tibble::tibble(
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      family = unname(as.character(record$family)),
      prediction_type = unname(as.character(record$prediction_type)),
      weight = as.numeric(record$weight),
      allocated_draws = as.integer(record$draw_count),
      prediction_seed = as.integer(record$prediction_seed),
      reference_g_day = as.numeric(record$reference_g_day),
      internal_unit_g_day = as.numeric(record$internal_unit_g_day),
      exposure_minimum_g_day =
        as.numeric(record$exposure_minimum_g_day),
      exposure_maximum_g_day =
        as.numeric(record$exposure_maximum_g_day),
      grid_step_g_day = as.numeric(record$grid_step_g_day),
      body_mass_reference_z =
        as.numeric(record$body_mass_reference_z),
      fit_path = record$fit_path,
      fit_exists = file.exists(record$fit_path),
      valid = record$draw_count > 0L && file.exists(record$fit_path) &&
        identical(unname(as.character(record$family)), "total_eiv") &&
        identical(
          unname(as.character(record$prediction_type)),
          "total_eiv"
        ) &&
        nchar(record$fit_sha256) == 64L &&
        record$reference_g_day == 78.785 &&
        record$internal_unit_g_day == 50 &&
        record$exposure_minimum_g_day == 50 &&
        record$grid_step_g_day == 1 &&
        record$body_mass_reference_z == 0 &&
        is.finite(record$exposure_maximum_g_day) &&
        record$exposure_maximum_g_day > 50
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  outcome_audit <- checks |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      allocated_draws = sum(allocated_draws),
      retained_weight = sum(weight),
      exposure_maximum_g_day = dplyr::first(exposure_maximum_g_day),
      .by = outcome
    )

  if (
    nrow(outcome_audit) != 4L ||
      any(outcome_audit$selected_models < 1L) ||
      any(outcome_audit$allocated_draws != 4000L) ||
      any(!is.finite(outcome_audit$retained_weight)) ||
      any(outcome_audit$retained_weight <= 0) ||
      any(outcome_audit$retained_weight > 1 + 1e-8) ||
      any(!is.finite(outcome_audit$exposure_maximum_g_day)) ||
      anyDuplicated(checks[c("outcome", "model_index")]) ||
      !all(checks$valid)
  ) {
    stop("The total-intake EIV reporting preflight failed.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_eiv_reporting_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "reporting", "input_preflight.csv"
    )
) {
  outcome_draws <- tapply(checks$allocated_draws, checks$outcome, sum)
  outcome_weights <- tapply(checks$weight, checks$outcome, sum)
  if (
    length(outcome_draws) != 4L || any(outcome_draws != 4000L) ||
      length(outcome_weights) != 4L ||
      any(!is.finite(outcome_weights)) || any(outcome_weights <= 0) ||
      any(outcome_weights > 1 + 1e-8) || !all(checks$valid)
  ) {
    stop("Cannot write an invalid total-intake EIV reporting preflight.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

update_2026_total_eiv_reporting_path <- function(
    outcome,
    stage,
    model_index = NULL
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure", "total_g_day",
    "eiv", "reporting", stage, outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  filename <- if (is.null(model_index)) {
    paste0(stage, ".qs")
  } else {
    sprintf("model_%02d_%s.qs", as.integer(model_index), stage)
  }
  file.path(directory, filename)
}

write_update_2026_total_eiv_prediction_draw_file <- function(
    record,
    result_path
) {
  if (
    length(record$fit_path) != 1L || is.na(record$fit_path) ||
      !file.exists(record$fit_path) || record$draw_count < 1L ||
      !identical(unname(as.character(record$family)), "total_eiv") ||
      !identical(
        unname(as.character(record$prediction_type)),
        "total_eiv"
      ) ||
      !identical(
        digest::digest(record$fit_path, file = TRUE, algo = "sha256"),
        as.character(record$fit_sha256)
      )
  ) {
    stop("A total-intake EIV prediction record is invalid.",
         call. = FALSE)
  }

  candidate <- read_update_2026_total_eiv_fit_file(record$fit_path)
  if (
    as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(candidate$outcome, as.character(record$outcome)) ||
      !identical(candidate$model_name, as.character(record$model_name))
  ) {
    stop("A total-intake EIV fit does not match its prediction record.",
         call. = FALSE)
  }

  all_draws <- posterior::as_draws_matrix(
    candidate$fit$draws("mu_grid")
  )
  set.seed(as.integer(record$prediction_seed))
  selected <- sample(
    seq_len(nrow(all_draws)),
    as.integer(record$draw_count),
    replace = nrow(all_draws) < as.integer(record$draw_count)
  )
  draws <- as.matrix(all_draws[selected, , drop = FALSE])
  grid <- candidate$grid |>
    dplyr::transmute(
      resistance_exercise_code,
      resistance_exercise = ifelse(
        resistance_exercise_code == 0,
        "YES",
        "NO"
      ),
      protein_intake = protein_intake_raw
    )

  if (
    nrow(draws) != as.integer(record$draw_count) ||
      ncol(draws) != nrow(grid) || anyNA(draws) ||
      any(!is.finite(draws)) ||
      min(grid$protein_intake) != record$exposure_minimum_g_day ||
      max(grid$protein_intake) != record$exposure_maximum_g_day ||
      !any(abs(grid$protein_intake - record$reference_g_day) < 1e-10)
  ) {
    stop("The total-intake EIV prediction draws are incomplete.",
         call. = FALSE)
  }

  reduction <- list(
    family = "total_eiv",
    outcome = as.character(record$outcome),
    model_index = as.integer(record$model_index),
    model_name = as.character(record$model_name),
    weight = as.numeric(record$weight),
    draw_count = as.integer(record$draw_count),
    prediction_seed = as.integer(record$prediction_seed),
    fit_sha256 = as.character(record$fit_sha256),
    grid = grid,
    draws = draws,
    settings = list(
      protein_min = min(grid$protein_intake),
      protein_max = max(grid$protein_intake),
      grid_step = as.numeric(record$grid_step_g_day),
      prediction_type = "total_eiv",
      reference_intake = as.numeric(record$reference_g_day),
      internal_unit_g_day = as.numeric(record$internal_unit_g_day),
      body_mass_reference_z = as.numeric(record$body_mass_reference_z)
    )
  )

  write_atomic_qs(reduction, result_path)
}

make_update_2026_total_eiv_model_average_records <- function(
    prediction_manifest,
    stacking_weights,
    n_draws = 4000L,
    seed = 42388L
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")

  if (
    !is.data.frame(prediction_manifest) ||
      !is.data.frame(stacking_weights) ||
      nrow(stacking_weights) != 72L ||
      any(prediction_manifest$family != "total_eiv") ||
      any(stacking_weights$family != "total_eiv")
  ) {
    stop("The total-intake EIV averaging inputs are invalid.",
         call. = FALSE)
  }

  purrr::map(seq_along(outcomes), function(index) {
    outcome <- outcomes[[index]]
    files <- dplyr::filter(
      prediction_manifest,
      .data$outcome == .env$outcome
    )
    weights <- dplyr::filter(
      stacking_weights,
      .data$outcome == .env$outcome
    ) |>
      dplyr::arrange(model_index)
    if (
      nrow(files) < 1L || sum(files$draw_count) != n_draws ||
        nrow(weights) != 18L || abs(sum(weights$weight) - 1) > 1e-8 ||
        any(!file.exists(files$prediction_path))
    ) {
      stop("An outcome-specific total-intake EIV average is invalid.",
           call. = FALSE)
    }
    list(
      family = "total_eiv",
      outcome = outcome,
      prediction_manifest = files,
      stacking_weights = weights,
      n_draws = as.integer(n_draws),
      averaging_seed = as.integer(seed + index)
    )
  })
}

write_update_2026_total_eiv_reporting_file <- function(
    model_average_path,
    data_by_outcome,
    reference_intake = 78.785,
    sesoi = 0.10,
    result_path
) {
  model_average <- read_sensitivity_full_model_average_file(
    model_average_path,
    family = "total_eiv"
  )
  outcome <- model_average$outcome
  data <- data_by_outcome[[outcome]]

  if (is.null(data) || !is.data.frame(data)) {
    stop("The total-intake EIV reporting data are unavailable.",
         call. = FALSE)
  }
  absolute <- summarise_primary_dose_response(model_average)
  supported <- build_sensitivity_mundlak_reporting_pilot(
    absolute,
    model_average,
    data,
    reference_intake
  )
  heatmap <- compute_primary_heatmap_contrasts(
    model_average = model_average,
    data = data,
    protein_min = 50,
    sesoi = sesoi
  )
  report <- list(
    family = "total_eiv",
    outcome = outcome,
    dose_response = supported$absolute_full_grid,
    dose_response_increments = supported$increments_full_grid,
    exposure_support_by_group = supported$support_by_group,
    common_exposure_support = supported$common_support,
    pairwise_contrasts = heatmap$contrasts,
    pairwise_support = heatmap$support,
    local_equivalence = summarise_primary_local_equivalence(
      heatmap$contrasts,
      outcome = outcome
    ),
    model_weights = tibble::tibble(
      model_name = names(model_average$model_weights),
      weight = as.numeric(model_average$model_weights)
    ),
    settings = utils::modifyList(
      model_average$settings,
      list(
        reference_intake = reference_intake,
        sesoi = sesoi,
        exposure = "total_g_day",
        exposure_definition = "errors_in_variables",
        exposure_unit = "g/day",
        body_mass_reference_z = 0
      )
    )
  )

  write_atomic_qs(report, result_path)
}

write_update_2026_total_eiv_reporting_audit <- function(
    audit,
    prediction_manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "reporting"
    )
) {
  if (
    !identical(audit$family, "total_eiv") ||
      !isTRUE(audit$all_reporting_checks_pass) ||
      nrow(audit$summary) != 4L ||
      nrow(prediction_manifest) != 26L ||
      any(prediction_manifest$family != "total_eiv") ||
      sum(prediction_manifest$draw_count) != 16000L
  ) {
    stop("The total-intake EIV reporting audit is incomplete.",
         call. = FALSE)
  }

  reports <- purrr::map(
    audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "total_eiv"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(
      report$model_weights,
      outcome = report$outcome,
      .before = 1L
    )
  })
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    prediction_manifest = file.path(output_dir, "prediction_manifest.csv"),
    dose_response = file.path(output_dir, "dose_response.csv"),
    dose_response_increments = file.path(
      output_dir,
      "dose_response_increments.csv"
    ),
    exposure_support_by_group = file.path(
      output_dir,
      "exposure_support_by_group.csv"
    ),
    common_exposure_support = file.path(
      output_dir,
      "common_exposure_support.csv"
    ),
    pairwise_contrasts = file.path(output_dir, "pairwise_contrasts.csv.gz"),
    pairwise_support = file.path(output_dir, "pairwise_support.csv"),
    local_equivalence = file.path(output_dir, "local_equivalence.csv"),
    model_weights = file.path(output_dir, "model_weights.csv")
  )

  readr::write_csv(audit$summary, paths[["summary"]], na = "")
  readr::write_csv(
    prediction_manifest,
    paths[["prediction_manifest"]],
    na = ""
  )
  readr::write_csv(bind_report("dose_response"), paths[["dose_response"]])
  readr::write_csv(
    bind_report("dose_response_increments"),
    paths[["dose_response_increments"]]
  )
  readr::write_csv(
    bind_report("exposure_support_by_group"),
    paths[["exposure_support_by_group"]]
  )
  readr::write_csv(
    bind_report("common_exposure_support"),
    paths[["common_exposure_support"]]
  )
  readr::write_csv(
    bind_report("pairwise_contrasts"),
    paths[["pairwise_contrasts"]]
  )
  readr::write_csv(
    bind_report("pairwise_support"),
    paths[["pairwise_support"]]
  )
  readr::write_csv(
    bind_report("local_equivalence"),
    paths[["local_equivalence"]]
  )
  readr::write_csv(model_weights, paths[["model_weights"]])
  unname(paths)
}

make_update_2026_total_eiv_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    data_by_outcome,
    input_preflight,
    specifications,
    accepted_fit_manifest,
    diagnostic_audit,
    integrated_loo_audit,
    exact_correction_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  expected_contrasts <- c(247L, 373L, 721L, 323L)
  expected_selected <- c(6L, 5L, 6L, 9L)
  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  specification_keys <- registry_keys(specification_table)
  accepted_keys <- registry_keys(accepted_fit_manifest)
  diagnostic_keys <- registry_keys(diagnostic_audit$diagnostic_summary)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, accepted_keys) &&
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- specification_table |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      diagnostic_audit$diagnostic_summary |>
        dplyr::select(outcome, model_index, diagnostic_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  preflight_summary <- input_preflight |>
    dplyr::distinct(
      outcome, contrasts, studies, arms, outcome_rows,
      exposure_minimum_g_day, exposure_maximum_g_day,
      minimum_exposure_se_g_day, maximum_exposure_se_g_day,
      reference_g_day, internal_unit_g_day, grid_minimum_g_day,
      grid_step_g_day
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes))

  accepted_stage_counts <- table(accepted_fit_manifest$stage)
  weight_sums <- stacking_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes))
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes))

  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = "total_eiv"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  reporting_model_weights <- bind_report("model_weights")
  reporting_weight_sums <- reporting_model_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes))
  initial_integrated_model_summary <- integrated_loo_audit$model_summary |>
    dplyr::filter(method == "integrated_observation_level_psis")
  initial_conditional_model_summary <- integrated_loo_audit$model_summary |>
    dplyr::filter(method == "conditional_observation_level_psis")
  correction_manifest <- exact_correction_audit$correction_manifest

  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      "all four total-intake EIV datasets and exposure errors are valid",
      "all five total-intake EIV registries contain the same 72 model keys",
      "model names agree across specifications fits diagnostics LOO and weights",
      "all 72 accepted fit files exist and have checksums",
      "all 72 final sampling diagnostics pass",
      "initial LOO contains 72 aligned models and four high-k cases",
      "all four exact refits and compact corrections pass",
      "final LOO contains 72 models and no unresolved high-k cases",
      "four stacking vectors contain 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      "all four reporting audits pass and retain all model weights"
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      identical(names(data_by_outcome), outcomes) &&
        nrow(input_preflight) == 72L && all(input_preflight$valid) &&
        nrow(preflight_summary) == 4L &&
        identical(preflight_summary$contrasts, expected_contrasts) &&
        all(preflight_summary$minimum_exposure_se_g_day > 0) &&
        all(is.finite(preflight_summary$maximum_exposure_se_g_day)) &&
        all(preflight_summary$reference_g_day == 78.785) &&
        all(preflight_summary$internal_unit_g_day == 50) &&
        all(preflight_summary$grid_minimum_g_day == 50) &&
        all(preflight_summary$grid_step_g_day == 1) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0) &&
        all(is.finite(analysis_data$protein_intake_raw)) &&
        all(is.finite(analysis_data$protein_intake_se)) &&
        all(analysis_data$protein_intake_se > 0),
      common_registry && length(specification_keys) == 72L,
      nrow(name_alignment) == 72L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(
          name_alignment$diagnostic_name ==
            name_alignment$specification_name
        ) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(accepted_fit_manifest) == 72L &&
        all(accepted_fit_manifest$family == "total_eiv") &&
        identical(unname(accepted_stage_counts["initial"]), 70L) &&
        identical(unname(accepted_stage_counts["remedy_1"]), 2L) &&
        all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(accepted_fit_manifest$bytes > 0) &&
        all(nchar(accepted_fit_manifest$sha256) == 64L),
      identical(diagnostic_audit$family, "total_eiv") &&
        diagnostic_audit$models == 72L &&
        isTRUE(diagnostic_audit$all_sampling_diagnostics_pass) &&
        all(diagnostic_audit$diagnostic_summary$diagnostic_pass),
      identical(integrated_loo_audit$family, "total_eiv") &&
        integrated_loo_audit$models == 72L &&
        nrow(initial_integrated_model_summary) == 72L &&
        nrow(initial_conditional_model_summary) == 72L &&
        integrated_loo_audit$exact_refits_required == 4L &&
        nrow(integrated_loo_audit$high_k_cases) == 4L,
      exact_correction_audit$exact_refits == 4L &&
        exact_correction_audit$exact_refits_passing == 4L &&
        isTRUE(
          exact_correction_audit$all_exact_refit_diagnostics_pass
        ) &&
        nrow(correction_manifest) == 4L &&
        all(file.exists(correction_manifest$correction_path)) &&
        all(correction_manifest$bytes > 0) &&
        all(nchar(correction_manifest$sha256) == 64L),
      identical(final_loo_audit$family, "total_eiv") &&
        nrow(final_loo_audit$model_summary) == 72L &&
        final_loo_audit$exact_refits == 4L &&
        isTRUE(final_loo_audit$stacking_ready) &&
        all(final_loo_audit$outcome_summary$unresolved_high_k_cases == 0L),
      nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        identical(prediction_sums$selected_models, expected_selected) &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      identical(reporting_audit$family, "total_eiv") &&
        isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid) &&
        nrow(reporting_model_weights) == 72L &&
        all(reporting_weight_sums$models == 18L) &&
        all(abs(reporting_weight_sums$weight_sum - 1) < 1e-8)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Updated total-intake EIV verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    preparation_outcome_counts = preparation_audit$outcome_counts,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    absolute_exposure_provenance = absolute_audit$exposure_provenance,
    absolute_support_by_outcome = absolute_audit$support_by_outcome,
    absolute_scaling_plan = absolute_audit$scaling_plan,
    absolute_model_registry = absolute_audit$model_registry,
    absolute_family_plan = absolute_audit$family_plan,
    eiv_input_preflight = input_preflight,
    analysis_data = analysis_data,
    model_specifications = specification_table,
    model_name_alignment = name_alignment,
    accepted_fit_manifest = accepted_fit_manifest,
    sampling_diagnostic_summary = diagnostic_audit$diagnostic_summary,
    sampling_parameter_failures = diagnostic_audit$parameter_failures,
    initial_integrated_loo_model_summary = integrated_loo_audit$model_summary,
    initial_integrated_loo_outcome_summary =
      integrated_loo_audit$outcome_summary,
    initial_high_pareto_k_cases = integrated_loo_audit$high_k_cases,
    exact_refit_diagnostic_summary =
      exact_correction_audit$diagnostic_summary,
    exact_correction_manifest = correction_manifest,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    final_exact_refit_summary = final_loo_audit$exact_refit_summary,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    reporting_model_weights = reporting_model_weights,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    c(
      "Final total-intake EIV checkpoint checks.",
      "Paths, sizes, and SHA-256 hashes for source data.",
      "Combined-data preparation invariants.",
      "Analysis counts by primary outcome.",
      "Shared absolute-exposure construction invariants.",
      "Eligible contrast counts for absolute exposure scales.",
      "Provenance of selected reported or derived exposures.",
      "Observed absolute-exposure support by outcome.",
      "Frozen references, units, and grid rules.",
      "Retained 18-model absolute-exposure registry.",
      "Planned primary and sensitivity absolute-exposure families.",
      "Total-intake EIV input, exposure-error, and schedule checks.",
      "Eligible arm-level rows supplied to total-intake EIV models.",
      "Complete 72-model total-intake EIV specification registry.",
      "Cross-stage total-intake EIV model-name identity audit.",
      "Accepted 72-fit lineage with stages and checksums.",
      "Final model-level sampling diagnostics.",
      "Parameter-level diagnostic failures.",
      "Initial conditional and integrated PSIS summaries.",
      "Initial integrated PSIS audit by outcome.",
      "The four model-observation cases selected for exact refitting.",
      "Final diagnostics for the four exact-deletion refits.",
      "Compact exact-correction paths and checksums.",
      "Final exact-corrected LOO lineage.",
      "Final LOO summary for all 72 models.",
      "Final high-k resolution by outcome.",
      "Final exact-correction audit by case.",
      "All 72 final exact-corrected stacking weights.",
      "Allocation of 4,000 prediction draws per outcome.",
      "Reporting file dimensions and checksums.",
      "All 72 weights retained in reporting objects.",
      "Total-intake EIV model-averaged dose-response curves.",
      "Changes from the 78.785 g/day reference.",
      "Observed total-intake support by training group.",
      "Total-intake support common to training groups.",
      "Pairwise total-intake contrasts and probabilities.",
      "Observed support for pairwise contrasts.",
      "Practical-equivalence summaries in grams per day."
    ),
    names(artifacts)
  )

  list(
    checks = checks,
    artifacts = artifacts,
    descriptions = descriptions,
    next_family = paste(
      "The absolute total-intake EIV sensitivity is frozen after this",
      "verification checkpoint; its lean-pruning plan can be audited",
      "without deleting or altering any preregistered analysis."
    )
  )
}

make_update_2026_total_eiv_pruning_plan <- function(
    accepted_fit_manifest,
    exact_correction_audit,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "eiv"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "total_eiv_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (any(!file.exists(verification_files))) {
    stop("The total-intake EIV verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  verification_index <- readr::read_csv(
    verification_manifest,
    show_col_types = FALSE
  )

  if (length(verification_files) != nrow(verification_index) + 2L) {
    stop("The total-intake EIV verification-file count is invalid.",
         call. = FALSE)
  }
  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "eiv"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the total-intake EIV archive.",
         call. = FALSE)
  }

  model_roots <- file.path(archive_root, c("initial", "remedy_1"))
  exact_root <- file.path(archive_root, "loo", "exact_refits")
  deletion_roots <- c(model_roots, exact_root)
  if (any(!dir.exists(deletion_roots))) {
    stop("An expected total-intake EIV sampling directory is missing.",
         call. = FALSE)
  }

  deletion_paths <- unlist(
    purrr::map(
      deletion_roots,
      ~ list.files(
        .x,
        recursive = TRUE,
        full.names = TRUE,
        all.files = TRUE
      )
    ),
    use.names = FALSE
  )

  deletion_paths <- deletion_paths[
    file.exists(deletion_paths) & !file.info(deletion_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  fit_paths <- deletion_paths[basename(deletion_paths) == "fit.qs"]
  relative_fit_paths <- substring(fit_paths, nchar(resolved_root) + 2L)
  model_match <- stringr::str_match(
    relative_fit_paths,
    "^(initial|remedy_1)/([^/]+)/model_([0-9]+)/fit\\.qs$"
  )
  exact_match <- stringr::str_match(
    relative_fit_paths,
    paste0(
      "^loo/exact_refits/([^/]+)/model_([0-9]+)/",
      "case_([0-9]+)_observation_([0-9]+)/fit\\.qs$"
    )
  )
  is_exact <- !is.na(exact_match[, 1L])
  accepted_paths <- normalizePath(
    accepted_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  fit_manifest <- tibble::tibble(
    path = fit_paths,
    fit_directory = dirname(fit_paths),
    relative_path = relative_fit_paths,
    archive_stage = ifelse(
      is_exact,
      "exact_refit",
      model_match[, 2L]
    ),
    outcome = ifelse(is_exact, exact_match[, 2L], model_match[, 3L]),
    model_index = as.integer(ifelse(
      is_exact,
      exact_match[, 3L],
      model_match[, 4L]
    )),
    case_id = as.integer(ifelse(is_exact, exact_match[, 4L], NA)),
    observation = as.integer(ifelse(is_exact, exact_match[, 5L], NA)),
    accepted_fit = fit_paths %in% accepted_paths,
    bytes = as.numeric(file.info(fit_paths)$size)
  ) |>
    dplyr::arrange(
      factor(archive_stage, levels = c("initial", "remedy_1", "exact_refit")),
      outcome,
      model_index,
      case_id
    )

  model_fit_manifest <- dplyr::filter(
    fit_manifest,
    archive_stage != "exact_refit"
  )
  exact_refit_manifest <- dplyr::filter(
    fit_manifest,
    archive_stage == "exact_refit"
  )
  stage_counts <- table(factor(
    model_fit_manifest$archive_stage,
    levels = c("initial", "remedy_1")
  ))
  exact_keys <- paste(
    exact_refit_manifest$outcome,
    exact_refit_manifest$model_index,
    exact_refit_manifest$observation,
    sep = "::"
  )
  diagnostic_keys <- paste(
    exact_correction_audit$diagnostic_summary$outcome,
    exact_correction_audit$diagnostic_summary$model_index,
    exact_correction_audit$diagnostic_summary$observation,
    sep = "::"
  )

  if (
    nrow(model_fit_manifest) != 74L ||
      !identical(as.integer(stage_counts), c(72L, 2L)) ||
      sum(model_fit_manifest$accepted_fit) != 72L ||
      sum(!model_fit_manifest$accepted_fit) != 2L ||
      nrow(exact_refit_manifest) != 4L ||
      any(exact_refit_manifest$accepted_fit) ||
      !setequal(exact_refit_manifest$case_id, seq_len(4L)) ||
      !setequal(exact_keys, diagnostic_keys) ||
      !isTRUE(exact_correction_audit$all_exact_refit_diagnostics_pass) ||
      anyNA(fit_manifest[c("archive_stage", "outcome", "model_index")]) ||
      any(fit_manifest$bytes <= 0)
  ) {
    stop("The total-intake EIV fit inventory is invalid.",
         call. = FALSE)
  }

  file_fit_directories <- vapply(
    deletion_paths,
    function(path) {
      if (basename(path) == "fit.qs") dirname(path) else dirname(dirname(path))
    },
    character(1L),
    USE.NAMES = FALSE
  )

  fit_positions <- match(file_fit_directories, fit_manifest$fit_directory)
  file_type <- dplyr::case_when(
    basename(deletion_paths) == "fit.qs" ~ "fit_object",
    tolower(tools::file_ext(deletion_paths)) == "csv" &
      basename(dirname(deletion_paths)) == "cmdstan" ~ "cmdstan_chain_csv",
    TRUE ~ "unknown"
  )
  deletion_manifest <- tibble::tibble(
    path = deletion_paths,
    relative_path = substring(deletion_paths, nchar(resolved_root) + 2L),
    archive_stage = fit_manifest$archive_stage[fit_positions],
    artifact_role = dplyr::case_when(
      fit_manifest$archive_stage[fit_positions] == "exact_refit" ~
        "exact_refit",
      fit_manifest$accepted_fit[fit_positions] ~ "accepted_model_fit",
      TRUE ~ "superseded_model_fit"
    ),
    outcome = fit_manifest$outcome[fit_positions],
    model_index = fit_manifest$model_index[fit_positions],
    case_id = fit_manifest$case_id[fit_positions],
    observation = fit_manifest$observation[fit_positions],
    file_type = file_type,
    bytes = as.numeric(file.info(deletion_paths)$size),
    lean_action = "delete refittable total-intake EIV sampling archive"
  ) |>
    dplyr::arrange(
      factor(archive_stage, levels = c("initial", "remedy_1", "exact_refit")),
      outcome,
      model_index,
      case_id,
      factor(file_type, levels = c("fit_object", "cmdstan_chain_csv")),
      relative_path
    )

  deletion_stage_counts <- table(factor(
    deletion_manifest$archive_stage,
    levels = c("initial", "remedy_1", "exact_refit")
  ))
  if (
    nrow(deletion_manifest) != 390L || anyNA(fit_positions) ||
      any(deletion_manifest$file_type == "unknown") ||
      !identical(as.integer(deletion_stage_counts), c(360L, 10L, 20L)) ||
      sum(deletion_manifest$file_type == "fit_object") != 78L ||
      sum(deletion_manifest$file_type == "cmdstan_chain_csv") != 312L ||
      sum(deletion_manifest$artifact_role == "accepted_model_fit") != 360L ||
      sum(deletion_manifest$artifact_role == "superseded_model_fit") != 10L ||
      sum(deletion_manifest$artifact_role == "exact_refit") != 20L ||
      any(deletion_manifest$bytes <= 0)
  ) {
    stop("The total-intake EIV deletion inventory is incomplete.",
         call. = FALSE)
  }

  compact_roots <- c(
    loo_psis = file.path(archive_root, "loo", "integrated"),
    exact_corrections = file.path(archive_root, "loo", "exact_corrections"),
    reporting = file.path(archive_root, "reporting")
  )
  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact total-intake EIV directory is missing.",
         call. = FALSE)
  }

  compact_paths <- unlist(
    purrr::map(
      compact_roots,
      ~ list.files(
        .x,
        recursive = TRUE,
        full.names = TRUE,
        all.files = TRUE
      )
    ),
    use.names = FALSE
  )

  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  normalized_compact_roots <- normalizePath(
    compact_roots,
    winslash = "/",
    mustWork = TRUE
  )
  component <- vapply(compact_paths, function(path) {
    matches <- names(compact_roots)[vapply(
      normalized_compact_roots,
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact total-intake EIV result"
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo_psis", "exact_corrections", "reporting")
  ))
  if (
    nrow(compact_manifest) != 110L ||
      !identical(as.integer(compact_counts), c(72L, 4L, 34L)) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact total-intake EIV archive is incomplete.",
         call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    model_fit_archives_deleted = nrow(model_fit_manifest),
    accepted_model_fit_archives_deleted = sum(model_fit_manifest$accepted_fit),
    superseded_model_fit_archives_deleted = sum(!model_fit_manifest$accepted_fit),
    exact_refit_archives_deleted = nrow(exact_refit_manifest),
    archive_files_deleted = nrow(deletion_manifest),
    fit_object_files_deleted = sum(deletion_manifest$file_type == "fit_object"),
    cmdstan_csv_files_deleted = sum(
      deletion_manifest$file_type == "cmdstan_chain_csv"
    ),
    fit_archive_files_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained = sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, corrected LOO, and all 72 weights remain frozen;",
      "restoring model or exact-refit objects requires refitting the",
      "absolute total-intake EIV sensitivity."
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_fit_manifest,
    exact_refit_manifest = exact_refit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_total_eiv_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "eiv", "pruning"
    )
) {
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    exact_refit_manifest = file.path(output_dir, "exact_refit_manifest.csv"),
    deletion_file_manifest = file.path(
      output_dir,
      "deletion_file_manifest.csv"
    ),
    compact_archive_manifest = file.path(
      output_dir,
      "compact_archive_manifest.csv"
    )
  )

  readr::write_csv(plan$summary, paths[["summary"]], na = "")
  readr::write_csv(
    plan$model_fit_manifest,
    paths[["model_fit_manifest"]],
    na = ""
  )
  readr::write_csv(
    plan$exact_refit_manifest,
    paths[["exact_refit_manifest"]],
    na = ""
  )
  readr::write_csv(
    plan$deletion_file_manifest,
    paths[["deletion_file_manifest"]],
    na = ""
  )
  readr::write_csv(
    plan$compact_archive_manifest,
    paths[["compact_archive_manifest"]],
    na = ""
  )
  unname(paths)
}

# Absolute-exposure study-level residual-correlation sensitivities ----

# Use separate total-intake and prescribed-supplement configurations for the
# likelihood with study-level residual correlation.
make_update_2026_absolute_rescor_config <- function(
    family,
    seed_offset
) {
  if (
    length(family) != 1L ||
      !family %in% c("total_rescor", "supplement_rescor") ||
      length(seed_offset) != 1L || !is.finite(seed_offset)
  ) {
    stop("The absolute residual-correlation configuration is invalid.",
         call. = FALSE)
  }

  list(
    family = family,
    outcomes = c("whole_body", "hypertrophy", "strength", "function"),
    model_indices = setdiff(
      seq_len(26L),
      c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
    ),
    chains = 4L,
    parallel_chains = 4L,
    seed = as.integer(1988L + seed_offset)
  )
}

make_update_2026_absolute_rescor_specifications <- function(
    base_specifications,
    family,
    exposure
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  remedy_1 <- c(
    "whole_body::1", "whole_body::17",
    "hypertrophy::6", "hypertrophy::8", "hypertrophy::9",
    "hypertrophy::21", "strength::17", "function::18"
  )
  remedy_2 <- "function::6"
  structural <- "function::23"
  specifications <- dplyr::bind_rows(base_specifications) |>
    dplyr::mutate(
      key = paste(outcome, model_index, sep = "::"),
      family = .env$family,
      exposure = .env$exposure,
      common_sample = TRUE,
      residual_correlation_by_study = TRUE,
      historical_schedule = dplyr::case_when(
        key %in% remedy_1 ~ "remedy_1",
        key == remedy_2 ~ "remedy_2",
        key == structural ~ "structural_uncorrelated",
        TRUE ~ "base"
      ),
      uncorrelated_study_effects = dplyr::if_else(
        key == structural,
        TRUE,
        dplyr::coalesce(uncorrelated_study_effects, FALSE)
      ),
      adapt_delta = dplyr::case_when(
        historical_schedule == "remedy_1" ~
          pmax(as.numeric(adapt_delta), 0.999),
        historical_schedule %in% c(
          "remedy_2", "structural_uncorrelated"
        ) ~ pmax(as.numeric(adapt_delta), 0.9999),
        TRUE ~ as.numeric(adapt_delta)
      ),
      max_treedepth = dplyr::case_when(
        historical_schedule == "remedy_1" ~
          pmax(as.integer(max_treedepth), 15L),
        historical_schedule %in% c(
          "remedy_2", "structural_uncorrelated"
        ) ~ pmax(as.integer(max_treedepth), 16L),
        TRUE ~ as.integer(max_treedepth)
      ),
      iter_warmup = dplyr::if_else(
        historical_schedule %in% c(
          "remedy_2", "structural_uncorrelated"
        ),
        3000L,
        2000L
      ),
      iter_sampling = dplyr::if_else(
        historical_schedule %in% c(
          "remedy_2", "structural_uncorrelated"
        ),
        8000L,
        6000L
      ),
      chains = 4L,
      parallel_chains = 4L
    ) |>
    dplyr::select(-key)

  keys <- paste(specifications$outcome, specifications$model_index, sep = "::")
  outcome_counts <- table(factor(specifications$outcome, levels = outcomes))
  schedule_counts <- table(factor(
    specifications$historical_schedule,
    levels = c("base", "remedy_1", "remedy_2", "structural_uncorrelated")
  ))

  if (
    nrow(specifications) != 72L || anyDuplicated(keys) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !all(specifications$model_index %in% retained) ||
      !identical(as.integer(schedule_counts), c(62L, 8L, 1L, 1L)) ||
      sum(specifications$historical_schedule ==
            "structural_uncorrelated") != 1L ||
      !specifications$uncorrelated_study_effects[
        keys == structural
      ] ||
      any(specifications$chains != 4L) ||
      any(specifications$parallel_chains != 4L)
  ) {
    stop("The absolute residual-correlation registry is invalid.",
         call. = FALSE)
  }

  output <- purrr::pmap(specifications, list)
  names(output) <- paste0(
    specifications$outcome,
    "_model_",
    stringr::str_pad(specifications$model_index, 2L, pad = "0")
  )
  output
}

prepare_update_2026_absolute_rescor_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome,
    family,
    exposure,
    exposure_minimum_g_day,
    grid_step_g_day = 1
) {
  data <- data_by_outcome[[specification$outcome]]
  priors <- priors_by_outcome[[specification$outcome]]

  if (
    is.null(data) || !nrow(data) || is.null(priors) ||
      !identical(specification$family, family) ||
      !identical(specification$exposure, exposure)
  ) {
    stop("Absolute residual-correlation inputs are unavailable.",
         call. = FALSE)
  }

  required <- c(
    "protein_intake_raw", "protein_intake", "mean_body_mass_kg",
    "absolute_exposure_reference_g_day",
    "absolute_exposure_unit_g_day"
  )
  if (!all(required %in% names(data))) {
    stop("Absolute residual-correlation data are incomplete.",
         call. = FALSE)
  }

  reference <- unique(data$absolute_exposure_reference_g_day)
  unit <- unique(data$absolute_exposure_unit_g_day)
  maximum <- max(data$protein_intake_raw, na.rm = TRUE)
  if (
    length(reference) != 1L || !is.finite(reference) ||
      length(unit) != 1L || !is.finite(unit) || unit <= 0 ||
      !is.finite(exposure_minimum_g_day) ||
      exposure_minimum_g_day >= maximum ||
      !is.finite(grid_step_g_day) || grid_step_g_day <= 0
  ) {
    stop("The absolute residual-correlation exposure scale is invalid.",
         call. = FALSE)
  }

  data <- add_absolute_primary_body_mass(data)
  input <- make_rescor_candidate_data(
    data,
    specification,
    priors,
    rcs_distinct_fallback = if (identical(family, "supplement_rescor")) {
      "unique_support"
    } else {
      "error"
    }
  )

  ordered_data <- add_primary_standardised_moderators(data) |>
    dplyr::arrange(study_no, arm_no, outcome_no)
  exposure_values <- sort(unique(c(
    round(seq(
      exposure_minimum_g_day,
      maximum,
      by = grid_step_g_day
    ), 10),
    reference
  )))

  grid <- tidyr::crossing(
    resistance_exercise_code = c(0, 1),
    protein_intake_raw = exposure_values
  ) |>
    dplyr::mutate(
      protein_intake = (protein_intake_raw - reference) / unit
    )
  moderator_data <- add_primary_standardised_moderators(data)
  moderator_centres <- attr(moderator_data, "moderator_centres")
  moderator_scales <- attr(moderator_data, "moderator_scales")
  input$family <- family
  input$exposure <- exposure
  input$grid <- grid
  input$reference_g_day <- as.numeric(reference)
  input$internal_unit_g_day <- as.numeric(unit)
  input$grid_step_g_day <- as.numeric(grid_step_g_day)
  input$stan_data$N_grid <- nrow(grid)
  input$stan_data$x_grid <- grid$protein_intake
  input$stan_data$rt_grid <- grid$resistance_exercise_code
  input$stan_data$age_grid_z <- rep(
    (0 - moderator_centres[["age_centre"]]) /
      moderator_scales[["age_centre"]],
    nrow(grid)
  )
  input$stan_data$duration_grid_z <- rep(
    (0 - moderator_centres[["duration_centre"]]) /
      moderator_scales[["duration_centre"]],
    nrow(grid)
  )
  input$stan_data$body_mass_z <- ordered_data$body_mass_outcome_z
  input$stan_data$body_mass_grid_z <- rep(0, nrow(grid))
  input
}

validate_update_2026_absolute_rescor_inputs <- function(
    inputs,
    config,
    expected_rows,
    expected_studies,
    expected_arms,
    expected_reference_g_day,
    expected_internal_unit_g_day
) {
  outcomes <- config$outcomes
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    stan_data <- input$stan_data
    cluster_manifest <- input$cluster_manifest
    prior_median <- stan_data$rho_lower +
      (1 - stan_data$rho_lower) *
      stats::plogis(stan_data$rho_raw_prior_location)
    expected_cluster_start <- c(
      1L,
      utils::head(cluster_manifest$cluster_end, -1L) + 1L
    )
    valid <-
      identical(input$family, config$family) &&
      stan_data$N > 0L && stan_data$N_study > 1L &&
      stan_data$N_cluster == stan_data$N_study &&
      length(stan_data$y) == stan_data$N &&
      length(stan_data$se_y) == stan_data$N &&
      length(stan_data$body_mass_z) == stan_data$N &&
      all(is.finite(stan_data$y)) &&
      all(is.finite(stan_data$se_y)) && all(stan_data$se_y > 0) &&
      all(is.finite(stan_data$x)) &&
      all(is.finite(stan_data$body_mass_z)) &&
      nrow(cluster_manifest) == stan_data$N_cluster &&
      identical(
        as.integer(cluster_manifest$cluster_start),
        as.integer(expected_cluster_start)
      ) &&
      max(cluster_manifest$cluster_end) == stan_data$N &&
      all(cluster_manifest$cluster_size >= 1L) &&
      is.finite(stan_data$rho_lower) &&
      stan_data$rho_lower > -1 && stan_data$rho_lower < 0 &&
      is.finite(prior_median) && abs(prior_median) < 1e-10 &&
      length(stan_data$body_mass_grid_z) == stan_data$N_grid &&
      all(stan_data$body_mass_grid_z == 0) &&
      all(is.finite(stan_data$x_grid)) &&
      identical(
        as.integer(stan_data$correlated_study_effects),
        as.integer(!isTRUE(specification$uncorrelated_study_effects))
      )
    tibble::tibble(
      family = input$family,
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      contrasts = as.integer(stan_data$N),
      studies = as.integer(stan_data$N_study),
      arms = as.integer(stan_data$N_arm),
      outcome_rows = as.integer(stan_data$N_outcome),
      minimum_cluster_size = min(cluster_manifest$cluster_size),
      maximum_cluster_size = max(cluster_manifest$cluster_size),
      rho_lower = as.numeric(stan_data$rho_lower),
      rho_prior_median = as.numeric(prior_median),
      exposure_minimum_g_day = min(input$grid$protein_intake_raw),
      exposure_maximum_g_day = max(input$grid$protein_intake_raw),
      reference_g_day = as.numeric(input$reference_g_day),
      internal_unit_g_day = as.numeric(input$internal_unit_g_day),
      grid_step_g_day = as.numeric(input$grid_step_g_day),
      includes_moderators = isTRUE(specification$includes_moderators),
      body_mass_in_stan_data =
        length(stan_data$body_mass_z) == stan_data$N,
      historical_schedule = specification$historical_schedule,
      uncorrelated_study_effects =
        isTRUE(specification$uncorrelated_study_effects),
      adapt_delta = as.numeric(specification$adapt_delta),
      max_treedepth = as.integer(specification$max_treedepth),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      valid = valid
    )
  }) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  outcome_counts <- table(factor(checks$outcome, levels = outcomes))
  schedule_counts <- table(factor(
    checks$historical_schedule,
    levels = c("base", "remedy_1", "remedy_2", "structural_uncorrelated")
  ))
  sample_summary <- checks |>
    dplyr::distinct(outcome, contrasts, studies, arms)

  if (
    nrow(checks) != 72L || anyDuplicated(keys) || !all(checks$valid) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !identical(as.integer(schedule_counts), c(62L, 8L, 1L, 1L)) ||
      nrow(sample_summary) != 4L ||
      !identical(
        stats::setNames(sample_summary$contrasts, sample_summary$outcome)[outcomes],
        expected_rows[outcomes]
      ) ||
      !identical(
        stats::setNames(sample_summary$studies, sample_summary$outcome)[outcomes],
        expected_studies[outcomes]
      ) ||
      !identical(
        stats::setNames(sample_summary$arms, sample_summary$outcome)[outcomes],
        expected_arms[outcomes]
      ) ||
      any(checks$maximum_cluster_size <= 1L) ||
      any(abs(checks$rho_prior_median) >= 1e-10) ||
      any(checks$reference_g_day != expected_reference_g_day) ||
      any(checks$internal_unit_g_day != expected_internal_unit_g_day) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$body_mass_in_stan_data)
  ) {
    stop("The absolute residual-correlation preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_absolute_rescor_input_preflight <- function(
    checks,
    family,
    output_file
) {
  if (
    nrow(checks) != 72L || !all(checks$valid) ||
      any(checks$family != family)
  ) {
    stop("Cannot write an invalid absolute residual-correlation preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

read_update_2026_absolute_rescor_fit_file <- function(path, family) {
  if (length(path) != 1L || is.na(path) || !file.exists(path)) {
    stop("The absolute residual-correlation fit file is unavailable.",
         call. = FALSE)
  }
  candidate <- qs::qread(path)
  output_files <- tryCatch(
    candidate$fit$output_files(),
    error = function(e) character()
  )

  if (
    !is.list(candidate) || !identical(candidate$family, family) ||
      !inherits(candidate$fit, "CmdStanMCMC") ||
      is.null(candidate$outcome) || is.null(candidate$model_index) ||
      length(output_files) < 1L || any(!file.exists(output_files))
  ) {
    stop("The absolute residual-correlation fit archive is invalid.",
         call. = FALSE)
  }

  candidate
}

fit_update_2026_absolute_rescor_candidate_to_file <- function(
    input,
    model,
    config,
    stage = "initial",
    output_root
) {
  if (is_sensitivity_pilot_skip(model)) {
    stop("The absolute residual-correlation Stan model was not compiled.",
         call. = FALSE)
  }

  specification <- input$specification
  if (
    !identical(input$family, config$family) ||
      !identical(specification$family, config$family)
  ) {
    stop("The absolute residual-correlation fit input is misaligned.",
         call. = FALSE)
  }

  outcome_offset <- match(specification$outcome, config$outcomes)
  candidate_dir <- file.path(
    output_root,
    specification$outcome,
    sprintf("model_%02d", as.integer(specification$model_index))
  )
  output_file <- file.path(candidate_dir, "fit.qs")
  cmdstan_dir <- file.path(candidate_dir, "cmdstan")
  dir.create(cmdstan_dir, recursive = TRUE, showWarnings = FALSE)
  input_signature <- list(
    specification = specification,
    stan_data = input$stan_data,
    grid = input$grid,
    cluster_manifest = input$cluster_manifest
  )

  if (isTRUE(specification$fixed_metric_sampling)) {
    input_signature$metric_source_sha256 <- input$metric_source_sha256
  }
  input_sha256 <- digest::digest(input_signature, algo = "sha256")
  stan_file <- model$stan_file()
  stan_sha256 <- digest::digest(
    file = stan_file,
    algo = "sha256",
    serialize = FALSE
  )
  existing <- if (file.exists(output_file)) {
    tryCatch(
      read_update_2026_absolute_rescor_fit_file(
        output_file,
        config$family
      ),
      error = function(e) NULL
    )
  } else {
    NULL
  }

  if (
    !is.null(existing) &&
      identical(existing$input_sha256, input_sha256) &&
      identical(existing$stan_sha256, stan_sha256)
  ) {
    return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
  }

  sample_arguments <- list(
    data = input$stan_data,
    chains = specification$chains,
    parallel_chains = specification$parallel_chains,
    iter_warmup = specification$iter_warmup,
    iter_sampling = specification$iter_sampling,
    adapt_delta = specification$adapt_delta,
    max_treedepth = specification$max_treedepth,
    seed = as.integer(
      config$seed + 100L * (outcome_offset - 1L) +
        specification$model_index
    ),
    refresh = 100,
    output_dir = cmdstan_dir
  )

  fixed_metric_sampling <- isTRUE(specification$fixed_metric_sampling)
  if (fixed_metric_sampling) {
    metric_source_path <- input$metric_source_path
    metric_source_sha256 <- input$metric_source_sha256
    if (
      length(metric_source_path) != 1L || is.na(metric_source_path) ||
        !file.exists(metric_source_path) ||
        length(metric_source_sha256) != 1L ||
        is.na(metric_source_sha256) ||
        !identical(
          digest::digest(
            file = metric_source_path,
            algo = "sha256",
            serialize = FALSE
          ),
          metric_source_sha256
        ) ||
        !identical(specification$adapt_engaged, FALSE) ||
        !is.finite(specification$step_size) ||
        specification$step_size <= 0
    ) {
      stop(
        "The fixed-metric residual-correlation sampling input is invalid.",
        call. = FALSE
      )
    }
    metric_source <- read_update_2026_absolute_rescor_fit_file(
      metric_source_path,
      config$family
    )
    inverse_metrics <- metric_source$fit$inv_metric(matrix = FALSE)
    if (
      length(inverse_metrics) != specification$chains ||
        any(vapply(inverse_metrics, function(metric) {
          !is.numeric(metric) || !length(metric) ||
            any(!is.finite(metric)) || any(metric <= 0)
        }, logical(1L)))
    ) {
      stop(
        "The source fit does not contain valid per-chain inverse metrics.",
        call. = FALSE
      )
    }
    metric_dir <- file.path(candidate_dir, "fixed_metric")
    dir.create(metric_dir, recursive = TRUE, showWarnings = FALSE)
    metric_files <- vapply(
      seq_along(inverse_metrics),
      function(chain) {
        path <- file.path(metric_dir, sprintf("chain_%02d.json", chain))
        cmdstanr::write_stan_json(
          data = list(inv_metric = inverse_metrics[[chain]]),
          file = path
        )
        normalizePath(path, winslash = "/", mustWork = TRUE)
      },
      character(1L)
    )
    sample_arguments$adapt_delta <- NULL
    sample_arguments$adapt_engaged <- FALSE
    sample_arguments$step_size <- as.numeric(specification$step_size)
    sample_arguments$metric <- "diag_e"
    sample_arguments$metric_file <- metric_files
    sample_arguments$init <- metric_source$fit
  }

  fit <- do.call(model$sample, sample_arguments)
  candidate <- list(
    family = config$family,
    archive_stage = stage,
    outcome = specification$outcome,
    model_index = as.integer(specification$model_index),
    model_name = paste0(
      specification$model_name,
      " [residual correlation by study]"
    ),
    specification = specification,
    grid = input$grid,
    cluster_manifest = input$cluster_manifest,
    reference_g_day = input$reference_g_day,
    internal_unit_g_day = input$internal_unit_g_day,
    grid_step_g_day = input$grid_step_g_day,
    output_dir = normalizePath(
      cmdstan_dir,
      winslash = "/",
      mustWork = TRUE
    ),
    input_sha256 = input_sha256,
    stan_sha256 = stan_sha256,
    sampling_control = list(
      fixed_metric_sampling = fixed_metric_sampling,
      adapt_engaged = !fixed_metric_sampling,
      step_size = if (fixed_metric_sampling) {
        as.numeric(specification$step_size)
      } else {
        NA_real_
      },
      metric_source_sha256 = if (fixed_metric_sampling) {
        input$metric_source_sha256
      } else {
        NA_character_
      }
    ),
    fit = fit
  )

  write_atomic_qs(candidate, output_file)
}

make_update_2026_absolute_rescor_fit_manifest <- function(
    paths,
    family,
    stage
) {
  paths <- unname(unlist(paths, use.names = FALSE))

  if (length(paths) != 72L || anyNA(paths) || any(!file.exists(paths))) {
    stop("The absolute residual-correlation fit set is incomplete.",
         call. = FALSE)
  }
  manifest <- purrr::map_dfr(paths, function(path) {
    candidate <- read_update_2026_absolute_rescor_fit_file(path, family)
    tibble::tibble(
      family = family,
      outcome = candidate$outcome,
      model_index = as.integer(candidate$model_index),
      model_name = candidate$model_name,
      fit_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      stage = stage,
      bytes = as.numeric(file.info(path)$size),
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    )

  if (
    anyDuplicated(manifest[c("outcome", "model_index")]) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The absolute residual-correlation fit manifest is invalid.",
         call. = FALSE)
  }

  manifest
}

compile_update_2026_absolute_rescor_diagnostic_audit <- function(
    diagnostics,
    family
) {
  summary <- dplyr::bind_rows(diagnostics) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    ) |>
    dplyr::mutate(
      status = dplyr::if_else(
        diagnostic_pass,
        "PASS",
        "REQUIRES REMEDIATION"
      )
    )

  if (
    nrow(summary) != 72L || any(summary$family != family) ||
      anyDuplicated(summary[c("outcome", "model_index")])
  ) {
    stop("The absolute residual-correlation diagnostic audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = family,
    diagnostic_summary = summary,
    parameter_failures = tibble::tibble(),
    models = nrow(summary),
    models_passing_sampling = sum(summary$diagnostic_pass),
    models_requiring_remediation = sum(!summary$diagnostic_pass),
    all_sampling_diagnostics_pass = all(summary$diagnostic_pass)
  )
}

write_update_2026_absolute_rescor_fit_manifest <- function(
    manifest,
    family,
    output_file
) {
  if (
    nrow(manifest) != 72L || any(manifest$family != family) ||
      any(!file.exists(manifest$fit_path)) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("Cannot write an invalid absolute residual-correlation manifest.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(manifest, output_file, na = "")
  output_file
}

write_update_2026_absolute_rescor_diagnostic_audit <- function(
    audit,
    family,
    output_file
) {
  if (
    !identical(audit$family, family) || audit$models != 72L ||
      nrow(audit$diagnostic_summary) != 72L
  ) {
    stop("Cannot write an invalid absolute residual-correlation audit.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(audit$diagnostic_summary, output_file, na = "")
  output_file
}

make_update_2026_absolute_rescor_remedy_inputs <- function(
    inputs,
    diagnostic_audit,
    family
) {
  expected_keys <- c(
    "whole_body::11",
    "hypertrophy::1", "hypertrophy::2", "hypertrophy::15",
    "hypertrophy::24",
    "function::1", "function::2", "function::5", "function::6",
    "function::9", "function::15", "function::18", "function::20",
    "function::21", "function::24"
  )

  expected_convergence_keys <- "whole_body::11"
  expected_geometry_keys <- setdiff(expected_keys, expected_convergence_keys)
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  geometry_keys <- failed$key[!failed$geometry_pass]
  convergence_keys <- failed$key[
    failed$geometry_pass & !failed$convergence_pass
  ]

  if (
    !identical(diagnostic_audit$family, family) ||
      diagnostic_audit$models != 72L || nrow(failed) != 15L ||
      anyDuplicated(failed$key) || !setequal(failed$key, expected_keys) ||
      !setequal(geometry_keys, expected_geometry_keys) ||
      !setequal(convergence_keys, expected_convergence_keys) ||
      any(failed$maximum_treedepth_transitions != 0L) ||
      any(failed$minimum_ebfmi < 0.2)
  ) {
    stop("The absolute residual-correlation remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    ) %in% expected_keys
  }) |>
    purrr::map(function(input) {
      specification <- input$specification
      key <- paste(
        specification$outcome,
        specification$model_index,
        sep = "::"
      )
      if (key %in% expected_convergence_keys) {
        specification$iter_sampling <- max(
          as.integer(specification$iter_sampling),
          8000L
        )
        specification$remedy_level <- "convergence_1"
        specification$remedy <-
          "extended_sampling_after_convergence_failure"
        specification$remedy_reason <- paste(
          "Sampling geometry passed, but an effective sample-size",
          "threshold was not met; posterior sampling is extended."
        )
      } else {
        remedy_level <- switch(
          specification$historical_schedule,
          base = "geometry_1",
          remedy_1 = "geometry_2",
          remedy_2 = "geometry_3",
          stop(
            "An absolute residual-correlation remedy schedule is invalid.",
            call. = FALSE
          )
        )
        schedule <- switch(
          remedy_level,
          geometry_1 = list(
            adapt_delta = 0.999,
            max_treedepth = 15L,
            iter_warmup = 3000L,
            iter_sampling = 8000L,
            remedy = "sampling_and_geometry_escalation_1"
          ),
          geometry_2 = list(
            adapt_delta = 0.9999,
            max_treedepth = 16L,
            iter_warmup = 3000L,
            iter_sampling = 8000L,
            remedy = "sampling_and_geometry_escalation_2"
          ),
          geometry_3 = list(
            adapt_delta = 0.99999,
            max_treedepth = 17L,
            iter_warmup = 4000L,
            iter_sampling = 12000L,
            remedy = "sampling_and_geometry_escalation_3"
          )
        )
        specification$adapt_delta <- max(
          as.numeric(specification$adapt_delta),
          schedule$adapt_delta
        )
        specification$max_treedepth <- max(
          as.integer(specification$max_treedepth),
          schedule$max_treedepth
        )
        specification$iter_warmup <- schedule$iter_warmup
        specification$iter_sampling <- schedule$iter_sampling
        specification$remedy_level <- remedy_level
        specification$remedy <- schedule$remedy
        specification$remedy_reason <- paste(
          "At least one divergent transition remained in the initial fit;",
          "step size, adaptation, tree depth, and sampling are escalated",
          "from the model's historical schedule."
        )
      }
      specification$archive_stage <- "remedy_1"
      input$specification <- specification
      input
    })

  selected_keys <- purrr::map_chr(selected, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })

  if (
    length(selected) != 15L || anyDuplicated(selected_keys) ||
      !setequal(selected_keys, expected_keys)
  ) {
    stop("The absolute residual-correlation remedy inputs are incomplete.",
         call. = FALSE)
  }

  selected <- selected[match(expected_keys, selected_keys)]
  names(selected) <- paste0(
    purrr::map_chr(selected, ~ .x$specification$outcome),
    "_model_",
    stringr::str_pad(
      purrr::map_int(selected, ~ .x$specification$model_index),
      width = 2L,
      pad = "0"
    )
  )

  selected
}

make_update_2026_supplement_rescor_remedy_inputs <- function(
    inputs,
    diagnostic_audit
) {
  expected_keys <- c(
    "hypertrophy::1", "hypertrophy::2", "hypertrophy::5",
    "hypertrophy::6", "hypertrophy::8", "hypertrophy::11",
    "hypertrophy::12", "hypertrophy::18", "hypertrophy::21",
    "hypertrophy::23", "hypertrophy::24",
    "function::1", "function::2", "function::4", "function::5",
    "function::6", "function::11", "function::12", "function::14",
    "function::18", "function::20", "function::23", "function::24",
    "function::26"
  )

  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  if (
    !identical(diagnostic_audit$family, "supplement_rescor") ||
      diagnostic_audit$models != 72L || nrow(failed) != 24L ||
      anyDuplicated(failed$key) || !setequal(failed$key, expected_keys) ||
      any(failed$geometry_pass) || !all(failed$convergence_pass) ||
      any(failed$divergent_transitions < 1L) ||
      any(failed$maximum_treedepth_transitions != 0L) ||
      any(failed$minimum_ebfmi < 0.2)
  ) {
    stop("The supplement residual-correlation remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    ) %in% expected_keys
  }) |>
    purrr::map(function(input) {
      specification <- input$specification
      remedy_level <- switch(
        specification$historical_schedule,
        base = "geometry_1",
        remedy_1 = "geometry_2",
        remedy_2 = "geometry_3",
        structural_uncorrelated = "geometry_3",
        stop(
          "A supplement residual-correlation remedy schedule is invalid.",
          call. = FALSE
        )
      )
      schedule <- switch(
        remedy_level,
        geometry_1 = list(
          adapt_delta = 0.999,
          max_treedepth = 15L,
          iter_warmup = 3000L,
          iter_sampling = 8000L,
          remedy = "sampling_and_geometry_escalation_1"
        ),
        geometry_2 = list(
          adapt_delta = 0.9999,
          max_treedepth = 16L,
          iter_warmup = 3000L,
          iter_sampling = 8000L,
          remedy = "sampling_and_geometry_escalation_2"
        ),
        geometry_3 = list(
          adapt_delta = 0.99999,
          max_treedepth = 17L,
          iter_warmup = 4000L,
          iter_sampling = 12000L,
          remedy = "sampling_and_geometry_escalation_3"
        )
      )
      specification$adapt_delta <- max(
        as.numeric(specification$adapt_delta),
        schedule$adapt_delta
      )
      specification$max_treedepth <- max(
        as.integer(specification$max_treedepth),
        schedule$max_treedepth
      )
      specification$iter_warmup <- schedule$iter_warmup
      specification$iter_sampling <- schedule$iter_sampling
      specification$remedy_level <- remedy_level
      specification$remedy <- schedule$remedy
      specification$remedy_reason <- paste(
        "At least one divergent transition remained in the initial fit;",
        "the model advances one geometry level from its historical schedule."
      )
      specification$archive_stage <- "remedy_1"
      input$specification <- specification
      input
    })

  selected_keys <- purrr::map_chr(selected, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })

  if (
    length(selected) != 24L || anyDuplicated(selected_keys) ||
      !setequal(selected_keys, expected_keys)
  ) {
    stop("The supplement residual-correlation remedy inputs are incomplete.",
         call. = FALSE)
  }

  selected <- selected[match(expected_keys, selected_keys)]
  names(selected) <- paste0(
    purrr::map_chr(selected, ~ .x$specification$outcome),
    "_model_",
    stringr::str_pad(
      purrr::map_int(selected, ~ .x$specification$model_index),
      width = 2L,
      pad = "0"
    )
  )

  selected
}

validate_update_2026_supplement_rescor_remedy_inputs <- function(
    inputs,
    initial_manifest
) {
  initial_keys <- paste(
    initial_manifest$outcome,
    initial_manifest$model_index,
    sep = "::"
  )
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    key <- paste(specification$outcome, specification$model_index, sep = "::")
    initial_index <- match(key, initial_keys)
    initial_fit_exists <- !is.na(initial_index) &&
      file.exists(initial_manifest$fit_path[[initial_index]])
    valid <-
      identical(input$family, "supplement_rescor") &&
      identical(specification$family, "supplement_rescor") &&
      identical(specification$archive_stage, "remedy_1") &&
      specification$remedy_level %in%
        c("geometry_1", "geometry_2", "geometry_3") &&
      input$stan_data$N > 0L && input$stan_data$N_study > 1L &&
      input$stan_data$N_arm > 1L && initial_fit_exists &&
      specification$chains == 4L && specification$parallel_chains == 4L
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      historical_schedule = specification$historical_schedule,
      remedy_level = specification$remedy_level,
      remedy = specification$remedy,
      contrasts = as.integer(input$stan_data$N),
      studies = as.integer(input$stan_data$N_study),
      arms = as.integer(input$stan_data$N_arm),
      adapt_delta = as.numeric(specification$adapt_delta),
      max_treedepth = as.integer(specification$max_treedepth),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      initial_fit_exists = initial_fit_exists,
      valid = valid
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    )

  level_counts <- table(factor(
    checks$remedy_level,
    levels = c("geometry_1", "geometry_2", "geometry_3")
  ))
  level_schedule <- list(
    geometry_1 = c(0.999, 15, 3000, 8000),
    geometry_2 = c(0.9999, 16, 3000, 8000),
    geometry_3 = c(0.99999, 17, 4000, 12000)
  )
  schedule_valid <- all(vapply(seq_len(nrow(checks)), function(index) {
    expected <- level_schedule[[checks$remedy_level[[index]]]]
    identical(
      as.numeric(unlist(checks[index, c(
        "adapt_delta", "max_treedepth", "iter_warmup", "iter_sampling"
      )], use.names = FALSE)),
      expected
    )
  }, logical(1L)))

  if (
    nrow(initial_manifest) != 72L || anyDuplicated(initial_keys) ||
      nrow(checks) != 24L ||
      !identical(as.integer(level_counts), c(18L, 4L, 2L)) ||
      anyDuplicated(paste(checks$outcome, checks$model_index, sep = "::")) ||
      !schedule_valid || any(checks$chains != 4L) ||
      any(checks$parallel_chains != 4L) ||
      !all(checks$initial_fit_exists) || !all(checks$valid)
  ) {
    stop("The supplement residual-correlation remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_supplement_rescor_remedy_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "rescor", "remedy_1", "input_preflight.csv"
    )
) {
  if (nrow(checks) != 24L || !all(checks$valid)) {
    stop("Cannot write an invalid supplement rescor remedy preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

make_update_2026_supplement_rescor_remedy_fit_manifest <- function(paths) {
  paths <- unname(unlist(paths, use.names = FALSE))
  if (
    length(paths) != 24L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The supplement rescor remedy fit set is incomplete.",
         call. = FALSE)
  }

  manifest <- purrr::map_dfr(paths, function(path) {
    candidate <- read_update_2026_absolute_rescor_fit_file(
      path,
      "supplement_rescor"
    )
    tibble::tibble(
      family = candidate$family,
      outcome = candidate$outcome,
      model_index = as.integer(candidate$model_index),
      model_name = candidate$model_name,
      fit_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      stage = candidate$archive_stage,
      remedy_level = candidate$specification$remedy_level,
      remedy = candidate$specification$remedy,
      bytes = as.numeric(file.info(path)$size),
      sha256 = digest::digest(file = path, algo = "sha256", serialize = FALSE)
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    )

  if (
    nrow(manifest) != 24L ||
      any(manifest$family != "supplement_rescor") ||
      anyDuplicated(paste(manifest$outcome, manifest$model_index, sep = "::")) ||
      any(manifest$stage != "remedy_1") ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The supplement rescor remedy manifest is invalid.",
         call. = FALSE)
  }

  manifest
}

