      previous_fit_exists = previous_fit_exists,
      valid = valid
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c("hypertrophy", "function")),
      model_index
    )

  level_counts <- table(factor(
    checks$remedy_level,
    levels = c("geometry_2", "geometry_3", "geometry_4")
  ))
  level_schedule <- list(
    geometry_2 = c(0.9999, 16, 3000, 8000),
    geometry_3 = c(0.99999, 17, 4000, 12000),
    geometry_4 = c(0.999999, 18, 6000, 12000)
  )
  schedule_valid <- all(vapply(seq_len(nrow(checks)), function(index) {
    expected <- level_schedule[[checks$remedy_level[[index]]]]
    identical(
      as.numeric(unlist(checks[index, c(
        "adapt_delta", "max_treedepth", "iter_warmup", "iter_sampling"
      )], use.names = FALSE)),
      expected
    )
  }, logical(1L)))

  if (
    nrow(previous_manifest) != 24L || anyDuplicated(previous_keys) ||
      nrow(checks) != 10L ||
      !identical(as.integer(level_counts), c(8L, 1L, 1L)) ||
      anyDuplicated(paste(checks$outcome, checks$model_index, sep = "::")) ||
      !schedule_valid || any(checks$chains != 4L) ||
      any(checks$parallel_chains != 4L) ||
      !all(checks$previous_fit_exists) || !all(checks$valid)
  ) {
    stop("The second supplement rescor remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

