validate_update_2026_absolute_rescor_remedy_inputs <- function(
    inputs,
    initial_manifest,
    family
) {
  initial_keys <- paste(
    initial_manifest$outcome,
    initial_manifest$model_index,
    sep = "::"
  )
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    key <- paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    )
    initial_index <- match(key, initial_keys)
    initial_fit_exists <-
      !is.na(initial_index) &&
      file.exists(initial_manifest$fit_path[[initial_index]])
    valid <-
      identical(input$family, family) &&
      identical(specification$family, family) &&
      identical(specification$archive_stage, "remedy_1") &&
      specification$remedy_level %in% c(
        "convergence_1", "geometry_1", "geometry_2", "geometry_3"
      ) &&
      input$stan_data$N > 0L && input$stan_data$N_study > 1L &&
      input$stan_data$N_arm > 1L && initial_fit_exists &&
      specification$chains == 4L && specification$parallel_chains == 4L
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      historical_schedule = specification$historical_schedule,
      remedy_level = specification$remedy_level,
      remedy = specification$remedy,
      contrasts = as.integer(input$stan_data$N),
      studies = as.integer(input$stan_data$N_study),
      arms = as.integer(input$stan_data$N_arm),
      adapt_delta = as.numeric(specification$adapt_delta),
      max_treedepth = as.integer(specification$max_treedepth),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      initial_fit_exists = initial_fit_exists,
      valid = valid
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index
    )

  expected <- tibble::tribble(
    ~outcome, ~model_index, ~remedy_level, ~adapt_delta,
    ~max_treedepth, ~iter_warmup, ~iter_sampling,
    "whole_body", 11L, "convergence_1", 0.999, 15L, 2000L, 8000L,
    "hypertrophy", 1L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "hypertrophy", 2L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "hypertrophy", 15L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "hypertrophy", 24L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "function", 1L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "function", 2L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "function", 5L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "function", 6L, "geometry_3", 0.99999, 17L, 4000L, 12000L,
    "function", 9L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "function", 15L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "function", 18L, "geometry_2", 0.9999, 16L, 3000L, 8000L,
    "function", 20L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "function", 21L, "geometry_1", 0.999, 15L, 3000L, 8000L,
    "function", 24L, "geometry_1", 0.999, 15L, 3000L, 8000L
  )

  comparison <- checks |>
    dplyr::left_join(
      expected,
      by = c("outcome", "model_index"),
      suffix = c("", "_expected")
    )
  keys <- paste(checks$outcome, checks$model_index, sep = "::")

  if (
    nrow(initial_manifest) != 72L || anyDuplicated(initial_keys) ||
      nrow(checks) != 15L || anyDuplicated(keys) ||
      anyNA(comparison$remedy_level_expected) ||
      any(comparison$remedy_level != comparison$remedy_level_expected) ||
      any(comparison$adapt_delta != comparison$adapt_delta_expected) ||
      any(comparison$max_treedepth !=
            comparison$max_treedepth_expected) ||
      any(comparison$iter_warmup != comparison$iter_warmup_expected) ||
      any(comparison$iter_sampling != comparison$iter_sampling_expected) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$initial_fit_exists) || !all(checks$valid)
  ) {
    stop("The absolute residual-correlation remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

