compile_update_2026_absolute_rescor_final_diagnostic_audit <- function(
    initial_audit,
    remedy_diagnostics,
    family,
    expected_replacements = 15L
) {
  initial <- initial_audit$diagnostic_summary
  remedy <- dplyr::bind_rows(remedy_diagnostics)
  initial_keys <- paste(initial$outcome, initial$model_index, sep = "::")
  remedy_keys <- paste(remedy$outcome, remedy$model_index, sep = "::")
  failed_keys <- initial_keys[!initial$diagnostic_pass]
  original_rows <- initial[match(remedy_keys, initial_keys), , drop = FALSE]

  if (
    !identical(initial_audit$family, family) ||
      nrow(initial) != 72L ||
      nrow(remedy) != as.integer(expected_replacements) ||
      anyDuplicated(initial_keys) || anyDuplicated(remedy_keys) ||
      !setequal(remedy_keys, failed_keys) ||
      any(remedy$family != family) ||
      !identical(remedy$model_name, original_rows$model_name)
  ) {
    stop("The absolute residual-correlation diagnostic replacement is invalid.",
         call. = FALSE)
  }

  final <- initial |>
    dplyr::filter(
      !paste(outcome, model_index, sep = "::") %in% remedy_keys
    ) |>
    dplyr::select(-status) |>
    dplyr::bind_rows(remedy)
  compile_update_2026_absolute_rescor_diagnostic_audit(
    diagnostics = final,
    family = family
  )
}

make_update_2026_absolute_rescor_second_remedy_inputs <- function(
    inputs,
    diagnostic_audit,
    family
) {
  expected_keys <- c(
    "function::5", "function::6", "function::9", "function::15",
    "function::18", "function::20", "function::21"
  )
  expected_divergences <- c(
    "function::5" = 1,
    "function::6" = 1,
    "function::9" = 2,
    "function::15" = 3,
    "function::18" = 2,
    "function::20" = 3,
    "function::21" = 3
  )

  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  observed_divergences <- stats::setNames(
    failed$divergent_transitions,
    failed$key
  )

  if (
    !identical(diagnostic_audit$family, family) ||
      diagnostic_audit$models != 72L || nrow(failed) != 7L ||
      anyDuplicated(failed$key) || !setequal(failed$key, expected_keys) ||
      !identical(
        as.numeric(observed_divergences[expected_keys]),
        as.numeric(expected_divergences[expected_keys])
      ) ||
      any(failed$geometry_pass) || !all(failed$convergence_pass) ||
      any(failed$maximum_treedepth_transitions != 0L) ||
      any(failed$minimum_ebfmi < 0.2)
  ) {
    stop("The second absolute residual-correlation remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    ) %in% expected_keys
  }) |>
    purrr::map(function(input) {
      specification <- input$specification
      next_level <- switch(
        specification$remedy_level,
        geometry_1 = "geometry_2",
        geometry_2 = "geometry_3",
        geometry_3 = "geometry_4",
        stop(
          "A second absolute residual-correlation remedy level is invalid.",
          call. = FALSE
        )
      )
      schedule <- switch(
        next_level,
        geometry_2 = list(
          adapt_delta = 0.9999,
          max_treedepth = 16L,
          iter_warmup = 3000L,
          iter_sampling = 8000L,
          remedy = "sampling_and_geometry_escalation_2"
        ),
        geometry_3 = list(
          adapt_delta = 0.99999,
          max_treedepth = 17L,
          iter_warmup = 4000L,
          iter_sampling = 12000L,
          remedy = "sampling_and_geometry_escalation_3"
        ),
        geometry_4 = list(
          adapt_delta = 0.999999,
          max_treedepth = 18L,
          iter_warmup = 6000L,
          iter_sampling = 12000L,
          remedy = "sampling_and_geometry_escalation_4"
        )
      )
      specification$adapt_delta <- max(
        as.numeric(specification$adapt_delta),
        schedule$adapt_delta
      )
      specification$max_treedepth <- max(
        as.integer(specification$max_treedepth),
        schedule$max_treedepth
      )
      specification$iter_warmup <- schedule$iter_warmup
      specification$iter_sampling <- schedule$iter_sampling
      specification$remedy_level <- next_level
      specification$remedy <- schedule$remedy
      specification$remedy_reason <- paste(
        "Isolated divergent transitions remained after remedy 1;",
        "the model advances one additional geometry level."
      )
      specification$archive_stage <- "remedy_2"
      input$specification <- specification
      input
    })

  selected_keys <- purrr::map_chr(selected, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })

  if (
    length(selected) != 7L || anyDuplicated(selected_keys) ||
      !setequal(selected_keys, expected_keys)
  ) {
    stop("The second absolute residual-correlation inputs are incomplete.",
         call. = FALSE)
  }

  selected <- selected[match(expected_keys, selected_keys)]
  names(selected) <- paste0(
    purrr::map_chr(selected, ~ .x$specification$outcome),
    "_model_",
    stringr::str_pad(
      purrr::map_int(selected, ~ .x$specification$model_index),
      width = 2L,
      pad = "0"
    )
  )

  selected
}

validate_update_2026_absolute_rescor_second_remedy_inputs <- function(
    inputs,
    previous_manifest,
    family
) {
  previous_keys <- paste(
    previous_manifest$outcome,
    previous_manifest$model_index,
    sep = "::"
  )
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    key <- paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    )
    previous_index <- match(key, previous_keys)
    previous_fit_exists <-
      !is.na(previous_index) &&
      file.exists(previous_manifest$fit_path[[previous_index]])
    valid <-
      identical(input$family, family) &&
      identical(specification$family, family) &&
      identical(specification$archive_stage, "remedy_2") &&
      specification$remedy_level %in% c(
        "geometry_2", "geometry_3", "geometry_4"
      ) &&
      input$stan_data$N > 0L && input$stan_data$N_study > 1L &&
      input$stan_data$N_arm > 1L && previous_fit_exists &&
      specification$chains == 4L && specification$parallel_chains == 4L
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      previous_remedy_stage = "remedy_1",
      remedy_level = specification$remedy_level,
      remedy = specification$remedy,
      contrasts = as.integer(input$stan_data$N),
      studies = as.integer(input$stan_data$N_study),
      arms = as.integer(input$stan_data$N_arm),
      adapt_delta = as.numeric(specification$adapt_delta),
      max_treedepth = as.integer(specification$max_treedepth),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      previous_fit_exists = previous_fit_exists,
      valid = valid
    )
  }) |>
    dplyr::arrange(model_index)

  expected <- tibble::tribble(
    ~model_index, ~remedy_level, ~adapt_delta, ~max_treedepth,
    ~iter_warmup, ~iter_sampling,
    5L, "geometry_2", 0.9999, 16L, 3000L, 8000L,
    6L, "geometry_4", 0.999999, 18L, 6000L, 12000L,
    9L, "geometry_2", 0.9999, 16L, 3000L, 8000L,
    15L, "geometry_2", 0.9999, 16L, 3000L, 8000L,
    18L, "geometry_3", 0.99999, 17L, 4000L, 12000L,
    20L, "geometry_2", 0.9999, 16L, 3000L, 8000L,
    21L, "geometry_2", 0.9999, 16L, 3000L, 8000L
  )

  comparison <- checks |>
    dplyr::left_join(
      expected,
      by = "model_index",
      suffix = c("", "_expected")
    )
  keys <- paste(checks$outcome, checks$model_index, sep = "::")

  if (
    nrow(previous_manifest) != 15L || anyDuplicated(previous_keys) ||
      nrow(checks) != 7L || any(checks$outcome != "function") ||
      anyDuplicated(keys) || anyNA(comparison$remedy_level_expected) ||
      any(comparison$remedy_level != comparison$remedy_level_expected) ||
      any(comparison$adapt_delta != comparison$adapt_delta_expected) ||
      any(comparison$max_treedepth !=
            comparison$max_treedepth_expected) ||
      any(comparison$iter_warmup != comparison$iter_warmup_expected) ||
      any(comparison$iter_sampling != comparison$iter_sampling_expected) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$previous_fit_exists) || !all(checks$valid)
  ) {
    stop(
      "The second absolute residual-correlation preflight is incomplete.",
      call. = FALSE
    )
  }

  checks
}

write_update_2026_absolute_rescor_second_remedy_preflight <- function(
    checks,
    output_file
) {
  if (nrow(checks) != 7L || !all(checks$valid)) {
