  switch(
    family,
    total_rescor = list(
      keys = c("function::6", "function::18", "function::21"),
      divergences = c(
        "function::6" = 11,
        "function::18" = 3,
        "function::21" = 2
      ),
      previous_manifest_rows = 7L,
      expected = tibble::tribble(
        ~outcome, ~model_index, ~step_size, ~max_treedepth,
        ~iter_warmup, ~iter_sampling,
        "function", 6L, 0.002, 18L, 1000L, 12000L,
        "function", 18L, 0.002, 18L, 1000L, 12000L,
        "function", 21L, 0.002, 18L, 1000L, 8000L
      )
    ),
    supplement_rescor = list(
      keys = c(
        "hypertrophy::1", "hypertrophy::12",
        "function::24", "function::26"
      ),
      divergences = c(
        "hypertrophy::1" = 1,
        "hypertrophy::12" = 1,
        "function::24" = 2,
        "function::26" = 1
      ),
      previous_manifest_rows = 10L,
      expected = tibble::tribble(
        ~outcome, ~model_index, ~step_size, ~max_treedepth,
        ~iter_warmup, ~iter_sampling,
        "hypertrophy", 1L, 0.002, 18L, 1000L, 8000L,
        "hypertrophy", 12L, 0.002, 18L, 1000L, 8000L,
        "function", 24L, 0.002, 18L, 1000L, 8000L,
        "function", 26L, 0.002, 18L, 1000L, 8000L
      )
    ),
    stop(
      "The third residual-correlation remedy family is unsupported.",
      call. = FALSE
    )
  )
}

make_update_2026_absolute_rescor_third_remedy_inputs <- function(
    inputs,
    diagnostic_audit,
    previous_manifest,
    family,
    step_size = 0.002
) {
  remedy_spec <- update_2026_absolute_rescor_third_remedy_spec(family)
  expected_keys <- remedy_spec$keys
  expected_divergences <- remedy_spec$divergences
  expected_count <- length(expected_keys)
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
  observed_divergences <- stats::setNames(
    failed$divergent_transitions,
    failed$key
  )
  previous_keys <- paste(
    previous_manifest$outcome,
    previous_manifest$model_index,
    sep = "::"
  )

  if (
    !identical(diagnostic_audit$family, family) ||
      diagnostic_audit$models != 72L || nrow(failed) != expected_count ||
      anyDuplicated(failed$key) || !setequal(failed$key, expected_keys) ||
      !identical(
        as.numeric(observed_divergences[expected_keys]),
        as.numeric(expected_divergences[expected_keys])
      ) ||
      any(failed$geometry_pass) || !all(failed$convergence_pass) ||
      any(failed$maximum_treedepth_transitions != 0L) ||
      any(failed$minimum_ebfmi < 0.2) ||
      nrow(previous_manifest) != remedy_spec$previous_manifest_rows ||
      anyDuplicated(previous_keys) ||
      !all(expected_keys %in% previous_keys) ||
      !is.finite(step_size) || step_size <= 0
  ) {
    stop("The third absolute residual-correlation remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    ) %in% expected_keys
  }) |>
    purrr::map(function(input) {
      specification <- input$specification
      key <- paste(
        specification$outcome,
        specification$model_index,
        sep = "::"
      )
      previous_index <- match(key, previous_keys)
      specification$max_treedepth <- max(
        as.integer(specification$max_treedepth),
        18L
      )
      specification$iter_warmup <- 1000L
      specification$iter_sampling <- max(
        as.integer(specification$iter_sampling),
        8000L
      )
      specification$remedy_level <- "fixed_metric_1"
      specification$remedy <- "fixed_metric_small_step_sampling"
      specification$remedy_reason <- paste(
        "Rare divergences remain in the lower-bound tail despite",
        "successful convergence and adaptive geometry escalation; reuse",
        "the accepted per-chain diagonal metrics with a fixed small step."
      )
      specification$fixed_metric_sampling <- TRUE
      specification$adapt_engaged <- FALSE
      specification$step_size <- as.numeric(step_size)
      specification$archive_stage <- "remedy_3"
      input$specification <- specification
      input$metric_source_path <-
        previous_manifest$fit_path[[previous_index]]
      input$metric_source_sha256 <-
        previous_manifest$sha256[[previous_index]]
      input
    })

  selected_keys <- purrr::map_chr(selected, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })

  if (
    length(selected) != expected_count || anyDuplicated(selected_keys) ||
      !setequal(selected_keys, expected_keys)
  ) {
    stop("The third absolute residual-correlation inputs are incomplete.",
         call. = FALSE)
  }

  selected <- selected[match(expected_keys, selected_keys)]
  names(selected) <- paste0(
    purrr::map_chr(selected, ~ .x$specification$outcome),
    "_model_",
    stringr::str_pad(
      purrr::map_int(selected, ~ .x$specification$model_index),
      width = 2L,
      pad = "0"
    )
  )

  selected
}

validate_update_2026_absolute_rescor_third_remedy_inputs <- function(
    inputs,
    previous_manifest,
    family
) {
  remedy_spec <- update_2026_absolute_rescor_third_remedy_spec(family)
  expected_keys <- remedy_spec$keys
  expected_count <- length(expected_keys)
  previous_keys <- paste(
    previous_manifest$outcome,
    previous_manifest$model_index,
    sep = "::"
  )
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    key <- paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    )
    previous_index <- match(key, previous_keys)
    previous_fit_exists <-
      !is.na(previous_index) &&
      file.exists(previous_manifest$fit_path[[previous_index]])
    source_hash_matches <-
      previous_fit_exists &&
      identical(
        input$metric_source_sha256,
        previous_manifest$sha256[[previous_index]]
      ) &&
      identical(
        digest::digest(
          file = input$metric_source_path,
          algo = "sha256",
          serialize = FALSE
        ),
        input$metric_source_sha256
      )
    valid <-
      identical(input$family, family) &&
      identical(specification$family, family) &&
      identical(specification$archive_stage, "remedy_3") &&
      identical(specification$remedy_level, "fixed_metric_1") &&
      isTRUE(specification$fixed_metric_sampling) &&
      identical(specification$adapt_engaged, FALSE) &&
      is.finite(specification$step_size) &&
      specification$step_size > 0 &&
      input$stan_data$N > 0L && input$stan_data$N_study > 1L &&
      input$stan_data$N_arm > 1L && previous_fit_exists &&
      source_hash_matches && specification$chains == 4L &&
      specification$parallel_chains == 4L
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      previous_remedy_stage = "remedy_2",
      remedy_level = specification$remedy_level,
      remedy = specification$remedy,
      contrasts = as.integer(input$stan_data$N),
      studies = as.integer(input$stan_data$N_study),
      arms = as.integer(input$stan_data$N_arm),
      adapt_engaged = specification$adapt_engaged,
      step_size = as.numeric(specification$step_size),
      max_treedepth = as.integer(specification$max_treedepth),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      metric_source_sha256 = input$metric_source_sha256,
      previous_fit_exists = previous_fit_exists,
      source_hash_matches = source_hash_matches,
      valid = valid
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  expected <- remedy_spec$expected
  comparison <- checks |>
    dplyr::left_join(
      expected,
      by = c("outcome", "model_index"),
      suffix = c("", "_expected")
    )
  keys <- paste(checks$outcome, checks$model_index, sep = "::")

  if (
    nrow(previous_manifest) != remedy_spec$previous_manifest_rows ||
      anyDuplicated(previous_keys) || nrow(checks) != expected_count ||
      anyDuplicated(keys) || !setequal(keys, expected_keys) ||
      anyNA(comparison$step_size_expected) ||
      any(comparison$step_size != comparison$step_size_expected) ||
      any(comparison$max_treedepth !=
            comparison$max_treedepth_expected) ||
      any(comparison$iter_warmup != comparison$iter_warmup_expected) ||
      any(comparison$iter_sampling != comparison$iter_sampling_expected) ||
      any(checks$adapt_engaged) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$previous_fit_exists) ||
      !all(checks$source_hash_matches) || !all(checks$valid)
  ) {
    stop(
      "The third absolute residual-correlation preflight is incomplete.",
      call. = FALSE
    )
  }

  checks
}

write_update_2026_absolute_rescor_third_remedy_preflight <- function(
    checks,
    output_file,
    family = "total_rescor"
) {
  remedy_spec <- update_2026_absolute_rescor_third_remedy_spec(family)
  keys <- paste(checks$outcome, checks$model_index, sep = "::")

  if (
    nrow(checks) != length(remedy_spec$keys) ||
      !setequal(keys, remedy_spec$keys) || !all(checks$valid)
  ) {
    stop(
      "Cannot write an invalid third absolute residual-correlation preflight.",
      call. = FALSE
    )
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

make_update_2026_absolute_rescor_third_remedy_fit_manifest <- function(
    paths,
    family
) {
  remedy_spec <- update_2026_absolute_rescor_third_remedy_spec(family)
  expected_count <- length(remedy_spec$keys)
  paths <- unname(unlist(paths, use.names = FALSE))

  if (
    length(paths) != expected_count || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop(
      "The third absolute residual-correlation fit set is incomplete.",
      call. = FALSE
    )
  }

  manifest <- purrr::map_dfr(paths, function(path) {
    candidate <- read_update_2026_absolute_rescor_fit_file(path, family)
    tibble::tibble(
      family = candidate$family,
      outcome = candidate$outcome,
      model_index = as.integer(candidate$model_index),
      model_name = candidate$model_name,
      fit_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      stage = candidate$archive_stage,
      remedy_level = candidate$specification$remedy_level,
      remedy = candidate$specification$remedy,
      adapt_engaged = candidate$sampling_control$adapt_engaged,
      step_size = candidate$sampling_control$step_size,
      metric_source_sha256 =
        candidate$sampling_control$metric_source_sha256,
      bytes = as.numeric(file.info(path)$size),
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  keys <- paste(manifest$outcome, manifest$model_index, sep = "::")
  if (
    nrow(manifest) != expected_count || any(manifest$family != family) ||
      anyDuplicated(keys) || !setequal(keys, remedy_spec$keys) ||
      any(manifest$stage != "remedy_3") ||
      any(manifest$adapt_engaged) || any(manifest$step_size != 0.002) ||
      any(nchar(manifest$metric_source_sha256) != 64L) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The third absolute residual-correlation manifest is invalid.",
         call. = FALSE)
  }

  manifest
}

