make_update_2026_absolute_rescor_accepted_fit_manifest <- function(
    initial_manifest,
    remedy_manifest,
    second_remedy_manifest,
    third_remedy_manifest,
    final_diagnostic_audit,
    family
) {
  stage_spec <- update_2026_absolute_rescor_accepted_stage_spec(family)
  replace_rows <- function(current, replacement) {
    current |>
      dplyr::anti_join(
        replacement |> dplyr::select(outcome, model_index),
        by = c("outcome", "model_index")
      ) |>
      dplyr::bind_rows(replacement)
  }

  accepted <- initial_manifest |>
    replace_rows(remedy_manifest) |>
    replace_rows(second_remedy_manifest) |>
    replace_rows(third_remedy_manifest) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  accepted_keys <- paste(
    accepted$outcome,
    accepted$model_index,
    sep = "::"
  )
  final_summary <- final_diagnostic_audit$diagnostic_summary
  final_keys <- paste(
    final_summary$outcome,
    final_summary$model_index,
    sep = "::"
  )
  outcome_counts <- table(factor(
    accepted$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  stage_counts <- table(factor(
    accepted$stage,
    levels = c("initial", "remedy_1", "remedy_2", "remedy_3")
  ))

  if (
    nrow(initial_manifest) != 72L ||
      nrow(remedy_manifest) != stage_spec$remedy_manifest_rows ||
      nrow(second_remedy_manifest) !=
        stage_spec$second_remedy_manifest_rows ||
      nrow(third_remedy_manifest) !=
        stage_spec$third_remedy_manifest_rows ||
      !identical(final_diagnostic_audit$family, family) ||
      !isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass) ||
      nrow(final_summary) != 72L || !all(final_summary$diagnostic_pass) ||
      nrow(accepted) != 72L || anyDuplicated(accepted_keys) ||
      !setequal(accepted_keys, final_keys) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !identical(
        as.integer(stage_counts),
        stage_spec$accepted_stage_counts
      ) ||
      any(accepted$family != family) ||
      any(!file.exists(accepted$fit_path)) ||
      any(accepted$bytes <= 0) || any(nchar(accepted$sha256) != 64L)
  ) {
    stop("The accepted absolute residual-correlation manifest is invalid.",
         call. = FALSE)
  }

  accepted
}

