validate_update_2026_absolute_rescor_loo_inputs <- function(
    accepted_fit_manifest,
    final_diagnostic_audit,
    inputs,
    family,
    loo_draws = 4000L,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  stage_spec <- update_2026_absolute_rescor_accepted_stage_spec(family)
  accepted_keys <- paste(
    accepted_fit_manifest$outcome,
    accepted_fit_manifest$model_index,
    sep = "::"
  )
  input_keys <- purrr::map_chr(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })
  input_families <- purrr::map_chr(inputs, "family")
  stage_counts <- table(factor(
    accepted_fit_manifest$stage,
    levels = c("initial", "remedy_1", "remedy_2", "remedy_3")
  ))
  outcome_counts <- table(factor(
    accepted_fit_manifest$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  stage_description <- paste(
    stage_spec$accepted_stage_counts,
    c("initial", "remedy-1", "remedy-2", "remedy-3"),
    collapse = " "
  )
  checks <- tibble::tibble(
    check = c(
      "all 72 final absolute residual-correlation diagnostics pass",
      "accepted registry contains 18 models per outcome",
      paste("accepted registry contains", stage_description, "fits"),
      "all 72 accepted fits align one-to-one with their original inputs",
      "all accepted fit files exist are nonempty and have hashes",
      paste(
        "study-integrated LOO uses 4000 draws a 0.7 threshold",
        "and one core per branch"
      )
    ),
    passed = c(
      identical(final_diagnostic_audit$family, family) &&
        final_diagnostic_audit$models == 72L &&
        isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass),
      identical(as.integer(outcome_counts), rep(18L, 4L)),
      identical(
        as.integer(stage_counts),
        stage_spec$accepted_stage_counts
      ),
      length(inputs) == 72L && !anyDuplicated(input_keys) &&
        setequal(accepted_keys, input_keys) &&
        all(input_families == family),
      all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(file.info(accepted_fit_manifest$fit_path)$size > 0) &&
        all(nchar(accepted_fit_manifest$sha256) == 64L),
      identical(as.integer(loo_draws), 4000L) &&
        identical(k_threshold, 0.7) &&
        identical(as.integer(cores_per_branch), 1L)
    )
  )

  ready <-
    nrow(accepted_fit_manifest) == 72L &&
    !anyDuplicated(accepted_keys) && all(checks$passed)
  if (!ready) {
    stop("The absolute residual-correlation LOO preflight is incomplete.",
         call. = FALSE)
  }

  list(
    family = family,
    models = 72L,
    loo_draws = as.integer(loo_draws),
    k_threshold = k_threshold,
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    ready = TRUE
  )
}

write_update_2026_absolute_rescor_loo_preflight <- function(
    preflight,
    family,
    output_dir
) {
  if (
    !identical(preflight$family, family) ||
      !isTRUE(preflight$ready) || preflight$models != 72L ||
      !all(preflight$checks$passed)
  ) {
    stop("Cannot write an invalid absolute residual-correlation LOO preflight.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    checks = file.path(output_dir, "checks.csv"),
    accepted_fit_manifest = file.path(
      output_dir,
      "accepted_fit_manifest.csv"
    )
  )
  readr::write_csv(preflight$checks, paths[["checks"]], na = "")
  readr::write_csv(
    preflight$accepted_fit_manifest,
    paths[["accepted_fit_manifest"]],
    na = ""
  )
  unname(paths)
}

# Prepare the accepted residual-correlation fits for holdout scoring while
# retaining the exposure family and candidate identifiers.
make_update_2026_absolute_rescor_loo_records <- function(
    accepted_fit_manifest,
    inputs,
    family
) {
  accepted_keys <- paste(
    accepted_fit_manifest$outcome,
    accepted_fit_manifest$model_index,
    sep = "::"
  )
  input_keys <- purrr::map_chr(inputs, function(input) {
    paste(
      input$specification$outcome,
      input$specification$model_index,
      sep = "::"
    )
  })

  if (
    nrow(accepted_fit_manifest) != 72L || length(inputs) != 72L ||
      any(accepted_fit_manifest$family != family) ||
      anyDuplicated(accepted_keys) || anyDuplicated(input_keys) ||
      !setequal(accepted_keys, input_keys) ||
      any(!file.exists(accepted_fit_manifest$fit_path))
  ) {
    stop("The absolute residual-correlation fit/input registry is misaligned.",
         call. = FALSE)
  }

  records <- purrr::map(seq_len(nrow(accepted_fit_manifest)), function(row) {
    record <- purrr::map(
      as.list(accepted_fit_manifest[row, , drop = FALSE]),
      unname
    )
    record$input <- inputs[[match(accepted_keys[[row]], input_keys)]]
    record
  })

  names(records) <- paste0(
    accepted_fit_manifest$outcome,
    "_model_",
    stringr::str_pad(accepted_fit_manifest$model_index, 2L, pad = "0")
  )
  records
}

compute_update_2026_absolute_rescor_integrated_loo_to_file <- function(
    fit_record,
    enabled,
    family,
    loo_draws = 4000L,
    k_threshold = 0.7,
    cores = 1L,
    output_root
) {
  if (!isTRUE(enabled)) {
    runtime_variable <- switch(
      family,
      total_rescor = "PROTEIN_UPDATE_2026_TOTAL_RESCOR_LOO",
      supplement_rescor = "PROTEIN_UPDATE_2026_SUPPLEMENT_RESCOR_LOO",
      "the corresponding residual-correlation LOO runtime flag"
    )
    stop(
      paste0(
        "Absolute residual-correlation LOO is disabled. Set ",
        runtime_variable,
        "=run to enable it."
      ),
      call. = FALSE
    )
  }

  candidate <- read_update_2026_absolute_rescor_fit_file(
    fit_record$fit_path,
    family
  )
  input <- fit_record$input
  if (
    !identical(candidate$family, family) ||
      !identical(input$family, family) ||
      candidate$model_index != input$specification$model_index ||
      candidate$model_index != fit_record$model_index ||
      !identical(candidate$outcome, input$specification$outcome) ||
      !identical(candidate$outcome, fit_record$outcome)
  ) {
    stop("The absolute residual-correlation LOO record is misaligned.",
         call. = FALSE)
  }

  available <- posterior::ndraws(candidate$fit$draws("b_intercept"))
  draw_ids <- make_sensitivity_loo_draw_ids(
    available,
    min(as.integer(loo_draws), available)
  )
  conditional_log_lik <- posterior::as_draws_matrix(
    candidate$fit$draws("log_lik_cluster")
  )[draw_ids, , drop = FALSE]
  integrated_log_lik <- posterior::as_draws_matrix(
    candidate$fit$draws("log_lik_cluster_integrated")
  )[draw_ids, , drop = FALSE]

  if (
    ncol(conditional_log_lik) != nrow(input$cluster_manifest) ||
      ncol(integrated_log_lik) != nrow(input$cluster_manifest) ||
      anyNA(conditional_log_lik) || any(!is.finite(conditional_log_lik)) ||
      anyNA(integrated_log_lik) || any(!is.finite(integrated_log_lik))
  ) {
    stop("The absolute residual-correlation log likelihood is invalid.",
         call. = FALSE)
  }

  result <- list(
    family = family,
    outcome = candidate$outcome,
    model_index = as.integer(candidate$model_index),
    model_name = candidate$model_name,
    loo = loo::loo(integrated_log_lik, cores = as.integer(cores)),
    conditional_loo = loo::loo(
      conditional_log_lik,
      cores = as.integer(cores)
    ),
    observation_manifest = input$cluster_manifest,
    remedy = "study_cluster_integrated_psis",
    k_threshold = k_threshold,
    loo_draws = length(draw_ids),
    fit_record = fit_record[c(
      "family", "outcome", "model_index", "model_name", "fit_path",
      "stage", "bytes", "sha256"
    )],
    input = input
  )

  output_dir <- file.path(output_root, result$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d_integrated_loo.qs", result$model_index)
  )
  write_atomic_qs(result, output_file)
}

write_update_2026_absolute_rescor_integrated_loo_audit <- function(
    audit,
    manifest,
    family,
    output_dir
) {
  method_counts <- table(factor(
    audit$model_summary$method,
    levels = c(
      "conditional_study_cluster_psis",
      "integrated_study_cluster_psis"
    )
  ))

  if (
    !identical(audit$family, family) || audit$models != 72L ||
      nrow(manifest) != 72L || nrow(audit$model_summary) != 144L ||
      !identical(as.integer(method_counts), c(72L, 72L)) ||
      nrow(audit$outcome_summary) != 4L ||
      any(audit$outcome_summary$models != 18L) ||
      audit$exact_refits_required != nrow(audit$high_k_cases) ||
      any(!file.exists(manifest$integrated_loo_path)) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The absolute residual-correlation LOO audit is incomplete.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    reduction_manifest = file.path(output_dir, "reduction_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    high_k_cases = file.path(output_dir, "high_k_cases.csv")
  )
  readr::write_csv(manifest, paths[["reduction_manifest"]], na = "")
  readr::write_csv(audit$model_summary, paths[["model_summary"]], na = "")
  readr::write_csv(
    audit$outcome_summary,
    paths[["outcome_summary"]],
    na = ""
  )
  readr::write_csv(audit$high_k_cases, paths[["high_k_cases"]], na = "")
  unname(paths)
}

make_update_2026_absolute_rescor_exact_config <- function(
    base_config,
    iter_warmup = 2000L,
    iter_sampling = 6000L,
    adapt_delta = 0.999,
    max_treedepth = 15L,
    seed_offset = 40000L
) {
  config <- base_config
  config$iter_warmup <- as.integer(iter_warmup)
  config$iter_sampling <- as.integer(iter_sampling)
  config$adapt_delta_floor <- as.numeric(adapt_delta)
  config$max_treedepth_floor <- as.integer(max_treedepth)
  config$seed <- as.integer(base_config$seed + seed_offset)

  if (
    !config$family %in% c("total_rescor", "supplement_rescor") ||
      config$chains != 4L || config$parallel_chains != 4L ||
      config$iter_warmup != 2000L || config$iter_sampling != 6000L ||
      config$adapt_delta_floor != 0.999 ||
      config$max_treedepth_floor != 15L
  ) {
    stop("The absolute residual-correlation exact-LOO config is invalid.",
         call. = FALSE)
  }

  config
}

