make_update_2026_absolute_rescor_leave_one_study_out_data <- function(
    stan_data,
    cluster
) {
  cluster <- as.integer(cluster)
  if (
    length(cluster) != 1L || is.na(cluster) || cluster < 1L ||
      cluster > stan_data$N_cluster
  ) {
    stop("Invalid held-out absolute residual-correlation study.",
         call. = FALSE)
  }

  first <- stan_data$cluster_start[[cluster]]
  last <- stan_data$cluster_end[[cluster]]
  keep <- setdiff(seq_len(stan_data$N), seq.int(first, last))
  row_fields <- c(
    "y", "se_y", "x", "study", "arm", "outcome",
    "resistance_exercise_code", "age_z", "duration_z", "body_mass_z"
  )

  if (
    !all(row_fields %in% names(stan_data)) ||
      any(vapply(stan_data[row_fields], length, integer(1L)) != stan_data$N)
  ) {
    stop("Absolute residual-correlation row data are incomplete.",
         call. = FALSE)
  }

  for (field in row_fields) {
    stan_data[[field]] <- stan_data[[field]][keep]
  }
  remap <- function(values) match(values, unique(values))
  stan_data$study <- remap(stan_data$study)
  stan_data$arm <- remap(stan_data$arm)
  stan_data$outcome <- remap(stan_data$outcome)
  stan_data$N <- length(keep)
  stan_data$N_study <- max(stan_data$study)
  stan_data$N_arm <- max(stan_data$arm)
  stan_data$N_outcome <- max(stan_data$outcome)
  runs <- rle(stan_data$study)
  stan_data$N_cluster <- length(runs$lengths)
  stan_data$cluster_end <- as.integer(cumsum(runs$lengths))
  stan_data$cluster_start <- as.integer(c(
    1L,
    utils::head(stan_data$cluster_end, -1L) + 1L
  ))

  if (max(runs$lengths) <= 1L) {
    stop("The training data cannot identify residual correlation.",
         call. = FALSE)
  }
  stan_data$rho_lower <- -1 / (max(runs$lengths) - 1) + 1e-8
  stan_data$rho_raw_prior_location <- stats::qlogis(
    -stan_data$rho_lower / (1 - stan_data$rho_lower)
  )
  stan_data
}

validate_update_2026_absolute_rescor_exact_inputs <- function(
    records,
    integrated_audit,
    config,
    expected_cases = 89L
) {
  exact_spec <- update_2026_absolute_rescor_exact_initial_spec(config$family)
  expected <- as.integer(integrated_audit$exact_refits_required)

  if (
    !is.list(records) ||
      as.integer(expected_cases) != exact_spec$expected_cases ||
      expected != as.integer(expected_cases) ||
      length(records) != expected
  ) {
    stop("The absolute residual-correlation exact-refit set has changed.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    original_fit_exists <- file.exists(record$original_fit_path)
    integrated_loo_exists <- file.exists(record$integrated_loo_path)
    original_hash_matches <-
      original_fit_exists &&
      identical(
        digest::digest(
          file = record$original_fit_path,
          algo = "sha256",
          serialize = FALSE
        ),
        record$original_fit_sha256
      )
    loo_hash_matches <-
      integrated_loo_exists &&
      identical(
        digest::digest(
          file = record$integrated_loo_path,
          algo = "sha256",
          serialize = FALSE
        ),
        record$integrated_loo_sha256
      )
    integrated <- if (integrated_loo_exists) {
      qs::qread(record$integrated_loo_path)
    } else {
      NULL
    }
    observation <- as.integer(record$observation)
    pareto_values <- if (
      is.list(integrated) && inherits(integrated$loo, "loo")
    ) {
      as.numeric(loo::pareto_k_values(integrated$loo))
    } else {
      numeric()
    }
    deletion_valid <- FALSE
    held_out_cluster_size <- NA_integer_
    study_no <- NA_character_
    effective_adapt_delta <- NA_real_
    effective_max_treedepth <- NA_integer_
    if (
      is.list(integrated) && identical(integrated$family, config$family) &&
        is.list(integrated$input) && is.list(integrated$input$stan_data) &&
        observation >= 1L &&
        observation <= integrated$input$stan_data$N_cluster
    ) {
      full_data <- integrated$input$stan_data
      if (
        is.data.frame(integrated$observation_manifest) &&
          "study_no" %in% names(integrated$observation_manifest) &&
          nrow(integrated$observation_manifest) >= observation
      ) {
        study_no <- as.character(
          integrated$observation_manifest$study_no[[observation]]
        )
      }
      held_out_cluster_size <-
        full_data$cluster_end[[observation]] -
        full_data$cluster_start[[observation]] + 1L
      training_data <-
        make_update_2026_absolute_rescor_leave_one_study_out_data(
          full_data,
          observation
        )
      deletion_valid <-
        training_data$N == full_data$N - held_out_cluster_size &&
        training_data$N_cluster == full_data$N_cluster - 1L &&
        training_data$N_study == full_data$N_study - 1L &&
        length(training_data$body_mass_z) == training_data$N &&
        all(is.finite(training_data$body_mass_z))
      effective_adapt_delta <- max(
        as.numeric(integrated$input$specification$adapt_delta),
        config$adapt_delta_floor
      )
      effective_max_treedepth <- max(
        as.integer(integrated$input$specification$max_treedepth),
        config$max_treedepth_floor
      )
    }
    pareto_matches <-
      length(pareto_values) >= observation && observation >= 1L &&
      isTRUE(all.equal(
        pareto_values[[observation]],
        as.numeric(record$pareto_k),
        tolerance = 1e-12
      )) && pareto_values[[observation]] > integrated_audit$k_threshold
    valid <-
      original_fit_exists && integrated_loo_exists &&
      original_hash_matches && loo_hash_matches &&
      is.list(integrated) &&
      identical(integrated$family, config$family) &&
      identical(integrated$outcome, record$outcome) &&
      integrated$model_index == record$model_index &&
      pareto_matches && deletion_valid &&
      is.finite(effective_adapt_delta) &&
      effective_adapt_delta > 0 && effective_adapt_delta < 1 &&
      effective_max_treedepth >= 1L
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = observation,
      study_no = study_no,
      cluster_size = as.integer(held_out_cluster_size),
      pareto_k = as.numeric(record$pareto_k),
      adapt_delta = effective_adapt_delta,
      max_treedepth = effective_max_treedepth,
      iter_warmup = as.integer(config$iter_warmup),
      iter_sampling = as.integer(config$iter_sampling),
      chains = as.integer(config$chains),
      parallel_chains = as.integer(config$parallel_chains),
      original_fit_exists = original_fit_exists,
      integrated_loo_exists = integrated_loo_exists,
      original_hash_matches = original_hash_matches,
      loo_hash_matches = loo_hash_matches,
      deletion_valid = deletion_valid,
      valid = valid
    )
  }) |>
    dplyr::arrange(case_id)

  outcome_counts <- table(factor(
    checks$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  if (
    nrow(checks) != expected ||
      !identical(checks$case_id, seq_len(expected)) ||
      anyDuplicated(paste(
        checks$outcome,
        checks$model_index,
        checks$observation,
        sep = "::"
      )) ||
      !identical(
        as.integer(outcome_counts),
        exact_spec$outcome_counts
      ) ||
      any(checks$iter_warmup != 2000L) ||
      any(checks$iter_sampling != 6000L) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$valid)
  ) {
    stop("The absolute residual-correlation exact preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_absolute_rescor_exact_preflight <- function(
    checks,
    output_file,
    expected_cases = 89L
) {
  if (nrow(checks) != as.integer(expected_cases) || !all(checks$valid)) {
    stop("Cannot write an invalid absolute residual-correlation exact preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

read_update_2026_absolute_rescor_exact_fit_file <- function(path, family) {
  if (length(path) != 1L || is.na(path) || !file.exists(path)) {
    stop("An absolute residual-correlation exact-refit file is unavailable.",
         call. = FALSE)
  }
  refit <- qs::qread(path)
  output_files <- tryCatch(
    refit$fitted_candidate$fit$output_files(),
    error = function(e) character()
  )

  if (
    !is.list(refit) || !identical(refit$family, family) ||
      !inherits(refit$fitted_candidate$fit, "CmdStanMCMC") ||
      length(output_files) != 4L || any(!file.exists(output_files)) ||
      is.null(refit$case_id) || is.null(refit$observation)
  ) {
    stop("An absolute residual-correlation exact-refit file is invalid.",
         call. = FALSE)
  }

  refit
}

fit_update_2026_absolute_rescor_exact_to_file <- function(
    record,
    model,
    config,
    enabled,
    output_root,
    stage = "exact_initial",
    metric_source_path = NULL,
    metric_source_sha256 = NULL,
    fixed_step_size = NULL
) {
  if (!isTRUE(enabled)) {
    runtime_variable <- switch(
      config$family,
      total_rescor = "PROTEIN_UPDATE_2026_TOTAL_RESCOR_EXACT",
      supplement_rescor = "PROTEIN_UPDATE_2026_SUPPLEMENT_RESCOR_EXACT",
      "the corresponding residual-correlation exact runtime flag"
    )
    stop(
      paste0(
        "Absolute residual-correlation exact fitting is disabled. Set ",
        runtime_variable,
        "=fit to enable it."
      ),
      call. = FALSE
    )
  }

  if (is_sensitivity_pilot_skip(model)) {
    stop("The absolute residual-correlation Stan model was not compiled.",
         call. = FALSE)
  }
  case_dir <- file.path(
    output_root,
    record$outcome,
    sprintf("model_%02d", as.integer(record$model_index)),
    sprintf("case_%03d", as.integer(record$case_id))
  )
  output_file <- file.path(case_dir, "fit.qs")
  cmdstan_dir <- file.path(case_dir, "cmdstan")
  dir.create(cmdstan_dir, recursive = TRUE, showWarnings = FALSE)
  fixed_metric_sampling <- !is.null(metric_source_path)
  signature <- list(
    family = config$family,
    stage = stage,
    case_id = as.integer(record$case_id),
    outcome = record$outcome,
    model_index = as.integer(record$model_index),
    observation = as.integer(record$observation),
    original_fit_sha256 = record$original_fit_sha256,
    integrated_loo_sha256 = record$integrated_loo_sha256,
    iter_warmup = as.integer(config$iter_warmup),
    iter_sampling = as.integer(config$iter_sampling),
    adapt_delta_floor = as.numeric(config$adapt_delta_floor),
    max_treedepth_floor = as.integer(config$max_treedepth_floor),
    fixed_metric_sampling = fixed_metric_sampling,
    metric_source_sha256 = metric_source_sha256,
    fixed_step_size = fixed_step_size
  )

  signature_sha256 <- digest::digest(signature, algo = "sha256")
  existing <- if (file.exists(output_file)) {
    tryCatch(
      read_update_2026_absolute_rescor_exact_fit_file(
        output_file,
        config$family
      ),
      error = function(e) NULL
    )
  } else {
    NULL
  }

  if (
    !is.null(existing) &&
      identical(existing$signature_sha256, signature_sha256)
  ) {
    return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
  }

  integrated_result <- qs::qread(record$integrated_loo_path)
  input <- integrated_result$input
  if (
    !identical(integrated_result$family, config$family) ||
      input$specification$model_index != record$model_index ||
      !identical(input$specification$outcome, record$outcome)
  ) {
    stop("The absolute residual-correlation exact record is misaligned.",
         call. = FALSE)
  }

  training_data <-
    make_update_2026_absolute_rescor_leave_one_study_out_data(
      input$stan_data,
      record$observation
    )
  specification <- input$specification
  specification$adapt_delta <- max(
    as.numeric(specification$adapt_delta),
    config$adapt_delta_floor
  )
  specification$max_treedepth <- max(
    as.integer(specification$max_treedepth),
    config$max_treedepth_floor
  )
  sample_arguments <- list(
    data = training_data,
    chains = config$chains,
    parallel_chains = config$parallel_chains,
    iter_warmup = config$iter_warmup,
    iter_sampling = config$iter_sampling,
    adapt_delta = specification$adapt_delta,
    max_treedepth = specification$max_treedepth,
    seed = as.integer(config$seed + record$case_id),
    refresh = 100,
    output_dir = cmdstan_dir
  )

  if (fixed_metric_sampling) {
    if (
      length(metric_source_path) != 1L || is.na(metric_source_path) ||
        !file.exists(metric_source_path) ||
        length(metric_source_sha256) != 1L ||
        is.na(metric_source_sha256) ||
        !identical(
          digest::digest(
            file = metric_source_path,
            algo = "sha256",
            serialize = FALSE
          ),
          metric_source_sha256
        ) ||
        length(fixed_step_size) != 1L || !is.finite(fixed_step_size) ||
        fixed_step_size <= 0
    ) {
      stop("The exact-refit fixed-metric source is invalid.",
           call. = FALSE)
    }
    metric_source <- read_update_2026_absolute_rescor_exact_fit_file(
      metric_source_path,
      config$family
    )
    inverse_metrics <-
      metric_source$fitted_candidate$fit$inv_metric(matrix = FALSE)
    if (
      length(inverse_metrics) != config$chains ||
        any(vapply(inverse_metrics, function(metric) {
          !is.numeric(metric) || !length(metric) ||
            any(!is.finite(metric)) || any(metric <= 0)
        }, logical(1L)))
    ) {
      stop("The exact-refit source has invalid per-chain metrics.",
           call. = FALSE)
    }
    metric_dir <- file.path(case_dir, "fixed_metric")
    dir.create(metric_dir, recursive = TRUE, showWarnings = FALSE)
    metric_files <- vapply(
      seq_along(inverse_metrics),
      function(chain) {
        path <- file.path(metric_dir, sprintf("chain_%02d.json", chain))
        cmdstanr::write_stan_json(
          data = list(inv_metric = inverse_metrics[[chain]]),
          file = path
        )
        normalizePath(path, winslash = "/", mustWork = TRUE)
      },
      character(1L)
    )
    sample_arguments$adapt_delta <- NULL
    sample_arguments$adapt_engaged <- FALSE
    sample_arguments$step_size <- as.numeric(fixed_step_size)
    sample_arguments$metric <- "diag_e"
    sample_arguments$metric_file <- metric_files
    sample_arguments$init <- metric_source$fitted_candidate$fit
    specification$fixed_metric_sampling <- TRUE
    specification$adapt_engaged <- FALSE
    specification$step_size <- as.numeric(fixed_step_size)
  }

  start_time <- proc.time()[["elapsed"]]
  fit <- do.call(model$sample, sample_arguments)
  fitted_candidate <- list(
    family = config$family,
    archive_stage = stage,
    outcome = record$outcome,
    model_index = as.integer(record$model_index),
    model_name = record$model_name,
    specification = specification,
    grid = input$grid,
    output_dir = normalizePath(
      cmdstan_dir,
      winslash = "/",
      mustWork = TRUE
    ),
    fit = fit
  )

  refit <- list(
    case_id = as.integer(record$case_id),
    family = config$family,
    outcome = record$outcome,
    model_index = as.integer(record$model_index),
    model_name = record$model_name,
    observation = as.integer(record$observation),
    pareto_k = as.numeric(record$pareto_k),
    fitted_candidate = fitted_candidate,
    input = input,
    integrated_result = integrated_result,
    signature = signature,
    signature_sha256 = signature_sha256,
    sampling_control = list(
      fixed_metric_sampling = fixed_metric_sampling,
      adapt_engaged = !fixed_metric_sampling,
      step_size = if (fixed_metric_sampling) {
        as.numeric(fixed_step_size)
      } else {
        NA_real_
      },
      metric_source_sha256 = if (fixed_metric_sampling) {
        metric_source_sha256
      } else {
        NA_character_
      }
    ),
    refit_seconds = proc.time()[["elapsed"]] - start_time
  )

  write_atomic_qs(refit, output_file)
}

make_update_2026_absolute_rescor_exact_fit_manifest <- function(
    paths,
    family,
    expected_cases = 89L,
    expected_case_ids = seq_len(expected_cases)
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  if (
    length(paths) != expected_cases || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The absolute residual-correlation exact-fit set is incomplete.",
         call. = FALSE)
  }

  manifest <- purrr::map_dfr(paths, function(path) {
    refit <- read_update_2026_absolute_rescor_exact_fit_file(path, family)
    tibble::tibble(
      case_id = as.integer(refit$case_id),
      family = refit$family,
      outcome = refit$outcome,
      model_index = as.integer(refit$model_index),
      model_name = refit$model_name,
      observation = as.integer(refit$observation),
      pareto_k = as.numeric(refit$pareto_k),
      exact_fit_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      bytes = as.numeric(file.info(path)$size),
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(case_id)

  if (
    nrow(manifest) != expected_cases ||
      !identical(manifest$case_id, as.integer(expected_case_ids)) ||
      any(manifest$family != family) ||
      anyDuplicated(paste(
        manifest$outcome,
        manifest$model_index,
        manifest$observation,
        sep = "::"
      )) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The absolute residual-correlation exact manifest is invalid.",
         call. = FALSE)
  }

  manifest
}

diagnose_update_2026_absolute_rescor_exact_fit_file <- function(
    path,
    family
) {
  refit <- read_update_2026_absolute_rescor_exact_fit_file(path, family)
  summarise_eiv_exact_loo_refit(refit)
}

write_update_2026_absolute_rescor_exact_audit <- function(
    diagnostic_audit,
    manifest,
    output_dir,
    expected_cases = 89L
) {
  if (
    diagnostic_audit$exact_refits != as.integer(expected_cases) ||
      nrow(manifest) != as.integer(expected_cases) ||
      nrow(diagnostic_audit$diagnostic_summary) !=
        as.integer(expected_cases) ||
      any(!file.exists(manifest$exact_fit_path)) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The absolute residual-correlation exact audit is incomplete.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    fit_manifest = file.path(output_dir, "fit_manifest.csv"),
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv")
  )
  readr::write_csv(manifest, paths[["fit_manifest"]], na = "")
  readr::write_csv(
    diagnostic_audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  unname(paths)
}

update_2026_absolute_rescor_exact_remedy_spec <- function(family) {
  switch(
    family,
    total_rescor = list(
      initial_cases = 89L,
      remedy_cases = 3L,
      keys = c(
        "73::function::8::5",
        "74::function::8::10",
        "83::function::20::13"
      ),
      divergences = c(2L, 1L, 2L),
      treedepth = c(0L, 0L, 0L),
      max_treedepth = 15L
    ),
    supplement_rescor = list(
      initial_cases = 139L,
      remedy_cases = 26L,
      keys = c(
        "30::hypertrophy::11::10",
        "47::hypertrophy::23::10",
        "50::hypertrophy::26::10",
        "53::strength::1::43",
        "95::function::2::11",
        "96::function::2::15",
        "98::function::4::15",
        "99::function::5::5",
        "100::function::5::11",
        "106::function::8::15",
        "107::function::8::20",
        "108::function::9::11",
        "110::function::11::11",
        "111::function::11::15",
        "112::function::12::11",
        "119::function::14::20",
        "122::function::18::15",
        "124::function::20::11",
        "125::function::20::15",
        "127::function::21::15",
        "130::function::24::5",
        "132::function::24::15",
        "134::function::26::5",
        "135::function::26::11",
        "138::function::26::15",
        "139::function::26::20"
      ),
      divergences = c(
        1L, 1L, 1L, 0L, 2L, 1L, 1L, 2L, 1L, 2L, 1L, 1L, 1L,
        3L, 2L, 1L, 1L, 1L, 1L, 1L, 1L, 3L, 1L, 2L, 1L, 2L
      ),
      treedepth = c(rep(0L, 3L), 1L, rep(0L, 22L)),
      max_treedepth = 16L
    ),
    stop(
      "The exact-remedy residual-correlation family is unsupported.",
      call. = FALSE
    )
  )
}

make_update_2026_absolute_rescor_exact_remedy_config <- function(
    exact_config,
    adapt_delta = 0.9995,
    max_treedepth = 15L,
    seed_offset = 1000L
) {
  remedy_spec <- update_2026_absolute_rescor_exact_remedy_spec(
    exact_config$family
  )
  config <- exact_config
  config$adapt_delta_floor <- max(
    as.numeric(exact_config$adapt_delta_floor),
    as.numeric(adapt_delta)
  )
  config$max_treedepth_floor <- max(
    as.integer(exact_config$max_treedepth_floor),
    as.integer(max_treedepth)
  )
  config$seed <- as.integer(exact_config$seed + seed_offset)

  if (
    !config$family %in% c("total_rescor", "supplement_rescor") ||
      config$chains != 4L || config$parallel_chains != 4L ||
      config$iter_warmup != 2000L || config$iter_sampling != 6000L ||
      config$adapt_delta_floor != 0.9995 ||
      config$max_treedepth_floor != remedy_spec$max_treedepth
  ) {
    stop(
      "The absolute residual-correlation exact-remedy config is invalid.",
      call. = FALSE
    )
  }

  config
}

select_update_2026_absolute_rescor_exact_remedy_records <- function(
    records,
    exact_audit,
    family = "total_rescor"
) {
  remedy_spec <- update_2026_absolute_rescor_exact_remedy_spec(
    family
  )
  failed <- exact_audit$diagnostic_summary |>
    dplyr::filter(!.data$diagnostic_pass) |>
    dplyr::arrange(case_id)
  failed_keys <- paste(
    failed$case_id,
    failed$outcome,
    failed$model_index,
    failed$observation,
    sep = "::"
  )
  expected_keys <- remedy_spec$keys

  if (
    exact_audit$exact_refits != remedy_spec$initial_cases ||
      exact_audit$exact_refits_requiring_remediation !=
        remedy_spec$remedy_cases ||
      nrow(failed) != remedy_spec$remedy_cases ||
      !identical(failed_keys, expected_keys) ||
      !identical(
        as.integer(failed$divergent_transitions),
        remedy_spec$divergences
      ) ||
      !identical(
        as.integer(failed$maximum_treedepth_transitions),
        remedy_spec$treedepth
      ) ||
      !all(failed$convergence_pass)
  ) {
    stop(
      "The absolute residual-correlation exact remedies changed.",
      call. = FALSE
    )
  }

  selected <- purrr::keep(records, function(record) {
    paste(
      as.integer(record$case_id),
      record$outcome,
      as.integer(record$model_index),
      as.integer(record$observation),
      sep = "::"
    ) %in% expected_keys
  })

  selected_keys <- purrr::map_chr(selected, function(record) {
    paste(
      as.integer(record$case_id),
      record$outcome,
      as.integer(record$model_index),
      as.integer(record$observation),
      sep = "::"
    )
  })

  if (
    length(selected) != remedy_spec$remedy_cases ||
      !identical(selected_keys, expected_keys)
  ) {
    stop(
      "Could not uniquely select the exact-remedy records.",
      call. = FALSE
    )
  }

  names(selected) <- sprintf(
    "case_%03d_%s_model_%02d_observation_%03d",
    purrr::map_int(selected, ~ as.integer(.x$case_id)),
    purrr::map_chr(selected, ~ .x$outcome),
    purrr::map_int(selected, ~ as.integer(.x$model_index)),
    purrr::map_int(selected, ~ as.integer(.x$observation))
  )
  selected
}

validate_update_2026_absolute_rescor_exact_remedy_inputs <- function(
    records,
    config,
    initial_manifest
) {
  remedy_spec <- update_2026_absolute_rescor_exact_remedy_spec(
    config$family
  )

  if (
    !is.list(records) || length(records) != remedy_spec$remedy_cases ||
      !is.data.frame(initial_manifest) ||
      nrow(initial_manifest) != remedy_spec$initial_cases
  ) {
    stop("The exact-remedy record or initial-refit count is invalid.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    initial_row <- initial_manifest |>
      dplyr::filter(.data$case_id == as.integer(record$case_id))
    if (nrow(initial_row) != 1L) {
      stop("An initial exact refit is missing from the remedy preflight.",
           call. = FALSE)
    }
    integrated <- qs::qread(record$integrated_loo_path)
    initial_refit <- read_update_2026_absolute_rescor_exact_fit_file(
      initial_row$exact_fit_path[[1L]],
      config$family
    )
    observation <- as.integer(record$observation)
    observed_k <- as.numeric(
      loo::pareto_k_values(integrated$loo)[[observation]]
    )
    training_data <-
      make_update_2026_absolute_rescor_leave_one_study_out_data(
        integrated$input$stan_data,
        observation
      )
    initial_hash_matches <- identical(
      digest::digest(
        file = initial_row$exact_fit_path[[1L]],
        algo = "sha256",
        serialize = FALSE
      ),
      initial_row$sha256[[1L]]
    )
    effective_adapt_delta <- max(
      as.numeric(integrated$input$specification$adapt_delta),
      as.numeric(config$adapt_delta_floor)
    )
    effective_max_treedepth <- max(
      as.integer(integrated$input$specification$max_treedepth),
      as.integer(config$max_treedepth_floor)
    )
    valid <-
      identical(integrated$family, config$family) &&
      identical(initial_refit$family, config$family) &&
      initial_refit$case_id == as.integer(record$case_id) &&
      identical(initial_refit$outcome, record$outcome) &&
      initial_refit$model_index == as.integer(record$model_index) &&
      initial_refit$observation == observation &&
      is.finite(observed_k) && observed_k > 0.7 &&
      length(training_data$body_mass_z) == training_data$N &&
      all(is.finite(training_data$body_mass_z)) &&
      file.exists(initial_row$exact_fit_path[[1L]]) &&
      initial_hash_matches
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = observation,
      remedy = if (config$max_treedepth_floor > 15L) {
        "adapt_delta_0.9995_treedepth_16_after_exact_refit"
      } else {
        "adapt_delta_0.9995_after_exact_refit"
      },
      adapt_delta = effective_adapt_delta,
      max_treedepth = effective_max_treedepth,
      iter_warmup = as.integer(config$iter_warmup),
      iter_sampling = as.integer(config$iter_sampling),
      chains = as.integer(config$chains),
      parallel_chains = as.integer(config$parallel_chains),
      pareto_k = observed_k,
      initial_exact_fit_exists =
        file.exists(initial_row$exact_fit_path[[1L]]),
      initial_exact_hash_matches = initial_hash_matches,
      integrated_loo_exists = file.exists(record$integrated_loo_path),
      body_mass_data_valid =
        length(training_data$body_mass_z) == training_data$N &&
        all(is.finite(training_data$body_mass_z)),
      valid = valid
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    checks$case_id,
    checks$outcome,
    checks$model_index,
    checks$observation,
    sep = "::"
  )

  if (
    nrow(checks) != remedy_spec$remedy_cases ||
      !identical(observed_keys, remedy_spec$keys) ||
      any(checks$adapt_delta != 0.9995) ||
      any(checks$max_treedepth != remedy_spec$max_treedepth) ||
      any(checks$iter_warmup != 2000L) ||
      any(checks$iter_sampling != 6000L) ||
      any(checks$chains != 4L) ||
      any(checks$parallel_chains != 4L) ||
      !all(checks$valid)
  ) {
    stop(
      "The absolute residual-correlation exact-remedy preflight failed.",
      call. = FALSE
    )
  }

  checks
}

write_update_2026_absolute_rescor_exact_remedy_preflight <- function(
    checks,
    output_file,
    expected_cases = 3L
) {
  if (nrow(checks) != as.integer(expected_cases) || !all(checks$valid)) {
    stop("Cannot write an invalid exact-remedy preflight.", call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

audit_update_2026_absolute_rescor_exact_remedy_diagnostics <- function(
    diagnostics,
    family = "total_rescor"
) {
  remedy_spec <- update_2026_absolute_rescor_exact_remedy_spec(family)
  summary <- dplyr::bind_rows(diagnostics) |>
    dplyr::arrange(case_id)
  keys <- paste(
    summary$case_id,
    summary$outcome,
    summary$model_index,
    summary$observation,
    sep = "::"
  )

  if (
    nrow(summary) != remedy_spec$remedy_cases ||
      !identical(keys, remedy_spec$keys) ||
      anyDuplicated(keys)
  ) {
    stop("The exact-remedy diagnostic set is incomplete.", call. = FALSE)
  }

  list(
    diagnostic_summary = summary,
    exact_refits = nrow(summary),
    exact_refits_passing = sum(summary$diagnostic_pass),
    exact_refits_requiring_remediation = sum(!summary$diagnostic_pass),
    all_exact_refit_diagnostics_pass = all(summary$diagnostic_pass)
  )
}

write_update_2026_absolute_rescor_exact_remedy_audit <- function(
    diagnostic_audit,
    manifest,
    output_dir,
    expected_cases = 3L
) {
  if (
    diagnostic_audit$exact_refits != as.integer(expected_cases) ||
      nrow(manifest) != as.integer(expected_cases) ||
      nrow(diagnostic_audit$diagnostic_summary) !=
        as.integer(expected_cases) ||
      any(!file.exists(manifest$exact_fit_path)) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The exact-remedy audit is incomplete.", call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    fit_manifest = file.path(output_dir, "fit_manifest.csv"),
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv")
  )
  readr::write_csv(manifest, paths[["fit_manifest"]], na = "")
  readr::write_csv(
    diagnostic_audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  unname(paths)
}

update_2026_absolute_rescor_exact_second_remedy_spec <- function(family) {
  switch(
    family,
    total_rescor = list(
      previous_cases = 3L,
      remedy_cases = 1L,
      keys = "74::function::8::10",
      divergences = 1L,
      treedepth = 0L,
      max_treedepth = 16L
    ),
    supplement_rescor = list(
      previous_cases = 26L,
      remedy_cases = 9L,
      keys = c(
        "30::hypertrophy::11::10",
        "98::function::4::15",
        "100::function::5::11",
        "106::function::8::15",
        "111::function::11::15",
        "124::function::20::11",
        "125::function::20::15",
        "132::function::24::15",
        "134::function::26::5"
      ),
      divergences = c(1L, 3L, 2L, 1L, 1L, 1L, 3L, 2L, 1L),
      treedepth = rep(0L, 9L),
      max_treedepth = 17L
    ),
    stop(
      "The second exact-remedy residual-correlation family is unsupported.",
      call. = FALSE
    )
  )
}

make_update_2026_absolute_rescor_exact_second_remedy_config <- function(
    remedy_config,
    iter_warmup = 3000L,
    iter_sampling = 8000L,
    adapt_delta = 0.9999,
    max_treedepth = 16L,
    seed_offset = 1000L
) {
  remedy_spec <- update_2026_absolute_rescor_exact_second_remedy_spec(
    remedy_config$family
  )
  config <- remedy_config
  config$iter_warmup <- as.integer(iter_warmup)
  config$iter_sampling <- as.integer(iter_sampling)
  config$adapt_delta_floor <- as.numeric(adapt_delta)
  config$max_treedepth_floor <- as.integer(max_treedepth)
  config$seed <- as.integer(remedy_config$seed + seed_offset)

  if (
    !config$family %in% c("total_rescor", "supplement_rescor") ||
      config$chains != 4L || config$parallel_chains != 4L ||
      config$iter_warmup != 3000L || config$iter_sampling != 8000L ||
      config$adapt_delta_floor != 0.9999 ||
      config$max_treedepth_floor != remedy_spec$max_treedepth ||
      config$iter_warmup <= remedy_config$iter_warmup ||
      config$iter_sampling <= remedy_config$iter_sampling ||
      config$adapt_delta_floor <= remedy_config$adapt_delta_floor ||
      config$max_treedepth_floor <= remedy_config$max_treedepth_floor
  ) {
    stop(
      "The absolute residual-correlation second exact-remedy config is invalid.",
      call. = FALSE
    )
  }

  config
}

select_update_2026_absolute_rescor_exact_second_remedy_records <- function(
    records,
    remedy_audit,
    family = "total_rescor"
) {
  remedy_spec <- update_2026_absolute_rescor_exact_second_remedy_spec(family)
  failed <- remedy_audit$diagnostic_summary |>
    dplyr::filter(!.data$diagnostic_pass) |>
    dplyr::arrange(case_id)
  failed_keys <- paste(
    failed$case_id,
    failed$outcome,
    failed$model_index,
    failed$observation,
    sep = "::"
  )

  if (
    remedy_audit$exact_refits != remedy_spec$previous_cases ||
      remedy_audit$exact_refits_requiring_remediation !=
        remedy_spec$remedy_cases ||
      nrow(failed) != remedy_spec$remedy_cases ||
      !identical(failed_keys, remedy_spec$keys) ||
      !identical(
        as.integer(failed$divergent_transitions),
        remedy_spec$divergences
      ) ||
      !identical(
        as.integer(failed$maximum_treedepth_transitions),
        remedy_spec$treedepth
      ) ||
      !all(failed$convergence_pass)
  ) {
    stop(
      "The second absolute residual-correlation exact remedy changed.",
      call. = FALSE
    )
  }

  selected <- purrr::keep(records, function(record) {
    paste(
      as.integer(record$case_id),
      record$outcome,
      as.integer(record$model_index),
      as.integer(record$observation),
      sep = "::"
    ) %in% remedy_spec$keys
  })

  selected_keys <- purrr::map_chr(selected, function(record) {
    paste(
      as.integer(record$case_id),
      record$outcome,
      as.integer(record$model_index),
      as.integer(record$observation),
      sep = "::"
    )
  })

  if (
    length(selected) != remedy_spec$remedy_cases ||
      !identical(selected_keys, remedy_spec$keys)
  ) {
    stop("Could not uniquely select the second exact-remedy records.",
         call. = FALSE)
  }

  names(selected) <- sprintf(
    "case_%03d_%s_model_%02d_observation_%03d",
    purrr::map_int(selected, ~ as.integer(.x$case_id)),
    purrr::map_chr(selected, ~ .x$outcome),
    purrr::map_int(selected, ~ as.integer(.x$model_index)),
    purrr::map_int(selected, ~ as.integer(.x$observation))
  )
  selected
}

validate_update_2026_absolute_rescor_exact_second_remedy_inputs <- function(
    records,
    config,
    previous_manifest
) {
  remedy_spec <- update_2026_absolute_rescor_exact_second_remedy_spec(
    config$family
  )

  if (
    !is.list(records) || length(records) != remedy_spec$remedy_cases ||
      !is.data.frame(previous_manifest) ||
      nrow(previous_manifest) != remedy_spec$previous_cases
  ) {
    stop("The second-remedy record or prior-remedy count is invalid.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    previous_row <- previous_manifest |>
      dplyr::filter(.data$case_id == as.integer(record$case_id))
    if (nrow(previous_row) != 1L) {
      stop("A prior exact-remedy fit is missing.", call. = FALSE)
    }
    previous_refit <- read_update_2026_absolute_rescor_exact_fit_file(
      previous_row$exact_fit_path[[1L]],
      config$family
    )
    integrated <- qs::qread(record$integrated_loo_path)
    observation <- as.integer(record$observation)
    observed_k <- as.numeric(
      loo::pareto_k_values(integrated$loo)[[observation]]
    )
    training_data <-
      make_update_2026_absolute_rescor_leave_one_study_out_data(
        integrated$input$stan_data,
        observation
      )
    previous_hash_matches <- identical(
      digest::digest(
        file = previous_row$exact_fit_path[[1L]],
        algo = "sha256",
        serialize = FALSE
      ),
      previous_row$sha256[[1L]]
    )
    effective_adapt_delta <- max(
      as.numeric(integrated$input$specification$adapt_delta),
      as.numeric(config$adapt_delta_floor)
    )
    effective_max_treedepth <- max(
      as.integer(integrated$input$specification$max_treedepth),
      as.integer(config$max_treedepth_floor)
    )
    record_key <- paste(
      as.integer(record$case_id),
      record$outcome,
      as.integer(record$model_index),
      observation,
      sep = "::"
    )
    valid <-
      record_key %in% remedy_spec$keys &&
      identical(integrated$family, config$family) &&
      identical(previous_refit$family, config$family) &&
      previous_refit$case_id == as.integer(record$case_id) &&
      identical(previous_refit$outcome, record$outcome) &&
      previous_refit$model_index == as.integer(record$model_index) &&
      previous_refit$observation == observation &&
      is.finite(observed_k) && observed_k > 0.7 &&
      length(training_data$body_mass_z) == training_data$N &&
      all(is.finite(training_data$body_mass_z)) &&
      file.exists(previous_row$exact_fit_path[[1L]]) &&
      previous_hash_matches
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = observation,
      remedy = "extended_adaptation_after_exact_remedy_1",
      adapt_delta = effective_adapt_delta,
      max_treedepth = effective_max_treedepth,
      iter_warmup = as.integer(config$iter_warmup),
      iter_sampling = as.integer(config$iter_sampling),
      chains = as.integer(config$chains),
      parallel_chains = as.integer(config$parallel_chains),
      pareto_k = observed_k,
      previous_fit_exists = file.exists(previous_row$exact_fit_path[[1L]]),
      previous_hash_matches = previous_hash_matches,
      integrated_loo_exists = file.exists(record$integrated_loo_path),
      body_mass_data_valid =
        length(training_data$body_mass_z) == training_data$N &&
        all(is.finite(training_data$body_mass_z)),
      valid = valid
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    checks$case_id,
    checks$outcome,
    checks$model_index,
    checks$observation,
    sep = "::"
  )

  if (
    nrow(checks) != remedy_spec$remedy_cases ||
      !identical(observed_keys, remedy_spec$keys) ||
      any(checks$adapt_delta != 0.9999) ||
      any(checks$max_treedepth != remedy_spec$max_treedepth) ||
      any(checks$iter_warmup != 3000L) ||
      any(checks$iter_sampling != 8000L) ||
      any(checks$chains != 4L) ||
      any(checks$parallel_chains != 4L) ||
      !all(checks$valid)
  ) {
    stop("The second exact-remedy preflight failed.", call. = FALSE)
  }

  checks
}

