validate_update_2026_absolute_rescor_exact_third_remedy_inputs <- function(
    records,
    config,
    previous_manifest,
    step_size = 0.002
) {
  remedy_spec <- update_2026_absolute_rescor_exact_third_remedy_spec(
    config$family
  )

  if (
    !is.list(records) || length(records) != remedy_spec$remedy_cases ||
      !is.data.frame(previous_manifest) ||
      nrow(previous_manifest) != remedy_spec$previous_cases ||
      !is.finite(step_size) || step_size <= 0
  ) {
    stop("The fixed-metric exact-refit inputs are incomplete.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    previous_row <- previous_manifest |>
      dplyr::filter(.data$case_id == as.integer(record$case_id))
    if (nrow(previous_row) != 1L) {
      stop("A second-remedy metric source is missing.", call. = FALSE)
    }
    previous_refit <- read_update_2026_absolute_rescor_exact_fit_file(
      previous_row$exact_fit_path[[1L]],
      config$family
    )
    inverse_metrics <-
      previous_refit$fitted_candidate$fit$inv_metric(matrix = FALSE)
    metrics_valid <-
      length(inverse_metrics) == config$chains &&
      all(vapply(inverse_metrics, function(metric) {
        is.numeric(metric) && length(metric) > 0L &&
          all(is.finite(metric)) && all(metric > 0)
      }, logical(1L)))
    previous_hash_matches <- identical(
      digest::digest(
        file = previous_row$exact_fit_path[[1L]],
        algo = "sha256",
        serialize = FALSE
      ),
      previous_row$sha256[[1L]]
    )
    integrated <- qs::qread(record$integrated_loo_path)
    observation <- as.integer(record$observation)
    training_data <-
      make_update_2026_absolute_rescor_leave_one_study_out_data(
        integrated$input$stan_data,
        observation
      )
    record_key <- paste(
      as.integer(record$case_id),
      record$outcome,
      as.integer(record$model_index),
      observation,
      sep = "::"
    )
    valid <-
      record_key %in% remedy_spec$keys &&
      identical(integrated$family, config$family) &&
      identical(previous_refit$family, config$family) &&
      previous_refit$case_id == as.integer(record$case_id) &&
      identical(previous_refit$outcome, record$outcome) &&
      previous_refit$model_index == as.integer(record$model_index) &&
      previous_refit$observation == observation &&
      file.exists(previous_row$exact_fit_path[[1L]]) &&
      previous_hash_matches && metrics_valid &&
      length(training_data$body_mass_z) == training_data$N &&
      all(is.finite(training_data$body_mass_z))
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = observation,
      remedy = "fixed_metric_small_step_sampling",
      adapt_engaged = FALSE,
      step_size = as.numeric(step_size),
      max_treedepth = as.integer(config$max_treedepth_floor),
      iter_warmup = as.integer(config$iter_warmup),
      iter_sampling = as.integer(config$iter_sampling),
      chains = as.integer(config$chains),
      parallel_chains = as.integer(config$parallel_chains),
      metric_source_path = previous_row$exact_fit_path[[1L]],
      metric_source_sha256 = previous_row$sha256[[1L]],
      previous_fit_exists = file.exists(previous_row$exact_fit_path[[1L]]),
      previous_hash_matches = previous_hash_matches,
      per_chain_metrics_valid = metrics_valid,
      body_mass_data_valid =
        length(training_data$body_mass_z) == training_data$N &&
        all(is.finite(training_data$body_mass_z)),
      valid = valid
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    checks$case_id,
    checks$outcome,
    checks$model_index,
    checks$observation,
    sep = "::"
  )

  if (
    nrow(checks) != remedy_spec$remedy_cases ||
      !identical(observed_keys, remedy_spec$keys) ||
      any(checks$adapt_engaged) ||
      any(checks$step_size != 0.002) ||
      any(checks$max_treedepth != remedy_spec$max_treedepth) ||
      any(checks$iter_warmup != 1000L) ||
      any(checks$iter_sampling != 8000L) ||
      any(checks$chains != 4L) ||
      any(checks$parallel_chains != 4L) ||
      !all(checks$valid)
  ) {
    stop("The fixed-metric exact-refit preflight failed.", call. = FALSE)
  }

  checks
}

audit_update_2026_absolute_rescor_exact_third_remedy_diagnostic <- function(
    diagnostics,
    family = "total_rescor"
) {
  remedy_spec <- update_2026_absolute_rescor_exact_third_remedy_spec(family)
  summary <- dplyr::bind_rows(diagnostics) |>
    dplyr::arrange(case_id)
  keys <- paste(
    summary$case_id,
    summary$outcome,
    summary$model_index,
    summary$observation,
    sep = "::"
  )

  if (
    nrow(summary) != remedy_spec$remedy_cases ||
      !identical(keys, remedy_spec$keys) ||
      anyDuplicated(keys)
  ) {
    stop("The third exact-remedy diagnostic is incomplete.", call. = FALSE)
  }

  list(
    diagnostic_summary = summary,
    exact_refits = nrow(summary),
    exact_refits_passing = sum(summary$diagnostic_pass),
    exact_refits_requiring_remediation = sum(!summary$diagnostic_pass),
    all_exact_refit_diagnostics_pass = all(summary$diagnostic_pass)
  )
}

update_2026_absolute_rescor_final_exact_spec <- function(family) {
  switch(
    family,
    total_rescor = list(
      exact_cases = 89L,
      stage_cases = c(initial = 89L, remedy_1 = 3L,
                      remedy_2 = 1L, remedy_3 = 1L),
      stage_failures = c(initial = 3L, remedy_1 = 1L,
                         remedy_2 = 1L, remedy_3 = 0L),
      accepted_stage_counts = c(initial = 86L, remedy_1 = 2L,
                                remedy_2 = 0L, remedy_3 = 1L)
    ),
    supplement_rescor = list(
      exact_cases = 139L,
      stage_cases = c(initial = 139L, remedy_1 = 26L,
                      remedy_2 = 9L, remedy_3 = 2L),
      stage_failures = c(initial = 26L, remedy_1 = 9L,
                         remedy_2 = 2L, remedy_3 = 0L),
      accepted_stage_counts = c(initial = 113L, remedy_1 = 17L,
                                remedy_2 = 7L, remedy_3 = 2L)
    ),
    stop(
      "The final exact residual-correlation family is unsupported.",
      call. = FALSE
    )
  )
}

make_update_2026_absolute_rescor_final_exact_audit <- function(
    initial_manifest,
    remedy_manifest,
    second_remedy_manifest,
    third_remedy_manifest,
    initial_audit,
    remedy_audit,
    second_remedy_audit,
    third_remedy_audit,
    family = "total_rescor"
) {
  final_spec <- update_2026_absolute_rescor_final_exact_spec(family)
  add_stage <- function(manifest, stage, expected_cases) {
    if (
      !is.data.frame(manifest) || nrow(manifest) != expected_cases ||
        any(manifest$family != family) ||
        any(!file.exists(manifest$exact_fit_path)) ||
        any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
    ) {
      stop("An exact-refit stage manifest is invalid.", call. = FALSE)
    }
    manifest |>
      dplyr::mutate(stage = stage)
  }

  initial <- add_stage(
    initial_manifest,
    "initial",
    final_spec$stage_cases[["initial"]]
  )
  remedy_1 <- add_stage(
    remedy_manifest,
    "remedy_1",
    final_spec$stage_cases[["remedy_1"]]
  )
  remedy_2 <- add_stage(
    second_remedy_manifest,
    "remedy_2",
    final_spec$stage_cases[["remedy_2"]]
  )
  remedy_3 <- add_stage(
    third_remedy_manifest,
    "remedy_3",
    final_spec$stage_cases[["remedy_3"]]
  )
  accepted_manifest <- initial |>
    dplyr::filter(!case_id %in% remedy_1$case_id) |>
    dplyr::bind_rows(remedy_1) |>
    dplyr::filter(!case_id %in% remedy_2$case_id) |>
    dplyr::bind_rows(remedy_2) |>
    dplyr::filter(!case_id %in% remedy_3$case_id) |>
    dplyr::bind_rows(remedy_3) |>
    dplyr::arrange(case_id)

  overlay_diagnostics <- function(existing, replacement) {
    existing |>
      dplyr::filter(!case_id %in% replacement$case_id) |>
      dplyr::bind_rows(replacement)
  }
  diagnostic_summary <- initial_audit$diagnostic_summary |>
    overlay_diagnostics(remedy_audit$diagnostic_summary) |>
    overlay_diagnostics(second_remedy_audit$diagnostic_summary) |>
    overlay_diagnostics(third_remedy_audit$diagnostic_summary) |>
    dplyr::left_join(
      accepted_manifest |>
        dplyr::select(case_id, stage),
      by = "case_id",
      relationship = "one-to-one"
    ) |>
    dplyr::arrange(case_id)

  stage_counts <- table(factor(
    accepted_manifest$stage,
    levels = names(final_spec$accepted_stage_counts)
  ))
  accepted_keys <- paste(
    accepted_manifest$outcome,
    accepted_manifest$model_index,
    accepted_manifest$observation,
    sep = "::"
  )
  diagnostic_keys <- paste(
    diagnostic_summary$outcome,
    diagnostic_summary$model_index,
    diagnostic_summary$observation,
    sep = "::"
  )

  if (
    initial_audit$exact_refits != final_spec$stage_cases[["initial"]] ||
      initial_audit$exact_refits_requiring_remediation !=
        final_spec$stage_failures[["initial"]] ||
      remedy_audit$exact_refits != final_spec$stage_cases[["remedy_1"]] ||
      remedy_audit$exact_refits_requiring_remediation !=
        final_spec$stage_failures[["remedy_1"]] ||
      second_remedy_audit$exact_refits !=
        final_spec$stage_cases[["remedy_2"]] ||
      second_remedy_audit$exact_refits_requiring_remediation !=
        final_spec$stage_failures[["remedy_2"]] ||
      third_remedy_audit$exact_refits !=
        final_spec$stage_cases[["remedy_3"]] ||
      third_remedy_audit$exact_refits_requiring_remediation !=
        final_spec$stage_failures[["remedy_3"]] ||
      !isTRUE(third_remedy_audit$all_exact_refit_diagnostics_pass) ||
      nrow(accepted_manifest) != final_spec$exact_cases ||
      !identical(
        accepted_manifest$case_id,
        seq_len(final_spec$exact_cases)
      ) ||
      anyDuplicated(accepted_keys) ||
      !identical(
        as.integer(stage_counts),
        unname(final_spec$accepted_stage_counts)
      ) ||
      any(!file.exists(accepted_manifest$exact_fit_path)) ||
      any(accepted_manifest$bytes <= 0) ||
      any(nchar(accepted_manifest$sha256) != 64L) ||
      nrow(diagnostic_summary) != final_spec$exact_cases ||
      !identical(
        diagnostic_summary$case_id,
        seq_len(final_spec$exact_cases)
      ) ||
      anyDuplicated(diagnostic_keys) ||
      !identical(accepted_keys, diagnostic_keys) ||
      !all(diagnostic_summary$diagnostic_pass)
  ) {
    stop(
      "The residual-correlation final exact audit is invalid.",
      call. = FALSE
    )
  }

  list(
    family = family,
    diagnostic_summary = diagnostic_summary,
    accepted_exact_fit_manifest = accepted_manifest,
    exact_refits = final_spec$exact_cases,
    exact_refits_passing = final_spec$exact_cases,
    exact_refits_requiring_remediation = 0L,
    all_exact_refit_diagnostics_pass = TRUE
  )
}

write_update_2026_absolute_rescor_final_exact_audit <- function(
    audit,
    output_dir
) {
  final_spec <- update_2026_absolute_rescor_final_exact_spec(audit$family)
  if (
    !audit$family %in% c("total_rescor", "supplement_rescor") ||
      audit$exact_refits != final_spec$exact_cases ||
      nrow(audit$diagnostic_summary) != final_spec$exact_cases ||
      nrow(audit$accepted_exact_fit_manifest) != final_spec$exact_cases ||
      !isTRUE(audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("Cannot write an incomplete final exact audit.", call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    accepted_exact_fit_manifest = file.path(
      output_dir,
      "accepted_exact_fit_manifest.csv"
    )
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$accepted_exact_fit_manifest,
    paths[["accepted_exact_fit_manifest"]],
    na = ""
  )
  unname(paths)
}

make_update_2026_absolute_rescor_accepted_exact_records <- function(
    manifest
) {
  families <- unique(manifest$family)
  if (length(families) != 1L) {
    stop("The accepted exact-fit family is ambiguous.", call. = FALSE)
  }

  final_spec <- update_2026_absolute_rescor_final_exact_spec(families[[1L]])
  if (
    !is.data.frame(manifest) || nrow(manifest) != final_spec$exact_cases ||
      !identical(manifest$case_id, seq_len(final_spec$exact_cases)) ||
      any(!file.exists(manifest$exact_fit_path)) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L)
  ) {
    stop("The accepted exact-fit manifest is invalid.", call. = FALSE)
  }

  purrr::map(seq_len(nrow(manifest)), function(row) {
    as.list(manifest[row, , drop = FALSE])
  })
}

update_2026_absolute_rescor_held_out_integrated_log_lik <- function(
    candidate,
    input,
    cluster,
    loo_draws = 4000L
) {
  data <- input$stan_data
  cluster <- as.integer(cluster)

  if (
    cluster < 1L || cluster > data$N_cluster ||
      length(data$body_mass_z) != data$N ||
      any(!is.finite(data$body_mass_z))
  ) {
    stop("The held-out absolute-exposure cluster is invalid.",
         call. = FALSE)
  }

  first <- data$cluster_start[[cluster]]
  last <- data$cluster_end[[cluster]]
  rows <- seq.int(first, last)
  variables <- c(
    "b_intercept", "b_rt", "b_protein", "b_protein_rt",
    "b_moderator", "sd_study", "L_study", "sd_arm",
    "sd_outcome", "rho"
  )
  all_draws <- posterior::as_draws_df(candidate$fit$draws(variables))
  draw_ids <- make_sensitivity_loo_draw_ids(
    nrow(all_draws),
    min(as.integer(loo_draws), nrow(all_draws))
  )
  draws <- as.data.frame(all_draws)[draw_ids, , drop = FALSE]
  n_draws <- nrow(draws)
  k_basis <- as.integer(data$K_basis)
  k_study <- as.integer(data$K_study)
  basis_list <- evaluate_eiv_stan_basis(
    matrix(data$x[rows], nrow = 1L),
    data
  )
  basis <- do.call(cbind, lapply(basis_list, as.numeric))
  fixed_mean <- outer(
    as.numeric(draws$b_intercept),
    rep(1, length(rows))
  ) + outer(
    as.numeric(draws$b_rt),
    data$resistance_exercise_code[rows]
  )

  if (data$include_protein == 1L) {
    coefficient <- extract_cmdstan_indexed_draw_matrix(
      draws,
      "b_protein",
      k_basis
    )
    fixed_mean <- fixed_mean + coefficient %*% t(basis)
  }

  if (data$include_rt_interaction == 1L) {
    coefficient <- extract_cmdstan_indexed_draw_matrix(
      draws,
      "b_protein_rt",
      k_basis
    )
    fixed_mean <- fixed_mean +
      (coefficient %*% t(basis)) *
      matrix(
        data$resistance_exercise_code[rows],
        nrow = n_draws,
        ncol = length(rows),
        byrow = TRUE
      )
  }

  if (data$include_moderators == 1L) {
    moderators <- extract_cmdstan_indexed_draw_matrix(
      draws,
      "b_moderator",
      3L
    )
    fixed_mean <- fixed_mean +
      outer(moderators[, 1L], data$duration_z[rows]) +
      outer(moderators[, 2L], data$age_z[rows]) +
      outer(moderators[, 3L], data$body_mass_z[rows])
  }

  study_design <- if (data$include_random_slope == 1L) {
    cbind(1, basis)
  } else {
    matrix(1, nrow = length(rows), ncol = 1L)
  }
  study_sd <- extract_cmdstan_indexed_draw_matrix(
    draws,
    "sd_study",
    k_study
  )
  study_cholesky <- if (data$correlated_study_effects == 1L) {
    extract_cmdstan_matrix_draw_array(
      draws,
      "L_study",
      k_study,
      k_study
    )
  } else {
    NULL
  }

  arm_match <- outer(data$arm[rows], data$arm[rows], "==")
  outcome_match <- outer(data$outcome[rows], data$outcome[rows], "==")
  residual_scale <- outer(data$se_y[rows], data$se_y[rows])
  observed <- data$y[rows]
  output <- numeric(n_draws)
  for (draw in seq_len(n_draws)) {
    study_covariance <- if (data$correlated_study_effects == 1L) {
      scaled_cholesky <- diag(study_sd[draw, ], nrow = k_study) %*%
        study_cholesky[draw, , ]
      tcrossprod(scaled_cholesky)
    } else {
      diag(study_sd[draw, ]^2, nrow = k_study)
    }
    residual_covariance <- residual_scale * as.numeric(draws$rho[[draw]])
    diag(residual_covariance) <- data$se_y[rows]^2
    covariance <- residual_covariance +
      study_design %*% study_covariance %*% t(study_design) +
      arm_match * as.numeric(draws$sd_arm[[draw]])^2 +
      outcome_match * as.numeric(draws$sd_outcome[[draw]])^2
    cholesky <- chol(covariance)
    centred <- observed - fixed_mean[draw, ]
    standardised <- forwardsolve(t(cholesky), centred)
    output[[draw]] <- -0.5 * (
      length(rows) * log(2 * pi) +
        2 * sum(log(diag(cholesky))) +
        sum(standardised^2)
    )
  }

  output
}

update_2026_absolute_rescor_exact_correction_file_path <- function(
    record,
    output_root
) {
  directory <- file.path(
    output_root,
    record$outcome,
    sprintf("model_%02d", as.integer(record$model_index))
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf(
      "case_%03d_study_%03d.qs",
      as.integer(record$case_id),
      as.integer(record$observation)
    )
  )
}

compute_update_2026_absolute_rescor_exact_correction_to_file <- function(
    record,
    diagnostic_audit,
    enabled,
    output_root,
    loo_draws = 4000L,
    family = "total_rescor"
) {
  if (!isTRUE(enabled)) {
    runtime_flag <- if (identical(family, "supplement_rescor")) {
      "PROTEIN_UPDATE_2026_SUPPLEMENT_RESCOR_CORRECTION"
    } else {
      "PROTEIN_UPDATE_2026_TOTAL_RESCOR_CORRECTION"
    }
    stop(
      paste0(
        "Absolute residual-correlation exact scoring is disabled. Set ",
        runtime_flag,
        "=run to enable it."
      ),
      call. = FALSE
    )
  }

  if (!isTRUE(diagnostic_audit$all_exact_refit_diagnostics_pass)) {
    stop("Exact scoring requires passing refit diagnostics.",
         call. = FALSE)
  }
  exact_fit_path <- unname(as.character(record$exact_fit_path))
  exact_fit_sha256 <- unname(as.character(record$sha256))

  if (
    !file.exists(exact_fit_path) ||
      !identical(
        digest::digest(
          file = exact_fit_path,
          algo = "sha256",
          serialize = FALSE
        ),
        exact_fit_sha256
      )
  ) {
    stop("An accepted exact refit failed checksum validation.",
         call. = FALSE)
  }

  refit <- read_update_2026_absolute_rescor_exact_fit_file(
    exact_fit_path,
    family
  )
  if (
    refit$case_id != as.integer(record$case_id) ||
      !identical(refit$outcome, record$outcome) ||
      refit$model_index != as.integer(record$model_index) ||
      refit$observation != as.integer(record$observation)
  ) {
    stop("An accepted exact-refit record is misaligned.", call. = FALSE)
  }

  signature <- list(
    scorer_version = 1L,
    family = family,
    case_id = as.integer(record$case_id),
    observation = as.integer(record$observation),
    exact_fit_sha256 = exact_fit_sha256,
    integrated_loo_sha256 = refit$signature$integrated_loo_sha256,
    accepted_stage = record$stage,
    loo_draws = as.integer(loo_draws),
    moderator_order = c("duration_z", "age_z", "body_mass_z")
  )

  signature_sha256 <- digest::digest(signature, algo = "sha256")
  output_file <- update_2026_absolute_rescor_exact_correction_file_path(
    record,
    output_root
  )
  existing <- if (file.exists(output_file)) {
    tryCatch(qs::qread(output_file), error = function(e) NULL)
  } else {
    NULL
  }

  if (
    !is.null(existing) && inherits(existing$loo, "loo") &&
      identical(existing$signature_sha256, signature_sha256)
  ) {
    return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
  }

  held_out_log_lik <-
    update_2026_absolute_rescor_held_out_integrated_log_lik(
      candidate = refit$fitted_candidate,
      input = refit$input,
      cluster = refit$observation,
      loo_draws = loo_draws
    )
  maximum_log_lik <- max(held_out_log_lik)
  scaled_likelihood <- exp(held_out_log_lik - maximum_log_lik)
  exact_elpd <- maximum_log_lik + log(mean(scaled_likelihood))
  exact_mcse <- tryCatch(
    posterior::mcse_mean(scaled_likelihood) / mean(scaled_likelihood),
    error = function(e) NA_real_
  )
  patched_loo <- refit$integrated_result$loo
  observation <- as.integer(refit$observation)
  old_elpd <- patched_loo$pointwise[observation, "elpd_loo"]
  old_p_loo <- patched_loo$pointwise[observation, "p_loo"]
  full_data_lpd <- old_elpd + old_p_loo
  patched_loo$pointwise[observation, "elpd_loo"] <- exact_elpd
  patched_loo$pointwise[observation, "p_loo"] <-
    full_data_lpd - exact_elpd
  patched_loo$pointwise[observation, "looic"] <- -2 * exact_elpd

  if ("mcse_elpd_loo" %in% colnames(patched_loo$pointwise)) {
    patched_loo$pointwise[observation, "mcse_elpd_loo"] <- exact_mcse
  }
  patched_loo$diagnostics$pareto_k[[observation]] <- NA_real_
  if (!is.null(patched_loo$diagnostics$n_eff)) {
    patched_loo$diagnostics$n_eff[[observation]] <- NA_real_
  }

  patched_loo <- update_primary_exact_loo_estimates(patched_loo)
  cluster_manifest <- refit$input$cluster_manifest
  cluster_row <- cluster_manifest[observation, , drop = FALSE]
  exact_refit_summary <- summarise_eiv_exact_loo_refit(refit) |>
    dplyr::mutate(
      accepted_stage = record$stage,
      held_out_study = cluster_row$study_no[[1L]],
      held_out_cluster_size = cluster_row$cluster_size[[1L]],
      old_psis_elpd_loo = old_elpd,
      exact_elpd_loo = exact_elpd,
      exact_minus_psis_elpd = exact_elpd - old_elpd,
      exact_elpd_mcse = exact_mcse
    )

  correction <- list(
    case_id = refit$case_id,
    family = family,
    outcome = refit$outcome,
    model_index = refit$model_index,
    model_name = refit$model_name,
    observation_manifest = cluster_manifest,
    loo = patched_loo,
    conditional_loo = refit$integrated_result$conditional_loo,
    remedy = "study_cluster_integrated_psis_plus_exact",
    k_threshold = refit$integrated_result$k_threshold,
    accepted_stage = record$stage,
    signature = signature,
    signature_sha256 = signature_sha256,
    exact_refit_summary = exact_refit_summary
  )

  write_atomic_qs(correction, output_file)
}

audit_update_2026_absolute_rescor_exact_correction_files <- function(
    paths,
    integrated_audit,
    family = "total_rescor"
) {
  exact_spec <- update_2026_absolute_rescor_exact_initial_spec(family)
  paths <- unname(unlist(paths, use.names = FALSE))
  expected <- as.integer(integrated_audit$exact_refits_required)

  if (
    length(paths) != expected || expected != exact_spec$expected_cases ||
      anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The exact study-cluster corrections are incomplete.",
         call. = FALSE)
  }

  corrections <- purrr::map(paths, qs::qread)
  manifest <- purrr::map2_dfr(paths, corrections, function(path, result) {
    tibble::tibble(
      case_id = as.integer(result$case_id),
      family = result$family,
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      model_name = result$model_name,
      observation =
        as.integer(result$exact_refit_summary$observation[[1L]]),
      accepted_stage = result$accepted_stage,
      correction_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      bytes = as.numeric(file.info(path)$size),
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(case_id)

  diagnostic_summary <- corrections |>
    purrr::map_dfr("exact_refit_summary") |>
    dplyr::arrange(case_id)
  observed_keys <- paste(
    manifest$outcome,
    manifest$model_index,
    manifest$observation,
    sep = "::"
  )
  expected_keys <- paste(
    integrated_audit$high_k_cases$outcome,
    integrated_audit$high_k_cases$model_index,
    integrated_audit$high_k_cases$observation,
    sep = "::"
  )
  outcome_counts <- table(factor(
    manifest$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))

  if (
    nrow(manifest) != exact_spec$expected_cases ||
      nrow(diagnostic_summary) != exact_spec$expected_cases ||
      !identical(
        manifest$case_id,
        seq_len(exact_spec$expected_cases)
      ) ||
      !identical(
        diagnostic_summary$case_id,
        seq_len(exact_spec$expected_cases)
      ) ||
      any(manifest$family != family) || anyDuplicated(observed_keys) ||
      !setequal(observed_keys, expected_keys) ||
      !identical(as.integer(outcome_counts), exact_spec$outcome_counts) ||
      any(manifest$bytes <= 0) || any(nchar(manifest$sha256) != 64L) ||
      !all(diagnostic_summary$diagnostic_pass)
  ) {
    stop("The exact study-cluster correction audit is invalid.",
         call. = FALSE)
  }

  list(
    family = family,
    diagnostic_summary = diagnostic_summary,
    correction_manifest = manifest,
    exact_refits = exact_spec$expected_cases,
    exact_refits_passing = exact_spec$expected_cases,
    exact_refits_requiring_remediation = 0L,
    all_exact_refit_diagnostics_pass = TRUE
  )
}

write_update_2026_absolute_rescor_exact_correction_audit <- function(
    audit,
    output_dir
) {
  exact_spec <- update_2026_absolute_rescor_exact_initial_spec(audit$family)
  if (
    !audit$family %in% c("total_rescor", "supplement_rescor") ||
      audit$exact_refits != exact_spec$expected_cases ||
      nrow(audit$diagnostic_summary) != exact_spec$expected_cases ||
      nrow(audit$correction_manifest) != exact_spec$expected_cases ||
      !isTRUE(audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("Cannot write an incomplete exact-correction audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    correction_manifest = file.path(output_dir, "correction_manifest.csv")
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$correction_manifest,
    paths[["correction_manifest"]],
    na = ""
  )
  unname(paths)
}

read_update_2026_absolute_rescor_exact_corrections <- function(manifest) {
  families <- unique(manifest$family)
  if (length(families) != 1L) {
    stop("The exact-correction family is ambiguous.", call. = FALSE)
  }
  exact_spec <- update_2026_absolute_rescor_exact_initial_spec(families[[1L]])

  if (
    !is.data.frame(manifest) ||
      nrow(manifest) != exact_spec$expected_cases ||
      !identical(manifest$case_id, seq_len(exact_spec$expected_cases)) ||
      any(!file.exists(manifest$correction_path))
  ) {
    stop("The exact-correction manifest is invalid.", call. = FALSE)
  }

  corrections <- purrr::map(manifest$correction_path, qs::qread)
  corrections <- corrections[order(purrr::map_int(corrections, "case_id"))]
  if (
    !identical(
      unname(purrr::map_int(corrections, "case_id")),
      seq_len(exact_spec$expected_cases)
    ) ||
      any(!purrr::map_lgl(corrections, ~ inherits(.x$loo, "loo")))
  ) {
    stop("The exact study-cluster corrections are invalid.",
         call. = FALSE)
  }

  corrections
}

make_update_2026_absolute_rescor_final_loo_audit <- function(
    integrated_manifest,
    exact_corrections,
    exact_audit,
    family = "total_rescor"
) {
  exact_spec <- update_2026_absolute_rescor_exact_initial_spec(family)
  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (!isTRUE(exact_audit$all_exact_refit_diagnostics_pass)) {
    stop("Final residual-correlation LOO requires passing exact refits.",
         call. = FALSE)
  }
  final <- apply_sensitivity_full_exact_loo_corrections_from_files(
    integrated_manifest = integrated_manifest,
    exact_results = exact_corrections,
    family = family,
    expected_models = 72L,
    expected_indices = retained
  )
  final$model_summary$method <-
    "integrated_study_cluster_psis_plus_exact"
  final$results <- purrr::map(final$results, function(result) {
    result$remedy <- if (anyNA(loo::pareto_k_values(result$loo))) {
      "study_cluster_integrated_psis_plus_exact"
    } else {
      "study_cluster_integrated_psis"
    }
    result
  })

  outcome_summary <- final$model_summary |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_unresolved_high_k =
        sum(n_pareto_k_gt_threshold > 0L),
      unresolved_high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_remaining_pareto_k = max(maximum_pareto_k, na.rm = TRUE),
      .by = outcome
    )

  correction_counts <- exact_audit$diagnostic_summary |>
    dplyr::count(outcome, model_index, name = "exact_corrections")
  final_manifest <- integrated_manifest |>
    dplyr::left_join(
      correction_counts,
      by = c("outcome", "model_index")
    ) |>
    dplyr::mutate(
      exact_corrections = tidyr::replace_na(exact_corrections, 0L),
      final_method = dplyr::if_else(
        exact_corrections > 0L,
        "integrated_study_cluster_psis_plus_exact",
        "integrated_study_cluster_psis"
      )
    )

  if (
    !isTRUE(final$stacking_ready) || nrow(final$model_summary) != 72L ||
      nrow(outcome_summary) != 4L || any(outcome_summary$models != 18L) ||
      any(outcome_summary$unresolved_high_k_cases != 0L) ||
      nrow(final_manifest) != 72L ||
      sum(final_manifest$exact_corrections) != exact_spec$expected_cases ||
      nrow(final$exact_refit_summary) != exact_spec$expected_cases
  ) {
    stop("The final residual-correlation LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  final$family <- family
  final$outcome_summary <- outcome_summary
  final$final_loo_manifest <- final_manifest
  final$exact_refits <- exact_spec$expected_cases
  final$all_exact_refit_diagnostics_pass <- TRUE
  final
}

write_update_2026_absolute_rescor_final_loo_audit <- function(
    audit,
    output_dir
) {
  exact_spec <- update_2026_absolute_rescor_exact_initial_spec(audit$family)
  if (
    !audit$family %in% c("total_rescor", "supplement_rescor") ||
      !isTRUE(audit$stacking_ready) ||
      nrow(audit$model_summary) != 72L ||
      nrow(audit$outcome_summary) != 4L ||
      nrow(audit$exact_refit_summary) != exact_spec$expected_cases ||
      nrow(audit$final_loo_manifest) != 72L
  ) {
    stop("Cannot write an incomplete final residual-correlation LOO audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    final_loo_manifest = file.path(output_dir, "final_loo_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    exact_refit_summary = file.path(output_dir, "exact_refit_summary.csv")
  )
  readr::write_csv(audit$final_loo_manifest, paths[["final_loo_manifest"]])
  readr::write_csv(audit$model_summary, paths[["model_summary"]])
  readr::write_csv(audit$outcome_summary, paths[["outcome_summary"]])
  readr::write_csv(
    audit$exact_refit_summary,
