make_update_2026_total_rescor_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    data_by_outcome,
    input_preflight,
    specifications,
    accepted_fit_manifest,
    diagnostic_audit,
    integrated_loo_audit,
    final_exact_audit,
    exact_correction_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit,
    family = "total_rescor"
) {
  verification_spec <- update_2026_absolute_rescor_verification_spec(family)
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  stages <- c("initial", "remedy_1", "remedy_2", "remedy_3")
  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::mutate(
      model_name = paste0(model_name, " [residual correlation by study]")
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  specification_keys <- registry_keys(specification_table)
  accepted_keys <- registry_keys(accepted_fit_manifest)
  diagnostic_keys <- registry_keys(diagnostic_audit$diagnostic_summary)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, accepted_keys) &&
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- specification_table |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      accepted_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      diagnostic_audit$diagnostic_summary |>
        dplyr::select(outcome, model_index, diagnostic_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  preflight_summary <- input_preflight |>
    dplyr::distinct(
      outcome, contrasts, studies, arms, exposure_minimum_g_day,
      exposure_maximum_g_day, reference_g_day, internal_unit_g_day,
      grid_step_g_day
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes))
  accepted_stage_counts <- table(factor(
    accepted_fit_manifest$stage,
    levels = stages
  ))
  exact_stage_counts <- table(factor(
    final_exact_audit$accepted_exact_fit_manifest$stage,
    levels = stages
  ))
  weight_sums <- stacking_weights |>
    dplyr::summarise(models = dplyr::n(), weight_sum = sum(weight),
                     .by = outcome) |>
    dplyr::arrange(factor(outcome, levels = outcomes))
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    ) |>
    dplyr::arrange(factor(outcome, levels = outcomes))

  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_sensitivity_full_reporting_file,
    family = family
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  reporting_model_weights <- bind_report("model_weights")
  reporting_weight_sums <- reporting_model_weights |>
    dplyr::summarise(models = dplyr::n(), weight_sum = sum(weight),
                     .by = outcome) |>
    dplyr::arrange(factor(outcome, levels = outcomes))
  integrated_models <- integrated_loo_audit$model_summary |>
    dplyr::filter(method == "integrated_study_cluster_psis")
  conditional_models <- integrated_loo_audit$model_summary |>
    dplyr::filter(method == "conditional_study_cluster_psis")
  correction_manifest <- exact_correction_audit$correction_manifest

  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      paste0("all four ", verification_spec$label, " datasets are valid"),
      "all five final registries contain the same 72 model keys",
      "model names agree across specifications fits diagnostics LOO and weights",
      "all 72 accepted fit files exist and have checksums",
      "all accepted-fit sampling diagnostics pass",
      paste0(
        "initial LOO contains 72 aligned models and ",
        verification_spec$exact_cases,
        " high-k cases"
      ),
      paste0(
        "all ", verification_spec$exact_cases,
        " accepted exact-refit sampling diagnostics pass"
      ),
      paste0(
        "all ", verification_spec$exact_cases,
        " compact exact corrections exist and have checksums"
      ),
      "final LOO contains 72 models and no unresolved high-k cases",
      "four stacking vectors contain 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      paste0("all four ", verification_spec$label,
             " reporting audits pass")
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      identical(names(data_by_outcome), outcomes) &&
        nrow(input_preflight) == 72L && all(input_preflight$valid) &&
        nrow(preflight_summary) == 4L &&
        identical(
          preflight_summary$contrasts,
          verification_spec$expected_contrasts
        ) &&
        identical(
          preflight_summary$studies,
          verification_spec$expected_studies
        ) &&
        identical(preflight_summary$arms, verification_spec$expected_arms) &&
        all(
          preflight_summary$exposure_minimum_g_day ==
            verification_spec$exposure_minimum_g_day
        ) &&
        all(
          preflight_summary$reference_g_day ==
            verification_spec$reference_g_day
        ) &&
        all(
          preflight_summary$internal_unit_g_day ==
            verification_spec$internal_unit_g_day
        ) &&
        all(preflight_summary$grid_step_g_day == 1) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0),
      common_registry && length(specification_keys) == 72L,
      nrow(name_alignment) == 72L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(name_alignment$diagnostic_name == name_alignment$specification_name) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(accepted_fit_manifest) == 72L &&
        all(accepted_fit_manifest$family == family) &&
        identical(
          as.integer(accepted_stage_counts),
          verification_spec$accepted_stage_counts
        ) &&
        all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(accepted_fit_manifest$bytes > 0) &&
        all(nchar(accepted_fit_manifest$sha256) == 64L),
      identical(diagnostic_audit$family, family) &&
        diagnostic_audit$models == 72L &&
        isTRUE(diagnostic_audit$all_sampling_diagnostics_pass) &&
        all(diagnostic_audit$diagnostic_summary$diagnostic_pass),
      identical(integrated_loo_audit$family, family) &&
        integrated_loo_audit$models == 72L &&
        nrow(integrated_models) == 72L && nrow(conditional_models) == 72L &&
        integrated_loo_audit$exact_refits_required ==
          verification_spec$exact_cases &&
        nrow(integrated_loo_audit$high_k_cases) ==
          verification_spec$exact_cases,
      final_exact_audit$exact_refits == verification_spec$exact_cases &&
        final_exact_audit$exact_refits_passing ==
          verification_spec$exact_cases &&
        final_exact_audit$exact_refits_requiring_remediation == 0L &&
        isTRUE(final_exact_audit$all_exact_refit_diagnostics_pass) &&
        identical(
          as.integer(exact_stage_counts),
          verification_spec$exact_stage_counts
        ),
      exact_correction_audit$exact_refits == verification_spec$exact_cases &&
        exact_correction_audit$exact_refits_passing ==
          verification_spec$exact_cases &&
        isTRUE(exact_correction_audit$all_exact_refit_diagnostics_pass) &&
        nrow(correction_manifest) == verification_spec$exact_cases &&
        all(file.exists(correction_manifest$correction_path)) &&
        all(correction_manifest$bytes > 0) &&
        all(nchar(correction_manifest$sha256) == 64L),
      identical(final_loo_audit$family, family) &&
        nrow(final_loo_audit$model_summary) == 72L &&
        final_loo_audit$exact_refits == verification_spec$exact_cases &&
        isTRUE(final_loo_audit$stacking_ready) &&
        all(final_loo_audit$outcome_summary$unresolved_high_k_cases == 0L),
      nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        all(prediction_sums$selected_models >= 1L) &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      identical(reporting_audit$family, family) &&
        isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid) &&
        nrow(reporting_model_weights) == 72L &&
        all(reporting_weight_sums$models == 18L) &&
        all(abs(reporting_weight_sums$weight_sum - 1) < 1e-8)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Updated residual-correlation verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    preparation_outcome_counts = preparation_audit$outcome_counts,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    absolute_exposure_provenance = absolute_audit$exposure_provenance,
    absolute_support_by_outcome = absolute_audit$support_by_outcome,
    absolute_scaling_plan = absolute_audit$scaling_plan,
    absolute_model_registry = absolute_audit$model_registry,
    absolute_family_plan = absolute_audit$family_plan,
    rescor_input_preflight = input_preflight,
    analysis_data = analysis_data,
    model_specifications = specification_table,
    model_name_alignment = name_alignment,
    accepted_fit_manifest = accepted_fit_manifest,
    sampling_diagnostic_summary = diagnostic_audit$diagnostic_summary,
    sampling_parameter_failures = diagnostic_audit$parameter_failures,
    initial_loo_model_summary = integrated_loo_audit$model_summary,
    initial_loo_outcome_summary = integrated_loo_audit$outcome_summary,
    initial_high_pareto_k_cases = integrated_loo_audit$high_k_cases,
    accepted_exact_fit_manifest =
      final_exact_audit$accepted_exact_fit_manifest,
    exact_refit_diagnostic_summary = final_exact_audit$diagnostic_summary,
    exact_correction_manifest = correction_manifest,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    final_exact_refit_summary = final_loo_audit$exact_refit_summary,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    reporting_model_weights = reporting_model_weights,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    paste("Frozen", verification_spec$label, "artifact:", names(artifacts)),
    names(artifacts)
  )
  list(checks = checks, artifacts = artifacts, descriptions = descriptions)
}

update_2026_absolute_rescor_pruning_spec <- function(family) {
  switch(
    family,
    total_rescor = list(
      label = "total residual-correlation",
      exposure = "total_g_day",
      model_fits = 97L,
      superseded_model_fits = 25L,
      exact_fits = 94L,
      accepted_exact_fits = 89L,
      superseded_exact_fits = 5L
    ),
    supplement_rescor = list(
      label = "supplement residual-correlation",
      exposure = "supplement_g_day",
      model_fits = 110L,
      superseded_model_fits = 38L,
      exact_fits = 176L,
      accepted_exact_fits = 139L,
      superseded_exact_fits = 37L
    ),
    stop("The residual-correlation pruning family is unsupported.",
         call. = FALSE)
  )
}

make_update_2026_total_rescor_pruning_plan <- function(
    accepted_fit_manifest,
    final_exact_audit,
    prediction_manifest,
    verification_files,
    family = "total_rescor",
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "rescor"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "total_rescor_update_2026"
      ),
      "manifest.csv"
    )
) {
  pruning_spec <- update_2026_absolute_rescor_pruning_spec(family)
  if (any(!file.exists(verification_files))) {
    stop("The residual-correlation verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure",
      pruning_spec$exposure,
      "rescor"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the residual-correlation archive.",
         call. = FALSE)
  }
  stages <- c("initial", "remedy_1", "remedy_2", "remedy_3")
  model_roots <- file.path(archive_root, stages)
  exact_roots <- file.path(archive_root, "loo", "exact", stages)
  deletion_roots <- c(model_roots, exact_roots)

  if (any(!dir.exists(deletion_roots))) {
    stop("An expected residual-correlation sampling directory is missing.",
         call. = FALSE)
  }
  deletion_paths <- unlist(purrr::map(deletion_roots, function(root) {
    list.files(root, recursive = TRUE, full.names = TRUE, all.files = TRUE)
  }), use.names = FALSE)
  deletion_paths <- deletion_paths[
    file.exists(deletion_paths) & !file.info(deletion_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  fit_paths <- deletion_paths[basename(deletion_paths) == "fit.qs"]
  relative_fit_paths <- substring(fit_paths, nchar(resolved_root) + 2L)
  is_exact <- startsWith(relative_fit_paths, "loo/exact/")
  model_match <- stringr::str_match(
    relative_fit_paths,
    "^(initial|remedy_1|remedy_2|remedy_3)/([^/]+)/model_([0-9]+)/fit\\.qs$"
  )
  exact_match <- stringr::str_match(
    relative_fit_paths,
    paste0(
      "^loo/exact/(initial|remedy_1|remedy_2|remedy_3)/",
      "([^/]+)/model_([0-9]+)/case_([0-9]+)/fit\\.qs$"
    )
  )
  accepted_model_paths <- normalizePath(
    accepted_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  accepted_exact_paths <- normalizePath(
    final_exact_audit$accepted_exact_fit_manifest$exact_fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  fit_manifest <- tibble::tibble(
    path = fit_paths,
    fit_directory = dirname(fit_paths),
    relative_path = relative_fit_paths,
    fit_class = ifelse(is_exact, "exact_refit", "model_fit"),
    archive_stage = ifelse(is_exact, exact_match[, 2L], model_match[, 2L]),
    outcome = ifelse(is_exact, exact_match[, 3L], model_match[, 3L]),
    model_index = as.integer(ifelse(
      is_exact,
      exact_match[, 4L],
      model_match[, 4L]
    )),
    case_id = as.integer(ifelse(is_exact, exact_match[, 5L], NA)),
    accepted_fit = ifelse(
      is_exact,
      fit_paths %in% accepted_exact_paths,
      fit_paths %in% accepted_model_paths
    ),
    bytes = as.numeric(file.info(fit_paths)$size)
  ) |>
    dplyr::arrange(fit_class, archive_stage, outcome, model_index, case_id)

  model_fit_manifest <- dplyr::filter(fit_manifest, fit_class == "model_fit")
  exact_refit_manifest <- dplyr::filter(fit_manifest, fit_class == "exact_refit")
  if (
    nrow(model_fit_manifest) != pruning_spec$model_fits ||
      sum(model_fit_manifest$accepted_fit) != 72L ||
      sum(!model_fit_manifest$accepted_fit) !=
        pruning_spec$superseded_model_fits ||
      nrow(exact_refit_manifest) != pruning_spec$exact_fits ||
      sum(exact_refit_manifest$accepted_fit) !=
        pruning_spec$accepted_exact_fits ||
      sum(!exact_refit_manifest$accepted_fit) !=
        pruning_spec$superseded_exact_fits ||
      anyNA(fit_manifest[c("archive_stage", "outcome", "model_index")]) ||
      any(fit_manifest$bytes <= 0)
  ) {
    stop("The residual-correlation fit inventory is invalid.", call. = FALSE)
  }

  fit_positions <- vapply(deletion_paths, function(path) {
    matches <- which(
      path == fit_manifest$path |
        startsWith(tolower(path), paste0(tolower(fit_manifest$fit_directory), "/"))
    )
    if (length(matches) == 1L) matches else NA_integer_
  }, integer(1L))

  if (anyNA(fit_positions)) {
    stop("A residual-correlation sampling file is not attached to one fit archive.",
         call. = FALSE)
  }
  extension <- tolower(tools::file_ext(deletion_paths))
  file_type <- dplyr::case_when(
    basename(deletion_paths) == "fit.qs" ~ "fit_object",
    extension == "csv" ~ "cmdstan_chain_csv",
    extension == "json" ~ "fixed_metric_json",
    TRUE ~ "unknown"
  )
  deletion_manifest <- tibble::tibble(
    path = deletion_paths,
    relative_path = substring(deletion_paths, nchar(resolved_root) + 2L),
    fit_class = fit_manifest$fit_class[fit_positions],
    archive_stage = fit_manifest$archive_stage[fit_positions],
    artifact_role = dplyr::case_when(
      fit_manifest$fit_class[fit_positions] == "exact_refit" &
        fit_manifest$accepted_fit[fit_positions] ~ "accepted_exact_refit",
      fit_manifest$fit_class[fit_positions] == "exact_refit" ~
        "superseded_exact_refit",
      fit_manifest$accepted_fit[fit_positions] ~ "accepted_model_fit",
      TRUE ~ "superseded_model_fit"
    ),
    outcome = fit_manifest$outcome[fit_positions],
    model_index = fit_manifest$model_index[fit_positions],
    case_id = fit_manifest$case_id[fit_positions],
    file_type = file_type,
    bytes = as.numeric(file.info(deletion_paths)$size),
    lean_action = paste(
      "delete refittable", pruning_spec$label, "sampling archive"
    )
  ) |>
    dplyr::arrange(fit_class, archive_stage, outcome, model_index, case_id,
                   relative_path)

  if (
    any(deletion_manifest$file_type == "unknown") ||
      sum(deletion_manifest$file_type == "fit_object") !=
        pruning_spec$model_fits + pruning_spec$exact_fits ||
      any(deletion_manifest$bytes <= 0)
  ) {
    stop("The residual-correlation deletion inventory is incomplete.",
         call. = FALSE)
  }

  compact_roots <- c(
    loo_psis = file.path(archive_root, "loo", "study_integrated"),
    exact_corrections = file.path(archive_root, "loo", "exact", "corrections"),
    reporting = file.path(archive_root, "reporting")
  )
  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact residual-correlation directory is missing.",
         call. = FALSE)
  }

  compact_paths <- unlist(purrr::map(compact_roots, function(root) {
    list.files(root, recursive = TRUE, full.names = TRUE, all.files = TRUE)
  }), use.names = FALSE)
  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  normalized_compact_roots <- normalizePath(
    compact_roots,
    winslash = "/",
    mustWork = TRUE
  )
  component <- vapply(compact_paths, function(path) {
    matches <- names(compact_roots)[vapply(
      normalized_compact_roots,
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = paste("retain compact", pruning_spec$label, "result")
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo_psis", "exact_corrections", "reporting")
  ))
  expected_reporting_files <- nrow(prediction_manifest) + 8L
  if (
    !identical(
      as.integer(compact_counts[1:2]),
      c(72L, pruning_spec$accepted_exact_fits)
    ) ||
      as.integer(compact_counts[[3L]]) != expected_reporting_files ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact residual-correlation archive is incomplete.",
         call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    model_fit_archives_deleted = nrow(model_fit_manifest),
    accepted_model_fit_archives_deleted = sum(model_fit_manifest$accepted_fit),
    superseded_model_fit_archives_deleted = sum(!model_fit_manifest$accepted_fit),
    exact_refit_archives_deleted = nrow(exact_refit_manifest),
    accepted_exact_refit_archives_deleted = sum(exact_refit_manifest$accepted_fit),
    superseded_exact_refit_archives_deleted = sum(!exact_refit_manifest$accepted_fit),
    archive_files_deleted = nrow(deletion_manifest),
    fit_archive_files_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained = sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, study-corrected LOO, and all 72 weights remain frozen;",
      "restoring model or exact-refit objects requires refitting the absolute",
      paste0(pruning_spec$label, " family.")
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_fit_manifest,
    exact_refit_manifest = exact_refit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_total_rescor_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "rescor", "pruning"
    )
) {
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    exact_refit_manifest = file.path(output_dir, "exact_refit_manifest.csv"),
    deletion_file_manifest = file.path(output_dir, "deletion_file_manifest.csv"),
    compact_archive_manifest = file.path(output_dir, "compact_archive_manifest.csv")
  )
  readr::write_csv(plan$summary, paths[["summary"]], na = "")
  readr::write_csv(plan$model_fit_manifest, paths[["model_fit_manifest"]], na = "")
  readr::write_csv(plan$exact_refit_manifest, paths[["exact_refit_manifest"]], na = "")
  readr::write_csv(plan$deletion_file_manifest, paths[["deletion_file_manifest"]], na = "")
  readr::write_csv(plan$compact_archive_manifest, paths[["compact_archive_manifest"]], na = "")
  unname(paths)
}

# Absolute total-intake protein-manipulation strategy family ----

# Extend the total-intake candidate formulas with the reviewed strategy
# classification and record which models include dose-by-strategy terms.
make_update_2026_total_strategy_specifications <- function(
    total_primary_specifications
) {
  specifications <- purrr::map(
    total_primary_specifications,
    function(specification) {
      specification$family <- "total_strategy"
      specification$primary_formula <- specification$formula
      specification$formula <- make_protein_strategy_formula(specification)
      specification$model_name <- paste0(
        specification$model_name,
        " [strategy]"
      )
      specification$includes_strategy_dose_interaction <-
        !as.integer(specification$model_index) %in% c(1L, 5L)
      specification
    }
  )

  registry <- dplyr::bind_rows(specifications)
  keys <- paste(registry$outcome, registry$model_index, sep = "::")
  outcome_counts <- table(factor(
    registry$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  has_strategy_main <- stringr::str_detect(
    registry$formula,
    "\\bstrategy_code\\b"
  )
  has_strategy_interaction <- stringr::str_detect(
    registry$formula,
    "strategy_code:|by\\s*=\\s*strategy_code"
  )
  formula_parses <- purrr::map_lgl(
    registry$formula,
    ~ !inherits(try(stats::as.formula(.x), silent = TRUE), "try-error")
  )

  if (
    length(specifications) != 72L || anyDuplicated(keys) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      any(registry$model_index %in%
            c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)) ||
      !all(has_strategy_main) ||
      !identical(
        has_strategy_interaction,
        registry$includes_strategy_dose_interaction
      ) ||
      !all(formula_parses)
  ) {
    stop(
      "The total-intake strategy specification registry is invalid.",
      call. = FALSE
    )
  }

  names(specifications) <- paste0(
    registry$outcome,
    "_model_",
    stringr::str_pad(registry$model_index, 2L, pad = "0")
  )
  specifications
}

prepare_update_2026_total_strategy_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome
) {
  data <- data_by_outcome[[specification$outcome]]
  priors <- priors_by_outcome[[specification$outcome]]

  if (is.null(data) || !nrow(data) || is.null(priors)) {
    stop("Total-intake strategy data or priors are missing.", call. = FALSE)
  }
  priors <- normalize_primary_brms_priors(priors)
  if (isTRUE(specification$regularised_variance_priors)) {
    priors <- add_regularised_variance_priors(priors)
  }

  if (isTRUE(specification$includes_moderators)) {
    data <- add_absolute_primary_body_mass(data)
    data <- add_primary_standardised_moderators(data)
    priors <- add_primary_standardised_moderator_priors(priors)
    priors <- add_absolute_primary_body_mass_prior(priors)
  }

  if (isTRUE(specification$targeted_smooth_prior)) {
    priors <- add_primary_targeted_smooth_prior(
      priors,
      scale = specification$smooth_prior_scale
    )
  }

  list(
    family = "total_strategy",
    formula = specification$formula,
    priors = priors,
    data = data,
    specification = specification
  )
}

validate_update_2026_total_strategy_inputs <- function(
    specifications,
    data_by_outcome,
    priors_by_outcome,
    absolute_audit,
    strategy_audit_review
) {
  if (
    !isTRUE(absolute_audit$ready_for_review) ||
      any(!absolute_audit$checks$passed) ||
      !isTRUE(strategy_audit_review$audit_ready)
  ) {
    stop(
      "The absolute-exposure or strategy-classification audit has not passed.",
      call. = FALSE
    )
  }

  checks <- purrr::map_dfr(specifications, function(specification) {
    input <- prepare_update_2026_total_strategy_input(
      specification,
      data_by_outcome,
      priors_by_outcome
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    includes_protein <- !as.integer(specification$model_index) %in% c(1L, 5L)
    has_strategy_interaction <- stringr::str_detect(
      input$formula,
      "strategy_code:|by\\s*=\\s*strategy_code"
    )
    tibble::tibble(
      family = input$family,
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      arms = dplyr::n_distinct(input$data$arm_no),
      addition_studies = dplyr::n_distinct(
        input$data$study_no[input$data$protein_strategy == "Addition"]
      ),
      substitution_studies = dplyr::n_distinct(
        input$data$study_no[input$data$protein_strategy == "Substitution"]
      ),
      exposure_minimum_g_day = min(input$data$protein_intake_raw),
      exposure_maximum_g_day = max(input$data$protein_intake_raw),
      reference_g_day = unique(input$data$absolute_exposure_reference_g_day),
      internal_unit_g_day = unique(input$data$absolute_exposure_unit_g_day),
      sampling_schedule = specification$sampling_schedule,
      adapt_delta = as.numeric(specification$adapt_delta),
      max_treedepth = as.integer(specification$max_treedepth),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      valid =
        all(c("protein_strategy", "strategy_code") %in% names(input$data)) &&
        setequal(unique(input$data$protein_strategy),
                 c("Addition", "Substitution")) &&
        all(input$data$strategy_code %in% c(0, 1)) &&
        stringr::str_detect(input$formula, "\\bstrategy_code\\b") &&
        identical(has_strategy_interaction, includes_protein)
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  outcome_counts <- table(factor(
    checks$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  expected_reference <- absolute_audit$scaling_plan$reference_g_day[
    absolute_audit$scaling_plan$exposure == "total_g_day"
  ]

  if (
    nrow(checks) != 72L || anyDuplicated(keys) || !all(checks$valid) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      any(checks$contrasts < 1L) || any(checks$studies < 2L) ||
      any(checks$addition_studies < 1L) ||
      any(checks$substitution_studies < 1L) ||
      any(checks$reference_g_day != expected_reference) ||
      any(checks$internal_unit_g_day != 50) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The total-intake strategy input preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

