make_update_2026_total_strategy_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  expected_keys <- c("strength::15", "function::9")
  failed_keys <- paste(failed$outcome, failed$model_index, sep = "::")
  if (
    !identical(diagnostic_audit$family, "total_strategy") ||
      nrow(failed) != 2L || !setequal(failed_keys, expected_keys) ||
      any(failed$divergent_transitions != 0) ||
      any(failed$maximum_treedepth_transitions <= 0L) ||
      !all(failed$convergence_pass)
  ) {
    stop("The total-intake strategy remedy no longer matches its audit.",
         call. = FALSE)
  }

  specification_keys <- purrr::map_chr(
    specifications,
    ~ paste(.x$outcome, .x$model_index, sep = "::")
  )
  selected <- specifications[match(expected_keys, specification_keys)]
  if (length(selected) != 2L || any(vapply(selected, is.null, logical(1)))) {
    stop("Could not uniquely select the total-strategy remedy models.",
         call. = FALSE)
  }

  selected <- purrr::map(selected, function(specification) {
    specification$adapt_delta <- max(
      as.numeric(specification$adapt_delta),
      0.995
    )
    specification$max_treedepth <- 15L
    specification$iter_warmup <- 3000L
    specification$iter_sampling <- 8000L
    specification$remedy <- "deeper_trees_after_treedepth_failure"
    specification$archive_stage <- "remedy_1"
    specification$remedy_reason <- paste(
      "Maximum-treedepth transitions with no divergence, E-BFMI,",
      "R-hat, ESS, or MCSE failure."
    )
    specification
  })

  names(selected) <- c("strength_model_15", "function_model_09")
  selected
}

validate_update_2026_total_strategy_remedy_inputs <- function(
    inputs,
    initial_fit_paths
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    expected_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      adapt_delta = as.numeric(specification$adapt_delta),
      max_treedepth = as.integer(specification$max_treedepth),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      initial_fit_exists =
        length(expected_path) == 1L && file.exists(expected_path),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(outcome, levels = c("strength", "function")),
      model_index
    )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  if (
    nrow(checks) != 2L ||
      !setequal(keys, c("strength::15", "function::9")) ||
      any(checks$adapt_delta != 0.995) ||
      any(checks$max_treedepth != 15L) ||
      any(checks$iter_warmup != 3000L) ||
      any(checks$iter_sampling != 8000L) ||
      any(checks$chains != 4L) ||
      any(checks$parallel_chains != 4L) ||
      !all(checks$initial_fit_exists) || !all(checks$valid)
  ) {
    stop("The total-intake strategy remedy preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

