combine_update_2026_total_strategy_remedy_diagnostics <- function(
    initial_audit,
    remedy_diagnostics
) {
  expected_keys <- c("strength::15", "function::9")
  if (length(remedy_diagnostics) != 2L) {
    stop("Expected two total-intake strategy remedy diagnostics.",
         call. = FALSE)
  }

  remedy_summary <- dplyr::bind_rows(
    purrr::map(remedy_diagnostics, "summary")
  )
  remedy_keys <- paste(
    remedy_summary$outcome,
    remedy_summary$model_index,
    sep = "::"
  )

  if (
    nrow(remedy_summary) != 2L ||
      !setequal(remedy_keys, expected_keys)
  ) {
    stop("The total-intake strategy remedy diagnostics are invalid.",
         call. = FALSE)
  }

  summary <- initial_audit$diagnostic_summary |>
    dplyr::filter(
      !paste(outcome, model_index, sep = "::") %in% expected_keys
    ) |>
    dplyr::bind_rows(remedy_summary) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    ) |>
    dplyr::mutate(
      ppc_warning = primary_ppc_warning(dplyr::pick(dplyr::everything())),
      status = dplyr::case_when(
        !diagnostic_pass ~ "REQUIRES REMEDIATION",
        ppc_warning ~ "PASS WITH PPC WARNING",
        TRUE ~ "PASS"
      )
    )

  parameter_failures <- initial_audit$parameter_failures |>
    dplyr::filter(
      !paste(outcome, model_index, sep = "::") %in% expected_keys
    ) |>
    dplyr::bind_rows(purrr::map_dfr(remedy_diagnostics, function(result) {
      result$parameter_failures |>
        dplyr::mutate(
          outcome = result$summary$outcome[[1L]],
          model_index = result$summary$model_index[[1L]],
          .before = 1L
        )
    }))

  outcome_summary <- summary |>
    dplyr::group_by(outcome) |>
    dplyr::summarise(
      models = dplyr::n(),
      models_passing_sampling = sum(diagnostic_pass),
      models_requiring_remediation = sum(!diagnostic_pass),
      models_with_ppc_warning = sum(ppc_warning),
      minimum_coverage = min(predictive_90_interval_coverage),
      maximum_coverage = max(predictive_90_interval_coverage),
      .groups = "drop"
    )

  if (
    nrow(summary) != 72L ||
      anyDuplicated(paste(summary$outcome, summary$model_index)) ||
      nrow(outcome_summary) != 4L
  ) {
    stop("The final total-intake strategy diagnostic audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_strategy",
    models = 72L,
    models_passing_sampling = sum(summary$diagnostic_pass),
    models_requiring_remediation = sum(!summary$diagnostic_pass),
    all_sampling_diagnostics_pass = all(summary$diagnostic_pass),
    diagnostic_summary = summary,
    parameter_failures = parameter_failures,
    outcome_summary = outcome_summary
  )
}

make_update_2026_total_strategy_accepted_fit_manifest <- function(
    initial_manifest,
    remedy_fit_paths,
    final_diagnostic_audit
) {
  remedy_paths <- unname(unlist(remedy_fit_paths, use.names = FALSE))

  if (
    nrow(initial_manifest) != 72L || length(remedy_paths) != 2L ||
      !isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass) ||
      final_diagnostic_audit$models_passing_sampling != 72L ||
      any(!file.exists(remedy_paths)) ||
      any(file.info(remedy_paths)$size <= 0)
  ) {
    stop(
      "Accepted total-strategy fits require 72 passing diagnostics.",
      call. = FALSE
    )
  }

  remedy <- tibble::tibble(
    outcome = basename(dirname(remedy_paths)),
    model_index = as.integer(stringr::str_match(
      basename(remedy_paths),
      "model_([0-9]+)\\.qs$"
    )[, 2]),
    fit_path = remedy_paths,
    stage = "remedy_1",
    bytes = file.info(remedy_paths)$size,
    sha256 = purrr::map_chr(
      remedy_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    )
  ) |>
    dplyr::left_join(
      initial_manifest |>
        dplyr::select(outcome, model_index, model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::select(
      outcome, model_index, model_name, fit_path, stage, bytes, sha256
    )

  remedy_keys <- paste(remedy$outcome, remedy$model_index, sep = "::")
  accepted <- initial_manifest |>
    dplyr::anti_join(
      remedy |> dplyr::select(outcome, model_index),
      by = c("outcome", "model_index")
    ) |>
    dplyr::bind_rows(remedy) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  retained_indices <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )
  index_check <- accepted |>
    dplyr::group_by(outcome) |>
    dplyr::summarise(
      models = dplyr::n(),
      indices_valid = setequal(model_index, retained_indices),
      .groups = "drop"
    )

  if (
    !setequal(remedy_keys, c("strength::15", "function::9")) ||
      nrow(accepted) != 72L ||
      anyDuplicated(accepted[c("outcome", "model_index")]) ||
      nrow(index_check) != 4L || any(index_check$models != 18L) ||
      !all(index_check$indices_valid) ||
      sum(accepted$stage == "initial") != 70L ||
      sum(accepted$stage == "remedy_1") != 2L ||
      !all(file.exists(accepted$fit_path)) || any(accepted$bytes <= 0) ||
      any(nchar(accepted$sha256) != 64L)
  ) {
    stop("The accepted total-intake strategy manifest is invalid.",
         call. = FALSE)
  }

  accepted
}

