update_2026_total_strategy_loo_file_path <- function(outcome, model_index) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure", "total_g_day",
    "strategy", "loo", "integrated", outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf("model_%02d_integrated_loo.qs", as.integer(model_index))
  )
}

compute_update_2026_total_strategy_integrated_loo_to_file <- function(
    record,
    enabled,
    cores = 1L,
    k_threshold = 0.7
) {
  retained_indices <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (!isTRUE(enabled)) {
    stop(
      "Total-intake strategy LOO is disabled. Set ",
      "PROTEIN_UPDATE_2026_TOTAL_STRATEGY_LOO=run to enable it.",
      call. = FALSE
    )
  }

  if (
    !file.exists(record$fit_path) ||
      !record$model_index %in% retained_indices ||
      !record$outcome %in%
        c("whole_body", "hypertrophy", "strength", "function")
  ) {
    stop("A total-intake strategy LOO record is invalid.", call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  if (
    !identical(candidate$outcome, record$outcome) ||
      as.integer(candidate$model_index) != record$model_index
  ) {
    stop("A total-strategy fit does not match its LOO record.",
         call. = FALSE)
  }

  initial <- compute_primary_candidate_psis_loo(
    fitted_candidate = candidate,
    cores = cores,
    save_psis = FALSE
  )
  integrated <- compute_primary_candidate_integrated_psis_loo(
    fitted_candidate = candidate,
    initial_loo_result = initial,
    k_threshold = k_threshold,
    cores = cores
  )
  integrated$fit_path <- normalizePath(
    record$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  integrated$fit_stage <- record$fit_stage
  output_file <- update_2026_total_strategy_loo_file_path(
    record$outcome,
    record$model_index
  )
  temporary_file <- paste0(output_file, ".tmp-", Sys.getpid())
  on.exit(unlink(temporary_file, force = TRUE), add = TRUE)
  qs::qsave(integrated, temporary_file, preset = "high")

  if (!file.copy(temporary_file, output_file, overwrite = TRUE)) {
    stop("Could not finalise a total-strategy LOO reduction.",
         call. = FALSE)
  }
  unlink(temporary_file, force = TRUE)
  normalizePath(output_file, winslash = "/", mustWork = TRUE)
}

