# Identify the total-intake strategy candidates that need to be refitted to
# align their observations for model comparison.
make_update_2026_total_strategy_common_sample_specifications <- function(
    specifications,
    integrated_loo_audit
) {
  alignment <- integrated_loo_audit$outcome_summary |>
    dplyr::select(outcome, observation_sets_aligned)
  hypertrophy_counts <- integrated_loo_audit$observation_set_audit |>
    dplyr::filter(outcome == "hypertrophy") |>
    dplyr::count(observations)

  if (
    !identical(integrated_loo_audit$family, "total_strategy") ||
      nrow(alignment) != 4L ||
      alignment$observation_sets_aligned[
        alignment$outcome == "hypertrophy"
      ] ||
      !all(alignment$observation_sets_aligned[
        alignment$outcome != "hypertrophy"
      ]) ||
      integrated_loo_audit$exact_refits_required != 0L ||
      !setequal(hypertrophy_counts$observations, c(412L, 420L)) ||
      any(hypertrophy_counts$n != 9L)
  ) {
    stop(
      "The total-strategy common-sample refit no longer matches its LOO audit.",
      call. = FALSE
    )
  }

  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  selected <- purrr::keep(
    specifications,
    function(specification) {
      identical(specification$outcome, "hypertrophy") &&
        !isTRUE(specification$includes_moderators) &&
        as.integer(specification$model_index) %in% expected_indices
    }
  )

  observed_indices <- sort(unname(
    purrr::map_int(selected, "model_index")
  ))
  if (
    length(selected) != 9L ||
      !identical(observed_indices, expected_indices)
  ) {
    stop("The total-strategy common-sample model set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::map(selected, function(specification) {
    specification$archive_stage <- "common_sample_1"
    specification$common_sample_reason <- paste(
      "Restrict non-moderator hypertrophy strategy candidates to the",
      "412-row body-mass-complete observation set used by moderator",
      "candidates so pointwise predictive densities align for stacking."
    )
    specification
  })

  names(selected) <- paste0(
    "hypertrophy_model_",
    stringr::str_pad(
      purrr::map_int(selected, "model_index"),
      2L,
      pad = "0"
    )
  )

  selected
}

prepare_update_2026_total_strategy_common_sample_input <- function(
    specification,
    data_by_outcome,
    priors_by_outcome
) {
  if (
    !identical(specification$outcome, "hypertrophy") ||
      isTRUE(specification$includes_moderators)
  ) {
    stop(
      "Only non-moderator hypertrophy strategy models need common-sample refits.",
      call. = FALSE
    )
  }

  common_data <- data_by_outcome
  common_data[["hypertrophy"]] <- common_data[["hypertrophy"]] |>
    dplyr::filter(is.finite(mean_body_mass_kg)) |>
    droplevels()
  input <- prepare_update_2026_total_strategy_input(
    specification = specification,
    data_by_outcome = common_data,
    priors_by_outcome = priors_by_outcome
  )
  input$family <- "total_strategy_common_sample"
  input
}

validate_update_2026_total_strategy_common_sample_inputs <- function(
    inputs,
    accepted_fit_manifest,
    integrated_loo_audit
) {
  reference <- integrated_loo_audit$observation_diagnostics |>
    dplyr::filter(outcome == "hypertrophy", model_index == 5L) |>
    dplyr::arrange(observation) |>
    dplyr::transmute(
      study_no = as.character(study_no),
      arm_no = as.integer(arm_no),
      outcome_no = as.integer(outcome_no),
      yi = as.numeric(yi),
      vi = as.numeric(vi)
    )

  if (nrow(reference) != 412L) {
    stop("The total-strategy common-sample reference is invalid.",
         call. = FALSE)
  }
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    observed <- input$data |>
      dplyr::transmute(
        study_no = as.character(study_no),
        arm_no = as.integer(arm_no),
        outcome_no = as.integer(outcome_no),
        yi = as.numeric(yi),
        vi = as.numeric(vi)
      )
    superseded_path <- accepted_fit_manifest |>
      dplyr::filter(
        outcome == specification$outcome,
        model_index == specification$model_index
      ) |>
      dplyr::pull(fit_path)
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      common_observation_set = isTRUE(all.equal(
        observed,
        reference,
        tolerance = 0,
        check.attributes = FALSE
      )),
      adapt_delta = as.numeric(specification$adapt_delta),
      max_treedepth = as.integer(specification$max_treedepth),
      iter_warmup = as.integer(specification$iter_warmup),
      iter_sampling = as.integer(specification$iter_sampling),
      chains = as.integer(specification$chains),
      parallel_chains = as.integer(specification$parallel_chains),
      superseded_fit_exists =
        length(superseded_path) == 1L && file.exists(superseded_path),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(model_index)

  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  if (
    nrow(checks) != 9L ||
      !identical(checks$model_index, expected_indices) ||
      any(checks$contrasts != 412L) || any(checks$studies != 51L) ||
      !all(checks$common_observation_set) ||
      !all(checks$superseded_fit_exists) || !all(checks$valid) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The total-strategy common-sample preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_strategy_common_sample_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "strategy", "common_sample_1", "input_preflight.csv"
    )
) {
  if (
    nrow(checks) != 9L ||
      !all(checks$common_observation_set) || !all(checks$valid)
  ) {
    stop("Cannot write an invalid total-strategy common-sample preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

