validate_update_2026_total_strategy_common_sample_loo_inputs <- function(
    accepted_fit_manifest,
    diagnostic_audit,
    common_sample_preflight,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  checks <- tibble::tribble(
    ~check, ~passed,
    "all nine total-strategy common-sample diagnostics pass",
    isTRUE(diagnostic_audit$all_sampling_diagnostics_pass),
    "accepted registry contains nine common-sample fits",
    nrow(accepted_fit_manifest) == 9L &&
      all(accepted_fit_manifest$stage == "common_sample_1"),
    "all nine fits use the 412-row common observation set",
    nrow(common_sample_preflight) == 9L &&
      all(common_sample_preflight$contrasts == 412L) &&
      all(common_sample_preflight$common_observation_set),
    "all accepted common-sample files exist and are nonempty",
    all(file.exists(accepted_fit_manifest$fit_path)) &&
      all(file.info(accepted_fit_manifest$fit_path)$size > 0),
    "all accepted common-sample hashes are present",
    all(nchar(accepted_fit_manifest$sha256) == 64L),
    "replacement LOO uses a 0.7 threshold and one core per branch",
    identical(as.numeric(k_threshold), 0.7) &&
      identical(as.integer(cores_per_branch), 1L)
  )

  ready <-
    identical(diagnostic_audit$family, "total_strategy_common_sample") &&
    !anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) &&
    all(checks$passed)
  if (!ready) {
    stop("The total-strategy common-sample LOO preflight is incomplete.",
         call. = FALSE)
  }

  list(
    family = "total_strategy_common_sample",
    models = 9L,
    k_threshold = as.numeric(k_threshold),
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    ready = TRUE
  )
}

