write_update_2026_total_strategy_reporting_audit <- function(
    audit,
    prediction_manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "strategy", "reporting"
    )
) {
  if (
    !identical(audit$family, "total_strategy") ||
      !isTRUE(audit$all_reporting_checks_pass) ||
      nrow(audit$summary) != 4L ||
      sum(prediction_manifest$draw_count) != 16000L
  ) {
    stop("The total-strategy reporting audit is incomplete.",
         call. = FALSE)
  }

  reports <- purrr::map(
    audit$summary$reporting_path,
    read_protein_strategy_full_reporting_file,
    family = "total_strategy"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(
      report$model_weights,
      outcome = report$outcome,
      .before = 1L
    )
  })
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    prediction_manifest = file.path(output_dir, "prediction_manifest.csv"),
    dose_response = file.path(output_dir, "dose_response.csv"),
    dose_response_increments = file.path(
      output_dir, "dose_response_increments.csv"
    ),
    exposure_support_by_group = file.path(
      output_dir, "exposure_support_by_group.csv"
    ),
    common_exposure_support = file.path(
      output_dir, "common_exposure_support.csv"
    ),
    addition_minus_substitution = file.path(
      output_dir, "addition_minus_substitution.csv"
    ),
    pairwise_contrasts = file.path(output_dir, "pairwise_contrasts.csv.gz"),
    pairwise_support = file.path(output_dir, "pairwise_support.csv"),
    local_equivalence = file.path(output_dir, "local_equivalence.csv"),
    model_weights = file.path(output_dir, "model_weights.csv")
  )

  readr::write_csv(audit$summary, paths[["summary"]])
  readr::write_csv(prediction_manifest, paths[["prediction_manifest"]])
  readr::write_csv(bind_report("dose_response"), paths[["dose_response"]])
  readr::write_csv(
    bind_report("dose_response_increments"),
    paths[["dose_response_increments"]]
  )
  readr::write_csv(
    bind_report("exposure_support_by_group"),
    paths[["exposure_support_by_group"]]
  )
  readr::write_csv(
    bind_report("common_exposure_support"),
    paths[["common_exposure_support"]]
  )
  readr::write_csv(
    bind_report("addition_minus_substitution"),
    paths[["addition_minus_substitution"]]
  )
  readr::write_csv(
    bind_report("pairwise_contrasts"),
    paths[["pairwise_contrasts"]]
  )
  readr::write_csv(
    bind_report("pairwise_support"),
    paths[["pairwise_support"]]
  )
  readr::write_csv(
    bind_report("local_equivalence"),
    paths[["local_equivalence"]]
  )
  readr::write_csv(model_weights, paths[["model_weights"]])
  unname(paths)
}

make_update_2026_total_strategy_verification_checkpoint <- function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    strategy_audit_review,
    data,
    input_preflight,
    specifications,
    final_fit_manifest,
    diagnostic_audit,
    common_sample_diagnostic_audit,
    integrated_loo_audit,
    common_sample_loo_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  data_by_outcome <- data$principal_by_outcome
  analysis_data <- purrr::imap_dfr(
    data_by_outcome,
    ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
  )
  specification_table <- dplyr::bind_rows(specifications) |>
    dplyr::arrange(factor(outcome, levels = outcomes), model_index)
  registry_keys <- function(table) {
    table |>
      dplyr::distinct(outcome, model_index) |>
      dplyr::arrange(outcome, model_index) |>
      dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
      dplyr::pull(key)
  }
  specification_keys <- registry_keys(specification_table)
  fit_keys <- registry_keys(final_fit_manifest)
  diagnostic_keys <- registry_keys(diagnostic_audit$diagnostic_summary)
  loo_keys <- registry_keys(final_loo_audit$model_summary)
  weight_keys <- registry_keys(stacking_weights)
  common_registry <-
    identical(specification_keys, fit_keys) &&
    identical(specification_keys, diagnostic_keys) &&
    identical(specification_keys, loo_keys) &&
    identical(specification_keys, weight_keys)
  name_alignment <- specification_table |>
    dplyr::select(outcome, model_index, specification_name = model_name) |>
    dplyr::left_join(
      final_fit_manifest |>
        dplyr::select(outcome, model_index, fit_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      diagnostic_audit$diagnostic_summary |>
        dplyr::select(outcome, model_index, diagnostic_name = model),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      final_loo_audit$model_summary |>
        dplyr::select(outcome, model_index, loo_name = model_name),
      by = c("outcome", "model_index")
    ) |>
    dplyr::left_join(
      stacking_weights |>
        dplyr::select(outcome, model_index, weight_name = model_name),
      by = c("outcome", "model_index")
    )

  fit_stage_counts <- table(factor(
    final_fit_manifest$stage,
    levels = c("initial", "remedy_1", "common_sample_1")
  ))
  weight_sums <- stacking_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    )
  prediction_sums <- prediction_manifest |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      draws = sum(draw_count),
      retained_weight = sum(weight),
      .by = outcome
    )
  reports <- purrr::map(
    reporting_audit$summary$reporting_path,
    read_protein_strategy_full_reporting_file,
    family = "total_strategy"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  reporting_model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(
      report$model_weights,
      outcome = report$outcome,
      .before = 1L
    )
  })
  reporting_weight_sums <- reporting_model_weights |>
    dplyr::summarise(
      models = dplyr::n(),
      weight_sum = sum(weight),
      .by = outcome
    )
  initial_observation_counts <- integrated_loo_audit$outcome_summary |>
    dplyr::filter(outcome == "hypertrophy") |>
    dplyr::pull(observation_counts)

  checks <- tibble::tibble(
    check = c(
      "three immutable source files have hashes",
      "the combined-data preparation audit remains valid",
      "the shared absolute-exposure audit remains valid",
      "the confirmed strategy-classification audit remains valid",
      "all four total-strategy datasets and 72 inputs are valid",
      "all five final registries contain the same 72 model keys",
      "model names agree across specifications fits diagnostics LOO and weights",
      "all 72 final fit files exist with 61 initial 2 remedy and 9 common-sample fits",
      "all 72 accepted sampling diagnostics pass",
      "all nine common-sample replacement diagnostics pass",
      "initial LOO contains 72 models no high-k cases and identifies the sample mismatch",
      "replacement LOO contains nine aligned models and no high-k cases",
      "final LOO contains 72 aligned models and no unresolved high-k cases",
      "four stacking vectors contain 18 models and sum to one",
      "prediction allocation contains 4000 draws per outcome",
      "all four total-strategy reporting audits pass"
    ),
    passed = c(
      nrow(source_manifest) == 3L &&
        all(nchar(source_manifest$sha256) == 64L),
      all(preparation_audit$checks$passed),
      all(absolute_audit$checks$passed) &&
        isTRUE(absolute_audit$ready_for_review),
      isTRUE(strategy_audit_review$audit_ready) &&
        strategy_audit_review$pending_confirmations == 0L &&
        all(strategy_audit_review$structural_checks$passed),
      identical(names(data_by_outcome), outcomes) &&
        nrow(input_preflight) == 72L &&
        all(input_preflight$family == "total_strategy") &&
        all(input_preflight$valid) &&
        all(input_preflight$reference_g_day == 78.785) &&
        all(input_preflight$internal_unit_g_day == 50) &&
        setequal(unique(analysis_data$protein_strategy),
                 c("Addition", "Substitution")) &&
        all(is.finite(analysis_data$yi)) &&
        all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0),
      common_registry && length(specification_keys) == 72L,
      nrow(name_alignment) == 72L &&
        all(stats::complete.cases(name_alignment)) &&
        all(name_alignment$fit_name == name_alignment$specification_name) &&
        all(name_alignment$diagnostic_name ==
              name_alignment$specification_name) &&
        all(name_alignment$loo_name == name_alignment$specification_name) &&
        all(name_alignment$weight_name == name_alignment$specification_name),
      nrow(final_fit_manifest) == 72L &&
        identical(as.integer(fit_stage_counts), c(61L, 2L, 9L)) &&
        all(file.exists(final_fit_manifest$fit_path)) &&
        all(final_fit_manifest$bytes > 0) &&
        all(nchar(final_fit_manifest$sha256) == 64L),
      identical(diagnostic_audit$family, "total_strategy") &&
        diagnostic_audit$models == 72L &&
        diagnostic_audit$models_passing_sampling == 72L &&
        isTRUE(diagnostic_audit$all_sampling_diagnostics_pass),
      identical(
        common_sample_diagnostic_audit$family,
        "total_strategy_common_sample"
      ) &&
        common_sample_diagnostic_audit$models == 9L &&
        common_sample_diagnostic_audit$models_passing_sampling == 9L &&
        isTRUE(common_sample_diagnostic_audit$all_sampling_diagnostics_pass),
      identical(integrated_loo_audit$family, "total_strategy") &&
        nrow(integrated_loo_audit$model_summary) == 72L &&
        integrated_loo_audit$exact_refits_required == 0L &&
        nrow(integrated_loo_audit$high_k_cases) == 0L &&
        length(initial_observation_counts) == 1L &&
        identical(unname(initial_observation_counts), "412,420"),
      identical(
        common_sample_loo_audit$family,
        "total_strategy_common_sample"
      ) &&
        common_sample_loo_audit$models == 9L &&
        common_sample_loo_audit$observations_per_model == 412L &&
        isTRUE(common_sample_loo_audit$observation_sets_aligned) &&
        common_sample_loo_audit$exact_refits_required == 0L &&
        isTRUE(common_sample_loo_audit$stacking_ready),
      identical(final_loo_audit$family, "total_strategy") &&
        nrow(final_loo_audit$model_summary) == 72L &&
        final_loo_audit$exact_refits == 0L &&
        nrow(final_loo_audit$high_k_cases) == 0L &&
        isTRUE(final_loo_audit$stacking_ready) &&
        all(final_loo_audit$outcome_summary$observation_sets_aligned),
      nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
        all(abs(weight_sums$weight_sum - 1) < 1e-8),
      nrow(prediction_sums) == 4L &&
        all(prediction_sums$selected_models >= 1L) &&
        all(prediction_sums$draws == 4000L) &&
        all(prediction_sums$retained_weight > 0) &&
        all(prediction_sums$retained_weight <= 1 + 1e-8) &&
        all(file.exists(prediction_manifest$prediction_path)) &&
        all(prediction_manifest$bytes > 0) &&
        all(nchar(prediction_manifest$sha256) == 64L),
      identical(reporting_audit$family, "total_strategy") &&
        isTRUE(reporting_audit$all_reporting_checks_pass) &&
        nrow(reporting_audit$summary) == 4L &&
        all(reporting_audit$summary$intervals_valid) &&
        all(reporting_audit$summary$reference_increment_valid) &&
        all(reporting_audit$summary$probabilities_valid) &&
        all(reporting_audit$summary$diagonal_contrasts_valid) &&
        nrow(reporting_model_weights) == 72L &&
        all(reporting_weight_sums$models == 18L) &&
        all(abs(reporting_weight_sums$weight_sum - 1) < 1e-8)
    )
  )

  failed <- is.na(checks$passed) | !checks$passed
  if (any(failed)) {
    stop(
      "Absolute total-strategy verification failed: ",
      paste(checks$check[failed], collapse = "; "),
      call. = FALSE
    )
  }

  artifacts <- list(
    verification_checks = checks,
    source_manifest = source_manifest,
    preparation_checks = preparation_audit$checks,
    preparation_outcome_counts = preparation_audit$outcome_counts,
    absolute_exposure_checks = absolute_audit$checks,
    absolute_outcome_coverage = absolute_audit$outcome_coverage,
    strategy_review_rows = strategy_audit_review$review_rows,
    strategy_review_status = strategy_audit_review$status_summary,
    strategy_structural_checks = strategy_audit_review$structural_checks,
    input_preflight = input_preflight,
    analysis_data = analysis_data,
    model_specifications = specification_table,
    model_name_alignment = name_alignment,
    final_fit_manifest = final_fit_manifest,
    sampling_diagnostic_summary = diagnostic_audit$diagnostic_summary,
    sampling_parameter_failures = diagnostic_audit$parameter_failures,
    common_sample_diagnostic_summary =
      common_sample_diagnostic_audit$diagnostic_summary,
    common_sample_parameter_failures =
      common_sample_diagnostic_audit$parameter_failures,
    initial_loo_model_summary = integrated_loo_audit$model_summary,
    initial_loo_outcome_summary = integrated_loo_audit$outcome_summary,
    initial_high_pareto_k_cases = integrated_loo_audit$high_k_cases,
    common_sample_loo_model_summary = common_sample_loo_audit$model_summary,
    common_sample_high_pareto_k_cases = common_sample_loo_audit$high_k_cases,
    final_loo_manifest = final_loo_audit$final_loo_manifest,
    final_loo_model_summary = final_loo_audit$model_summary,
    final_loo_outcome_summary = final_loo_audit$outcome_summary,
    final_high_pareto_k_cases = final_loo_audit$high_k_cases,
    stacking_weights = stacking_weights,
    prediction_allocation_manifest = prediction_manifest,
    reporting_file_manifest = reporting_audit$summary,
    reporting_model_weights = reporting_model_weights,
    dose_response_predictions = bind_report("dose_response"),
    dose_response_increments = bind_report("dose_response_increments"),
    exposure_support_by_group = bind_report("exposure_support_by_group"),
    common_exposure_support = bind_report("common_exposure_support"),
    addition_minus_substitution = bind_report("addition_minus_substitution"),
    pairwise_contrasts = bind_report("pairwise_contrasts"),
    pairwise_support = bind_report("pairwise_support"),
    local_equivalence = bind_report("local_equivalence")
  )

  descriptions <- stats::setNames(
    paste("Frozen absolute total-strategy artifact:", names(artifacts)),
    names(artifacts)
  )
  list(checks = checks, artifacts = artifacts, descriptions = descriptions)
}

make_update_2026_total_strategy_pruning_plan <- function(
    final_fit_manifest,
    prediction_manifest,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "strategy"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification", "total_strategy_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (length(verification_files) != 41L ||
      any(!file.exists(verification_files))) {
    stop("The absolute total-strategy verification bundle is incomplete.",
         call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "strategy"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the total-strategy archive.",
         call. = FALSE)
  }
  fit_roots <- file.path(
    archive_root,
    c("initial", "remedy_1", "common_sample_1")
  )

  if (any(!dir.exists(fit_roots))) {
    stop("An expected total-strategy fit directory is missing.",
         call. = FALSE)
  }
  fit_paths <- unlist(purrr::map(
    fit_roots,
    ~ list.files(.x, pattern = "\\.qs$", recursive = TRUE,
                 full.names = TRUE)
  ), use.names = FALSE) |>
    normalizePath(winslash = "/", mustWork = TRUE)
  relative_fit_paths <- substring(fit_paths, nchar(resolved_root) + 2L)
  fit_match <- stringr::str_match(
    relative_fit_paths,
    "^(initial|remedy_1|common_sample_1)/([^/]+)/model_([0-9]+)\\.qs$"
  )
  accepted_paths <- normalizePath(
    final_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  model_fit_manifest <- tibble::tibble(
    path = fit_paths,
    relative_path = relative_fit_paths,
    archive_stage = fit_match[, 2L],
    outcome = fit_match[, 3L],
    model_index = as.integer(fit_match[, 4L]),
    accepted_fit = fit_paths %in% accepted_paths,
    bytes = as.numeric(file.info(fit_paths)$size),
    lean_action = "delete frozen absolute total-strategy model fit archive"
  ) |>
    dplyr::arrange(archive_stage, outcome, model_index)

  stage_counts <- table(factor(
    model_fit_manifest$archive_stage,
    levels = c("initial", "remedy_1", "common_sample_1")
  ))
  accepted_stage_counts <- table(factor(
    model_fit_manifest$archive_stage[model_fit_manifest$accepted_fit],
    levels = c("initial", "remedy_1", "common_sample_1")
  ))

  if (
    nrow(model_fit_manifest) != 83L ||
      !identical(as.integer(stage_counts), c(72L, 2L, 9L)) ||
      sum(model_fit_manifest$accepted_fit) != 72L ||
      sum(!model_fit_manifest$accepted_fit) != 11L ||
      !identical(as.integer(accepted_stage_counts), c(61L, 2L, 9L)) ||
      anyNA(model_fit_manifest[c("archive_stage", "outcome", "model_index")]) ||
      any(model_fit_manifest$bytes <= 0)
  ) {
    stop("The absolute total-strategy fit inventory is invalid.",
         call. = FALSE)
  }

  deletion_manifest <- model_fit_manifest |>
    dplyr::transmute(
      path,
      relative_path,
      archive_stage,
      artifact_role = dplyr::if_else(
        accepted_fit,
        "accepted_model_fit",
        "superseded_model_fit"
      ),
      outcome,
      model_index,
      file_type = "fit_object",
      bytes,
      lean_action
    )

  compact_roots <- c(
    loo = file.path(archive_root, "loo"),
    reporting = file.path(archive_root, "reporting")
  )
  if (any(!dir.exists(compact_roots))) {
    stop("An expected compact total-strategy directory is missing.",
         call. = FALSE)
  }

  compact_paths <- unlist(purrr::map(compact_roots, function(root) {
    list.files(root, recursive = TRUE, full.names = TRUE, all.files = TRUE)
  }), use.names = FALSE)
  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  normalized_compact_roots <- normalizePath(
    compact_roots,
    winslash = "/",
    mustWork = TRUE
  )
  component <- vapply(compact_paths, function(path) {
    matches <- names(compact_roots)[vapply(
      normalized_compact_roots,
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact absolute total-strategy result"
  ) |>
    dplyr::arrange(archive_component, relative_path)

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo", "reporting")
  ))
  expected_reporting_files <- nrow(prediction_manifest) + 8L
  if (
    !identical(as.integer(compact_counts),
               c(81L, expected_reporting_files)) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact absolute total-strategy archive is incomplete.",
         call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    model_fit_archives_deleted = nrow(model_fit_manifest),
    accepted_model_fit_archives_deleted =
      sum(model_fit_manifest$accepted_fit),
    superseded_model_fit_archives_deleted =
      sum(!model_fit_manifest$accepted_fit),
    exact_refit_archives_deleted = 0L,
    archive_files_deleted = nrow(deletion_manifest),
    fit_archive_files_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained = sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, aligned integrated LOO, and all 72 weights remain",
      "frozen; restoring model objects requires refitting the absolute",
      "total-intake strategy family."
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_fit_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = normalizePath(
      verification_manifest,
      winslash = "/",
      mustWork = TRUE
    ),
    archive_root = resolved_root
  )
}

write_update_2026_total_strategy_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "strategy", "pruning"
    )
) {
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    deletion_file_manifest = file.path(output_dir, "deletion_file_manifest.csv"),
    compact_archive_manifest = file.path(output_dir, "compact_archive_manifest.csv")
  )
  readr::write_csv(plan$summary, paths[["summary"]], na = "")
  readr::write_csv(
    plan$model_fit_manifest,
    paths[["model_fit_manifest"]],
    na = ""
  )
  readr::write_csv(
    plan$deletion_file_manifest,
    paths[["deletion_file_manifest"]],
    na = ""
  )
  readr::write_csv(
    plan$compact_archive_manifest,
    paths[["compact_archive_manifest"]],
    na = ""
  )
  unname(paths)
}

# Strict within-study comparisons by total-intake strategy ----

# Prepare the total-intake contrasts and carry the strategy label used by the
# interaction models.
make_update_2026_total_strategy_within_data_by_outcome <- function(
    total_within_data_by_outcome,
    strategy_audit
) {
  outcomes <- c("whole_body", "hypertrophy", "strength", "function")
  if (!identical(names(total_within_data_by_outcome), outcomes)) {
    stop("The total within-study outcome registry is incomplete.",
         call. = FALSE)
  }

  output <- purrr::map(
    total_within_data_by_outcome,
    prepare_protein_strategy_within_data,
    audit = strategy_audit,
    analysis = "principal"
  )
  valid <- purrr::map_lgl(output, function(data) {
    nrow(data) > 0L &&
      setequal(unique(data$protein_strategy),
               c("Addition", "Substitution")) &&
      all(data$strategy_code %in% c(0, 1)) &&
      all(is.finite(data$yi)) &&
      all(is.finite(data$vi)) && all(data$vi > 0) &&
      all(is.finite(data$protein_intake_raw_treatment)) &&
      all(is.finite(data$protein_intake_raw_comparator)) &&
      all(data$absolute_exposure_reference_g_day == 78.785) &&
      all(data$absolute_exposure_unit_g_day == 50)
  })

  if (!all(valid)) {
    stop("An absolute total strategy-within dataset is invalid.",
         call. = FALSE)
  }
  output
}

make_update_2026_total_strategy_within_specifications <- function(
    total_within_specifications
) {
  specifications <- purrr::map(total_within_specifications, function(spec) {
    spec$family <- "total_strategy_within"
    spec$model_name <- paste0(spec$model_name, " [strategy]")
    spec$includes_strategy_contrast_interaction <-
      !as.integer(spec$model_index) %in% c(1L, 5L)
    spec
  })
  registry <- dplyr::bind_rows(specifications)
  keys <- paste(registry$outcome, registry$model_index, sep = "::")
  counts <- table(factor(
    registry$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  schedules <- table(factor(
    registry$historical_schedule,
    levels = c("base", "longer_sampling")
  ))

  if (
    length(specifications) != 72L || anyDuplicated(keys) ||
      !identical(as.integer(counts), rep(18L, 4L)) ||
      !identical(as.integer(schedules), c(68L, 4L)) ||
      any(registry$family != "total_strategy_within")
  ) {
    stop("The absolute total strategy-within registry is invalid.",
         call. = FALSE)
  }

  names(specifications) <- paste0(
    registry$outcome,
    "_model_",
    stringr::str_pad(registry$model_index, 2L, pad = "0")
  )
  specifications
}

prepare_update_2026_total_strategy_within_input <- function(
    specification,
    contrast_data_by_outcome,
    priors_by_outcome,
    config
) {
  input <- prepare_update_2026_total_within_input(
    specification = specification,
    contrast_data_by_outcome = contrast_data_by_outcome,
    priors_by_outcome = priors_by_outcome,
    config = config
  )
  input$formula <- make_protein_strategy_within_formula(
    formula = input$formula,
    model_index = as.integer(specification$model_index),
    contrast_names = input$contrast_names
  )
  input$family <- "total_strategy_within"
  input$specification$family <- "total_strategy_within"
  input$specification$formula <- input$formula
  input$specification$sensitivity_strategy_interaction <- TRUE
  input$specification$sensitivity_within_contrast <- TRUE
  input$strategy_reference <- "Substitution"
  input
}

validate_update_2026_total_strategy_within_inputs <- function(
    inputs,
    config
) {
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    local_config <- update_2026_total_within_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    includes_protein <- !as.integer(specification$model_index) %in% c(1L, 5L)
    contrast_names <- input$contrast_names
    interactions_valid <- if (includes_protein) {
      length(contrast_names) > 0L && all(vapply(
        contrast_names,
        function(name) grepl(
          paste0(name, ":strategy_code"),
          input$formula,
          fixed = TRUE
        ),
        logical(1L)
      ))
    } else {
      is.null(contrast_names)
    }
    tibble::tibble(
      family = input$family,
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      historical_schedule = specification$historical_schedule,
      includes_moderators = isTRUE(specification$includes_moderators),
      body_mass_in_formula =
        stringr::str_detect(input$formula, "\\bbody_mass_outcome_z\\b"),
      strategy_main_in_formula =
        stringr::str_detect(input$formula, "\\bstrategy_code\\b"),
      strategy_interactions_valid = interactions_valid,
      contrasts = nrow(input$data),
      studies = dplyr::n_distinct(input$data$study_no),
      addition_studies = dplyr::n_distinct(
        input$data$study_no[input$data$protein_strategy == "Addition"]
      ),
      substitution_studies = dplyr::n_distinct(
        input$data$study_no[input$data$protein_strategy == "Substitution"]
      ),
      exposure_minimum_g_day = min(c(
        input$data$protein_intake_raw_treatment,
        input$data$protein_intake_raw_comparator
      )),
      exposure_maximum_g_day = max(c(
        input$data$protein_intake_raw_treatment,
        input$data$protein_intake_raw_comparator
      )),
      reference_g_day = unique(
        input$data$absolute_exposure_reference_g_day
      ),
      internal_unit_g_day = unique(
        input$data$absolute_exposure_unit_g_day
      ),
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  outcome_counts <- table(factor(
    checks$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  schedule_counts <- table(factor(
    checks$historical_schedule,
    levels = c("base", "longer_sampling")
  ))
  moderator_formula_valid <-
    checks$body_mass_in_formula == checks$includes_moderators

  if (
    nrow(checks) != 72L || anyDuplicated(keys) ||
      !identical(as.integer(outcome_counts), rep(18L, 4L)) ||
      !identical(as.integer(schedule_counts), c(68L, 4L)) ||
      any(checks$family != "total_strategy_within") ||
      !all(checks$strategy_main_in_formula) ||
      !all(checks$strategy_interactions_valid) ||
      !all(moderator_formula_valid) ||
      any(checks$addition_studies < 1L) ||
      any(checks$substitution_studies < 1L) ||
      any(checks$reference_g_day != 78.785) ||
      any(checks$internal_unit_g_day != 50) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L)
  ) {
    stop("The absolute total strategy-within preflight failed.",
         call. = FALSE)
  }

  checks
}

write_update_2026_total_strategy_within_input_preflight <- function(
    preflight,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "strategy_within", "input_preflight.csv"
    )
) {
  if (nrow(preflight) != 72L || !all(preflight$valid)) {
    stop("Cannot write an invalid total strategy-within preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(preflight, output_file, na = "")
  output_file
}

fit_update_2026_total_strategy_within_candidate_to_file <- function(
    input,
    config,
    enabled,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure", "total_g_day",
      "strategy_within", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop("Absolute total strategy-within fitting is disabled.",
         call. = FALSE)
  }
  local_config <- update_2026_total_within_local_config(
    input$specification,
    config
  )
  candidate <- fit_sensitivity_brms_pilot(
    input = input,
    enabled = TRUE,
    config = local_config,
    family = "total_strategy_within"
  )
  output_dir <- file.path(output_root, candidate$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d.qs", as.integer(candidate$model_index))
  )
  write_atomic_qs(candidate, output_file)
}

make_update_2026_total_strategy_within_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))

  if (
    !identical(diagnostic_audit$family, "total_strategy_within") ||
      nrow(failed) != 1L || failed$key[[1L]] != "strength::26" ||
      !isTRUE(failed$geometry_pass[[1L]]) ||
      isTRUE(failed$convergence_pass[[1L]]) ||
      failed$divergent_transitions[[1L]] != 0 ||
      failed$maximum_treedepth_transitions[[1L]] != 0L
  ) {
    stop("The total strategy-within remedy set no longer matches its audit.",
         call. = FALSE)
  }

  keys <- purrr::map_chr(
    specifications,
    ~ paste(.x$outcome, .x$model_index, sep = "::")
  )
  selected <- specifications[match("strength::26", keys)]
  if (length(selected) != 1L || is.null(selected[[1L]])) {
    stop("Could not select the total strategy-within remedy model.",
         call. = FALSE)
  }

  selected <- purrr::map(selected, function(specification) {
    specification$adapt_delta <- max(
      as.numeric(specification$adapt_delta),
      0.999
    )
    specification$max_treedepth <- max(
      as.integer(specification$max_treedepth),
      15L
    )
    specification$iter_warmup <- 3000L
    specification$iter_sampling <- 8000L
    specification$remedy <- "longer_sampling_after_low_ess"
    specification$archive_stage <- "remedy_1"
    specification$remedy_reason <- paste(
      "Sampling geometry passed, but R-hat, effective sample-size, and",
      "Monte Carlo standard-error thresholds were not all met."
    )
    specification
  })

  names(selected) <- "strength_model_26"
  selected
}

validate_update_2026_total_strategy_within_remedy_inputs <- function(
    inputs,
    initial_fit_paths,
    config
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    initial_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    local_config <- update_2026_total_within_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      initial_fit_exists =
        length(initial_path) == 1L && file.exists(initial_path),
      valid = TRUE
    )
  })

  if (
    nrow(checks) != 1L || checks$outcome[[1L]] != "strength" ||
      checks$model_index[[1L]] != 26L ||
      checks$adapt_delta[[1L]] < 0.999 ||
      checks$max_treedepth[[1L]] < 15L ||
      checks$iter_warmup[[1L]] != 3000L ||
      checks$iter_sampling[[1L]] != 8000L ||
      checks$chains[[1L]] != 4L || checks$parallel_chains[[1L]] != 4L ||
      !checks$initial_fit_exists[[1L]]
  ) {
    stop("The total strategy-within remedy preflight is invalid.",
         call. = FALSE)
  }

  checks
}

