compute_update_2026_total_strategy_within_correction_to_file <- function(
    exact_fit_path,
    diagnostic_audit,
    enabled
) {
  if (!isTRUE(enabled)) {
    stop("Total strategy-within exact correction is disabled.",
         call. = FALSE)
  }

  refit <- read_sensitivity_full_exact_loo_file(
    exact_fit_path,
    "total_strategy_within"
  )
  output_file <-
    update_2026_total_strategy_within_correction_file_path(refit)

  if (file.exists(output_file) && file.info(output_file)$size > 0) {
    archived <- tryCatch(qs::qread(output_file), error = function(error) NULL)
    if (
      !is.null(archived) && inherits(archived$loo, "loo") &&
        as.integer(archived$case_id) == as.integer(refit$case_id) &&
        identical(archived$outcome, refit$outcome) &&
        as.integer(archived$model_index) == as.integer(refit$model_index) &&
        as.integer(archived$exact_refit_summary$observation[[1L]]) ==
          as.integer(refit$observation)
    ) {
      return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
    }
    stop("An existing total strategy-within correction is invalid.",
         call. = FALSE)
  }

  correction <- compute_sensitivity_full_exact_loo_file(
    path = exact_fit_path,
    diagnostic_audit = diagnostic_audit,
    family = "total_strategy_within"
  )
  if (
    !inherits(correction$loo, "loo") ||
      as.integer(correction$case_id) != as.integer(refit$case_id) ||
      nrow(correction$exact_refit_summary) != 1L ||
      !isTRUE(correction$exact_refit_summary$diagnostic_pass[[1L]])
  ) {
    stop("The total strategy-within exact correction is invalid.",
         call. = FALSE)
  }

  write_atomic_qs(correction, output_file)
}

audit_update_2026_total_strategy_within_corrections <- function(
    paths,
    integrated_audit
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  expected <- as.integer(integrated_audit$exact_refits_required)

  if (
    length(paths) != expected || expected != 49L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The total strategy-within exact corrections are incomplete.",
         call. = FALSE)
  }

  corrections <- purrr::map(paths, qs::qread)
  diagnostic_summary <- purrr::map_dfr(
    corrections,
    "exact_refit_summary"
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )

  manifest <- purrr::map2_dfr(paths, corrections, function(path, result) {
    tibble::tibble(
      case_id = as.integer(result$case_id),
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      model_name = result$model_name,
      observation =
        as.integer(result$exact_refit_summary$observation[[1L]]),
      correction_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      bytes = file.info(path)$size,
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    manifest$outcome,
    manifest$model_index,
    manifest$observation,
    sep = "::"
  )
  expected_keys <- paste(
    integrated_audit$high_k_cases$outcome,
    integrated_audit$high_k_cases$model_index,
    integrated_audit$high_k_cases$observation,
    sep = "::"
  )

  if (
    nrow(diagnostic_summary) != 49L || nrow(manifest) != 49L ||
      anyDuplicated(observed_keys) || !setequal(observed_keys, expected_keys) ||
      !identical(manifest$case_id, seq_len(49L)) ||
      !all(diagnostic_summary$diagnostic_pass)
  ) {
    stop("The total strategy-within correction audit is invalid.",
         call. = FALSE)
  }

  list(
    family = "total_strategy_within",
    diagnostic_summary = diagnostic_summary,
    correction_manifest = manifest,
    exact_refits = 49L,
    exact_refits_passing = sum(diagnostic_summary$diagnostic_pass),
    exact_refits_requiring_remediation =
      sum(!diagnostic_summary$diagnostic_pass),
    all_exact_refit_diagnostics_pass =
      all(diagnostic_summary$diagnostic_pass)
  )
}

write_update_2026_total_strategy_within_correction_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "strategy_within", "loo_exact", "corrections"
    )
) {
  if (
    audit$exact_refits != 49L ||
      nrow(audit$diagnostic_summary) != 49L ||
      nrow(audit$correction_manifest) != 49L
  ) {
    stop("Cannot write an incomplete total strategy-within correction audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    correction_manifest = file.path(output_dir, "correction_manifest.csv")
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$correction_manifest,
    paths[["correction_manifest"]],
    na = ""
  )
  unname(paths)
}

read_update_2026_total_strategy_within_corrections <- function(manifest) {
  if (
    !is.data.frame(manifest) || nrow(manifest) != 49L ||
      any(!file.exists(manifest$correction_path))
  ) {
    stop("The total strategy-within correction manifest is invalid.",
         call. = FALSE)
  }

  corrections <- purrr::map(manifest$correction_path, qs::qread)
  corrections <- corrections[order(purrr::map_int(corrections, "case_id"))]
  if (
    !identical(unname(purrr::map_int(corrections, "case_id")),
               seq_len(49L)) ||
      any(!purrr::map_lgl(corrections, ~ inherits(.x$loo, "loo")))
  ) {
    stop("The total strategy-within exact corrections are invalid.",
         call. = FALSE)
  }

  corrections
}

make_update_2026_total_strategy_within_final_loo_audit <- function(
    integrated_manifest,
    exact_corrections,
    exact_audit
) {
  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (!isTRUE(exact_audit$all_exact_refit_diagnostics_pass)) {
    stop("Final total strategy-within LOO requires passing exact refits.",
         call. = FALSE)
  }
  final <- apply_sensitivity_full_exact_loo_corrections_from_files(
    integrated_manifest = integrated_manifest,
    exact_results = exact_corrections,
    family = "total_strategy_within",
    expected_models = 72L,
    expected_indices = retained
  )
  outcome_summary <- final$model_summary |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_unresolved_high_k =
        sum(n_pareto_k_gt_threshold > 0L),
      unresolved_high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_remaining_pareto_k = max(maximum_pareto_k, na.rm = TRUE),
      .by = outcome
    )

  correction_counts <- exact_audit$diagnostic_summary |>
    dplyr::count(outcome, model_index, name = "exact_corrections")
  final_manifest <- integrated_manifest |>
    dplyr::left_join(
      correction_counts,
      by = c("outcome", "model_index")
    ) |>
    dplyr::mutate(
      exact_corrections = tidyr::replace_na(exact_corrections, 0L),
      final_method = dplyr::if_else(
        exact_corrections > 0L,
        "integrated_observation_level_psis_plus_exact",
        "integrated_observation_level_psis"
      )
    )

  if (
    !isTRUE(final$stacking_ready) || nrow(final$model_summary) != 72L ||
      nrow(outcome_summary) != 4L || any(outcome_summary$models != 18L) ||
      any(outcome_summary$unresolved_high_k_cases != 0L) ||
      nrow(final_manifest) != 72L ||
      sum(final_manifest$exact_corrections) != 49L
  ) {
    stop("The final total strategy-within LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  final$family <- "total_strategy_within"
  final$outcome_summary <- outcome_summary
  final$final_loo_manifest <- final_manifest
  final$exact_refits <- 49L
  final$all_exact_refit_diagnostics_pass <- TRUE
  final
}

write_update_2026_total_strategy_within_final_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "total_g_day",
      "strategy_within", "loo_final"
    )
) {
  if (
    !isTRUE(audit$stacking_ready) ||
      nrow(audit$model_summary) != 72L ||
      nrow(audit$outcome_summary) != 4L ||
      nrow(audit$exact_refit_summary) != 49L ||
      nrow(audit$final_loo_manifest) != 72L
  ) {
    stop("Cannot write an incomplete final total strategy-within LOO audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    final_loo_manifest = file.path(output_dir, "final_loo_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    exact_refit_summary = file.path(output_dir, "exact_refit_summary.csv")
  )
  readr::write_csv(audit$final_loo_manifest, paths[["final_loo_manifest"]])
  readr::write_csv(audit$model_summary, paths[["model_summary"]])
