write_update_2026_supplement_strategy_common_sample_diagnostic_audit <-
  function(
      audit,
      output_dir = here::here(
        "results", "update_2026", "absolute_exposure", "supplement_g_day",
        "strategy", "common_sample_1", "diagnostics"
      )
  ) {
    if (!identical(audit$family, "supplement_strategy_common_sample")) {
