validate_update_2026_supplement_strategy_common_sample_loo_inputs <-
  function(
      accepted_fit_manifest,
      diagnostic_audit,
      common_sample_preflight,
      k_threshold = 0.7,
      cores_per_branch = 1L
  ) {
    outcome_counts <- table(accepted_fit_manifest$outcome)
    expected_rows <- c(
      whole_body = 217L,
      hypertrophy = 336L,
      strength = 577L,
      `function` = 219L
    )
    checks <- tibble::tribble(
      ~check, ~passed,
      "all 36 supplement-strategy common-sample diagnostics pass",
      identical(
        diagnostic_audit$family,
        "supplement_strategy_common_sample"
      ) && isTRUE(diagnostic_audit$all_sampling_diagnostics_pass),
      "accepted registry contains nine replacements per outcome",
      length(outcome_counts) == 4L && all(outcome_counts == 9L),
      "all 36 replacements use their outcome common observation set",
      nrow(common_sample_preflight) == 36L &&
        all(common_sample_preflight$common_observation_set) &&
        all(
          common_sample_preflight$contrasts ==
            expected_rows[common_sample_preflight$outcome]
        ),
      "all accepted replacement files exist and are nonempty",
      all(file.exists(accepted_fit_manifest$fit_path)) &&
        all(file.info(accepted_fit_manifest$fit_path)$size > 0),
      "all accepted replacement hashes are present",
      all(nchar(accepted_fit_manifest$sha256) == 64L),
      "common-sample LOO uses a 0.7 threshold and one core per branch",
      identical(as.numeric(k_threshold), 0.7) &&
        identical(as.integer(cores_per_branch), 1L)
    )
    ready <-
      nrow(accepted_fit_manifest) == 36L &&
      !anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) &&
      all(accepted_fit_manifest$stage == "common_sample_1") &&
      all(checks$passed)
    if (!ready) {
      stop("The supplement-strategy common-sample LOO preflight is incomplete.",
           call. = FALSE)
    }
    list(
      family = "supplement_strategy_common_sample",
      models = 36L,
      k_threshold = as.numeric(k_threshold),
      cores_per_branch = as.integer(cores_per_branch),
      checks = checks,
      accepted_fit_manifest = accepted_fit_manifest,
      ready = TRUE
    )
  }

