update_2026_supplement_strategy_common_sample_loo_file_path <- function(
    outcome,
    model_index
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "strategy", "loo", "common_sample_final", outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf("model_%02d_integrated_loo.qs", as.integer(model_index))
  )
}

compute_update_2026_supplement_strategy_common_sample_loo_to_file <-
  function(
      record,
      enabled,
      cores = 1L,
      k_threshold = 0.7
  ) {
    expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
    if (!isTRUE(enabled)) {
      stop(
        "Supplement-strategy common-sample LOO is disabled. Set ",
        "PROTEIN_UPDATE_2026_SUPPLEMENT_STRATEGY_COMMON_SAMPLE_LOO=run.",
        call. = FALSE
      )
    }
    if (
      !file.exists(record$fit_path) ||
        !record$outcome %in%
          c("whole_body", "hypertrophy", "strength", "function") ||
        !record$model_index %in% expected_indices
    ) {
      stop("A supplement-strategy common-sample LOO record is invalid.",
           call. = FALSE)
    }
    candidate <- qs::qread(record$fit_path)
    if (
      !identical(candidate$outcome, record$outcome) ||
        as.integer(candidate$model_index) != record$model_index ||
        !identical(
          candidate$specification$family,
          "supplement_strategy_common_sample"
        )
    ) {
      stop("A supplement-strategy common-sample fit does not match its LOO record.",
           call. = FALSE)
    }
    initial <- compute_primary_candidate_psis_loo(
      fitted_candidate = candidate,
      cores = cores,
      save_psis = FALSE
    )
    integrated <- compute_primary_candidate_integrated_psis_loo(
      fitted_candidate = candidate,
      initial_loo_result = initial,
      k_threshold = k_threshold,
      cores = cores
    )
    integrated$fit_path <- normalizePath(
      record$fit_path,
      winslash = "/",
      mustWork = TRUE
    )
    integrated$fit_stage <- record$fit_stage
    output_file <-
      update_2026_supplement_strategy_common_sample_loo_file_path(
        record$outcome,
        record$model_index
      )
    temporary_file <- paste0(output_file, ".tmp-", Sys.getpid())
    on.exit(unlink(temporary_file, force = TRUE), add = TRUE)
    qs::qsave(integrated, temporary_file, preset = "high")
    if (!file.copy(temporary_file, output_file, overwrite = TRUE)) {
      stop("Could not finalise a supplement-strategy common-sample LOO reduction.",
           call. = FALSE)
    }
    unlink(temporary_file, force = TRUE)
    normalizePath(output_file, winslash = "/", mustWork = TRUE)
  }

audit_update_2026_supplement_strategy_common_sample_loo_files <- function(
    paths,
    k_threshold = 0.7
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  if (
    length(paths) != 36L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The supplement-strategy common-sample LOO files are incomplete.",
         call. = FALSE)
  }

  results <- purrr::map(paths, qs::qread)
  expected_indices <- c(1L, 2L, 4L, 9L, 11L, 15L, 17L, 21L, 23L)
  expected_rows <- c(
    whole_body = 217L,
    hypertrophy = 336L,
    strength = 577L,
    `function` = 219L
  )
  keys <- purrr::map_chr(
    results,
    ~ paste(.x$outcome, .x$model_index, sep = "|")
  )
  expected_keys <- as.vector(outer(
    names(expected_rows),
    expected_indices,
    function(outcome, model_index) paste(outcome, model_index, sep = "|")
  ))
  valid <- purrr::map_lgl(results, function(result) {
    inherits(result$loo, "loo") &&
      identical(result$remedy, "integrated_observation_level_psis") &&
      result$outcome %in% names(expected_rows) &&
      result$model_index %in% expected_indices &&
      nrow(result$observation_manifest) == expected_rows[[result$outcome]] &&
      nrow(result$loo$pointwise) == expected_rows[[result$outcome]]
  })

  observation_set_audit <- purrr::map_dfr(results, function(result) {
    manifest <- result$observation_manifest |>
      dplyr::mutate(
        dplyr::across(where(is.factor), as.character),
        study_no = as.character(study_no)
      )
    tibble::tibble(
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      observations = nrow(manifest),
      observation_set_sha256 = digest::digest(manifest, algo = "sha256")
    )
  })

  alignment <- observation_set_audit |>
    dplyr::summarise(
      models = dplyr::n(),
      observations = dplyr::first(observations),
      observation_sets_aligned =
        dplyr::n_distinct(observation_set_sha256) == 1L,
      .by = outcome
    )

  if (
    !all(valid) || anyDuplicated(keys) || !setequal(keys, expected_keys) ||
      nrow(alignment) != 4L || any(alignment$models != 9L) ||
      !all(alignment$observation_sets_aligned)
  ) {
    stop("The supplement-strategy common-sample LOO set is invalid.",
         call. = FALSE)
  }

  method_comparison <- purrr::map_dfr(results, "comparison")
  observation_diagnostics <- purrr::map_dfr(
    results,
    "observation_diagnostics"
  )
  model_summary <- method_comparison |>
    dplyr::filter(method == "integrated_observation_level_psis") |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  high_k_cases <- observation_diagnostics |>
    dplyr::filter(integrated_pareto_k > k_threshold) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index,
      observation
    )

  outcome_summary <- model_summary |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_high_k = sum(n_pareto_k_gt_threshold > 0L),
      high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_pareto_k = max(maximum_pareto_k),
      compute_hours = sum(compute_seconds) / 3600,
      .by = outcome
    ) |>
    dplyr::left_join(alignment, by = c("outcome", "models")) |>
    dplyr::mutate(
      stacking_ready = high_k_cases == 0L & observation_sets_aligned
    )

  reduction_manifest <- purrr::map2_dfr(
    paths,
    results,
    function(path, result) {
      tibble::tibble(
        outcome = result$outcome,
        model_index = as.integer(result$model_index),
        model_name = result$model_name,
        fit_stage = result$fit_stage,
        fit_path = result$fit_path,
        integrated_loo_path = normalizePath(
          path,
          winslash = "/",
          mustWork = TRUE
        ),
        bytes = file.info(path)$size,
        sha256 = digest::digest(
          file = path,
          algo = "sha256",
          serialize = FALSE
        )
      )
    }
  ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  if (
    nrow(model_summary) != 36L || nrow(method_comparison) != 72L ||
      nrow(observation_set_audit) != 36L ||
      nrow(reduction_manifest) != 36L
  ) {
    stop("The supplement-strategy common-sample LOO audit is incomplete.",
         call. = FALSE)
  }

  list(
    family = "supplement_strategy_common_sample",
    reduction_manifest = reduction_manifest,
    model_summary = model_summary,
    outcome_summary = outcome_summary,
    method_comparison = method_comparison,
    observation_diagnostics = observation_diagnostics,
    observation_set_audit = observation_set_audit,
    high_k_cases = high_k_cases,
    models = 36L,
    observation_sets_aligned = TRUE,
    exact_refits_required = nrow(high_k_cases),
    stacking_ready = nrow(high_k_cases) == 0L,
    k_threshold = k_threshold
  )
}

