audit_update_2026_supplement_strategy_aligned_loo <- function(
    aligned_loo_manifest,
    k_threshold = 0.7
) {
  audit <- audit_update_2026_supplement_strategy_integrated_loo_files(
    paths = aligned_loo_manifest$final_loo_path,
    k_threshold = k_threshold
  )
  key <- c("outcome", "model_index")
  source_check <- audit$reduction_manifest |>
    dplyr::select(dplyr::all_of(key), integrated_loo_path) |>
    dplyr::inner_join(
      aligned_loo_manifest |>
        dplyr::select(
          dplyr::all_of(key),
          final_loo_path,
          loo_source
        ),
      by = key
    )

  expected_high_k <- audit$high_k_cases |>
    dplyr::select(outcome, model_index) |>
    dplyr::distinct()
  if (
    nrow(source_check) != 72L ||
      any(source_check$integrated_loo_path != source_check$final_loo_path) ||
      !all(audit$outcome_summary$observation_sets_aligned) ||
      nrow(audit$high_k_cases) != 1L ||
      nrow(expected_high_k) != 1L ||
      expected_high_k$outcome[[1L]] != "hypertrophy" ||
      expected_high_k$model_index[[1L]] != 6L
  ) {
    stop("The aligned supplement-strategy LOO audit is invalid.",
         call. = FALSE)
  }

  audit$family <- "supplement_strategy_aligned"
  audit$aligned_loo_manifest <- aligned_loo_manifest
  audit$exact_refits_required <- nrow(audit$high_k_cases)
  audit$stacking_ready <-
    audit$exact_refits_required == 0L &&
    all(audit$outcome_summary$observation_sets_aligned)
  audit
}

