make_update_2026_supplement_strategy_exact_loo_records <- function(
    aligned_loo_audit
) {
  cases <- aligned_loo_audit$high_k_cases |>
    dplyr::select(outcome, model_index, model_name, observation) |>
    dplyr::distinct() |>
    dplyr::arrange(outcome, model_index, observation) |>
    dplyr::mutate(case_id = dplyr::row_number(), .before = 1L) |>
    dplyr::left_join(
      aligned_loo_audit$aligned_loo_manifest |>
        dplyr::select(
          outcome,
          model_index,
          fit_path,
          integrated_loo_path = final_loo_path
        ),
      by = c("outcome", "model_index")
    )

  expected <- tibble::tibble(
    outcome = "hypertrophy",
    model_index = 6L,
    observation = 198L
  )
  observed <- cases |>
    dplyr::select(outcome, model_index, observation)

  if (
    !identical(aligned_loo_audit$family, "supplement_strategy_aligned") ||
      aligned_loo_audit$exact_refits_required != 1L ||
      !isTRUE(all.equal(observed, expected, check.attributes = FALSE)) ||
      anyNA(cases$fit_path) || anyNA(cases$integrated_loo_path) ||
      any(!file.exists(cases$fit_path)) ||
      any(!file.exists(cases$integrated_loo_path))
  ) {
    stop("The supplement-strategy exact-LOO registry no longer matches its audit.",
         call. = FALSE)
  }

  records <- purrr::pmap(cases, list)
  names(records) <- paste0(
    cases$outcome,
    "_model_",
    stringr::str_pad(cases$model_index, 2L, pad = "0"),
    "_observation_",
    cases$observation
  )
  records
}

validate_update_2026_supplement_strategy_exact_loo_inputs <- function(
    records
) {
  if (!is.list(records) || length(records) != 1L) {
    stop("Expected one supplement-strategy exact-LOO record.",
         call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    candidate <- qs::qread(record$fit_path)
    integrated <- qs::qread(record$integrated_loo_path)
    observation <- as.integer(record$observation)
    standata <- brms::standata(candidate$model)
    observed_design <- as.numeric(standata$Z_3_1)
    expected_design <- rep(1, nrow(candidate$model$data))
    maximum_design_difference <- max(abs(
      observed_design - expected_design
    ))
    pareto_k <- as.numeric(
      loo::pareto_k_values(integrated$loo)[[observation]]
    )
    manifest_row <- integrated$observation_manifest[observation, ]
    adapt_delta <- max(
      as.numeric(candidate$specification$adapt_delta),
      0.999
    )
    max_treedepth <- max(
      as.integer(candidate$specification$max_treedepth),
      15L
    )
    valid <-
      identical(candidate$outcome, record$outcome) &&
      as.integer(candidate$model_index) == as.integer(record$model_index) &&
      identical(candidate$specification$family, "supplement_strategy") &&
      identical(integrated$outcome, record$outcome) &&
      as.integer(integrated$model_index) == as.integer(record$model_index) &&
      identical(integrated$study_structure, "study_intercept") &&
      nrow(candidate$model$data) == 336L &&
      nrow(integrated$observation_manifest) == 336L &&
      length(observed_design) == 336L &&
      is.finite(maximum_design_difference) &&
      maximum_design_difference < 1e-12 &&
      is.finite(pareto_k) && pareto_k > integrated$k_threshold
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      observation = observation,
      study_no = as.character(manifest_row$study_no[[1L]]),
      arm_no = as.integer(manifest_row$arm_no[[1L]]),
      outcome_no = as.integer(manifest_row$outcome_no[[1L]]),
      pareto_k = pareto_k,
      adapt_delta = adapt_delta,
      max_treedepth = max_treedepth,
      iter_warmup = 2000L,
      iter_sampling = 6000L,
      chains = 4L,
      parallel_chains = 4L,
      maximum_design_difference = maximum_design_difference,
      original_fit_exists = file.exists(record$fit_path),
      integrated_loo_exists = file.exists(record$integrated_loo_path),
      valid = valid
    )
  }) |>
    dplyr::arrange(case_id)

  key <- paste(
    checks$outcome,
    checks$model_index,
    checks$observation,
    sep = "::"
  )

  if (
    nrow(checks) != 1L || key[[1L]] != "hypertrophy::6::198" ||
      checks$case_id[[1L]] != 1L || checks$study_no[[1L]] != "124" ||
      checks$arm_no[[1L]] != 189L || checks$outcome_no[[1L]] != 1023L ||
      checks$adapt_delta[[1L]] != 0.999 ||
      checks$max_treedepth[[1L]] != 15L ||
      checks$iter_warmup[[1L]] != 2000L ||
      checks$iter_sampling[[1L]] != 6000L ||
      checks$chains[[1L]] != 4L || checks$parallel_chains[[1L]] != 4L ||
      !checks$original_fit_exists[[1L]] ||
      !checks$integrated_loo_exists[[1L]] || !checks$valid[[1L]]
  ) {
    stop("The supplement-strategy exact-LOO preflight is incomplete.",
         call. = FALSE)
  }

  checks
}

write_update_2026_supplement_strategy_exact_loo_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy", "loo_exact", "input_preflight.csv"
    )
) {
  if (nrow(checks) != 1L || !all(checks$valid)) {
    stop("Cannot write an invalid supplement-strategy exact-LOO preflight.",
         call. = FALSE)
  }
  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

update_2026_supplement_strategy_exact_loo_file_path <- function(record) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "strategy", "loo", "exact_correction",
    record$outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf(
      "model_%02d_case_%02d_observation_%04d.qs",
      as.integer(record$model_index),
      as.integer(record$case_id),
      as.integer(record$observation)
    )
  )
}

fit_and_score_update_2026_supplement_strategy_exact_loo_to_file <- function(
    record,
    enabled
) {
  if (!isTRUE(enabled)) {
    stop(
      "Supplement-strategy exact refitting is disabled. Set ",
      "PROTEIN_UPDATE_2026_SUPPLEMENT_STRATEGY_EXACT=fit.",
      call. = FALSE
    )
  }

  output_file <- update_2026_supplement_strategy_exact_loo_file_path(record)
  if (file.exists(output_file) && file.info(output_file)$size > 0) {
    archived <- tryCatch(qs::qread(output_file), error = function(error) NULL)
    if (
      !is.null(archived) && inherits(archived$loo, "loo") &&
        identical(archived$outcome, record$outcome) &&
        as.integer(archived$model_index) == as.integer(record$model_index) &&
        as.integer(
          archived$exact_refit_summary$observation[[1L]]
        ) == as.integer(record$observation)
    ) {
      return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
    }
    stop("An existing supplement-strategy exact correction is invalid.",
         call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  integrated <- qs::qread(record$integrated_loo_path)
  observation <- as.integer(record$observation)
  if (
    !identical(candidate$outcome, record$outcome) ||
      as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(integrated$outcome, record$outcome) ||
      as.integer(integrated$model_index) != as.integer(record$model_index) ||
      loo::pareto_k_values(integrated$loo)[[observation]] <= 0.7
  ) {
    stop("A supplement-strategy exact-LOO record failed validation.",
         call. = FALSE)
  }

  candidate$specification$adapt_delta <- max(
    as.numeric(candidate$specification$adapt_delta),
    0.999
  )
  candidate$specification$max_treedepth <- max(
    as.integer(candidate$specification$max_treedepth),
    15L
  )
  job <- list(
    case_id = as.integer(record$case_id),
    outcome = record$outcome,
    model_index = as.integer(record$model_index),
    model_name = record$model_name,
    observation = observation,
    fitted_candidate = candidate,
    integrated_result = integrated
  )

  refit <- fit_primary_integrated_exact_loo_case(
    job = job,
    chains = 4L,
    cores = 4L,
    warmup = 2000L,
    iter = 8000L,
    seed = 226888L + as.integer(record$case_id)
  )

  correction <- compute_primary_integrated_exact_loo_case(refit)
  correction$case_id <- as.integer(record$case_id)
  correction$fit_path <- normalizePath(
    record$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  correction$fit_stage <- integrated$fit_stage
  write_atomic_qs(correction, output_file)
}

audit_update_2026_supplement_strategy_exact_loo_files <- function(
    paths,
    aligned_loo_audit
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  if (
    length(paths) != 1L || aligned_loo_audit$exact_refits_required != 1L ||
      anyNA(paths) || any(!file.exists(paths)) ||
      any(file.info(paths)$size <= 0)
  ) {
    stop("The supplement-strategy exact-LOO correction is incomplete.",
         call. = FALSE)
  }

  corrections <- purrr::map(paths, qs::qread)
  diagnostic_summary <- purrr::map_dfr(
    corrections,
    "exact_refit_summary"
  )
  manifest <- purrr::map2_dfr(paths, corrections, function(path, result) {
    tibble::tibble(
      case_id = as.integer(result$case_id),
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      model_name = result$model_name,
      observation =
        as.integer(result$exact_refit_summary$observation[[1L]]),
      correction_path = normalizePath(
        path,
        winslash = "/",
        mustWork = TRUE
      ),
      bytes = file.info(path)$size,
      sha256 = digest::digest(
        file = path,
        algo = "sha256",
        serialize = FALSE
      )
    )
  })

  observed_key <- paste(
    manifest$outcome,
    manifest$model_index,
    manifest$observation,
    sep = "::"
  )
  expected_key <- paste(
    aligned_loo_audit$high_k_cases$outcome,
    aligned_loo_audit$high_k_cases$model_index,
    aligned_loo_audit$high_k_cases$observation,
    sep = "::"
  )

  if (
    nrow(diagnostic_summary) != 1L || nrow(manifest) != 1L ||
      observed_key[[1L]] != expected_key[[1L]] ||
      manifest$case_id[[1L]] != 1L
  ) {
    stop("The supplement-strategy exact-correction audit is invalid.",
         call. = FALSE)
  }

  list(
    diagnostic_summary = diagnostic_summary,
    correction_manifest = manifest,
    exact_refits = 1L,
    exact_refits_passing = sum(diagnostic_summary$diagnostic_pass),
    exact_refits_requiring_remediation =
      sum(!diagnostic_summary$diagnostic_pass),
    all_exact_refit_diagnostics_pass =
      all(diagnostic_summary$diagnostic_pass)
  )
}

write_update_2026_supplement_strategy_exact_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy", "loo_exact"
    )
) {
  if (
    audit$exact_refits != 1L ||
      nrow(audit$diagnostic_summary) != 1L ||
      nrow(audit$correction_manifest) != 1L
  ) {
    stop("Cannot write an incomplete supplement-strategy exact-correction audit.",
         call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    correction_manifest = file.path(output_dir, "correction_manifest.csv")
  )
  readr::write_csv(
    audit$diagnostic_summary,
    paths[["diagnostic_summary"]],
    na = ""
  )
  readr::write_csv(
    audit$correction_manifest,
    paths[["correction_manifest"]],
    na = ""
  )
  unname(paths)
}

make_update_2026_supplement_strategy_final_loo_manifest <- function(
    aligned_loo_audit,
    exact_loo_audit
) {
  if (
    !isTRUE(exact_loo_audit$all_exact_refit_diagnostics_pass) ||
      exact_loo_audit$exact_refits != 1L ||
      nrow(aligned_loo_audit$aligned_loo_manifest) != 72L
  ) {
    stop("Final supplement-strategy LOO assembly requires one passing exact refit.",
         call. = FALSE)
  }

  exact <- exact_loo_audit$correction_manifest |>
    dplyr::select(
      outcome,
      model_index,
      observation,
      correction_path,
      correction_bytes = bytes,
      correction_sha256 = sha256
    )

  manifest <- aligned_loo_audit$aligned_loo_manifest |>
    dplyr::rename(
      base_loo_source = loo_source,
      integrated_loo_path = final_loo_path,
      integrated_bytes = final_bytes,
      integrated_sha256 = final_sha256
    ) |>
    dplyr::left_join(exact, by = c("outcome", "model_index")) |>
    dplyr::mutate(
      loo_source = dplyr::if_else(
        is.na(correction_path),
        base_loo_source,
        "integrated_psis_plus_exact"
      ),
      final_loo_path = dplyr::coalesce(
        correction_path,
        integrated_loo_path
      ),
      final_bytes = dplyr::coalesce(
        correction_bytes,
        integrated_bytes
      ),
      final_sha256 = dplyr::coalesce(
        correction_sha256,
        integrated_sha256
      )
    ) |>
    dplyr::select(
      outcome, model_index, model_name, fit_stage, fit_path,
      base_loo_source, loo_source, observation,
      integrated_loo_path, correction_path, final_loo_path,
      final_bytes, final_sha256
    ) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  if (
    nrow(manifest) != 72L ||
      sum(manifest$loo_source == "integrated_psis_plus_exact") != 1L ||
      anyDuplicated(manifest[c("outcome", "model_index")]) ||
      any(!file.exists(manifest$final_loo_path)) ||
      any(file.info(manifest$final_loo_path)$size <= 0) ||
      any(nchar(manifest$final_sha256) != 64L)
  ) {
    stop("The final supplement-strategy LOO manifest is invalid.",
         call. = FALSE)
  }

  manifest
}

audit_update_2026_supplement_strategy_final_loo <- function(
    final_loo_manifest,
    exact_loo_audit,
    k_threshold = 0.7
) {
  audit <- audit_update_2026_supplement_strategy_integrated_loo_files(
    paths = final_loo_manifest$final_loo_path,
    k_threshold = k_threshold
  )

  if (
    nrow(final_loo_manifest) != 72L ||
      !isTRUE(exact_loo_audit$all_exact_refit_diagnostics_pass) ||
      exact_loo_audit$exact_refits != 1L ||
      nrow(audit$high_k_cases) != 0L ||
      audit$exact_refits_required != 0L ||
      !isTRUE(audit$stacking_ready) ||
      !all(audit$outcome_summary$observation_sets_aligned)
  ) {
    stop("The final supplement-strategy LOO audit is not stacking-ready.",
         call. = FALSE)
  }

  audit$family <- "supplement_strategy"
  audit$final_loo_manifest <- final_loo_manifest
  audit$exact_refit_summary <- exact_loo_audit$diagnostic_summary
  audit$exact_refits <- 1L
  audit$all_exact_refit_diagnostics_pass <- TRUE
  audit
}

write_update_2026_supplement_strategy_final_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy", "loo_final"
    )
) {
  if (
    !identical(audit$family, "supplement_strategy") ||
