make_update_2026_supplement_strategy_prediction_records <- function(
    accepted_fit_manifest,
    stacking_weights,
    n_draws = 4000L,
    exposure_minimum_g_day = 0,
    grid_step_g_day = 1,
    seed = 236988L
) {
  records <- make_update_2026_total_primary_prediction_records(
    accepted_fit_manifest = accepted_fit_manifest,
    stacking_weights = stacking_weights,
    n_draws = n_draws,
    exposure_minimum_g_day = exposure_minimum_g_day,
    grid_step_g_day = grid_step_g_day,
    seed = seed
  )

  records <- purrr::map(records, function(record) {
    record$family <- "supplement_strategy"
    record$prediction_type <- "supplement_strategy"
    record
  })
  allocated <- purrr::map_dfr(records, function(record) {
    tibble::tibble(
      outcome = as.character(record$outcome),
      draw_count = as.integer(record$draw_count)
    )
  }) |>
    dplyr::summarise(draws = sum(draw_count), .by = outcome)

  if (
    length(records) < 4L || nrow(allocated) != 4L ||
      any(allocated$draws != n_draws) ||
      any(!purrr::map_lgl(
        records,
        ~ identical(.x$family, "supplement_strategy") &&
          identical(.x$prediction_type, "supplement_strategy")
      ))
  ) {
    stop("The supplement-strategy prediction allocation is incomplete.",
         call. = FALSE)
  }

  records
}

make_update_2026_supplement_strategy_reporting_preflight <- function(
    records,
    data_by_outcome
) {
  checks <- purrr::map_dfr(records, function(record) {
    data <- data_by_outcome[[record$outcome]]
    maximum <- if (is.data.frame(data)) {
      max(data$protein_intake_raw, na.rm = TRUE)
    } else {
      NA_real_
    }
    reference <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_reference_g_day)
    } else {
      NA_real_
    }
    unit <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_unit_g_day)
    } else {
      NA_real_
    }
    tibble::tibble(
      outcome = as.character(record$outcome),
      model_index = as.integer(record$model_index),
      model_name = as.character(record$model_name),
      family = as.character(record$family),
      prediction_type = as.character(record$prediction_type),
      weight = as.numeric(record$weight),
      allocated_draws = as.integer(record$draw_count),
      prediction_seed = as.integer(record$prediction_seed),
      exposure_minimum_g_day =
        as.numeric(record$exposure_minimum_g_day),
      exposure_maximum_g_day = as.numeric(maximum),
      reference_g_day = as.numeric(reference),
      internal_unit_g_day = as.numeric(unit),
      grid_step_g_day = as.numeric(record$grid_step_g_day),
      fit_path = as.character(record$fit_path),
      fit_exists = file.exists(record$fit_path),
      valid =
        record$draw_count > 0L && file.exists(record$fit_path) &&
        identical(as.character(record$family), "supplement_strategy") &&
        identical(
          as.character(record$prediction_type),
          "supplement_strategy"
        ) &&
        nchar(record$fit_sha256) == 64L &&
        is.finite(maximum) && maximum > record$exposure_minimum_g_day &&
        length(reference) == 1L && reference == 0 &&
        length(unit) == 1L && unit == 25
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  audit <- checks |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      allocated_draws = sum(allocated_draws),
      retained_weight = sum(weight),
      .by = outcome
    )
  expected_maximum <- c(
    whole_body = 94,
    hypertrophy = 78.4,
    strength = 94,
    `function` = 320 / 7
  )

  if (
    nrow(audit) != 4L || any(audit$selected_models < 1L) ||
      any(audit$allocated_draws != 4000L) ||
      any(audit$retained_weight <= 0) ||
      any(audit$retained_weight > 1 + 1e-8) ||
      anyDuplicated(checks[c("outcome", "model_index")]) ||
      any(checks$exposure_minimum_g_day != 0) ||
      any(abs(
        checks$exposure_maximum_g_day - expected_maximum[checks$outcome]
      ) > 1e-8) ||
      any(checks$reference_g_day != 0) ||
      any(checks$internal_unit_g_day != 25) ||
      any(checks$grid_step_g_day != 1) || !all(checks$valid)
  ) {
    stop("The supplement-strategy reporting preflight failed.",
         call. = FALSE)
  }

  checks
}

write_update_2026_supplement_strategy_reporting_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy", "reporting", "input_preflight.csv"
    )
) {
  if (
    !all(checks$valid) ||
      any(tapply(checks$allocated_draws, checks$outcome, sum) != 4000L) ||
      any(checks$reference_g_day != 0) ||
      any(checks$internal_unit_g_day != 25)
  ) {
    stop("Cannot write an invalid supplement-strategy reporting preflight.",
         call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file)
  output_file
}

make_update_2026_supplement_strategy_prediction_grid <- function(
    data,
    fitted_candidate,
    exposure_minimum_g_day = 0,
    grid_step_g_day = 1
) {
  required <- c(
    "protein_intake_raw", "protein_strategy", "strategy_code",
    "resistance_exercise_code", "absolute_exposure_reference_g_day",
    "absolute_exposure_unit_g_day"
  )

  if (!all(required %in% names(data)) || !nrow(data)) {
    stop("The supplement-strategy prediction data are invalid.",
         call. = FALSE)
  }
  reference <- unique(data$absolute_exposure_reference_g_day)
  unit <- unique(data$absolute_exposure_unit_g_day)
  exposure_maximum_g_day <- max(data$protein_intake_raw, na.rm = TRUE)

  if (
    length(reference) != 1L || reference != 0 ||
      length(unit) != 1L || unit != 25 ||
      !is.finite(exposure_minimum_g_day) ||
      exposure_minimum_g_day >= exposure_maximum_g_day ||
      !is.finite(grid_step_g_day) || grid_step_g_day <= 0
  ) {
    stop("The supplement-strategy prediction-grid limits are invalid.",
         call. = FALSE)
  }

  exposure_values <- sort(unique(c(
    round(seq(
      exposure_minimum_g_day,
      exposure_maximum_g_day,
      by = grid_step_g_day
    ), 10),
    reference
  )))

  keys <- tidyr::crossing(
    protein_strategy = c("Substitution", "Addition"),
    resistance_exercise_code = c(0, 1),
    protein_intake = exposure_values
  ) |>
    dplyr::mutate(
      strategy_code = ifelse(protein_strategy == "Addition", 1, 0)
    )

  template_data <- fitted_candidate$model$data
  grouping_variables <- intersect(
    c("study_no", "arm_no", "outcome_no", "study_factor"),
    names(template_data)
  )
  complete <- stats::complete.cases(
    template_data[, grouping_variables, drop = FALSE]
  )

  if (!any(complete)) {
    stop("No complete row is available for the supplement-strategy grid.",
         call. = FALSE)
  }
  newdata <- template_data[
    rep(which(complete)[[1L]], nrow(keys)),
    ,
    drop = FALSE
  ]
  newdata$protein_strategy <- keys$protein_strategy
  newdata$strategy_code <- keys$strategy_code

  if ("strategy_factor" %in% names(newdata)) {
    newdata$strategy_factor <- factor(
      keys$protein_strategy,
      levels = c("Substitution", "Addition")
    )
  }

  newdata$resistance_exercise_code <- keys$resistance_exercise_code
  newdata$protein_intake_raw <- keys$protein_intake
  newdata$supplement_g_day <- keys$protein_intake
  newdata$protein_intake <- (keys$protein_intake - reference) / unit
  exercise_label <- ifelse(keys$resistance_exercise_code == 0, "yes", "no")
  if ("resistance_exercise_yes_no" %in% names(newdata)) {
    newdata$resistance_exercise_yes_no <- exercise_label
  }

  if ("resistance_exercise_factor" %in% names(newdata)) {
    newdata$resistance_exercise_factor <- factor(
      exercise_label,
      levels = levels(data$resistance_exercise_factor)
    )
  }

  if ("age_centre" %in% names(newdata)) newdata$age_centre <- 0
  if ("duration_centre" %in% names(newdata)) newdata$duration_centre <- 0
  if ("vi" %in% names(newdata)) newdata$vi <- 0
  moderator_data <- add_primary_standardised_moderators(data)
  moderator_centres <- attr(moderator_data, "moderator_centres")
  moderator_scales <- attr(moderator_data, "moderator_scales")
  newdata$age_outcome_z <-
    (0 - moderator_centres[["age_centre"]]) /
      moderator_scales[["age_centre"]]
  newdata$duration_outcome_z <-
    (0 - moderator_centres[["duration_centre"]]) /
      moderator_scales[["duration_centre"]]
  newdata$body_mass_outcome_z <- 0
  list(
    newdata = newdata,
    keys = tibble::tibble(
      protein_strategy = keys$protein_strategy,
      strategy_code = keys$strategy_code,
      resistance_exercise_code = keys$resistance_exercise_code,
      resistance_exercise_label = "Resistance Exercise?",
      resistance_exercise = ifelse(
        keys$resistance_exercise_code == 0,
        "YES",
        "NO"
      ),
      protein_intake = keys$protein_intake,
      protein_intake_g_day = keys$protein_intake
    ),
    reference_g_day = reference,
    unit_g_day = unit,
    protein_min = exposure_minimum_g_day,
    protein_max = max(exposure_values),
    grid_step = grid_step_g_day
  )
}

update_2026_supplement_strategy_reporting_path <- function(
    outcome,
    stage,
    model_index = NULL
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "strategy", "reporting", stage, outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  filename <- if (is.null(model_index)) {
    paste0(stage, ".qs")
  } else {
    sprintf("model_%02d_%s.qs", as.integer(model_index), stage)
  }
  file.path(directory, filename)
}

write_update_2026_supplement_strategy_prediction_draw_file <- function(
    record,
    data_by_outcome,
    result_path
) {
  if (
    !file.exists(record$fit_path) || record$draw_count < 1L ||
      !identical(as.character(record$family), "supplement_strategy")
  ) {
    stop("A supplement-strategy prediction record is invalid.",
         call. = FALSE)
  }

  candidate <- qs::qread(record$fit_path)
  if (
    !identical(candidate$outcome, as.character(record$outcome)) ||
      as.integer(candidate$model_index) != as.integer(record$model_index) ||
      !identical(candidate$model_name, as.character(record$model_name)) ||
      !candidate$specification$family %in%
        c("supplement_strategy", "supplement_strategy_common_sample")
  ) {
    stop("A supplement-strategy fit does not match its prediction record.",
         call. = FALSE)
  }

  grid <- make_update_2026_supplement_strategy_prediction_grid(
    data = data_by_outcome[[record$outcome]],
    fitted_candidate = candidate,
    exposure_minimum_g_day = record$exposure_minimum_g_day,
    grid_step_g_day = record$grid_step_g_day
  )
  old_mc_cores <- getOption("mc.cores")
  on.exit(options(mc.cores = old_mc_cores), add = TRUE)
  options(mc.cores = 1L)
  set.seed(as.integer(record$prediction_seed))
  draws <- as.matrix(brms::posterior_epred(
    candidate$model,
    newdata = grid$newdata,
    re_formula = NA,
    ndraws = as.integer(record$draw_count)
  ))

  if (ncol(draws) != nrow(grid$keys) && nrow(draws) == nrow(grid$keys)) {
    draws <- t(draws)
  }
  if (
    nrow(draws) != as.integer(record$draw_count) ||
      ncol(draws) != nrow(grid$keys) || anyNA(draws)
  ) {
    stop("Supplement-strategy predictions do not match their allocation.",
         call. = FALSE)
  }

  reduction <- list(
    family = "supplement_strategy",
    outcome = as.character(record$outcome),
    model_index = as.integer(record$model_index),
    model_name = as.character(record$model_name),
    weight = as.numeric(record$weight),
    draw_count = as.integer(record$draw_count),
    prediction_seed = as.integer(record$prediction_seed),
    fit_sha256 = as.character(record$fit_sha256),
    grid = grid$keys,
    draws = draws,
    settings = list(
      protein_min = grid$protein_min,
      protein_max = grid$protein_max,
      grid_step = grid$grid_step,
      reference_intake = grid$reference_g_day,
      internal_unit_g_day = grid$unit_g_day,
      prediction_type = "supplement_strategy"
    )
  )

  write_atomic_qs(reduction, result_path)
}

