fit_update_2026_supplement_strategy_within_candidate_to_file <- function(
    input,
    config,
    enabled,
    output_root = here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "strategy_within", "initial"
    )
) {
  if (!isTRUE(enabled)) {
    stop(
      paste0(
        "Supplement strategy-within fitting is disabled. Set ",
        "PROTEIN_UPDATE_2026_SUPPLEMENT_STRATEGY_WITHIN=fit to enable it."
      ),
      call. = FALSE
    )
  }

  if (!identical(input$family, "supplement_strategy_within")) {
    stop("The supplement strategy-within fit input is invalid.",
         call. = FALSE)
  }
  local_config <- update_2026_total_within_local_config(
    input$specification,
    config
  )
  candidate <- fit_sensitivity_brms_pilot(
    input = input,
    enabled = TRUE,
    config = local_config,
    family = "supplement_strategy_within"
  )
  output_dir <- file.path(output_root, candidate$outcome)
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  output_file <- file.path(
    output_dir,
    sprintf("model_%02d.qs", as.integer(candidate$model_index))
  )
  write_atomic_qs(candidate, output_file)
}

make_update_2026_supplement_strategy_within_remedy_specifications <- function(
    specifications,
    diagnostic_audit
) {
  expected_keys <- c("whole_body::9", "hypertrophy::21")
  failed <- diagnostic_audit$diagnostic_summary |>
    dplyr::filter(!diagnostic_pass) |>
    dplyr::mutate(key = paste(outcome, model_index, sep = "::"))

  if (
    !identical(diagnostic_audit$family, "supplement_strategy_within") ||
      nrow(failed) != 2L || anyDuplicated(failed$key) ||
      !setequal(failed$key, expected_keys) ||
      any(failed$divergent_transitions != 1) ||
      any(failed$maximum_treedepth_transitions != 0L) ||
      any(failed$geometry_pass) || !all(failed$convergence_pass)
  ) {
    stop("The supplement strategy-within remedy set is invalid.",
         call. = FALSE)
  }

  selected <- purrr::keep(specifications, function(specification) {
    paste(
      specification$outcome,
      specification$model_index,
      sep = "::"
    ) %in% expected_keys
  })

  if (length(selected) != 2L) {
    stop("Could not select the supplement strategy-within remedy models.",
         call. = FALSE)
  }
  selected <- purrr::map(selected, function(specification) {
    specification$adapt_delta <- max(
      as.numeric(specification$adapt_delta),
      0.999
    )
    specification$max_treedepth <- max(
      as.integer(specification$max_treedepth),
      15L
    )
    specification$iter_warmup <- 3000L
    specification$iter_sampling <- 8000L
    specification$remedy <- "higher_acceptance_after_divergence"
    specification$archive_stage <- "remedy_1"
    specification$remedy_reason <- paste(
      "One divergent transition with otherwise passing R-hat, effective",
      "sample-size, and Monte Carlo standard-error diagnostics."
    )
    specification
  })

  selected_table <- dplyr::bind_rows(selected) |>
    dplyr::transmute(key = paste(outcome, model_index, sep = "::"))
  if (!setequal(selected_table$key, expected_keys)) {
    stop("The supplement strategy-within remedy registry changed.",
         call. = FALSE)
  }

  selected
}

validate_update_2026_supplement_strategy_within_remedy_inputs <- function(
    inputs,
    initial_fit_paths,
    config
) {
  paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  checks <- purrr::map_dfr(inputs, function(input) {
    specification <- input$specification
    initial_path <- paths[
      basename(dirname(paths)) == specification$outcome &
        basename(paths) == sprintf(
          "model_%02d.qs",
          as.integer(specification$model_index)
        )
    ]
    local_config <- update_2026_total_within_local_config(
      specification,
      config
    )
    brms::make_standata(
      formula = stats::as.formula(input$formula),
      data = input$data,
      prior = input$priors
    )
    tibble::tibble(
      outcome = specification$outcome,
      model_index = as.integer(specification$model_index),
      model_name = specification$model_name,
      remedy = specification$remedy,
      adapt_delta = local_config$adapt_delta_floor,
      max_treedepth = local_config$max_treedepth_floor,
      iter_warmup = local_config$iter_warmup,
      iter_sampling = local_config$iter_sampling,
      chains = as.integer(local_config$chains),
      parallel_chains = as.integer(local_config$parallel_chains),
      initial_fit_exists =
        length(initial_path) == 1L && file.exists(initial_path),
      valid = TRUE
    )
  }) |>
    dplyr::arrange(outcome, model_index)

  keys <- paste(checks$outcome, checks$model_index, sep = "::")
  if (
    nrow(checks) != 2L || anyDuplicated(keys) ||
      !setequal(keys, c("whole_body::9", "hypertrophy::21")) ||
      any(checks$adapt_delta < 0.999) ||
      any(checks$max_treedepth < 15L) ||
      any(checks$iter_warmup != 3000L) ||
      any(checks$iter_sampling != 8000L) ||
      any(checks$chains != 4L) || any(checks$parallel_chains != 4L) ||
      !all(checks$initial_fit_exists) || !all(checks$valid)
  ) {
    stop("The supplement strategy-within remedy preflight is invalid.",
         call. = FALSE)
  }

  checks
}

