combine_update_2026_supplement_strategy_within_remedy_diagnostics <- function(
    initial_diagnostics,
    remedy_diagnostics
) {
  diagnostic_key <- function(x) {
    paste(x$summary$outcome[[1L]], x$summary$model_index[[1L]], sep = "::")
  }
  expected_keys <- c("whole_body::9", "hypertrophy::21")

  if (length(initial_diagnostics) != 72L ||
      length(remedy_diagnostics) != 2L) {
    stop("The supplement strategy-within remedy diagnostics are incomplete.",
         call. = FALSE)
  }
  initial_keys <- purrr::map_chr(initial_diagnostics, diagnostic_key)
  remedy_keys <- purrr::map_chr(remedy_diagnostics, diagnostic_key)
  failed_keys <- initial_diagnostics |>
    purrr::keep(~ !.x$summary$diagnostic_pass[[1L]]) |>
    purrr::map_chr(diagnostic_key)

  if (
    anyDuplicated(initial_keys) || anyDuplicated(remedy_keys) ||
      !setequal(remedy_keys, expected_keys) ||
      !setequal(remedy_keys, failed_keys) ||
      !all(remedy_keys %in% initial_keys)
  ) {
    stop("The supplement strategy-within diagnostic replacement is invalid.",
         call. = FALSE)
  }

  final_diagnostics <- initial_diagnostics
  final_diagnostics[match(remedy_keys, initial_keys)] <- remedy_diagnostics
  compile_update_2026_total_primary_diagnostic_audit(
    final_diagnostics,
    family = "supplement_strategy_within"
  )
}

make_update_2026_supplement_strategy_within_second_remedy_specifications <-
  function(
      remedy_specifications,
      diagnostic_audit
  ) {
    failed <- diagnostic_audit$diagnostic_summary |>
      dplyr::filter(!diagnostic_pass) |>
      dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
    if (
      !identical(diagnostic_audit$family, "supplement_strategy_within") ||
        nrow(failed) != 1L || failed$key[[1L]] != "hypertrophy::21" ||
        failed$divergent_transitions[[1L]] != 1 ||
        failed$maximum_treedepth_transitions[[1L]] != 0L ||
        isTRUE(failed$geometry_pass[[1L]]) ||
        !isTRUE(failed$convergence_pass[[1L]])
    ) {
      stop("The supplement strategy-within second-remedy set is invalid.",
           call. = FALSE)
    }
    selected <- purrr::keep(remedy_specifications, function(specification) {
      identical(specification$outcome, "hypertrophy") &&
        identical(as.integer(specification$model_index), 21L)
    })
    if (length(selected) != 1L) {
      stop("Could not select the supplement strategy-within second remedy.",
           call. = FALSE)
    }
    selected <- purrr::map(selected, function(specification) {
      specification$adapt_delta <- 0.9999
      specification$max_treedepth <- 16L
      specification$iter_warmup <- 4000L
      specification$iter_sampling <- 12000L
      specification$remedy <-
        "extended_adaptation_after_persistent_divergence"
      specification$archive_stage <- "remedy_2"
      specification$remedy_reason <- paste(
        "One divergent transition persisted after the first high-acceptance",
        "remedy despite strong convergence and effective sample sizes."
      )
      specification
    })
    names(selected) <- "hypertrophy_model_21"
    selected
  }

validate_update_2026_supplement_strategy_within_second_remedy_inputs <-
  function(
      inputs,
      first_remedy_fit_paths,
      config
  ) {
    paths <- unname(unlist(first_remedy_fit_paths, use.names = FALSE))
    checks <- purrr::map_dfr(inputs, function(input) {
      specification <- input$specification
      previous_path <- paths[
        basename(dirname(paths)) == specification$outcome &
          basename(paths) == sprintf(
            "model_%02d.qs",
            as.integer(specification$model_index)
          )
      ]
      local_config <- update_2026_total_within_local_config(
        specification,
        config
      )
      brms::make_standata(
        formula = stats::as.formula(input$formula),
        data = input$data,
        prior = input$priors
      )
      tibble::tibble(
        outcome = specification$outcome,
        model_index = as.integer(specification$model_index),
        model_name = specification$model_name,
        remedy = specification$remedy,
        adapt_delta = local_config$adapt_delta_floor,
        max_treedepth = local_config$max_treedepth_floor,
        iter_warmup = local_config$iter_warmup,
        iter_sampling = local_config$iter_sampling,
        chains = as.integer(local_config$chains),
        parallel_chains = as.integer(local_config$parallel_chains),
        remedy_1_fit_exists =
          length(previous_path) == 1L && file.exists(previous_path),
        valid = TRUE
      )
    })
    if (
      nrow(checks) != 1L || checks$outcome[[1L]] != "hypertrophy" ||
        checks$model_index[[1L]] != 21L ||
        checks$remedy[[1L]] !=
          "extended_adaptation_after_persistent_divergence" ||
        checks$adapt_delta[[1L]] < 0.9999 ||
        checks$max_treedepth[[1L]] < 16L ||
        checks$iter_warmup[[1L]] != 4000L ||
        checks$iter_sampling[[1L]] != 12000L ||
        checks$chains[[1L]] != 4L ||
        checks$parallel_chains[[1L]] != 4L ||
        !checks$remedy_1_fit_exists[[1L]] || !checks$valid[[1L]]
    ) {
      stop(
        "The supplement strategy-within second-remedy preflight is invalid.",
        call. = FALSE
      )
    }
    checks
  }

