combine_update_2026_supplement_strategy_within_second_remedy_diagnostics <-
  function(
      initial_diagnostics,
      first_remedy_diagnostics,
      second_remedy_diagnostics
  ) {
    diagnostic_key <- function(x) {
      paste(x$summary$outcome[[1L]], x$summary$model_index[[1L]], sep = "::")
    }
    initial_keys <- purrr::map_chr(initial_diagnostics, diagnostic_key)
    first_keys <- purrr::map_chr(first_remedy_diagnostics, diagnostic_key)
    second_keys <- purrr::map_chr(second_remedy_diagnostics, diagnostic_key)
    initial_failed_keys <- initial_diagnostics |>
      purrr::keep(~ !.x$summary$diagnostic_pass[[1L]]) |>
      purrr::map_chr(diagnostic_key)
    first_failed_keys <- first_remedy_diagnostics |>
      purrr::keep(~ !.x$summary$diagnostic_pass[[1L]]) |>
      purrr::map_chr(diagnostic_key)
    if (
      length(initial_diagnostics) != 72L ||
        length(first_remedy_diagnostics) != 2L ||
        length(second_remedy_diagnostics) != 1L ||
        anyDuplicated(initial_keys) || anyDuplicated(first_keys) ||
        anyDuplicated(second_keys) ||
        !setequal(initial_failed_keys,
                  c("whole_body::9", "hypertrophy::21")) ||
        !setequal(first_keys, initial_failed_keys) ||
        !identical(unname(first_failed_keys), "hypertrophy::21") ||
        !identical(unname(second_keys), "hypertrophy::21")
    ) {
      stop(
        "The supplement strategy-within second diagnostic replacement is invalid.",
        call. = FALSE
      )
    }
    final_diagnostics <- initial_diagnostics
    final_diagnostics[match(first_keys, initial_keys)] <-
      first_remedy_diagnostics
    final_diagnostics[match(second_keys, initial_keys)] <-
      second_remedy_diagnostics
    compile_update_2026_total_primary_diagnostic_audit(
      final_diagnostics,
      family = "supplement_strategy_within"
    )
  }

make_update_2026_supplement_strategy_within_structural_remedy_specifications <-
  function(
      second_remedy_specifications,
      diagnostic_audit
  ) {
    failed <- diagnostic_audit$diagnostic_summary |>
      dplyr::filter(!diagnostic_pass) |>
      dplyr::mutate(key = paste(outcome, model_index, sep = "::"))
    if (
      !identical(diagnostic_audit$family, "supplement_strategy_within") ||
        nrow(failed) != 1L || failed$key[[1L]] != "hypertrophy::21" ||
        failed$divergent_transitions[[1L]] != 1 ||
        failed$maximum_treedepth_transitions[[1L]] != 0L ||
        isTRUE(failed$geometry_pass[[1L]]) ||
        !isTRUE(failed$convergence_pass[[1L]])
    ) {
      stop("The supplement strategy-within structural remedy is invalid.",
           call. = FALSE)
    }
    if (length(second_remedy_specifications) != 1L) {
      stop("Expected one supplement strategy-within second-remedy model.",
           call. = FALSE)
    }
    selected <- purrr::map(
      second_remedy_specifications,
      function(specification) {
        if (
          specification$outcome != "hypertrophy" ||
            as.integer(specification$model_index) != 21L
        ) {
          stop("The structural remedy model key is invalid.", call. = FALSE)
        }
        specification$model_name <- paste0(
          specification$model_name,
          " [uncorrelated study effects remedy]"
        )
        specification$uncorrelated_study_effects <- TRUE
        specification$remedy <-
          "uncorrelated_study_effects_after_persistent_divergence"
        specification$archive_stage <- "structural_uncorrelated"
        specification$remedy_reason <- paste(
          "A single divergence persisted across the initial, high-acceptance,",
          "and extended-adaptation fits; the study intercept and exposure",
          "slope variances are retained while their correlation is removed."
        )
        specification
      }
    )
    names(selected) <- "hypertrophy_model_21"
    selected
  }

prepare_update_2026_supplement_strategy_within_structural_remedy_input <-
  function(
      specification,
      contrast_data_by_outcome,
      priors_by_outcome,
      config
  ) {
    input <- prepare_update_2026_supplement_strategy_within_input(
      specification = specification,
      contrast_data_by_outcome = contrast_data_by_outcome,
      priors_by_outcome = priors_by_outcome,
      config = config
    )
    correlated <- "(1 + protein_contrast_1 | study_no)"
    uncorrelated <- "(1 + protein_contrast_1 || study_no)"
    has_correlated <- stringr::str_detect(
      input$formula,
      stringr::fixed(correlated)
    )
    has_uncorrelated <- stringr::str_detect(
      input$formula,
      stringr::fixed(uncorrelated)
    )
    if (has_correlated && !has_uncorrelated) {
      input$formula <- stringr::str_replace(
        input$formula,
        stringr::fixed(correlated),
        uncorrelated
      )
    } else if (!has_uncorrelated || has_correlated) {
      stop("The structural-remedy study term is not uniquely identifiable.",
           call. = FALSE)
    }
    input$specification$formula <- input$formula
    input$specification$uncorrelated_study_effects <- TRUE
    input$structural_remedy <- "uncorrelated_study_intercept_and_slope"
    input
  }

validate_update_2026_supplement_strategy_within_structural_remedy_input <-
  function(
      inputs,
      second_remedy_fit_paths,
      config
  ) {
    paths <- unname(unlist(second_remedy_fit_paths, use.names = FALSE))
    checks <- purrr::map_dfr(inputs, function(input) {
      specification <- input$specification
      previous_path <- paths[
        basename(dirname(paths)) == specification$outcome &
          basename(paths) == sprintf(
            "model_%02d.qs",
            as.integer(specification$model_index)
          )
      ]
      local_config <- update_2026_total_within_local_config(
        specification,
        config
      )
      brms::make_standata(
        formula = stats::as.formula(input$formula),
        data = input$data,
        prior = input$priors
      )
      tibble::tibble(
        outcome = specification$outcome,
        model_index = as.integer(specification$model_index),
        model_name = specification$model_name,
        remedy = specification$remedy,
        correlated_term_removed = !stringr::str_detect(
          input$formula,
          stringr::fixed("(1 + protein_contrast_1 | study_no)")
        ),
        uncorrelated_term_present = stringr::str_detect(
          input$formula,
          stringr::fixed("(1 + protein_contrast_1 || study_no)")
        ),
        adapt_delta = local_config$adapt_delta_floor,
        max_treedepth = local_config$max_treedepth_floor,
        iter_warmup = local_config$iter_warmup,
        iter_sampling = local_config$iter_sampling,
        chains = as.integer(local_config$chains),
        parallel_chains = as.integer(local_config$parallel_chains),
        remedy_2_fit_exists =
          length(previous_path) == 1L && file.exists(previous_path),
        valid = TRUE
      )
    })
    if (
      nrow(checks) != 1L || checks$outcome[[1L]] != "hypertrophy" ||
        checks$model_index[[1L]] != 21L ||
        checks$remedy[[1L]] !=
          "uncorrelated_study_effects_after_persistent_divergence" ||
        !checks$correlated_term_removed[[1L]] ||
        !checks$uncorrelated_term_present[[1L]] ||
        checks$adapt_delta[[1L]] < 0.9999 ||
        checks$max_treedepth[[1L]] < 16L ||
        checks$iter_warmup[[1L]] != 4000L ||
        checks$iter_sampling[[1L]] != 12000L ||
        checks$chains[[1L]] != 4L ||
        checks$parallel_chains[[1L]] != 4L ||
        !checks$remedy_2_fit_exists[[1L]] || !checks$valid[[1L]]
    ) {
      stop("The supplement strategy-within structural preflight is invalid.",
           call. = FALSE)
    }
    checks
  }

