make_update_2026_supplement_strategy_within_accepted_fit_manifest <-
  function(
      initial_manifest,
      first_remedy_fit_paths,
      structural_fit_paths,
      structural_specifications,
      final_diagnostic_audit
  ) {
    first_paths <- unname(unlist(first_remedy_fit_paths, use.names = FALSE))
    structural_paths <- unname(unlist(
      structural_fit_paths,
      use.names = FALSE
    ))
    if (
      nrow(initial_manifest) != 72L || length(first_paths) != 2L ||
        length(structural_paths) != 1L ||
        any(!file.exists(c(first_paths, structural_paths))) ||
        any(file.info(c(first_paths, structural_paths))$size <= 0) ||
        !identical(final_diagnostic_audit$family,
                   "supplement_strategy_within") ||
        !isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass) ||
        final_diagnostic_audit$models_passing_sampling != 72L
    ) {
      stop(
        "Accepted supplement strategy-within fits require 72 passing diagnostics.",
        call. = FALSE
      )
    }
    suffix <- " [supplement_strategy_within]"
    initial_manifest <- initial_manifest |>
      dplyr::mutate(
        model_name = dplyr::if_else(
          stringr::str_ends(model_name, stringr::fixed(suffix)),
          model_name,
          paste0(model_name, suffix)
        )
      )
    make_path_manifest <- function(paths, stage) {
      tibble::tibble(
        outcome = basename(dirname(paths)),
        model_index = as.integer(stringr::str_match(
          basename(paths),
          "model_([0-9]+)\\.qs$"
        )[, 2L]),
        fit_path = normalizePath(paths, winslash = "/", mustWork = TRUE),
        stage = stage,
        bytes = file.info(paths)$size,
        sha256 = purrr::map_chr(
          paths,
          ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
        )
      )
    }
    first <- make_path_manifest(first_paths, "remedy_1") |>
      dplyr::filter(outcome == "whole_body", model_index == 9L) |>
      dplyr::left_join(
        initial_manifest |>
          dplyr::select(outcome, model_index, model_name),
        by = c("outcome", "model_index")
      ) |>
      dplyr::select(
        outcome, model_index, model_name, fit_path, stage, bytes, sha256
      )
    structural_names <- dplyr::bind_rows(structural_specifications) |>
      dplyr::transmute(
        outcome,
        model_index = as.integer(model_index),
        model_name = dplyr::if_else(
          stringr::str_ends(model_name, stringr::fixed(suffix)),
          model_name,
          paste0(model_name, suffix)
        )
      )
    structural <- make_path_manifest(
      structural_paths,
      "structural_uncorrelated"
    ) |>
      dplyr::left_join(
        structural_names,
        by = c("outcome", "model_index")
      ) |>
      dplyr::select(
        outcome, model_index, model_name, fit_path, stage, bytes, sha256
      )
    replacements <- dplyr::bind_rows(first, structural)
    accepted <- initial_manifest |>
      dplyr::anti_join(
        replacements |>
          dplyr::select(outcome, model_index),
        by = c("outcome", "model_index")
      ) |>
      dplyr::bind_rows(replacements) |>
      dplyr::arrange(
        factor(
          outcome,
          levels = c("whole_body", "hypertrophy", "strength", "function")
        ),
        model_index
      )
    stage_counts <- table(factor(
      accepted$stage,
      levels = c("initial", "remedy_1", "structural_uncorrelated")
    ))
    name_alignment <- accepted |>
      dplyr::select(outcome, model_index, accepted_name = model_name) |>
      dplyr::left_join(
        final_diagnostic_audit$diagnostic_summary |>
          dplyr::select(outcome, model_index, diagnostic_name = model),
        by = c("outcome", "model_index")
      )
    if (
      nrow(first) != 1L || nrow(structural) != 1L ||
        paste(first$outcome, first$model_index, sep = "::") !=
          "whole_body::9" ||
        paste(structural$outcome, structural$model_index, sep = "::") !=
          "hypertrophy::21" ||
        nrow(accepted) != 72L ||
        anyDuplicated(accepted[c("outcome", "model_index")]) ||
        any(table(accepted$outcome) != 18L) ||
        !identical(as.integer(stage_counts), c(70L, 1L, 1L)) ||
        anyNA(name_alignment) ||
        any(name_alignment$accepted_name != name_alignment$diagnostic_name) ||
        !all(file.exists(accepted$fit_path)) ||
        any(accepted$bytes <= 0) || any(nchar(accepted$sha256) != 64L)
    ) {
      stop("The accepted supplement strategy-within manifest is invalid.",
           call. = FALSE)
    }
    accepted
  }

validate_update_2026_supplement_strategy_within_loo_inputs <- function(
    accepted_fit_manifest,
    final_diagnostic_audit,
    k_threshold = 0.7,
    cores_per_branch = 1L
) {
  stage_counts <- table(factor(
    accepted_fit_manifest$stage,
    levels = c("initial", "remedy_1", "structural_uncorrelated")
  ))
  outcome_counts <- table(factor(
    accepted_fit_manifest$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))
  checks <- tibble::tribble(
    ~check, ~passed,
    "all 72 final supplement strategy-within diagnostics pass",
    identical(final_diagnostic_audit$family,
              "supplement_strategy_within") &&
      isTRUE(final_diagnostic_audit$all_sampling_diagnostics_pass),
    "accepted registry contains 18 models per outcome",
    identical(as.integer(outcome_counts), rep(18L, 4L)),
    "accepted registry contains 70 initial 1 remedy and 1 structural fit",
    identical(as.integer(stage_counts), c(70L, 1L, 1L)),
    "all accepted fit files exist and are nonempty",
    all(file.exists(accepted_fit_manifest$fit_path)) &&
      all(file.info(accepted_fit_manifest$fit_path)$size > 0),
    "all accepted fit hashes and strategy-within names are present",
    all(nchar(accepted_fit_manifest$sha256) == 64L) &&
      all(stringr::str_ends(
        accepted_fit_manifest$model_name,
        stringr::fixed(" [supplement_strategy_within]")
      )),
    "integrated LOO uses 4000 draws a 0.7 threshold and one core per branch",
    identical(k_threshold, 0.7) &&
      identical(as.integer(cores_per_branch), 1L)
  )

  ready <-
    nrow(accepted_fit_manifest) == 72L &&
    !anyDuplicated(accepted_fit_manifest[c("outcome", "model_index")]) &&
    all(checks$passed)
  if (!ready) {
    stop("The supplement strategy-within LOO preflight is incomplete.",
         call. = FALSE)
  }

  list(
    family = "supplement_strategy_within",
    models = 72L,
    loo_draws = 4000L,
    k_threshold = k_threshold,
    cores_per_branch = as.integer(cores_per_branch),
    checks = checks,
    accepted_fit_manifest = accepted_fit_manifest,
    ready = TRUE
  )
}

compute_update_2026_supplement_strategy_within_integrated_loo_to_file <-
  function(
      fit_record,
      enabled,
      loo_draws = 4000L,
      k_threshold = 0.7,
      cores = 1L,
      output_root = here::here(
        "model_archive", "update_2026", "absolute_exposure",
        "supplement_g_day", "strategy_within", "loo", "integrated"
      )
  ) {
    if (!isTRUE(enabled)) {
      stop(
        paste0(
          "Supplement strategy-within LOO is disabled. Set ",
          "PROTEIN_UPDATE_2026_SUPPLEMENT_STRATEGY_WITHIN_LOO=run ",
          "to enable it."
        ),
        call. = FALSE
      )
    }
    result <- compute_mundlak_full_file_integrated_loo(
      fit_record = fit_record,
      loo_draws = loo_draws,
      k_threshold = k_threshold,
      cores = cores,
      family = "supplement_strategy_within",
      slope_description =
        "strategy_modified_supplement_within_contrast_basis_slopes"
    )
    if (
      !inherits(result$loo, "loo") ||
        !inherits(result$conditional_loo, "loo") ||
        !identical(
          unname(as.character(result$family)),
          "supplement_strategy_within"
        ) ||
        !identical(result$remedy, "integrated_observation_level_psis")
    ) {
      stop(
        "Cannot archive an invalid supplement strategy-within LOO result.",
        call. = FALSE
      )
    }
    output_dir <- file.path(output_root, result$outcome)
    dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
    output_file <- file.path(
      output_dir,
      sprintf(
        "model_%02d_integrated_loo.qs",
        as.integer(result$model_index)
      )
    )
    write_atomic_qs(result, output_file)
  }

validate_update_2026_supplement_strategy_within_exact_inputs <- function(
    records,
    integrated_audit,
    config
) {
  expected <- as.integer(integrated_audit$exact_refits_required)

  if (!is.list(records) || length(records) != expected || expected != 35L) {
    stop("Expected 35 supplement strategy-within exact-LOO records.",
         call. = FALSE)
  }
  checks <- purrr::map_dfr(records, function(record) {
    integrated <- qs::qread(record$integrated_loo_path)
    observation <- as.integer(record$observation)
    if (
      !inherits(integrated$loo, "loo") ||
        !identical(
          unname(as.character(integrated$family)),
          "supplement_strategy_within"
        ) ||
        !identical(
          unname(as.character(integrated$outcome)),
          unname(as.character(record$outcome))
        ) ||
        as.integer(integrated$model_index) !=
          as.integer(record$model_index) ||
        observation < 1L ||
        observation > nrow(integrated$observation_manifest)
    ) {
      stop("A supplement strategy-within exact record is invalid.",
           call. = FALSE)
    }
    held_out <- integrated$observation_manifest[
      observation,
      ,
      drop = FALSE
    ]
    observed_k <- as.numeric(
      loo::pareto_k_values(integrated$loo)[[observation]]
    )
    tibble::tibble(
      case_id = as.integer(record$case_id),
      outcome = unname(as.character(record$outcome)),
      model_index = as.integer(record$model_index),
      model_name = unname(as.character(record$model_name)),
      observation = observation,
      study_no = as.character(held_out$study_no[[1L]]),
      arm_no = as.character(held_out$arm_no[[1L]]),
      outcome_no = as.character(held_out$outcome_no[[1L]]),
      pareto_k = observed_k,
      adapt_delta = as.numeric(config$adapt_delta_floor),
      max_treedepth = as.integer(config$max_treedepth_floor),
      iter_warmup = as.integer(config$iter_warmup),
      iter_sampling = as.integer(config$iter_sampling),
      chains = as.integer(config$chains),
      parallel_chains = as.integer(config$parallel_chains),
      original_fit_exists = file.exists(record$original_fit_path),
      integrated_loo_exists = file.exists(record$integrated_loo_path),
      valid = is.finite(observed_k) && observed_k > 0.7
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    checks$outcome,
    checks$model_index,
    checks$observation,
    sep = "::"
  )
  expected_keys <- paste(
    integrated_audit$high_k_cases$outcome,
    integrated_audit$high_k_cases$model_index,
    integrated_audit$high_k_cases$observation,
    sep = "::"
  )
  outcome_counts <- table(factor(
    checks$outcome,
    levels = c("whole_body", "hypertrophy", "strength", "function")
  ))

  if (
    nrow(checks) != expected || anyDuplicated(observed_keys) ||
      !setequal(observed_keys, expected_keys) ||
      !identical(checks$case_id, seq_len(expected)) ||
      !identical(as.integer(outcome_counts), c(1L, 18L, 0L, 16L)) ||
      !all(checks$original_fit_exists) ||
      !all(checks$integrated_loo_exists) || !all(checks$valid) ||
      config$chains != 4L || config$parallel_chains != 4L ||
      config$iter_warmup != 2000L || config$iter_sampling != 6000L ||
      config$adapt_delta_floor != 0.999 ||
      config$max_treedepth_floor != 15L
  ) {
    stop(
      "The supplement strategy-within exact-LOO preflight is incomplete.",
      call. = FALSE
    )
  }

  checks
}

write_update_2026_supplement_strategy_within_exact_preflight <- function(
