make_update_2026_supplement_strategy_within_final_exact_audit <- function(
    records,
    initial_fit_paths,
    remedy_fit_path,
    initial_audit,
    remedy_audit
) {
  initial_fit_paths <- unname(unlist(initial_fit_paths, use.names = FALSE))
  remedy_fit_path <- unname(unlist(remedy_fit_path, use.names = FALSE))

  if (
    initial_audit$exact_refits != 35L ||
      initial_audit$exact_refits_requiring_remediation != 1L ||
      remedy_audit$exact_refits != 1L ||
      !isTRUE(remedy_audit$all_exact_refit_diagnostics_pass) ||
      length(records) != 35L || length(initial_fit_paths) != 35L ||
      length(remedy_fit_path) != 1L ||
      any(!file.exists(initial_fit_paths)) || !file.exists(remedy_fit_path)
  ) {
    stop(
      "The supplement strategy-within exact fits are not ready to combine.",
      call. = FALSE
    )
  }

  record_manifest <- purrr::map2_dfr(
    records,
    initial_fit_paths,
    function(record, path) {
      tibble::tibble(
        case_id = as.integer(record$case_id),
        outcome = unname(as.character(record$outcome)),
        model_index = as.integer(record$model_index),
        model_name = unname(as.character(record$model_name)),
        observation = as.integer(record$observation),
        stage = "exact_initial",
        exact_fit_path = normalizePath(
          path,
          winslash = "/",
          mustWork = TRUE
        )
      )
    }
  ) |>
    dplyr::arrange(case_id)

  remedy_key <- "hypertrophy::12::134"
  manifest_keys <- paste(
    record_manifest$outcome,
    record_manifest$model_index,
    record_manifest$observation,
    sep = "::"
  )
  remedy_row <- match(remedy_key, manifest_keys)

  if (
    is.na(remedy_row) ||
      record_manifest$case_id[[remedy_row]] != 8L
  ) {
    stop("The supplement exact remedy has the wrong identity.", call. = FALSE)
  }

  record_manifest$stage[[remedy_row]] <- "exact_remedy_1"
  record_manifest$exact_fit_path[[remedy_row]] <- normalizePath(
    remedy_fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  record_manifest <- record_manifest |>
    dplyr::mutate(
      bytes = file.info(exact_fit_path)$size,
      sha256 = purrr::map_chr(
        exact_fit_path,
        ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
      )
    )

  case_lookup <- record_manifest |>
    dplyr::select(case_id, outcome, model_index, observation)
  initial_summary <- initial_audit$diagnostic_summary |>
    dplyr::left_join(
      case_lookup,
      by = c("outcome", "model_index", "observation"),
      relationship = "one-to-one"
    ) |>
    dplyr::relocate(case_id)
  remedy_summary <- remedy_audit$diagnostic_summary |>
    dplyr::left_join(
      case_lookup,
      by = c("outcome", "model_index", "observation"),
      relationship = "one-to-one"
    ) |>
    dplyr::relocate(case_id)
  diagnostic_summary <- initial_summary |>
    dplyr::filter(case_id != 8L) |>
    dplyr::bind_rows(remedy_summary) |>
    dplyr::left_join(
      record_manifest |>
        dplyr::select(case_id, stage),
      by = "case_id",
      relationship = "one-to-one"
    ) |>
    dplyr::arrange(case_id)

  stage_counts <- table(factor(
    record_manifest$stage,
    levels = c("exact_initial", "exact_remedy_1")
  ))
  if (
    nrow(record_manifest) != 35L ||
      !identical(record_manifest$case_id, seq_len(35L)) ||
      anyDuplicated(manifest_keys) ||
      !identical(as.integer(stage_counts), c(34L, 1L)) ||
      any(record_manifest$bytes <= 0) ||
      any(nchar(record_manifest$sha256) != 64L) ||
      nrow(diagnostic_summary) != 35L ||
      !identical(diagnostic_summary$case_id, seq_len(35L)) ||
      anyDuplicated(diagnostic_summary$case_id) ||
      !all(diagnostic_summary$diagnostic_pass)
  ) {
    stop(
      "The supplement strategy-within final exact audit is invalid.",
      call. = FALSE
    )
  }

  list(
    family = "supplement_strategy_within",
    diagnostic_summary = diagnostic_summary,
    accepted_exact_fit_manifest = record_manifest,
    exact_refits = 35L,
    exact_refits_passing = 35L,
    exact_refits_requiring_remediation = 0L,
    all_exact_refit_diagnostics_pass = TRUE
  )
}

write_update_2026_supplement_strategy_within_final_exact_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy_within", "loo_exact", "final"
    )
) {
  if (
    !identical(audit$family, "supplement_strategy_within") ||
      audit$exact_refits != 35L ||
      nrow(audit$diagnostic_summary) != 35L ||
      nrow(audit$accepted_exact_fit_manifest) != 35L ||
      !isTRUE(audit$all_exact_refit_diagnostics_pass)
  ) {
    stop("Cannot write an incomplete final exact audit.", call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    accepted_exact_fit_manifest = file.path(
      output_dir,
      "accepted_exact_fit_manifest.csv"
    )
  )
  readr::write_csv(audit$diagnostic_summary, paths[["diagnostic_summary"]])
  readr::write_csv(
    audit$accepted_exact_fit_manifest,
    paths[["accepted_exact_fit_manifest"]]
  )
  unname(paths)
}

make_update_2026_supplement_strategy_within_accepted_exact_records <-
  function(manifest) {
    if (
      !is.data.frame(manifest) || nrow(manifest) != 35L ||
        !identical(manifest$case_id, seq_len(35L)) ||
        any(!file.exists(manifest$exact_fit_path))
    ) {
      stop("The accepted exact-fit manifest is invalid.", call. = FALSE)
    }
    purrr::map(seq_len(nrow(manifest)), function(row) {
      purrr::map(as.list(manifest[row, , drop = FALSE]), unname)
    })
  }

update_2026_supplement_strategy_within_exact_correction_path <- function(
    refit
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "strategy_within", "loo", "exact_correction",
    refit$outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  file.path(
    directory,
    sprintf(
      "model_%02d_case_%03d_observation_%04d.qs",
      as.integer(refit$model_index),
      as.integer(refit$case_id),
      as.integer(refit$observation)
    )
  )
}

compute_update_2026_supplement_strategy_within_exact_correction <- function(
    record,
    diagnostic_audit,
    enabled
) {
  if (!isTRUE(enabled)) {
    stop("Supplement strategy-within exact correction is disabled.",
         call. = FALSE)
  }

  exact_fit_path <- unname(as.character(record$exact_fit_path))
  refit <- read_sensitivity_full_exact_loo_file(
    exact_fit_path,
    "supplement_strategy_within"
  )
  output_file <-
    update_2026_supplement_strategy_within_exact_correction_path(refit)

  if (file.exists(output_file) && file.info(output_file)$size > 0) {
    archived <- tryCatch(qs::qread(output_file), error = function(error) NULL)
    if (
      !is.null(archived) && inherits(archived$loo, "loo") &&
        as.integer(archived$case_id) == as.integer(refit$case_id) &&
        identical(archived$outcome, refit$outcome) &&
        as.integer(archived$model_index) == as.integer(refit$model_index) &&
        as.integer(archived$exact_refit_summary$observation[[1L]]) ==
          as.integer(refit$observation)
    ) {
      return(normalizePath(output_file, winslash = "/", mustWork = TRUE))
    }
    stop("An existing exact correction is invalid.", call. = FALSE)
  }

  correction <- compute_sensitivity_full_exact_loo_file(
    path = exact_fit_path,
    diagnostic_audit = diagnostic_audit,
    family = "supplement_strategy_within"
  )
  if (
    !inherits(correction$loo, "loo") ||
      as.integer(correction$case_id) != as.integer(refit$case_id) ||
      nrow(correction$exact_refit_summary) != 1L ||
      !isTRUE(correction$exact_refit_summary$diagnostic_pass[[1L]])
  ) {
    stop("The supplement strategy-within correction is invalid.",
         call. = FALSE)
  }

  write_atomic_qs(correction, output_file)
}

audit_update_2026_supplement_strategy_within_exact_corrections <- function(
    paths,
    integrated_audit
) {
  paths <- unname(unlist(paths, use.names = FALSE))
  expected <- as.integer(integrated_audit$exact_refits_required)

  if (
    length(paths) != expected || expected != 35L || anyNA(paths) ||
      any(!file.exists(paths)) || any(file.info(paths)$size <= 0)
  ) {
    stop("The exact-correction files are incomplete.", call. = FALSE)
  }

  corrections <- purrr::map(paths, qs::qread)
  diagnostic_summary <- purrr::map_dfr(
    corrections,
    "exact_refit_summary"
  ) |>
    dplyr::arrange(
      factor(outcome, levels = c(
        "whole_body", "hypertrophy", "strength", "function"
      )),
      model_index,
      observation
    )

  manifest <- purrr::map2_dfr(paths, corrections, function(path, result) {
    tibble::tibble(
      case_id = as.integer(result$case_id),
      outcome = result$outcome,
      model_index = as.integer(result$model_index),
      model_name = result$model_name,
      observation =
        as.integer(result$exact_refit_summary$observation[[1L]]),
      correction_path = normalizePath(path, winslash = "/", mustWork = TRUE),
      bytes = file.info(path)$size,
      sha256 = digest::digest(file = path, algo = "sha256", serialize = FALSE)
    )
  }) |>
    dplyr::arrange(case_id)

  observed_keys <- paste(
    manifest$outcome,
    manifest$model_index,
    manifest$observation,
    sep = "::"
  )
  expected_keys <- paste(
    integrated_audit$high_k_cases$outcome,
    integrated_audit$high_k_cases$model_index,
    integrated_audit$high_k_cases$observation,
    sep = "::"
  )

  if (
    nrow(diagnostic_summary) != 35L || nrow(manifest) != 35L ||
      anyDuplicated(observed_keys) || !setequal(observed_keys, expected_keys) ||
      !identical(manifest$case_id, seq_len(35L)) ||
      !all(diagnostic_summary$diagnostic_pass)
  ) {
    stop("The exact-correction audit is invalid.", call. = FALSE)
  }

  list(
    diagnostic_summary = diagnostic_summary,
    correction_manifest = manifest,
    exact_refits = 35L,
    exact_refits_passing = 35L,
    exact_refits_requiring_remediation = 0L,
    all_exact_refit_diagnostics_pass = TRUE
  )
}

write_update_2026_supplement_strategy_within_correction_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy_within", "loo_exact", "corrections"
    )
) {
  if (
    audit$exact_refits != 35L ||
      nrow(audit$diagnostic_summary) != 35L ||
      nrow(audit$correction_manifest) != 35L
  ) {
    stop("Cannot write an incomplete exact-correction audit.", call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    diagnostic_summary = file.path(output_dir, "diagnostic_summary.csv"),
    correction_manifest = file.path(output_dir, "correction_manifest.csv")
  )
  readr::write_csv(audit$diagnostic_summary, paths[["diagnostic_summary"]])
  readr::write_csv(audit$correction_manifest, paths[["correction_manifest"]])
