}

read_update_2026_supplement_strategy_within_corrections <- function(manifest) {
  if (
    !is.data.frame(manifest) || nrow(manifest) != 35L ||
      any(!file.exists(manifest$correction_path))
  ) {
    stop("The exact-correction manifest is invalid.", call. = FALSE)
  }
  corrections <- purrr::map(manifest$correction_path, qs::qread)
  corrections <- corrections[order(purrr::map_int(corrections, "case_id"))]
  if (
    !identical(purrr::map_int(corrections, "case_id"), seq_len(35L)) ||
      any(!purrr::map_lgl(corrections, ~ inherits(.x$loo, "loo")))
  ) {
    stop("The exact corrections are invalid.", call. = FALSE)
  }
  corrections
}

make_update_2026_supplement_strategy_within_final_loo_audit <- function(
    integrated_manifest,
    exact_corrections,
    correction_audit
) {
  retained <- setdiff(
    seq_len(26L),
    c(3L, 7L, 10L, 13L, 16L, 19L, 22L, 25L)
  )

  if (!isTRUE(correction_audit$all_exact_refit_diagnostics_pass)) {
    stop("Final LOO requires all exact corrections.", call. = FALSE)
  }
  final <- apply_sensitivity_full_exact_loo_corrections_from_files(
    integrated_manifest = integrated_manifest,
    exact_results = exact_corrections,
    family = "supplement_strategy_within",
    expected_models = 72L,
    expected_indices = retained
  )
  outcome_summary <- final$model_summary |>
    dplyr::summarise(
      models = dplyr::n(),
      models_with_unresolved_high_k = sum(n_pareto_k_gt_threshold > 0L),
      unresolved_high_k_cases = sum(n_pareto_k_gt_threshold),
      maximum_remaining_pareto_k = max(maximum_pareto_k, na.rm = TRUE),
      .by = outcome
    )

  correction_counts <- correction_audit$diagnostic_summary |>
    dplyr::count(outcome, model_index, name = "exact_corrections")
  final_manifest <- integrated_manifest |>
    dplyr::left_join(correction_counts, by = c("outcome", "model_index")) |>
    dplyr::mutate(
      exact_corrections = tidyr::replace_na(exact_corrections, 0L),
      final_method = dplyr::if_else(
        exact_corrections > 0L,
        "integrated_observation_level_psis_plus_exact",
        "integrated_observation_level_psis"
      )
    )

  if (
    !isTRUE(final$stacking_ready) || nrow(final$model_summary) != 72L ||
      nrow(outcome_summary) != 4L || any(outcome_summary$models != 18L) ||
      any(outcome_summary$unresolved_high_k_cases != 0L) ||
      nrow(final_manifest) != 72L ||
      sum(final_manifest$exact_corrections) != 35L
  ) {
    stop("The final LOO audit is not stacking-ready.", call. = FALSE)
  }

  final$family <- "supplement_strategy_within"
  final$outcome_summary <- outcome_summary
  final$final_loo_manifest <- final_manifest
  final$exact_refits <- 35L
  final$all_exact_refit_diagnostics_pass <- TRUE
  final
}

write_update_2026_supplement_strategy_within_final_loo_audit <- function(
    audit,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy_within", "loo_final"
    )
) {
  if (
    !isTRUE(audit$stacking_ready) || nrow(audit$model_summary) != 72L ||
      nrow(audit$outcome_summary) != 4L ||
      nrow(audit$exact_refit_summary) != 35L ||
      nrow(audit$final_loo_manifest) != 72L
  ) {
    stop("Cannot write an incomplete final LOO audit.", call. = FALSE)
  }

  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    final_loo_manifest = file.path(output_dir, "final_loo_manifest.csv"),
    model_summary = file.path(output_dir, "model_summary.csv"),
    outcome_summary = file.path(output_dir, "outcome_summary.csv"),
    exact_refit_summary = file.path(output_dir, "exact_refit_summary.csv")
  )
  readr::write_csv(audit$final_loo_manifest, paths[["final_loo_manifest"]])
  readr::write_csv(audit$model_summary, paths[["model_summary"]])
  readr::write_csv(audit$outcome_summary, paths[["outcome_summary"]])
  readr::write_csv(audit$exact_refit_summary, paths[["exact_refit_summary"]])
  unname(paths)
}

make_update_2026_supplement_strategy_within_prediction_records <- function(
    accepted_fit_manifest,
    stacking_weights,
    n_draws = 4000L,
    exposure_minimum_g_day = 0,
    grid_step_g_day = 1,
    seed = 244988L
) {
  records <- make_update_2026_total_strategy_within_prediction_records(
    accepted_fit_manifest = accepted_fit_manifest,
    stacking_weights = stacking_weights,
    n_draws = n_draws,
    exposure_minimum_g_day = exposure_minimum_g_day,
    grid_step_g_day = grid_step_g_day,
    seed = seed
  )

  records <- purrr::map(records, function(record) {
    record$family <- "supplement_strategy_within"
    record$prediction_type <- "supplement_strategy_within"
    record
  })
  allocation <- purrr::map_dfr(records, function(record) {
    tibble::tibble(
      outcome = record$outcome,
      allocated_draws = as.integer(record$draw_count)
    )
  }) |>
    dplyr::summarise(
      allocated_draws = sum(allocated_draws),
      .by = outcome
    )

  if (
    length(records) < 4L || nrow(allocation) != 4L ||
      any(allocation$allocated_draws != n_draws) ||
      any(!purrr::map_lgl(records, function(record) {
        identical(record$family, "supplement_strategy_within") &&
          identical(record$prediction_type, "supplement_strategy_within")
      }))
  ) {
    stop("The prediction allocation is incomplete.", call. = FALSE)
  }

  records
}

make_update_2026_supplement_strategy_within_reporting_preflight <- function(
    records,
    data_by_outcome
) {
  if (!is.list(records) || length(records) < 4L) {
    stop("The prediction allocation is incomplete.", call. = FALSE)
  }

  checks <- purrr::map_dfr(records, function(record) {
    data <- data_by_outcome[[record$outcome]]
    maximum <- if (
      is.data.frame(data) &&
        "protein_intake_raw_treatment" %in% names(data)
    ) {
      max(data$protein_intake_raw_treatment, na.rm = TRUE)
    } else {
      NA_real_
    }
    reference <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_reference_g_day)
    } else {
      NA_real_
    }
    unit <- if (is.data.frame(data)) {
      unique(data$absolute_exposure_unit_g_day)
    } else {
      NA_real_
    }
    tibble::tibble(
      outcome = unname(as.character(record$outcome)),
      model_index = as.integer(record$model_index),
      model_name = unname(as.character(record$model_name)),
      family = unname(as.character(record$family)),
      prediction_type = unname(as.character(record$prediction_type)),
      weight = as.numeric(record$weight),
      allocated_draws = as.integer(record$draw_count),
      prediction_seed = as.integer(record$prediction_seed),
      exposure_minimum_g_day = as.numeric(record$protein_min),
      exposure_maximum_g_day = as.numeric(maximum),
      reference_g_day = as.numeric(reference),
      internal_unit_g_day = as.numeric(unit),
      grid_step_g_day = as.numeric(record$grid_step),
      fit_path = unname(as.character(record$fit_path)),
      fit_exists = file.exists(record$fit_path),
      valid = record$draw_count > 0L && file.exists(record$fit_path) &&
        identical(
          unname(as.character(record$family)),
          "supplement_strategy_within"
        ) &&
        identical(
          unname(as.character(record$prediction_type)),
          "supplement_strategy_within"
        ) &&
        nchar(record$fit_sha256) == 64L &&
        is.finite(record$protein_min) && is.finite(maximum) &&
        maximum > record$protein_min &&
        length(reference) == 1L && reference == 0 &&
        length(unit) == 1L && unit == 25
    )
  }) |>
    dplyr::arrange(
      factor(
        outcome,
        levels = c("whole_body", "hypertrophy", "strength", "function")
      ),
      model_index
    )

  outcome_audit <- checks |>
    dplyr::summarise(
      selected_models = dplyr::n(),
      allocated_draws = sum(allocated_draws),
      retained_weight = sum(weight),
      .by = outcome
    )

  if (
    nrow(outcome_audit) != 4L ||
      any(outcome_audit$selected_models < 1L) ||
      any(outcome_audit$allocated_draws != 4000L) ||
      any(!is.finite(outcome_audit$retained_weight)) ||
      any(outcome_audit$retained_weight <= 0) ||
      any(outcome_audit$retained_weight > 1 + 1e-8) ||
      anyDuplicated(checks[c("outcome", "model_index")]) ||
      any(checks$exposure_minimum_g_day != 0) ||
      any(checks$reference_g_day != 0) ||
      any(checks$internal_unit_g_day != 25) ||
      any(checks$grid_step_g_day != 1) || !all(checks$valid)
  ) {
    stop("The reporting preflight failed.", call. = FALSE)
  }

  checks
}

write_update_2026_supplement_strategy_within_reporting_preflight <- function(
    checks,
    output_file = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy_within", "reporting", "input_preflight.csv"
    )
) {
  outcome_draws <- tapply(checks$allocated_draws, checks$outcome, sum)
  if (
    length(outcome_draws) != 4L || any(outcome_draws != 4000L) ||
      any(checks$reference_g_day != 0) ||
      any(checks$internal_unit_g_day != 25) || !all(checks$valid)
  ) {
    stop("Cannot write an invalid reporting preflight.", call. = FALSE)
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(checks, output_file, na = "")
  output_file
}

update_2026_supplement_strategy_within_reporting_path <- function(
    outcome,
    stage,
    model_index = NULL
) {
  directory <- here::here(
    "model_archive", "update_2026", "absolute_exposure",
    "supplement_g_day", "strategy_within", "reporting", stage, outcome
  )
  dir.create(directory, recursive = TRUE, showWarnings = FALSE)
  filename <- if (is.null(model_index)) {
    paste0(stage, ".qs")
  } else {
    sprintf("model_%02d_%s.qs", as.integer(model_index), stage)
  }
  file.path(directory, filename)
}

write_update_2026_supplement_strategy_within_prediction_draw_file <-
  function(record, data_by_outcome, result_path) {
    if (
      length(record$fit_path) != 1L || is.na(record$fit_path) ||
        !file.exists(record$fit_path) || record$draw_count < 1L ||
        !identical(
          unname(as.character(record$family)),
          "supplement_strategy_within"
        )
    ) {
      stop("A prediction record is invalid.", call. = FALSE)
    }
    candidate <- read_sensitivity_fit_file(record$fit_path)
    if (
      !identical(
        unname(as.character(candidate$family)),
        "supplement_strategy_within"
      ) ||
        !identical(
          unname(as.character(candidate$outcome)),
          unname(as.character(record$outcome))
        ) ||
        as.integer(candidate$model_index) != as.integer(record$model_index) ||
        !identical(
          unname(as.character(candidate$model_name)),
          unname(as.character(record$model_name))
        )
    ) {
      stop("A prediction fit does not match its record.", call. = FALSE)
    }
    data <- data_by_outcome[[record$outcome]]
    grid <- make_protein_strategy_within_prediction_grid(
      fitted_candidate = candidate,
      data = data,
      protein_min = as.numeric(record$protein_min),
      protein_max = max(data$protein_intake_raw_treatment, na.rm = TRUE),
      grid_step = as.numeric(record$grid_step),
      reference_raw = 0
    )
    old_mc_cores <- getOption("mc.cores")
    on.exit(options(mc.cores = old_mc_cores), add = TRUE)
    options(mc.cores = 1L)
    set.seed(as.integer(record$prediction_seed))
    draws <- as.matrix(brms::posterior_epred(
      candidate$model,
      newdata = grid$newdata,
      re_formula = NA,
      ndraws = as.integer(record$draw_count)
    ))
    if (ncol(draws) != nrow(grid$keys) && nrow(draws) == nrow(grid$keys)) {
      draws <- t(draws)
    }
    if (
      nrow(draws) != record$draw_count ||
        ncol(draws) != nrow(grid$keys) || anyNA(draws)
    ) {
      stop("Prediction draws are incomplete.", call. = FALSE)
    }
    reduction <- list(
      family = "supplement_strategy_within",
      outcome = record$outcome,
      model_index = as.integer(record$model_index),
      model_name = record$model_name,
      weight = as.numeric(record$weight),
      draw_count = as.integer(record$draw_count),
      prediction_seed = as.integer(record$prediction_seed),
      fit_sha256 = record$fit_sha256,
      grid = grid$keys,
      draws = draws,
      settings = list(
        protein_min = grid$protein_min,
        protein_max = grid$protein_max,
        grid_step = grid$grid_step,
        prediction_type = "supplement_strategy_within",
        reference_intake = 0,
        internal_unit_g_day = 25
      )
    )
    write_atomic_qs(reduction, result_path)
  }

write_update_2026_supplement_strategy_within_reporting_file <- function(
    model_average_path,
    data_by_outcome,
    result_path,
    sesoi = 0.10
) {
  model_average <- read_sensitivity_full_model_average_file(
    model_average_path,
    family = "supplement_strategy_within"
  )
  outcome <- model_average$outcome
  data <- data_by_outcome[[outcome]]
  strategy_summary <- build_protein_strategy_within_pilot_reporting(
    model_average = model_average,
    data = data,
    outcome = outcome
  )
  strategy_reports <- purrr::map(
    c("Substitution", "Addition"),
    function(strategy) {
      strategy_average <- subset_protein_strategy_model_average(
        model_average,
        strategy
      )
      strategy_data <- dplyr::filter(data, protein_strategy == strategy)
      absolute <- summarise_primary_dose_response(strategy_average)
      supported <- build_sensitivity_within_reporting_pilot(
        absolute,
        strategy_average,
        strategy_data,
        reference_intake = 0
      )
      heatmap <- compute_primary_heatmap_contrasts(
        model_average = strategy_average,
        data = dplyr::mutate(
          strategy_data,
          protein_intake_raw = protein_intake_raw_treatment
        ),
        protein_min = 0,
        sesoi = sesoi
      )
      annotate <- function(table) {
        dplyr::mutate(table, protein_strategy = strategy, .before = 1L)
      }
      list(
        increments = annotate(supported$increments_full_grid),
        support = annotate(supported$support_by_group),
        common_support = annotate(supported$common_support),
        pairwise = annotate(heatmap$contrasts),
        pairwise_support = annotate(heatmap$support),
        local_equivalence = annotate(
          summarise_primary_local_equivalence(
            heatmap$contrasts,
            outcome = outcome
          )
        )
      )
    }
  )

  bind_component <- function(name) {
    dplyr::bind_rows(purrr::map(strategy_reports, name))
  }
  report <- list(
    family = "supplement_strategy_within",
    outcome = outcome,
    dose_response = strategy_summary$dose_response_contrasts,
    dose_response_increments = bind_component("increments"),
    exposure_support_by_group = strategy_summary$support,
    common_exposure_support = strategy_summary$common_support,
    addition_minus_substitution =
      strategy_summary$addition_minus_substitution,
    pairwise_contrasts = bind_component("pairwise"),
    pairwise_support = bind_component("pairwise_support"),
    local_equivalence = bind_component("local_equivalence"),
    model_weights = tibble::tibble(
      model_name = names(model_average$model_weights),
      weight = as.numeric(model_average$model_weights)
    ),
    settings = utils::modifyList(
      model_average$settings,
      list(
        reference_intake = 0,
        protein_min = 0,
        sesoi = sesoi,
        internal_unit_g_day = 25
      )
    )
  )

  write_atomic_qs(report, result_path)
}

write_update_2026_supplement_strategy_within_reporting_audit <- function(
    audit,
    prediction_manifest,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy_within", "reporting"
    )
) {
  if (
    !identical(audit$family, "supplement_strategy_within") ||
      !isTRUE(audit$all_reporting_checks_pass) ||
      nrow(audit$summary) != 4L ||
      sum(prediction_manifest$draw_count) != 16000L
  ) {
    stop("The reporting audit is incomplete.", call. = FALSE)
  }

  reports <- purrr::map(
    audit$summary$reporting_path,
    read_protein_strategy_within_full_reporting_file,
    family = "supplement_strategy_within"
  )
  bind_report <- function(name) {
    purrr::map_dfr(reports, function(report) {
      dplyr::mutate(report[[name]], outcome = report$outcome, .before = 1L)
    })
  }
  model_weights <- purrr::map_dfr(reports, function(report) {
    dplyr::mutate(report$model_weights, outcome = report$outcome, .before = 1L)
  })
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    prediction_manifest = file.path(output_dir, "prediction_manifest.csv"),
    dose_response = file.path(output_dir, "dose_response.csv"),
    dose_response_increments = file.path(output_dir, "dose_response_increments.csv"),
    exposure_support_by_group = file.path(output_dir, "exposure_support_by_group.csv"),
    common_exposure_support = file.path(output_dir, "common_exposure_support.csv"),
    addition_minus_substitution = file.path(output_dir, "addition_minus_substitution.csv"),
    pairwise_contrasts = file.path(output_dir, "pairwise_contrasts.csv.gz"),
    pairwise_support = file.path(output_dir, "pairwise_support.csv"),
    local_equivalence = file.path(output_dir, "local_equivalence.csv"),
    model_weights = file.path(output_dir, "model_weights.csv")
  )

  readr::write_csv(audit$summary, paths[["summary"]])
  readr::write_csv(prediction_manifest, paths[["prediction_manifest"]])
  readr::write_csv(bind_report("dose_response"), paths[["dose_response"]])
  readr::write_csv(
    bind_report("dose_response_increments"),
    paths[["dose_response_increments"]]
  )
  readr::write_csv(
    bind_report("exposure_support_by_group"),
    paths[["exposure_support_by_group"]]
  )
  readr::write_csv(
    bind_report("common_exposure_support"),
    paths[["common_exposure_support"]]
  )
  readr::write_csv(
    bind_report("addition_minus_substitution"),
    paths[["addition_minus_substitution"]]
  )
  readr::write_csv(
    bind_report("pairwise_contrasts"),
    paths[["pairwise_contrasts"]]
  )
  readr::write_csv(
    bind_report("pairwise_support"),
    paths[["pairwise_support"]]
  )
  readr::write_csv(
    bind_report("local_equivalence"),
    paths[["local_equivalence"]]
  )
  readr::write_csv(model_weights, paths[["model_weights"]])
  unname(paths)
}

make_update_2026_supplement_strategy_within_verification_checkpoint <-
  function(
    source_manifest,
    preparation_audit,
    absolute_audit,
    strategy_audit_review,
    strategy_audit,
    data_by_outcome,
    input_preflight,
    specifications,
    accepted_fit_manifest,
    diagnostic_audit,
    integrated_loo_audit,
    final_exact_audit,
    correction_audit,
    final_loo_audit,
    stacking_weights,
    prediction_manifest,
    reporting_audit
  ) {
    outcomes <- c("whole_body", "hypertrophy", "strength", "function")
    analysis_data <- purrr::imap_dfr(
      data_by_outcome,
      ~ dplyr::mutate(.x, analysis_outcome = .y, .before = 1L)
    )
    specification_table <- dplyr::bind_rows(specifications) |>
      dplyr::arrange(factor(outcome, levels = outcomes), model_index)
    registry_keys <- function(table) {
      table |>
        dplyr::distinct(outcome, model_index) |>
        dplyr::arrange(outcome, model_index) |>
        dplyr::transmute(key = paste(outcome, model_index, sep = "::")) |>
        dplyr::pull(key)
    }
    specification_keys <- registry_keys(specification_table)
    accepted_keys <- registry_keys(accepted_fit_manifest)
    diagnostic_keys <- registry_keys(diagnostic_audit$diagnostic_summary)
    loo_keys <- registry_keys(final_loo_audit$model_summary)
    weight_keys <- registry_keys(stacking_weights)
    common_registry <-
      identical(specification_keys, accepted_keys) &&
      identical(specification_keys, diagnostic_keys) &&
      identical(specification_keys, loo_keys) &&
      identical(specification_keys, weight_keys)
    name_alignment <- specification_table |>
      dplyr::select(
        outcome,
        model_index,
        specification_name = model_name
      ) |>
      dplyr::mutate(
        expected_name = dplyr::if_else(
          outcome == "hypertrophy" & model_index == 21L,
          paste0(
            specification_name,
            " [uncorrelated study effects remedy]",
            " [supplement_strategy_within]"
          ),
          paste0(specification_name, " [supplement_strategy_within]")
        )
      ) |>
      dplyr::left_join(
        accepted_fit_manifest |>
          dplyr::select(outcome, model_index, fit_name = model_name),
        by = c("outcome", "model_index")
      ) |>
      dplyr::left_join(
        diagnostic_audit$diagnostic_summary |>
          dplyr::select(outcome, model_index, diagnostic_name = model),
        by = c("outcome", "model_index")
      ) |>
      dplyr::left_join(
        final_loo_audit$model_summary |>
          dplyr::select(outcome, model_index, loo_name = model_name),
        by = c("outcome", "model_index")
      ) |>
      dplyr::left_join(
        stacking_weights |>
          dplyr::select(outcome, model_index, weight_name = model_name),
        by = c("outcome", "model_index")
      )
    accepted_stages <- table(factor(
      accepted_fit_manifest$stage,
      levels = c("initial", "remedy_1", "structural_uncorrelated")
    ))
    exact_stages <- table(factor(
      final_exact_audit$accepted_exact_fit_manifest$stage,
      levels = c("exact_initial", "exact_remedy_1")
    ))
    weight_sums <- stacking_weights |>
      dplyr::summarise(
        models = dplyr::n(),
        weight_sum = sum(weight),
        .by = outcome
      )
    prediction_sums <- prediction_manifest |>
      dplyr::summarise(
        selected_models = dplyr::n(),
        draws = sum(draw_count),
        retained_weight = sum(weight),
        .by = outcome
      )
    reports <- purrr::map(
      reporting_audit$summary$reporting_path,
      read_protein_strategy_within_full_reporting_file,
      family = "supplement_strategy_within"
    )
    bind_report <- function(name) {
      purrr::map_dfr(reports, function(report) {
        dplyr::mutate(
          report[[name]],
          outcome = report$outcome,
          .before = 1L
        )
      })
    }
    reporting_model_weights <- purrr::map_dfr(reports, function(report) {
      dplyr::mutate(
        report$model_weights,
        outcome = report$outcome,
        .before = 1L
      )
    })
    reporting_weight_sums <- reporting_model_weights |>
      dplyr::summarise(
        models = dplyr::n(),
        weight_sum = sum(weight),
        .by = outcome
      )
    checks <- tibble::tibble(
      check = c(
        "three immutable source files have hashes",
        "the combined-data preparation audit remains valid",
        "the shared absolute-exposure audit remains valid",
        "the confirmed strategy classifications remain valid",
        "all four strategy-within datasets and 72 inputs are valid",
        "all five final registries contain the same 72 model keys",
        "model names agree across specifications fits diagnostics LOO and weights",
        "all 72 accepted fit files exist with the audited remedy stages",
        "all 72 accepted sampling diagnostics pass",
        "initial LOO contains 72 models and 35 audited high-k cases",
        "all 35 accepted exact refits and compact corrections are valid",
        "final corrected LOO contains no unresolved high-k cases",
        "four stacking vectors contain 18 models and sum to one",
        "prediction allocation contains 4000 draws per outcome",
        "all four supplement strategy-within reporting audits pass"
      ),
      passed = c(
        nrow(source_manifest) == 3L &&
          all(nchar(source_manifest$sha256) == 64L),
        all(preparation_audit$checks$passed),
        all(absolute_audit$checks$passed) &&
          isTRUE(absolute_audit$ready_for_review),
        isTRUE(strategy_audit_review$audit_ready) &&
          strategy_audit_review$pending_confirmations == 0L &&
          all(strategy_audit_review$structural_checks$passed) &&
          all(strategy_audit$classification_confirmed) &&
          all(strategy_audit$review_status == "Confirmed"),
        identical(names(data_by_outcome), outcomes) &&
          nrow(input_preflight) == 72L &&
          all(input_preflight$family == "supplement_strategy_within") &&
          all(input_preflight$valid) &&
          all(input_preflight$reference_g_day == 0) &&
          all(input_preflight$internal_unit_g_day == 25) &&
          setequal(
            unique(analysis_data$protein_strategy),
            c("Addition", "Substitution")
          ) &&
          all(is.finite(analysis_data$yi)) &&
          all(is.finite(analysis_data$vi)) && all(analysis_data$vi > 0),
        common_registry && length(specification_keys) == 72L,
        nrow(name_alignment) == 72L &&
          all(stats::complete.cases(name_alignment)) &&
          all(name_alignment$fit_name == name_alignment$expected_name) &&
          all(name_alignment$diagnostic_name == name_alignment$expected_name) &&
          all(name_alignment$loo_name == name_alignment$expected_name) &&
          all(name_alignment$weight_name == name_alignment$expected_name),
        nrow(accepted_fit_manifest) == 72L &&
          identical(as.integer(accepted_stages), c(70L, 1L, 1L)) &&
          all(file.exists(accepted_fit_manifest$fit_path)) &&
          all(accepted_fit_manifest$bytes > 0) &&
          all(nchar(accepted_fit_manifest$sha256) == 64L),
        identical(diagnostic_audit$family, "supplement_strategy_within") &&
          diagnostic_audit$models == 72L &&
          diagnostic_audit$models_passing_sampling == 72L &&
          isTRUE(diagnostic_audit$all_sampling_diagnostics_pass),
        integrated_loo_audit$models == 72L &&
          integrated_loo_audit$exact_refits_required == 35L &&
          nrow(integrated_loo_audit$high_k_cases) == 35L,
        final_exact_audit$exact_refits == 35L &&
          final_exact_audit$exact_refits_passing == 35L &&
          identical(as.integer(exact_stages), c(34L, 1L)) &&
          isTRUE(final_exact_audit$all_exact_refit_diagnostics_pass) &&
          correction_audit$exact_refits == 35L &&
          correction_audit$exact_refits_passing == 35L &&
          nrow(correction_audit$correction_manifest) == 35L &&
          all(file.exists(correction_audit$correction_manifest$correction_path)) &&
          all(nchar(correction_audit$correction_manifest$sha256) == 64L),
        identical(final_loo_audit$family, "supplement_strategy_within") &&
          nrow(final_loo_audit$model_summary) == 72L &&
          isTRUE(final_loo_audit$stacking_ready) &&
          all(final_loo_audit$outcome_summary$unresolved_high_k_cases == 0L),
        nrow(weight_sums) == 4L && all(weight_sums$models == 18L) &&
          all(abs(weight_sums$weight_sum - 1) < 1e-8),
        nrow(prediction_sums) == 4L &&
          sum(prediction_sums$selected_models) == 22L &&
          all(prediction_sums$draws == 4000L) &&
          all(prediction_sums$retained_weight > 0) &&
          all(file.exists(prediction_manifest$prediction_path)) &&
          all(prediction_manifest$bytes > 0) &&
          all(nchar(prediction_manifest$sha256) == 64L),
        identical(reporting_audit$family, "supplement_strategy_within") &&
          isTRUE(reporting_audit$all_reporting_checks_pass) &&
          nrow(reporting_audit$summary) == 4L &&
          all(reporting_audit$summary$intervals_valid) &&
          all(reporting_audit$summary$reference_increment_valid) &&
          all(reporting_audit$summary$probabilities_valid) &&
          all(reporting_audit$summary$diagonal_contrasts_valid) &&
          nrow(reporting_model_weights) == 72L &&
          all(reporting_weight_sums$models == 18L) &&
          all(abs(reporting_weight_sums$weight_sum - 1) < 1e-8)
      )
    )
    failed <- is.na(checks$passed) | !checks$passed
    if (any(failed)) {
      stop(
        "Supplement strategy-within verification failed: ",
        paste(checks$check[failed], collapse = "; "),
        call. = FALSE
      )
    }
    artifacts <- list(
      verification_checks = checks,
      source_manifest = source_manifest,
      preparation_checks = preparation_audit$checks,
      preparation_outcome_counts = preparation_audit$outcome_counts,
      absolute_exposure_checks = absolute_audit$checks,
      absolute_outcome_coverage = absolute_audit$outcome_coverage,
      strategy_review_rows = strategy_audit_review$review_rows,
      strategy_review_status = strategy_audit_review$status_summary,
      strategy_structural_checks = strategy_audit_review$structural_checks,
      supplement_strategy_audit = strategy_audit,
      input_preflight = input_preflight,
      analysis_data = analysis_data,
      model_specifications = specification_table,
      model_name_alignment = name_alignment,
      accepted_fit_manifest = accepted_fit_manifest,
      sampling_diagnostic_summary = diagnostic_audit$diagnostic_summary,
      sampling_parameter_failures = diagnostic_audit$parameter_failures,
      initial_loo_model_summary = integrated_loo_audit$model_summary,
      initial_loo_outcome_summary = integrated_loo_audit$outcome_summary,
      initial_high_pareto_k_cases = integrated_loo_audit$high_k_cases,
      final_exact_refit_diagnostic_summary =
        final_exact_audit$diagnostic_summary,
      accepted_exact_fit_manifest =
        final_exact_audit$accepted_exact_fit_manifest,
      exact_correction_manifest = correction_audit$correction_manifest,
      final_loo_manifest = final_loo_audit$final_loo_manifest,
      final_loo_model_summary = final_loo_audit$model_summary,
      final_loo_outcome_summary = final_loo_audit$outcome_summary,
      final_exact_refit_summary = final_loo_audit$exact_refit_summary,
      stacking_weights = stacking_weights,
      prediction_allocation_manifest = prediction_manifest,
      reporting_file_manifest = reporting_audit$summary,
      reporting_model_weights = reporting_model_weights,
      dose_response_predictions = bind_report("dose_response"),
      dose_response_increments = bind_report("dose_response_increments"),
      exposure_support_by_group = bind_report("exposure_support_by_group"),
      common_exposure_support = bind_report("common_exposure_support"),
      addition_minus_substitution = bind_report("addition_minus_substitution"),
      pairwise_contrasts = bind_report("pairwise_contrasts"),
      pairwise_support = bind_report("pairwise_support"),
      local_equivalence = bind_report("local_equivalence")
    )
    descriptions <- stats::setNames(
      paste(
        "Frozen supplement strategy-within artifact:",
        names(artifacts)
      ),
      names(artifacts)
    )
    list(checks = checks, artifacts = artifacts, descriptions = descriptions)
  }

make_update_2026_supplement_strategy_within_pruning_plan <- function(
    accepted_fit_manifest,
    final_exact_audit,
    prediction_manifest,
    verification_files,
    archive_root = here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "strategy_within"
    ),
    verification_manifest = file.path(
      here::here(
        "results", "verification",
        "supplement_strategy_within_update_2026"
      ),
      "manifest.csv"
    )
) {
  if (any(!file.exists(verification_files))) {
    stop("The verification bundle is incomplete.", call. = FALSE)
  }
  verify_update_2026_manifest_files(verification_manifest)
  resolved_root <- normalizePath(archive_root, winslash = "/", mustWork = TRUE)
  expected_root <- normalizePath(
    here::here(
      "model_archive", "update_2026", "absolute_exposure",
      "supplement_g_day", "strategy_within"
    ),
    winslash = "/",
    mustWork = TRUE
  )

  if (!identical(tolower(resolved_root), tolower(expected_root))) {
    stop("Refusing to plan pruning outside the intended archive.",
         call. = FALSE)
  }
  model_directories <- file.path(
    archive_root,
    c("initial", "remedy_1", "remedy_2", "structural_uncorrelated")
  )
  model_paths <- unlist(purrr::map(
    model_directories,
    ~ list.files(.x, pattern = "\\.qs$", recursive = TRUE, full.names = TRUE)
  ), use.names = FALSE) |>
    normalizePath(winslash = "/", mustWork = TRUE)
  exact_directories <- file.path(
    archive_root,
    "loo",
    c("exact_fit", "exact_remedy")
  )
  exact_paths <- unlist(purrr::map(
    exact_directories,
    ~ list.files(.x, pattern = "\\.qs$", recursive = TRUE, full.names = TRUE)
  ), use.names = FALSE) |>
    normalizePath(winslash = "/", mustWork = TRUE)
  accepted_model_paths <- normalizePath(
    accepted_fit_manifest$fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  accepted_exact_paths <- normalizePath(
    final_exact_audit$accepted_exact_fit_manifest$exact_fit_path,
    winslash = "/",
    mustWork = TRUE
  )
  model_manifest <- tibble::tibble(
    path = model_paths,
    relative_path = substring(model_paths, nchar(resolved_root) + 2L),
    fit_class = "model_fit",
    accepted_fit = model_paths %in% accepted_model_paths,
    bytes = as.numeric(file.info(model_paths)$size)
  )
  exact_manifest <- tibble::tibble(
    path = exact_paths,
    relative_path = substring(exact_paths, nchar(resolved_root) + 2L),
    fit_class = "exact_refit",
    accepted_fit = exact_paths %in% accepted_exact_paths,
    bytes = as.numeric(file.info(exact_paths)$size)
  )

  if (
    nrow(model_manifest) != 76L ||
      sum(model_manifest$accepted_fit) != 72L ||
      sum(!model_manifest$accepted_fit) != 4L ||
      nrow(exact_manifest) != 36L ||
      sum(exact_manifest$accepted_fit) != 35L ||
      sum(!exact_manifest$accepted_fit) != 1L ||
      any(c(model_manifest$bytes, exact_manifest$bytes) <= 0)
  ) {
    stop("The fit archive inventory is invalid.", call. = FALSE)
  }

  deletion_manifest <- dplyr::bind_rows(model_manifest, exact_manifest) |>
    dplyr::mutate(
      artifact_role = dplyr::case_when(
        fit_class == "exact_refit" & accepted_fit ~ "accepted_exact_refit",
        fit_class == "exact_refit" ~ "superseded_exact_refit",
        accepted_fit ~ "accepted_model_fit",
        TRUE ~ "superseded_model_fit"
      ),
      lean_action = "delete refittable fit archive"
    )

  compact_roots <- c(
    loo_psis = file.path(archive_root, "loo", "integrated"),
    exact_corrections = file.path(archive_root, "loo", "exact_correction"),
    reporting = file.path(archive_root, "reporting")
  )
  compact_paths <- unlist(purrr::map(
    compact_roots,
    ~ list.files(.x, recursive = TRUE, full.names = TRUE, all.files = TRUE)
  ), use.names = FALSE)
  compact_paths <- compact_paths[
    file.exists(compact_paths) & !file.info(compact_paths)$isdir
  ] |>
    normalizePath(winslash = "/", mustWork = TRUE)
  roots <- stats::setNames(
    normalizePath(unname(compact_roots), winslash = "/", mustWork = TRUE),
    names(compact_roots)
  )
  component <- vapply(compact_paths, function(path) {
    matches <- names(roots)[vapply(
      roots,
      function(root) startsWith(tolower(path), paste0(tolower(root), "/")),
      logical(1L)
    )]
    if (length(matches) == 1L) matches else "unknown"
  }, character(1L))

  compact_manifest <- tibble::tibble(
    path = compact_paths,
    relative_path = substring(compact_paths, nchar(resolved_root) + 2L),
    archive_component = unname(component),
    bytes = as.numeric(file.info(compact_paths)$size),
    sha256 = purrr::map_chr(
      compact_paths,
      ~ digest::digest(file = .x, algo = "sha256", serialize = FALSE)
    ),
    action = "retain compact supplement strategy-within result"
  )

  compact_counts <- table(factor(
    compact_manifest$archive_component,
    levels = c("loo_psis", "exact_corrections", "reporting")
  ))
  if (
    !identical(
      as.integer(compact_counts),
      c(72L, 35L, nrow(prediction_manifest) + 8L)
    ) ||
      any(compact_manifest$archive_component == "unknown") ||
      any(compact_manifest$bytes <= 0) ||
      any(nchar(compact_manifest$sha256) != 64L)
  ) {
    stop("The compact archive inventory is incomplete.", call. = FALSE)
  }

  summary <- tibble::tibble(
    mode = "lean",
    model_fit_archives_deleted = nrow(model_manifest),
    accepted_model_fit_archives_deleted = sum(model_manifest$accepted_fit),
    superseded_model_fit_archives_deleted = sum(!model_manifest$accepted_fit),
    exact_refit_archives_deleted = nrow(exact_manifest),
    accepted_exact_refit_archives_deleted = sum(exact_manifest$accepted_fit),
    superseded_exact_refit_archives_deleted = sum(!exact_manifest$accepted_fit),
    archive_files_deleted = nrow(deletion_manifest),
    fit_archive_files_retained = 0L,
    gib_reclaimed = sum(deletion_manifest$bytes) / 1024^3,
    compact_archive_files_retained = nrow(compact_manifest),
    compact_archive_gib_retained = sum(compact_manifest$bytes) / 1024^3,
    verification_files_retained = length(verification_files),
    restoration = paste(
      "Reported results, exact-corrected LOO, and all 72 weights remain",
      "frozen; restoring model or exact-refit objects requires refitting",
      "the supplement strategy-within family."
    )
  )

  list(
    summary = summary,
    model_fit_manifest = model_manifest,
    exact_refit_manifest = exact_manifest,
    deletion_file_manifest = deletion_manifest,
    compact_archive_manifest = compact_manifest,
    verification_manifest = verification_manifest,
    archive_root = resolved_root
  )
}

write_update_2026_supplement_strategy_within_pruning_plan <- function(
    plan,
    output_dir = here::here(
      "results", "update_2026", "absolute_exposure", "supplement_g_day",
      "strategy_within", "pruning"
    )
) {
  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
  paths <- c(
    summary = file.path(output_dir, "summary.csv"),
    model_fit_manifest = file.path(output_dir, "model_fit_manifest.csv"),
    exact_refit_manifest = file.path(output_dir, "exact_refit_manifest.csv"),
    deletion_file_manifest = file.path(output_dir, "deletion_file_manifest.csv"),
    compact_archive_manifest = file.path(output_dir, "compact_archive_manifest.csv")
  )
  readr::write_csv(plan$summary, paths[["summary"]], na = "")
  readr::write_csv(plan$model_fit_manifest, paths[["model_fit_manifest"]], na = "")
  readr::write_csv(plan$exact_refit_manifest, paths[["exact_refit_manifest"]], na = "")
  readr::write_csv(plan$deletion_file_manifest, paths[["deletion_file_manifest"]], na = "")
  readr::write_csv(plan$compact_archive_manifest, paths[["compact_archive_manifest"]], na = "")
  unname(paths)
}
